function New-TestRepoRoot {
    # Creates a disposable REPOSITORY-layout copy of the runtime with a chosen
    # bundled default. Commands whose behaviour is DEFINED by the shipped
    # bundled default (reset-layout) need a bundled default with content, and
    # the shipped starter deliberately has none. A repository-layout copy
    # honours DEVWS_CONFIG / DEVWS_STATE_ROOT, unlike an installed-layout copy
    # running from an elevated session (where the P2-E gate denies those
    # overrides and the real user state root would be used instead).
    param(
        [Parameter(Mandatory)][string]$Name,
        [switch]$RichBundledDefault
    )

    $root = Join-Path $TestRoot $Name
    New-Item -ItemType Directory -Path $root -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $RepoRoot "src") -Destination $root -Recurse
    New-Item -ItemType Directory -Path (Join-Path $root "config") -Force | Out-Null

    $bundledSource = if ($RichBundledDefault) { $WorkspaceFixturePath } else { $BundledConfigPath }
    Copy-Item -LiteralPath $bundledSource -Destination (Join-Path $root "config\workspace.default.json")

    return [pscustomobject]@{
        Root   = $root
        Script = Join-Path $root "src\ws.ps1"
    }
}

