function Initialize-TestPrivilegedFixture {
    # Stages the production administrator-protected surface (workers, libs,
    # helpers and the dual native runtime) into a fixture's privileged root so
    # health/installer tests exercise the real split layout.
    param(
        [Parameter(Mandatory)]
        $Fixture,
        [switch]$SkipNative
    )

    $privileged = $Fixture.Privileged

    if (-not (Test-Path -LiteralPath $privileged -PathType Container)) {
        New-Item -ItemType Directory -Path $privileged -Force | Out-Null
    }

    $null = Install-DevWSPrivilegedFiles -RepoRoot $RepoRoot -PrivilegedRoot $privileged

    if (-not $SkipNative) {
        $null = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $Fixture.Root -PrivilegedRoot $privileged
    }

    return $privileged
}

function Stop-TestFixtureProcess {
    # Exact-identity cleanup for disposable fixture processes. Idempotent by
    # design: tolerates a never-created, already-exited or disposed process
    # object, and never throws, so a cleanup path can never mask the original
    # test failure. Only the exact given process id is stopped.
    param($Process, [int]$TimeoutMilliseconds = 10000)

    if ($null -eq $Process) { return }

    try {
        if (-not $Process.HasExited) {
            Stop-Process -Id $Process.Id -Force -ErrorAction SilentlyContinue
            [void]$Process.WaitForExit($TimeoutMilliseconds)
        }
    }
    catch {
        # Best-effort cleanup: an unusable process object is already gone.
        $null = $_.Exception
    }
}

function Start-TestPipeServer {
    # Disposable same-user pipe server for negative pipe-target tests. It
    # records whether a connection produced any shutdown frame and stays alive
    # long enough for the test to prove it survived.
    param(
        [Parameter(Mandatory)][string]$PipeName,
        [Parameter(Mandatory)][string]$Prefix
    )

    $scriptPath = Join-Path $TestRoot ($Prefix + ".ps1")
    $readyPath  = Join-Path $TestRoot ($Prefix + ".ready")
    $resultPath = Join-Path $TestRoot ($Prefix + ".result")

    Set-Content -LiteralPath $scriptPath -Value @'
param([string]$PipeName, [string]$ReadyPath, [string]$ResultPath)
$ErrorActionPreference = 'Stop'
$server = [System.IO.Pipes.NamedPipeServerStream]::new(
    $PipeName,
    [System.IO.Pipes.PipeDirection]::InOut,
    1,
    [System.IO.Pipes.PipeTransmissionMode]::Byte,
    [System.IO.Pipes.PipeOptions]::CurrentUserOnly)
try {
    Set-Content -LiteralPath $ReadyPath -Value 'ready' -NoNewline
    $server.WaitForConnection()
    $reader = [System.IO.StreamReader]::new($server, [System.Text.UTF8Encoding]::new($false), $false, 4096, $true)
    $line = $reader.ReadLine()
    Set-Content -LiteralPath $ResultPath -Value ([string]$line) -NoNewline
    Start-Sleep -Seconds 30
}
finally {
    $server.Dispose()
}
'@ -NoNewline

    $process = Start-Process -FilePath "pwsh" -ArgumentList @(
        '-NoProfile', '-File', $scriptPath, $PipeName, $readyPath, $resultPath
    ) -PassThru -WindowStyle Hidden

    $deadline = (Get-Date).AddSeconds(20)

    while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $readyPath)) {
        Start-Sleep -Milliseconds 100
    }

    if (-not (Test-Path -LiteralPath $readyPath)) {
        Stop-TestFixtureProcess $process
        Remove-Item -LiteralPath $scriptPath, $readyPath, $resultPath -Force -ErrorAction SilentlyContinue
        throw "the test pipe server did not become ready"
    }

    return [pscustomobject]@{
        Process = $process
        Script  = $scriptPath
        Ready   = $readyPath
        Result  = $resultPath
    }
}

function Stop-TestPipeServer {
    param($Server)

    if ($null -eq $Server) { return }

    Stop-TestFixtureProcess $Server.Process
    Remove-Item -LiteralPath $Server.Script, $Server.Ready, $Server.Result -Force -ErrorAction SilentlyContinue
}

function Wait-TestFixtureProcessesGone {
    # Test-only bound for disposable fixture cleanup.
    #
    # A termination REQUEST (Stop-Process / Kill) is not proof that
    # Win32_Process has already stopped reporting the process: the process table
    # is eventually consistent, and a single immediate snapshot is a race on a
    # loaded host. Poll the EXACT fixture predicate until it is observably empty
    # or the deadline expires.
    #
    # This returns the observation; the caller still asserts Gone, so a genuine
    # leak fails instead of being hidden, and no test is retried.
    param(
        [Parameter(Mandatory)][scriptblock]$Select,
        [int]$TimeoutSeconds = 10,
        [int]$PollMilliseconds = 150
    )

    $deadline = [datetime]::UtcNow.AddSeconds($TimeoutSeconds)

    while ($true) {
        $remaining = @(& $Select)

        if ($remaining.Count -eq 0) {
            return [pscustomobject]@{ Gone = $true; Remaining = @() }
        }

        if ([datetime]::UtcNow -ge $deadline) {
            return [pscustomobject]@{ Gone = $false; Remaining = @($remaining) }
        }

        Start-Sleep -Milliseconds $PollMilliseconds
    }
}

function Get-FileBase64 {
    param([Parameter(Mandatory)][string]$Path)

    return [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($Path))
}

function Invoke-InstalledNativeProbe {
    # Runs the installed shared native loader in a genuinely fresh pwsh process
    # with Add-Type shadowed by a throwing function, so a successful
    # initialization proves installed execution byte-loads the generated DLL,
    # exposes every native type, and never invokes Roslyn. The probe reports
    # either INSTALLED-NATIVE-OK or the actionable failure message.
    param(
        [Parameter(Mandatory)][string]$NativeLibPath,
        [Parameter(Mandatory)][string]$Label
    )

    $probePath = Join-Path $TestRoot ("native-installed-probe-" + $Label + ".ps1")

    $probeSource = @'
param([Parameter(Mandatory)][string]$NativeLibPath)

$ErrorActionPreference = "Stop"

function Add-Type {
    throw "installed runtime invoked Add-Type: $args"
}

. $NativeLibPath

try {
    Initialize-DevWSNativeRuntime

    foreach ($typeName in @(Get-DevWSNativeRequiredTypeNames)) {
        if ($null -eq ([System.Management.Automation.PSTypeName]$typeName).Type) {
            throw "native type missing after initialization: $typeName"
        }
    }

    if ([DevWSWindowOpsNative]::IsWindow([IntPtr]::Zero)) { throw "unexpected live window" }
    if ([DevWSAppWindowNative]::IsWindow([IntPtr]::Zero)) { throw "unexpected live app window" }
    if ([DevWSAppOwnershipNative]::IsWindow([IntPtr]::Zero)) { throw "unexpected live ownership window" }

    $candidates = @([DevWSAppWindowCandidateCollector]::CollectAppWindowCandidates($true))
    if ($candidates.Count -lt 1) { throw "candidate collector returned nothing" }
    $null = $candidates[0].hwnd
    $null = $candidates[0].pathUnavailable

    Initialize-DevWSNativeRuntime
    Initialize-DevWSNativeRuntime

    Write-Output "INSTALLED-NATIVE-OK"
}
catch {
    Write-Output "INSTALLED-NATIVE-ERROR: $($_.Exception.Message)"
}
'@

    Set-Content -LiteralPath $probePath -Value $probeSource -NoNewline

    $output = & pwsh -NoLogo -NoProfile -File $probePath -NativeLibPath $NativeLibPath 2>&1 | Out-String

    return [pscustomobject]@{ ExitCode = $LASTEXITCODE; Output = $output }
}

function Invoke-TestNativeCompile {
    # Compiles one or more C# source files to an assembly in a fresh pwsh
    # process. The suite process already has the DevWS native types loaded
    # (repository mode), and Add-Type refuses to emit another assembly whose
    # type name is already loaded in the session.
    param(
        [Parameter(Mandatory)][string[]]$SourcePath,
        [Parameter(Mandatory)][string]$OutputPath,
        [Parameter(Mandatory)][string]$Label
    )

    $scriptPath = Join-Path $TestRoot ("native-compile-" + $Label + ".ps1")

    $scriptSource = @'
param(
    [Parameter(Mandatory)][string]$SourceList,
    [Parameter(Mandatory)][string]$OutputPath
)

$ErrorActionPreference = "Stop"

$sourceFiles = @($SourceList -split ";" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })

Add-Type -Path $sourceFiles -OutputAssembly $OutputPath -OutputType Library -ErrorAction Stop
'@

    Set-Content -LiteralPath $scriptPath -Value $scriptSource -NoNewline

    $sourceList = (@($SourcePath) -join ";")

    $output = & pwsh -NoLogo -NoProfile -File $scriptPath -SourceList $sourceList -OutputPath $OutputPath 2>&1 | Out-String

    if ($LASTEXITCODE -ne 0) {
        throw "Test native compile '$Label' failed: $output"
    }

    return $OutputPath
}

function Invoke-FreshCliDependencyProbe {
    # Loads ONLY the CLI entry point in a genuinely fresh pwsh process and
    # verifies that the exact-HWND/AHK operation layer is reachable. This is
    # the regression for the live Phase 8 deployment failure where ws.ps1
    # called Move-/Focus-DevWSWindowHwnd without dot-sourcing the library that
    # defines them (the in-process suite masked it by preloading every lib).
    param(
        [Parameter(Mandatory)][string]$WsPath,
        [string[]]$Functions = @(
            "Move-DevWSWindowHwnd",
            "Focus-DevWSWindowHwnd",
            "Get-DevWSWindowHwndRect",
            "Invoke-DevWSWindowHelper",
            "Invoke-DevWSResetWindowHelper",
            "Find-DevWSVisibleWindowHwndByExactTitle"
        )
    )

    $probePath = Join-Path $TestRoot "fresh-cli-probe.ps1"

    $probeSource = @'
param(
    [Parameter(Mandatory)][string]$WsPath,
    [Parameter(Mandatory)][string]$FunctionList
)

. $WsPath help *> $null

$exitCode = 0

foreach ($name in $FunctionList.Split(',')) {
    $name = $name.Trim()

    if ([string]::IsNullOrWhiteSpace($name)) { continue }

    if (Get-Command $name -ErrorAction SilentlyContinue) {
        Write-Output "OK $name"
    }
    else {
        Write-Output "MISSING $name"
        $exitCode = 1
    }
}

exit $exitCode
'@

    Set-Content -LiteralPath $probePath -Value $probeSource -NoNewline

    $output = & pwsh -NoLogo -NoProfile -File $probePath -WsPath $WsPath -FunctionList ($Functions -join ",") 2>&1 | Out-String
    $code = $LASTEXITCODE

    return [pscustomobject]@{ ExitCode = $code; Output = $output }
}

function New-WorkerProbeFixture {
    # A strict v3 workspace with an intentionally EMPTY window set, so the real
    # workers can run end-to-end without touching any window. Optionally carries
    # one valid non-empty binding (the regression for the worker dependency bug).
    param(
        [Parameter(Mandatory)][string]$Name,
        [switch]$WithBinding
    )

    $root = Join-Path $TestRoot $Name
    New-Item -ItemType Directory -Path $root -Force | Out-Null
    $stateRoot = Join-Path $root "state"
    New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

    $bindingsJson = if ($WithBinding) { '[{"hotkey":"alt+shift+y","setId":"main"}]' } else { '[]' }
    $configPath = Join-Path $root "workspace.json"
    $json = '{"version":3,"defaultSet":"main","bindings":' + $bindingsJson + ',"sets":[{"id":"main","windows":[]}]}'
    Set-Content -LiteralPath $configPath -Value $json -Encoding UTF8

    return [pscustomobject]@{
        Root       = $root
        ConfigPath = $configPath
        StateRoot  = $stateRoot
    }
}

function Invoke-FreshWorkerRun {
    # Runs the REAL worker script in a genuinely fresh pwsh process with only
    # DEVWS_CONFIG / DEVWS_STATE_ROOT pointed at the fixture. The probe first
    # proves the child did not preload the bindings library, then executes the
    # worker; the caller side connects to the worker's one-shot pipe (Public
    # Security Phase 2-D transport), sends a REAL DevWS.Worker.v1 request frame
    # and records the ACCEPTED / FINAL / error outcome. Server authentication
    # is deliberately not applied here (the suite process is not guaranteed to
    # be High); identity acceptance is covered by the worker-pipe pure matrix
    # and the disposable Windows POC.
    param(
        [Parameter(Mandatory)][string]$WorkerPath,
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][string]$StateRoot,
        [Parameter(Mandatory)][string]$Kind,
        [Parameter(Mandatory)][string]$RequestId,
        [hashtable]$Payload = @{}
    )

    $payloadFrame = [ordered]@{}

    foreach ($key in $Payload.Keys) {
        $payloadFrame[$key] = $Payload[$key]
    }

    $probePath = Join-Path $StateRoot "$Kind-worker-probe.ps1"
    $probeSource = @'
param(
    [Parameter(Mandatory)][string]$WorkerPath,
    [Parameter(Mandatory)][string]$ConfigPath,
    [Parameter(Mandatory)][string]$StateRoot
)

$env:DEVWS_CONFIG = $ConfigPath
$env:DEVWS_STATE_ROOT = $StateRoot

$preloaded = [bool](Get-Command ConvertTo-DevWSBindingHotkey -ErrorAction SilentlyContinue)
Write-Output "PRELOADED=$preloaded"

try {
    & $WorkerPath
    Write-Output "WORKER_OUTCOME=returned"
}
catch {
    Write-Output "WORKER_OUTCOME=threw"
    Write-Output ("WORKER_MESSAGE=" + ($_.Exception.Message -replace "`r?`n", " | "))
}

exit $(if ($preloaded) { 2 } else { 0 })
'@
    Set-Content -LiteralPath $probePath -Value $probeSource -NoNewline

    $stdoutPath = Join-Path $StateRoot "$Kind-worker-stdout.txt"
    $stderrPath = Join-Path $StateRoot "$Kind-worker-stderr.txt"

    $process = Start-Process -FilePath (Join-Path $PSHOME 'pwsh.exe') `
        -ArgumentList @('-NoLogo', '-NoProfile', '-File', "`"$probePath`"", '-WorkerPath', "`"$WorkerPath`"", '-ConfigPath', "`"$ConfigPath`"", '-StateRoot', "`"$StateRoot`"") `
        -PassThru -WindowStyle Hidden -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath

    $result = $null
    $accepted = $false
    $clientError = $null
    $pipeName = Get-DevWSWorkerOperationPipeName -Kind $Kind

    try {
        $client = $null
        $connectDeadline = [datetime]::UtcNow.AddSeconds(60)

        while ([datetime]::UtcNow -lt $connectDeadline) {
            $candidate = [System.IO.Pipes.NamedPipeClientStream]::new('.', $pipeName, [System.IO.Pipes.PipeDirection]::InOut, [System.IO.Pipes.PipeOptions]::None)

            try { $candidate.Connect(250); $client = $candidate; break }
            catch { $candidate.Dispose(); Start-Sleep -Milliseconds 100 }
        }

        if ($null -ne $client) {
            try {
                Write-DevWSWorkerFrame -Stream $client -Object ([ordered]@{
                    version   = 1
                    operation = $Kind
                    requestId = $RequestId
                    payload   = $payloadFrame
                })

                $firstFrame = Read-DevWSWorkerFrame -Stream $client -TimeoutSeconds 60

                if ($firstFrame.Ok -and [string]$firstFrame.Value.type -eq 'accepted' -and [string]$firstFrame.Value.requestId -ceq $RequestId) {
                    $accepted = $true
                    $finalFrame = Read-DevWSWorkerFrame -Stream $client -TimeoutSeconds 60

                    if ($finalFrame.Ok) {
                        if ([string]$finalFrame.Value.type -eq 'final') {
                            $result = [ordered]@{
                                requestId = [string]$finalFrame.Value.requestId
                                ok        = [bool]$finalFrame.Value.ok
                                message   = [string]$finalFrame.Value.message
                            }

                            if ($null -ne $finalFrame.Value.PSObject.Properties['data'] -and $null -ne $finalFrame.Value.data) {
                                $result['data'] = $finalFrame.Value.data
                            }
                        }
                        elseif ([string]$finalFrame.Value.type -eq 'error') {
                            $result = [ordered]@{ requestId = [string]$finalFrame.Value.requestId; ok = $false; message = [string]$finalFrame.Value.error }
                        }
                    }
                    else { $clientError = [string]$finalFrame.Error }
                }
                elseif ($firstFrame.Ok -and [string]$firstFrame.Value.type -eq 'error') {
                    $result = [ordered]@{ requestId = [string]$firstFrame.Value.requestId; ok = $false; message = [string]$firstFrame.Value.error }
                }
                else { $clientError = [string]$firstFrame.Error }
            }
            catch { $clientError = $_.Exception.Message }
            finally { $client.Dispose() }
        }
        else { $clientError = 'worker pipe connection deadline' }

        $null = $process.WaitForExit(90000)
    }
    finally {
        if (-not $process.HasExited) { try { $process.Kill() } catch { } ; $null = $process.WaitForExit(5000) }
    }

    $code = $process.ExitCode
    $output = ""

    if (Test-Path -LiteralPath $stdoutPath -PathType Leaf) { $output += (Get-Content -LiteralPath $stdoutPath -Raw) }
    if (Test-Path -LiteralPath $stderrPath -PathType Leaf) { $output += (Get-Content -LiteralPath $stderrPath -Raw) }

    if ($null -eq $result -and $null -ne $clientError) {
        $result = [ordered]@{ requestId = $RequestId; ok = $false; message = "transport: $clientError" }
    }

    $outcome = "unknown"

    if ($output -match 'WORKER_OUTCOME=threw') { $outcome = "threw" }
    elseif ($output -match 'WORKER_OUTCOME=returned') { $outcome = "returned" }

    $message = ""

    if ($output -match 'WORKER_MESSAGE=(.*)') { $message = $Matches[1].Trim() }

    return [pscustomobject]@{
        ExitCode  = $code
        Preloaded = ($output -match 'PRELOADED=True')
        Outcome   = $outcome
        Message   = $message
        Result    = $result
        Accepted  = $accepted
    }
}

# Public Security Phase 2-D worker-pipe fixture helpers: a real transport-level
# worker child (REAL New-DevWSWorkerPipeServer / bounded request validation /
# ACCEPTED / FINAL) driven through the REAL Start/Complete client with test
# overrides for the scheduled-task kick, the Kind expectation (the child is not
# a deployed task) and - where transport semantics rather than identity
# acceptance are under test - the identity policy.
$script:WorkerPipeFixtureSource = @'
$ErrorActionPreference = 'Continue'

. (Join-Path '@@LIBDIR@@' 'devws-paths.ps1')
. (Join-Path '@@LIBDIR@@' 'devws-config.ps1')
. (Join-Path '@@LIBDIR@@' 'devws-native.ps1')
. (Join-Path '@@LIBDIR@@' 'devws-worker-protocol.ps1')

$vars = Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot 'fixture-vars.json') | ConvertFrom-Json
function LogF([string]$m) { Add-Content -LiteralPath $vars.LogPath -Value ("[{0:HH:mm:ss.fff}] {1}" -f (Get-Date), $m) -Encoding UTF8 }

LogF 'fixture-start'
$server = New-DevWSWorkerPipeServer -Kind $vars.Kind -PipeName $vars.PipeName
LogF 'server-created'

if (-not (Wait-DevWSWorkerPipeConnection -Server $server -TimeoutSeconds 20)) { LogF 'no-client'; exit 0 }
LogF 'client-connected'

if ($vars.Mode -eq 'die-before-accept') { LogF 'die-before-accept'; exit 0 }

$request = Read-DevWSWorkerPipeRequest -Server $server -Kind $vars.Kind -TimeoutSeconds 15

if (-not $request.Ok) {
    [void](Send-DevWSWorkerError -Server $server -Kind $vars.Kind -RequestId ([string]$request.RequestId) -Error ([string]$request.Error))
    LogF ('rejected:' + $request.Error)
    Wait-DevWSWorkerFrameDelivery -Server $server
    exit 0
}

LogF ('request-ok ' + $request.RequestId)
[void](Send-DevWSWorkerAccepted -Server $server -Kind $vars.Kind -RequestId ([string]$request.RequestId))
LogF 'accepted-sent'

if ($vars.Mode -eq 'die-after-accept') { LogF 'die-after-accept'; exit 0 }

if ($vars.Mode -eq 'wait-release') {
    LogF 'waiting-for-release'
    $deadline = (Get-Date).AddSeconds(30)
    while (-not (Test-Path -LiteralPath $vars.ReleasePath) -and (Get-Date) -lt $deadline) { Start-Sleep -Milliseconds 100 }
    if (-not (Test-Path -LiteralPath $vars.ReleasePath)) { LogF 'release-timeout'; exit 5 }
    LogF 'released'
}

Add-Content -LiteralPath $vars.SideEffectPath -Value 'run' -Encoding UTF8
LogF 'side-effect'

if ($vars.Mode -eq 'final-lost') { LogF 'final-lost'; exit 0 }

if ($vars.Mode -eq 'fail') {
    [void](Send-DevWSWorkerFinal -Server $server -Kind $vars.Kind -RequestId ([string]$request.RequestId) -Ok $false -Message 'boom')
    LogF 'failed-final'
    Wait-DevWSWorkerFrameDelivery -Server $server
    exit 0
}

$data = $null
if ($vars.Mode -eq 'capture-data') { $data = @{ publication = [guid]::NewGuid().ToString() } }
[void](Send-DevWSWorkerFinal -Server $server -Kind $vars.Kind -RequestId ([string]$request.RequestId) -Ok $true -Message 'OK' -Data $data)
LogF 'final-sent'
Wait-DevWSWorkerFrameDelivery -Server $server
exit 0
'@

function New-WorkerPipeFixtureCase {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][ValidateSet("launch", "capture", "focus", "reset")][string]$Kind,
        [Parameter(Mandatory)][string]$Mode
    )

    $root = Join-Path $TestRoot $Name
    New-Item -ItemType Directory -Path $root -Force | Out-Null
    $script = Join-Path $root 'worker-pipe-fixture.ps1'
    $source = $script:WorkerPipeFixtureSource.Replace('@@LIBDIR@@', (Join-Path $RepoRoot 'src\lib'))
    Set-Content -LiteralPath $script -Value $source -NoNewline

    $case = [pscustomobject]@{
        Root       = $root
        Script     = $script
        Vars       = (Join-Path $root 'fixture-vars.json')
        Log        = (Join-Path $root 'fixture.log')
        SideEffect = (Join-Path $root 'side-effect.txt')
        Release    = (Join-Path $root 'release.txt')
        Kind       = $Kind
        Mode       = $Mode
        PipeName   = ("DevWS.WorkerFixture.$Name." + [guid]::NewGuid().ToString('N').Substring(0, 8))
        Process    = $null
    }

    [ordered]@{
        Kind           = $Kind
        Mode           = $Mode
        PipeName       = $case.PipeName
        LogPath        = $case.Log
        SideEffectPath = $case.SideEffect
        ReleasePath    = $case.Release
    } | ConvertTo-Json | Set-Content -LiteralPath $case.Vars -Encoding UTF8

    return $case
}

function Start-WorkerPipeFixtureProcess {
    param([Parameter(Mandatory)]$Case)

    # Serialization + endpoint hygiene: other cases' leftovers are gone, and
    # the case endpoint refuses connections before a new owner claims it.
    Wait-WorkerPipeFixturesGone -ExceptScript $Case.Script
    $Case.Process = Start-Process -FilePath (Join-Path $PSHOME 'pwsh.exe') -ArgumentList @('-NoProfile', '-WindowStyle', 'Hidden', '-File', "`"$($Case.Script)`"") -PassThru -WindowStyle Hidden
    return $Case.Process
}

function Wait-WorkerPipeFixturesGone {
    # All worker-pipe fixture children share the operation-scoped pipe
    # namespace, so only one CASE may own the pipe at a time. Leftovers from
    # earlier cases (identified by their distinct fixture script path) are
    # terminated and waited out before a new case spawns; children of the
    # CURRENT case are never touched.
    param(
        [string]$ExceptScript = ''
    )

    $deadline = [datetime]::UtcNow.AddSeconds(20)

    while ([datetime]::UtcNow -lt $deadline) {
        $alive = @(Get-CimInstance Win32_Process -Filter "Name = 'pwsh.exe'" | Where-Object {
            $_.ProcessId -ne $PID -and
            $_.CommandLine -like '*worker-pipe-fixture.ps1*' -and
            ($null -eq $ExceptScript -or $ExceptScript -eq '' -or $_.CommandLine -notlike "*$ExceptScript*")
        })

        if ($alive.Count -eq 0) { return }

        foreach ($stray in $alive) {
            Stop-Process -Id $stray.ProcessId -Force -ErrorAction SilentlyContinue
        }

        Start-Sleep -Milliseconds 200
    }
}

function Connect-WorkerPipeFixtureClient {
    # Test-only raw client against the CASE-scoped fixture endpoint. A connect
    # can still land on a closing endpoint from the SAME case's previous
    # fixture process (the case pipe name is stable across a case), so each
    # candidate is verified by PID against the current fixture process.
    param(
        [Parameter(Mandatory)]$Case,
        [int]$TimeoutSeconds = 30
    )

    $deadline = [datetime]::UtcNow.AddSeconds($TimeoutSeconds)

    while ([datetime]::UtcNow -lt $deadline) {
        $candidate = [System.IO.Pipes.NamedPipeClientStream]::new('.', $Case.PipeName, [System.IO.Pipes.PipeDirection]::InOut, [System.IO.Pipes.PipeOptions]::None)

        try {
            $candidate.Connect(250)

            $verifyProbe = $null

            try { $verifyProbe = Get-DevWSWorkerPipeServerProcessId -Connection $candidate } catch { $verifyProbe = $null }

            if ($null -ne $verifyProbe -and $verifyProbe -eq $Case.Process.Id) { return $candidate }

            $candidate.Dispose()
        }
        catch { $candidate.Dispose() }

        Start-Sleep -Milliseconds 100
    }

    return $null
}

function Stop-WorkerPipeFixtureProcess {
    param([Parameter(Mandatory)]$Case)
    if ($null -ne $Case.Process -and -not $Case.Process.HasExited) {
        try { $Case.Process.Kill() } catch { }
        try { $null = $Case.Process.WaitForExit(5000) } catch { }
    }

    # Sweep any other fixture child of this case (e.g. the second concurrent
    # caller's spawn) so no disposable process is left behind. The sweep must be
    # synchronized here, at the owner: a later case's single process-table
    # snapshot cannot distinguish a just-killed stray from a genuinely stranded
    # worker. Only this case's uniquely script-marked children are matched.
    $strays = @(Get-CimInstance Win32_Process -Filter "Name = 'pwsh.exe'" | Where-Object { $_.CommandLine -like "*$($Case.Script)*" })

    foreach ($stray in $strays) {
        Stop-Process -Id $stray.ProcessId -Force -ErrorAction SilentlyContinue
    }

    if ($strays.Count -gt 0) {
        $null = Wait-TestFixtureProcessesGone -Select {
            Get-CimInstance Win32_Process -Filter "Name = 'pwsh.exe'" | Where-Object { $_.CommandLine -like "*$($Case.Script)*" }
        }
    }
}

function New-WorkerPipeFixtureExpectation {
    # Returns a scriptblock that the CALLING Test-Case body dot-sources, so the
    # override functions are defined in that body's scope and disappear with
    # it. Values are embedded as literals: functions defined dynamically
    # resolve variables at call time, so captured variables would not survive.
    param(
        [Parameter(Mandatory)]$Case,
        [switch]$RefuseIdentity,
        [Parameter(Mandatory)][ValidateSet("launch", "capture", "focus", "reset")][string]$Kind
    )

    $refuseLiteral = if ($RefuseIdentity) { '$true' } else { '$false' }
    $scriptLiteral = $Case.Script.Replace("'", "''")
    $kindLiteral = $Kind
    $pipeLiteral = $Case.PipeName.Replace("'", "''")

    $source = @'
$script:workerPipeCase = [pscustomobject]@{ Script = '__SCRIPT__'; Kind = '__KIND__'; PipeName = '__PIPE__'; Process = $null }

function Get-DevWSWorkerOperationPipeName {
    # Case-scoped test endpoint: fixtures must never contend with each other
    # (or with anything else) on the production operation pipe name.
    param([Parameter(Mandatory)][ValidateSet("launch", "capture", "focus", "reset")][string]$Kind)
    return $script:workerPipeCase.PipeName
}

function Get-DevWSWorkerKindExpectation {
    param([string]$Kind)
    return [pscustomobject]@{
        TaskName = "Test-WorkerPipe-$Kind"
        Kind     = $Kind
        Exec     = (Join-Path $PSHOME 'pwsh.exe')
        Argv     = @('-NoProfile', '-WindowStyle', 'Hidden', '-File', '__SCRIPT__')
        Script   = '__SCRIPT__'
    }
}

function Start-DevWSScheduledTask {
    param([string]$TaskName)
    $null = Start-WorkerPipeFixtureProcess -Case $script:workerPipeCase
}

function Test-DevWSWorkerServerIdentityRecord {
    param($Record, [string]$ExpectedExec, [string[]]$ExpectedArgv, [string]$ExpectedUserSid, [int]$ExpectedSessionId)

    if (__REFUSE__) {
        return [pscustomobject]@{ Ok = $false; Reason = 'test-forced-refusal' }
    }

    return [pscustomobject]@{ Ok = $true; Reason = $null }
}
'@

    $source = $source.Replace('__SCRIPT__', $scriptLiteral).Replace('__REFUSE__', $refuseLiteral).Replace('__KIND__', $kindLiteral).Replace('__PIPE__', $pipeLiteral)
    return [scriptblock]::Create($source)
}

function Wait-WorkerPipeFixtureLog {
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Pattern,
        [int]$TimeoutSeconds = 30
    )

    $deadline = [datetime]::UtcNow.AddSeconds($TimeoutSeconds)

    while ([datetime]::UtcNow -lt $deadline) {
        if (Test-Path -LiteralPath $Path -PathType Leaf) {
            $content = Get-Content -LiteralPath $Path -Raw
            if ($content -match [regex]::Escape($Pattern)) { return $true }
        }
        Start-Sleep -Milliseconds 100
    }

    return $false
}

function Get-WorkerPipeFixtureSideEffectCount {
    param([Parameter(Mandatory)]$Case)
    if (-not (Test-Path -LiteralPath $Case.SideEffect -PathType Leaf)) { return 0 }
    return @(Get-Content -LiteralPath $Case.SideEffect | Where-Object { $_ -match 'run' }).Count
}

