function Write-BWCall {
    param([string]$Event, [string]$Id = '', [string]$Detail = '')
    $line = [ordered]@{ e = $Event; id = $Id; d = $Detail } | ConvertTo-Json -Compress
    Add-Content -LiteralPath (Get-BWLogPath) -Value $line
}
function Get-BWConfig { return (Get-Content -Raw -LiteralPath (Get-BWConfigPath) | ConvertFrom-Json) }
function Get-BWTerminals {
    $cfg = Get-BWConfig
    $set = @($cfg.sets | Where-Object { [string]$_.id -ieq [string]$cfg.defaultSet })[0]
    return @($set.windows | Where-Object { $_.type -eq 'terminal' })
}
function Get-BWTerminalIndex {
    param([string]$WindowId)
    $terms = @(Get-BWTerminals)
    for ($i = 0; $i -lt $terms.Count; $i++) {
        if ([string]$terms[$i].windowId -eq $WindowId) { return $i }
    }
    return -1
}
function Get-BWTerminalIdForHwnd {
    param([long]$Hwnd)
    $terms = @(Get-BWTerminals)
    for ($i = 0; $i -lt $terms.Count; $i++) {
        if ((900000 + $i * 10) -eq $Hwnd) { return [string]$terms[$i].id }
    }
    return ''
}
