# Stage 2 test stub library: the REAL canonical terminal launch policy plus a
# scripted WT world and a recording kick override. Window HWND space:
#   700000 + index*10 -> present/state HWND
#   800000 + index*10 -> present/snapshot HWND
#   900000 + index*10 -> created HWND after a successful kick
. (Join-Path '@@REPOLIB@@' 'devws-terminal-launch.ps1')

function Get-BWHwndIndex([long]$Hwnd) {
    foreach ($base in @(900000, 800000, 700000)) {
        if ($Hwnd -ge $base) { return [int](($Hwnd - $base) / 10) }
    }
    return -1
}
function Get-BWKickedIds {
    $path = '@@KICKED@@'
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return @() }
    return @(Get-Content -LiteralPath $path | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
}
function Get-DevWSTerminalTopLevelHwnds {
    $terms = @(Get-BWTerminals)
    $present = @(Get-BWControlValue 'present')
    $sources = Get-BWControlValue 'presentSource'
    $kicked  = @(Get-BWKickedIds)
    $hits = New-Object System.Collections.Generic.List[long]
    for ($i = 0; $i -lt $terms.Count; $i++) {
        $id = [string]$terms[$i].id
        if ($present -contains $id) {
            $src = 'state'
            if ($null -ne $sources) { $p = $sources.PSObject.Properties[$id]; if ($null -ne $p) { $src = [string]$p.Value } }
            if ($src -eq 'uia') { $hits.Add([long](800000 + $i * 10)) | Out-Null } else { $hits.Add([long](700000 + $i * 10)) | Out-Null }
        }
        elseif (($kicked -contains $id) -and -not (Test-BWControlList (Get-BWControl) 'hwndFail' $id)) {
            $hits.Add([long](900000 + $i * 10)) | Out-Null
        }
    }
    return $hits.ToArray()
}
function Read-DevWSTerminalHwndTabs {
    param([long]$Hwnd, [int]$EmptyRetryCount = 2, [int]$EmptyRetryDelayMilliseconds = 250)
    $idx = Get-BWHwndIndex $Hwnd
    $terms = @(Get-BWTerminals)
    $wid = ''
    $configured = 1
    $id = ''
    if ($idx -ge 0 -and $idx -lt $terms.Count) {
        $wid = [string]$terms[$idx].windowId
        $configured = @($terms[$idx].tabs).Count
        $id = [string]$terms[$idx].id
    }
    $count = $configured
    $overrides = Get-BWControlValue 'tabCounts'
    if ($Hwnd -ge 900000 -and $null -ne $overrides -and -not [string]::IsNullOrWhiteSpace($id)) {
        $hit = $overrides.PSObject.Properties[$id]
        if ($null -ne $hit) { $count = [int]$hit.Value }
    }
    Write-BWCall 'read' '' ("hwnd=$Hwnd count=$count")
    $names = @()
    for ($n = 0; $n -lt $count; $n++) { $names += $wid }
    $set = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $names) { if (-not [string]::IsNullOrWhiteSpace($name)) { [void]$set.Add($name) } }
    return [pscustomobject]@{ Ok = $true; TabNames = $set; RawCount = $count; EmptyRetries = 0 }
}
function Start-DevWSTerminalLaunchPlan {
    param($Plan, [string]$WtPath, [scriptblock]$ProcessStarter)
    $kicks = New-Object System.Collections.Generic.List[object]
    $failures = New-Object System.Collections.Generic.List[object]
    foreach ($record in @($Plan.Terminals)) {
        if ($record.State -ne 'missing') { continue }
        $startedAt = [DateTimeOffset]::UtcNow
        try {
            if (Test-BWControlList (Get-BWControl) 'kickFail' ([string]$record.TerminalId)) { throw "wt-boom ($($record.TerminalId))" }
            Write-BWCall 'kick' ([string]$record.TerminalId) ((@($record.CreateArguments)) -join ' ')
            Add-Content -LiteralPath '@@KICKED@@' -Value ([string]$record.TerminalId)
        }
        catch {
            $failures.Add([pscustomobject]@{ Order = [int]$record.Order; TerminalId = [string]$record.TerminalId; Ref = "$($Plan.SetId)/$($record.TerminalId)"; Message = $_.Exception.Message }) | Out-Null
            continue
        }
        $kicks.Add([pscustomobject]@{ Order = [int]$record.Order; TerminalId = [string]$record.TerminalId; WindowId = [string]$record.WindowId; CreateArguments = $record.CreateArguments; StartedAtUtc = $startedAt; DeadlineUtc = $startedAt.AddSeconds(15) }) | Out-Null
    }
    return [pscustomobject]@{ Kicks = $kicks.ToArray(); Failures = $failures.ToArray() }
}
'@

