function Invoke-BatchedWorkerRun {
    param([Parameter(Mandatory)]$Fixture)

    Remove-Item -LiteralPath $Fixture.ResultPath -Force -ErrorAction SilentlyContinue
    $output = & pwsh -NoLogo -NoProfile -File $Fixture.WorkerPath 2>&1 | Out-String
    $code = $LASTEXITCODE

    if ($code -ne 0) {
        Write-Host ("         [worker output] " + ($output -replace "`r?`n", " | ").Substring(0, [Math]::Min(400, ($output -replace "`r?`n", " | ").Length))) -ForegroundColor DarkYellow
    }

    $result = $null
    if (Test-Path -LiteralPath $Fixture.ResultPath -PathType Leaf) {
        try { $result = Get-Content -Raw -LiteralPath $Fixture.ResultPath | ConvertFrom-Json } catch { $result = $null }
    }

    $calls = @()
    if (Test-Path -LiteralPath $Fixture.CallsPath -PathType Leaf) {
        foreach ($line in @(Get-Content -LiteralPath $Fixture.CallsPath)) {
            if ([string]::IsNullOrWhiteSpace($line)) { continue }
            try { $calls += ($line | ConvertFrom-Json) } catch {}
        }
    }

    return [pscustomobject]@{ ExitCode = $code; Output = $output; Result = $result; Calls = $calls }
}

function Get-BatchedWorkerEvents {
    param([Parameter(Mandatory)]$Run)
    return @($Run.Calls | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.id) } | ForEach-Object { "$($_.e) $($_.id)" })
}

function Get-BatchedWorkerWtCallCount {
    param([Parameter(Mandatory)]$Fixture)
    if (-not (Test-Path -LiteralPath $Fixture.WtCallsPath)) { return 0 }
    return @(Get-Content -LiteralPath $Fixture.WtCallsPath | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }).Count
}


function Start-FreshCwdBootstrapProcess {
    # Runs the real static cwd bootstrap in a genuinely fresh pwsh process for
    # bootstrap regression coverage. The test launcher deliberately uses
    # -NoProfile for determinism; production tracked-tab argv never does (that
    # is asserted separately against New-DevWSTerminalCreateArguments).
    param(
        [Parameter(Mandatory)][string]$BootstrapPath,
        [Parameter(Mandatory)][string]$SetId,
        [Parameter(Mandatory)][string]$TerminalId,
        [Parameter(Mandatory)][string]$WindowId,
        [Parameter(Mandatory)][string]$SessionId,
        [Parameter(Mandatory)][string]$PublicationPath,
        [Parameter(Mandatory)][string]$ChildSpecBase64,
        [Parameter(Mandatory)][string]$WorkingDirectory,
        [int]$TabIndex = 0
    )

    $arguments = @(
        "-NoLogo",
        "-NoProfile",
        "-NoExit",
        "-File",
        $BootstrapPath,
        "-SetId",
        $SetId,
        "-TerminalId",
        $TerminalId,
        "-WindowId",
        $WindowId,
        "-TabIndex",
        [string]$TabIndex,
        "-SessionId",
        $SessionId,
        "-PublicationPath",
        $PublicationPath,
        "-ChildSpecBase64",
        $ChildSpecBase64
    )

    return (Start-Process `
        -FilePath (Get-Process -Id $PID).Path `
        -ArgumentList $arguments `
        -WorkingDirectory $WorkingDirectory `
        -PassThru `
        -WindowStyle Hidden)
}

function New-EditorStub {
    param(
        [Parameter(Mandatory)][string]$Name,
        [string]$ReplacementPath,
        [int]$ExitCode = 0,
        [string]$ViewLogPath,
        [string]$MarkerPath,
        [string]$DelayMarkerPath
    )

    $path = Join-Path $TestRoot "$Name.cmd"
    $lines = @("@echo off")

    if (-not [string]::IsNullOrWhiteSpace($DelayMarkerPath)) {
        # Approximate two seconds, then prove the editor process exited.
        $lines += "ping -n 3 127.0.0.1 >nul"
        $lines += "echo done > `"$DelayMarkerPath`""
    }

    if (-not [string]::IsNullOrWhiteSpace($ViewLogPath)) {
        $lines += "copy /Y `"%~1`" `"$ViewLogPath`" >nul"
    }

    if (-not [string]::IsNullOrWhiteSpace($MarkerPath)) {
        $lines += "echo ran > `"$MarkerPath`""
    }

    if (-not [string]::IsNullOrWhiteSpace($ReplacementPath)) {
        $lines += "copy /Y `"$ReplacementPath`" `"%~1`" >nul"
    }

    $lines += "exit /b $ExitCode"

    Set-Content -LiteralPath $path -Value ($lines -join "`r`n") -Encoding ASCII

    return $path
}

function Get-ThrownMessage {
    param([Parameter(Mandatory)][scriptblock]$Body)

    try {
        & $Body
    }
    catch {
        return $_.Exception.Message
    }

    throw "Assertion failed: expected an error, but no error was thrown."
}

function Invoke-WsCli {
    param(
        [Parameter(Mandatory)][string]$ConfigPath,
        [Parameter(Mandatory)][AllowEmptyCollection()][AllowEmptyString()][string[]]$Arguments = @(),
        [string]$InstallRoot,
        [string]$StateRoot,
        [string]$StartupPath,
        [string]$ScriptPath
    )

    $env:DEVWS_CONFIG = $ConfigPath

    if (-not [string]::IsNullOrWhiteSpace($InstallRoot)) {
        $env:DEVWS_INSTALL_ROOT = $InstallRoot
    }

    if (-not [string]::IsNullOrWhiteSpace($StateRoot)) {
        $env:DEVWS_STATE_ROOT = $StateRoot
    }

    if (-not [string]::IsNullOrWhiteSpace($StartupPath)) {
        $env:DEVWS_STARTUP_PATH = $StartupPath
    }

    try {
        $cliScript = if ([string]::IsNullOrWhiteSpace($ScriptPath)) { $WsScript } else { $ScriptPath }

        $output = & pwsh -NoLogo -NoProfile -File $cliScript @Arguments 2>&1 | Out-String
        $code   = $LASTEXITCODE
    }
    finally {
        Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        Remove-Item Env:\DEVWS_INSTALL_ROOT -ErrorAction SilentlyContinue
        Remove-Item Env:\DEVWS_STARTUP_PATH -ErrorAction SilentlyContinue

        # The test suite-wide state-root override must be restored, not removed.
        if (-not [string]::IsNullOrWhiteSpace($StateRoot)) {
            $env:DEVWS_STATE_ROOT = Join-Path $TestRoot "state-root"
        }
    }

    return [pscustomobject]@{
        ExitCode = $code
        Output   = $output
    }
}

New-Item -ItemType Directory -Path $TestRoot -Force | Out-Null

# Tests (and every child process they launch) must use disposable runtime state
# under the test root; the real %LOCALAPPDATA%\DevWS\state must never be
# touched by the test suite. The state-root directory itself is created up
# front so every run mode (the full suite or a single -Group selection) is
# deterministic and never depends on an earlier test having created it.
$env:DEVWS_STATE_ROOT = Join-Path $TestRoot "state-root"
New-Item -ItemType Directory -Path $env:DEVWS_STATE_ROOT -Force | Out-Null

try {
    Write-Host ""
    Write-Host "DevWS tests" -ForegroundColor Cyan

    Write-Host ""
    Start-TestGroup -Name 'default-config' -Title 'Default config'

    Test-Case "default config validates and preserves order" {
        # 1. The SHIPPED starter is a minimal, valid, personal-free schema-v3 config.
        $starter = Read-DevWSConfigFile -Path $BundledConfigPath
        Assert-DevWSConfig -Config $starter -Source $BundledConfigPath

        Assert-Equal 3 $starter.version "default config schema version"
        Assert-Equal "main" $starter.defaultSet "default set id"
        Assert-Equal 0 @($starter.bindings).Count "no set bindings yet"
        Assert-Equal 1 @($starter.sets).Count "single bundled set"
        Assert-Equal "main" $starter.sets[0].id "bundled set id"
        Assert-Equal 0 @($starter.sets[0].windows).Count "the shipped starter defines no workspace items"

        # The shipped starter must carry no personal workspace: no configured
        # item, no startup command, no application and no saved geometry.
        $starterJson = Get-Content -LiteralPath $BundledConfigPath -Raw
        foreach ($token in @('"path"', '"match"', '"launch"', '"layout"', '"command"', '"tabs"')) {
            Assert-True ($starterJson.IndexOf($token, [StringComparison]::Ordinal) -lt 0) `
                "the shipped starter must not contain the '$token' field"
        }

        # 2. The neutral test corpus preserves configured order and shape.
        $config = Get-TestWorkspaceConfig
        Assert-DevWSConfig -Config $config -Source $WorkspaceFixturePath

        $ids = @($config.sets[0].windows | ForEach-Object { $_.id })
        Assert-Equal 6 $ids.Count "workspace fixture window count"
        Assert-Equal "slot,studio,scratch,firefox,codex,antigravity" ($ids -join ",") "workspace fixture order"

        $types = @($config.sets[0].windows | ForEach-Object { $_.type }) -join ","
        Assert-Equal "terminal,terminal,terminal,app,app,app" $types "workspace fixture types"

        # Fixture identities are synthetic and distinct from the migrated live
        # canonical identities (DevWS-1/2/3).
        $windowIds = @($config.sets[0].windows | Where-Object { $_.type -eq "terminal" } | ForEach-Object { $_.windowId })
        Assert-Equal "DevWS-slot,DevWS-studio,DevWS-scratch" ($windowIds -join ",") "fixture terminal windowIds"

        $slot = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal "C:\DevWS-Fixture\workspaces\slot" $slot.path "slot path unchanged"
        Assert-Equal -7 $slot.layout.x "slot layout x unchanged"
        Assert-Equal 654 $slot.layout.w "slot layout w unchanged"
        Assert-Equal "devws-shell" $slot.tabs[0].command "slot command tab unchanged"
        Assert-True ($null -eq $slot.tabs[1].command) "slot idle tab unchanged"

        $firefox = @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal 633 $firefox.layout.x "firefox layout x unchanged"
        Assert-Equal "C:\Program Files\Mozilla Firefox\firefox.exe" $firefox.launch.value "firefox launch unchanged"

        $codex = @($config.sets[0].windows | Where-Object { $_.id -eq "codex" })[0]
        Assert-Equal "appId" $codex.launch.kind "codex launch kind unchanged"
        Assert-Equal "OpenAI.Codex_2p2nqsd0c76g0!App" $codex.launch.value "codex appId unchanged"
        Assert-Equal "processPathContains" $codex.match.kind "codex match kind unchanged"

        # 3. Path-existence validation stays enforced. The fixture's synthetic
        #    paths are deliberately absent on disk, so -RequireTerminalPaths must
        #    still refuse them (the accepting direction is exercised with real
        #    temporary directories in the validation group).
        $pathProbe = Get-TestWorkspaceConfig
        $pathProbe.sets[0].windows[0].path = Join-Path $TestRoot "definitely-absent-terminal-path"
        Assert-Throws { Assert-DevWSConfig -Config $pathProbe -Source $WorkspaceFixturePath -RequireTerminalPaths } `
            -Message "path existence validation still refuses an absent terminal path"
    }

