    Test-Case "binding hotkeys normalize to a canonical conservative grammar" {
        Assert-Equal "alt+shift+y" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+shift+y") "canonical input unchanged"
        Assert-Equal "alt+shift+y" (ConvertTo-DevWSBindingHotkey -Hotkey "SHIFT+ALT+Y") "case/order normalized"
        Assert-Equal "alt+shift+y" (ConvertTo-DevWSBindingHotkey -Hotkey " alt + SHIFT + y ") "surrounding whitespace tolerated"
        Assert-Equal "ctrl+alt+r" (ConvertTo-DevWSBindingHotkey -Hotkey "CTRL+ALT+R") "ctrl+alt"
        Assert-Equal "ctrl+shift+win+u" (ConvertTo-DevWSBindingHotkey -Hotkey "win+shift+ctrl+u") "canonical modifier order"
        Assert-Equal "ctrl+alt+shift+win+k" (ConvertTo-DevWSBindingHotkey -Hotkey "win+shift+alt+ctrl+k") "all four modifiers"
        Assert-Equal "alt+f1" (ConvertTo-DevWSBindingHotkey -Hotkey "ALT+F1") "f1"
        Assert-Equal "ctrl+f24" (ConvertTo-DevWSBindingHotkey -Hotkey "ctrl+F24") "f24"
        Assert-Equal "alt+1" (ConvertTo-DevWSBindingHotkey -Hotkey "ALT+1") "digit key"
        Assert-Equal "ctrl+space" (ConvertTo-DevWSBindingHotkey -Hotkey "CTRL+SPACE") "space"
        Assert-Equal "alt+enter" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+ENTER") "enter"
        Assert-Equal "shift+esc" (ConvertTo-DevWSBindingHotkey -Hotkey "shift+ESC") "esc"
        Assert-Equal "ctrl+backspace" (ConvertTo-DevWSBindingHotkey -Hotkey "ctrl+BACKSPACE") "backspace"
        Assert-Equal "alt+up" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+UP") "up"
        Assert-Equal "alt+down" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+DOWN") "down"
        Assert-Equal "alt+left" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+LEFT") "left"
        Assert-Equal "alt+right" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+RIGHT") "right"
        Assert-Equal "alt+home" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+HOME") "home"
        Assert-Equal "alt+end" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+END") "end"
        Assert-Equal "alt+pgup" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+PGUP") "pgup"
        Assert-Equal "alt+pgdn" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+PGDN") "pgdn"
        Assert-Equal "alt+insert" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+INSERT") "insert"
        Assert-Equal "alt+delete" (ConvertTo-DevWSBindingHotkey -Hotkey "alt+DELETE") "delete"

        foreach ($invalid in @(
            "", "y", "alt+", "+y", "alt++y", "alt+alt+y", "alt+shift+y+u",
            "alt+shift+u+y", "super+y", "alt+super", "alt+f25", "alt+tab+space",
            "alt+;", "alt+/", "ctrl+alt", "shift", "alt+ ", "alt+shift+yy"
        )) {
            Assert-Throws { ConvertTo-DevWSBindingHotkey -Hotkey $invalid } -Message "invalid hotkey '$invalid'"
        }
    }

    Test-Case "reserved hotkeys are detected after normalization" {
        foreach ($reserved in @("alt+shift+t", "shift+alt+t", "ALT+SHIFT+T")) {
            Assert-Equal $true (Test-DevWSReservedBindingHotkey -Hotkey $reserved) "reserved '$reserved'"
        }

        Assert-Equal $false (Test-DevWSReservedBindingHotkey -Hotkey "alt+t") "alt+t is ordinary binding space"
        Assert-Equal $false (Test-DevWSReservedBindingHotkey -Hotkey "T+ALT") "the retired Alt+T reservation is gone"
        Assert-Equal $false (Test-DevWSReservedBindingHotkey -Hotkey "ctrl+alt+t") "ctrl+alt+t is not reserved"
        Assert-Equal $false (Test-DevWSReservedBindingHotkey -Hotkey "alt+shift+y") "alt+shift+y is not reserved"

        Assert-Contains (Get-DevWSReservedBindingHotkeyReason -Hotkey "shift+alt+t") "defaultSet" "Alt+Shift+T reason names defaultSet"
        Assert-Equal "" (Get-DevWSReservedBindingHotkeyReason -Hotkey "alt+t") "Alt+T has no reservation reason"
    }

    Test-Case "binding hotkeys translate deterministically to AutoHotkey v2" {
        Assert-Equal "!+y" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "alt+shift+y") "alt+shift+y"
        Assert-Equal "^!r" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "ctrl+alt+r") "ctrl+alt+r"
        Assert-Equal "^+#u" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "ctrl+shift+win+u") "three modifiers"
        Assert-Equal "!Space" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "alt+space") "space"
        Assert-Equal "^PgDn" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "ctrl+pgdn") "pgdn"
        Assert-Equal "+F24" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "shift+f24") "f24"
        Assert-Equal "!1" (ConvertTo-DevWSAhkBindingHotkey -Hotkey "alt+1") "digit"

        Assert-Equal `
            (ConvertTo-DevWSAhkBindingHotkey -Hotkey "SHIFT+ALT+Y") `
            (ConvertTo-DevWSAhkBindingHotkey -Hotkey "alt+shift+y") `
            "translation is normalization-independent"

        Assert-Equal "'plain'" (ConvertTo-DevWSAhkSingleQuotedString -Value "plain") "single-quoted wrapper"
        Assert-Equal "'it``'s'" (ConvertTo-DevWSAhkSingleQuotedString -Value "it's") "single quote escaped"
        Assert-Equal "'a````b'" (ConvertTo-DevWSAhkSingleQuotedString -Value 'a`b') "backtick escaped"
        Assert-Throws { ConvertTo-DevWSAhkSingleQuotedString -Value "a`nb" } -Message "line breaks rejected"
    }

    Test-Case "bindings accept canonical { hotkey, setId } entries and reject invalid ones" {
        $empty = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"), (New-TestSet -Id "secondary"))
        Assert-DevWSConfig -Config $empty -Source "test"

        $valid = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main"),
            (New-TestSet -Id "secondary")
        ) -Bindings @(
            [ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" },
            [ordered]@{ hotkey = "ctrl+alt+r"; setId = "SECONDARY" },
            [ordered]@{ hotkey = "ctrl+shift+win+u"; setId = "main" }
        )
        Assert-DevWSConfig -Config $valid -Source "test"

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "main"; action = "launch" }))
        } "unknown property" "unknown binding property rejected"

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @("alt+shift+y"))
        } "bindings[0]" "malformed binding entry rejected"

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @([ordered]@{ hotkey = "alt+shift+y" }))
        } "setId" "missing setId rejected"

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" }))
        } "does not match a configured set" "unknown target set rejected"

        $message = Get-ThrownMessage {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @([ordered]@{ hotkey = "SHIFT+ALT+Y"; setId = "main" }))
        }
        Assert-Contains $message "alt+shift+y" "canonical spelling reported"
        Assert-Contains $message "canonical" "canonical requirement named"

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @([ordered]@{ hotkey = "y"; setId = "main" }))
        } "modifier" "invalid hotkey syntax rejected"

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"), (New-TestSet -Id "secondary")) -Bindings @(
                [ordered]@{ hotkey = "alt+shift+y"; setId = "main" },
                [ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" }
            ))
        } "duplicates" "duplicate canonical hotkeys rejected"

        foreach ($reserved in @("alt+shift+t")) {
            Assert-Throws {
                Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @((New-TestSet -Id "main")) -Bindings @([ordered]@{ hotkey = $reserved; setId = "main" }))
            } "reserved" "reserved '$reserved' rejected"
        }

        # The installer-only relaxed recognizer applies the same binding rules.
        $preModeConfig = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox")))
        ) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "main" })

        Assert-DevWSConfig -Config $preModeConfig -Source "test" -AllowMissingInstanceMode

        # alt+t is ordinary binding space for the relaxed recognizer too.
        Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox")))
        ) -Bindings @([ordered]@{ hotkey = "alt+t"; setId = "main" })) -Source "test" -AllowMissingInstanceMode

        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Sets @(
                (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox")))
            ) -Bindings @([ordered]@{ hotkey = "alt+shift+t"; setId = "main" })) -Source "test" -AllowMissingInstanceMode
        } "reserved" "relaxed recognizer rejects reserved bindings"
    }

