        $config = ConvertTo-TestConfig -Windows @($missing)
        Assert-DevWSConfig -Config $config -Source "test"

        Assert-Throws {
            Assert-DevWSConfig -Config $config -Source "test" -RequireTerminalPaths
        } "working directory does not exist"

        $disabledMissing = New-TerminalDefinition -Id "off" -Path (Join-Path $TestRoot "also-missing")
        $disabledMissing.enabled = $false
        $configWithDisabled = ConvertTo-TestConfig -Windows @($disabledMissing)
        Assert-DevWSConfig -Config $configWithDisabled -Source "test" -RequireTerminalPaths
    }

    Test-Case "valid minimal config passes" {
