        $app      = New-AppDefinition -Id "notes"
        $app.match.kind = "processPathContains"
        $app.match.value = "\Notes_"
        $app.launch.kind = "appId"
        $app.launch.value = "Vendor.Notes_1234!App"

        $config = ConvertTo-TestConfig -Windows @($terminal, $app)
