    Test-Case "terminal path validation is scoped to the selected set" {
        $mainTerminal      = New-TerminalDefinition -Id "slot" -Path $TestRoot
        $secondaryTerminal = New-TerminalDefinition -Id "slot" -WindowId "DevWS-secondary-slot" -Path (Join-Path $TestRoot "missing-secondary-dir")

        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($mainTerminal)),
            (New-TestSet -Id "secondary" -Windows @($secondaryTerminal))
        )

        # Structural validation passes, and default-set path validation ignores
        # the unrelated secondary set.
        Assert-DevWSConfig -Config $config -Source "test"
        Assert-DevWSConfig -Config $config -Source "test" -RequireTerminalPaths

        Assert-DevWSTerminalPaths -Config $config -Set (Resolve-DevWSSet -Config $config -Reference "main") -Source "test"

        Assert-Throws {
            Assert-DevWSTerminalPaths -Config $config -Set (Resolve-DevWSSet -Config $config -Reference "secondary") -Source "test"
        } "working directory does not exist"

        Assert-Throws {
            Assert-DevWSTerminalPaths -Config $config -Set "secondary" -Source "test"
        } "working directory does not exist"
    }

    Test-Case "malformed config JSON fails cleanly and names the file" {
        $dir = Join-Path $TestRoot "malformed-json"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $target = Join-Path $dir "workspace.json"
        Set-Content -LiteralPath $target -Value '{"version": 3, "sets": [' -Encoding UTF8

        Assert-Throws { Read-DevWSConfigFile -Path $target } "Invalid JSON"
        Assert-Throws { Read-DevWSConfigFile -Path $target } $target

        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target
        Assert-Throws { Get-DevWSConfig -Location $location } "Invalid JSON"
        Assert-Throws { Get-DevWSConfig -Location $location } $target
    }

    Test-Case "validation errors name the source, item, index, and field" {
        $terminal = New-TerminalDefinition -Id "badterm"
        $terminal.layout.w = 0
        $app = New-AppDefinition -Id "badapp"
        $app.match.kind = "title"

        $message = $null

        try {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Windows @($terminal, $app)) -Source "validation-context-test"
        }
        catch {
            $message = $_.Exception.Message
        }

        Assert-True ($null -ne $message) "invalid config is rejected"
        Assert-Contains $message "validation-context-test" "error names the source"
        Assert-Contains $message "sets[0] ('main') windows[0] ('badterm')" "terminal error carries its set, index, and id"
        Assert-Contains $message "layout.w" "terminal error names the field"
        Assert-Contains $message "sets[0] ('main') windows[1] ('badapp')" "app error carries its set, index, and id"
        Assert-Contains $message "match.kind" "app error names the field"
    }

    Write-Host ""
    Start-TestGroup -Name 'selection' -Title 'Selection and references'

    Test-Case "enabled-only selection preserves config order" {
        $a       = New-TerminalDefinition -Id "a"
        $b       = New-TerminalDefinition -Id "b"
        $b.enabled = $false
        $c       = New-TerminalDefinition -Id "c"
