        $config  = ConvertTo-TestConfig -Windows @($a, $b, $c, $app)

        $terminals = @(Get-DevWSWindows -Config $config -Type terminal -EnabledOnly)
        Assert-Equal "a,c" ($terminals.id -join ",") "enabled terminals in order"

        $all = @(Get-DevWSWindows -Config $config)
        Assert-Equal 4 $all.Count "all windows"

        $apps = @(Get-DevWSWindows -Config $config -Type app -EnabledOnly)
        Assert-Equal "app" ($apps.id -join ",") "enabled apps"
    }

    Test-Case "four-terminal configuration enumerates dynamically" {
        $terminals = @(
            (New-TerminalDefinition -Id "one" -Path $TestRoot),
            (New-TerminalDefinition -Id "two" -Path $TestRoot),
            (New-TerminalDefinition -Id "three" -Path $TestRoot),
            (New-TerminalDefinition -Id "four" -Path $TestRoot)
        )
        $config  = ConvertTo-TestConfig -Windows $terminals
        $enabled = @(Get-DevWSWindows -Config $config -Type terminal -EnabledOnly)
        Assert-Equal 4 $enabled.Count "four terminals"

        $ids = @($enabled | ForEach-Object { $_.id }) -join ","
        Assert-Equal "one,two,three,four" $ids "terminal order preserved"
    }

    Test-Case "references resolve by stable id and numeric order" {
        $config = Get-TestWorkspaceConfig

        Assert-Equal "slot" (Resolve-DevWSReference -Config $config -Reference "SLOT" -Type terminal).id "case-insensitive id"
        Assert-Equal "studio" (Resolve-DevWSReference -Config $config -Reference "2" -Type terminal).id "numeric terminal 2"
        Assert-Equal "scratch" (Resolve-DevWSReference -Config $config -Reference "3" -Type terminal).id "numeric terminal 3"
        Assert-Equal "firefox" (Resolve-DevWSReference -Config $config -Reference "1" -Type app).id "numeric app 1"

        Assert-Throws { Resolve-DevWSReference -Config $config -Reference "4" -Type terminal } "no terminal number 4"
        Assert-Throws { Resolve-DevWSReference -Config $config -Reference "firefox" -Type terminal } "not 'terminal'"
        Assert-Throws { Resolve-DevWSReference -Config $config -Reference "nope" } "Unknown workspace item"
    }

    Test-Case "set helpers resolve explicitly scoped items and default to defaultSet" {
        $mainApp = New-AppDefinition -Id "firefox"
        $secondaryApp = New-AppDefinition -Id "firefox"
        $secondaryApp.launch.value = "C:\Apps\secondary.exe"

        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($mainApp)),
            (New-TestSet -Id "secondary" -Windows @($secondaryApp))
        )

        $defaultItems   = @(Get-DevWSWindows -Config $config)
        $secondaryItems = @(Get-DevWSWindows -Config $config -Set "secondary")
        $resolvedSet    = Resolve-DevWSSet -Config $config -Reference "SECONDARY"

        Assert-Equal 1 $defaultItems.Count "unscoped selection uses defaultSet"
        Assert-Equal "C:\Apps\app.exe" $defaultItems[0].launch.value "default set item returned"
        Assert-Equal 1 $secondaryItems.Count "explicit set selection"
        Assert-Equal "C:\Apps\secondary.exe" $secondaryItems[0].launch.value "explicit set item returned"
        Assert-Equal "secondary" $resolvedSet.id "set ids resolve case-insensitively"

        Assert-Equal "app.exe" (Resolve-DevWSAppById -Config $config -Reference "firefox").match.value "unscoped resolution defaults to defaultSet"
        Assert-Equal "C:\Apps\secondary.exe" (Resolve-DevWSAppById -Config $config -Reference "firefox" -Set "secondary").launch.value "scoped resolution targets the named set"

        Assert-Equal 2 @(Get-DevWSSets -Config $config).Count "both sets enumerated"
        Assert-Throws { Resolve-DevWSSet -Config $config -Reference "nope" } "Unknown workspace set"
        Assert-Equal "main" (Resolve-DevWSTargetSet -Config $config).id "target-set defaulting"
    }

    Test-Case "scoped reference parser resolves sets and rejects malformed forms" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox"))),
            (New-TestSet -Id "secondary" -Windows @((New-AppDefinition -Id "firefox")))
        )

        $bare = Resolve-DevWSConfigReference -Config $config -Reference "firefox" -CommandName "test"
        Assert-Equal $false $bare.Scoped "bare reference is unscoped"
        Assert-Equal "main" $bare.SetId "bare reference targets defaultSet"
        Assert-Equal "firefox" $bare.ItemId "bare item portion"

        $scoped = Resolve-DevWSConfigReference -Config $config -Reference "SECONDARY/FIREFOX" -CommandName "test"
        Assert-Equal $true $scoped.Scoped "scoped reference flagged"
        Assert-Equal "secondary" $scoped.SetId "set resolves case-insensitively"
        Assert-Equal "secondary" $scoped.Set.id "resolved set object returned"
        Assert-Equal "FIREFOX" $scoped.ItemId "item portion preserved for case-insensitive item resolution"
        Assert-Equal "firefox" (Resolve-DevWSItemById -Config $config -Reference $scoped.ItemId -Set $scoped.Set).id "item resolves case-insensitively"

        Assert-Throws { Resolve-DevWSConfigReference -Config $config -Reference "/firefox" } "set id before '/' is empty"
        Assert-Throws { Resolve-DevWSConfigReference -Config $config -Reference "secondary/" } "item id after '/' is empty"
        Assert-Throws { Resolve-DevWSConfigReference -Config $config -Reference "secondary/foo/bar" } "exactly one '/'"
        Assert-Throws { Resolve-DevWSConfigReference -Config $config -Reference "unknown/firefox" } "Unknown workspace set"
    }

    Test-Case "bare references follow defaultSet changes" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox"))),
            (New-TestSet -Id "secondary" -Windows @((New-AppDefinition -Id "firefox")))
        )

        Assert-Equal "main" (Resolve-DevWSConfigReference -Config $config -Reference "firefox").SetId "initially defaultSet"

        $result = Set-DevWSDefaultSet -Config $config -Reference "secondary"
        Assert-Equal $true $result.Changed "default switched"
        Assert-Equal "secondary" $config.defaultSet "defaultSet updated"

        Assert-Equal "secondary" (Resolve-DevWSConfigReference -Config $config -Reference "firefox").SetId "bare reference follows the new default"
        Assert-Equal "firefox" (Get-DevWSWindows -Config $config -Type app)[0].id "unscoped item selection follows the new default"
    }

    Test-Case "scoped numeric references are stable-id only" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TerminalDefinition -Id "t1" -WindowId "DevWS-main-t1"),
                (New-TerminalDefinition -Id "t2" -WindowId "DevWS-main-t2")
            )),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TerminalDefinition -Id "x1" -WindowId "DevWS-secondary-x1"),
                (New-TerminalDefinition -Id "2" -WindowId "DevWS-secondary-2")
            ))
        )

        # Historical unscoped numeric alias keeps working against defaultSet.
        Assert-Equal "t2" (Resolve-DevWSReference -Config $config -Reference "2" -Type terminal).id "unscoped numeric alias"

        # Scoped "secondary/1" must never mean the first secondary terminal.
        $scopedOne = Resolve-DevWSConfigReference -Config $config -Reference "secondary/1"
        Assert-Equal "1" $scopedOne.ItemId "scoped item portion is literal"
        Assert-Throws {
            Resolve-DevWSItemById -Config $config -Reference $scopedOne.ItemId -Set $scopedOne.Set
        } "numeric aliases"

        # A literal stable id "2" in secondary resolves scoped without ordinal behavior.
        $scopedTwo = Resolve-DevWSConfigReference -Config $config -Reference "secondary/2"
        Assert-Equal "2" (Resolve-DevWSItemById -Config $config -Reference $scopedTwo.ItemId -Set $scopedTwo.Set).id "scoped literal numeric id resolves"
    }

    Test-Case "set management helpers manage ordered sets in memory" {
        $config = Get-TestWorkspaceConfig

        $lines = @(Get-DevWSSetsLines -Config $config)
        Assert-Equal 1 $lines.Count "one bundled set"
        Assert-Contains $lines[0] "* main" "default marker"
        Assert-Contains $lines[0] "6 items" "item count"
        Assert-Contains $lines[0] "(default)" "default suffix"

        $added = Add-DevWSSet -Config $config -Id "secondary"
        Assert-Equal "secondary" $added.id "added set id"
        Assert-Equal 0 @($added.windows).Count "new set is empty"
        Assert-Equal "main" $config.defaultSet "default unchanged"
        Assert-Equal "main,secondary" (@(Get-DevWSSets -Config $config).id -join ",") "sets stay ordered"
        Assert-DevWSConfig -Config $config -Source "test"

        $lines = @(Get-DevWSSetsLines -Config $config)
        Assert-Equal 2 $lines.Count "two sets listed"
        Assert-Contains $lines[1] "secondary" "second set listed"
        Assert-Contains $lines[1] "0 items" "empty count"

        Assert-Throws { Add-DevWSSet -Config $config -Id "SECONDARY" } "already exists"
        Assert-Throws { Add-DevWSSet -Config $config -Id "bad/id" } "reserved"
        Assert-Throws { Add-DevWSSet -Config $config -Id "bad id" } "may only contain"
        Assert-Equal 2 @(Get-DevWSSets -Config $config).Count "failed adds did not mutate"

        $setsBefore = ConvertTo-Json -InputObject @($config.sets) -Depth 20
        $switch = Set-DevWSDefaultSet -Config $config -Reference "SECONDARY"
        Assert-Equal $true $switch.Changed "case-insensitive switch"
        Assert-Equal "secondary" $config.defaultSet "defaultSet changed"
        Assert-Equal "secondary" (Get-DevWSDefaultSet -Config $config).id "resolved default"
        Assert-Equal $setsBefore (ConvertTo-Json -InputObject @($config.sets) -Depth 20) "only defaultSet changed"

        $again = Set-DevWSDefaultSet -Config $config -Reference "secondary"
        Assert-Equal $false $again.Changed "already-default is a no-op"
        Assert-Throws { Set-DevWSDefaultSet -Config $config -Reference "nope" } "Unknown workspace set"

        [void](Set-DevWSDefaultSet -Config $config -Reference "main")
        Assert-Throws { Remove-DevWSSet -Config $config -Reference "main" } "Cannot remove the default set"

        $removed = Remove-DevWSSet -Config $config -Reference "secondary"
        Assert-Equal "secondary" $removed.id "removed set reported"
        Assert-Equal 1 @(Get-DevWSSets -Config $config).Count "set removed"
        Assert-Equal "main" $config.defaultSet "default unchanged by removal"
        Assert-DevWSConfig -Config $config -Source "test"

        Assert-Throws { Remove-DevWSSet -Config $config -Reference "main" } "last remaining set"
        Assert-Throws { Remove-DevWSSet -Config $config -Reference "nope" } "Unknown workspace set"
    }

    Test-Case "mutation helpers are set-scoped and keep windowId checks global" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot" -WindowId "DevWS-main-slot" -Path $TestRoot))),
            (New-TestSet -Id "secondary" -Windows @((New-TerminalDefinition -Id "slot" -WindowId "DevWS-secondary-slot" -Path $TestRoot)))
        )

        # The same item id is free in a different set...
        Assert-DevWSNewItemId -Config $config -Set "main" -Id "secondary-only"

        # ...but a generated windowId must not collide with any other set's.
        # DevWS-secondary-other would be generated for a new secondary item;
        # give main's terminal that identity to force the global collision.
        @($config.sets[0].windows)[0].windowId = "DevWS-secondary-other"
        Assert-Throws {
            Add-DevWSTerminal -Config $config -Set "secondary" -Id "other" -Path $TestRoot -Command $null -Arguments @()
        } "collides"
        @($config.sets[0].windows)[0].windowId = "DevWS-main-slot"

        $app = Add-DevWSApp -Config $config -Set "secondary" -Id "firefox" -LaunchKind "exe" -LaunchValue "C:\ff.exe" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated"
        Assert-Equal "firefox" $app.id "app added"
        Assert-Equal 2 @((Resolve-DevWSSet -Config $config -Reference "secondary").windows).Count "secondary set grew"
        Assert-True (@((Resolve-DevWSSet -Config $config -Reference "main").windows).id -notcontains "firefox") "main set untouched"

        $removed = Remove-DevWSItem -Config $config -Reference "firefox" -Set "secondary"
        Assert-Equal "firefox" $removed.id "app removed from the resolved set"
        Assert-Equal 1 @((Resolve-DevWSSet -Config $config -Reference "secondary").windows).Count "secondary restored"

        Set-DevWSItemEnabled -Config $config -Reference "slot" -Enabled $false -Set "secondary" | Out-Null
        Assert-Equal $false (Resolve-DevWSItemById -Config $config -Reference "slot" -Set "secondary").enabled "flag changed in secondary"
        Assert-Equal $true (Resolve-DevWSItemById -Config $config -Reference "slot").enabled "main item unchanged"

        $renamed = Rename-DevWSItem -Config $config -Reference "slot" -NewId "slot2" -Set "secondary"
        Assert-Equal "slot2" $renamed.NewId "rename targets the resolved set"
        Assert-Equal "DevWS-secondary-slot" $renamed.Item.windowId "terminal windowId preserved by rename"
    }

    Write-Host ""
    Start-TestGroup -Name 'app-dispatch' -Title 'App dispatch'

    Test-Case "exe launch command quotes paths with spaces" {
        $config  = Get-TestWorkspaceConfig
        $firefox = Resolve-DevWSReference -Config $config -Reference "firefox" -Type app

        Assert-Equal '"C:\Program Files\Mozilla Firefox\firefox.exe"' (Get-DevWSAppLaunchCommandLine -App $firefox) "firefox command line"
    }

    Test-Case "exe launch command appends quoted args" {
        $app = @(Get-DevWSWindows -Config (ConvertTo-TestConfig -Windows @((New-AppDefinition))))[0]
        $app.launch.value = "C:\Apps\my app.exe"
        $app.launch.args = @("--flag", "two words")

        Assert-Equal '"C:\Apps\my app.exe" --flag "two words"' (Get-DevWSAppLaunchCommandLine -App $app) "quoted args"
    }

    Test-Case "appId launch command uses the AppsFolder shell" {
        $config = Get-TestWorkspaceConfig
        $codex  = Resolve-DevWSReference -Config $config -Reference "codex" -Type app

        Assert-Equal 'explorer.exe "shell:AppsFolder\OpenAI.Codex_2p2nqsd0c76g0!App"' (Get-DevWSAppLaunchCommandLine -App $codex) "codex command line"
    }

    Test-Case "appId launch rejects args with an actionable error" {
        $config = Get-TestWorkspaceConfig
        $codex  = Resolve-DevWSReference -Config $config -Reference "codex" -Type app
        $codex.launch.args = @("--profile")

        Assert-Throws { Get-DevWSAppLaunchCommandLine -App $codex } "does not support launch args"

        $message = $null

        try {
            $null = Get-DevWSAppLaunchCommandLine -App $codex
        }
        catch {
            $message = $_.Exception.Message
        }

        Assert-True ($null -ne $message) "args are rejected"
        Assert-Contains $message "codex" "error names the app"
        Assert-Contains $message "appId" "error names the launch kind"
        Assert-Contains $message "launch.args" "error names the offending field"
        Assert-Contains $message "exe" "error suggests the executable alternative"
        Assert-NotContains $message "Phase" "no stale phase wording"
    }

    Test-Case "app window matching uses Windows semantics and requires visible windows" {
        $exeMatch = [pscustomobject]@{ kind = "exe"; value = "Editor.EXE" }

        $visible = New-TestProbedWindow -Hwnd 11 -ProcessPath "C:\Apps\editor.exe" -ProcessName "editor.exe"
        Assert-True (Test-DevWSAppWindowMatch -Candidate $visible -Match $exeMatch) "exe match is case-insensitive"

        $hidden = New-TestProbedWindow -Hwnd 12 -ProcessPath "C:\Apps\editor.exe" -ProcessName "editor.exe" -Visible $false
        Assert-True (-not (Test-DevWSAppWindowMatch -Candidate $hidden -Match $exeMatch)) "hidden windows never match"

        $other = New-TestProbedWindow -Hwnd 13 -ProcessPath "C:\Apps\other.exe" -ProcessName "other.exe"
        Assert-True (-not (Test-DevWSAppWindowMatch -Candidate $other -Match $exeMatch)) "other executables do not match"

        $pathMatch = [pscustomobject]@{ kind = "processPathContains"; value = "\OPENAI.Codex_" }
        $pathCandidate = New-TestProbedWindow -Hwnd 14 -ProcessPath "C:\Program Files\WindowsApps\OpenAI.Codex_x\app\ChatGPT.exe" -ProcessName "ChatGPT.exe"
        Assert-True (Test-DevWSAppWindowMatch -Candidate $pathCandidate -Match $pathMatch) "processPathContains is case-insensitive"

        $noPath = New-TestProbedWindow -Hwnd 15 -ProcessPath $null -ProcessName "ChatGPT.exe"
        Assert-True (-not (Test-DevWSAppWindowMatch -Candidate $noPath -Match $pathMatch)) "unavailable paths cannot satisfy processPathContains"

        Assert-Throws {
            Test-DevWSAppWindowMatch -Candidate $visible -Match ([pscustomobject]@{ kind = "title"; value = "x" })
        } "unsupported app match.kind" "unknown match kinds fail"
    }

    Test-Case "configured dedicated identities come from explicit modes only" {
        $mainDedicated = New-AppDefinition -Id "editor"
        $mainDedicated["instanceMode"] = "dedicated"
        $mainShared = New-AppDefinition -Id "notes"
        $mainShared["instanceMode"] = "shared"
        $mainTransitional = New-AppDefinition -Id "browser" -InstanceMode ""
        $secondaryDedicated = New-AppDefinition -Id "editor"
        $secondaryDedicated["instanceMode"] = "dedicated"

        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($mainDedicated, $mainShared, $mainTransitional)),
            (New-TestSet -Id "secondary" -Windows @($secondaryDedicated))
        )

        $identities = @(Get-DevWSConfiguredDedicatedAppIdentities -Config $config)

        Assert-Equal 2 $identities.Count "only explicit dedicated apps produce identities"
        Assert-Equal "main/editor,secondary/editor" ((@($identities | ForEach-Object { $_.Key })) -join ",") "scoped identity keys"
    }

    Test-Case "dedicated selection resolves exact owners, adopts one unowned match, and refuses ambiguity" {
        $match = [pscustomobject]@{ kind = "exe"; value = "editor.exe" }

        $resolved = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 101 -OwnerKey "main/editor")) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "resolved" $resolved.Status "exact owner resolves"
        Assert-Equal 101 $resolved.Hwnd "exact owner hwnd returned"

        $mismatch = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 102 -ProcessPath "C:\Apps\other.exe" -ProcessName "other.exe" -OwnerKey "main/editor")) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "owned-mismatch" $mismatch.Status "exact owner that no longer matches fails"
        Assert-Contains $mismatch.Message "no longer matches" "mismatch is explained"

        $hiddenOwner = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 103 -Visible $false -OwnerKey "main/editor")) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "owned-mismatch" $hiddenOwner.Status "hidden exact owner is never silently replaced"

        $corrupt = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 104 -OwnerKey "main/editor"), (New-TestProbedWindow -Hwnd 105 -OwnerKey "main/editor")) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "ambiguous" $corrupt.Status "duplicate exact ownership is corruption"
        Assert-Contains $corrupt.Message "corrupt" "corruption is named"

        $adopt = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 106)) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "adopt" $adopt.Status "one unowned matching window is adopted"
        Assert-Equal 106 $adopt.Hwnd "adoption hwnd"

        $ambiguous = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 107), (New-TestProbedWindow -Hwnd 108)) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "ambiguous" $ambiguous.Status "multiple unowned matches fail"
        Assert-Contains $ambiguous.Message "never chooses arbitrarily" "ambiguity policy is stated"

        $ownedByOther = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 109 -OwnerKey "secondary/editor")) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "missing" $ownedByOther.Status "another item's window is never stolen"
    }

    Test-Case "dedicated launch outcome accepts only newly created distinct windows" {
        $match = [pscustomobject]@{ kind = "exe"; value = "editor.exe" }

        $noNew = Resolve-DevWSAppLaunchOutcome -Probed @((New-TestProbedWindow -Hwnd 201)) -PreLaunchHwnds @(201) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "missing" $noNew.Status "a pre-existing window is never a launch result"

        $oneNew = Resolve-DevWSAppLaunchOutcome -Probed @((New-TestProbedWindow -Hwnd 202)) -PreLaunchHwnds @(201) -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "resolved" $oneNew.Status "one new matching window resolves"
        Assert-Equal 202 $oneNew.Hwnd "new hwnd returned"
        Assert-True $oneNew.NeedsTagging "new dedicated windows need tagging"

        $twoNew = Resolve-DevWSAppLaunchOutcome -Probed @((New-TestProbedWindow -Hwnd 203), (New-TestProbedWindow -Hwnd 204)) -PreLaunchHwnds @() -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "ambiguous" $twoNew.Status "multiple new windows fail"
        Assert-Contains $twoNew.Message "multiple new matching windows" "ambiguity is named"

        $ownedNew = Resolve-DevWSAppLaunchOutcome -Probed @((New-TestProbedWindow -Hwnd 205 -OwnerKey "secondary/editor")) -PreLaunchHwnds @() -SetId "main" -ItemId "editor" -Match $match -Mode dedicated
        Assert-Equal "missing" $ownedNew.Status "a new window owned by another item is not claimed"
    }

    Test-Case "shared selection excludes dedicated-owned matches and refuses ambiguity" {
        $match = [pscustomobject]@{ kind = "exe"; value = "notes.exe" }

        $single = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 301 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe")) -SetId "main" -ItemId "notes" -Match $match -Mode shared
        Assert-Equal "resolved" $single.Status "one eligible window resolves"
        Assert-Equal 301 $single.Hwnd "eligible hwnd returned"

        $withDedicated = Resolve-DevWSAppWindowSelection -Probed @(
            (New-TestProbedWindow -Hwnd 302 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe"),
            (New-TestProbedWindow -Hwnd 303 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe" -OwnerKey "main/editor")
        ) -SetId "main" -ItemId "notes" -Match $match -Mode shared
        Assert-Equal "resolved" $withDedicated.Status "dedicated-owned matches are excluded"

        $ambiguous = Resolve-DevWSAppWindowSelection -Probed @(
            (New-TestProbedWindow -Hwnd 304 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe"),
            (New-TestProbedWindow -Hwnd 305 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe")
        ) -SetId "main" -ItemId "notes" -Match $match -Mode shared
        Assert-Equal "ambiguous" $ambiguous.Status "multiple eligible windows fail"
        Assert-Contains $ambiguous.Message "configured shared" "shared ambiguity is named"

        $onlyDedicated = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 306 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe" -OwnerKey "main/editor")) -SetId "main" -ItemId "notes" -Match $match -Mode shared
        Assert-Equal "missing" $onlyDedicated.Status "dedicated-owned windows never satisfy shared"

        $hidden = Resolve-DevWSAppWindowSelection -Probed @((New-TestProbedWindow -Hwnd 307 -ProcessPath "C:\Apps\notes.exe" -ProcessName "notes.exe" -Visible $false)) -SetId "main" -ItemId "notes" -Match $match -Mode shared
        Assert-Equal "missing" $hidden.Status "hidden matches never satisfy shared"
    }

    Test-Case "unsupported launch kinds fail before any process starts" {
        $config = Get-TestWorkspaceConfig
        $app    = Resolve-DevWSReference -Config $config -Reference "antigravity" -Type app
        $app.launch.kind = "shell"

        Assert-Throws { Get-DevWSAppLaunchCommandLine -App $app } "unsupported launch.kind"
        Assert-Throws { Invoke-DevWSAppLaunchCommand -App $app } "unsupported launch.kind"

        $codex = Resolve-DevWSReference -Config $config -Reference "codex" -Type app
        $codex.launch.args = @("--profile")
        Assert-Throws { Invoke-DevWSAppLaunchCommand -App $codex } "does not support launch args"
    }

    Write-Host ""
    Start-TestGroup -Name 'terminal-dispatch' -Title 'Terminal dispatch'

    Test-Case "terminal create arguments build tabs from config" {
        $config  = Get-TestWorkspaceConfig
        $slot    = Resolve-DevWSReference -Config $config -Reference "slot" -Type terminal
        $arguments = @(New-DevWSTerminalCreateArguments -Terminal $slot)
        $joined    = $arguments -join " "

        Assert-Equal 2 (@($arguments | Where-Object { $_ -eq "new-tab" }).Count) "one new-tab per configured tab"
        Assert-Equal "-w" $arguments[0] "window flag first"
        Assert-Equal "DevWS-slot" $arguments[1] "windowId second"
        Assert-Contains $joined "new-tab -p PowerShell -d C:\DevWS-Fixture\workspaces\slot --title DevWS-slot --suppressApplicationTitle" "tab creation options"
        Assert-Contains $joined "pwsh -NoExit -Command & 'devws-shell'" "configured command"
        Assert-Equal "devws-shell + idle" (Get-DevWSTerminalTabSummary -Terminal $slot) "tab summary"

        # WT command boundaries: one separator per configured tab, with the
        # final separator immediately before focus-tab (a missing one sends
        # `focus-tab -t N` to the last tab's pwsh).
        $separators = @($arguments | Where-Object { $_ -eq ";" })
        Assert-Equal 2 $separators.Count "one WT separator per configured tab"

        $focusIndex = [array]::IndexOf($arguments, "focus-tab")
        Assert-True ($focusIndex -gt 0) "focus-tab present in argv"
        Assert-Equal ";" $arguments[$focusIndex - 1] "separator immediately before focus-tab"
        Assert-Equal ($arguments.Count - 3) $focusIndex "focus-tab is the last WT command"

        $tail = @($arguments | Select-Object -Last 6)
        Assert-Equal 6 $tail.Count "tail length"
        Assert-Equal "--suppressApplicationTitle" $tail[0] "tail: final tab options"
        Assert-Equal "pwsh" $tail[1] "tail: final tab shell"
        Assert-Equal ";" $tail[2] "tail: separator"
        Assert-Equal "focus-tab" $tail[3] "tail: focus command"
        Assert-Equal "-t" $tail[4] "tail: focus flag"
        Assert-Equal "0" $tail[5] "tail: activeTab"
    }

    Test-Case "one-tab command-only terminal builds without an idle tab" {
        $terminal = New-TerminalDefinition -Id "agy" -Path $TestRoot
        $terminal.tabs = @([ordered]@{ command = "agy"; args = @() })
        $terminal.activeTab = 0

        $item      = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]
        $arguments = @(New-DevWSTerminalCreateArguments -Terminal $item)
        $joined    = $arguments -join " "

        Assert-Equal 1 (@($arguments | Where-Object { $_ -eq "new-tab" }).Count) "exactly one tab"
        Assert-Equal 1 (@($arguments | Where-Object { $_ -eq "pwsh" }).Count) "command tab is the only shell"
        Assert-Contains $joined "& 'agy'" "configured command"
        Assert-NotContains $joined "-NoLogo" "idle-tab mechanics are gone"

        # A one-tab terminal still needs the separator before focus-tab.
        Assert-Equal 1 (@($arguments | Where-Object { $_ -eq ";" }).Count) "one separator for one tab"
        $focusIndex = [array]::IndexOf($arguments, "focus-tab")
        Assert-Equal ";" $arguments[$focusIndex - 1] "separator immediately before focus-tab"
        Assert-Equal ($arguments.Count - 3) $focusIndex "focus-tab is the last WT command"
        Assert-Equal "focus-tab" $arguments[$arguments.Count - 3] "tail: focus command"
        Assert-Equal "-t" $arguments[$arguments.Count - 2] "tail: focus flag"
        Assert-Equal "0" $arguments[$arguments.Count - 1] "tail: activeTab"
    }

    Test-Case "terminal arguments quote configured command args" {
        $terminal = New-TerminalDefinition -Id "agy" -Path $TestRoot
        $terminal.tabs = @(
            [ordered]@{ command = "agy"; args = @("--foo", "bar baz", "it's") }
        )
        $terminal.activeTab = 0

        $item      = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]
        $arguments = @(New-DevWSTerminalCreateArguments -Terminal $item)
        $joined    = $arguments -join " "

        Assert-Contains $joined "& 'agy' '--foo' 'bar baz' 'it''s'" "command and args are single-quoted"

        $commandIndex = [array]::IndexOf($arguments, "& 'agy' '--foo' 'bar baz' 'it''s'")
        Assert-True ($commandIndex -gt 0) "command line is a single argv entry"
        Assert-Equal "-Command" $arguments[$commandIndex - 1] "pwsh -Command precedes the command line"
        Assert-Equal ";" $arguments[$commandIndex + 1] "separator follows the complete pwsh command"

        $focusIndex = [array]::IndexOf($arguments, "focus-tab")
        Assert-Equal ";" $arguments[$focusIndex - 1] "separator immediately before focus-tab"
    }

    Test-Case "command and args edge cases stay structured" {
        $terminal = New-TerminalDefinition -Id "tool" -Path $TestRoot
        $terminal.tabs = @(
            [ordered]@{ command = "tool"; args = @("", 'say "hi"', "two words", "plain") }
        )
        $terminal.activeTab = 0

        $item   = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]
        $joined = (@(New-DevWSTerminalCreateArguments -Terminal $item)) -join " "

        Assert-Contains $joined "& 'tool' '' 'say `"hi`"' 'two words' 'plain'" "empty, quoted, and spaced args preserved"
    }

    Test-Case "arbitrary tab counts build from config" {
        foreach ($tabCount in @(1, 2, 3, 4)) {
            $tabs = @()

            for ($i = 0; $i -lt $tabCount; $i++) {
                if ($i % 2 -eq 0) {
                    $tabs += [ordered]@{ command = "tool$i"; args = @("--n", "$i") }
                }
                else {
                    $tabs += [ordered]@{ command = $null; args = @() }
                }
            }

            $terminal = New-TerminalDefinition -Id "term$tabCount" -Path $TestRoot
            $terminal.tabs = $tabs
            $terminal.activeTab = $tabCount - 1

            $item      = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]
            $arguments = @(New-DevWSTerminalCreateArguments -Terminal $item)

            Assert-Equal $tabCount (@($arguments | Where-Object { $_ -eq "new-tab" }).Count) "$tabCount configured tabs"
            Assert-Contains ($arguments -join " ") "focus-tab -t $($tabCount - 1)" "$tabCount-tab activeTab"

            # Structural proof: one WT separator per configured tab, every
            # separator follows a complete tab payload and precedes a WT
            # command, and the last one precedes focus-tab.
            $separatorIndexes = @()
            $newTabIndexes    = @()

            for ($a = 0; $a -lt $arguments.Count; $a++) {
                if ($arguments[$a] -eq ";") { $separatorIndexes += $a }
                if ($arguments[$a] -eq "new-tab") { $newTabIndexes += $a }
            }

            Assert-Equal $tabCount $separatorIndexes.Count "$tabCount separators (one per configured tab)"

            foreach ($separatorIndex in $separatorIndexes) {
                Assert-True ($separatorIndex + 1 -lt $arguments.Count) "$tabCount-tab separator has a following command"
                Assert-True ($arguments[$separatorIndex + 1] -in @("new-tab", "focus-tab")) "$tabCount-tab separator precedes a WT command"
            }

            for ($a = 0; $a -lt $arguments.Count - 1; $a++) {
                Assert-True (-not ($arguments[$a] -eq ";" -and $arguments[$a + 1] -eq ";")) "$tabCount-tab no adjacent separators"
            }

            foreach ($newTabIndex in $newTabIndexes) {
                $nextSeparator = $null

                for ($a = $newTabIndex + 1; $a -lt $arguments.Count; $a++) {
                    if ($arguments[$a] -eq ";") { $nextSeparator = $a; break }
                }

                Assert-True ($null -ne $nextSeparator) "$tabCount-tab every new-tab is closed by a separator"
                Assert-True ($arguments[$nextSeparator - 1] -eq "pwsh" -or $arguments[$nextSeparator - 1].StartsWith("& ")) "$tabCount-tab separator follows the complete tab payload"
            }

            $focusIndex = [array]::IndexOf($arguments, "focus-tab")
            Assert-Equal ($arguments.Count - 3) $focusIndex "$tabCount-tab focus-tab is the last WT command"
            Assert-Equal ";" $arguments[$focusIndex - 1] "$tabCount-tab separator immediately before focus-tab"
            Assert-Equal "$($tabCount - 1)" $arguments[$focusIndex + 2] "$tabCount-tab activeTab index"
        }
    }

    Test-Case "launch and reset inherit the corrected creation argv from the shared helper" {
        # Reset still builds creation argv directly through the shared helper.
        $reset = Get-SourceOf "src\workers\elevated-reset.ps1"
        Assert-Contains $reset "New-DevWSTerminalCreateArguments" "elevated-reset.ps1 builds creation argv through the shared helper"
        Assert-NotContains $reset 'Add(";"' "elevated-reset.ps1 must not build WT separators itself"
        Assert-NotContains $reset "focus-tab" "elevated-reset.ps1 must not append its own focus-tab command"

        # Stage 2: the launch worker delegates creation policy to the canonical
        # terminal-launch library, which is the only place that builds argv.
        $worker = Get-SourceOf "src\workers\elevated.ps1"
        Assert-Contains $worker "Get-DevWSTerminalLaunchPlan" "launch worker uses the canonical terminal plan"
        Assert-NotContains $worker "New-DevWSTerminalCreateArguments" "launch worker must not duplicate creation policy"
        Assert-NotContains $worker 'Add(";"' "launch worker must not build WT separators itself"
        Assert-NotContains $worker "focus-tab" "launch worker must not append its own focus-tab command"

        $library = Get-SourceOf "src\lib\devws-terminal-launch.ps1"
        Assert-Contains $library "New-DevWSTerminalCreateArguments" "canonical library builds creation argv through the shared helper"
        Assert-NotContains $library 'Add(";"' "canonical library must not build WT separators itself"
        Assert-NotContains $library "focus-tab" "canonical library must not append its own focus-tab command"

        # Both hosts use the same shared helper, so the boundary fix is
        # inherited without duplicating it.
        $config = Get-TestWorkspaceConfig
        $slot   = Resolve-DevWSReference -Config $config -Reference "slot" -Type terminal
        $arguments = @(New-DevWSTerminalCreateArguments -Terminal $slot)
        $focusIndex = [array]::IndexOf($arguments, "focus-tab")

        Assert-Equal ";" $arguments[$focusIndex - 1] "shared helper output carries the separator"
    }

    Test-Case "arbitrary terminal counts build without slot assumptions" {
        $terminals = @(
            (New-TerminalDefinition -Id "one" -Path $TestRoot),
            (New-TerminalDefinition -Id "two" -Path $TestRoot),
            (New-TerminalDefinition -Id "three" -Path $TestRoot),
            (New-TerminalDefinition -Id "four" -Path $TestRoot)
        )
        $config  = ConvertTo-TestConfig -Windows $terminals
        $enabled = @(Get-DevWSWindows -Config $config -Type terminal -EnabledOnly)
        Assert-Equal 4 $enabled.Count "four terminals"

        foreach ($terminal in $enabled) {
            $arguments = @(New-DevWSTerminalCreateArguments -Terminal $terminal)
