    Write-Host ""
    Start-TestGroup -Name 'runtime-state' -Title 'Runtime state'

    Test-Case "missing runtime state is handled as empty v2 state" {
        $state = Read-DevWSRuntimeState -Path (Join-Path $TestRoot "state\missing.json")

        Assert-Equal 2 $state.version "state version"
        Assert-Equal 0 $state.terminals.Count "no terminals"
        Assert-True ($null -eq (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot")) "no entry"
    }

    Test-Case "runtime state saves and loads atomically" {
        $path = Join-Path $TestRoot "state\runtime.json"

        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 123456
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "agy" -WindowId "DevWS-agy" -Hwnd 987654
        Save-DevWSRuntimeState -State $state -Path $path

        Assert-True (Test-Path -LiteralPath $path -PathType Leaf) "state file written"
        Assert-True (-not (Test-Path -LiteralPath "$path.tmp")) "temp file cleaned up"

        $loaded = Read-DevWSRuntimeState -Path $path
        Assert-Equal 2 $loaded.terminals.Count "two entries"

        $entry = Get-DevWSRuntimeTerminal -State $loaded -SetId "MAIN" -Id "SLOT"
        Assert-Equal "DevWS-slot" $entry.windowId "windowId stored"
        Assert-Equal 123456 $entry.hwnd "hwnd stored as number"

        $text = Get-Content -LiteralPath $path -Raw
        Assert-Contains $text '"version": 2' "state version written"
    }

    Test-Case "runtime state keys are set-scoped and do not collide" {
        $path = Join-Path $TestRoot "state\two-set-runtime.json"

        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-1" -Hwnd 111
        Set-DevWSRuntimeTerminal -State $state -SetId "secondary" -Id "slot" -WindowId "DevWS-secondary-slot" -Hwnd 222

        Assert-Equal 2 $state.terminals.Count "duplicate item ids coexist"
        Assert-Equal 111 (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot").hwnd "main hwnd"
        Assert-Equal 222 (Get-DevWSRuntimeTerminal -State $state -SetId "secondary" -Id "slot").hwnd "secondary hwnd"
        Assert-Equal 111 (Get-DevWSRuntimeTerminal -State $state -SetId "MAIN" -Id "SLOT").hwnd "scoped lookup is case-insensitive"
        Assert-Equal "main/slot" (Get-DevWSRuntimeTerminalKey -SetId "main" -Id "slot") "canonical key format"

        Assert-Throws { Get-DevWSRuntimeTerminalKey -SetId "" -Id "slot" } "requires both" "missing set id rejected"
        Assert-Throws { Get-DevWSRuntimeTerminalKey -SetId "main" -Id "" } "requires both" "missing item id rejected"

        # Updating one scoped entry never alters the other.
        Set-DevWSRuntimeTerminal -State $state -SetId "secondary" -Id "slot" -WindowId "DevWS-secondary-slot" -Hwnd 333
        Assert-Equal 111 (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot").hwnd "main untouched by secondary update"
        Assert-Equal 333 (Get-DevWSRuntimeTerminal -State $state -SetId "secondary" -Id "slot").hwnd "secondary updated"

        Save-DevWSRuntimeState -State $state -Path $path
        $loaded = Read-DevWSRuntimeState -Path $path
        Assert-Equal 111 (Get-DevWSRuntimeTerminal -State $loaded -SetId "main" -Id "slot").hwnd "main survives reload"
        Assert-Equal 333 (Get-DevWSRuntimeTerminal -State $loaded -SetId "secondary" -Id "slot").hwnd "secondary survives reload"

        Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
    }

    Test-Case "runtime state overwrites only the exact scoped key case-insensitively" {
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 1
        Set-DevWSRuntimeTerminal -State $state -SetId "MAIN" -Id "SLOT" -WindowId "DevWS-slot-2" -Hwnd 2

        Assert-Equal 1 $state.terminals.Count "single entry"
        $entry = Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot"
        Assert-Equal "DevWS-slot-2" $entry.windowId "entry replaced"
        Assert-Equal 2 $entry.hwnd "hwnd replaced"
    }

    Test-Case "version 1 runtime state is disposed without migration or rewrite" {
        $dir = Join-Path $TestRoot "state\v1-dispose"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $path = Join-Path $dir "runtime-state.json"
        $v1 = '{"version":1,"terminals":{"slot":{"windowId":"DevWS-1","hwnd":111},"studio":{"windowId":"DevWS-2","hwnd":222}}}'
        Set-Content -LiteralPath $path -Value $v1 -Encoding UTF8
        $before = Get-FileBase64 -Path $path

        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 2 $state.version "returned state is v2"
        Assert-Equal 0 $state.terminals.Count "legacy bare entries are not imported"
        Assert-Equal $before (Get-FileBase64 -Path $path) "reading does not rewrite the file"

        # A later normal write produces v2 state keyed by set/item only.
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-1" -Hwnd 111
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "studio" -WindowId "DevWS-2" -Hwnd 222
        Save-DevWSRuntimeState -State $state -Path $path

        $text = Get-Content -LiteralPath $path -Raw
        Assert-Contains $text '"version": 2' "new state is v2"
        Assert-Contains $text 'main/slot' "slot key is set-scoped"
        Assert-Contains $text 'main/studio' "studio key is set-scoped"
        Assert-NotContains $text '"slot":' "no bare slot key is written"
        Assert-NotContains $text '"studio":' "no bare studio key is written"

        $reloaded = Read-DevWSRuntimeState -Path $path
        Assert-Equal 2 $reloaded.terminals.Count "two recovered scoped entries"
        Assert-Equal 111 (Get-DevWSRuntimeTerminal -State $reloaded -SetId "main" -Id "slot").hwnd "slot hwnd recovered"
        Assert-Equal 222 (Get-DevWSRuntimeTerminal -State $reloaded -SetId "main" -Id "studio").hwnd "studio hwnd recovered"
    }

    Test-Case "corrupt or unknown runtime state does not throw and stays empty" {
        $dir = Join-Path $TestRoot "state\corrupt"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $path = Join-Path $dir "runtime-state.json"
        $configBefore = Get-FileBase64 -Path $WorkspaceFixturePath

        Set-Content -LiteralPath $path -Value '{"version":2,"terminals":{"main/slot":{'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "corrupt state ignored"

        Set-Content -LiteralPath $path -Value '[]'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "non-object JSON ignored"

        Set-Content -LiteralPath $path -Value '"just a string"'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "scalar JSON ignored"

        Set-Content -LiteralPath $path -Value '{"version":99,"terminals":{"main/slot":{"windowId":"DevWS-1","hwnd":5}}}'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "unknown version ignored"

        Set-Content -LiteralPath $path -Value '{"version":2}'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "missing terminals property ignored"

        Set-Content -LiteralPath $path -Value '{"version":2,"terminals":{"main/slot":null}}'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "null terminal record ignored"

        Set-Content -LiteralPath $path -Value '{"version":2,"terminals":{"main/slot":{"windowId":"DevWS-1","hwnd":"abc"}}}'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 0 $state.terminals.Count "non-numeric hwnd ignored"

        Set-Content -LiteralPath $path -Value '{"version":2,"terminals":{"main/slot":{"hwnd":7}}}'
        $state = Read-DevWSRuntimeState -Path $path
        Assert-Equal 7 (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot").hwnd "record without windowId still reads (windowId empty)"

        Assert-Equal $configBefore (Get-FileBase64 -Path $WorkspaceFixturePath) "malformed runtime state never touches canonical config"
    }

    Test-Case "stale renamed runtime keys fall back without aliasing" {
        # A rename keeps the durable windowId but changes the scoped key; the
        # old key must never satisfy a lookup for the new key.
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "old" -WindowId "DevWS-durable" -Hwnd 919191

        Assert-Equal 919191 (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "old").hwnd "old key intact"
        Assert-True ($null -eq (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "new")) "new key has no alias entry"

        # After rediscovery the new key can be cached independently.
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "new" -WindowId "DevWS-durable" -Hwnd 929292
        Assert-Equal 929292 (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "new").hwnd "new key cached"
        Assert-Equal 919191 (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "old").hwnd "old key remains stale but harmless"
    }

