    Test-Case "HWND association requires windowId, process, and tab match" {
        $tabs = New-DevWSPresentTabNameSet -Names @("DevWS-a")

        Assert-True (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ProcessName "WindowsTerminal.exe" -TabNames $tabs -RequireProcess) "fully valid"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ExpectedWindowId "DevWS-b" -ProcessName "WindowsTerminal.exe" -TabNames $tabs -RequireProcess)) "state recorded for another terminal"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ProcessName "notepad.exe" -TabNames $tabs -RequireProcess)) "wrong process"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ProcessName $null -TabNames $tabs -RequireProcess)) "process required for stored hwnd"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ProcessName "WindowsTerminal.exe" -TabNames (New-DevWSPresentTabNameSet -Names @("Other")) -RequireProcess)) "tab association missing"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ProcessName "WindowsTerminal.exe" -TabNames $null)) "no tab names"
        Assert-True (Test-DevWSHwndAssociation -WindowId "DevWS-a" -TabNames $tabs) "association-only mode is available"
