    Test-Case "UIA-recovered HWNDs must belong to Windows Terminal" {
        $tabs = New-DevWSPresentTabNameSet -Names @("DevWS-a")

        # A foreign application exposing a same-named UI Automation tab must be
        # rejected by the same validator used for stored HWNDs.
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "DevWS-a" -ProcessName "notepad.exe" -TabNames $tabs -RequireProcess)) "association rejects a foreign process"

        $foreign = [pscustomobject]@{ Hwnd = 11; ExpectedWindowId = $null; ProcessName = "notepad.exe"; TabNames = $tabs }
        Assert-True ($null -eq (Select-DevWSTerminalHwndCandidate -Candidates @($foreign) -WindowId "DevWS-a" -RequireProcess)) "selector rejects a foreign process"

        # The same candidate with a verified WindowsTerminal process is accepted.
        $managed = [pscustomobject]@{ Hwnd = 12; ExpectedWindowId = $null; ProcessName = "WindowsTerminal.exe"; TabNames = $tabs }
        $selected = Select-DevWSTerminalHwndCandidate -Candidates @($managed) -WindowId "DevWS-a" -RequireProcess
        Assert-Equal 12 $selected.Hwnd "selector accepts the managed candidate"
    }

    Test-Case "HWND candidate selector skips invalid entries" {
        $tabs = New-DevWSPresentTabNameSet -Names @("DevWS-a")

        $wrongWindow = [pscustomobject]@{ Hwnd = 1; ExpectedWindowId = "DevWS-other"; ProcessName = "WindowsTerminal.exe"; TabNames = $tabs }
        $wrongProcess = [pscustomobject]@{ Hwnd = 2; ExpectedWindowId = "DevWS-a"; ProcessName = "notepad.exe"; TabNames = $tabs }
        $valid        = [pscustomobject]@{ Hwnd = 3; ExpectedWindowId = "DevWS-a"; ProcessName = "WindowsTerminal.exe"; TabNames = $tabs }

        $selected = Select-DevWSTerminalHwndCandidate -Candidates @($wrongWindow, $wrongProcess, $valid) -WindowId "DevWS-a" -RequireProcess
        Assert-Equal 3 $selected.Hwnd "first valid candidate selected"

        $none = Select-DevWSTerminalHwndCandidate -Candidates @($wrongWindow, $null) -WindowId "DevWS-a" -RequireProcess
        Assert-True ($null -eq $none) "stale candidates are rejected"
    }

    Test-Case "stale runtime-state HWNDs cannot make a closed terminal present" {
        # A closed window yields no HWND candidate (Get-DevWSHwndCandidate
        # returns $null when the window no longer exists), so a stored state
        # entry must be rejected and the terminal treated as missing.
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-1" -Hwnd 918273645

        $entry = Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot"
        Assert-Equal 918273645 $entry.hwnd "stale HWND stored (disposable state)"
        Assert-Equal "DevWS-1" $entry.windowId "stale entry windowId"

        # Missing/closed HWND -> candidate is $null -> selector rejects it.
        $selected = Select-DevWSTerminalHwndCandidate -Candidates @($null) -WindowId "DevWS-1" -RequireProcess
        Assert-True ($null -eq $selected) "a closed HWND never validates as present"

        # A state entry recorded for another managed terminal never validates.
        $tabs = New-DevWSPresentTabNameSet -Names @("DevWS-1")
        $crossed = [pscustomobject]@{
            Hwnd             = 5
            ExpectedWindowId = "DevWS-OTHER"
            ProcessName      = "WindowsTerminal.exe"
            TabNames         = $tabs
        }

        Assert-True ($null -eq (Select-DevWSTerminalHwndCandidate -Candidates @($crossed) -WindowId "DevWS-1" -RequireProcess)) "crossed state entry never validates"

        # A candidate whose tab set no longer contains the windowId is
        # rejected (a reused HWND for an unrelated window).
        $wrongTabs = [pscustomobject]@{
            Hwnd             = 6
            ExpectedWindowId = "DevWS-1"
            ProcessName      = "WindowsTerminal.exe"
            TabNames         = (New-DevWSPresentTabNameSet -Names @("SomethingElse"))
        }

        Assert-True ($null -eq (Select-DevWSTerminalHwndCandidate -Candidates @($wrongTabs) -WindowId "DevWS-1" -RequireProcess)) "missing tab association never validates"

        # Resolver composition: rejected state falls through to UIA discovery,
        # and "missing" is what lets launch create the terminal.
        $identity = Get-SourceOf "src\lib\devws-identity.ps1"
        $resolveStart = $identity.IndexOf("function Resolve-DevWSTerminalHwnd")
        Assert-True ($resolveStart -ge 0) "resolver located"

        $resolver    = $identity.Substring($resolveStart)
        $stateBranch = $resolver.IndexOf("Get-DevWSRuntimeTerminal")
        $uiaFallback = $resolver.IndexOf("Get-DevWSTerminalHwnd")

        Assert-True ($stateBranch -ge 0 -and $uiaFallback -gt $stateBranch) "stale state falls through to UIA discovery"
        Assert-Contains $resolver 'Status = "missing"' "no terminal resolves to missing, so launch may create it"

        # Stage 2: state-first classification is owned by the canonical
        # terminal-launch library; state is validated before any candidate
        # discovery, and the worker delegates to it.
        $planLib = Get-SourceOf "src\lib\devws-terminal-launch.ps1"
        $stateIndex = $planLib.IndexOf("Step 1: state-first exact validation")
        $candidateIndex = $planLib.IndexOf("Step 2: unmatched candidates")
        Assert-True ($stateIndex -ge 0 -and $candidateIndex -gt $stateIndex) "state-first classification precedes candidate discovery"
        Assert-Contains $planLib 'State = "present"; Source = "state"' "a validated state HWND becomes present/state"

        $worker = Get-SourceOf "src\workers\elevated.ps1"
        Assert-Contains $worker "Get-DevWSTerminalLaunchPlan" "launch worker delegates to the canonical plan"
        Assert-NotContains $worker "Resolve-DevWSTerminalHwnd" "no legacy per-terminal resolver in the worker"
    }

    Test-Case "created-window tab count is guarded by raw counts" {
        Assert-True (Test-DevWSCreatedTabCount -ActualCount 2 -ConfiguredCount 2) "exact count accepted"
        Assert-True (Test-DevWSCreatedTabCount -ActualCount 1 -ConfiguredCount 2) "lower count tolerated (documented materialization policy)"
        Assert-True (-not (Test-DevWSCreatedTabCount -ActualCount 3 -ConfiguredCount 2)) "extra tabs rejected"
        Assert-True (Test-DevWSCreatedTabCount -ActualCount 4 -ConfiguredCount 4) "four exact accepted"
        Assert-True (-not (Test-DevWSCreatedTabCount -ActualCount 5 -ConfiguredCount 4)) "four plus duplicate rejected"
    }

    Test-Case "raw tab counting preserves duplicate names" {
        $twoIdentical = @("DevWS-a", "DevWS-a")
        Assert-Equal 2 (Get-DevWSTabCountFromElements -Elements $twoIdentical) "two identical names count as two"

        $fourIdentical = @("DevWS-a", "DevWS-a", "DevWS-a", "DevWS-a")
        Assert-Equal 4 (Get-DevWSTabCountFromElements -Elements $fourIdentical) "four identical names count as four"

        Assert-Equal 0 (Get-DevWSTabCountFromElements -Elements @()) "empty count"
        Assert-Equal 0 (Get-DevWSTabCountFromElements -Elements $null) "null count"

        # The name-set helper still deduplicates those same names, which is
        # correct for identity/presence but must not be used for counting.
        Assert-Equal 1 (New-DevWSPresentTabNameSet -Names $fourIdentical).Count "name set deduplicates for identity"
    }

