        foreach ($kind in @("launch", "capture", "focus", "reset")) {
            Assert-Equal "DevWS.Worker.$kind.$sid" (Get-DevWSWorkerOperationPipeName -Kind $kind) "$kind pipe name is operation- and SID-scoped"
        }

        Assert-Equal "DevWorkspace-ElevatedHelper"   (Get-DevWSWorkerKindTaskName -Kind "launch")  "launch task binding"
        Assert-Equal "DevWorkspace-ElevatedCapture"  (Get-DevWSWorkerKindTaskName -Kind "capture") "capture task binding"
        Assert-Equal "DevWorkspace-ElevatedFocus"    (Get-DevWSWorkerKindTaskName -Kind "focus")   "focus task binding"
        Assert-Equal "DevWorkspace-ElevatedReset"    (Get-DevWSWorkerKindTaskName -Kind "reset")   "reset task binding"

        Assert-Equal "elevated.ps1"         (Get-DevWSWorkerKindScriptName -Kind "launch")  "launch script binding"
        Assert-Equal "elevated-capture.ps1" (Get-DevWSWorkerKindScriptName -Kind "capture") "capture script binding"
        Assert-Equal "elevated-focus.ps1"   (Get-DevWSWorkerKindScriptName -Kind "focus")   "focus script binding"
        Assert-Equal "elevated-reset.ps1"   (Get-DevWSWorkerKindScriptName -Kind "reset")   "reset script binding"

        Assert-Equal "-NoProfile -WindowStyle Hidden -File" ((Get-DevWSWorkerFixedArgumentPrefix) -join " ") "fixed worker action prefix"

        $protocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        Assert-Contains $protocol "DevWS.Worker.`$Kind.`$sid" "pipe namespace literal" 
        Assert-NotContains $protocol "Get-DevWSExchangePaths" "the request/result file exchange is retired"
        Assert-NotContains $protocol "Wait-DevWSResultFile" "the result-file polling helper is retired"
