    Test-Case "frame codec enforces the encoded byte ceiling, strict UTF-8 and framing" {
        $bytes = ConvertTo-DevWSWorkerFrameBytes -Object ([ordered]@{ version = 1; operation = "focus"; requestId = "11111111-2222-3333-4444-555555555555"; payload = @{ setId = "main" } })
        $roundTrip = Test-DevWSWorkerFrameBytes -Bytes ($bytes + [byte]10)
        Assert-Equal $true $roundTrip.Ok "encoded frame round trips"
        Assert-Equal "focus" ([string]$roundTrip.Value.operation) "frame value decoded"

        $missing = Test-DevWSWorkerFrameBytes -Bytes $bytes
        Assert-Equal $false $missing.Ok "a frame without the LF terminator is refused"
        Assert-Contains $missing.Error "newline" "missing terminator reason"

        $empty = Test-DevWSWorkerFrameBytes -Bytes ([byte[]]@(10))
        Assert-Equal $false $empty.Ok "empty frame refused"

        $invalidUtf8 = Test-DevWSWorkerFrameBytes -Bytes ([byte[]]@(0x7B, 0x22, 0xFF, 0xFE, 0x22, 0x7D, 10))
        Assert-Equal $false $invalidUtf8.Ok "invalid UTF-8 refused"
        Assert-Contains $invalidUtf8.Error "UTF-8" "invalid UTF-8 reason"

        $deep = Test-DevWSWorkerFrameBytes -Bytes (([System.Text.Encoding]::UTF8.GetBytes((('[' * 20) + '1' + (']' * 20)))) + [byte]10)
        Assert-Equal $false $deep.Ok "over-deep nesting refused"
        Assert-Contains $deep.Error "nesting" "nesting reason"

        $scalar = Test-DevWSWorkerFrameBytes -Bytes (([System.Text.Encoding]::UTF8.GetBytes('42')) + [byte]10)
        Assert-Equal $false $scalar.Ok "non-object frame root refused"

        # Multibyte boundary: the ceiling applies to ENCODED bytes.
        $prefix = '{"version":1,"operation":"poc","requestId":"x","payload":{"pad":"'
        $suffix = '"}}'
        $pad = ('é' * 30000)
        $text = $prefix + $pad + $suffix
        $encoded = [System.Text.Encoding]::UTF8.GetBytes($text)
        while ($encoded.Length -lt 65536) { $pad += 'a'; $text = $prefix + $pad + $suffix; $encoded = [System.Text.Encoding]::UTF8.GetBytes($text) }
        Assert-Equal 65536 $encoded.Length "boundary frame sized to the encoded ceiling"
        $boundary = Test-DevWSWorkerFrameBytes -Bytes ($encoded + [byte]10)
        Assert-Equal $true $boundary.Ok "a frame of exactly 65,536 encoded bytes is accepted"

        $over = Test-DevWSWorkerFrameBytes -Bytes (([System.Text.Encoding]::UTF8.GetBytes($text + 'a')) + [byte]10)
        Assert-Equal $false $over.Ok "one encoded byte over the ceiling is refused"
        Assert-Contains $over.Error "ceiling" "over-ceiling reason"

        $readFrame = Read-DevWSWorkerFrame -Stream ([System.IO.MemoryStream]::new(($bytes + [byte]10))) -TimeoutSeconds 2
        Assert-Equal $true $readFrame.Ok "stream reader collects one LF-terminated frame"
        $partialStream = [System.IO.MemoryStream]::new($bytes[0..([Math]::Floor($bytes.Length / 2))])
        $partialRead = Read-DevWSWorkerFrame -Stream $partialStream -TimeoutSeconds 1
        Assert-Equal $false $partialRead.Ok "a partial frame without LF is refused"
    }

    Test-Case "strict request schema per operation" {
        function Test-RequestFrameJson([string]$json, [string]$kind) {
            $frameBytes = [System.Text.Encoding]::UTF8.GetBytes($json)
            $frame = Test-DevWSWorkerFrameBytes -Bytes ($frameBytes + [byte]10)
            if (-not $frame.Ok) { return $frame }
            $checked = Test-DevWSWorkerRequestFrame -Value $frame.Value -Kind $kind
            return [pscustomobject]@{ Ok = $checked.Ok; Error = $checked.Error; RequestId = $checked.RequestId }
        }

        $rid = "11111111-2222-3333-4444-555555555555"
        $valid = Test-RequestFrameJson "{""version"":1,""operation"":""focus"",""requestId"":""$rid"",""payload"":{""setId"":""main""}}" "focus"
        Assert-Equal $true $valid.Ok "valid focus request admitted"
        Assert-Equal $rid $valid.RequestId "canonical GUID requestId retained"

        Assert-Equal $false (Test-RequestFrameJson "{""version"":2,""operation"":""focus"",""requestId"":""$rid"",""payload"":{""setId"":""main""}}" "focus").Ok "wrong version refused"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""launch"",""requestId"":""$rid"",""payload"":{""setId"":""main""}}" "focus").Ok "cross-kind operation refused"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""focus"",""requestId"":""11111111-2222-3333-4444-55555555555A"",""payload"":{""setId"":""main""}}" "focus").Ok "non-canonical requestId refused"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""focus"",""requestId"":""$rid"",""payload"":{""setId"":""main""},""extra"":1}" "focus").Ok "unexpected top-level field refused"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""focus"",""requestId"":""$rid"",""payload"":{""setId"":""main"",""extra"":1}}" "focus").Ok "unexpected focus payload field refused"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""focus"",""requestId"":""$rid"",""payload"":{}}" "focus").Ok "missing setId refused"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""capture"",""requestId"":""$rid"",""payload"":{""setId"":""main"",""terminalPlacements"":[]}}" "capture").Ok "capture rejects placement payloads"
        Assert-Equal $false (Test-RequestFrameJson "{""version"":1,""operation"":""reset"",""requestId"":""$rid"",""payload"":{""setId"":""main""}}" "reset").Ok "reset requires placements"
        Assert-Equal $true (Test-RequestFrameJson "{""version"":1,""operation"":""reset"",""requestId"":""$rid"",""payload"":{""setId"":""main"",""terminalPlacements"":[{""id"":""slot"",""move"":true}]}}" "reset").Ok "reset placements admitted"
        Assert-Equal $true (Test-RequestFrameJson "{""version"":1,""operation"":""launch"",""requestId"":""$rid"",""payload"":{""setId"":""main"",""terminalPlacements"":[]}}" "launch").Ok "launch placements optional and admitted"
    }

    Test-Case "strict response correlation and type-conditional fields" {
        function Test-ResponseFrameObject($object, [string]$operation, [string]$requestId, [string[]]$allowedTypes) {
            $frameBytes = [System.Text.Encoding]::UTF8.GetBytes(($object | ConvertTo-Json -Compress))
            $frame = Test-DevWSWorkerFrameBytes -Bytes ($frameBytes + [byte]10)
            if (-not $frame.Ok) { return $frame }
            return Test-DevWSWorkerResponseFrame -Value $frame.Value -ExpectedOperation $operation -ExpectedRequestId $requestId -AllowedTypes $allowedTypes
        }

        $rid = "11111111-2222-3333-4444-555555555555"

        Assert-Equal $true (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "accepted"; operation = "focus"; requestId = $rid }) "focus" $rid @("accepted")).Ok "accepted admitted"
        Assert-Equal $true (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "final"; operation = "focus"; requestId = $rid; ok = $true; message = "OK" }) "focus" $rid @("final")).Ok "final admitted"
        Assert-Equal $true (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "final"; operation = "capture"; requestId = $rid; ok = $true; message = "OK"; data = @{ publication = "x" } }) "capture" $rid @("final")).Ok "final data admitted"
        Assert-Equal $true (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "error"; operation = "focus"; requestId = $rid; error = "nope" }) "focus" $rid @("error")).Ok "error admitted"

        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "final"; operation = "focus"; requestId = "99999999-2222-3333-4444-555555555555"; ok = $true; message = "x" }) "focus" $rid @("final")).Ok "stale requestId refused"
        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "final"; operation = "launch"; requestId = $rid; ok = $true; message = "x" }) "focus" $rid @("final")).Ok "cross-kind operation refused"
        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "final"; operation = "focus"; requestId = $rid; message = "x" }) "focus" $rid @("final")).Ok "final without boolean ok refused"
        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "final"; operation = "focus"; requestId = $rid; ok = "true"; message = "x" }) "focus" $rid @("final")).Ok "string ok refused"
        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "accepted"; operation = "focus"; requestId = $rid; data = @{} }) "focus" $rid @("accepted")).Ok "accepted with data refused"
        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "error"; operation = "focus"; requestId = $rid }) "focus" $rid @("error")).Ok "error without text refused"
        Assert-Equal $false (Test-ResponseFrameObject ([ordered]@{ version = 1; type = "accepted"; operation = "focus"; requestId = $rid }) "focus" $rid @("error")).Ok "unexpected accepted refused when only error allowed"
    }

    Test-Case "caller-observable state classification and deadline arithmetic" {
        Assert-Equal "NotTransmitted" (Resolve-DevWSWorkerCallerState -Connected $false -BytesSent $false) "no connection and no bytes"
        Assert-Equal "NotTransmitted" (Resolve-DevWSWorkerCallerState -Connected $true -BytesSent $false) "authenticated connection without bytes"
        Assert-Equal "Rejected" (Resolve-DevWSWorkerCallerState -Connected $true -BytesSent $true -CorrelatedRejection $true) "explicit correlated rejection"
        Assert-Equal "UncertainNoAck" (Resolve-DevWSWorkerCallerState -Connected $true -BytesSent $true) "bytes without acknowledgment"
        Assert-Equal "UncertainAfterAccept" (Resolve-DevWSWorkerCallerState -Connected $true -BytesSent $true -AcceptedObserved $true) "accepted without final"
        Assert-Equal "Completed" (Resolve-DevWSWorkerCallerState -Connected $true -BytesSent $true -AcceptedObserved $true -FinalObserved $true) "correlated final"

        $future = [datetime]::UtcNow.AddSeconds(30)
        $remaining = Get-DevWSWorkerRemainingSeconds -Deadline $future
        Assert-True ($remaining -ge 28 -and $remaining -le 30) "remaining budget tracks the absolute deadline (got $remaining)"
        Assert-Equal 0 (Get-DevWSWorkerRemainingSeconds -Deadline ([datetime]::UtcNow.AddSeconds(-5))) "expired budget is zero, never negative"

        $failure = New-DevWSWorkerStateException -State "UncertainAfterAccept" -Message "lost"
        Assert-Equal "UncertainAfterAccept" (Get-DevWSWorkerErrorState -ErrorRecord ([pscustomobject]@{ Exception = $failure })) "state survives on the exception data"
        Assert-Equal $null (Get-DevWSWorkerErrorState -ErrorRecord ([pscustomobject]@{ Exception = [System.Exception]::new("plain") })) "plain failures carry no worker state"
    }

    Test-Case "identity policy accepts the authenticated shape and refuses every deviation" {
        $exec = (Get-Process -Id $PID).Path
        $scriptPath = Join-Path $TestRoot "identity-policy-worker.ps1"
        $sessionId = Get-DevWSCurrentTokenSessionId
        $userSid = Get-DevWSCurrentUserSid
        $argv = @("-NoProfile", "-WindowStyle", "Hidden", "-File", $scriptPath)

        function New-IdentityRecord([hashtable]$Overrides) {
            $record = [ordered]@{
                Integrity    = "S-1-16-12288"
                UserSid      = $userSid
                SessionId    = $sessionId
                ImagePath    = $exec
                CommandLine  = ('"' + $exec + '" -NoProfile -WindowStyle Hidden -File "' + $scriptPath + '"')
                CreationTime = [long]134000000000000000
            }
            foreach ($key in $Overrides.Keys) { $record[$key] = $Overrides[$key] }
            return [pscustomobject]$record
        }

        function Test-Identity([hashtable]$Overrides) {
            return Test-DevWSWorkerServerIdentityRecord -Record (New-IdentityRecord $Overrides) -ExpectedExec $exec -ExpectedArgv $argv -ExpectedUserSid $userSid -ExpectedSessionId $sessionId
        }

        Assert-Equal $true (Test-Identity @{}).Ok "exact authenticated shape accepted"

        $integrity = Test-Identity @{ Integrity = "S-1-16-8192" }
        Assert-Equal $false $integrity.Ok "Medium integrity refused"
        Assert-Contains $integrity.Reason "integrity" "integrity refusal reason"

        Assert-Equal $false (Test-Identity @{ UserSid = "S-1-5-21-0-0-0-9999" }).Ok "wrong user refused"
        Assert-Equal $false (Test-Identity @{ SessionId = $sessionId + 7 }).Ok "wrong session refused"
        Assert-Equal $false (Test-Identity @{ ImagePath = "C:\evil\pwsh.exe" }).Ok "wrong executable refused"
        Assert-Equal $false (Test-Identity @{ CreationTime = $null }).Ok "missing creation time refused"
        Assert-Equal $false (Test-Identity @{ CreationTime = [long]0 }).Ok "zero creation time refused"
        Assert-Equal $false (Test-Identity @{ CommandLine = "" }).Ok "missing command line refused"
        Assert-Equal $false (Test-Identity @{ CommandLine = "not json parseable at all ??" }).Ok "unparsable command line refused"

        # Command-line mimic and near-miss forms: substring evidence alone never passes.
        $mimic = Test-Identity @{ CommandLine = ('"' + $exec + '" -NoProfile -WindowStyle Hidden -File "' + (Join-Path $TestRoot "evil\identity-policy-worker.ps1") + '"') }
        Assert-Equal $false $mimic.Ok "a look-alike worker script path is refused"

        $extra = Test-Identity @{ CommandLine = ('"' + $exec + '" -NoProfile -WindowStyle Hidden -File "' + $scriptPath + '" -Extra') }
        Assert-Equal $false $extra.Ok "an extra argv token is refused"

        $wrongArgv0 = Test-Identity @{ CommandLine = ('"C:\evil\pwsh.exe" -NoProfile -WindowStyle Hidden -File "' + $scriptPath + '"') }
        Assert-Equal $false $wrongArgv0.Ok "a different image argv0 is refused"

        $substring = Test-Identity @{ CommandLine = ("x " + $exec + " -NoProfile -WindowStyle Hidden -File " + $scriptPath) }
        Assert-Equal $false $substring.Ok "a substring-only command line is refused"
    }

    Test-Case "scheduled task declaration parsing and workspace path helpers" {
        $sampleXml = @"
<?xml version="1.0" encoding="UTF-16"?>
<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
  <Actions Context="Author">
    <Exec>
      <Command>C:\Program Files\WindowsApps\Microsoft.PowerShell_7.6.6.0_x64__8wekyb3d8bbwe\pwsh.exe</Command>
      <Arguments>-NoProfile -WindowStyle Hidden -File "C:\Program Files\DevWS\privileged\workers\elevated.ps1"</Arguments>
    </Exec>
  </Actions>
</Task>
"@
        $declaration = ConvertFrom-DevWSScheduledTaskDeclarationXml -Xml $sampleXml
        Assert-Equal "C:\Program Files\WindowsApps\Microsoft.PowerShell_7.6.6.0_x64__8wekyb3d8bbwe\pwsh.exe" $declaration.Exec "task action executable parsed"
        Assert-Equal 5 @($declaration.Argv).Count "token-aware argument list parsed"
        Assert-Equal "-File" $declaration.Argv[3] "argument tokens kept exactly"
        Assert-Equal "C:\Program Files\DevWS\privileged\workers\elevated.ps1" $declaration.Argv[4] "protected worker script token"

        $badXml = Get-ThrownMessage { ConvertFrom-DevWSScheduledTaskDeclarationXml -Xml "not xml" }
        Assert-Contains $badXml "valid XML" "malformed declaration fails actionably"

        Assert-Equal $true (Test-DevWSWorkerPathIdentityEqual -Left "C:\X\Y\z.ps1" -Right "c:\x\y\Z.ps1\") "canonical path identity is case- and separator-insensitive"
        Assert-Equal $false (Test-DevWSWorkerPathIdentityEqual -Left "C:\X\Y\z.ps1" -Right "C:\X\Y\z.ps1.bak") "canonical path identity is exact"
        Assert-Equal $false (Test-DevWSWorkerPathIdentityEqual -Left "C:\X\Y\z.ps1" -Right "z.ps1") "relative paths never match"

        $protectedScript = Get-DevWSWorkerKindExpectedScriptPath -Kind "launch"
        Assert-Contains $protectedScript "workers" "protected worker script root"
        Assert-Contains $protectedScript "elevated.ps1" "protected worker script name"
    }

