    Test-Case "caller death after transmission executes at most once and stays uncertain" {
        $case = New-WorkerPipeFixtureCase -Name "wp-caller-death" -Kind "focus" -Mode "normal"
        . (New-WorkerPipeFixtureExpectation -Case $case -Kind "focus")

        try {
            $null = Start-WorkerPipeFixtureProcess -Case $case

            $client = Connect-WorkerPipeFixtureClient -Case $case -TimeoutSeconds 30
            Assert-True ($null -ne $client) "raw fixture connection established"

            try {
                Write-DevWSWorkerFrame -Stream $client -Object ([ordered]@{
                    version   = 1
                    operation = "focus"
                    requestId = [guid]::NewGuid().ToString()
                    payload   = [ordered]@{ setId = "main" }
                })

                # Caller death is simulated only AFTER the worker has consumed
                # the request frame (the transport contract: transmission that
                # completed is irreversible). A close that races the worker's
                # accept/read is a different (pre-transmission) scenario.
                $null = Wait-WorkerPipeFixtureLog -Path $case.Log -Pattern "request-ok" -TimeoutSeconds 20
            }
            finally { $client.Dispose() }

            $deadline = [datetime]::UtcNow.AddSeconds(20)

            while ([datetime]::UtcNow -lt $deadline -and (Get-WorkerPipeFixtureSideEffectCount -Case $case) -eq 0) {
                Start-Sleep -Milliseconds 100
            }

            Assert-Equal 1 (Get-WorkerPipeFixtureSideEffectCount -Case $case) "the transmitted operation executed exactly once"
        }
        finally { Stop-WorkerPipeFixtureProcess -Case $case }
    }

