    Test-Case "bounded response delivery gives a stalled reader a finite worker exit" {
        # Correction A: a client that connects, sends a valid request and then
        # keeps its handle open without reading a single response byte must not
        # block the single-instance worker indefinitely.
        $case = New-WorkerPipeFixtureCase -Name "wp-stalled-reader" -Kind "focus" -Mode "normal"
        . (New-WorkerPipeFixtureExpectation -Case $case -Kind "focus")

        try {
            $null = Start-WorkerPipeFixtureProcess -Case $case

            $client = Connect-WorkerPipeFixtureClient -Case $case -TimeoutSeconds 30
            Assert-True ($null -ne $client) "stalled-reader connection established"

            try {
                Write-DevWSWorkerFrame -Stream $client -Object ([ordered]@{
                    version   = 1
                    operation = "focus"
                    requestId = [guid]::NewGuid().ToString()
                    payload   = [ordered]@{ setId = "main" }
                })

                # The fixture serves the request, reaches its delivery barrier
                # and must exit within the finite bound despite the silent,
                # still-open reader (bound = delivery budget + process slack).
                $watch = [System.Diagnostics.Stopwatch]::StartNew()
                $exited = $case.Process.WaitForExit(20000)
                $watch.Stop()

                Assert-True $exited "the stalled reader did not pin the worker (exited within the finite bound)"
                Assert-True ($watch.Elapsed.TotalMilliseconds -lt 15000) "worker exit bound stayed finite (measured $([Math]::Round($watch.Elapsed.TotalMilliseconds)) ms)"
                Assert-Equal 1 (Get-WorkerPipeFixtureSideEffectCount -Case $case) "the accepted operation still executed exactly once"

                # Normal fast delivery still works for a cooperating reader.
                $reader = [System.IO.StreamReader]::new($client, [System.Text.UTF8Encoding]::new($false), $false, 4096, $true)
                $accepted = Read-DevWSWorkerFrame -Stream $reader.BaseStream -TimeoutSeconds 10
                $final = Read-DevWSWorkerFrame -Stream $reader.BaseStream -TimeoutSeconds 10
                Assert-True ($accepted.Ok -and [string]$accepted.Value.type -eq 'accepted') "ACCEPTED remained readable after the stalled window"
                Assert-True ($final.Ok -and [string]$final.Value.type -eq 'final') "FINAL remained readable after the stalled window"
            }
            finally { $client.Dispose() }
        }
        finally { Stop-WorkerPipeFixtureProcess -Case $case }
    }

