    Test-Case "identity acquisition failures close the process handle and classify as pre-transmission" {
        # Correction B: every throwing acquisition path must close the just
        # opened process handle, return a failed record and surface as
        # NotTransmitted (no request byte may be sent).
        $case = New-WorkerPipeFixtureCase -Name "wp-identity-throw" -Kind "focus" -Mode "normal"
        . (New-WorkerPipeFixtureExpectation -Case $case -Kind "focus")

        try {
            $null = Start-WorkerPipeFixtureProcess -Case $case

            # One fixture connection serves the whole matrix: the identity
            # record read is non-destructive (it only queries process facts),
            # so all four injection points can run against the same live server.
            $client = Connect-WorkerPipeFixtureClient -Case $case -TimeoutSeconds 30
            Assert-True ($null -ne $client) "identity-throw connection"

            try {
                foreach ($injection in @('token', 'image', 'creation', 'commandline')) {
                    # Body-local injection functions resolve dynamically for the
                    # calls made from this body and disappear with its scope;
                    # they never replace the library definitions used by other
                    # tests. The injection selector travels via a script
                    # variable because function bodies resolve variables at
                    # call time through the same dynamic chain.
                    $script:workerPipeThrowInjection = $injection

                    function Get-DevWSTokenStringSid {
                        param([IntPtr]$Token, [int]$InformationClass)
                        if ($script:workerPipeThrowInjection -eq 'token') { throw "injected token failure" }
                        return 'S-1-16-12288'
                    }
                    function Get-DevWSWorkerProcessImagePath {
                        param([IntPtr]$Handle)
                        if ($script:workerPipeThrowInjection -eq 'image') { throw "injected image failure" }
                        return (Get-Process -Id $PID).Path
                    }
                    function Get-DevWSWorkerProcessCreationTime {
                        param([IntPtr]$Handle)
                        if ($script:workerPipeThrowInjection -eq 'creation') { throw "injected creation failure" }
                        return [long]134000000000000000
                    }
                    function Get-DevWSWorkerProcessCommandLine {
                        param([IntPtr]$Handle)
                        if ($script:workerPipeThrowInjection -eq 'commandline') { throw "injected command-line failure" }
                        return '"x" y'
                    }

                    $record = Get-DevWSWorkerServerIdentityRecord -Connection $client
                    Assert-Equal $false $record.Ok "identity record failed for the injected $injection failure"
                    Assert-Equal ([IntPtr]::Zero) ([IntPtr]$record.Handle) "no handle is exposed on the failure path ($injection)"
                    Assert-Contains ([string]$record.Error) 'identity-read-failed' "the $injection failure is named"
                }
            }
            finally {
                $client.Dispose()
            }
        }
        finally { Stop-WorkerPipeFixtureProcess -Case $case }
    }

    Test-Case "unexpected ACK-read failures stay uncertain and never become NotTransmitted" {
        # Correction B: after transmission may have begun, a throwing read or a
