                param($Stream, [int]$TimeoutSeconds = 20, [int]$MaxBytes = 65536)
                throw "injected ack read failure"
            }

            $err = $null

            try { $null = Start-DevWSWorkerRequest -Kind "focus" -TaskName "DevWorkspace-ElevatedFocus" -Payload @{ setId = "main" } -TimeoutSeconds 30 } catch { $err = $_ }

            Assert-True ($null -ne $err) "the injected read failure surfaced"
            Assert-Equal "UncertainNoAck" (Get-DevWSWorkerErrorState -ErrorRecord $err) "a post-transmission read failure is uncertain, never NotTransmitted"

            # Contract semantics under test: the uncertainty classification and
            # the absence of any automatic replay. One worker serves exactly one
            # request, so the counted side effect can never exceed one; the
            # fixture log evidences that the child performed its transport work.
            Start-Sleep -Milliseconds 500
            $count = Get-WorkerPipeFixtureSideEffectCount -Case $case
            Assert-True ($count -le 1) "the transmitted operation can never execute more than once (got $count)"
            Assert-True (Test-Path $case.Log) "the fixture produced its transport log"
        }
        finally {
            Stop-WorkerPipeFixtureProcess -Case $case
        }
    }

