        . (New-WorkerPipeFixtureExpectation -Case $case -Kind "focus" -RefuseIdentity)

        try {
            $before = @(Get-Process -Id $PID).HandleCount

            for ($i = 1; $i -le 8; $i++) {
                $err = $null
                try { $null = Start-DevWSWorkerRequest -Kind "focus" -TaskName "DevWorkspace-ElevatedFocus" -Payload @{ setId = "main" } -TimeoutSeconds 8 } catch { $err = $_ }
                Assert-Equal "NotTransmitted" (Get-DevWSWorkerErrorState -ErrorRecord $err) "attempt $i refused before transmission"
            }

            [System.GC]::Collect()
            [System.GC]::WaitForPendingFinalizers()
            [System.GC]::Collect()

            $after = @(Get-Process -Id $PID).HandleCount
            Assert-True (($after - $before) -le 8) "handle count stayed bounded across refused attempts (before=$before after=$after)"
        }
        finally { Stop-WorkerPipeFixtureProcess -Case $case }
    }

    Test-Case "scheduled task kickoff is bounded, exit-code checked and token-exact" {
        # Correction C: the trusted absolute schtasks.exe runs on a hard budget
        # with verbatim argument tokens; a nonzero exit is refused explicitly
        # and a stalled invocation is terminated without touching the worker.
        $protocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        Assert-Contains $protocol "function Invoke-DevWSBoundedProcess" "bounded process runner present"
        Assert-Contains $protocol "Get-DevWSTrustedSystemExecutable -Name `"schtasks.exe`"" "trusted absolute schtasks resolver retained"
        Assert-Contains $protocol "-Arguments @('/run', '/tn', `$TaskName)" "kickoff passes verbatim argument tokens (no shell quoting)"
        Assert-Contains $protocol "ExitCode -ne 0" "nonzero exit codes are refused explicitly"
        Assert-Contains $protocol "10000" "the kick budget is ten seconds"
        Assert-NotContains $protocol "& `$schtasks /run" "no unbounded direct invocation remains"
        Assert-NotContains $protocol "Start-Process" "no shell/Start-Process quoting path"

        # The corrected lifetime contract: no unbounded output waits, retained
        # diagnostics are capped, and termination claims require confirmation.
        Assert-NotContains $protocol "GetAwaiter()" "no unbounded output-task waits remain"
        Assert-Contains $protocol "OutputRetentionChars" "retained diagnostics are bounded"
        Assert-Contains $protocol "could not be confirmed" "unconfirmed termination is never claimed as terminated"
        Assert-Contains $protocol "TerminationGraceMilliseconds" "termination cleanup is an explicitly bounded window"

        # Bounded runner behavior itself: immediate success, immediate nonzero,
        # and a stalled child that must be terminated within the budget.
        # Output contract: exactly ONE structured result object (never a stray
        # Boolean from the inner Process.Start), with ExitCode and Detail.
        $pwsh = (Get-Process -Id $PID).Path

        $successOutput = @(Invoke-DevWSBoundedProcess -FilePath $pwsh -Arguments @('-NoProfile', '-Command', 'exit 0') -TimeoutMilliseconds 15000 -Label 'probe')
        Assert-Equal 1 $successOutput.Count "a successful run returns exactly one output object"
        $success = $successOutput[0]
        Assert-True ($null -ne $success.PSObject.Properties['ExitCode']) "the result exposes ExitCode"
        Assert-True ($null -ne $success.PSObject.Properties['Detail']) "the result exposes Detail"
        Assert-Equal 0 $success.ExitCode "immediate success returns exit 0"
        Assert-Equal '' ([string]$success.Detail) "a silent child yields an empty detail"

        $nonzeroOutput = @(Invoke-DevWSBoundedProcess -FilePath $pwsh -Arguments @('-NoProfile', '-Command', 'exit 7') -TimeoutMilliseconds 15000 -Label 'probe')
        Assert-Equal 1 $nonzeroOutput.Count "a nonzero child exit returns exactly one structured result"
        Assert-Equal 7 $nonzeroOutput[0].ExitCode "immediate nonzero exit is reported"

        $detailOutput = @(Invoke-DevWSBoundedProcess -FilePath $pwsh -Arguments @('-NoProfile', '-Command', '[Console]::Error.Write("probe-detail"); exit 5') -TimeoutMilliseconds 15000 -Label 'probe')
        Assert-Equal 1 $detailOutput.Count "a child with stderr still returns exactly one structured result"
        Assert-Contains ([string]$detailOutput[0].Detail) 'probe-detail' "retained stderr surfaces as Detail"

        # No stray Boolean may ever reach the success pipeline.
        $strayBoolean = @($successOutput | Where-Object { $_ -is [bool] })
        Assert-Equal 0 $strayBoolean.Count "the runner never emits a stray Boolean to the success pipeline"

        $missingTask = $null
        try { Start-DevWSScheduledTask -TaskName "DevWS-Definitely-Missing-Task-$([guid]::NewGuid().ToString('N').Substring(0,8))" -TimeoutMilliseconds 10000 } catch { $missingTask = $_ }
        Assert-True ($null -ne $missingTask) "a nonexistent task kick fails"
        Assert-Contains ([string]$missingTask.Exception.Message) "exit code" "the kickoff failure names the exit code"

        # Stalled child: a unique marker makes the ACTUAL child PID directly
        # identifiable, so the orphan assertion observes the real process rather
        # than filtering on a diagnostic label absent from the command line.
        $stallMarker = "P2D-KICK-STALL-$([guid]::NewGuid().ToString('N').Substring(0, 8))"
        $watch = [System.Diagnostics.Stopwatch]::StartNew()
        $stalled = $null

        try {
            Invoke-DevWSBoundedProcess -FilePath $pwsh -Arguments @('-NoProfile', '-Command', "Start-Sleep -Seconds 60 # $stallMarker") -TimeoutMilliseconds 2000 -Label 'stalled probe' | Out-Null
        }
        catch { $stalled = $_ }

        $watch.Stop()
        Assert-True ($null -ne $stalled) "a stalled invocation is refused"
        Assert-Contains ([string]$stalled.Exception.Message) "did not finish within" "the stall is named"
        Assert-Contains ([string]$stalled.Exception.Message) "terminated (exit confirmed" "confirmed termination is reported"
        Assert-True ($watch.Elapsed.TotalMilliseconds -lt 15000) "the stall was terminated within the budget (measured $([Math]::Round($watch.Elapsed.TotalMilliseconds)) ms)"

        $stalledPid = $null
        $pidMatch = [regex]::Match([string]$stalled.Exception.Message, 'pid=(\d+)')

        if ($pidMatch.Success) { $stalledPid = [int]$pidMatch.Groups[1].Value }

        if ($null -ne $stalledPid) {
            Assert-Equal $false ([bool](Get-Process -Id $stalledPid -ErrorAction SilentlyContinue)) "the actual launched child PID ($stalledPid) is no longer running"
        }

        # Timeout and termination failures THROW: they must never return a
        # success-shaped result object to the pipeline.
        $stalledPipeline = @()

        try { $stalledPipeline = @(Invoke-DevWSBoundedProcess -FilePath $pwsh -Arguments @('-NoProfile', '-Command', 'Start-Sleep -Seconds 60') -TimeoutMilliseconds 1500 -Label 'throw-shaped probe') } catch { }

        Assert-Equal 0 $stalledPipeline.Count "a timed-out invocation returns no object at all"

        $orphanGone = Wait-TestFixtureProcessesGone -Select {
            Get-CimInstance Win32_Process -Filter "Name = 'pwsh.exe'" | Where-Object { $_.CommandLine -like "*$stallMarker*" }
        }
        Assert-Equal $true $orphanGone.Gone "no process carrying the stalled child marker remains"
    }

    Test-Case "a descendant holding an inherited writer cannot delay the runner" {
        # The immediate child exits promptly, but its grandchild keeps an
        # inherited stdout/stderr writer open. The runner must return finitely
        # instead of waiting for EOF on those pipes.
        $pwsh = (Get-Process -Id $PID).Path
        $marker = "P2D-INHERIT-$([guid]::NewGuid().ToString('N').Substring(0, 8))"
        $fixtureDir = Join-Path $TestRoot "kickoff-inherit-$([guid]::NewGuid().ToString('N').Substring(0, 6))"
        New-Item -ItemType Directory -Path $fixtureDir -Force | Out-Null
        $fixtureCmd = Join-Path $fixtureDir 'hold-writer.cmd'

        @(
            '@echo off',
            "start `"`" `"$pwsh`" -NoProfile -Command `"Start-Sleep -Seconds 60 # $marker`"",
            'exit /b 0'
        ) | Set-Content -LiteralPath $fixtureCmd -Encoding ASCII

        try {
            $watch = [System.Diagnostics.Stopwatch]::StartNew()
            $result = Invoke-DevWSBoundedProcess -FilePath (Join-Path $env:SystemRoot 'System32\cmd.exe') -Arguments @('/c', $fixtureCmd) -TimeoutMilliseconds 15000 -Label 'inherited-writer probe'
            $watch.Stop()

            Assert-Equal 0 $result.ExitCode "the immediate child exit code is returned"
            Assert-True ($watch.Elapsed.TotalMilliseconds -lt 12000) "the runner returned finitely despite the inherited writer (measured $([Math]::Round($watch.Elapsed.TotalMilliseconds)) ms)"
        }
        finally {
            # The grandchild is a fixture artifact: terminate it by its unique
            # marker so the suite leaves no disposable process behind. A kill
            # request is not proof that Win32_Process already stopped reporting
            # it, so the absence check is a bounded condition wait instead of one
            # instantaneous snapshot.
            $holders = @(Get-CimInstance Win32_Process -Filter "Name = 'pwsh.exe'" | Where-Object { $_.CommandLine -like "*$marker*" })

            foreach ($holder in $holders) {
                Stop-Process -Id $holder.ProcessId -Force -ErrorAction SilentlyContinue
            }

            $gone = Wait-TestFixtureProcessesGone -Select {
                Get-CimInstance Win32_Process -Filter "Name = 'pwsh.exe'" | Where-Object { $_.CommandLine -like "*$marker*" }
            }

            Assert-Equal $true $gone.Gone ("the inherited-writer fixture grandchild was cleaned up (remaining: " + (@($gone.Remaining | ForEach-Object { $_.ProcessId }) -join ',') + ")")
        }
    }

    Test-Case "excessive diagnostic output is bounded and never blocks the caller" {
        # A child that floods both streams must not delay the runner or grow the
        # retained diagnostic beyond the configured ceiling.
        $pwsh = (Get-Process -Id $PID).Path
        $watch = [System.Diagnostics.Stopwatch]::StartNew()
        $result = Invoke-DevWSBoundedProcess -FilePath $pwsh -Arguments @('-NoProfile', '-Command', '[Console]::Out.Write(("x" * 200000)); [Console]::Error.Write(("y" * 200000)); exit 3') -TimeoutMilliseconds 20000 -OutputRetentionChars 2048 -Label 'flood probe'
        $watch.Stop()

        Assert-Equal 3 $result.ExitCode "the flooding child's exit code is returned"
        Assert-True ([string]$result.Detail.Length -le 2048) "retained diagnostics are capped (got $([string]$result.Detail.Length) chars)"
        Assert-True ($watch.Elapsed.TotalMilliseconds -lt 20000) "a flooding child never delays the caller (measured $([Math]::Round($watch.Elapsed.TotalMilliseconds)) ms)"
    }

    Test-Case "unconfirmed termination is reported honestly, never as terminated" {
        # Deterministic injection: a process double whose pre-timeout exit check
        # never becomes true and whose post-timeout waits never confirm an exit
        # simulates a failed/delayed termination, proving the runner refuses to
        # claim termination it did not observe.
        function New-DevWSBoundedProcessInstance {
            param([Parameter(Mandatory)][System.Diagnostics.ProcessStartInfo]$StartInfo)

            $double = [pscustomobject]@{ HasExited = $false; SessionId = 0 }
            $double | Add-Member -MemberType ScriptMethod -Name Start -Value { }
            $double | Add-Member -MemberType ScriptMethod -Name WaitForExit -Value { param($ms) return $false }
            $double | Add-Member -MemberType ScriptMethod -Name Kill -Value { param($tree) }
            $double | Add-Member -MemberType ScriptProperty -Name StandardOutput -Value { [System.IO.StreamReader]::new([System.IO.MemoryStream]::new()) }
            $double | Add-Member -MemberType ScriptProperty -Name StandardError -Value { [System.IO.StreamReader]::new([System.IO.MemoryStream]::new()) }
            $double | Add-Member -MemberType ScriptMethod -Name Dispose -Value { }

            return $double
        }

        $err = $null

        try {
            Invoke-DevWSBoundedProcess -FilePath (Get-Process -Id $PID).Path -Arguments @('-NoProfile', '-Command', 'exit 0') -TimeoutMilliseconds 500 -TerminationGraceMilliseconds 500 -Label 'unconfirmed probe' | Out-Null
        }
        catch { $err = $_ }

        Assert-True ($null -ne $err) "the unconfirmed-termination path surfaced"
        Assert-Contains ([string]$err.Exception.Message) "could not be confirmed" "the runner reports unconfirmed termination honestly"
        Assert-NotContains ([string]$err.Exception.Message) "was terminated (exit confirmed" "the unconfirmed path never claims confirmed termination"
    }

    Test-Case "kickoff failures are NotTransmitted and consume the operation deadline" {
        function Start-DevWSScheduledTask {
            param([string]$TaskName, [int]$TimeoutMilliseconds = 10000)
            throw "injected kickoff failure"
        }

        try {
            $watch = [System.Diagnostics.Stopwatch]::StartNew()
            $err = $null
            try { $null = Start-DevWSWorkerRequest -Kind "focus" -TaskName "DevWorkspace-ElevatedFocus" -Payload @{ setId = "main" } -TimeoutSeconds 7 } catch { $err = $_ }
            $watch.Stop()

            Assert-True ($null -ne $err) "the injected kickoff failure surfaced"
            Assert-Equal "NotTransmitted" (Get-DevWSWorkerErrorState -ErrorRecord $err) "a failed kick sends no request bytes"
            Assert-Contains ([string]$err.Exception.Message) "could not be started" "the kickoff failure is named"
            Assert-True ($watch.Elapsed.TotalSeconds -lt 5) "no connect or ACK wait ran after the kick failure"

            # Deadline accounting begins at the operation start: the handle's
            # deadline is anchored before the kick, so a bounded kick can never
            # extend the total budget.
            $protocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
            $deadlineIndex = $protocol.IndexOf('$deadline = [datetime]::UtcNow.AddSeconds')
            $kickIndex = $protocol.IndexOf('Start-DevWSScheduledTask -TaskName $boundTask')
            Assert-True ($deadlineIndex -ge 0 -and $kickIndex -gt $deadlineIndex) "the deadline is anchored before the kickoff"
        }
        finally { }
    }

