        $ownsBranch = $captureSource.Substring($ownsIndex, $rectIndex - $ownsIndex)
        Assert-Contains $ownsBranch '|MISSING' "locator-only race is classified MISSING"
        Assert-Contains $ownsBranch "continue" "locator-only race skips capture and state"
