            $workerSource = Get-SourceOf ("src\workers\" + $worker)
            Assert-NotContains $workerSource "AutomationElement" "$worker must not keep its own UIA enumeration"
        }
    }

    Test-Case "UIA recovery reuses the shared HWND association validator" {
        $lib = Get-SourceOf "src\lib\devws-identity.ps1"

        $start = $lib.IndexOf("function Get-DevWSTerminalHwnd")
        $end   = $lib.IndexOf("function Wait-DevWSTerminalHwnd")
        Assert-True ($start -ge 0 -and $end -gt $start) "UIA recovery function located"

        $region = $lib.Substring($start, $end - $start)
        Assert-Contains $region "Get-DevWSHwndCandidate" "recovery probes the HWND through the shared candidate builder"
        Assert-Contains $region "Select-DevWSTerminalHwndCandidate" "recovery uses the shared selector"
        Assert-Contains $region "-RequireProcess" "recovery requires a WindowsTerminal process"
    }

    Test-Case "created-tab guard counts raw TabItems, not unique names" {
        $uia = Get-SourceOf "src\lib\devws-uia.ps1"

        $start = $uia.IndexOf("function Get-DevWSTabElementsFromHwnd")
        $end   = $uia.IndexOf("function Wait-DevWSTabCountFromHwnd")
        Assert-True ($start -ge 0 -and $end -gt $start) "raw count helpers located"

        $region = $uia.Substring($start, $end - $start)
        Assert-Contains $region "TabItem" "raw helpers enumerate TabItems"
        Assert-NotContains $region "New-DevWSPresentTabNameSet" "raw counting must not build a deduplicated name set"

        $lib = Get-SourceOf "src\lib\devws-identity.ps1"
        $guardStart = $lib.IndexOf("function Test-DevWSCreatedTabCount")
        $guardEnd   = $lib.IndexOf("function Get-DevWSHwndCandidate")
        Assert-True ($guardStart -ge 0 -and $guardEnd -gt $guardStart) "guard function located"

        $guard = $lib.Substring($guardStart, $guardEnd - $guardStart)
        Assert-Contains $guard '$ActualCount' "guard takes the raw count"
        Assert-Contains $guard '$ConfiguredCount' "guard takes the configured count"
        Assert-NotContains $guard "TabNames" "guard must not take a deduplicated name set"
    }

    Write-Host ""
    Start-TestGroup -Name 'capture' -Title 'Capture handling'

    Test-Case "capture parser reads geometry and rejects bad lines" {
        $dir = Join-Path $TestRoot "capture"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $path = Join-Path $dir "capture.txt"

        Set-Content -LiteralPath $path -Value @("slot|-7|0|654|1407", "studio|1913|0|654|1407")
        $parsed = Read-DevWSCaptureFile -Path $path
        Assert-Equal 2 $parsed.Count "parsed entries"
        Assert-Equal -7 $parsed["slot"].x "x value"
        Assert-Equal 1407 $parsed["studio"].h "h value"

        Set-Content -LiteralPath $path -Value "slot|MISSING"
        Assert-Throws { Read-DevWSCaptureFile -Path $path } "was not found"

        Set-Content -LiteralPath $path -Value "slot|INVALID|1|1|1|1"
        Assert-Throws { Read-DevWSCaptureFile -Path $path } "invalid geometry"

        Set-Content -LiteralPath $path -Value "slot|1|2|3"
        Assert-Throws { Read-DevWSCaptureFile -Path $path } "Invalid geometry"

        Set-Content -LiteralPath $path -Value @("slot|1|2|3|4", "slot|5|6|7|8")
        Assert-Throws { Read-DevWSCaptureFile -Path $path } "Duplicate"
    }

    Test-Case "capture completeness fails on any missing required item" {
        $captured = @{ slot = [pscustomobject]@{ x = 0; y = 0; w = 1; h = 1 } }

        Assert-DevWSCaptureComplete -Captured $captured -RequiredIds @("slot") -SourceLabel "Terminal"

        Assert-Throws {
            Assert-DevWSCaptureComplete -Captured $captured -RequiredIds @("slot", "studio") -SourceLabel "Terminal"
        } "studio"
    }

    Write-Host ""
    Start-TestGroup -Name 'config-persistence' -Title 'Config persistence'

    Test-Case "config round-trips and updates layout by stable id" {
        $dir = Join-Path $TestRoot "save"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $target = Join-Path $dir "workspace.json"
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $target

        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target
        Assert-Equal "override" $location.Source "explicit override source"
        Assert-True $location.IsWritable "explicit override is writable"

        $config = Get-DevWSConfig -Location $location
        $slot   = Resolve-DevWSReference -Config $config -Reference "slot" -Type terminal
        Set-DevWSLayout -Item $slot -Rect ([pscustomobject]@{ x = -1; y = -2; w = 300; h = 400 })
        Save-DevWSConfig -Config $config -Location $location

        $reloaded = Get-DevWSConfig -Location $location
        $slot2    = Resolve-DevWSReference -Config $reloaded -Reference "SLOT" -Type terminal

        Assert-Equal -1 $slot2.layout.x "x persisted"
        Assert-Equal -2 $slot2.layout.y "y persisted"
        Assert-Equal 300 $slot2.layout.w "w persisted"
        Assert-Equal 400 $slot2.layout.h "h persisted"
        Assert-Equal 6 @($reloaded.sets[0].windows).Count "window count preserved"
        Assert-True (-not (Test-Path -LiteralPath "$target.tmp" -PathType Leaf)) "temp file cleaned up"
    }

    Test-Case "bundled default config can never be written" {
        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $BundledConfigPath
        Assert-True $location.IsBundledDefault "bundled default detected"
        Assert-True (-not $location.IsWritable) "bundled default is read-only"

        Assert-Throws {
            Save-DevWSConfig -Config (Get-TestWorkspaceConfig) -Location $location
        } "Refusing to modify"

        Assert-Throws {
            Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override (Join-Path $TestRoot "missing.json")
        } "does not exist"
    }

    Test-Case "DEVWS_CONFIG selects a writable user config" {
        $dir = Join-Path $TestRoot "envcfg"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $target = Join-Path $dir "workspace.json"
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $target

        $env:DEVWS_CONFIG = $target

        try {
            $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot
            Assert-Equal "env" $location.Source "env source"
            Assert-True $location.IsWritable "env target is writable"

            $override = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $WorkspaceFixturePath
            Assert-Equal "override" $override.Source "override beats env"
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        $env:DEVWS_CONFIG = Join-Path $dir "missing.json"

        try {
            Assert-Throws { Resolve-DevWSConfigLocation -StartPath $RepoRoot } "does not exist"
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }
    }

    Write-Host ""
    Start-TestGroup -Name 'config-precedence' -Title 'Config location precedence'

    Test-Case "canonical user config is preferred over the bundled default" {
        $homeDir   = Join-Path $TestRoot "precedence-home"
        $canonical = Join-Path $homeDir ".config\devws\workspace.json"
        New-Item -ItemType Directory -Path (Split-Path -Parent $canonical) -Force | Out-Null
        Set-Content -LiteralPath $canonical -Value '{"version": 3, "defaultSet": "main", "bindings": [], "sets": [{"id": "main", "windows": []}]}' -Encoding UTF8

        $root   = Join-Path $TestRoot "precedence-tree"
        $src    = Join-Path $root "src"
        $defDir = Join-Path $root "config"
        New-Item -ItemType Directory -Path $src, $defDir -Force | Out-Null
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination (Join-Path $defDir "workspace.default.json")

        $canonicalPath = $canonical
        $srcPath       = $src
        $savedEnv      = $env:DEVWS_CONFIG
        Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue

        try {
            # Substituting the canonical location isolates precedence from the
            # live %USERPROFILE%\.config\devws\workspace.json.
            $location = & {
                function Get-DevWSCanonicalConfigPath { return $canonicalPath }
                Resolve-DevWSConfigLocation -StartPath $srcPath
            }

            Assert-Equal "user" $location.Source "canonical user config wins over the bundled default"
            Assert-True $location.IsWritable "canonical config is writable"
            Assert-True (-not $location.IsBundledDefault) "not marked as the bundled default"
            Assert-True ($null -eq $location.Warning) "no warning for a writable user config"
            Assert-True ([string]::Equals($location.Path, (Resolve-Path -LiteralPath $canonical).Path, [StringComparison]::OrdinalIgnoreCase)) "canonical path selected"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv }
        }
    }

    Test-Case "bundled default is used when no canonical config exists" {
        $homeDir = Join-Path $TestRoot "fallback-home"

        $root   = Join-Path $TestRoot "fallback-tree"
        $src    = Join-Path $root "src"
        $defDir = Join-Path $root "config"
        New-Item -ItemType Directory -Path $src, $defDir -Force | Out-Null
        $bundled = Join-Path $defDir "workspace.default.json"
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $bundled

        $canonicalPath = Join-Path $homeDir ".config\devws\workspace.json"
        $srcPath       = $src
        $savedEnv      = $env:DEVWS_CONFIG
        Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue

        try {
            $location = & {
                function Get-DevWSCanonicalConfigPath { return $canonicalPath }
                Resolve-DevWSConfigLocation -StartPath $srcPath
            }

            Assert-Equal "default" $location.Source "bundled default fallback"
            Assert-True $location.IsBundledDefault "marked as the bundled default"
            Assert-True (-not $location.IsWritable) "bundled default is read-only"
            Assert-True ([string]::Equals($location.Path, (Resolve-Path -LiteralPath $bundled).Path, [StringComparison]::OrdinalIgnoreCase)) "bundled default path selected"
            Assert-Contains ([string]$location.Warning) "read-only" "warning explains the read-only default"

            # The fallback config is a complete, valid v2 config.
            $config = Get-DevWSConfig -Location $location
            Assert-Equal 6 @($config.sets[0].windows).Count "fallback config loads"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv }
        }
    }

    Write-Host ""
    Start-TestGroup -Name 'config-mutations' -Title 'Config mutations'

    Test-Case "add-terminal builds command + idle defaults" {
        $config = Get-TestWorkspaceConfig
        $resolved = Resolve-DevWSDirectoryPath -PathText $TestRoot
        $before = @($config.sets[0].windows).Count

        $item = Add-DevWSTerminal -Config $config -Id "agy" -Path $resolved -Command "agy" -Arguments @()

        Assert-Equal ($before + 1) @($config.sets[0].windows).Count "item appended"
        Assert-Equal "agy" $item.id "id"
        Assert-Equal "terminal" $item.type "type"
        Assert-Equal $true $item.enabled "enabled"
        Assert-Equal $true $item.elevated "elevated"
        Assert-Equal "DevWS-main-agy" $item.windowId "windowId"
        Assert-Equal $resolved $item.path "absolute path stored"
        Assert-Equal 0 $item.activeTab "activeTab"
        Assert-Equal 2 @($item.tabs).Count "command + idle tabs"
        Assert-Equal "agy" $item.tabs[0].command "command tab"
        Assert-Equal 0 @($item.tabs[0].args).Count "no args"
        Assert-True ($null -eq $item.tabs[1].command) "idle tab"
        Assert-DevWSConfig -Config $config -Source "test"
    }

    Test-Case "add-terminal idle-only default" {
        $config = Get-TestWorkspaceConfig
        $resolved = Resolve-DevWSDirectoryPath -PathText $TestRoot

        $item = Add-DevWSTerminal -Config $config -Id "idleterm" -Path $resolved -Command $null -Arguments @()

        Assert-Equal 1 @($item.tabs).Count "one idle tab"
        Assert-True ($null -eq $item.tabs[0].command) "idle tab"
    }

    Test-Case "add-terminal preserves arguments as an array" {
        $config = Get-TestWorkspaceConfig
        $resolved = Resolve-DevWSDirectoryPath -PathText $TestRoot

        $item = Add-DevWSTerminal -Config $config -Id "argterm" -Path $resolved -Command "somecmd" -Arguments @("--flag", "hello world", "")

        Assert-Equal 3 @($item.tabs[0].args).Count "arg count"
        Assert-Equal "--flag" $item.tabs[0].args[0] "first arg"
        Assert-Equal "hello world" $item.tabs[0].args[1] "spaced arg"
        Assert-Equal "" $item.tabs[0].args[2] "empty arg"
    }

    Test-Case "add-terminal copies the last terminal layout" {
        $config = Get-TestWorkspaceConfig
        $resolved = Resolve-DevWSDirectoryPath -PathText $TestRoot
        $terminals = @(Get-DevWSWindows -Config $config -Type terminal)
        $last = $terminals[$terminals.Count - 1]

        $before = @($config.sets[0].windows | ForEach-Object { "$($_.id):$($_.layout.x),$($_.layout.y),$($_.layout.w),$($_.layout.h)" })

        $item = Add-DevWSTerminal -Config $config -Id "layoutcopy" -Path $resolved -Command $null -Arguments @()

        Assert-Equal $last.layout.x $item.layout.x "x copied"
        Assert-Equal $last.layout.y $item.layout.y "y copied"
        Assert-Equal $last.layout.w $item.layout.w "w copied"
        Assert-Equal $last.layout.h $item.layout.h "h copied"

        $after = @($config.sets[0].windows | Where-Object { $_.id -ne "layoutcopy" } | ForEach-Object { "$($_.id):$($_.layout.x),$($_.layout.y),$($_.layout.w),$($_.layout.h)" })
        Assert-Equal ($before -join "|") ($after -join "|") "other layouts untouched"
    }

    Test-Case "add-terminal fallback layout with no terminals" {
        $config = Get-TestWorkspaceConfig
        $config.sets[0].windows = @($config.sets[0].windows | Where-Object { $_.type -eq "app" })
        $resolved = Resolve-DevWSDirectoryPath -PathText $TestRoot

        $item = Add-DevWSTerminal -Config $config -Id "firstterm" -Path $resolved -Command $null -Arguments @()

        Assert-Equal 0 $item.layout.x "fallback x"
        Assert-Equal 0 $item.layout.y "fallback y"
        Assert-Equal 654 $item.layout.w "fallback w"
        Assert-Equal 1407 $item.layout.h "fallback h"
    }

    Test-Case "add-terminal rejects duplicate ids and windowId collisions" {
        $config = Get-TestWorkspaceConfig
        $resolved = Resolve-DevWSDirectoryPath -PathText $TestRoot
        $before = @($config.sets[0].windows).Count

        Assert-Throws {
            Add-DevWSTerminal -Config $config -Id "SLOT" -Path $resolved -Command $null -Arguments @()
        } "already exists"
        Assert-Equal $before @($config.sets[0].windows).Count "duplicate id did not mutate"

        ($config.sets[0].windows | Where-Object { $_.id -eq "studio" }).windowId = "DevWS-main-newone"
        Assert-Throws {
            Add-DevWSTerminal -Config $config -Id "newone" -Path $resolved -Command $null -Arguments @()
        } "collides"
        Assert-Equal $before @($config.sets[0].windows).Count "windowId collision did not mutate"
    }

    Test-Case "add-terminal id rules are conservative" {
        $config = Get-TestWorkspaceConfig

        foreach ($badId in @("", "bad id", "bad/id", "bad|id")) {
            Assert-Throws { Assert-DevWSNewItemId -Config $config -Id $badId } "id"
        }

        Assert-Throws { Assert-DevWSNewItemId -Config $config -Id "bad`nid" } "newline"

        Assert-Equal "DevWS-main-ok.id_1-2" (Assert-DevWSNewTerminalId -Config $config -Id "ok.id_1-2") "allowed id"
        Assert-Equal "DevWS-main-2" (Assert-DevWSNewTerminalId -Config $config -Id "2") "digit-only id allowed"
    }

    Test-Case "app ids are independent of terminal windowIds" {
        # Terminal rename preserves windowId, so 'slot' can be a free global
        # id while the old named-window identity still exists.
        $terminalConfig = Get-TestWorkspaceConfig
        [void](Rename-DevWSItem -Config $terminalConfig -Reference "slot" -NewId "backend" -CommandName "ws rename")
        Assert-Equal "DevWS-slot" @($terminalConfig.sets[0].windows | Where-Object { $_.id -eq "backend" })[0].windowId "windowId preserved by rename"

        # Terminal creation must still refuse the generated-windowId collision.
        # New terminals in main are generated as DevWS-main-<id>; force that
        # identity to already exist under the renamed terminal.
        @($terminalConfig.sets[0].windows | Where-Object { $_.id -eq "backend" })[0].windowId = "DevWS-main-slot"

        Assert-Throws {
            Add-DevWSTerminal -Config $terminalConfig -Id "slot" -Path $TestRoot -Command $null -Arguments @()
        } "collides"
        Assert-Throws {
            Clone-DevWSTerminal -Config $terminalConfig -SourceId "scratch" -NewId "slot" -CommandName "ws clone-terminal"
        } "collides"
        Assert-Equal 6 @($terminalConfig.sets[0].windows).Count "failed terminal creations did not mutate"

        # Apps never own a terminal windowId, so the same id is allowed.
        $appConfig = Get-TestWorkspaceConfig
        [void](Rename-DevWSItem -Config $appConfig -Reference "slot" -NewId "backend" -CommandName "ws rename")

        $added = Add-DevWSApp `
            -Config $appConfig `
            -Id "slot" `
            -LaunchKind "exe" `
            -LaunchValue "C:\Some\App.exe" `
            -MatchKind "exe" `
            -MatchValue "App.exe" `
            -InstanceMode "dedicated"

        Assert-Equal "slot" $added.id "app id allowed"
        Assert-Equal "app" $added.type "created as an app"
        Assert-True (-not (Test-DevWSProperty -Object $added -Name "windowId")) "app carries no terminal windowId"
        Assert-Equal 7 @($appConfig.sets[0].windows).Count "app appended"
        Assert-DevWSConfig -Config $appConfig -Source "test"

        # Cloning an app under the same freed id is allowed as well.
        $cloneConfig = Get-TestWorkspaceConfig
        [void](Rename-DevWSItem -Config $cloneConfig -Reference "slot" -NewId "backend" -CommandName "ws rename")

        $cloned = Clone-DevWSApp -Config $cloneConfig -SourceId "firefox" -NewId "slot" -CommandName "ws clone-app"

        Assert-Equal "slot" $cloned.Clone.id "clone id allowed"
        Assert-Equal "app" $cloned.Clone.type "clone is an app"
        Assert-Equal $false $cloned.Clone.enabled "clone starts disabled"
        Assert-True (-not (Test-DevWSProperty -Object $cloned.Clone -Name "windowId")) "clone carries no terminal windowId"
        Assert-DevWSConfig -Config $cloneConfig -Source "test"
    }

    Test-Case "enable and disable mutate flags idempotently" {
        $config = Get-TestWorkspaceConfig

        $disable = Set-DevWSItemEnabled -Config $config -Reference "ANTIGRAVITY" -Enabled $false -CommandName "ws disable"
        Assert-True $disable.Changed "app disabled"
        Assert-Equal $false $disable.Item.enabled "flag false"

        $again = Set-DevWSItemEnabled -Config $config -Reference "antigravity" -Enabled $false -CommandName "ws disable"
        Assert-True (-not $again.Changed) "idempotent disable"

        $enable = Set-DevWSItemEnabled -Config $config -Reference "slot" -Enabled $true -CommandName "ws enable"
        Assert-True (-not $enable.Changed) "already-enabled terminal"

        $offTerminal = Set-DevWSItemEnabled -Config $config -Reference "studio" -Enabled $false -CommandName "ws disable"
        Assert-True $offTerminal.Changed "terminal disabled"
    }

