    Test-Case "set-command replaces or converts the first tab" {
        $config = Get-TestWorkspaceConfig

        $slot = Resolve-DevWSTerminalById -Config $config -Reference "slot" -CommandName "ws set-command"
        [void](Set-DevWSTerminalCommand -Config $config -Terminal $slot -CommandText "agy" -Arguments @("--model", "foo"))

