        } "already exists"
        Assert-Throws {
            Add-DevWSApp -Config $config -Id "slot" -LaunchKind "exe" -LaunchValue "C:\a.exe" -MatchKind "exe" -MatchValue "a.exe" -InstanceMode "dedicated"
        } "already exists"
        Assert-Throws {
            Add-DevWSApp -Config $config -Id "2" -LaunchKind "exe" -LaunchValue "C:\a.exe" -MatchKind "exe" -MatchValue "a.exe" -InstanceMode "dedicated"
        } "must not be numeric"
        Assert-Throws {
            Add-DevWSApp -Config $config -Id "bad id" -LaunchKind "exe" -LaunchValue "C:\a.exe" -MatchKind "exe" -MatchValue "a.exe" -InstanceMode "dedicated"
        } "may only contain"
        Assert-Throws {
            Add-DevWSApp -Config $config -Id "okapp" -LaunchKind "bogus" -LaunchValue "C:\a.exe" -MatchKind "exe" -MatchValue "a.exe" -InstanceMode "dedicated"
        } "Unsupported launch kind"
