        } "match value is required"
        Assert-Throws {
            Add-DevWSApp -Config $config -Id "okapp" -LaunchKind "exe" -LaunchValue "C:\a.exe" -MatchKind "exe" -MatchValue "a.exe" -InstanceMode "sometimes"
        } "Unknown instance mode"
        Assert-Throws {
            Add-DevWSApp -Config $config -Id "okapp" -LaunchKind "exe" -LaunchValue "C:\a.exe" -MatchKind "exe" -MatchValue "a.exe" -InstanceMode ""
        } "instance mode is required"

