    Test-Case "rename validates new ids without numeric alias semantics" {
        $config = Get-TestWorkspaceConfig

        Assert-Throws {
            Rename-DevWSItem -Config $config -Reference "firefox" -NewId "slot" -CommandName "ws rename"
        } "already exists"
        Assert-Throws {
            Rename-DevWSItem -Config $config -Reference "firefox" -NewId "SLOT" -CommandName "ws rename"
        } "already exists"
        Assert-Throws {
            Rename-DevWSItem -Config $config -Reference "firefox" -NewId "bad id" -CommandName "ws rename"
        } "may only contain"
        Assert-Throws {
            Rename-DevWSItem -Config $config -Reference "firefox" -NewId "" -CommandName "ws rename"
        } "non-empty item id"
        Assert-Throws {
            Rename-DevWSItem -Config $config -Reference "firefox" -NewId "5" -CommandName "ws rename"
        } "must not be numeric"

        # Numeric source text is never resolved positionally.
        Assert-Throws {
            Rename-DevWSItem -Config $config -Reference "9" -NewId "other" -CommandName "ws rename"
        } "numeric aliases"

        # Case-only rename changes only casing and never duplicates the item.
        [void](Rename-DevWSItem -Config $config -Reference "firefox" -NewId "Firefox" -CommandName "ws rename")
        Assert-Equal 1 @($config.sets[0].windows | Where-Object { $_.id -ceq "Firefox" }).Count "case-only rename applied"
        Assert-Equal 6 @($config.sets[0].windows).Count "case-only rename did not duplicate"
        Assert-DevWSConfig -Config $config -Source "test"

        # Terminal ids may remain digit-only and resolve by exact configured id.
        $other = Get-TestWorkspaceConfig
        [void](Rename-DevWSItem -Config $other -Reference "studio" -NewId "2" -CommandName "ws rename")
        Assert-Equal "2" (Resolve-DevWSItemById -Config $other -Reference "2").id "digit-only terminal id resolves exactly"
        Assert-Equal "DevWS-studio" @($other.sets[0].windows | Where-Object { $_.id -eq "2" })[0].windowId "digit-only rename still preserved windowId"
    }

    Test-Case "rename never modifies runtime state" {
        $statePath = Get-DevWSStatePath
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 424242
        Save-DevWSRuntimeState -State $state -Path $statePath
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))

        $config = Get-TestWorkspaceConfig
        [void](Rename-DevWSItem -Config $config -Reference "slot" -NewId "backend" -CommandName "ws rename")

        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))) "runtime state bytes unchanged"
        $reloaded = Read-DevWSRuntimeState -Path $statePath
        Assert-True ($null -ne (Get-DevWSRuntimeTerminal -State $reloaded -SetId "main" -Id "slot")) "old-id cache entry remains untouched"
        Assert-True ($null -eq (Get-DevWSRuntimeTerminal -State $reloaded -SetId "main" -Id "backend")) "no runtime state is migrated to the new id"

        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
    }

    Test-Case "clone-terminal deep-copies definitions with a fresh windowId" {
        $config = Get-TestWorkspaceConfig
        $slot = Resolve-DevWSTerminalById -Config $config -Reference "slot" -CommandName "ws clone-terminal"
        $slot.tabs = @(
            [pscustomobject][ordered]@{ command = "one"; args = @("a") },
            [pscustomobject][ordered]@{ command = $null; args = @() },
            [pscustomobject][ordered]@{ command = "three"; args = @("x y", "z") },
            [pscustomobject][ordered]@{ command = $null; args = @() }
        )
        $slot.activeTab = 2
        $slot.enabled = $false
        $slot.elevated = $false

        $result = Clone-DevWSTerminal -Config $config -SourceId "slot" -NewId "backend" -CommandName "ws clone-terminal"
        $clone = $result.Clone

        Assert-Equal "slot" $result.SourceId "source id reported"
        Assert-Equal "backend" $clone.id "new id"
        Assert-Equal "terminal" $clone.type "type"
        Assert-Equal $false $clone.enabled "enabled copied"
        Assert-Equal $false $clone.elevated "elevated copied"
        Assert-Equal "DevWS-main-backend" $clone.windowId "fresh generated windowId"
        Assert-Equal $slot.path $clone.path "path copied"
        Assert-Equal 2 $clone.activeTab "activeTab copied"
        Assert-Equal 4 @($clone.tabs).Count "arbitrary tab count copied"
        Assert-Equal "one" $clone.tabs[0].command "first command copied"
        Assert-Equal "a" (@($clone.tabs[0].args) -join ",") "first args copied"
        Assert-True ($null -eq $clone.tabs[1].command) "second tab copied"
        Assert-Equal "three" $clone.tabs[2].command "third command copied"
        Assert-Equal "x y,z" (@($clone.tabs[2].args) -join ",") "args with spaces copied exactly"
        Assert-True ($null -eq $clone.tabs[3].command) "fourth tab copied"
        Assert-Equal "$($slot.layout.x),$($slot.layout.y),$($slot.layout.w),$($slot.layout.h)" "$($clone.layout.x),$($clone.layout.y),$($clone.layout.w),$($clone.layout.h)" "layout copied"
        Assert-Equal 7 @($config.sets[0].windows).Count "clone appended"
        Assert-DevWSConfig -Config $config -Source "test"

        # Deep copy: mutating the clone must not mutate the source.
        $clone.layout.x = 999
        $clone.tabs[0].command = "changed"
        $clone.tabs[0].args[0] = "changed"
        $clone.tabs[2].args[0] = "changed"
        Assert-Equal -7 $slot.layout.x "source layout untouched"
        Assert-Equal "one" $slot.tabs[0].command "source command untouched"
        Assert-Equal "a" $slot.tabs[0].args[0] "source args untouched"
        Assert-Equal "x y" $slot.tabs[2].args[0] "source spaced args untouched"
    }

