    Test-Case "clone-app deep-copies and always starts disabled" {
        $config = Get-TestWorkspaceConfig
        $firefox = Resolve-DevWSAppById -Config $config -Reference "firefox" -CommandName "ws clone-app"
        $firefox.launch.args = @("--private-window", "C:\My Files\profile")
        $sourceMatch  = "$($firefox.match.kind)|$($firefox.match.value)"
        $sourceLaunch = "$($firefox.launch.kind)|$($firefox.launch.value)|$(@($firefox.launch.args) -join ',')"
        $sourceLayout = "$($firefox.layout.x),$($firefox.layout.y),$($firefox.layout.w),$($firefox.layout.h)"

        $result = Clone-DevWSApp -Config $config -SourceId "firefox" -NewId "firefox-dev" -CommandName "ws clone-app"
        $clone = $result.Clone

        Assert-Equal "firefox" $result.SourceId "source id reported"
        Assert-Equal "firefox-dev" $clone.id "new id"
        Assert-Equal "app" $clone.type "type"
        Assert-Equal "dedicated" $clone.instanceMode "clone-app is always an explicit dedicated template"
        Assert-Equal $false $clone.enabled "clone is disabled even though the source is enabled"
        Assert-Equal $true $firefox.enabled "source enabled state unchanged"
        Assert-Equal "exe" $clone.match.kind "match kind copied"
        Assert-Equal "firefox.exe" $clone.match.value "match value copied"
        Assert-Equal "exe" $clone.launch.kind "launch kind copied"
        Assert-Equal $firefox.launch.value $clone.launch.value "launch value copied"
        Assert-Equal 2 @($clone.launch.args).Count "args copied"
        Assert-Equal "--private-window" $clone.launch.args[0] "first arg copied"
        Assert-Equal "C:\My Files\profile" $clone.launch.args[1] "spaced arg copied"
        Assert-Equal $sourceLayout "$($clone.layout.x),$($clone.layout.y),$($clone.layout.w),$($clone.layout.h)" "layout copied"
        Assert-Equal 7 @($config.sets[0].windows).Count "clone appended"
        Assert-DevWSConfig -Config $config -Source "test"

        # Deep copy: mutating the clone must not mutate the source.
        $clone.match.value = "changed.exe"
        $clone.launch.kind = "appId"
        $clone.launch.value = "changed!App"
        $clone.launch.args[0] = "changed"
        $clone.layout.y = 999
        Assert-Equal $sourceMatch "$($firefox.match.kind)|$($firefox.match.value)" "source match untouched"
        Assert-Equal $sourceLaunch "$($firefox.launch.kind)|$($firefox.launch.value)|$(@($firefox.launch.args) -join ',')" "source launch untouched"
        Assert-Equal $sourceLayout "$($firefox.layout.x),$($firefox.layout.y),$($firefox.layout.w),$($firefox.layout.h)" "source layout untouched"

        # A shared source still produces an explicit dedicated clone.
        $sharedConfig = Get-TestWorkspaceConfig
        $sharedSource = Resolve-DevWSAppById -Config $sharedConfig -Reference "firefox" -CommandName "ws clone-app"
        $sharedSource.instanceMode = "shared"
        $sharedClone = Clone-DevWSApp -Config $sharedConfig -SourceId "firefox" -NewId "firefox-copy" -CommandName "ws clone-app"
        Assert-Equal "dedicated" $sharedClone.Clone.instanceMode "shared source still yields an explicit dedicated clone"
        Assert-Equal $false $sharedClone.Clone.enabled "shared-source clone stays disabled"
    }

