        Assert-Equal "staging" $result.Clone.id "new set id"
        Assert-Equal "main" $config.defaultSet "default unchanged"
        Assert-Equal 2 @(Get-DevWSSets -Config $config).Count "set appended"
        Assert-Equal "main,staging" (@(Get-DevWSSets -Config $config).id -join ",") "sets stay ordered"

        $cloneWindows = @($result.Clone.windows)
