        Assert-Equal $false $cloneFirefox.enabled "disabled app state preserved"
        Assert-Equal "--profile,dev work" (@($cloneFirefox.launch.args) -join ",") "app args preserved"
        Assert-Equal 111 $cloneFirefox.layout.x "app layout preserved"
        Assert-Equal "firefox.exe" $cloneFirefox.match.value "app match preserved"
        Assert-Equal "dedicated" $cloneFirefox.instanceMode "explicit dedicated mode preserved through clone-set"

        $cloneCodex = @($cloneWindows | Where-Object { $_.id -eq "codex" })[0]
        Assert-Equal "appId" $cloneCodex.launch.kind "appId launch preserved"
        Assert-Equal "processPathContains" $cloneCodex.match.kind "match kind preserved"
        Assert-Equal "shared" $cloneCodex.instanceMode "explicit shared mode preserved through clone-set"

        $cloneAntigravity = @($cloneWindows | Where-Object { $_.id -eq "antigravity" })[0]
        Assert-Equal "shared" $cloneAntigravity.instanceMode "third explicit mode preserved through clone-set"

        # Source terminal windowIds are never copied into the clone.
        $sourceWindowIds = @($source.windows | Where-Object { $_.type -eq "terminal" } | ForEach-Object { $_.windowId })

        foreach ($cloneWindowId in @($cloneWindows | Where-Object { $_.type -eq "terminal" } | ForEach-Object { $_.windowId })) {
            Assert-True ($sourceWindowIds -notcontains $cloneWindowId) "clone windowId is not copied: $cloneWindowId"
        }

        Assert-Equal $sourceBefore (ConvertTo-Json -InputObject @($source.windows) -Depth 20) "source set unchanged"
        Assert-Equal $bindingsBefore (ConvertTo-Json -InputObject @($config.bindings) -Depth 20) "bindings unchanged"

        # Deep copy in memory: mutating the clone must not touch the source.
        $cloneSlot.tabs[0].command = "changed"
        $cloneSlot.tabs[0].args[0] = "changed"
        $cloneSlot.layout.x = 999
        $cloneFirefox.launch.args[0] = "changed"
        $cloneFirefox.match.value = "changed.exe"

        Assert-Equal "build" $slot.tabs[0].command "source command untouched"
        Assert-Equal "--fast" $slot.tabs[0].args[0] "source args untouched"
        Assert-Equal -7 $slot.layout.x "source layout untouched"
        Assert-Equal "--profile" $firefox.launch.args[0] "source app args untouched"
        Assert-Equal "firefox.exe" $firefox.match.value "source match untouched"
    }

