    Test-Case "terminal rename recovers identity through UIA without state migration" {
        # Pure simulation: the old id keeps its cached entry, the new id has no
        # entry, and windowId is the identity the non-creating fallback uses.
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 12345

        $config = Get-TestWorkspaceConfig
        $result = Rename-DevWSItem -Config $config -Reference "slot" -NewId "backend" -CommandName "ws rename"

        Assert-Equal "DevWS-slot" $result.Item.windowId "renamed terminal preserved its named-window identity"
        Assert-True ($null -ne (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot")) "old-id cache entry remains"
        Assert-True ($null -eq (Get-DevWSRuntimeTerminal -State $state -SetId "main" -Id "backend")) "new id has no cached entry after rename"
        Assert-Equal 1 @($state.terminals.Keys).Count "rename did not add or remove state entries"

        # Composition proof: identity resolution checks set-scoped runtime state
        # first, then falls back to non-creating UI Automation by windowId, and
        # the lifecycle workers refresh state under the current scoped id after
        # a non-state resolution. No GUI automation is executed here.
        $identity = Get-SourceOf "src\lib\devws-identity.ps1"
        $resolveStart = $identity.IndexOf("function Resolve-DevWSTerminalHwnd")
        Assert-True ($resolveStart -ge 0) "identity resolver located"

        $resolver    = $identity.Substring($resolveStart)
        $stateLookup = $resolver.IndexOf('Get-DevWSRuntimeTerminal -State $State -SetId $SetId -Id $TerminalId')
        $uiaLookup   = $resolver.IndexOf('Get-DevWSTerminalHwnd -WindowId $WindowId')
        Assert-True ($stateLookup -ge 0) "identity resolution validates cached state by set + terminal id"
        Assert-True ($uiaLookup -gt $stateLookup) "identity resolution falls back to UIA by windowId"

        $captureCore = Get-SourceOf "src\lib\devws-terminal-operations.ps1"
        Assert-Contains $captureCore 'Resolve-DevWSTerminalHwnd -WindowId $windowId -SetId $SetId -State $State -TerminalId $terminalId' "capture core resolves with the set-scoped config id and windowId"
        Assert-Contains $captureCore 'if ($identity.Source -ne "state")' "capture core refreshes state only after non-state recovery"
        Assert-Contains $captureCore 'Update-DevWSRuntimeTerminal -SetId $SetId -Id $terminalId -WindowId $windowId' "capture core writes runtime state under the current scoped id"
    }

    Test-Case "set-geometry updates only the saved layout rectangle" {
        $config = Get-TestWorkspaceConfig
        $firefox = Resolve-DevWSAppById -Config $config -Reference "firefox" -CommandName "ws set-geometry"
        $appBefore = ConvertTo-Json -InputObject ([pscustomobject][ordered]@{
            enabled = $firefox.enabled
            match   = $firefox.match
            launch  = $firefox.launch
        }) -Depth 10

        [void](Set-DevWSItemGeometry -Config $config -Item $firefox -X -5 -Y -10 -W 1294 -H 1407)

        Assert-Equal -5 $firefox.layout.x "negative x accepted"
        Assert-Equal -10 $firefox.layout.y "negative y accepted"
        Assert-Equal 1294 $firefox.layout.w "w stored"
        Assert-Equal 1407 $firefox.layout.h "h stored"
        Assert-Equal $appBefore (ConvertTo-Json -InputObject ([pscustomobject][ordered]@{
            enabled = $firefox.enabled
            match   = $firefox.match
            launch  = $firefox.launch
        }) -Depth 10) "non-layout app fields untouched"
        Assert-DevWSConfig -Config $config -Source "test"

        $slot = Resolve-DevWSTerminalById -Config $config -Reference "slot" -CommandName "ws set-geometry"
        $tabsBefore = ConvertTo-Json -InputObject @($slot.tabs) -Depth 10

        [void](Set-DevWSItemGeometry -Config $config -Item $slot -X 0 -Y 0 -W 1 -H 1)

        Assert-Equal 0 $slot.layout.x "zero x accepted"
        Assert-Equal 0 $slot.layout.y "zero y accepted"
        Assert-Equal 1 $slot.layout.w "width 1 accepted"
        Assert-Equal 1 $slot.layout.h "height 1 accepted"
        Assert-Equal $tabsBefore (ConvertTo-Json -InputObject @($slot.tabs) -Depth 10) "terminal tabs untouched"

        Assert-Throws {
            Set-DevWSItemGeometry -Config $config -Item $slot -X 0 -Y 0 -W 0 -H 100
        } "Width must be greater than 0"
        Assert-Throws {
            Set-DevWSItemGeometry -Config $config -Item $slot -X 0 -Y 0 -W -3 -H 100
        } "Width must be greater than 0"
        Assert-Throws {
            Set-DevWSItemGeometry -Config $config -Item $slot -X 0 -Y 0 -W 100 -H 0
        } "Height must be greater than 0"
        Assert-Throws {
            Set-DevWSItemGeometry -Config $config -Item $slot -X 0 -Y 0 -W 100 -H -1
        } "Height must be greater than 0"
        Assert-Equal 1 $slot.layout.w "failed geometry did not mutate"
    }

    Test-Case "geometry parsing accepts canonical, short, and reordered switches" {
        $canonical = ConvertFrom-DevWSGeometryArguments -Parts @("--x", "-7", "--y", "0", "--width", "654", "--height", "1407") -CommandName "ws set-geometry"
        Assert-Equal -7 $canonical.x "negative x"
        Assert-Equal 0 $canonical.y "zero y"
        Assert-Equal 654 $canonical.w "width"
        Assert-Equal 1407 $canonical.h "height"

        $short = ConvertFrom-DevWSGeometryArguments -Parts @("-x", "-7", "-y", "0", "-width", "654", "-height", "1407") -CommandName "ws set-geometry"
        Assert-Equal -7 $short.x "single-dash x"
        Assert-Equal 654 $short.w "single-dash width"
        Assert-Equal 1407 $short.h "single-dash height"

        $reordered = ConvertFrom-DevWSGeometryArguments -Parts @("--height", "1", "--width", "1", "--y", "-3", "--x", "0") -CommandName "ws set-geometry"
        Assert-Equal 0 $reordered.x "reordered x"
        Assert-Equal -3 $reordered.y "reordered negative y"
        Assert-Equal 1 $reordered.w "width 1 accepted"
        Assert-Equal 1 $reordered.h "height 1 accepted"
    }

    Test-Case "geometry parsing rejects malformed arguments" {
        $cases = @(
            @{ Name = "missing height";  Syntax = @("--x", "0", "--y", "0", "--width", "100"); Error = "Usage: ws set-geometry" },
            @{ Name = "duplicate x";     Syntax = @("--x", "0", "--x", "1", "--y", "0", "--width", "100", "--height", "100"); Error = "Duplicate switch" },
            @{ Name = "duplicate width"; Syntax = @("--x", "0", "--y", "0", "--width", "1", "--width", "2", "--height", "100"); Error = "Duplicate switch" },
            @{ Name = "unknown switch";  Syntax = @("--z", "0", "--x", "0", "--y", "0", "--width", "100", "--height", "100"); Error = "Unknown switch" },
            @{ Name = "non-integer";     Syntax = @("--x", "nope", "--y", "0", "--width", "100", "--height", "100"); Error = "requires an integer value" },
            @{ Name = "decimal";         Syntax = @("--x", "1.5", "--y", "0", "--width", "100", "--height", "100"); Error = "requires an integer value" },
            @{ Name = "decimal form";    Syntax = @("--x", "3.0", "--y", "0", "--width", "100", "--height", "100"); Error = "requires an integer value" },
            @{ Name = "missing value";   Syntax = @("--x"); Error = "requires an integer value" },
            @{ Name = "stray positional"; Syntax = @("0", "0", "100", "100"); Error = "expects" },
            @{ Name = "width zero";      Syntax = @("--x", "0", "--y", "0", "--width", "0", "--height", "100"); Error = "Width must be greater than 0" },
            @{ Name = "width negative";  Syntax = @("--x", "0", "--y", "0", "--width", "-5", "--height", "100"); Error = "Width must be greater than 0" },
            @{ Name = "height zero";     Syntax = @("--x", "0", "--y", "0", "--width", "100", "--height", "0"); Error = "Height must be greater than 0" },
            @{ Name = "height negative"; Syntax = @("--x", "0", "--y", "0", "--width", "100", "--height", "-1"); Error = "Height must be greater than 0" },
            @{ Name = "old -w switch";   Syntax = @("--x", "0", "--y", "0", "-w", "100", "--height", "100"); Error = "Unknown switch" },
            @{ Name = "old --w switch";  Syntax = @("--x", "0", "--y", "0", "--w", "100", "--height", "100"); Error = "Unknown switch" },
            @{ Name = "old -h switch";   Syntax = @("--x", "0", "--y", "0", "--width", "100", "-h", "100"); Error = "Unknown switch" },
            @{ Name = "old --h switch";  Syntax = @("--x", "0", "--y", "0", "--width", "100", "--h", "100"); Error = "Unknown switch" }
        )

        foreach ($case in $cases) {
            Assert-Throws {
                ConvertFrom-DevWSGeometryArguments -Parts $case.Syntax -CommandName "ws set-geometry"
            } $case.Error "$($case.Name) rejected"
        }

        Assert-Throws {
            ConvertFrom-DevWSGeometryArguments -Parts @() -CommandName "ws set-geometry"
        } "Usage: ws set-geometry"
    }

    Test-Case "reset-layout matches by id and windowId and preserves non-layout state" {
        $default = Get-TestWorkspaceConfig
        $config = Get-TestWorkspaceConfig
        $defaultBefore = ConvertTo-Json -InputObject @($default.sets[0].windows) -Depth 10

        # Renamed terminal keeps its windowId -> windowId fallback match.
        [void](Rename-DevWSItem -Config $config -Reference "slot" -NewId "backend" -CommandName "ws rename")
        # Disabled items are still reset.
        [void](Set-DevWSItemEnabled -Config $config -Reference "studio" -Enabled $false -CommandName "ws disable")
        # Cloned terminal with a fresh windowId -> skipped.
        [void](Clone-DevWSTerminal -Config $config -SourceId "scratch" -NewId "customcopy" -CommandName "ws clone-terminal")
        # Renamed app (apps never use windowId fallback) -> skipped.
        [void](Rename-DevWSItem -Config $config -Reference "codex" -NewId "assistant" -CommandName "ws rename")
        # Newly added app -> skipped.
        [void](Add-DevWSApp -Config $config -Id "spotify" -LaunchKind "exe" -LaunchValue "C:\spotify.exe" -MatchKind "exe" -MatchValue "spotify.exe" -InstanceMode "dedicated")
        # Case-insensitive id match.
        ($config.sets[0].windows | Where-Object { $_.id -eq "firefox" }).id = "FireFox"
        # Removed bundled item must not be re-added.
        [void](Remove-DevWSItem -Config $config -Reference "antigravity" -CommandName "ws remove")

        foreach ($item in @($config.sets[0].windows)) {
            Set-DevWSLayout -Item $item -Rect ([pscustomobject]@{ x = 900; y = 901; w = 902; h = 903 })
        }

        $idsBefore       = @($config.sets[0].windows | ForEach-Object { $_.id }) -join ","
        $nonLayoutBefore = ConvertTo-Json -InputObject @($config.sets[0].windows | ForEach-Object {
            [pscustomobject][ordered]@{
                id = $_.id; type = $_.type; enabled = $_.enabled
                windowId = $_.windowId; path = $_.path; elevated = $_.elevated
                tabs = $_.tabs; activeTab = $_.activeTab; match = $_.match; launch = $_.launch
            }
        }) -Depth 10

        $result = Reset-DevWSLayoutsFromDefault -Config $config -DefaultConfig $default -DefaultSource "test default"

        $matched      = @($result.Matches)
        $skippedItems = @($result.Skipped)

        Assert-Equal 4 $matched.Count "matched by id and windowId"
        Assert-Equal 3 $skippedItems.Count "unmatched items skipped"
        Assert-Equal "backend,studio,scratch,FireFox" (@($matched | ForEach-Object { $_.Item.id }) -join ",") "match order follows config order"
        Assert-Equal "assistant,customcopy,spotify" (@($skippedItems | ForEach-Object { $_.id }) -join ",") "skipped items reported"
        Assert-Equal 7 @($config.sets[0].windows).Count "no items added or removed"
        Assert-Equal $idsBefore (@($config.sets[0].windows | ForEach-Object { $_.id }) -join ",") "item order unchanged"

        $backendMatch = @($matched | Where-Object { $_.Item.id -eq "backend" })[0]
        Assert-Equal "windowId" $backendMatch.MatchedBy "renamed terminal matched via preserved windowId"
        Assert-Equal "DevWS-slot" $backendMatch.Item.windowId "windowId preserved"
        Assert-Equal "slot" $backendMatch.Default.id "fallback resolved to the bundled slot definition"

        $byId = @{}
        foreach ($item in @($config.sets[0].windows)) { $byId[$item.id] = $item }

        $defaultById = @{}
        foreach ($item in @($default.sets[0].windows)) { $defaultById[$item.id] = $item }

        foreach ($pair in @(
            @{ Config = "backend"; Default = "slot" },
            @{ Config = "studio"; Default = "studio" },
            @{ Config = "scratch"; Default = "scratch" },
            @{ Config = "FireFox"; Default = "firefox" }
        )) {
            $actual   = "$($byId[$pair.Config].layout.x),$($byId[$pair.Config].layout.y),$($byId[$pair.Config].layout.w),$($byId[$pair.Config].layout.h)"
            $expected = "$($defaultById[$pair.Default].layout.x),$($defaultById[$pair.Default].layout.y),$($defaultById[$pair.Default].layout.w),$($defaultById[$pair.Default].layout.h)"
            Assert-Equal $expected $actual "layout restored for $($pair.Config)"
        }

        Assert-Equal "900,901,902,903" "$($byId['assistant'].layout.x),$($byId['assistant'].layout.y),$($byId['assistant'].layout.w),$($byId['assistant'].layout.h)" "renamed app layout untouched"
        Assert-Equal "900,901,902,903" "$($byId['customcopy'].layout.x),$($byId['customcopy'].layout.y),$($byId['customcopy'].layout.w),$($byId['customcopy'].layout.h)" "clone layout untouched"
        Assert-Equal "900,901,902,903" "$($byId['spotify'].layout.x),$($byId['spotify'].layout.y),$($byId['spotify'].layout.w),$($byId['spotify'].layout.h)" "custom app layout untouched"
        Assert-Equal $false $byId["studio"].enabled "disabled matching item still included"

        $nonLayoutAfter = ConvertTo-Json -InputObject @($config.sets[0].windows | ForEach-Object {
            [pscustomobject][ordered]@{
                id = $_.id; type = $_.type; enabled = $_.enabled
                windowId = $_.windowId; path = $_.path; elevated = $_.elevated
                tabs = $_.tabs; activeTab = $_.activeTab; match = $_.match; launch = $_.launch
            }
        }) -Depth 10
        Assert-Equal $nonLayoutBefore $nonLayoutAfter "all non-layout fields preserved"
        Assert-Equal $defaultBefore (ConvertTo-Json -InputObject @($default.sets[0].windows) -Depth 10) "bundled default not modified"
        Assert-DevWSConfig -Config $config -Source "test"
    }

