function Find-DevWSReversiblyEncodedPrintableContent {
    # Returns the first base64-charset literal that decodes to fully printable
    # ASCII, or $null. This catches content hidden behind a reversible encoding
    # without the repository needing to know which value was hidden.
    param([Parameter(Mandatory)][string]$Text)

    foreach ($m in [regex]::Matches($Text, '(?<![A-Za-z0-9+/])[A-Za-z0-9+/]{24,}={0,2}(?![A-Za-z0-9+/=])')) {
        $literal = $m.Value.TrimEnd('=')
        $literal = $literal + ('=' * ((4 - ($literal.Length % 4)) % 4))

        try { $bytes = [Convert]::FromBase64String($literal) } catch { continue }
        if ($bytes.Length -lt 8) { continue }

        $printable = @($bytes | Where-Object { $_ -ge 32 -and $_ -le 126 }).Count -eq $bytes.Length
        if ($printable) { return $m.Value }
    }

    return $null
}

    Test-Case "repository artifacts carry no publication-forbidden content" {
        # GENERIC publication invariants. These forbid content CLASSES, never a
        # particular private value, so this public repository stores no private
        # identifier in plain form or in any reversible encoding. Exact private
        # identity checks live in the external, unpublished sanitization audit.
        #
        # Every rule is proven to fire against a SYNTHETIC sample that is
        # assembled from fragments at runtime, so this file never contains a
        # literal that its own rules would flag.
        $rules = @(
            @{
                Name    = 'personal user-profile path'
                Pattern = '(?i)(?<![A-Za-z0-9])[A-Za-z]:\\+Users\\+[A-Za-z0-9][A-Za-z0-9._-]*'
                Sample  = 'C:\Users\' + 'sample-account' + '\work'
                Hint    = 'use %USERPROFILE% or a synthetic fixture root instead of a literal account path'
            }
            @{
                Name    = 'github token'
                Pattern = '(?<![A-Za-z0-9_])(?:gh[porsu]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})'
                Sample  = 'ghp_' + ('A' * 36)
                Hint    = 'never commit a credential'
            }
            @{
                Name    = 'aws access key'
                Pattern = '(?<![A-Z0-9])AKIA[0-9A-Z]{16}(?![A-Z0-9])'
                Sample  = 'AKIA' + ('B' * 16)
                Hint    = 'never commit a credential'
            }
            @{
                Name    = 'api key'
                Pattern = '(?<![A-Za-z0-9_-])sk-[A-Za-z0-9_-]{20,}'
                Sample  = 'sk-' + ('c' * 32)
                Hint    = 'never commit a credential'
            }
            @{
                Name    = 'slack token'
                Pattern = '(?<![A-Za-z0-9])xox[baprs]-[A-Za-z0-9-]{10,}'
                Sample  = 'xoxb-' + ('d' * 24)
                Hint    = 'never commit a credential'
            }
            @{
                Name    = 'bearer token'
                Pattern = '(?i)\bBearer\s+[A-Za-z0-9._-]{20,}'
                Sample  = 'Bearer ' + ('e' * 32)
                Hint    = 'never commit a credential'
            }
            @{
                Name    = 'private key block'
                Pattern = '-----BEGIN [A-Z ]*PRIVATE KEY-----'
                Sample  = '-----BEGIN ' + 'PRIVATE KEY-----'
                Hint    = 'never commit key material'
            }
            @{
                Name         = 'concrete display device path in production source or shipped config'
                Pattern      = '(?i)\\\\?\?\\DISPLAY#(?!<)[^#\r\n]+#'
                Sample       = '\\?\' + 'DISPLAY#' + 'SAMPLEDEV' + '#1&2&0&UID0#'
                Hint         = 'document the device-path shape with <placeholder> segments; concrete device paths belong in fixtures'
                ExcludeTests = $true
            }
            @{
                Name         = 'pnp instance identifier in production source or shipped config'
                Pattern      = '(?i)&[0-9a-f]{6,}&0&UID[0-9]+'
                Sample       = '&' + 'abcdef' + '&0&UID' + '9999'
                Hint         = 'machine-specific instance identifiers belong in fixtures, not in shipped code'
                ExcludeTests = $true
            }
            @{
                Name    = 'reversibly encoded printable content'
                Pattern = $null
                Sample  = 'QUJD' + ('REVG' * 8)
                Hint    = 'remove the encoding, or document why it is required'
            }
        )

        $scanRoots = @(
            (Join-Path $RepoRoot 'src'),
            (Join-Path $RepoRoot 'config'),
            (Join-Path $RepoRoot 'tests'),
            (Join-Path $RepoRoot 'install.ps1'),
            (Join-Path $RepoRoot 'uninstall.ps1')
        )

        # A rule that cannot fire is worse than no rule, so each one must match
        # its own synthetic sample before it is used to judge the repository.
        foreach ($rule in $rules) {
            $fires = if ($null -eq $rule.Pattern) {
                $null -ne (Find-DevWSReversiblyEncodedPrintableContent -Text $rule.Sample)
            }
            else {
                [regex]::IsMatch($rule.Sample, $rule.Pattern)
            }

            Assert-True $fires "publication rule '$($rule.Name)' fires on its synthetic sample"
        }

        $scanned = 0
        $violations = @()

        foreach ($root in $scanRoots) {
            $files = @(
                if (Test-Path -LiteralPath $root -PathType Container) {
                    Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object {
                        $_.FullName -notmatch '[\\/]\.git[\\/]'
                    }
                }
                else {
                    Get-Item -LiteralPath $root
                }
            )

            foreach ($file in $files) {
                $scanned++
                $relative = $file.FullName.Substring($RepoRoot.Length + 1)
                $content = Get-Content -LiteralPath $file.FullName -Raw

                foreach ($rule in $rules) {
                    if ($rule.ExcludeTests -and $relative -like 'tests\*') { continue }

                    $hit = if ($null -eq $rule.Pattern) {
                        $null -ne (Find-DevWSReversiblyEncodedPrintableContent -Text $content)
                    }
                    else {
                        [regex]::IsMatch($content, $rule.Pattern)
                    }

                    if ($hit) {
                        $violations += ('{0} [{1}] - {2}' -f $relative, $rule.Name, $rule.Hint)
                    }
                }
            }
        }

        $violationDetail = ($violations -join [Environment]::NewLine)
        Assert-Equal 0 $violations.Count ("publication-forbidden content found:" + [Environment]::NewLine + $violationDetail)
        Assert-True ($scanned -ge 55) "the publication scan covered the repository artifacts (scanned $scanned files)"
    }

    Test-Case "deferred lifecycle tokens stay absent and the tracked-cwd substrate stays scoped" {
        $deferredTokens = @(
            "sharedId",
            "instanceId",
            "EnumPropsW",
            "DEVWS_SET",
            "DEVWS_ITEM",
            "DEVWS_TAB",
            "prompt hook",
            "generation token"
        )

        foreach ($file in @(Get-ChildItem -Path (Join-Path $RepoRoot "src") -Recurse -Filter *.ps1)) {
            $codeLines = @(Get-Content -LiteralPath $file.FullName | Where-Object {
                $trimmed = $_.Trim()
                -not ($trimmed.StartsWith("#") -or $trimmed.StartsWith(";"))
            })
            $code = $codeLines -join "`n"

            foreach ($token in $deferredTokens) {
                Assert-True (-not [regex]::IsMatch($code, $token)) "deferred token '$token' must not appear in $($file.Name)"
            }
        }

        # Phase 8 lifecycle vocabulary lives in the config validator, the
        # copy-preserving mutations, the ownership-aware lifecycle library, the
        # installer enrichment path, the CLI mode command, and the read-only
        # status model (which only reports the mode and delegates every mode
        # semantic to Get-DevWSAppInstanceMode); no other library interprets
        # instanceMode.
        foreach ($file in @(Get-ChildItem -Path (Join-Path $RepoRoot "src") -Recurse -Filter *.ps1)) {
            if ($file.Name -in @("devws-config.ps1", "devws-mutation.ps1", "devws-app-window.ps1", "devws-install.ps1", "ws.ps1", "devws-status.ps1")) {
                continue
            }

            $codeLines = @(Get-Content -LiteralPath $file.FullName | Where-Object {
                $trimmed = $_.Trim()
                -not ($trimmed.StartsWith("#") -or $trimmed.StartsWith(";"))
            })
            $code = $codeLines -join "`n"

            Assert-True (-not [regex]::IsMatch($code, "instanceMode")) "instanceMode stays config/lifecycle-only: $($file.Name)"
        }

        # Win32 ownership primitives stay centralized: only the ownership
        # primitive library and the ownership-aware lifecycle library may use
        # them. devws-install.ps1 is exempted from the three native method
        # names only, because its structural validator must name the methods
        # it validates; the ownership functions stay exclusive to the
        # ownership libraries everywhere.
        foreach ($file in @(Get-ChildItem -Path (Join-Path $RepoRoot "src") -Recurse -Filter *.ps1)) {
            if ($file.Name -in @("devws-app-ownership.ps1", "devws-app-window.ps1")) {
                continue
            }

            $codeLines = @(Get-Content -LiteralPath $file.FullName | Where-Object {
                $trimmed = $_.Trim()
                -not ($trimmed.StartsWith("#") -or $trimmed.StartsWith(";"))
            })
            $code = $codeLines -join "`n"

            if ($file.Name -ne "devws-install.ps1") {
                foreach ($token in @("SetProp", "GetProp", "RemoveProp")) {
                    Assert-True (-not [regex]::IsMatch($code, $token)) "ownership token '$token' must stay in the ownership libraries: $($file.Name)"
                }
            }

            foreach ($token in @("Set-DevWSAppOwnership", "Test-DevWSAppOwnership", "Remove-DevWSAppOwnership", "Get-DevWSAppOwnership")) {
                Assert-True (-not [regex]::IsMatch($code, $token)) "ownership token '$token' must stay in the ownership libraries: $($file.Name)"
            }
        }

        $appWindowCode = @(Get-Content -LiteralPath (Join-Path $RepoRoot "src\lib\devws-app-window.ps1") | Where-Object {
            $trimmed = $_.Trim()
            -not ($trimmed.StartsWith("#") -or $trimmed.StartsWith(";"))
        }) -join "`n"
        Assert-NotContains $appWindowCode "MainWindowHandle" "lifecycle resolution never relies on MainWindowHandle"

        # Phase 9 Pass 2: `ws save` now exists; save-layout stays geometry-only.
        $ws = Get-SourceOf "src\ws.ps1"

        Assert-Contains $ws '"save" {' "ws save dispatch exists"
        Assert-Contains $ws "Save-DevWSWorkspace" "ws save implementation exists"

        # Future layout scope remains research-only in the runtime libraries.
        # Pass 5B intentionally introduced read-only monitor diagnostics,
        # Pass 5C introduced the optional topology-profile schema, and v0.3
        # Phase 1 introduces the relative-layout schema in the config
        # validator. Profile/grid vocabulary stays research-only elsewhere,
        # and mutation code stays monitor-free.
        foreach ($file in @("devws-config.ps1", "devws-display.ps1", "devws-mutation.ps1")) {
            $codeLines = @(Get-Content -LiteralPath (Join-Path $RepoRoot "src\lib\$file") | Where-Object {
                $trimmed = $_.Trim()
                -not ($trimmed.StartsWith("#") -or $trimmed.StartsWith(";"))
            })
            $code = $codeLines -join "`n"

            $layoutTokens = @("tiling", "named zone", "normalized")

            if ($file -ne "devws-config.ps1") {
                $layoutTokens += "relative"
            }

            if ($file -eq "devws-mutation.ps1") {
                $layoutTokens += "monitor"
            }

            foreach ($token in $layoutTokens) {
                Assert-True (-not [regex]::IsMatch($code, $token)) "future layout token '$token' must not appear in $file"
            }
        }
    }

    Test-Case "Phase 8 bindings and lifecycle sources respect their boundaries" {
        $readCode = {
            param([string]$Path)

            return (@(Get-Content -LiteralPath $Path | Where-Object {
                $trimmed = $_.Trim()
                -not ($trimmed.StartsWith("#") -or $trimmed.StartsWith(";"))
            }) -join "`n")
        }

        $bindingsCode  = & $readCode (Join-Path $RepoRoot "src\lib\devws-bindings.ps1")
        $lifecycleCode = & $readCode (Join-Path $RepoRoot "src\lib\devws-lifecycle.ps1")

        # One managed Startup script only; the generated include carries no
        # #SingleInstance and never re-declares the core shortcuts.
        Assert-NotContains $bindingsCode "#SingleInstance" "generated include does not own #SingleInstance"
        Assert-True (-not [regex]::IsMatch($bindingsCode, '!\s*t::')) "generated include never owns Alt+T"
        Assert-True (-not [regex]::IsMatch($bindingsCode, '!\s*\+\s*t::')) "generated include never owns Alt+Shift+T"
        Assert-NotContains $bindingsCode "schtasks" "generated include never runs scheduled tasks"

        # Generated handlers must be explicit `ws launch <set>` only.
        $generated = New-DevWSBindingsAhkContent -Bindings @(
            [pscustomobject]@{ hotkey = "alt+shift+y"; setId = "secondary" },
            [pscustomobject]@{ hotkey = "ctrl+alt+r"; setId = "research" }
        ) -AppScriptPath "C:\Program Files\DevWS test\app\ws.ps1"

        $generatedPattern = '^[!#^+]+[A-Za-z0-9]+::Run\(''pwsh\.exe -NoLogo -NoProfile -WindowStyle Hidden -File "[^"]+" launch [a-z0-9._-]+'', , "Hide"\)$'

        foreach ($line in @($generated -split "`r?`n")) {
            if ([string]::IsNullOrWhiteSpace($line) -or $line.StartsWith(";")) {
                continue
            }

            Assert-True ([regex]::IsMatch($line, $generatedPattern)) "binding line is an explicit ws launch: $line"
            Assert-NotContains $line "focus" "no focus in generated handler"
            Assert-NotContains $line "reset" "no reset in generated handler"
            Assert-NotContains $line "schtasks" "no scheduled tasks in generated handler"
        }

        # No job queue, lock file, or background-service architecture.
        foreach ($source in @($bindingsCode, $lifecycleCode)) {
            foreach ($forbidden in @("Start-Job", "Register-ScheduledTask", "\.lock", "FileStream", "queue")) {
                Assert-True (-not [regex]::IsMatch($source, $forbidden)) "no lifecycle machinery token '$forbidden'"
            }
        }

        Assert-Contains $lifecycleCode "[System.Threading.Mutex]" "lifecycle lock is a named .NET mutex"
        Assert-Contains $lifecycleCode "Local\DevWS.Lifecycle.v1" "production mutex name"
    }

