        $nativeLine = '. (Join-Path $LibDir "devws-native.ps1")'
        $ownershipLine = '. (Join-Path $LibDir "devws-app-ownership.ps1")'
        $appWindowLine = '. (Join-Path $LibDir "devws-app-window.ps1")'
        $ahkLine = '. (Join-Path $LibDir "devws-ahk.ps1")'
        $windowOpsLine = '. (Join-Path $LibDir "devws-window-ops.ps1")'

        Assert-Contains $ws $nativeLine "ws.ps1 dot-sources devws-native.ps1 explicitly"
        Assert-Contains $ws $ownershipLine "ws.ps1 dot-sources devws-app-ownership.ps1 explicitly"
        Assert-Contains $ws $appWindowLine "ws.ps1 dot-sources devws-app-window.ps1 explicitly"
        Assert-Contains $ws $ahkLine "ws.ps1 dot-sources devws-ahk.ps1 explicitly"
        Assert-Contains $ws $windowOpsLine "ws.ps1 dot-sources devws-window-ops.ps1 explicitly"

        $nativeIndex = $ws.IndexOf($nativeLine, [StringComparison]::Ordinal)
        $ownershipIndex = $ws.IndexOf($ownershipLine, [StringComparison]::Ordinal)
        $appWindowIndex = $ws.IndexOf($appWindowLine, [StringComparison]::Ordinal)
        $ahkIndex = $ws.IndexOf($ahkLine, [StringComparison]::Ordinal)
        $windowOpsIndex = $ws.IndexOf($windowOpsLine, [StringComparison]::Ordinal)

        Assert-True ($nativeIndex -ge 0 -and $ownershipIndex -gt $nativeIndex) "devws-native.ps1 is loaded before devws-app-ownership.ps1"
        Assert-True ($nativeIndex -ge 0 -and $appWindowIndex -gt $nativeIndex) "devws-native.ps1 is loaded before devws-app-window.ps1"
        Assert-True ($ahkIndex -ge 0 -and $windowOpsIndex -gt $ahkIndex) "devws-ahk.ps1 is loaded before devws-window-ops.ps1"

        # Every worker that loads the window-operation layer also loads the
        # shared native runtime first: the workers use native HWND operations.
        foreach ($workerName in @("elevated.ps1", "elevated-focus.ps1", "elevated-capture.ps1", "elevated-reset.ps1")) {
            $worker = Get-SourceOf "src\workers\$workerName"
            $workerNative = $worker.IndexOf($nativeLine, [StringComparison]::Ordinal)
            $workerOps = $worker.IndexOf($windowOpsLine, [StringComparison]::Ordinal)

            Assert-True ($workerNative -ge 0 -and $workerOps -gt $workerNative) "$workerName loads devws-native.ps1 before devws-window-ops.ps1"
        }
    }

