    Test-Case "fresh worker processes validate a non-empty binding (launch/focus/capture/reset)" {
        $fixture = New-WorkerProbeFixture -Name "worker-binding-fresh" -WithBinding

        $workers = [ordered]@{
            launch  = "src\workers\elevated.ps1"
            focus   = "src\workers\elevated-focus.ps1"
            capture = "src\workers\elevated-capture.ps1"
            reset   = "src\workers\elevated-reset.ps1"
        }

        foreach ($kind in $workers.Keys) {
            $payload = @{ setId = "main" }

            if ($kind -eq "reset") {
                $payload["terminalPlacements"] = @([ordered]@{ id = "probe"; move = $true; x = 0; y = 0; w = 100; h = 100 })
            }

            # Public Security Phase 2-D: the one-shot transport requires a
            # canonical lowercase GUID request id for every kind; the capture
            # worker additionally claims with that exact operation id.
            $requestId = [guid]::NewGuid().ToString()

            $run = Invoke-FreshWorkerRun `
                -WorkerPath (Join-Path $RepoRoot $workers[$kind]) `
                -ConfigPath $fixture.ConfigPath `
                -StateRoot $fixture.StateRoot `
                -Kind $kind `
                -RequestId $requestId `
                -Payload $payload

            Assert-Equal $false $run.Preloaded "$kind child process did not preload the bindings library"
            Assert-True ($null -ne $run.Result) "$kind worker wrote a protocol result file"
            Assert-Equal $requestId ([string]$run.Result.requestId) "$kind result carries the request id"
            Assert-NotContains ([string]$run.Message) "ConvertTo-DevWSBindingHotkey" "$kind failure is not the missing-parser defect"
            Assert-NotContains ([string]$run.Result.message) "ConvertTo-DevWSBindingHotkey" "$kind result is not the missing-parser defect"

            if ($kind -eq "reset") {
                # Reset deliberately targets a nonexistent id: validation must
                # pass, then execution must fail for the intended reason - an
                # accepted operation with an unsuccessful FINAL.
                Assert-Equal $false ([bool]$run.Result.ok) "reset reports failure after successful validation"
                Assert-Contains ([string]$run.Result.message) "No configured terminal with id 'probe'" "reset fails for the intended reason"
            }
            else {
                Assert-Equal $true ([bool]$run.Result.ok) "$kind reports success with an empty workspace"
                Assert-Equal "OK" ([string]$run.Result.message) "$kind result message"
            }
        }
    }

    Test-Case "staged worker processes validate a non-empty binding" {
        $fixture = New-InstallFixture "worker-binding-staged"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture

        $probeFixture = New-WorkerProbeFixture -Name "worker-binding-staged-state" -WithBinding

        $stagedWorkers = [ordered]@{
            launch  = "elevated.ps1"
            focus   = "elevated-focus.ps1"
            capture = "elevated-capture.ps1"
            reset   = "elevated-reset.ps1"
        }

        foreach ($kind in $stagedWorkers.Keys) {
            $stagedWorker = Join-Path $fixture.Privileged ("workers\" + $stagedWorkers[$kind])
            Assert-True (Test-Path -LiteralPath $stagedWorker -PathType Leaf) "staged worker exists: $($stagedWorkers[$kind])"
            Assert-Contains (Get-Content -LiteralPath $stagedWorker -Raw) "devws-bindings.ps1" "staged worker wires the bindings library: $($stagedWorkers[$kind])"

            $payload = @{ setId = "main" }

            if ($kind -eq "reset") {
                $payload["terminalPlacements"] = @([ordered]@{ id = "probe"; move = $true; x = 0; y = 0; w = 100; h = 100 })
            }

            # Phase 2-B: the staged (installed-privileged) capture worker can
            # never claim a protected publication inside the repository test
            # process - its installed protected root is the REAL machine root,
            # which tests must never touch (installed layouts ignore the
            # repository seam by design). Exercise its domain contract instead:
            # a non-canonical operation id is refused by the transport frame
            # contract (Public Security Phase 2-D); all other kinds use valid
            # canonical GUID request ids.
            $requestId = $(if ($kind -eq "capture") { "staged-capture" } else { [guid]::NewGuid().ToString() })

            $run = Invoke-FreshWorkerRun `
                -WorkerPath $stagedWorker `
                -ConfigPath $probeFixture.ConfigPath `
                -StateRoot $probeFixture.StateRoot `
                -Kind $kind `
                -RequestId $requestId `
                -Payload $payload

            Assert-Equal $false $run.Preloaded "staged $kind child did not preload the bindings library"
            Assert-True ($null -ne $run.Result) "staged $kind worker wrote a protocol result file"
            Assert-NotContains ([string]$run.Message) "ConvertTo-DevWSBindingHotkey" "staged $kind failure is not the missing-parser defect"
            Assert-NotContains ([string]$run.Result.message) "ConvertTo-DevWSBindingHotkey" "staged $kind result is not the missing-parser defect"

            if ($kind -eq "reset") {
                Assert-Equal $false ([bool]$run.Result.ok) "staged reset reports failure after successful validation"
                Assert-Contains ([string]$run.Result.message) "No configured terminal with id 'probe'" "staged reset fails for the intended reason"
            }
            elseif ($kind -eq "capture") {
                Assert-Equal $false ([bool]$run.Result.ok) "staged capture refuses a non-canonical operation id"
                Assert-Contains ([string]$run.Result.message) "canonical lowercase GUID" "staged capture names its domain contract"
            }
            else {
                Assert-Equal $true ([bool]$run.Result.ok) "staged $kind reports success with an empty workspace"
            }
        }
    }

