    Test-Case "help library is a dependency-free leaf loadable in a fresh process" {
        $helpLib = Join-Path $RepoRoot "src\lib\devws-help.ps1"
        Assert-True (Test-Path -LiteralPath $helpLib -PathType Leaf) "help library exists"

