        # Fresh-process isolation: only devws-help.ps1 is loaded; any hidden
        # dependency would surface as a command-not-found failure.
        $probePath = Join-Path $TestRoot "help-isolation-probe.ps1"
        $outPath   = Join-Path $TestRoot "help-isolation.json"
        $probe = @(
            '$ErrorActionPreference = "Stop"',
            ('. "' + $helpLib + '"'),
            '$commands = @(Get-DevWSHelpCommandInfo)',
            '$topics = @(Get-DevWSHelpTopicInfo)',
            '$quick = (Show-DevWSHelpQuick 6>&1 | Out-String)',
            '$directTopics = @(Get-DevWSHelpDirectTopicInfo | ForEach-Object { [string]$_.Name })',
            '[ordered]@{',
            '    commandCount = $commands.Count',
            '    topicCount = $topics.Count',
            '    directTopics = $directTopics',
            '    commands = $commands',
            '    topics = $topics',
            '    suggestion = [string](@(Get-DevWSCommandSuggestion -CommandName "launhc")[0])',
            '    quickLength = $quick.Length',
            ('} | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath "' + $outPath + '" -Encoding UTF8')
        ) -join "`r`n"
        Set-Content -LiteralPath $probePath -Value $probe -NoNewline

        $proc = Start-Process -FilePath "pwsh" -ArgumentList @('-NoLogo', '-NoProfile', '-File', $probePath) -PassThru -WindowStyle Hidden -Wait
        Assert-Equal 0 $proc.ExitCode "isolated help probe exits cleanly"

        $isolated = Get-Content -LiteralPath $outPath -Raw | ConvertFrom-Json
        $expected = @(Get-DevWSHelpCommandInfo)
        Assert-Equal $expected.Count $isolated.commandCount "isolated catalog command count"
        Assert-Equal ($expected | ConvertTo-Json -Compress -Depth 12) ($isolated.commands | ConvertTo-Json -Compress -Depth 12) "isolated catalog metadata matches"
        Assert-Equal 5 $isolated.topicCount "isolated topic count"
        Assert-Equal "items,layout,hotkeys,tools" ($isolated.directTopics -join ",") "isolated direct topic metadata"
        Assert-Equal "launch" $isolated.suggestion "isolated suggestion for launhc"
        Assert-True ($isolated.quickLength -gt 0) "isolated quick help renders"
    }

    function Test-RepoTextEolCompliance {
        # EOL determinism guard: a covered text file passes only when every LF
        # byte is immediately preceded by CR (bare-LF detection on RAW bytes;
        # a file with no newline or no bytes passes by definition). Binary
        # files are out of scope. Returns offending relative paths.
        param(
            [Parameter(Mandatory)][string]$Root,
            [string[]]$Extensions = @(".ps1", ".ahk", ".cmd", ".json")
        )

        $offenses = [System.Collections.Generic.List[string]]::new()
        $files = [System.Collections.Generic.List[object]]::new()

        foreach ($top in @(Get-ChildItem -LiteralPath $Root -Force | Where-Object { $_.Name -ne ".git" })) {
            if ($top.PSIsContainer) {
                foreach ($file in @(Get-ChildItem -LiteralPath $top.FullName -Recurse -File -Force)) { $files.Add($file) | Out-Null }
            }
            else {
                $files.Add($top) | Out-Null
            }
        }

        foreach ($file in $files) {
            if ($Extensions -notcontains $file.Extension.ToLowerInvariant()) { continue }

            $bytes = [System.IO.File]::ReadAllBytes($file.FullName)
            $bareLf = 0

            for ($i = 0; $i -lt $bytes.Length; $i++) {
                if ($bytes[$i] -eq 10 -and ($i -eq 0 -or $bytes[$i - 1] -ne 13)) { $bareLf++ }
            }

            if ($bareLf -gt 0) {
                $relative = $file.FullName.Substring($Root.Length).TrimStart('\')
                $offenses.Add("$relative (bareLF=$bareLf)") | Out-Null
            }
        }

        return $offenses.ToArray()
    }

    Test-Case "runtime text uses deterministic CRLF line endings" {
        # A. The explicit policy exists and is independent of core.autocrlf.
        $attributesPath = Join-Path $RepoRoot ".gitattributes"
        Assert-True (Test-Path -LiteralPath $attributesPath -PathType Leaf) ".gitattributes exists"

        $attributes = Get-Content -LiteralPath $attributesPath -Raw

        foreach ($rule in @("*.ps1 text eol=crlf", "*.ahk text eol=crlf", "*.cmd text eol=crlf", "*.json text eol=crlf")) {
            Assert-Contains $attributes $rule "EOL policy rule present: $rule"
        }

        # B. Every covered working-tree text file physically uses CRLF only.
        $offenses = @(Test-RepoTextEolCompliance -Root $RepoRoot)
        Assert-True (0 -eq $offenses.Count) ("covered runtime text is CRLF-only" + $(if ($offenses.Count -gt 0) { " -- offenses: " + ($offenses -join ", ") } else { "" }))

        # C. Every source-managed manifest text type is covered by the policy,
        # so a future new runtime text type cannot silently bypass it.
        $covered = @(".ps1", ".ahk", ".cmd", ".json")

        foreach ($entry in @(Get-DevWSInstallManifest -RepoRoot $RepoRoot)) {
            $extension = [System.IO.Path]::GetExtension($entry.Target).ToLowerInvariant()
            Assert-True ($covered -contains $extension) "manifest text type is covered by the EOL policy: $($entry.Target)"
        }

        foreach ($entry in @(Get-DevWSPrivilegedInstallManifest -RepoRoot $RepoRoot)) {
            $extension = [System.IO.Path]::GetExtension($entry.Target).ToLowerInvariant()
            Assert-True ($covered -contains $extension) "privileged manifest text type is covered by the EOL policy: $($entry.Target)"
        }

        # D. Concrete regression case: the attribute itself (not core.autocrlf)
        # owns the materialized form of the former offender.
        # git check-attr only answers inside a Git work tree. A disposable
        # verification copy that is not a work tree must report a visible skip
        # rather than a silent pass.
        $insideWorkTree = $false
        try {
            $probe = @(git -C $RepoRoot rev-parse --is-inside-work-tree 2>&1)
            $insideWorkTree = ($LASTEXITCODE -eq 0 -and ($probe -join ' ').Trim() -eq 'true')
        }
        catch {
            $insideWorkTree = $false
        }

        if (-not $insideWorkTree) {
            Skip-Test "the candidate is not a Git work tree, so 'git check-attr' cannot report attribute state"
        }

        $check = @(git -C $RepoRoot check-attr text eol -- "src/lib/devws-status.ps1")
        Assert-Contains ($check -join "`n") "text: set" "devws-status.ps1 is text"
        Assert-Contains ($check -join "`n") "eol: crlf" "devws-status.ps1 is CRLF-materialized"
    }

