    Test-Case "ws list runs against the bundled default" {
        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $BundledConfigPath

        try {
            $output = & pwsh -NoLogo -NoProfile -File $WsScript list 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            if ($null -eq $savedConfig) { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            else { $env:DEVWS_CONFIG = $savedConfig }
        }

        Assert-Equal 0 $code "ws list exit code"

        # The shipped starter is a valid, empty workspace: the listing must
        # succeed and advertise its single set without listing any item.
        Assert-Contains $output "WORKSPACE: main" "ws list reports the shipped default set"

        foreach ($id in @("slot", "studio", "scratch", "firefox", "codex", "antigravity")) {
            Assert-NotContains $output $id "the empty shipped starter lists no item: $id"
        }

        Assert-NotContains $output "DevWS-Fixture" "the shipped starter lists no fixture content"
    }

    Test-Case "ws quick help is concise, progressive, and side-effect free" {
        $target = New-WritableConfigCopy "help-quick"
        $before = Get-FileBase64 -Path $target

        $bare = Invoke-WsCli -ConfigPath $target -Arguments @()
        Assert-Equal 0 $bare.ExitCode "bare ws exit"
        Assert-Contains $bare.Output "WS  DevWS workspace manager" "bare ws title"
        Assert-Contains $bare.Output "ws <command> [args]" "bare ws usage"
        Assert-Contains $bare.Output "ws <group>" "bare ws group usage"
        Assert-Contains $bare.Output "ws help <command|group|all>" "bare ws help usage"

        $help = Invoke-WsCli -ConfigPath $target -Arguments @("help")
        Assert-Equal 0 $help.ExitCode "ws help exit code"
        Assert-Equal $bare.Output $help.Output "bare ws and ws help print the same quick reference"

        foreach ($needle in @(
            "Common", "Command groups", "Workspace sets", "Utilities", "Help",
            "launch [set]", "focus [set]", "status [set]", "save [set]", "list [set]",
            "items", "layout", "hotkeys", "tools",
            "sets", "help sets", "edit", "doctor",
            "help <command>", "help <group>", "help all"
        )) {
            Assert-Contains $help.Output $needle "quick help mentions $needle"
        }

        # The quick reference must not dump the low-level mutation surface or
        # the compatibility aliases.
        foreach ($needle in @(
            "set-instance-mode", "clone-terminal", "sync-hotkeys", "remove-set",
            "save-layout", "show-layout", "ws show", "ws health",
            "ws set <id|number>", "ws reset-terminal"
        )) {
            Assert-NotContains $help.Output $needle "quick help omits $needle"
        }

        Assert-Equal $before (Get-FileBase64 -Path $target) "quick help left config bytes unchanged"
    }

    Test-Case "ws help all exposes the complete grouped command surface" {
        $target = New-WritableConfigCopy "help-all"
        $before = Get-FileBase64 -Path $target

        $help = Invoke-WsCli -ConfigPath $target -Arguments @("help", "all")
        Assert-Equal 0 $help.ExitCode "ws help all exit code"

        $known = @(
            "launch", "focus", "list", "show", "status", "save", "save-layout", "show-layout",
            "enable", "disable", "remove",
            "add-terminal", "clone-terminal", "set-path", "set-command",
            "add-app", "clone-app", "set-launch", "set-match", "set-app-args", "set-instance-mode",
            "rename", "edit",
            "set-geometry", "reset-layout", "layout-profile",
            "sets", "add-set", "clone-set", "rename-set", "remove-set", "set-default",
            "bind", "unbind", "bindings", "sync-hotkeys",
            "health", "doctor", "detect-app", "monitors",
            "set", "reset", "reset-terminal", "reset-terminals",
            "help"
        )

        foreach ($command in $known) {
            Assert-Contains $help.Output ("ws " + $command) "help all advertises ws $command"
        }

        foreach ($section in @(
            "Workspace", "Item configuration", "Layout", "Workspace sets",
            "Hotkeys", "Tools / diagnostics", "Terminal reset",
            "Compatibility aliases", "Help"
        )) {
            Assert-Contains $help.Output $section "help all section $section"
        }

        # Navigation discovery: direct command groups are listed explicitly and
        # the sets collision is explained without duplicating group commands.
        Assert-Contains $help.Output "Command groups" "help all exposes direct command groups"
        Assert-Contains $help.Output "ws sets lists sets; ws help sets shows set-management commands" "help all explains the sets collision"

        # Every command advertised in help all is a real dispatch command.
        $documented = [System.Collections.Generic.List[string]]::new()

        foreach ($line in @($help.Output -split "`n")) {
            if ($line.Trim() -cmatch '^ws\s+([a-z][a-z-]*)') {
                $documented.Add($Matches[1])
            }
        }

        Assert-True ($documented.Count -ge 30) "help all documents the full command surface"

        foreach ($command in @($documented | Sort-Object -Unique)) {
            Assert-True ($known -contains $command) "documented command exists: ws $command"
        }

        Assert-True ($documented -contains "save") "help all advertises the implemented ws save command"

        Assert-Equal $before (Get-FileBase64 -Path $target) "help all left config bytes unchanged"
    }

