    Test-Case "direct command-group shortcuts render their help-topic views" {
        $target = New-WritableConfigCopy "help-groups"

        foreach ($group in @("items", "layout", "hotkeys", "tools")) {
            $direct = Invoke-WsCli -ConfigPath $target -Arguments @($group)
            $topic  = Invoke-WsCli -ConfigPath $target -Arguments @("help", $group)

            Assert-Equal 0 $direct.ExitCode "ws $group exit"
            Assert-Equal 0 $topic.ExitCode "ws help $group exit"
            Assert-Equal $topic.Output $direct.Output "ws $group matches ws help $group"
        }

        # Case-insensitive navigation is preserved.
        $lowerItems = Invoke-WsCli -ConfigPath $target -Arguments @("items")
        $upperItems = Invoke-WsCli -ConfigPath $target -Arguments @("ITEMS")
        $mixedLayout = Invoke-WsCli -ConfigPath $target -Arguments @("Layout")
        $lowerLayout = Invoke-WsCli -ConfigPath $target -Arguments @("layout")
        Assert-Equal $lowerItems.Output $upperItems.Output "ws ITEMS matches ws items"
        Assert-Equal $lowerLayout.Output $mixedLayout.Output "ws Layout matches ws layout"

        # Unexpected arguments are refused with actionable, group-specific text
        # instead of a generic unknown-command error.
        foreach ($case in @(
            @{ Args = @("items", "foo");   First = "ws enable" },
            @{ Args = @("layout", "foo");  First = "ws save-layout" },
            @{ Args = @("hotkeys", "foo"); First = "ws bind" },
            @{ Args = @("tools", "foo");   First = "ws edit" }
        )) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $case.Args
            $label = ($case.Args -join " ")

            Assert-Equal 1 $result.ExitCode "group extra-argument exit: $label"
            Assert-Contains $result.Output "command-group browser and does not accept arguments" "group refusal text: $label"
            Assert-Contains $result.Output $case.First "group refusal names a flat command: $label"
            Assert-NotContains $result.Output "Unknown command" "group refusal is not a generic unknown-command error: $label"
        }

        # Presentation-only: no config dependency, no config writes.
        $missing = Join-Path $TestRoot "help-groups-missing\workspace.json"
        $brokenDir = Join-Path $TestRoot "help-groups-broken"
        New-Item -ItemType Directory -Path $brokenDir -Force | Out-Null
        $broken = Join-Path $brokenDir "workspace.json"
        Set-Content -LiteralPath $broken -Value '{ not json' -NoNewline
        $before = Get-FileBase64 -Path $target

        foreach ($group in @("items", "layout", "hotkeys", "tools")) {
            Assert-Equal 0 (Invoke-WsCli -ConfigPath $missing -Arguments @($group)).ExitCode "ws $group works without a config file"
            Assert-Equal 0 (Invoke-WsCli -ConfigPath $broken -Arguments @($group)).ExitCode "ws $group works with a malformed config"
        }

        Assert-Equal $before (Get-FileBase64 -Path $target) "direct groups left config bytes unchanged"
    }

