    Test-Case "every quick-help navigation token resolves to an executable surface" {
        # Data-driven drift invariant: the quick reference may only advertise
        # tokens the top-level dispatcher can execute (real command, command
        # alias, direct command-group shortcut) or explicit help invocations.
        # This is the invariant that would have caught the historical bug where
        # help-topic names were printed as though they were commands.
        $commands = @(Get-DevWSHelpCommandInfo)
        $aliases = @($commands | ForEach-Object { $_.Aliases } | ForEach-Object { [string]$_.Name })
        $directTopics = @(Get-DevWSHelpDirectTopicInfo | ForEach-Object { [string]$_.Name })

        Assert-Equal "items,layout,hotkeys,tools" ($directTopics -join ",") "direct topics come from metadata"
        Assert-Equal $false (Test-DevWSHelpDirectTopic -Name "sets") "sets is not hijacked into a group shortcut"
        foreach ($name in @("items", "layout", "hotkeys", "tools")) {
            Assert-True (Test-DevWSHelpDirectTopic -Name $name) "$name is a direct group"
        }

        $known = @($commands | ForEach-Object { [string]$_.Name }) + $aliases + $directTopics

        # Parse the real rendered CLI output (single rendered lines), not the
        # in-process information stream, where the NoNewline left column and
        # the right column arrive as separate records.
        $target = New-WritableConfigCopy "help-invariant"
        $quick = (Invoke-WsCli -ConfigPath $target -Arguments @()).Output

        $tokens = [System.Collections.Generic.List[string]]::new()

        foreach ($line in @($quick -split "`r?`n")) {
            $match = [regex]::Match($line.TrimEnd(), '^  (\S.*?)\s{2,}\S')

            if (-not $match.Success) { continue }

            $left = $match.Groups[1].Value.Trim()

            if ($left -like 'ws *') { continue }   # usage template lines

            $tokens.Add($left) | Out-Null
        }

        Assert-True ($tokens.Count -ge 14) "quick help advertises navigation rows"

        foreach ($left in $tokens) {
            if ($left -eq "help" -or $left -like "help *") {
                $helpTarget = $left.Substring(4).Trim()

                if ($helpTarget.StartsWith('<')) { continue }   # placeholder form

                Assert-True (($known -contains $helpTarget) -or ($helpTarget -eq "all")) "help row target resolves: help $helpTarget"
                continue
            }

            $token = $left.Split(' ')[0]
            Assert-True ($known -contains $token) "quick-help token resolves: $token"
        }

        # The dispatcher routes on the metadata helper instead of a second
        # hardcoded list, and the direct-group dispatch block stays
        # presentation-only.
        $wsSource = Get-SourceOf "src\ws.ps1"
        Assert-Contains $wsSource "Test-DevWSHelpDirectTopic -Name `$_" "dispatcher routes on the metadata helper"

        $start = $wsSource.IndexOf("Test-DevWSHelpDirectTopic -Name `$_")
        $end   = $wsSource.IndexOf('"launch" {', $start)
        Assert-True ($start -ge 0 -and $end -gt $start) "direct-group dispatch region located"

        $region = $wsSource.Substring($start, $end - $start)

        Assert-Contains $region "Show-DevWSHelpTopic" "direct groups delegate to the topic renderer"

        foreach ($forbidden in @("Get-DevWSContext", "Save-DevWSConfig", "Invoke-DevWSWorkerRequest", "New-DevWSElevatedBrokerPrepare", "Get-DevWSMonitorTopology", "Move-DevWSWindowHwnd")) {
            Assert-NotContains $region $forbidden "direct groups are presentation-only: $forbidden"
        }
    }

    Test-Case "CLI lifecycle commands accept one set argument and reject extras" {
        $target = New-WritableConfigCopy "cli-set-args-grammar"
        $before = Get-FileBase64 -Path $target

        $extraCases = @(
            @("launch", "main", "extra"),
            @("focus", "main", "extra"),
            @("list", "main", "extra"),
            @("show", "main", "extra"),
            @("save-layout", "main", "extra"),
            @("save", "main", "extra"),
            @("show-layout", "main", "extra"),
            @("reset-terminals", "main", "extra")
        )

        foreach ($arguments in $extraCases) {
