            Assert-Contains $result.Output "Unknown workspace set" ("unknown set error for: " + ($arguments -join " "))
        }

        Assert-Equal $before (Get-FileBase64 -Path $target) "grammar failures left config bytes unchanged"
    }

    Test-Case "ws add-terminal refuses to modify the bundled default config" {
        # The shipped starter has no configured items, so the write attempt
        # must use an operation that is VALID against an empty workspace.
        # The refusal concerns the config LOCATION, not the addressed item.
        $before = Get-Content -LiteralPath $BundledConfigPath -Raw
        $env:DEVWS_CONFIG = $BundledConfigPath

        try {
            $output = & pwsh -NoLogo -NoProfile -File $WsScript add-terminal bundledprobe . somecmd 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        Assert-Equal 1 $code "add-terminal exit code"
        Assert-Contains $output "Refusing to modify" "read-only refusal message"
        Assert-Equal $before (Get-Content -LiteralPath $BundledConfigPath -Raw) "default config unchanged"
    }

