    Write-Host ""
    Start-TestGroup -Name 'cli-mutations' -Title 'CLI mutations'

    Test-Case "acceptance: disable, add-terminal, list, enable, set-path, set-command, remove" {
        $target = New-WritableConfigCopy "acceptance"
        $spaceDir = Join-Path $TestRoot "acceptance work dir"
        New-Item -ItemType Directory -Path $spaceDir -Force | Out-Null

        # ws disable antigravity
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("disable", "antigravity")
        Assert-Equal 0 $result.ExitCode "disable exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $false ($config.sets[0].windows | Where-Object { $_.id -eq "antigravity" }).enabled "antigravity disabled"

        # ws add-terminal agy . agy
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-terminal", "agy", ".", "agy")
        Assert-Equal 0 $result.ExitCode "add exit"

        $config = Read-DevWSConfigFile -Path $target
        $agy = @($config.sets[0].windows | Where-Object { $_.id -eq "agy" })
        Assert-Equal 1 $agy.Count "agy added"
        $agy = $agy[0]
        Assert-Equal "terminal" $agy.type "type"
        Assert-Equal "DevWS-main-agy" $agy.windowId "windowId"
        Assert-Equal $true $agy.enabled "enabled"
        Assert-Equal $true $agy.elevated "elevated"
        Assert-Equal 0 $agy.activeTab "activeTab"
        Assert-Equal 2 @($agy.tabs).Count "command + idle"
        Assert-Equal "agy" $agy.tabs[0].command "command"
        Assert-True ($null -eq $agy.tabs[1].command) "idle tab"
        Assert-Equal (Resolve-Path -LiteralPath ".").Path $agy.path "resolved current directory"
        Assert-Equal 2553 $agy.layout.x "layout copied from last terminal"

        # ws list
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("list")
        Assert-Equal 0 $result.ExitCode "list exit"
        Assert-Contains $result.Output "agy" "list shows new terminal"

        # ws enable antigravity
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("enable", "antigravity")
        Assert-Equal 0 $result.ExitCode "enable exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $true ($config.sets[0].windows | Where-Object { $_.id -eq "antigravity" }).enabled "antigravity enabled"

        # ws set-path agy <dir with spaces>
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "agy", $spaceDir)
        Assert-Equal 0 $result.ExitCode "set-path exit"
        Assert-Contains $result.Output "keep their current directory until reset" "set-path is config-only"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal (Resolve-Path -LiteralPath $spaceDir).Path ($config.sets[0].windows | Where-Object { $_.id -eq "agy" }).path "path updated"

        # ws set-command agy somecmd --model foo
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "agy", "somecmd", "--model", "foo")
        Assert-Equal 0 $result.ExitCode "set-command exit"
        Assert-Contains $result.Output "keep their current command until reset" "set-command is config-only"
        $config = Read-DevWSConfigFile -Path $target
        $agy = @($config.sets[0].windows | Where-Object { $_.id -eq "agy" })[0]
        Assert-Equal "somecmd" $agy.tabs[0].command "command replaced"
        Assert-Equal "--model,foo" (@($agy.tabs[0].args) -join ",") "args replaced"
        Assert-True ($null -eq $agy.tabs[1].command) "idle tab preserved"

        # ws remove agy -Force
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("remove", "agy", "-Force")
        Assert-Equal 0 $result.ExitCode "remove exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 0 @($config.sets[0].windows | Where-Object { $_.id -eq "agy" }).Count "agy removed"
        Assert-Equal 6 @($config.sets[0].windows).Count "six items again"
        Assert-Equal $true ($config.sets[0].windows | Where-Object { $_.id -eq "antigravity" }).enabled "antigravity still enabled"
    }

