        Assert-Equal 1 $result.ExitCode "usage exit"
        Assert-Contains $result.Output "Usage: ws add-terminal" "usage message"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "usage failure unchanged"
    }

    Test-Case "mutations refuse the bundled default config" {
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($BundledConfigPath))

        # An empty shipped starter has no items to disable, so the write
        # attempt uses an operation that is valid against an empty workspace.
        $result = Invoke-WsCli -ConfigPath $BundledConfigPath -Arguments @("add-set", "bundledprobe")
        Assert-Equal 1 $result.ExitCode "add-set refused"
        Assert-Contains $result.Output "Refusing to modify" "read-only message"

        $result = Invoke-WsCli -ConfigPath $BundledConfigPath -Arguments @("add-terminal", "tempterm", ".", "somecmd")
        Assert-Equal 1 $result.ExitCode "add refused"

        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($BundledConfigPath))) "bundled default unchanged"
    }

    Test-Case "duplicate adds and invalid mutations leave bytes unchanged" {
        $target = New-WritableConfigCopy "cli-unchanged"
        $spaceDir = Join-Path $TestRoot "cli-unchanged dir"
        New-Item -ItemType Directory -Path $spaceDir -Force | Out-Null

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-terminal", "dup", $spaceDir, "somecmd")
        Assert-Equal 0 $result.ExitCode "first add"

        $afterFirst = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-terminal", "DUP", $spaceDir)
        Assert-Equal 1 $result.ExitCode "duplicate id rejected"
        Assert-Contains $result.Output "already exists" "duplicate id error names the collision"
        Assert-NotContains $result.Output "Usage:" "duplicate id must fail validation, not parsing"
        Assert-Equal $afterFirst ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "duplicate id unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-terminal", "badpath", (Join-Path $TestRoot "no-such-dir"))
        Assert-Equal 1 $result.ExitCode "invalid path rejected"
        Assert-Contains $result.Output "does not exist" "invalid path error refers to path resolution"
        Assert-NotContains $result.Output "Usage:" "invalid path must fail validation, not parsing"
        Assert-Equal $afterFirst ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "invalid path unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "dup", (Join-Path $TestRoot "no-such-dir"))
        Assert-Equal 1 $result.ExitCode "invalid set-path rejected"
        Assert-Equal $afterFirst ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "invalid set-path unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "dup", "")
        Assert-Equal 1 $result.ExitCode "empty set-command rejected"
        Assert-Equal $afterFirst ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "empty set-command unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "firefox", "somecmd")
        Assert-Equal 1 $result.ExitCode "app set-command rejected"
        Assert-Equal $afterFirst ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "app set-command unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "2", "somecmd")
        Assert-Equal 1 $result.ExitCode "numeric alias rejected for set-command"
        Assert-Equal $afterFirst ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "numeric alias unchanged"
    }

    Test-Case "remove confirms by default and cancellation keeps config" {
        $target = New-WritableConfigCopy "cli-cancel"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $env:DEVWS_CONFIG = $target

        try {
            $output = "n" | & pwsh -NoLogo -NoProfile -File $WsScript remove firefox 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        Assert-Equal 0 $code "cancelled exit"
        Assert-Contains $output "Cancelled" "cancellation message"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "cancellation left config unchanged"

        $env:DEVWS_CONFIG = $target

        try {
            $output = "y" | & pwsh -NoLogo -NoProfile -File $WsScript remove firefox 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        Assert-Equal 0 $code "confirmed exit"
        Assert-Contains $output "Removed" "removal message"
        Assert-Contains $output "No running window was closed" "remove never closes a live window"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 0 @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" }).Count "firefox removed"
    }

