    Test-Case "CLI add-app creates apps and rejects invalid mutations without touching bytes" {
        $target = New-WritableConfigCopy "cli-add-app"
        $config = Read-DevWSConfigFile -Path $target
        $lastApp = @($config.sets[0].windows | Where-Object { $_.type -eq "app" })[-1]

        $result = Invoke-WsCli -ConfigPath $target -Arguments @(
            "add-app", "discord", "exe", "C:\Program Files\Discord\Discord.exe", "exe", "Discord.exe", "dedicated"
        )
        Assert-Equal 0 $result.ExitCode "add-app exit"
        Assert-Contains $result.Output "not launched" "config-only notice"
        Assert-Contains $result.Output "mode:     dedicated" "explicit mode reported"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 7 @($config.sets[0].windows).Count "app appended"
        $discord = @($config.sets[0].windows | Where-Object { $_.id -eq "discord" })
        Assert-Equal 1 $discord.Count "discord configured"
        $discord = $discord[0]

        Assert-Equal "app" $discord.type "type"
        Assert-Equal $true $discord.enabled "enabled default"
        Assert-Equal "exe" $discord.match.kind "match kind"
        Assert-Equal "Discord.exe" $discord.match.value "match value"
        Assert-Equal "exe" $discord.launch.kind "launch kind"
        Assert-Equal "C:\Program Files\Discord\Discord.exe" $discord.launch.value "launch value"
        Assert-Equal 0 @($discord.launch.args).Count "empty args default"
        Assert-Equal "dedicated" $discord.instanceMode "explicit mode stored"
        Assert-Equal $lastApp.layout.x $discord.layout.x "layout copied from last app"
        Assert-Equal "slot,studio,scratch,firefox,codex,antigravity,discord" (@($config.sets[0].windows | ForEach-Object { $_.id }) -join ",") "existing order preserved"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @(
            "add-app", "codexclone", "appId", "OpenAI.Codex_2p2nqsd0c76g0!App", "processPathContains", "\OpenAI.Codex_", "shared"
        )
        Assert-Equal 0 $result.ExitCode "appId add exit"
        $config = Read-DevWSConfigFile -Path $target
        $clone = @($config.sets[0].windows | Where-Object { $_.id -eq "codexclone" })[0]
        Assert-Equal "appId" $clone.launch.kind "appId launch kind stored"
        Assert-Equal "processPathContains" $clone.match.kind "processPathContains match kind stored"
        Assert-Equal "shared" $clone.instanceMode "shared mode stored"

        $afterValid = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $failures = @(
            @{ Name = "duplicate id";   Args = @("add-app", "DISCORD", "exe", "C:\a.exe", "exe", "a.exe", "dedicated"); Error = "already exists" },
            @{ Name = "terminal id";    Args = @("add-app", "slot", "exe", "C:\a.exe", "exe", "a.exe", "dedicated"); Error = "already exists" },
            @{ Name = "numeric id";     Args = @("add-app", "2", "exe", "C:\a.exe", "exe", "a.exe", "dedicated"); Error = "must not be numeric" },
            @{ Name = "invalid id";     Args = @("add-app", "bad id", "exe", "C:\a.exe", "exe", "a.exe", "dedicated"); Error = "may only contain" },
            @{ Name = "launch kind";    Args = @("add-app", "newapp", "bogus", "C:\a.exe", "exe", "a.exe", "dedicated"); Error = "Unsupported launch kind" },
            @{ Name = "match kind";     Args = @("add-app", "newapp", "exe", "C:\a.exe", "bogus", "a.exe", "dedicated"); Error = "Unsupported match kind" },
            @{ Name = "launch value";   Args = @("add-app", "newapp", "exe", "", "exe", "a.exe", "dedicated"); Error = "launch value is required" },
            @{ Name = "match value";    Args = @("add-app", "newapp", "exe", "C:\a.exe", "exe", "   ", "dedicated"); Error = "match value is required" },
            @{ Name = "unknown mode";   Args = @("add-app", "newapp", "exe", "C:\a.exe", "exe", "a.exe", "sometimes"); Error = "Unknown instance mode" },
            @{ Name = "missing fields"; Args = @("add-app", "newapp", "exe"); Error = "Usage: ws add-app" }
        )

        foreach ($failure in $failures) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $failure.Args
            Assert-Equal 1 $result.ExitCode "$($failure.Name) exit"
            Assert-Contains $result.Output $failure.Error "$($failure.Name) error"
            Assert-Equal $afterValid ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "$($failure.Name) left bytes unchanged"
        }
    }

    Test-Case "CLI set-instance-mode updates every same-id app atomically" {
        $target = New-TwoSetConfigCopy "cli-set-instance-mode"
        $before = Get-FileBase64 -Path $target

        # 'firefox' is dedicated in both sets; switch both to shared (identical
        # definitions, so equivalence holds).
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-instance-mode", "firefox", "shared")
        Assert-Equal 0 $result.ExitCode "set-instance-mode exit"
        Assert-Contains $result.Output "Instance mode for app id 'firefox' set to 'shared'." "mode message"
        Assert-Contains $result.Output "main/firefox" "first definition reported"
        Assert-Contains $result.Output "secondary/firefox" "second definition reported"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal "shared" @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].instanceMode "main updated"
        Assert-Equal "shared" @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0].instanceMode "secondary updated"

        # A scoped reference applies to every same-id definition too, and the
        # mode round-trips back to dedicated (different definitions allowed).
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-instance-mode", "secondary/firefox", "dedicated")
        Assert-Equal 0 $result.ExitCode "scoped set-instance-mode exit"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal "dedicated" @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].instanceMode "scoped call updated main too"
        Assert-Equal "dedicated" @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0].instanceMode "scoped call updated secondary"

        # An unknown mode fails without touching bytes.
        $stable = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-instance-mode", "firefox", "sometimes")
        Assert-Equal 1 $result.ExitCode "unknown mode exit"
        Assert-Contains $result.Output "Unknown instance mode" "unknown mode error"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "unknown mode left bytes unchanged"

        # Missing arguments fail with usage.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-instance-mode", "firefox")
        Assert-Equal 1 $result.ExitCode "missing mode exit"
        Assert-Contains $result.Output "Usage: ws set-instance-mode" "missing mode usage"

        # Single-set default: only one definition changes.
        $singleTarget = New-WritableConfigCopy "cli-set-instance-mode-single"
        $result = Invoke-WsCli -ConfigPath $singleTarget -Arguments @("set-instance-mode", "codex", "dedicated")
        Assert-Equal 0 $result.ExitCode "single occurrence exit"
        Assert-Contains $result.Output "main/codex" "single occurrence reported"
        $singleConfig = Read-DevWSConfigFile -Path $singleTarget
        Assert-Equal "dedicated" @($singleConfig.sets[0].windows | Where-Object { $_.id -eq "codex" })[0].instanceMode "single definition updated"

        Assert-True ($before -ne $stable) "successful mode changes did rewrite config"
    }

    Test-Case "set-instance-mode to shared rejects non-equivalent same-id definitions atomically" {
        $target = New-LifecycleConfigCopy "cli-set-instance-mode-shared-conflict"

        # main/browser and secondary/browser are dedicated with different
        # definitions; switching the id to shared must fail because shared
        # definitions have to be identical.
        $before = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-instance-mode", "browser", "shared")
        Assert-Equal 1 $result.ExitCode "conflict exit"
        Assert-Contains $result.Output "explicitly shared" "equivalence error reported"
        Assert-Equal $before (Get-FileBase64 -Path $target) "conflict left canonical bytes unchanged"
    }

