            @{ Name = "app source";     Args = @("clone-terminal", "firefox", "copy"); Error = "is an app" },
            @{ Name = "duplicate";      Args = @("clone-terminal", "slot", "backend"); Error = "already exists" },
            @{ Name = "numeric source"; Args = @("clone-terminal", "9", "copy"); Error = "numeric aliases" },
            @{ Name = "missing args";   Args = @("clone-terminal", "slot"); Error = "Usage: ws clone-terminal" }
        )

        foreach ($failure in $failures) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $failure.Args
            Assert-Equal 1 $result.ExitCode "$($failure.Name) exit"
            Assert-Contains $result.Output $failure.Error "$($failure.Name) error"
            Assert-Equal $stable ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "$($failure.Name) left bytes unchanged"
        }
    }

    Test-Case "CLI clone-app creates a disabled template and explains the safety rule" {
