            Assert-Contains $result.Output $failure.Error "$($failure.Name) error"
            Assert-Equal $stable ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "$($failure.Name) left bytes unchanged"
        }
    }

    Test-Case "CLI scoped config mutations touch only the target set" {
        $target = New-TwoSetConfigCopy "cli-scoped-mutations"
        $dir = Join-Path $TestRoot "scoped-mutations-dir"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null

        $config     = Read-DevWSConfigFile -Path $target
        $mainBefore = ConvertTo-Json -InputObject @($config.sets[0].windows) -Depth 20

        # disable secondary/firefox
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("disable", "secondary/firefox")
        Assert-Equal 0 $result.ExitCode "disable exit"
        Assert-Contains $result.Output "Disabled 'secondary/firefox' [app]." "scoped disable label"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $false @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "secondary app disabled"
        Assert-Equal $true @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "main app untouched"

        # enable secondary/firefox
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("enable", "secondary/firefox")
        Assert-Equal 0 $result.ExitCode "enable exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $true @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "secondary app re-enabled"

        # set-path secondary/studio
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "secondary/studio", $dir)
        Assert-Equal 0 $result.ExitCode "set-path exit"
        Assert-Contains $result.Output "Terminal 'secondary/studio'" "scoped path label"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal (Resolve-Path -LiteralPath $dir).Path @($config.sets[1].windows | Where-Object { $_.id -eq "studio" })[0].path "secondary path updated"
        Assert-Equal "C:\DevWS-Fixture\workspaces\studio" @($config.sets[0].windows | Where-Object { $_.id -eq "studio" })[0].path "main path untouched"

        # set-command secondary/studio with literal tool arguments
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "secondary/studio", "some-tool", "-w", "5")
        Assert-Equal 0 $result.ExitCode "set-command exit"
        $config = Read-DevWSConfigFile -Path $target
        $secondaryStudio = @($config.sets[1].windows | Where-Object { $_.id -eq "studio" })[0]
        Assert-Equal "some-tool" $secondaryStudio.tabs[0].command "secondary command stored"
        Assert-Equal "-w,5" (@($secondaryStudio.tabs[0].args) -join ",") "literal scoped args stored"
        Assert-Equal "devws-shell" @($config.sets[0].windows | Where-Object { $_.id -eq "studio" })[0].tabs[0].command "main command untouched"

        # set-geometry secondary/firefox
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-geometry", "secondary/firefox", "--x", "10", "--y", "20", "--width", "1000", "--height", "900")
        Assert-Equal 0 $result.ExitCode "set-geometry exit"
        Assert-Contains $result.Output "Updated layout for 'secondary/firefox'." "scoped geometry label"
        $config = Read-DevWSConfigFile -Path $target
        $secondaryFirefox = @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal 10 $secondaryFirefox.layout.x "secondary geometry updated"
        Assert-Equal 1000 $secondaryFirefox.layout.w "secondary width updated"
        Assert-Equal 633 @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].layout.x "main geometry untouched"

        # add-app secondary/discord plus app mutations
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-app", "secondary/discord", "exe", "C:\Program Files\Discord\Discord.exe", "exe", "Discord.exe", "dedicated")
        Assert-Equal 0 $result.ExitCode "add-app exit"
        Assert-Contains $result.Output "Added app 'secondary/discord'." "scoped add-app label"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 7 @($config.sets[1].windows).Count "secondary grew"
        Assert-Equal 6 @($config.sets[0].windows).Count "main untouched by add-app"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-match", "secondary/discord", "processPathContains", "Discord")
        Assert-Equal 0 $result.ExitCode "set-match exit"
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-launch", "secondary/discord", "exe", "C:\Program Files\Discord\Discord.exe")
        Assert-Equal 0 $result.ExitCode "set-launch exit"
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-app-args", "secondary/discord", "-w", "5")
        Assert-Equal 0 $result.ExitCode "set-app-args exit"
        $config = Read-DevWSConfigFile -Path $target
        $discord = @($config.sets[1].windows | Where-Object { $_.id -eq "discord" })[0]
        Assert-Equal "processPathContains" $discord.match.kind "scoped match updated"
        Assert-Equal "C:\Program Files\Discord\Discord.exe" $discord.launch.value "scoped launch updated"
        Assert-Equal "-w,5" (@($discord.launch.args) -join ",") "scoped app args stored literally"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-app-args", "secondary/discord", "--clear")
        Assert-Equal 0 $result.ExitCode "clear exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 0 @(@($config.sets[1].windows | Where-Object { $_.id -eq "discord" })[0].launch.args).Count "scoped app args cleared"

        # rename secondary/firefox browser
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("rename", "secondary/firefox", "browser")
        Assert-Equal 0 $result.ExitCode "rename exit"
        Assert-Contains $result.Output "Renamed app 'secondary/firefox' -> 'secondary/browser'." "scoped rename label"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 0 @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" }).Count "secondary renamed away"
        Assert-Equal 1 @($config.sets[1].windows | Where-Object { $_.id -eq "browser" }).Count "secondary renamed target"
        Assert-Equal 1 @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" }).Count "main firefox intact"

        # rename cannot move an item between sets
        $stable = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("rename", "secondary/browser", "main/browser2")
        Assert-Equal 1 $result.ExitCode "move-style rename rejected"
        Assert-Contains $result.Output "cannot move an item between sets" "rename is not a move"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "move-style rename left bytes unchanged"

        # set compatibility alias with a stable scoped reference
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set", "secondary/slot", $dir)
        Assert-Equal 0 $result.ExitCode "scoped set alias exit"
        Assert-Contains $result.Output "Terminal 'secondary/slot'" "scoped set alias label"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal (Resolve-Path -LiteralPath $dir).Path @($config.sets[1].windows | Where-Object { $_.id -eq "slot" })[0].path "secondary slot path via alias"
        Assert-Equal "C:\DevWS-Fixture\workspaces\slot" @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0].path "main slot path untouched"

        # scoped numeric references are never ordinal
        $stable = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set", "secondary/2", $dir)
        Assert-Equal 1 $result.ExitCode "scoped ordinal rejected"
        Assert-Contains $result.Output "numeric aliases" "no scoped ordinal fallback"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "rejected scoped ordinal left bytes unchanged"

        # a literal stable id "2" resolves scoped
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-terminal", "secondary/2", $dir, "two-tool")
        Assert-Equal 0 $result.ExitCode "literal numeric id add exit"
        Assert-Contains $result.Output "Added terminal 'secondary/2'." "literal numeric add label"
        Assert-Contains $result.Output "windowId: DevWS-secondary-2" "literal numeric identity"
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set", "secondary/2", $dir)
        Assert-Equal 0 $result.ExitCode "literal numeric set alias exit"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("remove", "secondary/2", "-Force")
        Assert-Equal 0 $result.ExitCode "remove exit"
        Assert-Contains $result.Output "Removed 'secondary/2'" "scoped remove label"

        # add-terminal secondary/agy with common-parameter-looking literals
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-terminal", "secondary/agy", $dir, "agy-tool", "-e", "-i", "--private-window")
        Assert-Equal 0 $result.ExitCode "scoped add-terminal exit"
        Assert-Contains $result.Output "Added terminal 'secondary/agy'." "scoped add-terminal label"
        Assert-Contains $result.Output "windowId: DevWS-secondary-agy" "set-qualified identity"
        $config = Read-DevWSConfigFile -Path $target
        $agy = @($config.sets[1].windows | Where-Object { $_.id -eq "agy" })[0]
        Assert-Equal "-e,-i,--private-window" (@($agy.tabs[0].args) -join ",") "literal scoped add-terminal args"
        Assert-Equal 0 @($config.sets[0].windows | Where-Object { $_.id -eq "agy" }).Count "main has no scoped addition"

        # scoped failure cases leave bytes unchanged
        $stable = Get-FileBase64 -Path $target
        $failures = @(
            @{ Args = @("disable", "secondary/nope"); Error = "Unknown workspace item" },
            @{ Args = @("add-app", "missing/app", "exe", "C:\a.exe", "exe", "a.exe", "dedicated"); Error = "Unknown workspace set" },
            @{ Args = @("enable", "/x"); Error = "before '/' is empty" },
            @{ Args = @("disable", "secondary/"); Error = "after '/' is empty" },
            @{ Args = @("disable", "secondary/a/b"); Error = "exactly one '/'" }
        )

        foreach ($failure in $failures) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $failure.Args
            Assert-Equal 1 $result.ExitCode ("exit for: " + ($failure.Args -join " "))
            Assert-Contains $result.Output $failure.Error ("error for: " + ($failure.Args -join " "))
            Assert-Equal $stable (Get-FileBase64 -Path $target) ("bytes for: " + ($failure.Args -join " "))
        }

        # The main set was never touched by any scoped mutation.
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $mainBefore (ConvertTo-Json -InputObject @($config.sets[0].windows) -Depth 20) "main set untouched throughout"
    }

    Test-Case "duplicate-id matrix keeps config and read operations set-local" {
        $target = New-LifecycleConfigCopy "duplicate-id-matrix"
        $dir = Join-Path $TestRoot "duplicate-id-matrix-dir"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null

        # Read selection.
        $mainList   = Invoke-WsCli -ConfigPath $target -Arguments @("list", "main")
        $secondList = Invoke-WsCli -ConfigPath $target -Arguments @("list", "secondary")
        Assert-Contains $mainList.Output "editor.exe" "main list shows the main-only app"
        Assert-NotContains $mainList.Output "notes.exe" "main list hides the secondary-only app"
        Assert-Contains $secondList.Output "notes.exe" "secondary list shows the secondary-only app"
        Assert-NotContains $secondList.Output "editor.exe" "secondary list hides the main-only app"

        $mainLayout = Invoke-WsCli -ConfigPath $target -Arguments @("show-layout", "main")
        Assert-Contains $mainLayout.Output "Saved layout for set 'main'" "main layout heading"
        Assert-NotContains $mainLayout.Output "set 'secondary'" "show-layout is single-set"

        # Config mutations on duplicate terminal ids.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "secondary/termalpha", $dir)
        Assert-Equal 0 $result.ExitCode "scoped set-path exit"
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "main/termalpha", "maintool", "--flag")
        Assert-Equal 0 $result.ExitCode "scoped set-command exit"
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-geometry", "secondary/termalpha", "--x", "77", "--y", "78", "--width", "79", "--height", "80")
        Assert-Equal 0 $result.ExitCode "scoped set-geometry exit"

        $config      = Read-DevWSConfigFile -Path $target
        $mainAlpha   = @($config.sets[0].windows | Where-Object { $_.id -eq "termalpha" })[0]
        $secondAlpha = @($config.sets[1].windows | Where-Object { $_.id -eq "termalpha" })[0]
        Assert-Equal "maintool" $mainAlpha.tabs[0].command "main duplicate command updated"
        Assert-True ($null -eq $secondAlpha.tabs[0].command) "secondary duplicate command untouched"
        Assert-Equal (Resolve-Path -LiteralPath $dir).Path $secondAlpha.path "secondary duplicate path updated"
        Assert-Equal $TestRoot $mainAlpha.path "main duplicate path untouched"
        Assert-Equal 77 $secondAlpha.layout.x "secondary duplicate geometry updated"
        Assert-Equal 0 $mainAlpha.layout.x "main duplicate geometry untouched"

        # Duplicate app ids: set-match touches one definition only.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-match", "secondary/browser", "processPathContains", "secondary-browser")
        Assert-Equal 0 $result.ExitCode "scoped set-match exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal "processPathContains" @($config.sets[1].windows | Where-Object { $_.id -eq "browser" })[0].match.kind "secondary duplicate app updated"
        Assert-Equal "exe" @($config.sets[0].windows | Where-Object { $_.id -eq "browser" })[0].match.kind "main duplicate app untouched"

        # Rename one duplicate; the other set keeps its id.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("rename", "secondary/termalpha", "termx")
        Assert-Equal 0 $result.ExitCode "scoped rename exit"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 0 @($config.sets[1].windows | Where-Object { $_.id -eq "termalpha" }).Count "secondary renamed away"
        Assert-Equal 1 @($config.sets[1].windows | Where-Object { $_.id -eq "termx" }).Count "secondary renamed target"
        Assert-Equal 1 @($config.sets[0].windows | Where-Object { $_.id -eq "termalpha" }).Count "main duplicate intact"

        # Clone commands keep set-local identity and definitions.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-terminal", "main/termalpha", "main/termcopy")
        Assert-Equal 0 $result.ExitCode "same-set terminal clone exit"
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-app", "main/browser", "secondary/browser2")
        Assert-Equal 0 $result.ExitCode "cross-set app clone exit"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal "DevWS-main-termcopy" @($config.sets[0].windows | Where-Object { $_.id -eq "termcopy" })[0].windowId "same-set clone identity"
        Assert-Equal "main-browser.exe" @($config.sets[1].windows | Where-Object { $_.id -eq "browser2" })[0].match.value "cross-set clone uses the source definition"
        Assert-Equal $false @($config.sets[1].windows | Where-Object { $_.id -eq "browser2" })[0].enabled "app clone starts disabled"
        Assert-Equal "main" $config.defaultSet "defaultSet untouched by the matrix"
    }

    Test-Case "CLI cross-set clones target explicit sets with fresh identities" {
        $target = New-TwoSetConfigCopy "cli-cross-set-clones"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-terminal", "main/slot", "secondary/slot2")
        Assert-Equal 0 $result.ExitCode "cross-set clone exit"
        Assert-Contains $result.Output "Cloned terminal 'main/slot' -> 'secondary/slot2'." "cross-set clone message"
        Assert-Contains $result.Output "windowId: DevWS-secondary-slot2" "fresh set-qualified identity"

        $config    = Read-DevWSConfigFile -Path $target
        $mainSet   = @($config.sets | Where-Object { $_.id -eq "main" })[0]
        $secondSet = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]
        Assert-Equal 6 @($mainSet.windows).Count "main count unchanged"
        Assert-Equal 1 @($secondSet.windows | Where-Object { $_.id -eq "slot2" }).Count "clone landed in secondary"
        Assert-Equal 0 @($mainSet.windows | Where-Object { $_.id -eq "slot2" }).Count "clone did not land in main"
        Assert-Equal "DevWS-secondary-slot2" @($secondSet.windows | Where-Object { $_.id -eq "slot2" })[0].windowId "clone identity"
        Assert-Equal "DevWS-slot" @($mainSet.windows | Where-Object { $_.id -eq "slot" })[0].windowId "source identity untouched"

        # Unscoped target keeps the historical same-set behavior.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-terminal", "secondary/slot", "copy")
        Assert-Equal 0 $result.ExitCode "same-set clone exit"
        Assert-Contains $result.Output "Cloned terminal 'secondary/slot' -> 'secondary/copy'." "same-set clone message"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 1 @($config.sets[1].windows | Where-Object { $_.id -eq "copy" }).Count "copy landed in the source set"
        Assert-Equal 0 @($config.sets[0].windows | Where-Object { $_.id -eq "copy" }).Count "copy did not land in defaultSet"

        # Cross-set clone-app.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-app", "main/firefox", "secondary/firefox-dev")
        Assert-Equal 0 $result.ExitCode "cross-set app clone exit"
        Assert-Contains $result.Output "Cloned app 'main/firefox' -> 'secondary/firefox-dev'." "cross-set app clone message"

        $config = Read-DevWSConfigFile -Path $target
        $firefoxDev = @($config.sets[1].windows | Where-Object { $_.id -eq "firefox-dev" })[0]
        Assert-Equal $false $firefoxDev.enabled "app clone disabled"
        Assert-Equal "firefox.exe" $firefoxDev.match.value "app clone match copied"
        Assert-Equal $true @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "source app still enabled"

        # Unscoped clone-app target stays in the source set.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-app", "secondary/firefox", "firefox-copy")
        Assert-Equal 0 $result.ExitCode "same-set app clone exit"
        Assert-Contains $result.Output "Cloned app 'secondary/firefox' -> 'secondary/firefox-copy'." "same-set app clone message"

        # Failure: unknown target set.
        $stable = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("clone-terminal", "main/slot", "missing/copy")
        Assert-Equal 1 $result.ExitCode "unknown target set exit"
        Assert-Contains $result.Output "Unknown workspace set" "unknown target set error"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "unknown target set left bytes unchanged"
    }

