    Test-Case "lifecycle target resolver honors defaultSet without mutating it" {
        $target = New-LifecycleConfigCopy "lifecycle-target-resolver"
        $config = Read-DevWSConfigFile -Path $target

        $bare = Resolve-DevWSLifecycleTarget -Config $config
        Assert-Equal "main" $bare.SetId "bare target is defaultSet"
        Assert-Equal "main" $bare.Set.id "resolved set object returned"

        $explicit = Resolve-DevWSLifecycleTarget -Config $config -SetId "SECONDARY"
        Assert-Equal "secondary" $explicit.SetId "explicit target canonicalizes case"
