    Test-Case "launch and focus target the selected set and carry canonical setId" {
        $target = New-LifecycleConfigCopy "lifecycle-launch-focus"
        $calls  = [System.Collections.Generic.List[object]]::new()

        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            function Start-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = "worker-start"; WorkerKind = $Kind; Payload = $Payload })
                return [pscustomobject]@{ Kind = $Kind; TaskName = $TaskName; RequestId = "stub"; RequestPath = "stub-req"; ResultPath = "stub-res"; TimeoutSeconds = $TimeoutSeconds }
            }

            function Complete-DevWSWorkerRequest {
                param($Request)
                $calls.Add([pscustomobject]@{ Kind = "worker-complete"; WorkerKind = $Request.Kind })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = "worker"; WorkerKind = $Kind; Payload = $Payload })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                return @()
            }

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                $calls.Add([pscustomobject]@{ Kind = "resolve"; SetId = $SetId; AppId = [string]$App.id; Operation = $Operation })
                return [long](500000 + $calls.Count)
            }

            function Move-DevWSWindowHwnd {
                param([long]$Hwnd, $Layout, [string]$Context)
                $calls.Add([pscustomobject]@{ Kind = "move"; Hwnd = $Hwnd; Context = $Context; X = $Layout.x })
            }

            function Focus-DevWSWindowHwnd {
                param([long]$Hwnd, [string]$Context)
                $calls.Add([pscustomobject]@{ Kind = "focus"; Hwnd = $Hwnd; Context = $Context })
            }

            Invoke-DevWSLaunch -SetId "SECONDARY"

            $resolved = @($calls | Where-Object { $_.Kind -eq "resolve" })
            Assert-Equal 2 $resolved.Count "secondary launch resolves both secondary apps"
            Assert-Equal "browser,notes" ((@($resolved | ForEach-Object { $_.AppId })) -join ",") "secondary app definitions only"
            Assert-True (@($resolved | Where-Object { $_.SetId -ne "secondary" }).Count -eq 0) "launch resolutions are scoped to secondary"

            $moved = @($calls | Where-Object { $_.Kind -eq "move" })
            Assert-Equal 2 $moved.Count "each resolved app is moved exactly once"
            Assert-Equal "app 'secondary/browser',app 'secondary/notes'" ((@($moved | ForEach-Object { $_.Context })) -join ",") "move contexts name the scoped app"

            $workerStarts = @($calls | Where-Object { $_.Kind -eq "worker-start" })
            Assert-Equal 1 $workerStarts.Count "one launch worker request"
            Assert-Equal "launch" $workerStarts[0].WorkerKind "launch kind"
            Assert-Equal "secondary" $workerStarts[0].Payload.setId "canonical setId in launch payload"
            Assert-Equal 1 @($calls | Where-Object { $_.Kind -eq "worker-complete" }).Count "launch worker settled after apps"

            $calls.Clear()
            Invoke-DevWSFocus -SetId "secondary"

            $resolved = @($calls | Where-Object { $_.Kind -eq "resolve" })
            Assert-Equal 2 $resolved.Count "secondary focus resolves both secondary apps"
            Assert-True (@($resolved | Where-Object { $_.Operation -ne "focus" }).Count -eq 0) "focus operation reaches resolution"

            $focused = @($calls | Where-Object { $_.Kind -eq "focus" })
            Assert-Equal 2 $focused.Count "focus activates each resolved app"
            Assert-True (@($calls | Where-Object { $_.Kind -eq "move" }).Count -eq 0) "focus never moves windows"

            $workerCalls = @($calls | Where-Object { $_.Kind -eq "worker" })
            Assert-Equal 1 $workerCalls.Count "one focus worker request"
            Assert-Equal "focus" $workerCalls[0].WorkerKind "focus kind"
            Assert-Equal "secondary" $workerCalls[0].Payload.setId "canonical setId in focus payload"

            $calls.Clear()
            Invoke-DevWSLaunch

            $resolved = @($calls | Where-Object { $_.Kind -eq "resolve" })
            Assert-Equal "browser,editor" ((@($resolved | ForEach-Object { $_.AppId })) -join ",") "bare launch uses defaultSet apps"
            Assert-True (@($resolved | Where-Object { $_.SetId -ne "main" }).Count -eq 0) "bare launch resolutions target main"

            $workerStarts = @($calls | Where-Object { $_.Kind -eq "worker-start" })
            Assert-Equal "main" $workerStarts[0].Payload.setId "bare launch targets defaultSet"

            $calls.Clear()
            Assert-Throws { Invoke-DevWSLaunch -SetId "missing" } "Unknown workspace set"
            Assert-Equal 0 $calls.Count "unknown set performs no lifecycle work"

            $config = Read-DevWSConfigFile -Path $target
            Assert-Equal "main" $config.defaultSet "explicit lifecycle target never changes defaultSet"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

