    Test-Case "single reset resolves scoped references and sends set-scoped payloads" {
        $target = New-LifecycleConfigCopy "lifecycle-single-reset"
        $calls  = [System.Collections.Generic.List[object]]::new()

        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

