                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = $Kind; Payload = $Payload })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            Reset-DevWSTerminal -Reference "termalpha"
            Assert-Equal "main" $calls[0].Payload.setId "unscoped stable id targets defaultSet"
            Assert-Equal "termalpha" (@($calls[0].Payload.terminalPlacements | ForEach-Object { $_.id }) -join ",") "local id payload"
            Assert-Equal $true ([bool](@($calls[0].Payload.terminalPlacements)[0].move)) "profile-free reset carries an explicit frozen move decision"

            $calls.Clear()
            Reset-DevWSTerminal -Reference "2"
            Assert-Equal "main" $calls[0].Payload.setId "unscoped ordinal targets defaultSet"
            Assert-Equal "termbeta" (@($calls[0].Payload.terminalPlacements | ForEach-Object { $_.id }) -join ",") "ordinal resolves by default-set terminal order"

            $calls.Clear()
            Reset-DevWSTerminal -Reference "secondary/termbeta"
