            Assert-Equal "termbeta" (@($calls[0].Payload.terminalPlacements | ForEach-Object { $_.id }) -join ",") "scoped local id"

            $calls.Clear()
            Reset-DevWSTerminal -Reference "secondary/1"
            Assert-Equal "secondary" $calls[0].Payload.setId "literal numeric stable id resolves scoped"
            Assert-Equal "1" (@($calls[0].Payload.terminalPlacements | ForEach-Object { $_.id }) -join ",") "literal id used, not ordinal"

            $calls.Clear()
            $message = Get-ThrownMessage { Reset-DevWSTerminal -Reference "secondary/2" }
            Assert-Contains $message "numeric aliases" "scoped ordinal is never interpreted"
            Assert-Equal 0 $calls.Count "no worker request for rejected scoped ordinal"

            $calls.Clear()
            Reset-DevWSTerminal -Reference "secondary/offterm"
            Assert-Equal "offterm" (@($calls[0].Payload.terminalPlacements | ForEach-Object { $_.id }) -join ",") "explicit single reset of a disabled terminal is preserved"

            $calls.Clear()
            $message = Get-ThrownMessage { Reset-DevWSTerminal -Reference "secondary/nope" }
            Assert-Contains $message "Unknown workspace item" "unknown scoped item"
            Assert-Equal 0 $calls.Count "no worker request for unknown item"

            $config = Read-DevWSConfigFile -Path $target
            Assert-Equal "main" $config.defaultSet "reset never changes defaultSet"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

