    Test-Case "reset preflight state drives the worker-request gate" {
        $target  = New-LifecycleConfigCopy "reset-task-state"
        $calls   = [System.Collections.Generic.List[object]]::new()
        $queries = [System.Collections.Generic.List[string]]::new()
        $state   = 3

        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            function Get-DevWSRootScheduledTaskState {
                param([string]$TaskName)
                $queries.Add($TaskName)
                return $state
            }

            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = $Kind; Payload = $Payload })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            # Non-running state proceeds exactly as before.
            Reset-DevWSTerminal -Reference "termalpha"
            Assert-Equal 1 $queries.Count "one preflight state read"
            Assert-Equal "DevWorkspace-ElevatedReset" $queries[0] "preflight reads the reset task"
            Assert-Equal 1 $calls.Count "non-running state starts one worker request"

            # Running (4) blocks with the exact existing message.
            $state = 4
            $message = Get-ThrownMessage { Reset-DevWSTerminal -Reference "termalpha" }
            Assert-Equal "A workspace terminal reset is already running." $message "exact running-state message"
            Assert-Equal 1 $calls.Count "running state starts no worker request"

            # A helper failure (for example the task is missing) blocks too.
            function Get-DevWSRootScheduledTaskState {
                param([string]$TaskName)
                throw "Scheduled task '$TaskName' was not found in the root Task Scheduler folder; run install.ps1 to register the DevWS scheduled tasks."
            }

            $message = Get-ThrownMessage { Reset-DevWSTerminal -Reference "termalpha" }
            Assert-Contains $message "was not found" "helper failure surfaces before any request"
            Assert-Equal 1 $calls.Count "helper failure starts no worker request"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

