    Test-Case "reset task-state scope guards" {
        $ws = Get-SourceOf "src\ws.ps1"
        $start = $ws.IndexOf("function Invoke-DevWSTerminalReset")
        $end   = $ws.IndexOf("function Reset-DevWSTerminal")
        Assert-True ($start -ge 0 -and $end -gt $start) "reset preflight region located"
        $region = $ws.Substring($start, $end - $start)

        Assert-Contains $region "Get-DevWSRootScheduledTaskState" "reset preflight uses the exact-root state helper"
        Assert-NotContains $region "Get-ScheduledTask" "reset preflight performs no named cmdlet task lookup"
        Assert-Contains $region '$taskState -eq 4' "running-state boundary preserved"
        Assert-Contains $region "A workspace terminal reset is already running." "exact running message preserved"

        $protocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        Assert-Contains $protocol "function Get-DevWSRootScheduledTaskState" "state helper lives with controlled task invocation"
        Assert-Contains $protocol 'Get-DevWSTrustedSystemExecutable -Name "schtasks.exe"' "general worker startup resolves the trusted absolute schtasks"
        Assert-Contains $protocol 'Invoke-DevWSBoundedProcess' "general worker startup uses the bounded process runner"
        Assert-Contains $protocol "-Arguments @('/run', '/tn', `$TaskName)" "general worker startup still uses schtasks /run with token-verbatim arguments"
        Assert-NotContains $protocol 'schtasks.exe /run /tn' "no bare schtasks invocation remains"
        Assert-NotContains $protocol "Get-ScheduledTask" "worker protocol has no scheduled-task cmdlet lookup"

        # Scope guards: health snapshot and installer task behavior are unchanged.
        $health = Get-SourceOf "src\lib\devws-health.ps1"
        Assert-Contains $health "Get-DevWSHealthScheduledTaskIndex" "health one-snapshot implementation retained"
        Assert-NotContains $health "Get-ScheduledTask -TaskName" "health still has no named queries"

        $install = Get-SourceOf "src\lib\devws-install.ps1"
        Assert-Contains $install "Get-ScheduledTask -TaskName" "installer scheduled-task behavior unchanged"
    }

    Test-Case "save-layout targets one set atomically and keeps app input set-local" {
        $target = New-LifecycleConfigCopy "lifecycle-save-layout"
        $calls  = [System.Collections.Generic.List[object]]::new()

        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            $script:LifecycleCapture = [ordered]@{
                TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
                AppRects      = @{
                    browser = @{ x = 11; y = 12; w = 13; h = 14 }
                    notes   = @{ x = 21; y = 22; w = 23; h = 24 }
                }
                FailAppId     = $null
            }
            $script:LifecycleRectByHwnd = @{}

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                $calls.Add([pscustomobject]@{ Kind = "resolve"; SetId = $SetId; AppId = [string]$App.id; Operation = $Operation })

                if ($script:LifecycleCapture.FailAppId -eq [string]$App.id) {
                    throw "Application '$SetId/$($App.id)' window was not found; nothing was saved."
                }

                $hwnd = [long](700000 + $calls.Count)
                $rect = $script:LifecycleCapture.AppRects[[string]$App.id]
                $script:LifecycleRectByHwnd[$hwnd] = [pscustomobject]@{
                    Valid = $true
                    x     = [int]$rect.x
                    y     = [int]$rect.y
                    w     = [int]$rect.w
                    h     = [int]$rect.h
                }

                return $hwnd
            }

            function Get-DevWSWindowHwndRect {
                param([long]$Hwnd)
                return $script:LifecycleRectByHwnd[$Hwnd]
            }

            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = $Kind; Payload = $Payload })
                return (New-DevWSTestWorkerCaptureResult -Lines @($script:LifecycleCapture.TerminalLines))
            }

            $configBefore = Read-DevWSConfigFile -Path $target
            $mainBefore   = ConvertTo-Json -InputObject @($configBefore.sets[0].windows) -Depth 20
            $beforeAll    = Get-FileBase64 -Path $target

            $text = (& { Save-DevWSLayout -SetId "SECONDARY" } *>&1 | Out-String)
            Assert-Contains $text "Layout saved for set 'secondary'." "save-layout names the set"

            $resolved = @($calls | Where-Object { $_.Kind -eq "resolve" })
            Assert-Equal 2 $resolved.Count "secondary apps resolved for capture"
            Assert-Equal "browser,notes" ((@($resolved | ForEach-Object { $_.AppId })) -join ",") "capture input uses the secondary app definitions"
            Assert-True (@($resolved | Where-Object { $_.SetId -ne "secondary" }).Count -eq 0) "capture input excludes other sets"
            Assert-True (@($resolved | Where-Object { $_.Operation -ne "capture" }).Count -eq 0) "capture operation reaches resolution"

            $workerCalls = @($calls | Where-Object { $_.Kind -eq "capture" })
            Assert-Equal 1 $workerCalls.Count "one capture worker request"
            Assert-Equal "secondary" $workerCalls[0].Payload.setId "capture payload carries canonical setId"

            $config = Read-DevWSConfigFile -Path $target
            $mainAfter = ConvertTo-Json -InputObject @($config.sets[0].windows) -Depth 20
            Assert-Equal $mainBefore $mainAfter "main set is untouched by secondary save-layout"

            $secondary = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]
            Assert-Equal 11 @($secondary.windows | Where-Object { $_.id -eq "browser" })[0].layout.x "secondary app layout updated from its exact window"
            Assert-Equal 21 @($secondary.windows | Where-Object { $_.id -eq "notes" })[0].layout.x "secondary-only app layout updated"
            Assert-Equal 31 @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].layout.x "secondary terminal layout updated"
            Assert-Equal 51 @($secondary.windows | Where-Object { $_.id -eq "1" })[0].layout.x "literal-id terminal layout updated"
            Assert-Equal 0 @($secondary.windows | Where-Object { $_.id -eq "offterm" })[0].layout.x "disabled item untouched"
            Assert-Equal "main" $config.defaultSet "save-layout never changes defaultSet"

            $afterSuccess = Get-FileBase64 -Path $target

            # An unresolved app fails before any terminal capture or config write.
            $script:LifecycleCapture.FailAppId = "notes"
            Assert-Throws {
                Save-DevWSLayout -SetId "secondary"
            } "window was not found"
            Assert-Equal $afterSuccess (Get-FileBase64 -Path $target) "app resolution failure leaves canonical bytes unchanged"
            $script:LifecycleCapture.FailAppId = $null

            # Incomplete terminal capture fails all-or-nothing.
            $script:LifecycleCapture.TerminalLines = @("termalpha|31|32|33|34")
            Assert-Throws {
                Save-DevWSLayout -SetId "secondary"
            } "was not captured"
            Assert-Equal $afterSuccess (Get-FileBase64 -Path $target) "failed capture leaves canonical bytes unchanged"
            Assert-True ($beforeAll -ne $afterSuccess) "successful capture did change secondary layout"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "save-layout never reuses stale capture output" {
        $target = New-LifecycleConfigCopy "save-layout-stale"
        $calls  = [System.Collections.Generic.List[object]]::new()

        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target
        $env:DEVWS_STATE_ROOT = Join-Path $TestRoot "p2b-stale-seed-state"
        New-Item -ItemType Directory -Path $env:DEVWS_STATE_ROOT -Force | Out-Null

        try {
            $runtimeRoot = Get-DevWSRuntimeRoot

            # Seed COMPLETE stale capture files as if an earlier request had
            # succeeded. They must never be mistaken for current output.
            [System.IO.File]::WriteAllLines((Join-Path $runtimeRoot "capture-normal.txt"), @("browser|1|2|3|4", "notes|5|6|7|8"), [System.Text.UTF8Encoding]::new($false))
            [System.IO.File]::WriteAllLines((Join-Path $runtimeRoot "capture-elevated.txt"), @("termalpha|9|9|9|9", "termbeta|9|9|9|9", "1|9|9|9|9"), [System.Text.UTF8Encoding]::new($false))

            $before = Get-FileBase64 -Path $target

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                throw "stale-app-resolution-failure"
            }

            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = $Kind; Payload = $Payload })
                # Simulate a capture worker that completes with a protected claim
                # but produces no geometry file.
                return (New-DevWSTestWorkerCaptureResult)
            }

            # App resolution failing must never fall back to stale files.
            Assert-Throws {
                Save-DevWSLayout -SetId "secondary"
            } "stale-app-resolution-failure"

            Assert-Equal $before (Get-FileBase64 -Path $target) "stale capture never rewrites canonical config"
            Assert-True (-not (Test-Path -LiteralPath (Join-Path $runtimeRoot "capture-normal.txt"))) "stale app capture removed before capture"
            Assert-True (Test-Path -LiteralPath (Join-Path $runtimeRoot "capture-elevated.txt")) "the legacy state-root elevated capture is left in place and is never authority"

            # A capture worker that produces no geometry still fails atomically.
            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                return [long]720000
            }

            function Get-DevWSWindowHwndRect {
                param([long]$Hwnd)
                return [pscustomobject]@{ Valid = $true; x = 1; y = 2; w = 3; h = 4 }
            }

            Assert-Throws {
                Save-DevWSLayout -SetId "secondary"
            } "produced no geometry file"

            Assert-Equal $before (Get-FileBase64 -Path $target) "missing terminal geometry leaves canonical config unchanged"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

