    Test-Case "bare lifecycle commands follow defaultSet after set-default" {
        $target = New-LifecycleConfigCopy "lifecycle-default-switch"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-default", "secondary")
        Assert-Equal 0 $result.ExitCode "set-default exit"

        $calls = [System.Collections.Generic.List[object]]::new()

        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            # This case tests set selection/defaultSet semantics, not Task
            # Scheduler integration. Without this shadow the reset path reads the
            # host's real root task and only passes on a machine that has run
            # install.ps1, which makes the case depend on incidental host state.
            # TASK_STATE_READY (3) is a registered, non-running managed task, so
            # the reset path continues through the worker stubs below. The
            # shadow is scoped to this body and disappears with it.
            function Get-DevWSRootScheduledTaskState {
                param([string]$TaskName)
                return 3
            }

            function Start-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = "worker-start"; Payload = $Payload })
                return [pscustomobject]@{ Kind = $Kind; TaskName = $TaskName; RequestId = "stub"; RequestPath = "stub-req"; ResultPath = "stub-res"; TimeoutSeconds = $TimeoutSeconds }
            }

            function Complete-DevWSWorkerRequest {
                param($Request)
                $calls.Add([pscustomobject]@{ Kind = "worker-complete"; Payload = $null })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = $Kind; Payload = $Payload })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                return @()
            }

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                return [long]630000
            }

            function Move-DevWSWindowHwnd {
                param([long]$Hwnd, $Layout, [string]$Context)
            }

            function Focus-DevWSWindowHwnd {
                param([long]$Hwnd, [string]$Context)
            }

            Invoke-DevWSLaunch
            Assert-Equal "secondary" $calls[0].Payload.setId "bare launch follows the new default"

            $calls.Clear()
            Invoke-DevWSFocus
            Assert-Equal "secondary" $calls[0].Payload.setId "bare focus follows the new default"

            $layoutText = (& { Show-DevWSLayout } *>&1 | Out-String)
            Assert-Contains $layoutText "Saved layout for set 'secondary' (default)" "bare show-layout follows the new default"

            # Bare resets and unscoped config mutations follow the new default.
            $calls.Clear()
            Reset-DevWSTerminal -Reference "termbeta"
            Assert-Equal "secondary" $calls[0].Payload.setId "bare stable-id reset follows the new default"

            $calls.Clear()
            Reset-DevWSTerminal -Reference "2"
            Assert-Equal "secondary" $calls[0].Payload.setId "bare numeric reset follows the new default"
            Assert-Equal "termbeta" (@($calls[0].Payload.terminalPlacements | ForEach-Object { $_.id }) -join ",") "numeric alias resolves inside the new default set"

            $calls.Clear()
            Reset-DevWSTerminals -SkipConfirmation
            Assert-Equal "secondary" $calls[0].Payload.setId "bare reset-terminals follows the new default"

            Invoke-DevWSDisableItem -Reference "browser"
            $config = Read-DevWSConfigFile -Path $target
            Assert-Equal $false @($config.sets[1].windows | Where-Object { $_.id -eq "browser" })[0].enabled "bare disable targets the new default"
            Assert-Equal $true @($config.sets[0].windows | Where-Object { $_.id -eq "browser" })[0].enabled "main duplicate app untouched"

            # Explicit main targets never switch the default back.
            $calls.Clear()
            Invoke-DevWSLaunch -SetId "main"
            Assert-Equal "main" $calls[0].Payload.setId "explicit main launch"

            $mainText = (& { Show-DevWSList -SetId "main" } *>&1 | Out-String)
            Assert-Contains $mainText "WORKSPACE: main" "explicit main list"

            # CLI child helpers remove DEVWS_CONFIG in their finally block, so
            # this runs last inside the DEVWS_CONFIG scope.
            $list = Invoke-WsCli -ConfigPath $target -Arguments @("list")
            Assert-Contains $list.Output "WORKSPACE: secondary (default)" "bare list follows the new default"

            $config = Read-DevWSConfigFile -Path $target
            Assert-Equal "secondary" $config.defaultSet "explicit main targeting does not change defaultSet"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "workers require a target set before any lifecycle work" {
        $target = New-LifecycleConfigCopy "worker-setid-guards"
        $probeFixture = New-WorkerProbeFixture "worker-setid-guards-state"

        $cases = @(
            @{ Worker = "elevated.ps1";         Kind = "launch" },
            @{ Worker = "elevated-focus.ps1";   Kind = "focus" },
            @{ Worker = "elevated-capture.ps1"; Kind = "capture" },
            @{ Worker = "elevated-reset.ps1";   Kind = "reset" }
        )

        foreach ($case in $cases) {
            $workerPath = Join-Path $RepoRoot ("src\workers\" + $case.Worker)

            $missing = Invoke-FreshWorkerRun `
                -WorkerPath $workerPath `
                -ConfigPath $probeFixture.ConfigPath `
                -StateRoot $probeFixture.StateRoot `
                -Kind $case.Kind `
                -RequestId ([guid]::NewGuid().ToString()) `
                -Payload @{}

            Assert-Equal $false ([bool]$missing.Result.ok) "$($case.Worker) fails without a setId"
            Assert-Contains ([string]$missing.Result.message) "setId" "$($case.Worker) names the required setId"
            Assert-Equal 0 $missing.ExitCode "$($case.Worker) rejects cleanly without a crash"

            $unknownPayload = @{ setId = "missing-set" }

            if ($case.Kind -eq "reset") {
                # The transport schema requires placements before the worker can
                # even resolve the set; supply a well-formed placement so the
                # unknown-set contract itself is exercised.
                $unknownPayload["terminalPlacements"] = @([ordered]@{ id = "probe"; move = $true; x = 0; y = 0; w = 100; h = 100 })
            }

            $unknown = Invoke-FreshWorkerRun `
                -WorkerPath $workerPath `
                -ConfigPath $probeFixture.ConfigPath `
                -StateRoot $probeFixture.StateRoot `
                -Kind $case.Kind `
                -RequestId ([guid]::NewGuid().ToString()) `
                -Payload $unknownPayload

            Assert-Equal $false ([bool]$unknown.Result.ok) "$($case.Worker) fails for an unknown set"
            Assert-Contains ([string]$unknown.Result.message) "Unknown workspace set" "$($case.Worker) message for an unknown set"

            if ($case.Kind -eq "reset") {
                # A valid set with no placement records is still an invalid
                # request and must fail before any destructive work.
                $empty = Invoke-FreshWorkerRun `
                    -WorkerPath $workerPath `
                    -ConfigPath $probeFixture.ConfigPath `
                    -StateRoot $probeFixture.StateRoot `
                    -Kind $case.Kind `
                    -RequestId ([guid]::NewGuid().ToString()) `
                    -Payload @{ setId = "main" }

                Assert-Equal $false ([bool]$empty.Result.ok) "reset without placements fails"
                Assert-Contains ([string]$empty.Result.message) "terminalPlacements" "reset names the required placements"
            }
        }
    }

    Test-Case "workers enumerate and identify terminals strictly by the requested set" {
        foreach ($worker in @("elevated.ps1", "elevated-focus.ps1", "elevated-capture.ps1", "elevated-reset.ps1")) {
            $source = Get-SourceOf ("src\workers\" + $worker)

            Assert-Contains $source 'Test-DevWSProperty -Object $payload -Name "setId"' "$worker validates setId presence"
            Assert-Contains $source "Resolve-DevWSLifecycleTarget" "$worker resolves the requested set"
