            foreach ($line in @($source -split "`n" | Where-Object { $_ -match 'Get-DevWSWindows -Config' })) {
                Assert-Contains $line '-Set $target.Set' "$worker enumerates with the explicit target set"
            }

            Assert-NotContains $source 'Get-DevWSDefaultSet' "$worker never falls back to defaultSet"

            foreach ($line in @($source -split "`n" | Where-Object { $_ -match 'Resolve-DevWSTerminalHwnd' })) {
                Assert-Contains $line "-SetId" "$worker identifies with a set-scoped key"
            }

            foreach ($line in @($source -split "`n" | Where-Object { $_ -match 'Update-DevWSRuntimeTerminal' })) {
                Assert-Contains $line "-SetId" "$worker updates set-scoped state"
            }
        }
    }

    Test-Case "CLI set management is config-only, ordered, and guarded" {
        $target = New-WritableConfigCopy "cli-set-management"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("sets")
        Assert-Equal 0 $result.ExitCode "sets exit"
        Assert-Contains $result.Output "* main" "default marker"
        Assert-Contains $result.Output "6 items" "main item count"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("sets", "secondary")
        Assert-Equal 1 $result.ExitCode "sets extra arg exit"
        Assert-Contains $result.Output "does not accept additional arguments" "sets refuses extra arguments"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-set", "secondary")
        Assert-Equal 0 $result.ExitCode "add-set exit"
        Assert-Contains $result.Output "Added set 'secondary' (0 items)." "add-set output"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal "main,secondary" (@($config.sets).id -join ",") "set appended in order"
        Assert-Equal "main" $config.defaultSet "default unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("sets")
        Assert-Contains $result.Output "secondary" "second set listed"
        Assert-Contains $result.Output "0 items" "empty count listed"

        $stable = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-set", "SECONDARY")
        Assert-Equal 1 $result.ExitCode "duplicate set exit"
        Assert-Contains $result.Output "already exists" "duplicate set error"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-set", "bad/id")
        Assert-Equal 1 $result.ExitCode "slash set id exit"
        Assert-Contains $result.Output "reserved" "slash set id error"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-set", "bad id")
        Assert-Equal 1 $result.ExitCode "spaced set id exit"
        Assert-Contains $result.Output "may only contain" "spaced set id error"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "failed adds left bytes unchanged"

        # Confirmation: declining leaves bytes and the set intact.
        $env:DEVWS_CONFIG = $target

        try {
            $output = "n" | & pwsh -NoLogo -NoProfile -File $WsScript remove-set secondary 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        Assert-Equal 0 $code "cancelled exit"
        Assert-Contains $output "Cancelled" "cancellation output"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "cancelled removal left bytes unchanged"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("remove-set", "main", "-Force")
        Assert-Equal 1 $result.ExitCode "default refusal exit"
        Assert-Contains $result.Output "Cannot remove the default set" "default refusal"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("remove-set", "secondary", "-Force")
        Assert-Equal 0 $result.ExitCode "remove-set exit"
        Assert-Contains $result.Output "Removed set 'secondary' from the configuration." "removal output"
        Assert-Contains $result.Output "No window was closed" "config-only notice"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 1 @($config.sets).Count "set removed"
        Assert-Equal "main" $config.defaultSet "default unchanged by removal"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("remove-set", "nope", "-Force")
        Assert-Equal 1 $result.ExitCode "unknown set exit"
        Assert-Contains $result.Output "Unknown workspace set" "unknown set error"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("remove-set", "main", "-Force")
        Assert-Equal 1 $result.ExitCode "last set exit"
        Assert-Contains $result.Output "last remaining set" "last set refusal"

        # set-default
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("add-set", "secondary")
        Assert-Equal 0 $result.ExitCode "re-add exit"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-default", "secondary")
        Assert-Equal 0 $result.ExitCode "set-default exit"
        Assert-Contains $result.Output "Default set is now 'secondary'." "set-default output"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal "secondary" $config.defaultSet "default switched"
        Assert-Equal "main,secondary" (@($config.sets).id -join ",") "sets unchanged by switch"

        $stable = Get-FileBase64 -Path $target
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-default", "secondary")
        Assert-Equal 0 $result.ExitCode "already-default exit"
        Assert-Contains $result.Output "already the default set" "already-default output"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "already-default is a no-op without rewrite"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-default", "nope")
        Assert-Equal 1 $result.ExitCode "unknown default exit"
        Assert-Contains $result.Output "Unknown workspace set" "unknown default error"
        Assert-Equal $stable (Get-FileBase64 -Path $target) "unknown default left bytes unchanged"
    }

    Test-Case "config-only and read-only commands leave runtime state and requests untouched" {
        $target    = New-LifecycleConfigCopy "state-invariants"
        $stateRoot = Join-Path $TestRoot "state-invariants-root"
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = $stateRoot

        $snapshot = {
            return (@(Get-ChildItem -LiteralPath $stateRoot -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }) -join "|")
        }

        try {
            $configCommands = @(
                @("enable", "main/termalpha"),
                @("disable", "main/termalpha"),
                @("set-path", "main/termalpha", $TestRoot),
                @("set-command", "main/termalpha", "invariant-tool", "--flag"),
                @("set-geometry", "main/termalpha", "--x", "1", "--y", "2", "--width", "3", "--height", "4"),
                @("rename", "main/termalpha", "termx"),
                @("clone-terminal", "main/termx", "copy"),
                @("add-terminal", "main/newterm", $TestRoot),
                @("remove", "main/newterm", "-Force"),
                @("set-match", "main/editor", "exe", "editor.exe"),
                @("set-app-args", "main/editor", "--flag"),
                @("clone-app", "main/editor", "editor2"),
                @("set-launch", "main/editor2", "exe", "C:\Apps\editor2.exe"),
                @("add-set", "hs"),
                @("remove-set", "hs", "-Force"),
                @("set-default", "main")
            )

            foreach ($arguments in $configCommands) {
                $before = & $snapshot
                $result = Invoke-WsCli -ConfigPath $target -Arguments $arguments
                Assert-Equal 0 $result.ExitCode ("config-only exit for: " + ($arguments -join " "))
                Assert-Equal $before (& $snapshot) ("no runtime/request files after: " + ($arguments -join " "))
            }

            # Read-only commands leave runtime state and config untouched.
            $configBefore = Get-FileBase64 -Path $target
            $readOnly = @(
                @("sets"),
                @("list"),
                @("list", "secondary"),
                @("show", "main"),
                @("show-layout", "secondary"),
                @("detect-app", "zzz-no-such-process-xyz-42")
            )

            foreach ($arguments in $readOnly) {
                $before = & $snapshot
                $result = Invoke-WsCli -ConfigPath $target -Arguments $arguments
                Assert-Equal 0 $result.ExitCode ("read-only exit for: " + ($arguments -join " "))
                Assert-Equal $before (& $snapshot) ("no runtime/request files after: " + ($arguments -join " "))
            }

            Assert-Equal $configBefore (Get-FileBase64 -Path $target) "read-only commands left config bytes unchanged"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

