        Assert-Contains $result.Output "Disabled 'firefox' [app]." "bare label remains bare"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $false @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "bare command now targets secondary"
        Assert-Equal $false @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "main keeps its own state"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("enable", "firefox")
        Assert-Equal 0 $result.ExitCode "bare enable after switch exit"

        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal $true @($config.sets[1].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "bare enable targets secondary"
        Assert-Equal $false @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].enabled "main stays disabled"

        # Helper-level: unscoped selection follows the new defaultSet.
        Assert-Equal "secondary" (Get-DevWSDefaultSet -Config $config).id "helper default follows"
        Assert-Equal "secondary" (Resolve-DevWSConfigReference -Config $config -Reference "firefox").SetId "bare reference follows"
        $bareApps = @(Get-DevWSWindows -Config $config -Type app)
        Assert-Equal $true @($bareApps | Where-Object { $_.id -eq "firefox" })[0].enabled "unscoped selection follows the new default"
    }

    Test-Case "CLI set-geometry updates saved geometry only" {
        $target = New-WritableConfigCopy "cli-set-geometry"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-geometry", "firefox", "--x", "633", "--y", "0", "--width", "1294", "--height", "1407")
        Assert-Equal 0 $result.ExitCode "set-geometry exit"
        Assert-Contains $result.Output "Updated layout for 'firefox'." "update message"
        Assert-Contains $result.Output "old: x=" "old rectangle shown"
        Assert-Contains $result.Output "new: x=633 y=0 w=1294 h=1407" "new rectangle shown"
        Assert-Contains $result.Output "not moved or resized" "config-only notice"

        $config = Read-DevWSConfigFile -Path $target
        $firefox = @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal 633 $firefox.layout.x "x stored"
        Assert-Equal 1407 $firefox.layout.h "h stored"
        Assert-Equal "exe" $firefox.launch.kind "app launch preserved"

        # Negative coordinates and single-dash long switches survive the
        # generic argument pass-through.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-geometry", "slot", "-x", "-7", "-y", "-3", "-width", "654", "-height", "1407")
        Assert-Equal 0 $result.ExitCode "short/negative exit"
        $config = Read-DevWSConfigFile -Path $target
        $slot = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal -7 $slot.layout.x "negative x stored"
        Assert-Equal -3 $slot.layout.y "negative y stored"
        Assert-Equal 654 $slot.layout.w "single-dash width stored"

        # Canonical mixed form.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-geometry", "slot", "--x", "-7", "--y", "0", "--width", "700", "--height", "800")
        Assert-Equal 0 $result.ExitCode "mixed form exit"
        $config = Read-DevWSConfigFile -Path $target
        $slot = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal 700 $slot.layout.w "mixed form stored"
    }

    Test-Case "CLI set-geometry rejects invalid geometry without touching bytes" {
        $target = New-WritableConfigCopy "cli-set-geometry-bad"
        $stable = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $failures = @(
            @{ Name = "non-integer";     Args = @("set-geometry", "firefox", "--x", "nope", "--y", "0", "--width", "100", "--height", "100"); Error = "requires an integer value" },
            @{ Name = "decimal";         Args = @("set-geometry", "firefox", "--x", "1.5", "--y", "0", "--width", "100", "--height", "100"); Error = "requires an integer value" },
            @{ Name = "width zero";      Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "0", "--height", "100"); Error = "Width must be greater than 0" },
            @{ Name = "height negative"; Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "100", "--height", "-1"); Error = "Height must be greater than 0" },
            @{ Name = "duplicate x";     Args = @("set-geometry", "firefox", "--x", "0", "--x", "1", "--y", "0", "--width", "100", "--height", "100"); Error = "Duplicate switch" },
            @{ Name = "duplicate width"; Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "1", "--width", "2", "--height", "100"); Error = "Duplicate switch" },
            @{ Name = "unknown switch";  Args = @("set-geometry", "firefox", "--z", "0", "--x", "0", "--y", "0", "--width", "100", "--height", "100"); Error = "Unknown switch" },
            @{ Name = "old -w switch";   Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "-w", "100", "--height", "100"); Error = "Unknown switch" },
            @{ Name = "old --w switch";  Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--w", "100", "--height", "100"); Error = "Unknown switch" },
            @{ Name = "old -h switch";   Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "100", "-h", "100"); Error = "Unknown switch" },
            @{ Name = "old --h switch";  Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "100", "--h", "100"); Error = "Unknown switch" },
            @{ Name = "missing field";   Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "100"); Error = "Usage: ws set-geometry" },
            @{ Name = "no switches";     Args = @("set-geometry", "firefox"); Error = "Usage: ws set-geometry" },
            @{ Name = "unknown id";      Args = @("set-geometry", "nope", "--x", "0", "--y", "0", "--width", "100", "--height", "100"); Error = "Unknown workspace item" },
            @{ Name = "numeric id";      Args = @("set-geometry", "9", "--x", "0", "--y", "0", "--width", "100", "--height", "100"); Error = "numeric aliases" }
        )

        foreach ($failure in $failures) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $failure.Args
            Assert-Equal 1 $result.ExitCode "$($failure.Name) exit"
            Assert-Contains $result.Output $failure.Error "$($failure.Name) error"
            Assert-Equal $stable ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "$($failure.Name) left bytes unchanged"
        }
    }

    Test-Case "CLI passes literal -w arguments through to commands" {
        $target = New-WritableConfigCopy "cli-literal-w"

        # A literal -w token must reach configured command arguments instead
        # of being captured by a ws.ps1 parameter.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "slot", "some-tool", "-w", "5")
        Assert-Equal 0 $result.ExitCode "set-command exit"

        $config = Read-DevWSConfigFile -Path $target
        $slot = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal "some-tool" $slot.tabs[0].command "command stored"
        Assert-Equal 2 @($slot.tabs[0].args).Count "two literal command arguments"
        Assert-Equal "-w" $slot.tabs[0].args[0] "first command argument"
        Assert-Equal "5" $slot.tabs[0].args[1] "second command argument"

        # Same pass-through for app launch arguments.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-app-args", "firefox", "-w", "5")
        Assert-Equal 0 $result.ExitCode "set-app-args exit"

        $config = Read-DevWSConfigFile -Path $target
        $firefox = @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal 2 @($firefox.launch.args).Count "two literal app arguments"
        Assert-Equal "-w" $firefox.launch.args[0] "first app argument"
        Assert-Equal "5" $firefox.launch.args[1] "second app argument"

        # The double-dash spelling also stays literal.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "slot", "other-tool", "--w", "6")
        Assert-Equal 0 $result.ExitCode "double-dash exit"

        $config = Read-DevWSConfigFile -Path $target
        $slot = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal 2 @($slot.tabs[0].args).Count "two double-dash arguments"
        Assert-Equal "--w" $slot.tabs[0].args[0] "double-dash argument literal"
        Assert-Equal "6" $slot.tabs[0].args[1] "double-dash value"

        # Other common-parameter-looking tool arguments stay literal too.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-command", "slot", "third-tool", "-e", "-i", "--private-window")
        Assert-Equal 0 $result.ExitCode "common-parameter-looking exit"

        $config = Read-DevWSConfigFile -Path $target
        $slot = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal "-e,-i,--private-window" (@($slot.tabs[0].args) -join ",") "common-parameter-looking arguments literal"

        # The top-level script must not reserve -w again.
        $source = Get-SourceOf "src\ws.ps1"
        Assert-NotContains $source '[string]$W' "ws.ps1 must not declare a global W parameter"
        Assert-NotContains $source 'ValueFromRemainingArguments' "ws.ps1 must use simple binding so -w passes through"
    }

    Test-Case "CLI reset-layout restores matching layouts and reports skips" {
        # reset-layout restores from the SHIPPED bundled default. The shipped
        # starter is deliberately empty, so this case runs the real CLI from a
        # disposable repository copy whose bundled default is the rich fixture.
        $repo = New-TestRepoRoot "cli-reset-layout" -RichBundledDefault
        $target = New-WritableConfigCopy "cli-reset-layout-cfg"

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("rename", "slot", "backend")
        Assert-Equal 0 $result.ExitCode "rename exit"
        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("add-app", "spotify", "exe", "C:\spotify.exe", "exe", "spotify.exe", "dedicated")
        Assert-Equal 0 $result.ExitCode "add-app exit"
        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("set-geometry", "firefox", "--x", "1", "--y", "2", "--width", "3", "--height", "4")
        Assert-Equal 0 $result.ExitCode "scramble exit"

        $config = Read-DevWSConfigFile -Path $target
        $spotify = @($config.sets[0].windows | Where-Object { $_.id -eq "spotify" })[0]
        $spotifyBefore = "$($spotify.layout.x),$($spotify.layout.y),$($spotify.layout.w),$($spotify.layout.h)"

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("reset-layout", "-Force")
        Assert-Equal 0 $result.ExitCode "reset-layout exit"
        Assert-Contains $result.Output "Restored saved layout for 6 item(s):" "restored count"
        Assert-Contains $result.Output "backend <- bundled terminal 'slot' via windowId DevWS-slot" "windowId fallback reported"
        Assert-Contains $result.Output "Skipped 1 item(s) with no bundled default match:" "skipped header"
        Assert-Contains $result.Output "spotify" "skipped item listed"
        Assert-Contains $result.Output "no live windows were moved or resized" "config-only notice"

        $config = Read-DevWSConfigFile -Path $target
        $firefox = @($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal 1294 $firefox.layout.w "default width restored"
        Assert-Equal 1407 $firefox.layout.h "default height restored"
        $spotify = @($config.sets[0].windows | Where-Object { $_.id -eq "spotify" })[0]
        Assert-Equal $spotifyBefore "$($spotify.layout.x),$($spotify.layout.y),$($spotify.layout.w),$($spotify.layout.h)" "unmatched item layout untouched"
        Assert-Equal 7 @($config.sets[0].windows).Count "no items added or removed"
    }

    Test-Case "CLI reset-layout confirmation declines cleanly and -Force or --force skip it" {
        # reset-layout restores from the SHIPPED bundled default (see the
        # previous case): run the real CLI from a disposable repository copy.
        $repo = New-TestRepoRoot "cli-reset-confirm-repo" -RichBundledDefault
        $target = New-WritableConfigCopy "cli-reset-confirm"

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("set-geometry", "firefox", "--x", "9", "--y", "9", "--width", "9", "--height", "9")
        Assert-Equal 0 $result.ExitCode "scramble exit"
        $scrambled = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $env:DEVWS_CONFIG = $target

        try {
            $output = "n" | & pwsh -NoLogo -NoProfile -File $repo.Script reset-layout 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        Assert-Equal 0 $code "declined exit"
        Assert-Contains $output "Cancelled" "cancellation message"
        Assert-Equal $scrambled ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "declined reset left bytes unchanged"

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("reset-layout", "-Force")
        Assert-Equal 0 $result.ExitCode "-Force exit"
        Assert-Contains $result.Output "Restored saved layout" "-Force skipped the prompt"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 1294 (@($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].layout.w) "-Force restored geometry"

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("set-geometry", "firefox", "--x", "9", "--y", "9", "--width", "9", "--height", "9")
        Assert-Equal 0 $result.ExitCode "rescramble exit"

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("reset-layout", "--force")
        Assert-Equal 0 $result.ExitCode "--force exit"
        Assert-Contains $result.Output "Restored saved layout" "--force skipped the prompt"
        $config = Read-DevWSConfigFile -Path $target
        Assert-Equal 1294 (@($config.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].layout.w) "--force restored geometry"
    }

