    Test-Case "CLI reset-layout with no matches rewrites nothing" {
        $dir = Join-Path $TestRoot "cli-reset-nomatch"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $target = Join-Path $dir "workspace.json"

        $json = @'
{
  "version": 3,
  "defaultSet": "main",
  "bindings": [],
  "sets": [
    {
      "id": "main",
      "windows": [
        {
          "id": "customterm",
          "type": "terminal",
          "enabled": true,
          "windowId": "DevWS-customterm",
          "path": "C:\\Temp",
          "elevated": true,
          "tabs": [ { "command": null, "args": [] } ],
          "activeTab": 0,
          "layout": { "x": 11, "y": 12, "w": 13, "h": 14 }
        },
        {
          "id": "customapp",
          "type": "app",
          "enabled": true,
          "match": { "kind": "exe", "value": "customapp.exe" },
          "launch": { "kind": "exe", "value": "C:\\customapp.exe", "args": [] },
          "instanceMode": "dedicated",
          "layout": { "x": 21, "y": 22, "w": 23, "h": 24 }
        }
      ]
    }
  ]
}
'@
        Set-Content -LiteralPath $target -Value $json -Encoding UTF8
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $result = Invoke-WsCli -ScriptPath $repo.Script -ConfigPath $target -Arguments @("reset-layout", "-Force")
        Assert-Equal 0 $result.ExitCode "no-match exit"
        Assert-Contains $result.Output "No configured items matched the bundled default layout." "explicit no-match message"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "no rewrite when nothing matches"
    }

    Test-Case "CLI app mutations accept ids freed by terminal rename" {
