        }

        $source = Get-SourceOf "src\ws.ps1"

        $start = $source.IndexOf("function Invoke-DevWSSetGeometry")
        $end   = $source.IndexOf("function Invoke-DevWSSetPath")
        Assert-True ($start -ge 0 -and $end -gt $start) "layout commands located"

        $region = $source.Substring($start, $end - $start)

        foreach ($functionName in @(
            "function Invoke-DevWSSetGeometry",
            "function Invoke-DevWSResetLayout"
        )) {
            Assert-Contains $region $functionName "checked region contains $functionName"
        }

        foreach ($forbidden in @(
            "Invoke-DevWSWorkerRequest",
            "schtasks",
            "Start-Process",
            "Reset-DevWSTerminal",
            "Invoke-DevWSLaunch",
            "Invoke-DevWSFocus",
            "Get-DevWSWindowsTerminalPath",
            "Invoke-DevWSAppLaunchCommand", "Resolve-DevWSAppLifecycleWindow",
            "Save-DevWSLayout",
            "Move-DevWSWindow",
            "Update-DevWSRuntimeTerminal"
        )) {
            Assert-NotContains $region $forbidden "layout commands must not invoke lifecycle: $forbidden"
        }

        Assert-Contains $region "Save-DevWSConfig" "layout commands persist through the atomic save"
        Assert-Contains $region "Find-DevWSBundledDefaultConfig" "reset-layout reads the bundled default independently"
    }

    Write-Host ""
    Start-TestGroup -Name 'tools' -Title 'Tools (edit, doctor, detect-app)'

    Test-Case "editor specs classify VS Code family and plain editors" {
        foreach ($name in @("code", "code.cmd", "code.exe", "code-insiders", "code-insiders.cmd", "codium", "codium.cmd")) {
            $spec = New-DevWSEditorSpec -Name $name -Path (Join-Path "C:\tools" $name)
            Assert-Equal "vscode" $spec.Family "$name is VS Code family"
            Assert-Equal "--wait" (@($spec.Arguments) -join " ") "$name waits for the session"
        }

        Assert-True (-not (Test-DevWSVsCodeEditorName -Name "notepad.exe")) "notepad is not VS Code"
        Assert-True (-not (Test-DevWSVsCodeEditorName -Name "vim")) "vim is not VS Code"
        Assert-True (-not (Test-DevWSVsCodeEditorName -Name "")) "empty name is not VS Code"

        $notepad = New-DevWSEditorSpec -Name "notepad.exe" -Path "C:\Windows\System32\notepad.exe"
        Assert-Equal "other" $notepad.Family "notepad family"
        Assert-Equal 0 @($notepad.Arguments).Count "notepad has no extra arguments"
    }

    Test-Case "editor selection uses DEVWS_EDITOR, falls back to notepad, and waits for exit" {
        $stub = New-EditorStub -Name "select-editor-stub"

        $spec = Get-DevWSEditorSpec -EditorOverride $stub
        Assert-Equal $stub $spec.Path "override path used"
        Assert-Equal "other" $spec.Family "stub family"
        Assert-Equal 0 @($spec.Arguments).Count "stub has no extra arguments"

        Assert-Throws {
            Get-DevWSEditorSpec -EditorOverride "definitely-missing-editor-xyz-42"
        } "DEVWS_EDITOR" "invalid override rejected"

        $fallback = Get-DevWSEditorSpec -EditorOverride "" -PreferredEditor "definitely-missing-editor-xyz-42"
        Assert-Equal "other" $fallback.Family "fallback family"
        Assert-True ($fallback.Path -like "*notepad*") "fallback is notepad"

        $saved = $env:DEVWS_EDITOR

        try {
            $env:DEVWS_EDITOR = $stub
            $fromEnv = Get-DevWSEditorSpec
            Assert-Equal $stub $fromEnv.Path "DEVWS_EDITOR takes precedence"
        }
        finally {
            if ($null -eq $saved) {
                Remove-Item Env:\DEVWS_EDITOR -ErrorAction SilentlyContinue
            }
            else {
                $env:DEVWS_EDITOR = $saved
            }
        }

        # The invocation waits for the editor to exit: the marker is written
        # after a delay and must exist once the call returns.
        $marker = Join-Path $TestRoot "editor-waited-marker.txt"
        $slowStub = New-EditorStub -Name "slow-editor-stub" -DelayMarkerPath $marker
        $subject = Join-Path $TestRoot "editor-waited-file.json"
        Set-Content -LiteralPath $subject -Value "{}" -Encoding UTF8

        $watch = [System.Diagnostics.Stopwatch]::StartNew()
        $exitCode = Invoke-DevWSEditorFile -FilePath $subject -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $slowStub)
        $watch.Stop()

        Assert-Equal 0 $exitCode "slow editor exit code"
        Assert-True (Test-Path -LiteralPath $marker) "waited for the editor process to finish"
        Assert-True ($watch.ElapsedMilliseconds -ge 900) "did not return before the editor exited"
    }

    Test-Case "edit session saves valid edits from a temporary copy atomically" {
        $target = New-WritableConfigCopy "edit-session-valid"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $edited = Read-DevWSConfigFile -Path $target
        ($edited.sets[0].windows | Where-Object { $_.id -eq "antigravity" }).enabled = $false
        $replacement = Join-Path $TestRoot "edit-session-valid-replacement.json"
        $edited | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $replacement -Encoding UTF8

        $viewLog = Join-Path $TestRoot "edit-session-valid-editor-view.json"
        $stub = New-EditorStub -Name "edit-session-valid-stub" -ReplacementPath $replacement -ViewLogPath $viewLog

        $statePath = Get-DevWSStatePath
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 4711
        Save-DevWSRuntimeState -State $state -Path $statePath
        $stateBefore = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))

        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target
        $result = Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $stub)

        Assert-Equal "saved" $result.Status "session reports saved"
        Assert-True ($result.TempPath -ne $target) "editor worked on a temporary copy"
        Assert-True ((Split-Path -Leaf $result.TempPath) -like "devws-edit-*.json") "temporary copy naming"

        Assert-True (Test-Path -LiteralPath $viewLog) "editor view captured"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($viewLog))) "editor received the current canonical bytes"

        $saved = Read-DevWSConfigFile -Path $target
        Assert-Equal $false ($saved.sets[0].windows | Where-Object { $_.id -eq "antigravity" }).enabled "valid edit persisted"
        Assert-DevWSConfig -Config $saved -Source "test"
        Assert-True (-not (Test-Path -LiteralPath $result.TempPath)) "temporary copy cleaned up"
        Assert-Equal $stateBefore ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))) "runtime state untouched"

        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
    }

    Test-Case "edit session preserves canonical config for invalid edits" {
        $target = New-WritableConfigCopy "edit-session-invalid"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))
        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target
        $preserved = @()

        # Malformed JSON.
        $broken = Join-Path $TestRoot "edit-session-broken.json"
        Set-Content -LiteralPath $broken -Value '{ "version": 3, "sets": [' -Encoding UTF8
        $brokenStub = New-EditorStub -Name "edit-session-broken-stub" -ReplacementPath $broken

        $message = Get-ThrownMessage {
            [void](Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $brokenStub))
        }

        Assert-Contains $message "Edited config is invalid" "broken JSON rejected"
        Assert-Contains $message "Canonical config was not changed" "broken JSON leaves canonical untouched"
        Assert-Contains $message "preserved at" "broken JSON copy preserved"
        $preserved += ($message -split "`n")[-1].Trim()

        # Valid JSON that fails schema validation.
        $schema = Join-Path $TestRoot "edit-session-schema.json"
        $schemaConfig = Get-TestWorkspaceConfig
        $schemaConfig.sets[0].windows[0].layout.w = 0
        $schemaConfig | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $schema -Encoding UTF8
        $schemaStub = New-EditorStub -Name "edit-session-schema-stub" -ReplacementPath $schema

        $message = Get-ThrownMessage {
            [void](Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $schemaStub))
        }

        Assert-Contains $message "Edited config is invalid" "schema-invalid config rejected"
        Assert-Contains $message "layout.w" "schema error names the field"
        $preserved += ($message -split "`n")[-1].Trim()

        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "canonical bytes unchanged for both invalid edits"

        foreach ($file in $preserved) {
            Assert-True (Test-Path -LiteralPath $file -PathType Leaf) "invalid edited copy preserved: $file"
            Remove-Item -LiteralPath $file -Force
        }
    }

    Test-Case "edit session reports no changes without rewriting canonical config" {
        $target = New-WritableConfigCopy "edit-session-nochange"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))
        $written = (Get-Item -LiteralPath $target).LastWriteTimeUtc
        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target
        $stub = New-EditorStub -Name "edit-session-nochange-stub"

        $result = Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $stub)

        Assert-Equal "unchanged" $result.Status "no-change status"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "canonical bytes unchanged"
        Assert-Equal $written (Get-Item -LiteralPath $target).LastWriteTimeUtc "canonical file not rewritten"
        Assert-True (-not (Test-Path -LiteralPath $result.TempPath)) "temporary copy cleaned up"
    }

    Test-Case "editor failures leave canonical config unchanged and preserve modified copies" {
        $target = New-WritableConfigCopy "edit-session-failure"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))
        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target

        $noopFail = New-EditorStub -Name "edit-session-fail-noop" -ExitCode 5
        $message = Get-ThrownMessage {
            [void](Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $noopFail))
        }

        Assert-Contains $message "exited with code 5" "editor failure reported"
        Assert-Contains $message "Canonical config was not changed" "plain failure leaves canonical untouched"
        Assert-NotContains $message "preserved at" "unchanged failure keeps no copy"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "canonical bytes unchanged after plain failure"
        Assert-Equal 0 @(Get-ChildItem -Path (Get-DevWSRuntimeRoot) -Filter "devws-edit-*.json" -File -ErrorAction SilentlyContinue).Count "no leftover copies from plain failure"

        $edited = Read-DevWSConfigFile -Path $target
        ($edited.sets[0].windows | Where-Object { $_.id -eq "antigravity" }).enabled = $false
        $replacement = Join-Path $TestRoot "edit-session-failure-replacement.json"
        $edited | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $replacement -Encoding UTF8

        $modFail = New-EditorStub -Name "edit-session-fail-modified" -ReplacementPath $replacement -ExitCode 5
        $message = Get-ThrownMessage {
            [void](Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $modFail))
        }

        Assert-Contains $message "preserved at" "modified failure preserves the copy"
        $preserved = ($message -split "`n")[-1].Trim()
        Assert-True (Test-Path -LiteralPath $preserved -PathType Leaf) "modified copy exists"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "canonical bytes unchanged after modified failure"

        Remove-Item -LiteralPath $preserved -Force
    }

