        )

        $text = (& { Invoke-DevWSDoctorCheck -Summary $okSummary } *>&1 | Out-String)
        Assert-Contains $text "DevWS doctor" "doctor heading"
        Assert-Contains $text "[ok]" "pass marker"
        Assert-Contains $text "Health check PASSED" "pass summary"
        Assert-Equal 0 (Get-DevWSDoctorExitCode -Summary $okSummary) "pass exit code"

        $badSummary = Get-DevWSHealthSummary -Results @(
            (New-DevWSHealthCheckResult -Id "os-windows" -Description "Windows" -Ok $true -Message "ok"),
            (New-DevWSHealthCheckResult -Id "task-runlevel" -Description "Task run level" -Ok $false -Message "check failed")
