        Assert-Contains $text "Task run level" "failed check description visible"
        Assert-Contains $text "Health check FAILED" "fail summary"
        Assert-Equal 1 (Get-DevWSDoctorExitCode -Summary $badSummary) "fail exit code"

        $returned = Invoke-DevWSDoctorCheck -Summary $okSummary 6>$null
        Assert-True $returned.Ok "summary returned to the caller"
    }

