    Test-Case "detect-app config matching reports scoped identity and explicit modes" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated"),
                (New-TestMatchedAppDefinition -Id "codex" -MatchKind "exe" -MatchValue "ChatGPT.exe" -InstanceMode "shared")
            )),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated"),
                (New-TestMatchedAppDefinition -Id "codex" -MatchKind "exe" -MatchValue "ChatGPT.exe" -InstanceMode "shared")
            ))
        )

        $firefox = New-TestWindowCandidate -Hwnd 1001 -ProcessId 111
        $matches = @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $firefox)

        Assert-Equal 2 $matches.Count "same id in two sets yields two scoped matches"
        Assert-Equal "main/firefox,secondary/firefox" (@($matches | ForEach-Object { $_.ScopedId }) -join ",") "scoped identity preserves set order"
        Assert-Equal "dedicated,dedicated" (@($matches | ForEach-Object { $_.InstanceMode }) -join ",") "explicit mode reported"
        Assert-Equal "firefox" $matches[0].ItemId "item id retained beside the set id"
        Assert-Equal "secondary" $matches[1].SetId "second match keeps its set"
        Assert-Equal "firefox.exe" ([string]$matches[0].App.match.value) "underlying app definition is exposed"

        $codexCandidate = New-TestWindowCandidate -Hwnd 2002 -ProcessId 222 -ProcessName "ChatGPT" -ProcessPath "C:\Program Files\WindowsApps\OpenAI\ChatGPT.exe" -Title "ChatGPT"
        $codexMatches = @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $codexCandidate)
        Assert-Equal "main/codex,secondary/codex" (@($codexMatches | ForEach-Object { $_.ScopedId }) -join ",") "shared matches keep scoped identity"
        Assert-Equal "shared,shared" (@($codexMatches | ForEach-Object { $_.InstanceMode }) -join ",") "shared mode reported"

        $hidden = New-TestWindowCandidate -Hwnd 3003 -Visible $false
        Assert-Equal 0 @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $hidden).Count "hidden candidates never match"

        $spotify = New-TestWindowCandidate -Hwnd 4004 -ProcessId 444 -ProcessName "spotify" -ProcessPath "C:\Apps\Spotify.exe" -Title "Spotify" -Class "Chrome_WidgetWin_1"
        Assert-Equal 0 @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $spotify).Count "unconfigured candidate has no matches"

        Assert-Equal "firefox" (Get-DevWSConfiguredAppDefinition -Config $config -ScopedId "SECONDARY/FIREFOX").id "definition lookup is scoped and case-insensitive"
        Assert-Equal $null (Get-DevWSConfiguredAppDefinition -Config $config -ScopedId "main/missing") "unknown scoped definition is null"
    }

    Test-Case "detect-app probe keeps one row per HWND and never tags windows" {
        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"))

        $first  = New-TestWindowCandidate -Hwnd 1001 -ProcessId 111
        $second = New-TestWindowCandidate -Hwnd 1002 -ProcessId 111 -Title "Mozilla Firefox (second)"

        $probed = @(Get-DevWSAppWindowProbe -Config $config -Candidates @($first, $second))

        Assert-Equal 2 $probed.Count "one probe record per visible top-level HWND"
        Assert-Equal "1001,1002" (@($probed | ForEach-Object { $_.hwnd }) -join ",") "multiple windows from one PID stay separate"
        Assert-Equal $null $probed[0].ownerKey "probe never invents ownership"
        Assert-Equal $null $probed[0].ownerError "clean probe has no ownership error"

        # Read-only: probing must not add or remove any ownership property.
        Assert-NotContains (Get-SourceOf "src\lib\devws-app-window.ps1") "SetPropW" "app-window probe never sets ownership"
    }

    Test-Case "detect-app filter matches scoped diagnostic fields case-insensitively" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated")
            )),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated")
            ))
        )

        $candidate = New-TestWindowCandidate -Hwnd 1001 -ProcessId 111
        $matches = @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $candidate)

        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "firefox") "process name"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "FIREFOX.EXE") "exe filename case-insensitive"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "Mozilla Firefox") "window title"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "MozillaWindowClass") "window class"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "program files") "executable path"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "main/firefox") "scoped configured match"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "secondary/firefox [dedicated]") "scoped match with explicit mode"
        Assert-True (-not (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "spotify")) "no false match"
        Assert-True (Test-DevWSDetectAppFilter -Candidate $candidate -Matches $matches -Filter "") "empty filter matches everything"
    }

    Test-Case "detect-app shows ownership, mismatch, corruption, and suggestions read-only" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated"),
                (New-TestMatchedAppDefinition -Id "codex" -MatchKind "exe" -MatchValue "ChatGPT.exe" -InstanceMode "shared")
            ))
        )

        $firefoxDefinition = Get-DevWSConfiguredAppDefinition -Config $config -ScopedId "main/firefox"
        $codexDefinition   = Get-DevWSConfiguredAppDefinition -Config $config -ScopedId "main/codex"

        # Owned dedicated window: exact scoped owner shown, no mismatch.
        $owned = New-TestWindowCandidate -Hwnd 1001 -ProcessId 111 -OwnerKey "main/firefox"
        $ownedMatches = @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $owned)
        $ownedText = (@(Get-DevWSDetectAppLines -Candidate $owned -Matches $ownedMatches -OwnerApp $firefoxDefinition)) -join "`n"

        Assert-Contains $ownedText "firefox.exe" "process header"
        Assert-Contains $ownedText "hwnd:        1001" "hwnd line"
        Assert-Contains $ownedText "pid:         111" "pid line"
        Assert-Contains $ownedText "title:       Mozilla Firefox" "title line"
        Assert-Contains $ownedText "class:       MozillaWindowClass" "class line"
        Assert-Contains $ownedText "exe:        firefox.exe" "exe line"
        Assert-Contains $ownedText "path:       C:\Program Files\Mozilla Firefox\firefox.exe" "path line"
        Assert-Contains $ownedText "ownership:  main/firefox" "active dedicated owner shown"
        Assert-Contains $ownedText "configured:" "configured block"
        Assert-Contains $ownedText "main/firefox [dedicated]" "scoped match with mode"
        Assert-NotContains $ownedText "owner status: mismatch" "matching owner is not a mismatch"

        # Shared window: correctly unowned, scoped shared match, no fake owner.
        $shared = New-TestWindowCandidate -Hwnd 2002 -ProcessId 222 -ProcessName "ChatGPT" -ProcessPath "C:\Program Files\WindowsApps\OpenAI\ChatGPT.exe" -Title "ChatGPT" -Class "Chrome_WidgetWin_1"
        $sharedMatches = @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $shared)
        $sharedText = (@(Get-DevWSDetectAppLines -Candidate $shared -Matches $sharedMatches -OwnerApp $codexDefinition)) -join "`n"

        Assert-Contains $sharedText "ownership:  (unowned)" "shared windows remain unowned"
        Assert-Contains $sharedText "main/codex [shared]" "shared scoped match shown"
        Assert-NotContains $sharedText "ownership:  main/" "no fake shared owner label"
        Assert-NotContains $sharedText "owner status" "unowned windows have no owner status"

        # Owner no longer matches its configured definition: flagged, not repaired.
        $mismatch = New-TestWindowCandidate -Hwnd 3003 -ProcessId 333 -ProcessName "notepad" -ProcessPath "C:\Windows\notepad.exe" -Title "Untitled - Notepad" -Class "Notepad" -OwnerKey "main/firefox"
        $mismatchText = (@(Get-DevWSDetectAppLines -Candidate $mismatch -Matches @() -OwnerApp $firefoxDefinition)) -join "`n"

        Assert-Contains $mismatchText "ownership:  main/firefox" "stale owner key still shown"
        Assert-Contains $mismatchText "owner status: mismatch" "owner/definition mismatch flagged"
        Assert-Contains $mismatchText "configured: (none)" "mismatched window has no configured match"
        Assert-Contains $mismatchText "suggested match:  exe notepad.exe" "suggestion still derived"

        # Corruption is surfaced verbatim and never guessed away.
        $corrupt = New-TestWindowCandidate -Hwnd 4004 -ProcessId 444 -OwnerError "HWND 4004 carries multiple DevWS ownership properties (a, b). Refusing to guess an owner."
        $corruptText = (@(Get-DevWSDetectAppLines -Candidate $corrupt -Matches @() -OwnerApp $null)) -join "`n"

        Assert-Contains $corruptText "ownership:  corruption: HWND 4004 carries multiple DevWS ownership properties" "corruption surfaced verbatim"
        Assert-NotContains $corruptText "owner status" "corruption never picks an owner"

        # Owner key without a current definition is reported as unknown.
        $unknown = New-TestWindowCandidate -Hwnd 5005 -ProcessId 555 -OwnerKey "main/firefox"
        $unknownText = (@(Get-DevWSDetectAppLines -Candidate $unknown -Matches @() -OwnerApp $null)) -join "`n"
        Assert-Contains $unknownText "owner status: unknown" "missing definition reported instead of guessing"

        # Unconfigured candidate keeps actionable suggestions.
        $spotify = New-TestWindowCandidate -Hwnd 6006 -ProcessId 666 -ProcessName "spotify" -ProcessPath "C:\Apps\Spotify.exe" -Title "Spotify" -Class "Chrome_WidgetWin_1"

        Assert-Equal 0 @(Get-DevWSConfiguredAppWindowMatches -Config $config -Candidate $spotify).Count "no configured match"

        $suggestedText = (@(Get-DevWSDetectAppLines -Candidate $spotify -Matches @() -OwnerApp $null)) -join "`n"
        Assert-Contains $suggestedText "configured: (none)" "none marker"
        Assert-Contains $suggestedText "ownership:  (unowned)" "unowned marker"
        Assert-Contains $suggestedText "suggested match:  exe Spotify.exe" "suggested match"
        Assert-Contains $suggestedText "suggested launch: exe C:\Apps\Spotify.exe" "suggested launch"

        # Unreadable executable path is stated, never invented.
        $packaged = New-TestWindowCandidate -Hwnd 7007 -ProcessId 777 -ProcessName "packagedapp" -ProcessPath "" -Title "Packaged"

        $packagedText = (@(Get-DevWSDetectAppLines -Candidate $packaged -Matches @() -OwnerApp $null)) -join "`n"
        Assert-Contains $packagedText "exe:        packagedapp.exe" "derived exe name"
        Assert-Contains $packagedText "path:       unavailable" "unavailable path shown"
        Assert-Contains $packagedText "suggested match:  exe packagedapp.exe" "derived suggestion"
        Assert-Contains $packagedText "suggested launch: unavailable (executable path is unreadable)" "no invented launch path"
        Assert-NotContains $packagedText "appId" "no AppID fabricated"
        Assert-NotContains $packagedText "!App" "no AppID fabricated"
    }

    Test-Case "CLI detect-app reports no matches without touching config or state" {
        $target = New-WritableConfigCopy "cli-detect-app"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $statePath = Get-DevWSStatePath
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 999
        Save-DevWSRuntimeState -State $state -Path $statePath
        $stateBefore = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("detect-app", "zzz-no-such-process-xyz-42")
        Assert-Equal 0 $result.ExitCode "detect-app exit"
        Assert-Contains $result.Output "No visible application windows matched 'zzz-no-such-process-xyz-42'." "actionable no-match message"

        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "config bytes unchanged"
        Assert-Equal $stateBefore ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))) "runtime state unchanged"

        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
    }

    Test-Case "ws health and ws doctor share the diagnostics implementation" {
        $okSummary = Get-DevWSHealthSummary -Results @(
            (New-DevWSHealthCheckResult -Id "os-windows" -Description "Windows" -Ok $true -Message "ok")
        )

