    Write-Host ""
    Start-TestGroup -Name 'ownership' -Title 'Phase 8 app ownership foundation'

    # Test-only native helper: a disposable message-only window, never a real
    # application window. Used by the ownership round-trip test below.
    if (-not ([System.Management.Automation.PSTypeName]'DevWSTestOwnershipWindow').Type) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public static class DevWSTestOwnershipWindow
{
    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr CreateWindowExW(uint dwExStyle, string lpClassName, string lpWindowName, uint dwStyle, int x, int y, int nWidth, int nHeight, IntPtr hWndParent, IntPtr hMenu, IntPtr hInstance, IntPtr lpParam);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool DestroyWindow(IntPtr hWnd);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);

    [StructLayout(LayoutKind.Sequential)]
    public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }

    public static IntPtr Create()
    {
        // HWND_MESSAGE == (IntPtr)(-3): a message-only window that is never
        // visible and never behaves like a real application window.
        return CreateWindowExW(0, "STATIC", "", 0, 0, 0, 0, 0, new IntPtr(-3), IntPtr.Zero, IntPtr.Zero, IntPtr.Zero);
    }

    public static IntPtr CreatePopup()
    {
        // WS_POPUP == 0x80000000: a real top-level window that is never shown.
        // It is enumerable but not visible (no visible side effects).
        return CreateWindowExW(0, "STATIC", "", 0x80000000u, 0, 0, 0, 0, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero);
    }

    public static bool Destroy(IntPtr hWnd)
    {
        return DestroyWindow(hWnd);
    }

    public static int[] Rect(IntPtr hWnd)
    {
        RECT r;
        if (!GetWindowRect(hWnd, out r)) return null;
        return new int[] { r.Left, r.Top, r.Right - r.Left, r.Bottom - r.Top };
    }
}
'@ -ErrorAction Stop
    }

    Test-Case "ownership property names are deterministic and validated" {
        Assert-Equal "DevWS.Owner.v1.main/editor" (Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "editor") "canonical property name"
        Assert-Equal "DevWS.Owner.v1.main/editor" (Get-DevWSAppOwnershipPropertyName -SetId "MAIN" -ItemId "Editor") "case-insensitive normalization"
        Assert-Equal "DevWS.Owner.v1.set-1.a/agent.2" (Get-DevWSAppOwnershipPropertyName -SetId "Set-1.A" -ItemId "Agent.2") "stable-id character family preserved"
        Assert-True ((Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "editor") -ne (Get-DevWSAppOwnershipPropertyName -SetId "secondary" -ItemId "editor")) "distinct sets generate distinct property names"
        Assert-True ((Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "editor") -ne (Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "browser")) "distinct items generate distinct property names"
        Assert-Contains (Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "editor") "DevWS.Owner.v1." "versioned reserved prefix"

        foreach ($emptyId in @("", "   ")) {
            Assert-Throws { Get-DevWSAppOwnershipPropertyName -SetId $emptyId -ItemId "editor" } "non-empty" "empty set id '$emptyId' rejected"
        }

        foreach ($badId in @("hello world", "foo\bar", "foo:bar")) {
            Assert-Throws { Get-DevWSAppOwnershipPropertyName -SetId $badId -ItemId "editor" } "unsupported characters" "invalid set id '$badId' rejected"
        }

        Assert-Throws { Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "" } "non-empty" "empty item id rejected"
        Assert-Throws { Get-DevWSAppOwnershipPropertyName -SetId "main/item" -ItemId "editor" } "must not contain" "slash in set id rejected"
        Assert-Throws { Get-DevWSAppOwnershipPropertyName -SetId "main" -ItemId "a/b" } "must not contain" "slash in item id rejected"
    }

    Test-Case "ownership lookup is bounded and rejects malformed candidates" {
        $candidates = @(
            [pscustomobject]@{ SetId = "main"; ItemId = "editor" },
            [pscustomobject]@{ SetId = "secondary"; ItemId = "editor" }
        )

        # No live window: no ownership and no guessing.
        Assert-True ($null -eq (Get-DevWSAppOwnership -Hwnd 0 -Candidates $candidates)) "zero HWND is unowned"
        Assert-True ($null -eq (Get-DevWSAppOwnership -Hwnd 99999999 -Candidates $candidates)) "destroyed HWND is unowned"

        # Candidate shape validation happens before any window work.
        Assert-Throws { Get-DevWSAppOwnership -Hwnd 0 -Candidates @("editor") } "scoped identity" "unscoped string candidate rejected"
        Assert-Throws { Get-DevWSAppOwnership -Hwnd 0 -Candidates @("main/editor/extra") } "scoped identity" "multi-slash candidate rejected"
        Assert-Throws { Get-DevWSAppOwnership -Hwnd 0 -Candidates @($null) } "null" "null candidate rejected"
        Assert-Throws {
            Get-DevWSAppOwnership -Hwnd 0 -Candidates @([pscustomobject]@{ SetId = "main"; ItemId = "bad id" })
        } "unsupported characters" "invalid id candidate rejected"
    }

    Test-Case "ownership descriptors normalize once and deduplicate" {
        $descriptors = @(Get-DevWSAppOwnershipDescriptors -Candidates @(
            [pscustomobject]@{ SetId = "MAIN"; ItemId = "Editor" },
            "main/editor",
            "secondary/agent"
        ))

        Assert-Equal 2 $descriptors.Count "duplicate property names are deduplicated"
        Assert-Equal "MAIN" $descriptors[0].SetId "first candidate set casing is canonical"
        Assert-Equal "Editor" $descriptors[0].ItemId "first candidate item casing is canonical"
        Assert-Equal "DevWS.Owner.v1.main/editor" $descriptors[0].PropertyName "canonical descriptor property name"
        Assert-Equal "DevWS.Owner.v1.secondary/agent" $descriptors[1].PropertyName "later descriptor preserved"

        Assert-Equal 0 @(Get-DevWSAppOwnershipDescriptors -Candidates @()).Count "empty candidate set yields no descriptors"

        Assert-Throws { Get-DevWSAppOwnershipDescriptors -Candidates @("editor") } "scoped identity" "unscoped string candidate rejected"
        Assert-Throws { Get-DevWSAppOwnershipDescriptors -Candidates @("main/editor/extra") } "scoped identity" "multi-slash candidate rejected"
        Assert-Throws { Get-DevWSAppOwnershipDescriptors -Candidates @($null) } "null" "null candidate rejected"
        Assert-Throws {
            Get-DevWSAppOwnershipDescriptors -Candidates @([pscustomobject]@{ SetId = "main"; ItemId = "bad id" })
        } "unsupported characters" "invalid id candidate rejected"
    }

    Test-Case "ownership round-trips on a disposable message-only window" {
        $testWindow = [DevWSTestOwnershipWindow]::Create()

        if ($testWindow -eq [IntPtr]::Zero) {
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        $h = [long]$testWindow

        try {
            Assert-True (-not (Test-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor")) "fresh window is unowned"

            $setName = Set-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor"
            Assert-Equal "DevWS.Owner.v1.main/editor" $setName "set returns the exact property name"
            Assert-True (Test-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor") "tagged window reports owned"
            Assert-True (-not (Test-DevWSAppOwnership -Hwnd $h -SetId "secondary" -ItemId "editor")) "other scoped candidate stays unowned"

            $owner = Get-DevWSAppOwnership -Hwnd $h -Candidates @(
                [pscustomobject]@{ SetId = "secondary"; ItemId = "editor" },
                [pscustomobject]@{ SetId = "main"; ItemId = "editor" }
            )
            Assert-Equal "main" $owner.SetId "lookup returns the matching set id"
            Assert-Equal "editor" $owner.ItemId "lookup returns the canonical candidate item"
            Assert-Equal "DevWS.Owner.v1.main/editor" $owner.PropertyName "lookup reports the exact property"

            # Duplicate normalized candidates are not an ambiguity.
            $duplicate = Get-DevWSAppOwnership -Hwnd $h -Candidates @("MAIN/Editor", "main/editor")
            Assert-Equal "MAIN" $duplicate.SetId "first candidate casing is canonical"
            Assert-Equal "Editor" $duplicate.ItemId "first candidate item casing is canonical"

            # Two distinct candidate keys on one window must refuse to guess.
            $null = Set-DevWSAppOwnership -Hwnd $h -SetId "secondary" -ItemId "editor"
            $message = Get-ThrownMessage {
                Get-DevWSAppOwnership -Hwnd $h -Candidates @("main/editor", "secondary/editor")
            }
            Assert-Contains $message "multiple DevWS ownership properties" "ambiguous ownership is reported"

            # Explicit removal distinguishes removed from already absent.
            Assert-Equal "removed" (Remove-DevWSAppOwnership -Hwnd $h -SetId "secondary" -ItemId "editor").Result "second key removed"
            Assert-Equal "removed" (Remove-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor").Result "first key removed"
            Assert-Equal "absent" (Remove-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor").Result "second removal reports absent"
            Assert-True (-not (Test-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor")) "removed window is unowned again"

            # Destroying the HWND ends the ownership; no durable record remains.
            Assert-True ([DevWSTestOwnershipWindow]::Destroy($testWindow)) "test window destroyed"
            Assert-True (-not (Test-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor")) "destroyed HWND is unowned"
            Assert-Equal "window-gone" (Remove-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor").Result "removal on destroyed HWND reports window-gone"
        }
        finally {
            # Harmless if the window is already destroyed.
            [void][DevWSTestOwnershipWindow]::Destroy($testWindow)
        }

        Assert-Throws { Set-DevWSAppOwnership -Hwnd 0 -SetId "main" -ItemId "editor" } "not a valid window handle" "set rejects a zero HWND"
        Assert-Throws { Set-DevWSAppOwnership -Hwnd 99999999 -SetId "main" -ItemId "editor" } "no longer exists" "set rejects a dead HWND"
    }

    Test-Case "descriptor ownership lookup matches the public primitive on a disposable window" {
        $testWindow = [DevWSTestOwnershipWindow]::Create()

        if ($testWindow -eq [IntPtr]::Zero) {
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        $h = [long]$testWindow

        try {
            $descriptors = @(Get-DevWSAppOwnershipDescriptors -Candidates @("secondary/editor", "main/editor"))

            Assert-True ($null -eq (Get-DevWSAppOwnershipFromDescriptors -Hwnd $h -Descriptors $descriptors)) "untagged window is unowned"
            Assert-True ($null -eq (Get-DevWSAppOwnershipFromDescriptors -Hwnd 0 -Descriptors $descriptors)) "zero HWND is unowned"
            Assert-True ($null -eq (Get-DevWSAppOwnershipFromDescriptors -Hwnd 99999999 -Descriptors $descriptors)) "dead HWND is unowned"

            $null = Set-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor"

            $viaDescriptors = Get-DevWSAppOwnershipFromDescriptors -Hwnd $h -Descriptors $descriptors
            $viaPublic      = Get-DevWSAppOwnership -Hwnd $h -Candidates @("secondary/editor", "main/editor")

            Assert-Equal "main" $viaDescriptors.SetId "descriptor lookup returns the matching set id"
            Assert-Equal "editor" $viaDescriptors.ItemId "descriptor lookup returns the canonical item"
            Assert-Equal "DevWS.Owner.v1.main/editor" $viaDescriptors.PropertyName "descriptor lookup reports the exact property"
            Assert-Equal $viaPublic.SetId $viaDescriptors.SetId "descriptor and public lookups agree on set"
            Assert-Equal $viaPublic.ItemId $viaDescriptors.ItemId "descriptor and public lookups agree on item"

            $null = Set-DevWSAppOwnership -Hwnd $h -SetId "secondary" -ItemId "editor"
            $message = Get-ThrownMessage { Get-DevWSAppOwnershipFromDescriptors -Hwnd $h -Descriptors $descriptors }
            Assert-Contains $message "multiple DevWS ownership properties" "descriptor lookup refuses ambiguous ownership"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($testWindow)
        }
    }

    Test-Case "ownership probing stays strict for lifecycle and tolerant for detect-app" {
        $testWindow = [DevWSTestOwnershipWindow]::Create()

        if ($testWindow -eq [IntPtr]::Zero) {
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        $h = [long]$testWindow
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TestMatchedAppDefinition -Id "editor" -MatchKind "exe" -MatchValue "test.exe" -InstanceMode "dedicated"))),
            (New-TestSet -Id "secondary" -Windows @((New-TestMatchedAppDefinition -Id "editor" -MatchKind "exe" -MatchValue "test.exe" -InstanceMode "dedicated")))
        )

        $candidates = @([pscustomobject]@{
            hwnd = $h; pid = 1; processName = "test"; processPath = "C:\Apps\test.exe"
            visible = $true; class = "TestWindow"; title = "Test"
        })

        try {
            $clean = @(Get-DevWSAppWindowProbe -Config $config -Candidates $candidates -TolerantOwnership)
            Assert-Equal 1 $clean.Count "clean disposable window is probed"
            Assert-Equal $null $clean[0].ownerKey "clean window is unowned"
            Assert-Equal $null $clean[0].ownerError "clean window has no ownership error"

            $null = Set-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor"
            $null = Set-DevWSAppOwnership -Hwnd $h -SetId "secondary" -ItemId "editor"

            Assert-Throws {
                $null = Get-DevWSAppWindowProbe -Config $config -Candidates $candidates
            } "multiple DevWS ownership properties" "lifecycle probing stays strict about ownership corruption"

            $tolerant = @(Get-DevWSAppWindowProbe -Config $config -Candidates $candidates -TolerantOwnership)
            Assert-Equal 1 $tolerant.Count "tolerant probe still returns the window"
            Assert-Contains ([string]$tolerant[0].ownerError) "multiple DevWS ownership properties" "tolerant probe captures the corruption verbatim"
            Assert-Equal $null $tolerant[0].ownerKey "tolerant probe never guesses an owner"

            $lines = (@(Get-DevWSDetectAppLines -Candidate $tolerant[0] -Matches @() -OwnerApp $null)) -join "`n"
            Assert-Contains $lines "ownership:  corruption: HWND $h carries multiple DevWS ownership properties" "detect-app surfaces the corruption"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($testWindow)
        }
    }

    Test-Case "final v3 validation requires a canonical explicit instanceMode" {
        # Missing instanceMode is invalid at runtime, but remains recognizable by
        # the installer-only relaxed path for enrichment.
        $withoutMode = ConvertTo-TestConfig -Windows @((New-AppDefinition -Id "editor" -InstanceMode ""))
        $missingMessage = Get-ThrownMessage { Assert-DevWSConfig -Config $withoutMode -Source "test" }
        Assert-Contains $missingMessage "missing 'instanceMode'" "missing mode rejected by final validation"
        Assert-DevWSPreInstanceModeV3Config -Config $withoutMode -Source "test"
        Assert-True ($null -eq (Get-DevWSAppInstanceMode -Item $withoutMode.sets[0].windows[0])) "missing mode yields null for legacy/malformed objects"

        foreach ($mode in @("dedicated", "shared")) {
            $app = New-AppDefinition -Id "editor" -InstanceMode $mode
            $config = ConvertTo-TestConfig -Windows @($app)
            Assert-DevWSConfig -Config $config -Source "test"
            Assert-Equal $mode (Get-DevWSAppInstanceMode -Item $config.sets[0].windows[0]) "explicit '$mode' is read back"
        }

        foreach ($badMode in @("Dedicated", "SHARED", "both", "", " shared", "shared ")) {
            $app = New-AppDefinition -Id "editor" -InstanceMode ""
            $app["instanceMode"] = $badMode

            Assert-Throws {
                Assert-DevWSConfig -Config (ConvertTo-TestConfig -Windows @($app)) -Source "test"
            } "instanceMode" "non-canonical mode '$badMode' rejected"

            Assert-Throws {
                Assert-DevWSPreInstanceModeV3Config -Config (ConvertTo-TestConfig -Windows @($app)) -Source "test"
            } "instanceMode" "relaxed recognition still rejects invalid explicit mode '$badMode'"
        }

        $nullMode = New-AppDefinition -Id "editor" -InstanceMode ""
        $nullMode["instanceMode"] = $null
        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Windows @($nullMode)) -Source "test"
        } "instanceMode" "null instanceMode rejected"

        $numberMode = New-AppDefinition -Id "editor" -InstanceMode ""
        $numberMode["instanceMode"] = 1
        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Windows @($numberMode)) -Source "test"
        } "instanceMode" "non-string instanceMode rejected"

        # Terminals never use the app instance-mode vocabulary.
        $terminal = New-TerminalDefinition -Id "editor"
        $terminal["instanceMode"] = "shared"
        Assert-Throws {
            Assert-DevWSConfig -Config (ConvertTo-TestConfig -Windows @($terminal)) -Source "test"
        } "instanceMode" "terminal instanceMode rejected"
        Assert-Throws {
            Assert-DevWSPreInstanceModeV3Config -Config (ConvertTo-TestConfig -Windows @($terminal)) -Source "test"
        } "instanceMode" "relaxed recognition rejects terminal instanceMode too"
        Assert-True ($null -eq (Get-DevWSAppInstanceMode -Item (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0])) "helper ignores terminals"
    }

    Test-Case "explicit cross-set instance modes must not contradict" {
        foreach ($mode in @("shared", "dedicated")) {
            $mainApp = New-AppDefinition -Id "editor"
            $mainApp["instanceMode"] = $mode
            $otherApp = New-AppDefinition -Id "editor"
            $otherApp["instanceMode"] = $mode

            $config = ConvertTo-TestConfig -Sets @(
                (New-TestSet -Id "main" -Windows @($mainApp)),
                (New-TestSet -Id "secondary" -Windows @($otherApp))
            )

            Assert-DevWSConfig -Config $config -Source "test"
        }

        # Contradiction across sets is rejected case-insensitively on the id.
        $sharedApp = New-AppDefinition -Id "Editor"
        $sharedApp["instanceMode"] = "shared"
        $dedicatedApp = New-AppDefinition -Id "editor"
        $dedicatedApp["instanceMode"] = "dedicated"

        $contradiction = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($sharedApp)),
            (New-TestSet -Id "secondary" -Windows @($dedicatedApp))
        )

        $message = Get-ThrownMessage { Assert-DevWSConfig -Config $contradiction -Source "test" }
        Assert-Contains $message "one instance mode across sets" "shared/dedicated contradiction rejected"
        Assert-Contains $message "editor" "contradiction names the app id"

        # Explicit in one set + missing in another is no longer valid runtime
        # v3 (final validation requires every app mode), but the installer-only
        # relaxed recognizer still accepts it for enrichment.
        $explicitApp = New-AppDefinition -Id "editor"
        $explicitApp["instanceMode"] = "dedicated"
        $missingApp = New-AppDefinition -Id "editor" -InstanceMode ""

        $transitional = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($explicitApp)),
            (New-TestSet -Id "secondary" -Windows @($missingApp))
        )

        Assert-Throws {
            Assert-DevWSConfig -Config $transitional -Source "test"
        } "missing 'instanceMode'" "final validation rejects explicit + missing"

        Assert-DevWSPreInstanceModeV3Config -Config $transitional -Source "test"
    }

    Test-Case "clone and save paths preserve or set instanceMode" {
        # clone-set copies the explicit mode into the new set.
        $config = Get-TestWorkspaceConfig
        $sourceFirefox = Resolve-DevWSAppById -Config $config -Reference "firefox" -CommandName "ws clone-set"
        $sourceFirefox | Add-Member -NotePropertyName instanceMode -NotePropertyValue "dedicated" -Force

        $cloneSet = Clone-DevWSSet -Config $config -SourceId "main" -NewId "secondary"
        $clonedFirefox = @($cloneSet.Clone.windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal "dedicated" $clonedFirefox.instanceMode "clone-set preserves instanceMode"

        # clone-app stays disabled and preserves the explicit source mode.
        $config2 = Get-TestWorkspaceConfig
        $sourceApp = Resolve-DevWSAppById -Config $config2 -Reference "firefox" -CommandName "ws clone-app"
        $sourceApp | Add-Member -NotePropertyName instanceMode -NotePropertyValue "shared" -Force

        $cloneResult = Clone-DevWSApp -Config $config2 -SourceId "firefox" -NewId "firefox-copy" -CommandName "ws clone-app"
        Assert-Equal "dedicated" $cloneResult.Clone.instanceMode "clone-app always produces an explicit dedicated clone"
        Assert-Equal $false $cloneResult.Clone.enabled "clone-app still starts disabled"

        # Nested app mutations and rename preserve the field.
        $config3 = Get-TestWorkspaceConfig
        $mutatedApp = Resolve-DevWSAppById -Config $config3 -Reference "firefox" -CommandName "ws set-launch"
        $mutatedApp | Add-Member -NotePropertyName instanceMode -NotePropertyValue "dedicated" -Force

        $null = Set-DevWSAppLaunch -Config $config3 -App $mutatedApp -Kind "exe" -Value "C:\Apps\other.exe"
        Assert-Equal "dedicated" $mutatedApp.instanceMode "set-launch preserves instanceMode"
        $null = Set-DevWSAppMatch -Config $config3 -App $mutatedApp -Kind "exe" -Value "other.exe"
        $null = Set-DevWSAppArguments -Config $config3 -App $mutatedApp -Arguments @("--one")
        Assert-Equal "dedicated" $mutatedApp.instanceMode "set-match/set-app-args preserve instanceMode"

        $renamed = Rename-DevWSItem -Config $config3 -Reference "firefox" -NewId "firefox2" -CommandName "ws rename"
        Assert-Equal "dedicated" $renamed.Item.instanceMode "rename preserves instanceMode"
        Assert-DevWSConfig -Config $config3 -Source "test"

        # Atomic save/load round-trip (the edit path's persistence step).
        $target = New-WritableConfigCopy "instance-mode-save"
        $location = [pscustomobject]@{ Path = $target; IsWritable = $true; Source = "test"; IsBundledDefault = $false; Warning = $null }
        $saved = Read-DevWSConfigFile -Path $target
        $savedApp = Resolve-DevWSAppById -Config $saved -Reference "firefox" -CommandName "ws edit"
        $savedApp | Add-Member -NotePropertyName instanceMode -NotePropertyValue "shared" -Force

        Save-DevWSConfig -Config $saved -Location $location

        $reloaded = Read-DevWSConfigFile -Path $target
        $reloadedApp = @($reloaded.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0]
        Assert-Equal "shared" $reloadedApp.instanceMode "save/load preserves instanceMode"
        Assert-Equal "shared" (Get-DevWSAppInstanceMode -Item $reloadedApp) "helper reads the persisted mode"

        # The bundled default now carries the locked personal modes.
        $defaultConfig = Get-TestWorkspaceConfig
        Assert-Equal "dedicated" @($defaultConfig.sets[0].windows | Where-Object { $_.id -eq "firefox" })[0].instanceMode "firefox is dedicated"
        Assert-Equal "shared" @($defaultConfig.sets[0].windows | Where-Object { $_.id -eq "codex" })[0].instanceMode "codex is shared"
        Assert-Equal "shared" @($defaultConfig.sets[0].windows | Where-Object { $_.id -eq "antigravity" })[0].instanceMode "antigravity is shared"
    }

    Test-Case "bundled default app definitions are otherwise unchanged" {
        $config = Get-TestWorkspaceConfig
        $apps = @{}

        foreach ($app in @($config.sets[0].windows | Where-Object { $_.type -eq "app" })) {
            $apps[[string]$app.id] = $app
