    function New-SharedScenarioConfig {
        param(
            [string]$MainMatchKind = "exe",
            [string]$MainMatchValue = "assistant.exe",
            [string]$MainLaunchKind = "exe",
            [string]$MainLaunchValue = "C:\Apps\assistant.exe",
            [object[]]$MainArgs = @(),
            [int]$MainLayoutX = 1,
            [bool]$MainEnabled = $true,
            [string]$SecondaryMatchKind = $null,
            [string]$SecondaryMatchValue = $null,
            [string]$SecondaryLaunchKind = $null,
            [string]$SecondaryLaunchValue = $null,
            [object[]]$SecondaryArgs = $null,
            [int]$SecondaryLayoutX = 2,
            [bool]$SecondaryEnabled = $true
        )

        if ([string]::IsNullOrWhiteSpace($SecondaryMatchKind))   { $SecondaryMatchKind = $MainMatchKind }
        if ([string]::IsNullOrWhiteSpace($SecondaryMatchValue))  { $SecondaryMatchValue = $MainMatchValue }
        if ([string]::IsNullOrWhiteSpace($SecondaryLaunchKind))  { $SecondaryLaunchKind = $MainLaunchKind }
        if ([string]::IsNullOrWhiteSpace($SecondaryLaunchValue)) { $SecondaryLaunchValue = $MainLaunchValue }
        if ($null -eq $SecondaryArgs)                            { $SecondaryArgs = @($MainArgs) }

        $mainApp = [ordered]@{
            id           = "assistant"
            type         = "app"
            enabled      = $MainEnabled
            instanceMode = "shared"
            match        = [ordered]@{ kind = $MainMatchKind; value = $MainMatchValue }
            launch       = [ordered]@{ kind = $MainLaunchKind; value = $MainLaunchValue; args = @($MainArgs) }
            layout       = [ordered]@{ x = $MainLayoutX; y = 0; w = 10; h = 10 }
        }

        $secondaryApp = [ordered]@{
            id           = "assistant"
            type         = "app"
            enabled      = $SecondaryEnabled
            instanceMode = "shared"
            match        = [ordered]@{ kind = $SecondaryMatchKind; value = $SecondaryMatchValue }
            launch       = [ordered]@{ kind = $SecondaryLaunchKind; value = $SecondaryLaunchValue; args = @($SecondaryArgs) }
            layout       = [ordered]@{ x = $SecondaryLayoutX; y = 0; w = 10; h = 10 }
        }

        return ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($mainApp)),
            (New-TestSet -Id "secondary" -Windows @($secondaryApp))
        )
    }

    Test-Case "shared definitions with the same id must be identical" {
        Assert-DevWSConfig -Config (New-SharedScenarioConfig) -Source "test"

        $cases = @(
            @{ Name = "match.value"; Config = (New-SharedScenarioConfig -SecondaryMatchValue "other.exe"); Field = "match.value" },
            @{ Name = "match.kind"; Config = (New-SharedScenarioConfig -SecondaryMatchKind "processPathContains"); Field = "match.kind" },
            @{ Name = "launch.value"; Config = (New-SharedScenarioConfig -SecondaryLaunchValue "C:\Apps\other.exe"); Field = "launch.value" },
            @{ Name = "launch.kind"; Config = (New-SharedScenarioConfig -SecondaryLaunchKind "appId"); Field = "launch.kind" },
            @{ Name = "launch.args order"; Config = (New-SharedScenarioConfig -MainArgs @("--one", "--two") -SecondaryArgs @("--two", "--one")); Field = "launch.args" },
            @{ Name = "launch.args length"; Config = (New-SharedScenarioConfig -MainArgs @("--one") -SecondaryArgs @()); Field = "launch.args" }
        )

        foreach ($case in $cases) {
            $message = Get-ThrownMessage { Assert-DevWSConfig -Config $case.Config -Source "test" }
            Assert-Contains $message $case.Field "$($case.Name) difference reported"
            Assert-Contains $message "explicitly shared" "$($case.Name) explains the shared rule"
            Assert-Contains $message "'main'" "$($case.Name) names the first set"
            Assert-Contains $message "'secondary'" "$($case.Name) names the second set"
        }

        # Layout and enabled state may differ per set.
        Assert-DevWSConfig -Config (New-SharedScenarioConfig -MainLayoutX 1 -SecondaryLayoutX 999 -MainEnabled $true -SecondaryEnabled $false) -Source "test"

        # Explicit + missing is invalid at runtime (every app requires a mode)
        # but remains recognizable for installer enrichment.
        $explicit = New-AppDefinition -Id "assistant" -InstanceMode "shared"
        $missing = New-AppDefinition -Id "assistant" -InstanceMode ""
        $transitional = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($explicit)),
            (New-TestSet -Id "secondary" -Windows @($missing))
        )

        Assert-Throws {
            Assert-DevWSConfig -Config $transitional -Source "test"
        } "missing 'instanceMode'" "final validation rejects explicit + missing"

        Assert-DevWSPreInstanceModeV3Config -Config $transitional -Source "test"

        # Shared + dedicated for the same id is still rejected by both.
        $sharedApp = New-AppDefinition -Id "assistant" -InstanceMode "shared"
        $dedicatedApp = New-AppDefinition -Id "assistant" -InstanceMode "dedicated"
        $contradiction = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($sharedApp)),
            (New-TestSet -Id "secondary" -Windows @($dedicatedApp))
        )
        $contradictionMessage = Get-ThrownMessage { Assert-DevWSConfig -Config $contradiction -Source "test" }
        Assert-Contains $contradictionMessage "one instance mode across sets" "explicit mode contradiction still fails"

        $relaxedContradictionMessage = Get-ThrownMessage { Assert-DevWSPreInstanceModeV3Config -Config $contradiction -Source "test" }
        Assert-Contains $relaxedContradictionMessage "one instance mode across sets" "relaxed recognition also rejects contradictions"
    }

