    Test-Case "app window enumeration includes hidden top-level windows only on request" {
        $popup = [DevWSTestOwnershipWindow]::CreatePopup()

        if ($popup -eq [IntPtr]::Zero) {
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        $h = [long]$popup

        try {
            $visible = @(Get-DevWSAppWindowCandidates)
            $all     = @(Get-DevWSAppWindowCandidates -IncludeInvisible)

            Assert-Equal 0 @($visible | Where-Object { [long]$_.hwnd -eq $h }).Count "hidden window excluded by default"

            $found = @($all | Where-Object { [long]$_.hwnd -eq $h })
            Assert-Equal 1 $found.Count "hidden window enumerable on request"
            Assert-Equal $false ([bool]$found[0].visible) "popup window is not visible"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($popup)
        }
    }

    # Test-only native helper: an off-screen but genuinely visible top-level
    # window with a caller-supplied title, used to exercise the native
    # collector's visible title/class and process-metadata semantics.
    if (-not ([System.Management.Automation.PSTypeName]'DevWSAppCandidateTestWindow').Type) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public static class DevWSAppCandidateTestWindow
{
    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr CreateWindowExW(uint dwExStyle, string lpClassName, string lpWindowName, uint dwStyle, int x, int y, int nWidth, int nHeight, IntPtr hWndParent, IntPtr hMenu, IntPtr hInstance, IntPtr lpParam);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool DestroyWindow(IntPtr hWnd);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    public static long CreateVisible(string title)
    {
        // WS_OVERLAPPEDWINDOW | WS_VISIBLE, parked off-screen so nothing
        // appears on the interactive desktop.
        return CreateWindowExW(0, "STATIC", title, 0x10CF0000u, -2000, 200, 400, 300, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero).ToInt64();
    }

    public static bool Hide(long hWnd) { return ShowWindow((IntPtr)hWnd, 0); }
    public static bool Destroy(long hWnd) { return DestroyWindow((IntPtr)hWnd); }
}
'@ -ErrorAction Stop
    }

    Test-Case "native candidate collector preserves visible and hidden record facts" {
        $title = "DevWS-Candidate-$([guid]::NewGuid().ToString('N'))"
        $visibleHwnd = [DevWSAppCandidateTestWindow]::CreateVisible($title)
        $hiddenPopup = [DevWSTestOwnershipWindow]::CreatePopup()

        if ($visibleHwnd -eq 0 -or $hiddenPopup -eq [IntPtr]::Zero) {
            if ($visibleHwnd -ne 0) { [void][DevWSAppCandidateTestWindow]::Destroy($visibleHwnd) }
            if ($hiddenPopup -ne [IntPtr]::Zero) { [void][DevWSTestOwnershipWindow]::Destroy($hiddenPopup) }
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        try {
            $all = @(Get-DevWSAppWindowCandidates -IncludeInvisible)
            $visibleOnly = @(Get-DevWSAppWindowCandidates)

            $visibleRecord = @($all | Where-Object { [long]$_.hwnd -eq $visibleHwnd })
            Assert-Equal 1 $visibleRecord.Count "visible test window enumerated"
            Assert-Equal "DevWSAppWindowCandidate" $visibleRecord[0].GetType().Name "candidates are CLR fact records"
            Assert-Equal $true ([bool]$visibleRecord[0].visible) "visible flag reported"
            Assert-Equal $title ([string]$visibleRecord[0].title) "visible title captured"
            Assert-Equal "Static" ([string]$visibleRecord[0].class) "visible class captured"
            Assert-True (([string]$visibleRecord[0].processName).EndsWith(".exe", [System.StringComparison]::OrdinalIgnoreCase)) "process name normalized to the .exe shape"
            Assert-Equal $false ([bool]$visibleRecord[0].pathUnavailable) "own process path available"
            Assert-True (-not [string]::IsNullOrWhiteSpace([string]$visibleRecord[0].processPath)) "own process path captured"

            $hiddenRecord = @($all | Where-Object { [long]$_.hwnd -eq [long]$hiddenPopup })
            Assert-Equal 1 $hiddenRecord.Count "hidden top-level window retained when requested"
            Assert-Equal $false ([bool]$hiddenRecord[0].visible) "hidden record marked invisible"
            Assert-Equal $null $hiddenRecord[0].processName "hidden record has no process name"
            Assert-Equal $null $hiddenRecord[0].processPath "hidden record has no process path"
            Assert-Equal $true ([bool]$hiddenRecord[0].pathUnavailable) "hidden record path is unavailable"
            Assert-Equal "" ([string]$hiddenRecord[0].title) "hidden record title stays empty"
            Assert-Equal "" ([string]$hiddenRecord[0].class) "hidden record class stays empty"

            Assert-Equal 0 @($visibleOnly | Where-Object { [long]$_.hwnd -eq [long]$hiddenPopup }).Count "hidden window excluded by default"
            Assert-Equal 1 @($visibleOnly | Where-Object { [long]$_.hwnd -eq $visibleHwnd }).Count "visible window included by default"

            # Hidden records never match even before metadata is inspected.
            Assert-Equal $false (Test-DevWSAppWindowMatch -Candidate $hiddenRecord[0] -Match ([pscustomobject]@{ kind = "exe"; value = "whatever.exe" })) "hidden candidate can never match"

            # Lowercase consumers keep working against the CLR properties.
            $dtoRecord = $visibleRecord[0]
            Assert-Equal $visibleHwnd ([long]$dtoRecord.hwnd) "lowercase hwnd access"
            Assert-Equal ([uint32]$PID) ([uint32]$dtoRecord.pid) "lowercase pid access"
            Assert-Equal $false ([bool]$dtoRecord.pathUnavailable) "lowercase pathUnavailable access"
        }
        finally {
            [void][DevWSAppCandidateTestWindow]::Destroy($visibleHwnd)
            [void][DevWSTestOwnershipWindow]::Destroy($hiddenPopup)
        }
    }

    Test-Case "native candidate enumeration preserves EnumWindows order" {
        # Two immediate snapshots: every HWND common to both must keep its
        # relative order (desktop churn may add/remove unrelated windows).
        $orderOk = $false

        for ($attempt = 0; $attempt -lt 3 -and -not $orderOk; $attempt++) {
            $first = @(Get-DevWSAppWindowCandidates -IncludeInvisible)
            $second = @(Get-DevWSAppWindowCandidates -IncludeInvisible)

            $secondIndex = @{}
            for ($i = 0; $i -lt $second.Count; $i++) {
                $secondIndex[[long]$second[$i].hwnd] = $i
            }

            $lastIndex = -1
            $orderOk = $true

            foreach ($record in $first) {
                $index = $secondIndex[[long]$record.hwnd]
                if ($null -eq $index) { continue }
                if ($index -lt $lastIndex) { $orderOk = $false; break }
                $lastIndex = $index
            }
        }

        Assert-True $orderOk "common HWNDs keep EnumWindows relative order"
    }

    Test-Case "app window probe classifies bounded ownership on disposable windows" {
        $first  = [DevWSTestOwnershipWindow]::Create()
        $second = [DevWSTestOwnershipWindow]::Create()

        if ($first -eq [IntPtr]::Zero -or $second -eq [IntPtr]::Zero) {
            # A runtime skip must not leave a partially created fixture behind:
            # destroy whichever window(s) were actually created before leaving.
            if ($first  -ne [IntPtr]::Zero) { [void][DevWSTestOwnershipWindow]::Destroy($first) }
            if ($second -ne [IntPtr]::Zero) { [void][DevWSTestOwnershipWindow]::Destroy($second) }
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        $h1 = [long]$first
        $h2 = [long]$second

        try {
            $mainEditor = New-AppDefinition -Id "editor"
            $mainEditor["instanceMode"] = "dedicated"
            $secondaryEditor = New-AppDefinition -Id "editor"
            $secondaryEditor["instanceMode"] = "dedicated"
            $sharedNotes = New-AppDefinition -Id "notes"
            $sharedNotes["instanceMode"] = "shared"

            $config = ConvertTo-TestConfig -Sets @(
                (New-TestSet -Id "main" -Windows @($mainEditor, $sharedNotes)),
                (New-TestSet -Id "secondary" -Windows @($secondaryEditor))
            )

            $null = Set-DevWSAppOwnership -Hwnd $h1 -SetId "main" -ItemId "editor"
            $null = Set-DevWSAppOwnership -Hwnd $h2 -SetId "secondary" -ItemId "editor"

            $candidates = @(
                [pscustomobject]@{ hwnd = $h1; pid = 1; processName = "editor.exe"; processPath = "C:\Apps\editor.exe"; visible = $true; class = "Test"; title = "Test" },
                [pscustomobject]@{ hwnd = $h2; pid = 2; processName = "editor.exe"; processPath = "C:\Apps\editor.exe"; visible = $true; class = "Test"; title = "Test" }
            )

            $probed = @(Get-DevWSAppWindowProbe -Config $config -Candidates $candidates)
            Assert-Equal "main/editor" $probed[0].ownerKey "bounded lookup finds the main owner"
            Assert-Equal "secondary/editor" $probed[1].ownerKey "bounded lookup finds the secondary owner"

            $third = [DevWSTestOwnershipWindow]::Create()
            $probedThird = @(Get-DevWSAppWindowProbe -Config $config -Candidates @(
                [pscustomobject]@{ hwnd = [long]$third; pid = 3; processName = "editor.exe"; processPath = "C:\Apps\editor.exe"; visible = $true; class = "Test"; title = "Test" }
            ))
            Assert-True ($null -eq $probedThird[0].ownerKey) "untagged window stays unowned"
            [void][DevWSTestOwnershipWindow]::Destroy($third)

            # Multiple identity properties on one window are corruption.
            $null = Set-DevWSAppOwnership -Hwnd $h1 -SetId "secondary" -ItemId "editor"
            Assert-Throws {
                Get-DevWSAppWindowProbe -Config $config -Candidates $candidates
            } "multiple DevWS ownership properties" "corrupt ownership fails"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($first)
            [void][DevWSTestOwnershipWindow]::Destroy($second)
        }
    }

    Test-Case "app window probe builds ownership descriptors once per probe" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TestMatchedAppDefinition -Id "editor" -MatchKind "exe" -MatchValue "editor.exe" -InstanceMode "dedicated")))
        )

        $descriptorCalls = [System.Collections.Generic.List[object]]::new()
        $lookupCalls     = [System.Collections.Generic.List[long]]::new()

        function Get-DevWSAppOwnershipDescriptors {
            param([object[]]$Candidates)
            $descriptorCalls.Add($Candidates.Count)
            return @([pscustomobject]@{ SetId = "main"; ItemId = "editor"; PropertyName = "DevWS.Owner.v1.main/editor" })
        }

        function Get-DevWSAppOwnershipFromDescriptors {
            param([long]$Hwnd, [object[]]$Descriptors)
            $lookupCalls.Add($Hwnd)
            return $null
        }

        $candidates = @(1..5 | ForEach-Object {
            [pscustomobject]@{
                hwnd = [long]$_; pid = [uint32]1; processName = "editor.exe"; processPath = "C:\Apps\editor.exe"
                pathUnavailable = $false; visible = $true; class = "Test"; title = "Test"
            }
        })

        $probed = @(Get-DevWSAppWindowProbe -Config $config -Candidates $candidates)

        Assert-Equal 1 $descriptorCalls.Count "descriptors are built exactly once per probe"
        Assert-Equal 5 $lookupCalls.Count "descriptor lookup runs for every candidate"
        Assert-Equal 5 $probed.Count "probe still returns every candidate"

        $source = Get-SourceOf "src\lib\devws-app-window.ps1"
        Assert-Contains $source "Get-DevWSAppOwnershipDescriptors" "probe uses precomputed ownership descriptors"
        Assert-NotContains $source "Get-DevWSAppOwnership -Hwnd" "probe no longer normalizes candidates per HWND"
    }

    Test-Case "app window selection preserves the dedicated/shared/hidden matrix" {
        function New-MatrixRecord {
            param([long]$Hwnd, [bool]$Visible, [string]$Path, $OwnerKey)

            return [pscustomobject]@{
                hwnd            = $Hwnd
                pid             = 1
                processName     = ""
                processPath     = $Path
                pathUnavailable = [string]::IsNullOrWhiteSpace($Path)
                visible         = $Visible
                class           = ""
                title           = ""
                ownerSetId      = if ($OwnerKey) { ($OwnerKey -split '/')[0] } else { $null }
                ownerItemId     = if ($OwnerKey) { ($OwnerKey -split '/')[1] } else { $null }
                ownerKey        = $OwnerKey
                ownerError      = $null
            }
        }

        $match   = [pscustomobject]@{ kind = "exe"; value = "firefox.exe" }
        $firefox = "C:\Program Files\Mozilla Firefox\firefox.exe"
        $other   = "secondary/editor"

        $cases = @(
            @{ Name = "dedicated none";                    Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true "C:\x\chrome.exe" $null));                                                        Expected = "missing" }
            @{ Name = "dedicated one unowned";             Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true $firefox $null));                                                              Expected = "adopt" }
            @{ Name = "dedicated two unowned";             Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true $firefox $null), (New-MatrixRecord 2 $true $firefox $null));                     Expected = "ambiguous" }
            @{ Name = "dedicated exact owner matches";     Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true $firefox "main/firefox"));                                                       Expected = "resolved" }
            @{ Name = "dedicated owner mismatch";          Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true "C:\x\chrome.exe" "main/firefox"));                                               Expected = "owned-mismatch" }
            @{ Name = "dedicated two exact owners";        Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true $firefox "main/firefox"), (New-MatrixRecord 2 $true $firefox "main/firefox")); Expected = "ambiguous" }
            @{ Name = "dedicated other-owned match";       Mode = "dedicated"; Records = @((New-MatrixRecord 1 $true $firefox $other));                                                                 Expected = "missing" }
            @{ Name = "shared none";                       Mode = "shared";    Records = @((New-MatrixRecord 1 $true "C:\x\chrome.exe" $null));                                                        Expected = "missing" }
            @{ Name = "shared one eligible";               Mode = "shared";    Records = @((New-MatrixRecord 1 $true $firefox $null));                                                              Expected = "resolved" }
            @{ Name = "shared two eligible";               Mode = "shared";    Records = @((New-MatrixRecord 1 $true $firefox $null), (New-MatrixRecord 2 $true $firefox $null));                     Expected = "ambiguous" }
            @{ Name = "shared dedicated-owned excluded";   Mode = "shared";    Records = @((New-MatrixRecord 1 $true $firefox $other));                                                                 Expected = "missing" }
            @{ Name = "shared owned plus unowned";         Mode = "shared";    Records = @((New-MatrixRecord 1 $true $firefox $other), (New-MatrixRecord 2 $true $firefox $null));                     Expected = "resolved" }
            @{ Name = "hidden exact owner";                Mode = "dedicated"; Records = @((New-MatrixRecord 1 $false $firefox "main/firefox"));                                                       Expected = "owned-mismatch" }
            @{ Name = "hidden unowned candidate";          Mode = "dedicated"; Records = @((New-MatrixRecord 1 $false $firefox $null));                                                              Expected = "missing" }
            @{ Name = "visible unowned plus hidden owner"; Mode = "dedicated"; Records = @((New-MatrixRecord 1 $false $firefox "main/firefox"), (New-MatrixRecord 2 $true $firefox $null));         Expected = "owned-mismatch" }
        )

        foreach ($case in $cases) {
            $selection = Resolve-DevWSAppWindowSelection `
                -Probed $case.Records `
                -SetId "main" `
                -ItemId "firefox" `
                -Match $match `
                -Mode $case.Mode

            Assert-Equal $case.Expected ([string]$selection.Status) "selection case: $($case.Name)"
        }
    }

    Test-Case "dedicated lifecycle adopts one unowned window and records exact ownership" {
        $testWindow = [DevWSTestOwnershipWindow]::Create()

        if ($testWindow -eq [IntPtr]::Zero) {
            Skip-Test "no disposable test window could be created (no usable window station)"
        }

        $h = [long]$testWindow
        $launchCalls = [System.Collections.Generic.List[string]]::new()

        try {
            $app = New-AppDefinition -Id "editor"
            $app["instanceMode"] = "dedicated"
            $app["match"] = [ordered]@{ kind = "exe"; value = "editor.exe" }
            $config = ConvertTo-TestConfig -Windows @($app)
            $appItem = $config.sets[0].windows[0]

            $probeState = [pscustomobject]@{ calls = 0 }
            $probeProvider = {
                $probeState.calls++
                $ownerKey = $null

                if ($probeState.calls -gt 1) { $ownerKey = "main/editor" }

                @([pscustomobject]@{
                    hwnd        = $h
                    pid         = 1
                    processName = "editor.exe"
                    processPath = "C:\Apps\editor.exe"
                    visible     = $true
                    class       = "Test"
                    title       = "Test"
                    ownerSetId  = if ($ownerKey) { "main" } else { $null }
                    ownerItemId = if ($ownerKey) { "editor" } else { $null }
                    ownerKey    = $ownerKey
                })
            }
            $launcher = { param($LaunchApp) $launchCalls.Add([string]$LaunchApp.id) }

            $resolved = Resolve-DevWSAppLifecycleWindow -Config $config -SetId "main" -App $appItem -Operation "focus" -ProbeProvider $probeProvider -Launcher $launcher

            Assert-Equal $h $resolved "adopted window returned"
            Assert-True (Test-DevWSAppOwnership -Hwnd $h -SetId "main" -ItemId "editor") "adoption recorded exact ownership"
            Assert-Equal 0 $launchCalls.Count "focus never launches"

            $again = Resolve-DevWSAppLifecycleWindow -Config $config -SetId "main" -App $appItem -Operation "focus" -ProbeProvider $probeProvider -Launcher $launcher
            Assert-Equal $h $again "exact owner is reused"
            Assert-Equal 0 $launchCalls.Count "owned window is never relaunched"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($testWindow)
        }
    }

