    Test-Case "instance mode enrichment follows the deterministic policy" {
        $template = Get-TestWorkspaceConfig

        # Rule 2 (template match) + rule 3 (unknown singleton) with canonical
        # output ordering and an untouched source object.
        $premode = [pscustomobject][ordered]@{
            version    = 3
            defaultSet = "main"
            bindings   = @()
            sets       = @(
                [pscustomobject][ordered]@{
                    id      = "main"
                    windows = @(
                        [pscustomobject][ordered]@{ id = "firefox"; type = "app"; enabled = $true
                            match = [pscustomobject]@{ kind = "exe"; value = "firefox.exe" }
                            launch = [pscustomobject]@{ kind = "exe"; value = "C:\Program Files\Mozilla Firefox\firefox.exe"; args = @() }
                            layout = [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4 } },
                        [pscustomobject][ordered]@{ id = "unknownapp"; type = "app"; enabled = $true
                            match = [pscustomobject]@{ kind = "exe"; value = "unknownapp.exe" }
                            launch = [pscustomobject]@{ kind = "exe"; value = "C:\Apps\unknownapp.exe"; args = @() }
                            layout = [pscustomobject]@{ x = 5; y = 6; w = 7; h = 8 } }
                    )
                }
            )
        }

        $sourceBefore = ConvertTo-Json -InputObject $premode -Depth 20
        $enriched = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $premode -BundledTemplate $template

        Assert-Equal $sourceBefore (ConvertTo-Json -InputObject $premode -Depth 20) "enrichment never mutates the source"
        Assert-DevWSConfig -Config $enriched -Source "test"
        Assert-Equal "dedicated" $enriched.sets[0].windows[0].instanceMode "bundled template mode applied"
        Assert-Equal "dedicated" $enriched.sets[0].windows[1].instanceMode "unknown singleton becomes dedicated"
        Assert-Equal "id,type,enabled,match,launch,instanceMode,layout" (@($enriched.sets[0].windows[0].PSObject.Properties.Name) -join ",") "canonical property order"

        # Rule 2 must NOT apply when the identity/launch definition changed.
        $changedDefinition = [pscustomobject][ordered]@{
            version    = 3
            defaultSet = "main"
            bindings   = @()
            sets       = @(
                [pscustomobject][ordered]@{
                    id      = "main"
                    windows = @(
                        [pscustomobject][ordered]@{ id = "firefox"; type = "app"; enabled = $true
                            match = [pscustomobject]@{ kind = "exe"; value = "firefox.exe" }
                            launch = [pscustomobject]@{ kind = "exe"; value = "C:\Portable\firefox-dev.exe"; args = @() }
                            layout = [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4 } }
                    )
                }
            )
        }
        $changedResult = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $changedDefinition -BundledTemplate $template
        Assert-Equal "dedicated" $changedResult.sets[0].windows[0].instanceMode "changed personal definition is not inferred from the template id alone"

        # Rule 1: an explicit mode propagates to a missing same-id definition.
        $explicitApp = [ordered]@{ id = "assistant"; type = "app"; enabled = $true; instanceMode = "shared"
            match = [ordered]@{ kind = "exe"; value = "assistant.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\assistant.exe"; args = @() }
            layout = [ordered]@{ x = 1; y = 0; w = 10; h = 10 } }
        $missingApp = [ordered]@{ id = "assistant"; type = "app"; enabled = $true
            match = [ordered]@{ kind = "exe"; value = "assistant.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\assistant.exe"; args = @() }
            layout = [ordered]@{ x = 2; y = 0; w = 10; h = 10 } }
        $propagate = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($explicitApp)),
            (New-TestSet -Id "secondary" -Windows @($missingApp))
        )
        $propagated = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $propagate -BundledTemplate $template
        Assert-DevWSConfig -Config $propagated -Source "test"
        Assert-Equal "shared" $propagated.sets[0].windows[0].instanceMode "explicit mode preserved"
        Assert-Equal "shared" $propagated.sets[1].windows[0].instanceMode "explicit mode propagated"

        # Rule 1 shared equivalence: a differing definition fails safely.
        $differingApp = [ordered]@{ id = "assistant"; type = "app"; enabled = $true
            match = [ordered]@{ kind = "exe"; value = "assistant.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\other.exe"; args = @() }
            layout = [ordered]@{ x = 2; y = 0; w = 10; h = 10 } }
        $incompatible = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($explicitApp)),
            (New-TestSet -Id "secondary" -Windows @($differingApp))
        )
        $before = ConvertTo-Json -InputObject $incompatible -Depth 20
        $message = Get-ThrownMessage {
            $null = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $incompatible -BundledTemplate $template
        }
        Assert-Contains $message "not equivalent" "incompatible shared propagation fails"
        Assert-Equal $before (ConvertTo-Json -InputObject $incompatible -Depth 20) "failed enrichment leaves the source untouched"

        # Rule 4: unknown multi-set app ids fail safely.
        $unknownMain = [ordered]@{ id = "mystery"; type = "app"; enabled = $true
            match = [ordered]@{ kind = "exe"; value = "mystery.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\mystery.exe"; args = @() }
            layout = [ordered]@{ x = 1; y = 0; w = 10; h = 10 } }
        $unknownSecondary = [ordered]@{ id = "mystery"; type = "app"; enabled = $true
            match = [ordered]@{ kind = "exe"; value = "mystery.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\mystery.exe"; args = @() }
            layout = [ordered]@{ x = 2; y = 0; w = 10; h = 10 } }
        $ambiguous = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($unknownMain)),
            (New-TestSet -Id "secondary" -Windows @($unknownSecondary))
        )
        $ambiguousMessage = Get-ThrownMessage {
            $null = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $ambiguous -BundledTemplate $template
        }
        Assert-Contains $ambiguousMessage "Cannot infer instanceMode" "ambiguous multi-set app fails"
        Assert-Contains $ambiguousMessage "main/mystery" "failure names the first scoped app"
        Assert-Contains $ambiguousMessage "secondary/mystery" "failure names the second scoped app"

        # Rule 1 dedicated propagation allows differing definitions per set.
        $dedicatedExplicit = [ordered]@{ id = "assistant"; type = "app"; enabled = $true; instanceMode = "dedicated"
            match = [ordered]@{ kind = "exe"; value = "assistant.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\assistant.exe"; args = @() }
            layout = [ordered]@{ x = 1; y = 0; w = 10; h = 10 } }
        $dedicatedMissing = [ordered]@{ id = "assistant"; type = "app"; enabled = $true
            match = [ordered]@{ kind = "exe"; value = "assistant.exe" }
            launch = [ordered]@{ kind = "exe"; value = "C:\Apps\assistant-variant.exe"; args = @() }
            layout = [ordered]@{ x = 2; y = 0; w = 10; h = 10 } }
        $dedicatedPropagate = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @($dedicatedExplicit)),
            (New-TestSet -Id "secondary" -Windows @($dedicatedMissing))
        )
        $dedicatedResult = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $dedicatedPropagate -BundledTemplate $template
        Assert-DevWSConfig -Config $dedicatedResult -Source "test"
        Assert-Equal "dedicated" $dedicatedResult.sets[1].windows[0].instanceMode "dedicated propagates even with differing definitions"

        # Cloned default-like two-set config receives the locked modes in both.
        $twoSet = Get-TestWorkspaceConfig
        [void](Clone-DevWSSet -Config $twoSet -SourceId "main" -NewId "secondary")

        foreach ($set in @($twoSet.sets)) {
            foreach ($app in @($set.windows | Where-Object { $_.type -eq "app" })) {
                $app.PSObject.Properties.Remove("instanceMode")
            }
        }

        $twoSetEnriched = ConvertTo-DevWSConfigWithExplicitInstanceModes -Config $twoSet -BundledTemplate $template
        Assert-DevWSConfig -Config $twoSetEnriched -Source "test"

        foreach ($set in @($twoSetEnriched.sets)) {
            $modeById = @{}
            foreach ($app in @($set.windows | Where-Object { $_.type -eq "app" })) {
                $modeById[[string]$app.id] = [string]$app.instanceMode
            }

            Assert-Equal "dedicated" $modeById["firefox"] "firefox locked mode in set $($set.id)"
            Assert-Equal "shared" $modeById["codex"] "codex locked mode in set $($set.id)"
            Assert-Equal "shared" $modeById["antigravity"] "antigravity locked mode in set $($set.id)"
        }
    }

    Write-Host ""
    Start-TestGroup -Name 'hardening' -Title 'Final hardening'

    Test-Case "final command surface dispatch and aliases" {
        $target = New-WritableConfigCopy "final-surface"

        # Unknown commands are rejected without side effects.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("definitely-not-a-command")
        Assert-Equal 1 $result.ExitCode "unknown command exit"
        Assert-Contains $result.Output "Unknown command" "unknown command message"

        # show is an intentional alias of list.
        $list = Invoke-WsCli -ConfigPath $target -Arguments @("list")
        $show = Invoke-WsCli -ConfigPath $target -Arguments @("show")
        Assert-Equal 0 $list.ExitCode "list exit"
        Assert-Equal 0 $show.ExitCode "show exit"
        Assert-Equal $list.Output $show.Output "show output matches list"

        # reset-terminal is an intentional alias of reset; an unknown reference
        # fails identically before any scheduled-task interaction.
        $reset = Invoke-WsCli -ConfigPath $target -Arguments @("reset", "does-not-exist")
        $alias = Invoke-WsCli -ConfigPath $target -Arguments @("reset-terminal", "does-not-exist")
        Assert-Equal 1 $reset.ExitCode "reset unknown exit"
        Assert-Equal 1 $alias.ExitCode "reset-terminal unknown exit"
        Assert-Equal $reset.Output $alias.Output "reset-terminal output matches reset"

        $help = Invoke-WsCli -ConfigPath $target -Arguments @("help", "all")
        Assert-Equal 0 $help.ExitCode "help all exit"

        $known = @(
            "launch", "focus", "list", "show", "status", "save", "save-layout", "show-layout",
            "enable", "disable", "remove",
            "add-terminal", "clone-terminal", "set-path", "set-command",
            "add-app", "clone-app", "set-launch", "set-match", "set-app-args", "set-instance-mode",
            "rename", "edit",
            "set-geometry", "reset-layout", "layout-profile",
            "sets", "add-set", "clone-set", "rename-set", "remove-set", "set-default",
            "bind", "unbind", "bindings", "sync-hotkeys",
            "health", "doctor", "detect-app", "monitors",
            "set", "reset", "reset-terminal", "reset-terminals",
            "help"
        )

        foreach ($command in $known) {
            Assert-Contains $help.Output ("ws " + $command) "help all advertises ws $command"
        }

        # Pass 4/5 wording: help must not claim bindings are unimplemented.
        Assert-NotContains $help.Output "not implemented yet" "help never claims unimplemented bindings"
        Assert-NotContains $help.Output "bindings must stay empty" "help never claims bindings must stay empty"
        Assert-NotContains $help.Output "devws v2" "help is version-neutral"

        # Every command advertised in help output exists (catches stale docs).
        $documented = [System.Collections.Generic.List[string]]::new()

        foreach ($line in @($help.Output -split "`n")) {
            if ($line.Trim() -cmatch '^ws\s+([a-z][a-z-]*)') {
                $documented.Add($Matches[1])
            }
        }

        Assert-True ($documented.Count -ge 30) "help documents the full command surface"

        foreach ($command in @($documented | Sort-Object -Unique)) {
            Assert-True ($known -contains $command) "documented command exists: ws $command"
        }

        # Phase 9 Pass 2: the previously deferred ws save command is now part
        # of the documented surface.
        Assert-True ($documented -contains "save") "help advertises the implemented ws save command"
    }

    Test-Case "unknown commands suggest close matches without a full help dump" {
        $target = New-WritableConfigCopy "unknown-suggest"
        $before = Get-FileBase64 -Path $target

        $typo = Invoke-WsCli -ConfigPath $target -Arguments @("launhc")
        Assert-Equal 1 $typo.ExitCode "typo exit"
        Assert-Contains $typo.Output "Unknown command 'launhc'." "typo message"
        Assert-Contains $typo.Output "Did you mean:" "typo suggestion header"
        Assert-Contains $typo.Output "  ws launch" "typo suggests launch"
        Assert-NotContains $typo.Output "ws add-terminal" "typo does not dump full help"

        $nonsense = Invoke-WsCli -ConfigPath $target -Arguments @("frobnicate")
        Assert-Equal 1 $nonsense.ExitCode "distant nonsense exit"
        Assert-Contains $nonsense.Output "Unknown command 'frobnicate'." "distant nonsense message"
        Assert-NotContains $nonsense.Output "Did you mean" "distant nonsense has no misleading suggestion"
        Assert-NotContains $nonsense.Output "ws add-terminal" "distant nonsense does not dump full help"

        # Direct command-group shortcuts are suggestion candidates too.
        foreach ($case in @(
            @{ Typo = "layuot"; Expected = "layout" },
            @{ Typo = "item";   Expected = "items" },
            @{ Typo = "tool";   Expected = "tools" }
        )) {
            $groupTypo = Invoke-WsCli -ConfigPath $target -Arguments @($case.Typo)
            Assert-Equal 1 $groupTypo.ExitCode "group typo exit: $($case.Typo)"
            Assert-Contains $groupTypo.Output "Did you mean:" "group typo suggestion header: $($case.Typo)"
            Assert-Contains $groupTypo.Output ("  ws " + $case.Expected) "group typo suggests $($case.Expected)"
        }

        Assert-Equal $before (Get-FileBase64 -Path $target) "unknown commands left config bytes unchanged"
    }

    Test-Case "failed mutations leave config bytes and runtime state untouched" {
        $target = New-WritableConfigCopy "final-atomicity"
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        $statePath = Get-DevWSStatePath
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "DevWS-slot" -Hwnd 31337
        Save-DevWSRuntimeState -State $state -Path $statePath
        $stateBefore = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))

        $failures = @(
            @{ Name = "add-app duplicate";        Args = @("add-app", "firefox", "exe", "C:\x.exe", "exe", "x.exe", "dedicated") },
            @{ Name = "rename duplicate";         Args = @("rename", "firefox", "slot") },
            @{ Name = "clone-terminal duplicate"; Args = @("clone-terminal", "slot", "studio") },
            @{ Name = "set-geometry invalid";     Args = @("set-geometry", "firefox", "--x", "0", "--y", "0", "--width", "0", "--height", "10") }
        )

        foreach ($failure in $failures) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $failure.Args
            Assert-Equal 1 $result.ExitCode "$($failure.Name) exit"
            Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "$($failure.Name) left config bytes unchanged"
            Assert-Equal $stateBefore ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))) "$($failure.Name) left runtime state unchanged"
        }

        # An invalid edit session leaves both untouched as well.
        $location = Resolve-DevWSConfigLocation -StartPath $RepoRoot -Override $target
        $broken = Join-Path $TestRoot "final-atomicity-broken.json"
        Set-Content -LiteralPath $broken -Value "{ not json" -Encoding UTF8
        $stub = New-EditorStub -Name "final-atomicity-stub" -ReplacementPath $broken

        $message = Get-ThrownMessage {
            [void](Invoke-DevWSEditSession -Location $location -EditorSpec (New-DevWSEditorSpec -Name "stub.cmd" -Path $stub))
        }

        Assert-Contains $message "Edited config is invalid" "invalid edit rejected"
        Assert-Equal $before ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "invalid edit left config bytes unchanged"
        Assert-Equal $stateBefore ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($statePath))) "invalid edit left runtime state unchanged"

        Remove-Item -LiteralPath (($message -split "`n")[-1].Trim()) -Force
        Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
    }

