    Test-Case "installed workers resolve the privileged root and fail cleanly without a request" {
        $fixture = New-InstallFixture "worker-layout"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $privileged = Initialize-TestPrivilegedFixture -Fixture $fixture

        $savedInstall = $env:DEVWS_INSTALL_ROOT
        $savedConfig  = $env:DEVWS_CONFIG
        $savedState   = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_INSTALL_ROOT = $fixture.Root
            $env:DEVWS_CONFIG = Join-Path $fixture.Config "workspace.default.json"
            $env:DEVWS_STATE_ROOT = $fixture.State

            foreach ($worker in @("elevated.ps1", "elevated-capture.ps1", "elevated-focus.ps1", "elevated-reset.ps1")) {
                $workerPath = Join-Path $privileged ("workers\" + $worker)
                $pipeName = Get-DevWSWorkerOperationPipeName -Kind ($worker -replace '^elevated-?', '' -replace '\.ps1$', '' -replace '^$', 'launch')

                # Public Security Phase 2-D: without a caller the worker creates
                # its one-shot pipe, waits boundedly and exits cleanly with no
                # side effects (no request/result files exist any more).
                $process = Start-Process -FilePath (Join-Path $PSHOME 'pwsh.exe') -ArgumentList @('-NoLogo', '-NoProfile', '-File', "`"$workerPath`"") -PassThru -WindowStyle Hidden -RedirectStandardOutput (Join-Path $fixture.State ($worker + ".out.txt")) -RedirectStandardError (Join-Path $fixture.State ($worker + ".err.txt"))
                Start-Sleep -Milliseconds 400
                $out = if (Test-Path (Join-Path $fixture.State ($worker + ".out.txt"))) { Get-Content -Raw -LiteralPath (Join-Path $fixture.State ($worker + ".out.txt")) } else { "" }
                $err = if (Test-Path (Join-Path $fixture.State ($worker + ".err.txt"))) { Get-Content -Raw -LiteralPath (Join-Path $fixture.State ($worker + ".err.txt")) } else { "" }
                $output = $out + $err
                Assert-NotContains $output "runtime libraries were not found" "$worker found its libraries"
                Assert-NotContains $output "is incomplete" "$worker privileged runtime is complete"
                Assert-NotContains $output "is not recognized as the name of a cmdlet" "$worker loaded its libraries"
                Assert-NotContains $output "ParserError" "$worker has no parse error"

                # Client probe: the worker's one-shot pipe answers the bounded
                # connect path (proving the transport is really serving).
                $client = Connect-DevWSWorkerPipe -Kind ($worker -replace '^elevated-?', '' -replace '\.ps1$', '' -replace '^$', 'launch') -TimeoutSeconds 10
                Assert-True ($null -ne $client) "$worker serves its one-shot pipe"
                if ($null -ne $client) { $client.Dispose() }
            }
        }
        finally {
            if ($null -eq $savedInstall) {
                Remove-Item Env:\DEVWS_INSTALL_ROOT -ErrorAction SilentlyContinue
            }
            else {
                $env:DEVWS_INSTALL_ROOT = $savedInstall
            }

            if ($null -eq $savedConfig) {
                Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
            }
            else {
                $env:DEVWS_CONFIG = $savedConfig
            }

            if ($null -eq $savedState) {
                Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue
            }
            else {
                $env:DEVWS_STATE_ROOT = $savedState
            }
        }
    }

    Test-Case "trusted AutoHotkey resolution accepts only machine-wide Program Files v2" {
        $versionReader = {
            param($CandidatePath)

            if ($CandidatePath -like '*ahk-v1*') { return [pscustomobject]@{ FileMajorPart = 1; ProductMajorPart = 1 } }
            return [pscustomobject]@{ FileMajorPart = 2; ProductMajorPart = 2 }
        }

        function New-AhkFixtureRoot([string]$Name) {
            $pf = Join-Path $TestRoot ("ahk-trust-" + $Name + "\Program Files")
            New-Item -ItemType Directory -Path $pf -Force | Out-Null
            return $pf
        }

        function New-AhkStub([string]$Directory, [string]$Leaf = 'AutoHotkey64.exe') {
            New-Item -ItemType Directory -Path $Directory -Force | Out-Null
            $path = Join-Path $Directory $Leaf
            Set-Content -LiteralPath $path -Value "# AutoHotkey fixture stub" -NoNewline
            return $path
        }

        function New-AhkRecord([string]$Scope, [AllowNull()][string]$InstallDir, [switch]$Present, [string]$ErrorText = '') {
            return [pscustomobject]@{
                Scope      = $Scope
                Present    = [bool]$Present
                InstallDir = [string]$InstallDir
                Error      = $ErrorText
            }
        }

        # 1. Standard all-users installation recorded in HKLM.
        $pf = New-AhkFixtureRoot 'standard'
        $standardDir = Join-Path $pf 'AutoHotkey'
        $standardExe = New-AhkStub (Join-Path $standardDir 'v2')

        $resolved = Resolve-DevWSTrustedAutoHotkeyPath `
            -MachineRecord (New-AhkRecord 'Machine' $standardDir -Present) `
            -UserRecord (New-AhkRecord 'User' $null) `
            -TrustedRoots @($pf) `
            -ProgramFilesRoot $pf `
            -GetVersionInfo $versionReader

        Assert-Equal $standardExe $resolved "a standard all-users installation is accepted"

        # 2. Custom all-users installation that still lives under Program Files.
        $pf2 = New-AhkFixtureRoot 'custom'
        $customDir = Join-Path $pf2 'Dev Tools\AutoHotkey 2'
        $customExe = New-AhkStub (Join-Path $customDir 'v2')

        $resolved = Resolve-DevWSTrustedAutoHotkeyPath `
            -MachineRecord (New-AhkRecord 'Machine' $customDir -Present) `
            -UserRecord (New-AhkRecord 'User' $null) `
            -TrustedRoots @($pf2) `
            -ProgramFilesRoot $pf2 `
            -GetVersionInfo $versionReader

        Assert-Equal $customExe $resolved "a custom all-users installation under Program Files is accepted"

        # 3. No registry record: the canonical default is derived from Program Files.
        $pf3 = New-AhkFixtureRoot 'fallback'
        $fallbackExe = New-AhkStub (Join-Path $pf3 'AutoHotkey\v2')

        $resolved = Resolve-DevWSTrustedAutoHotkeyPath `
            -MachineRecord (New-AhkRecord 'Machine' $null) `
            -UserRecord (New-AhkRecord 'User' $null) `
            -TrustedRoots @($pf3) `
            -ProgramFilesRoot $pf3 `
            -GetVersionInfo $versionReader

        Assert-Equal $fallbackExe $resolved "the canonical default is derived from the Program Files known folder"

        # 4. Current-user-only installation: never authority, actionable refusal.
        $pf4 = New-AhkFixtureRoot 'useronly'
        $userDir = Join-Path $TestRoot 'ahk-trust-useronly\LocalAppData\Programs\AutoHotkey'
        $null = New-AhkStub (Join-Path $userDir 'v2')

        $error = $null
        try {
            $null = Resolve-DevWSTrustedAutoHotkeyPath `
                -MachineRecord (New-AhkRecord 'Machine' $null) `
                -UserRecord (New-AhkRecord 'User' $userDir -Present) `
                -TrustedRoots @($pf4) `
                -ProgramFilesRoot $pf4 `
                -GetVersionInfo $versionReader
        }
        catch { $error = $_.Exception.Message }

        Assert-True ($null -ne $error) "a current-user-only installation is not trusted"
        Assert-Contains $error "installed only for the current user" "the diagnostic explains the all-users requirement"
        Assert-Contains $error "High-integrity" "the diagnostic names the privileged reason"
        Assert-Contains $error "all-users AutoHotkey v2 installation" "the diagnostic prescribes the all-users installation"

        # 5. HKLM wins over an arbitrary HKCU record.
        $pf5 = New-AhkFixtureRoot 'both'
        $machineDir = Join-Path $pf5 'AutoHotkey'
        $machineExe = New-AhkStub (Join-Path $machineDir 'v2')
        $otherUserDir = Join-Path $TestRoot 'ahk-trust-both\LocalAppData\Programs\AutoHotkey'
        $null = New-AhkStub (Join-Path $otherUserDir 'v2')

        $resolved = Resolve-DevWSTrustedAutoHotkeyPath `
            -MachineRecord (New-AhkRecord 'Machine' $machineDir -Present) `
            -UserRecord (New-AhkRecord 'User' $otherUserDir -Present) `
            -TrustedRoots @($pf5) `
            -ProgramFilesRoot $pf5 `
            -GetVersionInfo $versionReader

        Assert-Equal $machineExe $resolved "HKLM is authoritative and HKCU cannot redirect it"

        # 6. Stale HKLM record: explicit failure, never a silent fallback.
        $pf6 = New-AhkFixtureRoot 'stale'
        $null = New-AhkStub (Join-Path $pf6 'AutoHotkey\v2')
        $staleDir = Join-Path $pf6 'Removed AutoHotkey'

        $error = $null
        try {
            $null = Resolve-DevWSTrustedAutoHotkeyPath `
                -MachineRecord (New-AhkRecord 'Machine' $staleDir -Present) `
                -UserRecord (New-AhkRecord 'User' $null) `
                -TrustedRoots @($pf6) `
                -ProgramFilesRoot $pf6 `
                -GetVersionInfo $versionReader
        }
        catch { $error = $_.Exception.Message }

        Assert-True ($null -ne $error) "a stale machine-wide record fails"
        Assert-Contains $error $staleDir "the failure names the recorded directory"
        Assert-Contains $error "not usable" "the failure is actionable"
        Assert-Contains $error "does not exist" "the failure names the missing interpreter"

        # 7. Machine-wide record outside Program Files.
        $pf7 = New-AhkFixtureRoot 'outside'
        $outsideDir = Join-Path $TestRoot 'ahk-trust-outside\User AutoHotkey'
        $null = New-AhkStub (Join-Path $outsideDir 'v2')

        $error = $null
        try {
            $null = Resolve-DevWSTrustedAutoHotkeyPath `
                -MachineRecord (New-AhkRecord 'Machine' $outsideDir -Present) `
                -UserRecord (New-AhkRecord 'User' $null) `
                -TrustedRoots @($pf7) `
                -ProgramFilesRoot $pf7 `
                -GetVersionInfo $versionReader
        }
        catch { $error = $_.Exception.Message }

        Assert-True ($null -ne $error) "a machine-wide record outside Program Files is refused"
        Assert-Contains $error "outside the administrator-protected Program Files roots" "the refusal names the root policy"

        # 8. Malformed and environment-variable records are explicit failures.
        foreach ($malformed in @('', '%ProgramFiles%\AutoHotkey', 'AutoHotkey')) {
            $error = $null
            try {
                $null = Resolve-DevWSTrustedAutoHotkeyPath `
                    -MachineRecord (New-AhkRecord 'Machine' $malformed -Present) `
                    -UserRecord (New-AhkRecord 'User' $null) `
                    -TrustedRoots @($pf7) `
                    -ProgramFilesRoot $pf7 `
                    -GetVersionInfo $versionReader
            }
            catch { $error = $_.Exception.Message }

            Assert-True ($null -ne $error) "malformed machine-wide record '$malformed' fails"
            Assert-Contains $error "HKLM\Software\AutoHotkey" "the failure names the registry record"
        }

        # 9. v1 and a wrong leaf are rejected by the pure candidate assessment.
        $v1Dir = Join-Path $pf7 'ahk-v1\v2'
        $v1Exe = New-AhkStub $v1Dir
        $v1 = Test-DevWSTrustedAutoHotkeyPath -Path $v1Exe -TrustedRoots @($pf7) -GetVersionInfo $versionReader
        Assert-Equal $false $v1.Ok "AutoHotkey v1 is refused"
        Assert-Contains $v1.Reason "not AutoHotkey v2" "the refusal names the version"

        $wrongLeaf = New-AhkStub (Join-Path $pf7 'wrong') 'AutoHotkey.exe'
        $wrong = Test-DevWSTrustedAutoHotkeyPath -Path $wrongLeaf -TrustedRoots @($pf7) -GetVersionInfo $versionReader
        Assert-Equal $false $wrong.Ok "a different executable name is refused"
        Assert-Contains $wrong.Reason "AutoHotkey64.exe" "the refusal names the required executable"

        $bare = Test-DevWSTrustedAutoHotkeyPath -Path 'AutoHotkey64.exe' -TrustedRoots @($pf7) -GetVersionInfo $versionReader
        Assert-Equal $false $bare.Ok "a bare executable name is refused"
        Assert-Contains $bare.Reason "not an absolute path" "the refusal names absoluteness"

        $outsideExe = New-AhkStub (Join-Path $TestRoot 'ahk-trust-outside\bin')
        $outside = Test-DevWSTrustedAutoHotkeyPath -Path $outsideExe -TrustedRoots @($pf7) -GetVersionInfo $versionReader
        Assert-Equal $false $outside.Ok "a user-writable location is refused"
        Assert-Contains $outside.Reason "outside the administrator-protected Program Files roots" "the refusal names the root policy"

        # 10. The canonical runtime entry point uses the resolver, never a literal.
        $paths = Get-SourceOf "src\lib\devws-paths.ps1"
        $start = $paths.IndexOf('function Resolve-DevWSTrustedAutoHotkeyPath')
        $end   = $paths.IndexOf('function Get-DevWSWindowsTerminalPath')
        Assert-True ($start -ge 0 -and $end -gt $start) "the AutoHotkey resolver region is located"

        $region = $paths.Substring($start, $end - $start)
        Assert-Contains $region 'Get-DevWSAutoHotkeyInstallRecord' "the resolver consumes the registry discovery adapter"
        Assert-Contains $region 'Test-DevWSTrustedAutoHotkeyPath' "the resolver applies the candidate policy"
        Assert-Contains $region "GetFolderPath('ProgramFiles')" "the fallback derives from the known folder"
        Assert-NotContains $region 'C:\Program Files' "no literal Program Files path is used"
        Assert-NotContains $region 'Get-Command' "no command discovery"
        Assert-NotContains $region '$env:PATH' "no PATH lookup"
        Assert-NotContains $region 'HKCU:\' "no user-hive authority"
    }

    Write-Host ""
    Start-TestGroup -Name 'install-layout' -Title 'Install layout'

    Test-Case "health requires every repository runtime library" {
        $required = @(Get-DevWSRequiredLibraryNames)
        $actual   = @(Get-ChildItem -Path (Join-Path $RepoRoot "src\lib") -Filter "*.ps1" -File | ForEach-Object { $_.Name })

        Assert-Equal $required.Count @($required | Sort-Object -Unique).Count "required library list has no duplicates"
        Assert-Equal (($actual | Sort-Object) -join ",") (($required | Sort-Object) -join ",") "health-required set matches src\lib exactly"

        $health = Get-SourceOf "src\lib\devws-health.ps1"
        Assert-Contains $health "Get-DevWSRequiredLibraryNames" "app-libs check uses the shared required-library list"
        Assert-NotContains $health '"devws-paths.ps1"' "no second hard-coded library list remains"
    }

    Test-Case "install manifest splits the normal and privileged surfaces" {
        $manifest = @(Get-DevWSInstallManifest -RepoRoot $RepoRoot)
        $targets  = @($manifest | ForEach-Object { $_.Target })
        $privilegedManifest = @(Get-DevWSPrivilegedInstallManifest -RepoRoot $RepoRoot)
        $privilegedTargets  = @($privilegedManifest | ForEach-Object { $_.Target })

        foreach ($required in @(
            "app\ws.ps1",
            "app\config\workspace.default.json",
            "app\lib\devws-paths.ps1",
            "app\lib\devws-config.ps1",
            "app\lib\devws-install.ps1",
            "app\lib\devws-health.ps1",
            "helpers\window-helper.ahk",
            "bin\ws.cmd"
        )) {
            Assert-True ($targets -contains $required) "normal manifest contains $required"
        }

        # The privileged surface is exactly workers + privileged libs + helpers.
        Assert-Equal 27 $privilegedManifest.Count "privileged manifest carries 27 files"
        Assert-Equal 19 @($privilegedTargets | Where-Object { $_ -like "lib\*.ps1" }).Count "19 privileged libraries"
        Assert-Equal 5  @($privilegedTargets | Where-Object { $_ -like "workers\*.ps1" }).Count "5 privileged workers"
        Assert-Equal 3  @($privilegedTargets | Where-Object { $_ -like "helpers\*" }).Count "3 privileged helpers"

        foreach ($required in @(
            "workers\elevated.ps1",
            "workers\elevated-capture.ps1",
            "workers\elevated-focus.ps1",
            "workers\elevated-reset.ps1",
            "workers\elevated-broker.ps1",
            "helpers\cwd-shell-bootstrap.ps1",
            "helpers\reset-window.ahk",
            "helpers\window-helper.ahk",
            "lib\devws-paths.ps1",
            "lib\devws-native.ps1"
        )) {
            Assert-True ($privilegedTargets -contains $required) "privileged manifest contains $required"
        }

        # High-reachable files must never stage to the user-writable root.
        Assert-Equal 1 @($targets | Where-Object { $_ -like "helpers\*" }).Count "only the medium helper stays user-owned"
        Assert-Equal 0 @($targets | Where-Object { $_ -like "workers\*" }).Count "workers never stage user-writable"

        foreach ($sharedLib in @(Get-DevWSPrivilegedLibraryNames)) {
            Assert-True ($targets -contains ("app\lib\" + $sharedLib)) "shared library still staged normal: $sharedLib"
            Assert-True ($privilegedTargets -contains ("lib\" + $sharedLib)) "shared library staged privileged: $sharedLib"
        }

        foreach ($entry in $manifest) {
            Assert-True (Test-Path -LiteralPath $entry.Source -PathType Leaf) "normal manifest source exists: $($entry.Source)"
        }

        foreach ($entry in $privilegedManifest) {
            Assert-True (Test-Path -LiteralPath $entry.Source -PathType Leaf) "privileged manifest source exists: $($entry.Source)"
        }

        # Targets are unique case-insensitively per surface (no collisions).
        foreach ($surface in @($targets, $privilegedTargets)) {
            $keys = @($surface | ForEach-Object { $_.ToLowerInvariant() })
            Assert-Equal $keys.Count (@($keys | Sort-Object -Unique).Count) "manifest targets are unique case-insensitively"
        }

        $libCount = @(Get-ChildItem -Path (Join-Path $RepoRoot "src\lib") -Filter "*.ps1" -File).Count
        Assert-Equal $libCount @($targets | Where-Object { $_ -like "app\lib\*.ps1" }).Count "all libraries are staged normal"

        # Every worker import is covered by the privileged library set.
        foreach ($worker in @(Get-DevWSPrivilegedWorkerNames)) {
            $source = Get-SourceOf ("src\workers\" + $worker)
            $imports = @([regex]::Matches($source, 'Join-Path \$LibDir "([^"]+\.ps1)"'))
            Assert-True ($imports.Count -gt 0) "$worker imports libraries"

            foreach ($match in $imports) {
                Assert-True ($privilegedTargets -contains ("lib\" + $match.Groups[1].Value)) "$worker dependency is privileged: $($match.Groups[1].Value)"
            }
        }

        # The privileged worker set matches src\workers exactly.
        $workerFiles = @(Get-ChildItem -Path (Join-Path $RepoRoot "src\workers") -Filter "*.ps1" -File | ForEach-Object { $_.Name } | Sort-Object)
        $privilegedWorkers = @($privilegedTargets | Where-Object { $_ -like "workers\*.ps1" } | ForEach-Object { Split-Path -Leaf $_ } | Sort-Object)
        Assert-Equal ($workerFiles -join ",") ($privilegedWorkers -join ",") "privileged worker set matches src\workers"
    }

    Test-Case "application files stage, verify, and parse in a fixture install root" {
        $fixture = New-InstallFixture "stage"
        $installed = @(Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root)

        Assert-True ($installed.Count -gt 10) "files staged"
        Assert-Equal 0 @(Get-DevWSMissingInstalledFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root).Count "no missing files"
        Assert-Equal 0 @(Get-DevWSInstalledPowerShellErrors -InstallRoot $fixture.Root).Count "installed PowerShell parses"
        Assert-True (Test-Path -LiteralPath $fixture.State -PathType Container) "state directory created"

        $shim = Get-Content -LiteralPath (Join-Path $fixture.Root "bin\ws.cmd") -Raw
        Assert-Contains $shim "$($fixture.Root)\app\ws.ps1" "shim points at this install root"
        Assert-NotContains $shim "\.ws\ws.ps1" "shim has no legacy v1 path"

        $second = @(Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root)
        Assert-Equal $installed.Count $second.Count "reinstall stages the same file set"
    }

    Test-Case "staged runtime files match repository bytes across both surfaces" {
        $fixture = New-InstallFixture "stage-parity"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $privileged = Initialize-TestPrivilegedFixture -Fixture $fixture -SkipNative

        Assert-Equal (Get-FileBase64 -Path (Join-Path $RepoRoot "src\ws.ps1")) (Get-FileBase64 -Path (Join-Path $fixture.Root "app\ws.ps1")) "ws.ps1 byte parity"
        Assert-Equal (Get-FileBase64 -Path $BundledConfigPath) (Get-FileBase64 -Path (Join-Path $fixture.Root "app\config\workspace.default.json")) "bundled config byte parity"

        foreach ($file in @(Get-ChildItem -Path (Join-Path $RepoRoot "src\lib") -Filter "*.ps1" -File)) {
            Assert-Equal (Get-FileBase64 -Path $file.FullName) (Get-FileBase64 -Path (Join-Path $fixture.Root ("app\lib\" + $file.Name))) "normal lib parity: $($file.Name)"
        }

        # Shared libraries stage byte-identically into BOTH surfaces.
        foreach ($name in @(Get-DevWSPrivilegedLibraryNames)) {
            Assert-Equal (Get-FileBase64 -Path (Join-Path $RepoRoot ("src\lib\" + $name))) (Get-FileBase64 -Path (Join-Path $privileged ("lib\" + $name))) "privileged lib parity: $name"
        }

        foreach ($name in @(Get-DevWSPrivilegedHelperNames)) {
            Assert-Equal (Get-FileBase64 -Path (Join-Path $RepoRoot ("src\helpers\" + $name))) (Get-FileBase64 -Path (Join-Path $privileged ("helpers\" + $name))) "privileged helper parity: $name"
        }

        foreach ($name in @(Get-DevWSPrivilegedWorkerNames)) {
            Assert-Equal (Get-FileBase64 -Path (Join-Path $RepoRoot ("src\workers\" + $name))) (Get-FileBase64 -Path (Join-Path $privileged ("workers\" + $name))) "privileged worker parity: $name"
        }

        Assert-Equal (Get-FileBase64 -Path (Join-Path $RepoRoot "src\helpers\window-helper.ahk")) (Get-FileBase64 -Path (Join-Path $fixture.Root "helpers\window-helper.ahk")) "medium helper parity"

        # bin\ws.cmd is generated for this install root; validate the generated
        # content instead of demanding byte equality with the repo template.
        $shim = Get-Content -LiteralPath (Join-Path $fixture.Root "bin\ws.cmd") -Raw
        Assert-Contains $shim "$($fixture.Root)\app\ws.ps1" "generated shim targets this install root"
        Assert-NotContains $shim "\.ws\ws.ps1" "generated shim is not the v1 shim"

        Assert-Equal 0 @(Get-DevWSInstalledPowerShellErrors -InstallRoot $fixture.Root).Count "every staged normal .ps1 parses"
        Assert-Equal 0 @(Get-DevWSPrivilegedPowerShellErrors -PrivilegedRoot $privileged).Count "every staged privileged .ps1 parses"

        # Every library each worker dot-sources is staged into its own surface.
        foreach ($worker in @(Get-DevWSPrivilegedWorkerNames)) {
            $source = Get-SourceOf ("src\workers\" + $worker)
            $imports = @([regex]::Matches($source, 'Join-Path \$LibDir "([^"]+\.ps1)"'))

            Assert-True ($imports.Count -gt 0) "$worker imports libraries"

            foreach ($match in $imports) {
                $libName = $match.Groups[1].Value
                Assert-True (Test-Path -LiteralPath (Join-Path $privileged ("lib\" + $libName)) -PathType Leaf) "$worker dependency staged privileged: $libName"
                Assert-True (Test-Path -LiteralPath (Join-Path $fixture.Root ("app\lib\" + $libName)) -PathType Leaf) "$worker dependency staged normal: $libName"
            }
        }
    }

    Test-Case "staged install runs list and recognizes the Phase 6 command surface" {
        $fixture = New-InstallFixture "staged-cli"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $target = Join-Path $fixture.Root "canonical.json"
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $target

        $stagedWs = Join-Path $fixture.Root "app\ws.ps1"

        $env:DEVWS_CONFIG = $target

        try {
            $output = & pwsh -NoLogo -NoProfile -File $stagedWs list 2>&1 | Out-String
            $code   = $LASTEXITCODE
        }
        finally {
            Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
        }

        Assert-Equal 0 $code "staged ws list exit"
        Assert-Contains $output "slot" "staged ws list output"

        $helpOutput = & pwsh -NoLogo -NoProfile -File $stagedWs help 2>&1 | Out-String
        Assert-Equal 0 $LASTEXITCODE "staged ws help exit"
        Assert-Contains $helpOutput "help all" "staged quick help advertises help all"
        Assert-NotContains $helpOutput "ws add-app" "staged quick help is concise"

        $helpAllOutput = & pwsh -NoLogo -NoProfile -File $stagedWs help all 2>&1 | Out-String
        Assert-Equal 0 $LASTEXITCODE "staged ws help all exit"

        foreach ($needle in @("ws edit", "ws health", "ws doctor", "ws detect-app", "ws add-app", "ws clone-terminal", "ws set-geometry", "ws reset-layout")) {
            Assert-Contains $helpAllOutput $needle "staged help all mentions $needle"
        }
    }

    Test-Case "shim and hotkey templates match generated installed content" {
        $shimTemplate = Get-Content -LiteralPath (Join-Path $RepoRoot "src\shim\ws.cmd") -Raw
        $shimGenerated = New-DevWSShimContent

        Assert-Equal ($shimTemplate -replace "`r`n", "`n").Trim() ($shimGenerated -replace "`r`n", "`n").Trim() "shim template matches generated default"
        Assert-Contains $shimTemplate "%LOCALAPPDATA%\DevWS\app\ws.ps1" "shim template targets the installed app"
        Assert-NotContains $shimTemplate "\.ws\ws.ps1" "shim template no longer targets v1"

        # The template keeps a host-independent %LOCALAPPDATA% token for the
        # generated-bindings include path; generated content resolves it to the
        # concrete default state path.
        $hotkeyTemplate = (Get-Content -LiteralPath (Join-Path $RepoRoot "src\hotkeys\TerminalShortcut.ahk") -Raw).Replace('%LOCALAPPDATA%', $env:LOCALAPPDATA)
        $bindingsPath   = Join-Path $env:LOCALAPPDATA "DevWS\state\hotkeys\bindings.ahk"
        $hotkeyGenerated = New-DevWSTerminalShortcutContent `
            -AppScriptPath (Join-Path $env:LOCALAPPDATA "DevWS\app\ws.ps1") `
            -BindingsPath $bindingsPath

        Assert-Equal ($hotkeyTemplate -replace "`r`n", "`n").Trim() ($hotkeyGenerated -replace "`r`n", "`n").Trim() "hotkey template matches generated default"
        Assert-NotContains $hotkeyGenerated "AdminTerminal" "no retired external task binding"
        Assert-NotContains $hotkeyGenerated "!t::" "no built-in Alt+T handler"
        Assert-NotContains $hotkeyGenerated "schtasks /run" "no external scheduled-task invocation"
        Assert-Contains $hotkeyGenerated 'EnvGet("LOCALAPPDATA")' "paths resolve LOCALAPPDATA"
        Assert-Contains $hotkeyGenerated '\DevWS\app\ws.ps1' "fallback targets the installed app"
        Assert-Contains $hotkeyGenerated '\DevWS\app\coordinator.ps1' "coordinator start targets the installed host"
        Assert-NotContains $hotkeyGenerated '\.ws\ws.ps1' "launch no longer targets v1"
        Assert-Contains $hotkeyGenerated "#SingleInstance Force" "SingleInstance retained"
        Assert-Contains $hotkeyGenerated '#Include "*i' "generated include is optional for a missing file"
        Assert-Contains $hotkeyGenerated $bindingsPath "include targets the generated state file"
        Assert-True (Test-DevWSManagedHotkeyIncludeContract -Content $hotkeyGenerated -BindingsPath $bindingsPath) "include contract recognized"

        # Stage 1 contract: the normal Alt+Shift+T path sends a launch request
        # to the warm coordinator over local IPC; the direct pwsh spawn is only
        # the bounded fallback and the login startup ensure is idempotent.
        Assert-Contains $hotkeyGenerated '!+t::DevWSLaunchWorkspace()' "Alt+Shift+T uses the direct IPC sender"
        Assert-Contains $hotkeyGenerated 'DevWS.Coordinator.v1' "the coordinator pipe name is part of the contract"
        Assert-Contains $hotkeyGenerated 'DevWSCoordinatorRequest()' "the IPC request helper exists"
        Assert-Contains $hotkeyGenerated 'DevWSCoordinatorStart()' "bounded coordinator recovery exists"
        Assert-Contains $hotkeyGenerated 'DevWSCoordinatorProbe()' "login startup ensure exists"
        Assert-Contains $hotkeyGenerated 'DevWSAppScript ''" launch''' "fallback launches the bare workspace"
        Assert-NotContains $hotkeyGenerated "!+t::Run('pwsh" "the old direct pwsh hotkey line is gone"
        Assert-NotContains $hotkeyGenerated "launch main" "no hard-coded default set"
        Assert-NotContains $hotkeyGenerated "launch secondary" "no hard-coded non-default set"
        Assert-True (Test-DevWSManagedHotkeyContent -Content $hotkeyGenerated -InstallRoot (Join-Path $env:LOCALAPPDATA "DevWS")) "generated content satisfies the managed-hotkey contract"
        Assert-True (Test-DevWSManagedHotkeyContent -Content $hotkeyTemplate -InstallRoot (Join-Path $env:LOCALAPPDATA "DevWS")) "template satisfies the managed-hotkey contract"

        $install = Get-SourceOf "src\lib\devws-install.ps1"
        $start   = $install.IndexOf("function New-DevWSTerminalShortcutContent")
        $end     = $install.IndexOf("function Test-DevWSLegacyHotkeyContent")
        Assert-True ($start -ge 0 -and $end -gt $start) "hotkey generation located"

        $hotkeyRegion = $install.Substring($start, $end - $start)
        Assert-NotContains $hotkeyRegion "defaultSet" "hotkey generation never depends on defaultSet"
    }

    Write-Host ""
    Start-TestGroup -Name 'privileged-runtime' -Title 'Privileged runtime split (Security Phase 1)'

    Test-Case "the privileged path split resolves the protected roots" {
        Assert-Equal "repository" (Get-DevWSPathsLayout) "repository layout detected"
        Assert-Equal ([Environment]::GetFolderPath('ProgramFiles') + "\DevWS\privileged") (Get-DevWSPrivilegedInstallRoot) "privileged root derives from the registry Program Files"
        Assert-Equal (Join-Path (Get-DevWSPrivilegedInstallRoot) "lib") (Get-DevWSPrivilegedLibRoot) "privileged lib root"
        Assert-Equal (Join-Path (Get-DevWSPrivilegedInstallRoot) "workers") (Get-DevWSPrivilegedWorkersRoot) "privileged workers root"
        Assert-Equal (Join-Path (Get-DevWSPrivilegedInstallRoot) "helpers") (Get-DevWSPrivilegedHelpersRoot) "privileged helpers root"
        Assert-Equal (Join-Path (Get-DevWSPrivilegedInstallRoot) "native\DevWS.Native.dll") (Get-DevWSPrivilegedNativeDllPath) "privileged native DLL path"
        Assert-True ((Get-DevWSPrivilegedInstallRoot).StartsWith([Environment]::GetFolderPath('ProgramFiles'), [StringComparison]::OrdinalIgnoreCase)) "privileged root lives under Program Files"
        Assert-True (-not (Test-DevWSPathUnderRoot -Path (Get-DevWSPrivilegedInstallRoot) -Root ([Environment]::GetFolderPath('LocalApplicationData')))) "privileged root is never under LocalAppData"

        foreach ($name in @(Get-DevWSPrivilegedLibraryNames)) {
            Assert-True (Test-Path -LiteralPath (Join-Path $RepoRoot ("src\lib\" + $name)) -PathType Leaf) "privileged library source exists: $name"
        }

        foreach ($name in @(Get-DevWSPrivilegedWorkerNames)) {
            Assert-True (Test-Path -LiteralPath (Join-Path $RepoRoot ("src\workers\" + $name)) -PathType Leaf) "privileged worker source exists: $name"
        }
    }

    Test-Case "trusted PowerShell resolution accepts the protected installation and rejects user-writable candidates" {
        $real = Resolve-DevWSTrustedPowerShellPath
        Assert-True ($real.EndsWith("pwsh.exe", [StringComparison]::OrdinalIgnoreCase)) "resolved executable is pwsh.exe"
        Assert-True ([System.IO.Path]::IsPathRooted($real)) "resolved executable is absolute"
        Assert-Equal $true (Test-DevWSTrustedExecutablePath -Path $real) "protected installation accepted"

        $copy = Join-Path $TestRoot "trusted-pwsh-copy\pwsh.exe"
        New-Item -ItemType Directory -Path (Split-Path -Parent $copy) -Force | Out-Null
        [System.IO.File]::Copy($real, $copy, $true)
        Assert-Equal $false (Test-DevWSTrustedExecutablePath -Path $copy) "user-writable copy rejected"
        Assert-Equal $false (Test-DevWSTrustedExecutablePath -Path (Join-Path $TestRoot "missing-pwsh.exe")) "missing candidate rejected"
        Assert-Equal $false (Test-DevWSTrustedExecutablePath -Path "pwsh.exe") "relative candidate rejected"

        Assert-Throws { Resolve-DevWSTrustedPowerShellPath -CandidatePath $copy } "not a trusted privileged-execution candidate"
        Assert-Equal $real (Resolve-DevWSTrustedPowerShellPath -CandidatePath $real -VerifyRuntime) "runtime verification accepts the real installation"

        # Audit correction: the trusted root list is exactly Program Files /
        # Program Files (x86) / %SystemRoot%\System32 and the candidate must be
        # named pwsh.exe.
        Assert-Equal $false ((Get-DevWSTrustedExecutableRoots) -contains ([Environment]::GetFolderPath('Windows'))) "the whole Windows folder is never a trusted root"
        Assert-Equal $false (Test-DevWSTrustedExecutablePath -Path (Join-Path $env:SystemRoot "System32\cmd.exe")) "a non-pwsh System32 executable is rejected by name"
        Assert-Equal $false (Test-DevWSTrustedExecutablePath -Path (Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe")) "Windows PowerShell is rejected (name and root)"
        Assert-Equal $false (Test-DevWSTrustedExecutablePath -Path (Join-Path $env:SystemRoot "System32\not-pwsh.exe")) "an arbitrary System32 descendant is rejected"
        Assert-Equal "pwsh.exe" (Split-Path -Leaf $real) "the trusted resolver only ever selects pwsh.exe"
    }

    Test-Case "installed privileged resolution ignores hostile environment overrides" {
        $fixture = New-InstallFixture "priv-env"
        $privileged = Initialize-TestPrivilegedFixture -Fixture $fixture

        $probe = Join-Path $fixture.Root "probe-env.ps1"
        Set-Content -LiteralPath $probe -Value @(
            'Set-StrictMode -Version Latest',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-paths.ps1")',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-cwd-paths.ps1")',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-cwd.ps1")',
            '"layout=$(Get-DevWSPathsLayout)"',
            '"privRoot=$(Get-DevWSPrivilegedInstallRoot)"',
            '"privLib=$(Get-DevWSPrivilegedLibRoot)"',
            '"privWorkers=$(Get-DevWSPrivilegedWorkersRoot)"',
            '"privHelpers=$(Get-DevWSPrivilegedHelpersRoot)"',
            '"privNative=$(Get-DevWSPrivilegedNativeDllPath)"',
            '"userRoot=$(Get-DevWSInstallRoot)"',
            '"helpers=$(Get-DevWSHelpersRoot)"',
            '"workers=$(Get-DevWSWorkersRoot)"',
            '"windowHelper=$(Get-DevWSWindowHelperPath)"',
            '"resetHelper=$(Get-DevWSResetWindowHelperPath)"',
            '"bootstrap=$(Get-DevWSCwdBootstrapPath)"',
            '"wt=$(Get-DevWSWindowsTerminalPath)"',
            '"wtTrusted=$(try { Resolve-DevWSTrustedWindowsTerminalPath } catch { ''ERROR: '' + $_.Exception.Message })"',
            '"wtRecords=$(( @(Get-DevWSWindowsTerminalPackageRecords | ForEach-Object { $_.Name + "|" + $_.PackageFamilyName + "|" + $_.PublisherId }) -join ";"))"',
            '$env:PATH = "C:\hostile-path"',
            '"wtTrustedAfterPathPoison=$(try { Resolve-DevWSTrustedWindowsTerminalPath } catch { ''ERROR: '' + $_.Exception.Message })"',
            '"ahk=$(try { Get-DevWSAutoHotkeyPath } catch { ''ERROR: '' + $_.Exception.Message })"',
            '"startup=$(Get-DevWSStartupPath)"'
        )

        $savedEnv = @{}
        foreach ($name in @('DEVWS_INSTALL_ROOT', 'DEVWS_WORKERS_ROOT', 'DEVWS_HELPERS_ROOT', 'DEVWS_AHK_PATH', 'DEVWS_WT_PATH', 'DEVWS_STARTUP_PATH')) {
            $savedEnv[$name] = [Environment]::GetEnvironmentVariable($name)
        }

        try {
            $env:DEVWS_INSTALL_ROOT = "C:\hostile-install"
            $env:DEVWS_WORKERS_ROOT  = "C:\hostile-workers"
            $env:DEVWS_HELPERS_ROOT  = "C:\hostile-helpers"
            $env:DEVWS_AHK_PATH      = "C:\hostile-ahk.exe"
            $env:DEVWS_WT_PATH       = "C:\hostile-wt.exe"
            $env:DEVWS_STARTUP_PATH  = "C:\hostile-startup"

            $output = & pwsh -NoLogo -NoProfile -File $probe 2>&1 | Out-String
            $code = $LASTEXITCODE
        }
        finally {
            foreach ($name in $savedEnv.Keys) {
                [Environment]::SetEnvironmentVariable($name, $savedEnv[$name])
            }
        }

        Assert-Equal 0 $code "env probe exits cleanly`n$output"
        Assert-Contains $output "layout=installed-privileged" "privileged layout detected"
        Assert-Contains $output "privRoot=$privileged" "privileged root is the file's own root"
        Assert-Contains $output "privWorkers=$privileged\workers" "privileged workers root"
        Assert-Contains $output "privHelpers=$privileged\helpers" "privileged helpers root"
        Assert-Contains $output "privNative=$privileged\native\DevWS.Native.dll" "privileged native path"
        Assert-Contains $output "helpers=$privileged\helpers" "layout-local helpers root"
        Assert-Contains $output "workers=$privileged\workers" "layout-local workers root"
        Assert-Contains $output "windowHelper=$privileged\helpers\window-helper.ahk" "window helper routed privileged"
        Assert-Contains $output "resetHelper=$privileged\helpers\reset-window.ahk" "reset helper routed privileged"
        Assert-Contains $output "bootstrap=$privileged\helpers\cwd-shell-bootstrap.ps1" "bootstrap routed privileged"
        Assert-Contains $output "userRoot=$([Environment]::GetFolderPath('LocalApplicationData'))\DevWS" "user root derives from the registry LocalAppData"
        Assert-Contains $output "wt=$([Environment]::GetFolderPath('LocalApplicationData'))\Microsoft\WindowsApps\wt.exe" "WT alias derives from the registry LocalAppData"
        $expectedAhk = $null
        try { $expectedAhk = Resolve-DevWSTrustedAutoHotkeyPath } catch { $expectedAhk = $null }

        if ($null -ne $expectedAhk) {
            Assert-Contains $output ("ahk=" + $expectedAhk) "installed resolution uses the machine-wide trusted resolver"
        }
        else {
            Assert-Contains $output "ahk=ERROR: " "installed resolution fails closed when no machine-wide installation exists"
        }

        Assert-NotContains $output "hostile-ahk" "the installed layout never honors the AutoHotkey override"
        Assert-NotContains $output "hostile" "no hostile override is honored"

        # The installed launch path must never trust the alias pathname: the
        # trusted resolver selects the registered package executable (or fails
        # closed when no package is registered).
        $livePackage = @(Get-AppxPackage -Name "Microsoft.WindowsTerminal" -ErrorAction SilentlyContinue | Select-Object -First 1)[0]

        if ($null -ne $livePackage -and -not [string]::IsNullOrWhiteSpace([string]$livePackage.InstallLocation)) {
            $liveExe = Join-Path ([string]$livePackage.InstallLocation) "WindowsTerminal.exe"
            Assert-Contains $output "wtTrusted=$liveExe" "installed resolver selects the protected package executable"
            Assert-True ($liveExe.StartsWith([Environment]::GetFolderPath('ProgramFiles') + "\WindowsApps\", [StringComparison]::OrdinalIgnoreCase)) "package executable lives under Program Files\WindowsApps"
            Assert-NotContains $output "wtTrusted=$([Environment]::GetFolderPath('LocalApplicationData'))" "the trusted launcher is never the user-profile alias"
            Assert-Contains $output "wtRecords=Microsoft.WindowsTerminal|Microsoft.WindowsTerminal_8wekyb3d8bbwe|8wekyb3d8bbwe" "native package records carry the official identity"
            Assert-Contains $output "wtTrustedAfterPathPoison=$liveExe" "resolution is independent of PATH in an installed host"
        }
        else {
            Assert-Contains $output "wtTrusted=ERROR: Windows Terminal is not registered" "resolution fails closed without a registered package"
            Assert-Contains $output "wtRecords=" "no native records without a registered package"
            Assert-Contains $output "wtTrustedAfterPathPoison=ERROR" "resolution still fails closed after a PATH poison"
        }
    }

    Test-Case "installed workers fail closed without a complete privileged runtime" {
        $fixture = New-InstallFixture "priv-incomplete"
        $privileged = Initialize-TestPrivilegedFixture -Fixture $fixture
        Remove-Item -LiteralPath (Join-Path $privileged "lib\devws-state.ps1") -Force

        $probe = Join-Path $fixture.Root "probe-incomplete.ps1"
        Set-Content -LiteralPath $probe -Value @(
            '$ErrorActionPreference = ''Stop''',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-paths.ps1")',
            'Assert-DevWSWorkerLibraryRoot -LibDir (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib")',
            'Write-Output "NOTHROW"'
        )

        $output = & pwsh -NoLogo -NoProfile -File $probe 2>&1 | Out-String
        Assert-Contains $output "is incomplete" "incomplete privileged runtime fails closed"
        Assert-Contains $output "devws-state.ps1" "the missing privileged file is named"
        Assert-NotContains $output "NOTHROW" "the assert never silently passes"

        # A legacy user-writable worker location has no library fallback.
        $legacyDir = Join-Path $fixture.Root "legacy-workers"
        New-Item -ItemType Directory -Path $legacyDir -Force | Out-Null
        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\workers\elevated.ps1") -Destination (Join-Path $legacyDir "elevated.ps1")
        $legacyOutput = & pwsh -NoLogo -NoProfile -File (Join-Path $legacyDir "elevated.ps1") 2>&1 | Out-String
        Assert-Contains $legacyOutput "runtime libraries were not found" "legacy user-writable worker location has no fallback"
        Assert-NotContains $legacyOutput "Worker request file" "legacy worker never reaches request handling"

        # The worker library assert rejects installed-normal (user-writable) layouts.
        $normalFixture = New-InstallFixture "priv-normal-assert"
        New-Item -ItemType Directory -Path $normalFixture.Lib -Force | Out-Null
        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\lib\devws-paths.ps1") -Destination (Join-Path $normalFixture.Lib "devws-paths.ps1")
        $normalProbe = Join-Path $normalFixture.Root "probe-normal.ps1"
        Set-Content -LiteralPath $normalProbe -Value @(
            '$ErrorActionPreference = ''Stop''',
            '. (Join-Path $PSScriptRoot "app\lib\devws-paths.ps1")',
            'Assert-DevWSWorkerLibraryRoot -LibDir (Join-Path $PSScriptRoot "app\lib")',
            'Write-Output "NOTHROW"'
        )
        $normalOutput = & pwsh -NoLogo -NoProfile -File $normalProbe 2>&1 | Out-String
        Assert-Contains $normalOutput "must not run from the user-writable install layout" "installed-normal worker layout rejected"
    }

    Test-Case "installed privileged terminal creation uses the absolute trusted shell token" {
        $fixture = New-InstallFixture "priv-argv"
        $privileged = Initialize-TestPrivilegedFixture -Fixture $fixture -SkipNative

        # The repository/session layout keeps the historical bare token.
        Assert-Equal "pwsh" (Get-DevWSPowerShellLaunchToken) "repository layout keeps the bare shell token"

        $probe = Join-Path $fixture.Root "probe-argv.ps1"
        Set-Content -LiteralPath $probe -Value @'
$ErrorActionPreference = 'Stop'
$priv = Join-Path $PSScriptRoot "Program Files\DevWS\privileged"
. (Join-Path $priv "lib\devws-paths.ps1")
. (Join-Path $priv "lib\devws-config.ps1")
. (Join-Path $priv "lib\devws-bindings.ps1")
. (Join-Path $priv "lib\devws-terminal.ps1")

$terminal = [pscustomobject]@{
    id = "poc"; type = "terminal"; enabled = $true; windowId = "DevWS-poc"; path = "C:\"
    elevated = $true
    tabs = @([pscustomobject]@{ command = $null; args = @() })
    activeTab = 0
    layout = [pscustomobject]@{ x = 0; y = 0; w = 100; h = 100 }
}
$context = [pscustomobject]@{
    BootstrapPath   = (Join-Path $priv "helpers\cwd-shell-bootstrap.ps1")
    SetId           = "main"; TerminalId = "poc"; WindowId = "DevWS-poc"; TabIndex = 0
    SessionId       = "session"; PublicationPath = (Join-Path $priv "publication.json")
    ChildSpecBase64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes('{"command":null,"args":[]}'))
}
$argv = @(New-DevWSTerminalCreateArguments -Terminal $terminal -TrackingContexts @($context))
foreach ($entry in $argv) { Write-Output ("ARG:" + $entry) }
'@

        $output = & pwsh -NoLogo -NoProfile -File $probe 2>&1 | Out-String
        Assert-Equal 0 $LASTEXITCODE "argv probe exits cleanly`n$output"

        $argvEntries = @($output -split "`r?`n" | Where-Object { $_.StartsWith("ARG:") } | ForEach-Object { $_.Substring(4) })
        $expectedShell = (ConvertTo-DevWSTerminalCommandLineToken -Value (Resolve-DevWSTrustedPowerShellPath))
        $expectedBootstrap = (ConvertTo-DevWSTerminalCommandLineToken -Value (Join-Path $privileged "helpers\cwd-shell-bootstrap.ps1"))

        # Windows Terminal quotes payload tokens containing spaces itself; the
        # token must be passed raw (embedded quotes break the tab commandline,
        # proven live during deployment validation).
        Assert-True ($argvEntries -contains $expectedShell) "absolute trusted shell token present"
        Assert-True ($expectedShell -ne "pwsh") "installed layout never uses the bare shell token"
        Assert-True (-not $expectedShell.Contains('"')) "shell token is passed raw (no embedded quotes)"
        Assert-True (-not $expectedBootstrap.Contains('"')) "bootstrap token is passed raw (no embedded quotes)"
        $fileIndex = [array]::IndexOf($argvEntries, "-File")
        Assert-True ($fileIndex -ge 0) "-File present"
        Assert-Equal $expectedBootstrap $argvEntries[$fileIndex + 1] "privileged bootstrap path follows -File"
        Assert-True ($argvEntries -contains "-NoExit") "-NoExit preserved"
        Assert-True (-not ($argvEntries -contains "-NoProfile")) "interactive tabs never add -NoProfile"
        Assert-True (-not ($argvEntries -contains "pwsh")) "no bare pwsh token anywhere in the argv"
    }

    Test-Case "native runtime layout routes by integrity surface" {
