        $repoLayout = Get-DevWSNativeRuntimeLayout -LibRoot (Join-Path $RepoRoot "src\lib")
        Assert-Equal "repository" $repoLayout.Mode "repository native layout"
        Assert-Equal (Join-Path $RepoRoot "src\native") $repoLayout.NativeRoot "repository native root"

        $normalLayout = Get-DevWSNativeRuntimeLayout -LibRoot (Join-Path $fixture.Root "app\lib")
