    Test-Case "effective generation tracks normal and privileged runtime changes separately" {
        $fixture = New-InstallFixture "priv-gen"
        $privileged = Initialize-TestPrivilegedFixture -Fixture $fixture -SkipNative

        New-Item -ItemType Directory -Path $fixture.Lib, $fixture.Bin -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $fixture.Lib "normal.ps1") -Value "# normal" -NoNewline

        $privGen1 = Get-DevWSPrivilegedRuntimeGeneration -Root $privileged
        $effGen1  = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $fixture.Root -PrivilegedRoot $privileged
        Assert-Equal $privGen1 (Get-DevWSPrivilegedRuntimeGeneration -Root $privileged) "privileged generation is deterministic"

        Set-Content -LiteralPath (Join-Path $privileged "lib\devws-paths.ps1") -Value "# changed" -NoNewline
        $privGen2 = Get-DevWSPrivilegedRuntimeGeneration -Root $privileged
        $effGen2  = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $fixture.Root -PrivilegedRoot $privileged
        Assert-True ($privGen2 -ne $privGen1) "privileged change moves the privileged generation"
        Assert-True ($effGen2 -ne $effGen1) "privileged change moves the effective generation"

        Set-Content -LiteralPath (Join-Path $fixture.Lib "normal.ps1") -Value "# normal changed" -NoNewline
        $effGen3 = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $fixture.Root -PrivilegedRoot $privileged
        Assert-True ($effGen3 -ne $effGen2) "normal change moves the effective generation"
        Assert-Equal $privGen2 (Get-DevWSPrivilegedRuntimeGeneration -Root $privileged) "normal change leaves the privileged generation alone"
    }

    Test-Case "host integrity helper reports the current token label" {
        $integrity = Get-DevWSProcessIntegrityLevel
        Assert-True ($integrity.Name -in @("Low", "Medium", "High", "System", "Untrusted", "Unknown")) "known integrity name"

        if ($null -ne $integrity.Sid) {
            $expected = @{
                "S-1-16-4096"  = "Low"
                "S-1-16-8192"  = "Medium"
                "S-1-16-12288" = "High"
                "S-1-16-16384" = "System"
                "S-1-16-2048"  = "Untrusted"
            }[$integrity.Sid]
            Assert-Equal $expected $integrity.Name "name matches the label SID"
        }

        Assert-Equal ($integrity.Name -eq "High") $integrity.IsHigh "IsHigh is derived from the label"
        Assert-Equal ($integrity.Name -eq "Medium") $integrity.IsMedium "IsMedium is derived from the label"
    }

    Test-Case "trusted Windows Terminal identity policy is fail-closed" {
        $fixture = New-InstallFixture "priv-wt-policy"
        $fixtureRoots = Join-Path $fixture.Root "WindowsApps"
        $packageDir = Join-Path $fixtureRoots "Microsoft.WindowsTerminal_1.2.3.0_x64__8wekyb3d8bbwe"
        New-Item -ItemType Directory -Path $packageDir -Force | Out-Null
        $exe = Join-Path $packageDir "WindowsTerminal.exe"
        Set-Content -LiteralPath $exe -Value "fixture" -NoNewline

        Assert-Equal $true (Test-DevWSTrustedWindowsTerminalCandidate -Path $exe -TrustedRoots @($fixtureRoots)) "fixture package executable accepted"
        Assert-Equal $true (Test-DevWSTrustedWindowsTerminalCandidate -Path $exe -TrustedRoots @("C:\other", $fixtureRoots)) "any matching trusted root is accepted"
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path $exe -TrustedRoots @()) "empty trusted roots rejected"
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path (Join-Path $packageDir "missing.exe") -TrustedRoots @($fixtureRoots)) "missing launcher rejected"

        # An ordinary file at the expected alias pathname is never a package launcher.
        $ordinaryAlias = Join-Path $fixture.Root "alias\wt.exe"
        New-Item -ItemType Directory -Path (Split-Path -Parent $ordinaryAlias) -Force | Out-Null
        Set-Content -LiteralPath $ordinaryAlias -Value "fake" -NoNewline
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path $ordinaryAlias -TrustedRoots @($fixtureRoots)) "ordinary wt.exe outside WindowsApps rejected"
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path $ordinaryAlias -TrustedRoots @((Split-Path -Parent $ordinaryAlias))) "ordinary wt.exe rejected even under a declared root (wrong name)"

        # Wrong executable name inside the package directory.
        $wrongName = Join-Path $packageDir "wt.exe"
        Set-Content -LiteralPath $wrongName -Value "fixture" -NoNewline
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path $wrongName -TrustedRoots @($fixtureRoots)) "wrong executable name rejected"

        # Candidate outside the trusted root.
        $outside = Join-Path $fixture.Root "elsewhere\WindowsTerminal.exe"
        New-Item -ItemType Directory -Path (Split-Path -Parent $outside) -Force | Out-Null
        Set-Content -LiteralPath $outside -Value "fixture" -NoNewline
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path $outside -TrustedRoots @($fixtureRoots)) "candidate outside the trusted root rejected"

        # Junction substitute: no reparse point may appear between the trusted
        # root and the candidate.
        $junctionTarget = Join-Path $fixture.Root "junction-target"
        New-Item -ItemType Directory -Path $junctionTarget -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $junctionTarget "WindowsTerminal.exe") -Value "fixture" -NoNewline
        $junctionPackage = Join-Path $fixtureRoots "Microsoft.WindowsTerminal_9.9.9.0_x64__8wekyb3d8bbwe"
        cmd /c mklink /J "$junctionPackage" "$junctionTarget" | Out-Null
        Assert-True (Test-Path -LiteralPath $junctionPackage -PathType Container) "junction fixture created"
        Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path (Join-Path $junctionPackage "WindowsTerminal.exe") -TrustedRoots @($fixtureRoots)) "junction substitute rejected"

        # Live read-only validation of the real machine identity (the real
        # appexec link is never modified).
        $livePackage = @(Get-AppxPackage -Name "Microsoft.WindowsTerminal" -ErrorAction SilentlyContinue | Select-Object -First 1)[0]

        if ($null -ne $livePackage -and -not [string]::IsNullOrWhiteSpace([string]$livePackage.InstallLocation)) {
            $liveExe = Join-Path ([string]$livePackage.InstallLocation) "WindowsTerminal.exe"
            Assert-Equal $true (Test-DevWSTrustedWindowsTerminalCandidate -Path $liveExe -TrustedRoots @(Get-DevWSTrustedWindowsTerminalRoots)) "live package executable accepted"
            Assert-Equal ([System.IO.Path]::GetFullPath($liveExe)) (Resolve-DevWSTrustedWindowsTerminalPath -Installed) "installed resolver returns the live package executable"
            Assert-Equal $false (Test-DevWSTrustedWindowsTerminalCandidate -Path (Join-Path $env:LOCALAPPDATA "Microsoft\WindowsApps\wt.exe") -TrustedRoots @(Get-DevWSTrustedWindowsTerminalRoots)) "the per-user alias is never a trusted package launcher"
        }
        else {
            Assert-Throws { Resolve-DevWSTrustedWindowsTerminalPath -Installed } "not registered" "resolution fails closed without a registered package"
        }
    }

    Test-Case "trusted Windows Terminal package selection is exact and fail-closed" {
        Assert-Equal "Microsoft.WindowsTerminal" ([string]$script:DevWSOfficialWindowsTerminalPackageName) "official package name constant"
        Assert-Equal "Microsoft.WindowsTerminal_8wekyb3d8bbwe" ([string]$script:DevWSOfficialWindowsTerminalPackageFamilyName) "official package family constant"
        Assert-Equal "8wekyb3d8bbwe" ([string]$script:DevWSOfficialWindowsTerminalPublisherId) "official publisher id constant"

        $officialLocation = Join-Path $TestRoot "p6f-packages\Microsoft.WindowsTerminal_1.0.0.0_x64__8wekyb3d8bbwe"
        New-Item -ItemType Directory -Path $officialLocation -Force | Out-Null

        function New-P6FWTPackageRecord {
            param(
                $Name = "Microsoft.WindowsTerminal",
                $PackageFamilyName = "Microsoft.WindowsTerminal_8wekyb3d8bbwe",
                $PublisherId = "8wekyb3d8bbwe",
                $InstallLocation = $null,
                [switch]$OmitFamily,
                [switch]$OmitPublisher,
                [switch]$OmitLocation
            )

            $record = [ordered]@{
                Name         = $Name
                Version      = "1.0.0.0"
                Architecture = "x64"
            }

            if (-not $OmitFamily) { $record["PackageFamilyName"] = $PackageFamilyName }
            if (-not $OmitPublisher) { $record["PublisherId"] = $PublisherId }
            if (-not $OmitLocation) { $record["InstallLocation"] = $(if ($null -eq $InstallLocation) { $officialLocation } else { $InstallLocation }) }

            return [pscustomobject]$record
        }

        # correct name + family + publisher + valid location -> accepted
        $accepted = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord))
        Assert-Equal $true $accepted.Ok "official identity accepted"
        Assert-Equal "ok" $accepted.ReasonCode "official identity reason code"
        Assert-Equal $officialLocation $accepted.Package.InstallLocation "selected install location"

        # correct name + WRONG family -> rejected
        $wrongFamily = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -PackageFamilyName "Evil.WindowsTerminal_evil1234567"))
        Assert-Equal $false $wrongFamily.Ok "wrong package family rejected"
        Assert-Equal "family-mismatch" $wrongFamily.ReasonCode "wrong family reason code"

        # correct name + correct family + WRONG publisher -> rejected
        $wrongPublisher = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -PublisherId "evil1234567"))
        Assert-Equal $false $wrongPublisher.Ok "wrong publisher rejected"
        Assert-Equal "publisher-mismatch" $wrongPublisher.ReasonCode "wrong publisher reason code"

        # wrong name + official publisher -> rejected
        $wrongName = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -Name "Evil.WindowsTerminal"))
        Assert-Equal $false $wrongName.Ok "wrong package name rejected"
        Assert-Equal "name-mismatch" $wrongName.ReasonCode "wrong name reason code"

        # missing family property -> rejected
        $missingFamily = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -OmitFamily))
        Assert-Equal $false $missingFamily.Ok "missing package family rejected"
        Assert-Equal "family-mismatch" $missingFamily.ReasonCode "missing family reason code"

        # missing publisher property -> rejected
        $missingPublisher = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -OmitPublisher))
        Assert-Equal $false $missingPublisher.Ok "missing publisher rejected"
        Assert-Equal "publisher-mismatch" $missingPublisher.ReasonCode "missing publisher reason code"

        # blank / relative InstallLocation -> rejected
        $blankLocation = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -InstallLocation " "))
        Assert-Equal $false $blankLocation.Ok "blank install location rejected"
        Assert-Equal "invalid-install-location" $blankLocation.ReasonCode "blank location reason code"

        $relativeLocation = Select-DevWSTrustedWindowsTerminalPackage -Packages @((New-P6FWTPackageRecord -InstallLocation "relative\package"))
        Assert-Equal $false $relativeLocation.Ok "relative install location rejected"
        Assert-Equal "invalid-install-location" $relativeLocation.ReasonCode "relative location reason code"

        # no packages -> fail closed
        $none = Select-DevWSTrustedWindowsTerminalPackage -Packages @()
        Assert-Equal $false $none.Ok "no packages fails closed"
        Assert-Equal "not-registered" $none.ReasonCode "no packages reason code"

        # malformed records only -> fail closed
        $malformed = Select-DevWSTrustedWindowsTerminalPackage -Packages @($null, (New-P6FWTPackageRecord -OmitFamily -OmitPublisher -OmitLocation))
        Assert-Equal $false $malformed.Ok "malformed records fail closed"

        # two untrusted same-name packages -> no official package
        $twoUntrusted = Select-DevWSTrustedWindowsTerminalPackage -Packages @(
            (New-P6FWTPackageRecord -PackageFamilyName "Evil.WindowsTerminal_evil1234567"),
            (New-P6FWTPackageRecord -PublisherId "evil1234567")
        )
        Assert-Equal $false $twoUntrusted.Ok "untrusted same-name packages rejected"

        # one malicious + one official -> official selected (no first-wins)
        $mixed = Select-DevWSTrustedWindowsTerminalPackage -Packages @(
            (New-P6FWTPackageRecord -PackageFamilyName "Evil.WindowsTerminal_evil1234567"),
            (New-P6FWTPackageRecord),
            (New-P6FWTPackageRecord -PublisherId "evil1234567")
        )
        Assert-Equal $true $mixed.Ok "official package selected from a mixed enumeration"
        Assert-Equal $officialLocation $mixed.Package.InstallLocation "the official install location wins"

        # one malicious + one official, reversed -> identical result
        $mixedReversed = Select-DevWSTrustedWindowsTerminalPackage -Packages @(
            (New-P6FWTPackageRecord -PublisherId "evil1234567"),
            (New-P6FWTPackageRecord),
            (New-P6FWTPackageRecord -PackageFamilyName "Evil.WindowsTerminal_evil1234567")
        )
        Assert-Equal $mixed.Ok $mixedReversed.Ok "enumeration order does not change acceptance"
        Assert-Equal $mixed.Package.InstallLocation $mixedReversed.Package.InstallLocation "enumeration order does not change the selection"

        # duplicate representations of the same registered identity -> accepted
        $duplicates = Select-DevWSTrustedWindowsTerminalPackage -Packages @(
            (New-P6FWTPackageRecord),
            (New-P6FWTPackageRecord),
            (New-P6FWTPackageRecord -Name "microsoft.windowsterminal" -PackageFamilyName "MICROSOFT.WINDOWSTERMINAL_8WEKYB3D8BBWE" -PublisherId "8WEKYB3D8BBWE")
        )
        Assert-Equal $true $duplicates.Ok "duplicate representations of one identity are normalized"
        Assert-Equal "ok" $duplicates.ReasonCode "duplicate normalization reason code"

        # multiple distinct official registrations -> ambiguous, fail closed
        $ambiguous = Select-DevWSTrustedWindowsTerminalPackage -Packages @(
            (New-P6FWTPackageRecord),
            (New-P6FWTPackageRecord -InstallLocation (Join-Path $TestRoot "p6f-packages\Microsoft.WindowsTerminal_2.0.0.0_x64__8wekyb3d8bbwe"))
        )
        Assert-Equal $false $ambiguous.Ok "multiple official registrations are ambiguous"
        Assert-Equal "ambiguous" $ambiguous.ReasonCode "ambiguity reason code"
        Assert-Contains $ambiguous.Reason "refusing to choose an enumeration order" "ambiguity policy is explicit"

        # the selector never uses Select-Object -First 1
        $selectorSource = Get-SourceOf "src\lib\devws-paths.ps1"
        Assert-NotContains $selectorSource "Get-AppxPackage" "the production path never uses Get-AppxPackage"
    }

    Test-Case "installed Terminal resolution is independent of command discovery" {
        $savedPath = $env:PATH
        $savedConfig = $env:DEVWS_WT_PATH

        function Get-AppxPackage {
            throw "poisoned Get-AppxPackage must never be consulted by the trusted resolver"
        }

        try {
            $env:PATH = Join-Path $TestRoot "poisoned-path"
            $env:DEVWS_WT_PATH = "C:\poisoned-wt.exe"

            $resolved = Resolve-DevWSTrustedWindowsTerminalPath -Installed

            $records = @(Get-DevWSWindowsTerminalPackageRecords)
            $selection = Select-DevWSTrustedWindowsTerminalPackage -Packages $records

            if ($selection.Ok) {
                Assert-Equal "Microsoft.WindowsTerminal" ([string]$selection.Package.Name) "live record name"
                Assert-Equal "Microsoft.WindowsTerminal_8wekyb3d8bbwe" ([string]$selection.Package.PackageFamilyName) "live record package family"
                Assert-Equal "8wekyb3d8bbwe" ([string]$selection.Package.PublisherId) "live record publisher id"

                $expected = [System.IO.Path]::GetFullPath((Join-Path ([string]$selection.Package.InstallLocation) "WindowsTerminal.exe"))
                Assert-Equal $expected $resolved "the native package query drives the resolver"

                # Independent oracle: the module-qualified package cmdlets (never
                # used by the production path) must agree about the install
                # location.
                $oracle = @(Appx\Get-AppxPackage -Name "Microsoft.WindowsTerminal" -ErrorAction SilentlyContinue)
                Assert-Equal 1 @($oracle).Count "independent oracle sees exactly one official package"
                Assert-Equal ([System.IO.Path]::GetFullPath([string]$oracle[0].InstallLocation)) ([System.IO.Path]::GetFullPath([string]$selection.Package.InstallLocation)) "native query and the package oracle agree on InstallLocation"
            }
            else {
                Assert-Equal "not-registered" ([string]$selection.ReasonCode) "fail-closed without a registered package"
                Assert-Throws { Resolve-DevWSTrustedWindowsTerminalPath -Installed } "not registered" "the resolver fails closed"
            }

            # Re-resolve with the poison still installed: identical result.
            $resolvedAgain = Resolve-DevWSTrustedWindowsTerminalPath -Installed
            Assert-Equal $resolved $resolvedAgain "poisoned discovery, hostile PATH and hostile DEVWS_WT_PATH change nothing"
        }
        finally {
            Remove-Item function:Get-AppxPackage -Force -ErrorAction SilentlyContinue

            if ($null -eq $savedPath) { Remove-Item Env:\PATH -ErrorAction SilentlyContinue } else { $env:PATH = $savedPath }
            if ($null -eq $savedConfig) { Remove-Item Env:\DEVWS_WT_PATH -ErrorAction SilentlyContinue } else { $env:DEVWS_WT_PATH = $savedConfig }

            . (Join-Path $RepoRoot "src\lib\devws-paths.ps1")
        }
    }

    Test-Case "failed Windows Terminal trust validation stops the launch before Process.Start" {
        $script:pwtStarterCalls = 0
        $script:pwtResolverCalls = 0
        $script:pwtThrowMessage = "simulated Windows Terminal trust failure"

        function Resolve-DevWSTrustedWindowsTerminalPath {
            $script:pwtResolverCalls++
            throw $script:pwtThrowMessage
        }

        $plan = [pscustomobject]@{
            SetId     = "main"
            Terminals = @([pscustomobject]@{
                State           = "missing"
                Order           = 0
                TerminalId      = "t"
                WindowId        = "DevWS-pwt"
                CreateArguments = @("new-tab")
            })
        }

        try {
            # Every trust failure class must throw before any Process.Start:
            # missing official identity, publisher mismatch, ambiguous official
            # registrations, and candidate protected-path failure.
            foreach ($reason in @(
                "official Windows Terminal package identity is missing",
                "publisher identity mismatch",
                "multiple distinct official registrations",
                "candidate failed the protected-path policy"
            )) {
                $script:pwtThrowMessage = $reason
                $script:pwtStarterCalls = 0
                $script:pwtResolverCalls = 0

                $message = Get-ThrownMessage {
                    Start-DevWSTerminalLaunchPlan -Plan $plan -ProcessStarter { $script:pwtStarterCalls++ }
                }

                Assert-Contains $message $reason "the trust failure surfaces from the launch plan ($reason)"
                Assert-Equal 1 $script:pwtResolverCalls "the trusted resolver ran exactly once for the failed launch ($reason)"
                Assert-Equal 0 $script:pwtStarterCalls "Process.Start is never called after a failed trust validation ($reason)"
            }

            # Explicit test injection stays available: an explicit -WtPath is
            # used without invoking the trusted resolver.
            $script:pwtStarterCalls = 0
            $script:pwtResolverCalls = 0
            $stubPath = Join-Path $TestRoot "pwt-stub\wt.exe"
            $null = Start-DevWSTerminalLaunchPlan -Plan $plan -WtPath $stubPath -ProcessStarter { $script:pwtStarterCalls++ }

            Assert-Equal 0 $script:pwtResolverCalls "an explicit repository stub bypasses the trusted resolver"
            Assert-Equal 1 $script:pwtStarterCalls "the injected stub starts the process"
        }
        finally {
            . (Join-Path $RepoRoot "src\lib\devws-paths.ps1")
            . (Join-Path $RepoRoot "src\lib\devws-terminal-launch.ps1")
        }

        Assert-Equal (Get-DevWSWindowsTerminalPath) (Resolve-DevWSTrustedWindowsTerminalPath) "the real resolver is restored"

        # Static routing: every installed WT launch site resolves the trusted
        # launcher, and the locator uses the trusted shell token.
        Assert-Contains (Get-SourceOf "src\lib\devws-terminal-launch.ps1") "Resolve-DevWSTrustedWindowsTerminalPath" "launch plan resolves the trusted launcher"
        Assert-Contains (Get-SourceOf "src\workers\elevated-reset.ps1") "Resolve-DevWSTrustedWindowsTerminalPath" "reset worker resolves the trusted launcher"
        Assert-Contains (Get-SourceOf "src\lib\devws-locator.ps1") "Resolve-DevWSTrustedWindowsTerminalPath" "locator resolves the trusted launcher"
        Assert-Contains (Get-SourceOf "src\lib\devws-locator.ps1") "Get-DevWSPowerShellLaunchToken" "locator uses the trusted shell token"
    }

    Test-Case "health reuses the trusted Windows Terminal validator" {
        $fixture = New-InstallFixture "priv-wt-health"
        $fixtureRoots = Join-Path $fixture.Root "Program Files\WindowsApps"
        $packageDir = Join-Path $fixtureRoots "Microsoft.WindowsTerminal_1.2.3.0_x64__8wekyb3d8bbwe"
        New-Item -ItemType Directory -Path $packageDir -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $packageDir "WindowsTerminal.exe") -Value "fixture" -NoNewline

        $context = [pscustomobject]@{
            InstallRoot               = $fixture.Root
            StateRoot                 = $fixture.State
            CanonicalPath             = Join-Path $fixture.Root "canonical.json"
            StartupPath               = Join-Path $fixture.Root "Startup"
            LegacyShimPath            = Join-Path $fixture.Root "local-bin\ws.cmd"
            WindowsTerminalPath       = (Join-Path $packageDir "WindowsTerminal.exe")
            WindowsTerminalTrustRoots = @($fixtureRoots)
            WindowsTerminalTrustError = $null
            AutoHotkeyPath            = Join-Path $fixture.Root "AutoHotkey64.exe"
            MetadataPath              = Join-Path $fixture.State "install-metadata.json"
            PrivilegedRoot            = $fixture.Privileged
        }

        function Get-PWTHealthById($summary) {
            $byId = @{}
            foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }
            return $byId
        }

        $byId = Get-PWTHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $true $byId["windows-terminal"].Ok "trusted fixture package executable passes"

        # A carried trust-resolution error fails the check with its message.
        $context.WindowsTerminalTrustError = "simulated resolution failure"
        $byId = Get-PWTHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $false $byId["windows-terminal"].Ok "carried trust error fails the check"
        Assert-Contains $byId["windows-terminal"].Message "simulated resolution failure" "the carried message surfaces"

        # An ordinary stub never passes when trust roots are declared.
        $context.WindowsTerminalTrustError = $null
        $context.WindowsTerminalPath = Join-Path $fixture.Root "stub-wt.exe"
        Set-Content -LiteralPath $context.WindowsTerminalPath -Value "x" -NoNewline
        $byId = Get-PWTHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $false $byId["windows-terminal"].Ok "ordinary stub fails the trusted check"

        # Legacy repository/health contexts keep the existence-only check.
        $legacy = [pscustomobject]@{
            InstallRoot          = $fixture.Root
            StateRoot            = $fixture.State
            CanonicalPath        = Join-Path $fixture.Root "canonical.json"
            StartupPath          = Join-Path $fixture.Root "Startup"
            LegacyShimPath       = Join-Path $fixture.Root "local-bin\ws.cmd"
            WindowsTerminalPath  = $context.WindowsTerminalPath
            AutoHotkeyPath       = Join-Path $fixture.Root "AutoHotkey64.exe"
            MetadataPath         = Join-Path $fixture.State "install-metadata.json"
            PrivilegedRoot       = $fixture.Privileged
        }
        $byId = Get-PWTHealthById (Invoke-DevWSHealthCheck -Context $legacy)
        Assert-Equal $true $byId["windows-terminal"].Ok "legacy context keeps the existence-only check"
    }

    Test-Case "host integrity is read from the native process token" {
        $pathsSource = Get-SourceOf "src\lib\devws-paths.ps1"
        Assert-NotContains $pathsSource "whoami" "the integrity helper never invokes whoami"
        Assert-Contains $pathsSource "GetTokenInformation" "the integrity helper reads the process token directly"
        Assert-Contains $pathsSource "TokenIntegrityLevel" "the integrity helper documents the token integrity class"

        $integrity = Get-DevWSProcessIntegrityLevel
        Assert-True ($integrity.Name -in @("Low", "Medium", "High", "System", "Untrusted", "Unknown")) "known integrity name"
        Assert-True (-not [string]::IsNullOrWhiteSpace([string]$integrity.Sid)) "the native token read returns a label SID"
        Assert-Equal ($integrity.Name -eq "High") $integrity.IsHigh "IsHigh derives from the token label"
        Assert-Equal ($integrity.Name -eq "Medium") $integrity.IsMedium "IsMedium derives from the token label"

        # Independent oracle (test-only): whoami /groups must agree with the
        # native token read.
        $oracleSid = $null

        foreach ($line in @(whoami /groups 2>$null)) {
            if ($line -match '(S-1-16-\d+)') { $oracleSid = $Matches[1] }
        }

        Assert-Equal $oracleSid ([string]$integrity.Sid) "the native read matches the independent oracle"
    }

    Test-Case "trusted system executables resolve under System32 only" {
        $systemRoot = [Environment]::GetFolderPath('Windows')
        $expected = Join-Path (Join-Path $systemRoot "System32") "schtasks.exe"

        Assert-Equal $expected (Get-DevWSTrustedSystemExecutable -Name "schtasks.exe") "schtasks resolves under System32"
        Assert-True (Test-Path -LiteralPath $expected -PathType Leaf) "the resolved System32 executable exists"
        Assert-Equal 0 (@(Get-DevWSTrustedExecutableRoots) | Where-Object { $_ -ieq $systemRoot }).Count "the whole Windows folder is not a trusted executable root"

        Assert-Throws { Get-DevWSTrustedSystemExecutable -Name "..\evil.exe" } "plain file name" "path separators are rejected"
        Assert-Throws { Get-DevWSTrustedSystemExecutable -Name "definitely-not-real-p6f.exe" } "was not found" "missing system executables fail closed"

        # No High-reachable library may invoke a bare schtasks.exe any more:
        # both libraries are copied into the privileged runtime.
        $workerProtocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        Assert-Contains $workerProtocol 'Get-DevWSTrustedSystemExecutable -Name "schtasks.exe"' "worker protocol uses the trusted absolute schtasks"
        Assert-NotContains $workerProtocol "schtasks.exe /run" "worker protocol has no bare schtasks invocation"

        $brokerProtocol = Get-SourceOf "src\lib\devws-broker-protocol.ps1"
        Assert-Contains $brokerProtocol 'Get-DevWSTrustedSystemExecutable -Name "schtasks.exe"' "broker protocol uses the trusted absolute schtasks"
        Assert-NotContains $brokerProtocol '-FilePath "schtasks.exe"' "broker protocol has no bare schtasks executable path"

        $health = Get-SourceOf "src\lib\devws-health.ps1"
        Assert-Contains $health "(Resolve-DevWSTrustedPowerShellPath)" "health spawns only the trusted PowerShell"
        Assert-NotContains $health '-FilePath "pwsh"' "health has no bare pwsh spawn"
    }

    Test-Case "the AutoHotkey High path stays absolute and unredirectable" {
        $savedAhk = $env:DEVWS_AHK_PATH

        try {
            # Repository layout: the development/CI override is honoured verbatim.
            $overridePath = Join-Path $TestRoot "portable-ahk\AutoHotkey64.exe"
            $env:DEVWS_AHK_PATH = $overridePath

            Assert-Equal $overridePath (Get-DevWSAutoHotkeyPath) "the repository override is honored"
            Assert-True ([System.IO.Path]::IsPathRooted($overridePath)) "the override route stays absolute"

            # Without an override the path comes from the trusted machine-wide
            # resolver, never a literal, PATH list or alias.
            Remove-Item Env:\DEVWS_AHK_PATH -ErrorAction SilentlyContinue

            $machine = $null
            try { $machine = Resolve-DevWSTrustedAutoHotkeyPath } catch { $machine = $null }

            if ($null -ne $machine) {
                Assert-Equal $machine (Get-DevWSAutoHotkeyPath) "AutoHotkey resolves through the trusted machine-wide resolver"
                Assert-True ([System.IO.Path]::IsPathRooted($machine)) "AutoHotkey path is absolute"
                Assert-True (
                    (Test-DevWSPathUnderRoot -Path $machine -Root ([Environment]::GetFolderPath('ProgramFiles'))) -or
                    (Test-DevWSPathUnderRoot -Path $machine -Root ([Environment]::GetFolderPath('ProgramFilesX86')))
                ) "AutoHotkey lives under an administrator-protected Program Files root"
                Assert-Equal "AutoHotkey64.exe" (Split-Path -Leaf $machine) "the v2 x64 interpreter is selected"
                Assert-NotContains $machine ";" "no PATH list can leak into the AutoHotkey path"
            }
            else {
                $threw = $null
                try { $null = Get-DevWSAutoHotkeyPath } catch { $threw = $_.Exception.Message }
                Assert-Contains $threw "No trusted machine-wide AutoHotkey v2 installation" "an absent machine installation fails closed with an actionable message"
            }

            $ahkSource = Get-SourceOf "src\lib\devws-ahk.ps1"
            $ahkSourceCode = (@($ahkSource -split "`r?`n") | Where-Object { $_ -notmatch '^\s*#' }) -join "`n"
            Assert-Contains $ahkSource "System.Diagnostics.Process" "the AHK invoker launches a real process"
            Assert-Contains $ahkSource "(Get-DevWSAutoHotkeyPath)" "the AHK invoker consumes the trusted path helper"
            Assert-NotContains $ahkSourceCode "Start-Process" "the AHK invoker uses no Start-Process file redirects"
            Assert-NotContains $ahkSource "devws-ahk-" "the AHK invoker creates no temporary output files"
        }
        finally {
            if ($null -eq $savedAhk) { Remove-Item Env:\DEVWS_AHK_PATH -ErrorAction SilentlyContinue } else { $env:DEVWS_AHK_PATH = $savedAhk }
        }
    }

