    Test-Case "installer migration rehearsal backs up the deployed v2 bytes exactly" {
        $fixture = New-InstallFixture "live-shape-migrate"
        $source  = New-LiveShapeV2Fixture "live-shape-migrate-source"
        New-Item -ItemType Directory -Path (Split-Path -Parent $fixture.Canonical) -Force | Out-Null
        Copy-Item -LiteralPath $source -Destination $fixture.Canonical

        $canonicalBefore = Get-FileBase64 -Path $fixture.Canonical
        $unrelated = Join-Path $fixture.Root "unrelated.txt"
        Set-Content -LiteralPath $unrelated -Value "keep me" -Encoding UTF8
        $unrelatedBefore = Get-FileBase64 -Path $unrelated

        $missingV1 = Join-Path $fixture.Root "missing-v1.json"
        $plan = Get-DevWSInstallConfigPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1
        Assert-Equal "migrate-v2" $plan.Action "v2 migration planned"
        Assert-Equal $true $plan.CanonicalV2 "recognized as v2"

        $result = Initialize-DevWSWorkspaceConfig -Plan $plan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1 -BackupRoot $fixture.Backups
        Assert-Equal "migrate-v2" $result.Action "migration executed"
        Assert-True (Test-Path -LiteralPath $result.Backup -PathType Leaf) "backup written"
        Assert-Equal $canonicalBefore (Get-FileBase64 -Path $result.Backup) "backup bytes equal the pre-migration canonical bytes"
        Assert-Equal $unrelatedBefore (Get-FileBase64 -Path $unrelated) "unrelated file untouched"

        # Re-read the installed canonical: definitions round-trip unchanged and
        # the legacy identities survive the byte-level migration path.
        $installed = Read-DevWSConfigFile -Path $fixture.Canonical
        Assert-DevWSConfig -Config $installed -Source "rehearsed canonical"
        Assert-Equal 3 $installed.version "installed canonical is v3"
        Assert-Equal "main" $installed.defaultSet "installed defaultSet"
        Assert-Equal 1 @($installed.sets).Count "installed single set"

        $sourceConfig = Read-DevWSConfigFile -Path $source
        $expectedModes = @{ firefox = "dedicated"; codex = "shared"; antigravity = "shared" }

        for ($i = 0; $i -lt 6; $i++) {
            $expectedItem = $sourceConfig.windows[$i]
            $actualItem   = $installed.sets[0].windows[$i]

            if ($expectedItem.type -eq "app") {
                $expectedJson = ([pscustomobject][ordered]@{
                    id           = [string]$expectedItem.id
                    type         = "app"
                    enabled      = [bool]$expectedItem.enabled
                    match        = $expectedItem.match
                    launch       = $expectedItem.launch
                    instanceMode = $expectedModes[[string]$expectedItem.id]
                    layout       = $expectedItem.layout
                }) | ConvertTo-Json -Depth 20 -Compress
            }
            else {
                $expectedJson = $expectedItem | ConvertTo-Json -Depth 20 -Compress
            }

            Assert-Equal $expectedJson ($actualItem | ConvertTo-Json -Depth 20 -Compress) "window $i preserved semantically (mode added where required)"
        }

        Assert-Equal "DevWS-1" @($installed.sets[0].windows)[0].windowId "migrated canonical keeps DevWS-1"
        Assert-Equal "DevWS-2" @($installed.sets[0].windows)[1].windowId "migrated canonical keeps DevWS-2"
        Assert-Equal "DevWS-3" @($installed.sets[0].windows)[2].windowId "migrated canonical keeps DevWS-3"

        $plan2 = Get-DevWSInstallConfigPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1
        Assert-Equal "preserve" $plan2.Action "reinstall preserves the migrated v3 canonical"
    }

