        Assert-Contains $plan.Message "main/mystery" "plan names the first scoped app"
        Assert-Contains $plan.Message "secondary/mystery" "plan names the second scoped app"
        Assert-Equal $before (Get-FileBase64 -Path $canonical) "canonical untouched by planning"

        Assert-Throws {
            Initialize-DevWSWorkspaceConfig -Plan $plan -CanonicalPath $canonical -BundledPath $WorkspaceFixturePath -V1Path $v1Path -BackupRoot (Join-Path $dir "backups")
        } "was NOT modified" "execution refuses the failed plan"

