        $preMode = Read-DevWSConfigFile -Path $fixture.Canonical
        Assert-DevWSPreInstanceModeV3Config -Config $preMode -Source "rehearsal pre-mode"
        $strictMessage = Get-ThrownMessage { Assert-DevWSConfig -Config $preMode -Source "rehearsal pre-mode" }
        Assert-Contains $strictMessage "missing 'instanceMode'" "strict runtime validation rejects the pre-mode fixture"

        $plan = Get-DevWSInstallConfigPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1
        Assert-Equal "enrich-v3-instance-modes" $plan.Action "enrichment planned"
        Assert-Equal $true $plan.CanonicalPreInstanceMode "plan marks the historical shape"
        Assert-Equal 3 $plan.CanonicalSchema "plan reports schema 3"

        $result = Initialize-DevWSWorkspaceConfig -Plan $plan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1 -BackupRoot $fixture.Backups
        Assert-Equal "enrich-v3-instance-modes" $result.Action "enrichment executed"
        Assert-True (Test-Path -LiteralPath $result.Backup -PathType Leaf) "backup written"
        Assert-Equal $canonicalBefore (Get-FileBase64 -Path $result.Backup) "backup bytes exactly equal the pre-enrichment canonical"

        $installed = Read-DevWSConfigFile -Path $fixture.Canonical
        Assert-DevWSConfig -Config $installed -Source "rehearsed canonical"
        Assert-Equal 3 $installed.version "version remains 3"
        Assert-Equal "main" $installed.defaultSet "defaultSet remains main"
        Assert-Equal 0 @($installed.bindings).Count "bindings remain empty"
        Assert-Equal 1 @($installed.sets).Count "still exactly one set"
        Assert-Equal "main" $installed.sets[0].id "set id unchanged"
        Assert-Equal "slot,studio,scratch,firefox,codex,antigravity" (@($installed.sets[0].windows | ForEach-Object { $_.id }) -join ",") "six items in exact order"
        Assert-Equal "DevWS-1,DevWS-2,DevWS-3" (@($installed.sets[0].windows | Where-Object { $_.type -eq "terminal" } | ForEach-Object { $_.windowId }) -join ",") "legacy terminal identities unchanged"

        $modes = @{}
        foreach ($app in @($installed.sets[0].windows | Where-Object { $_.type -eq "app" })) {
            $modes[[string]$app.id] = [string]$app.instanceMode
        }

        Assert-Equal "dedicated" $modes["firefox"] "firefox locked dedicated"
        Assert-Equal "shared" $modes["codex"] "codex locked shared"
        Assert-Equal "shared" $modes["antigravity"] "antigravity locked shared"

        # Every definition is semantically unchanged apart from the added mode.
        $sourceConfig = Read-DevWSConfigFile -Path $source

        for ($i = 0; $i -lt 6; $i++) {
            $expectedItem = $sourceConfig.sets[0].windows[$i]
            $actualItem   = $installed.sets[0].windows[$i]

            Assert-Equal ([string]$expectedItem.id) ([string]$actualItem.id) "item $i id"
            Assert-Equal ([string]$expectedItem.type) ([string]$actualItem.type) "item $i type"
            Assert-Equal ([bool]$expectedItem.enabled) ([bool]$actualItem.enabled) "item $i enabled"
            Assert-Equal (ConvertTo-Json -InputObject $expectedItem.layout -Depth 5 -Compress) (ConvertTo-Json -InputObject $actualItem.layout -Depth 5 -Compress) "item $i layout"

            if ($expectedItem.type -eq "app") {
                Assert-Equal (ConvertTo-Json -InputObject $expectedItem.match -Depth 5 -Compress) (ConvertTo-Json -InputObject $actualItem.match -Depth 5 -Compress) "item $i match"
                Assert-Equal (ConvertTo-Json -InputObject $expectedItem.launch -Depth 5 -Compress) (ConvertTo-Json -InputObject $actualItem.launch -Depth 5 -Compress) "item $i launch"
                Assert-True (-not (Test-DevWSProperty -Object $expectedItem -Name "instanceMode")) "fixture app starts without a mode"
                Assert-Equal $modes[[string]$expectedItem.id] ([string]$actualItem.instanceMode) "item $i mode added"
            }
            else {
                Assert-Equal ([string]$expectedItem.windowId) ([string]$actualItem.windowId) "item $i windowId"
                Assert-Equal ([string]$expectedItem.path) ([string]$actualItem.path) "item $i path"
                Assert-Equal ([bool]$expectedItem.elevated) ([bool]$actualItem.elevated) "item $i elevated"
                Assert-Equal ([int]$expectedItem.activeTab) ([int]$actualItem.activeTab) "item $i activeTab"
                Assert-Equal (ConvertTo-Json -InputObject @($expectedItem.tabs) -Depth 10 -Compress) (ConvertTo-Json -InputObject @($actualItem.tabs) -Depth 10 -Compress) "item $i tabs"
            }
        }

        # Second installer pass: the enriched final config is preserved
        # byte-for-byte.
        $enrichedBytes = Get-FileBase64 -Path $fixture.Canonical

        $plan2 = Get-DevWSInstallConfigPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1
        Assert-Equal "preserve" $plan2.Action "second plan preserves the enriched config"
        Assert-Equal $true $plan2.CanonicalValid "second plan sees final valid v3"

        $result2 = Initialize-DevWSWorkspaceConfig -Plan $plan2 -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $missingV1 -BackupRoot $fixture.Backups
        Assert-Equal "preserve" $result2.Action "second execution preserves"
        Assert-Equal $enrichedBytes (Get-FileBase64 -Path $fixture.Canonical) "second installer pass is byte-preserving"
    }

    Test-Case "installer fails safely for every invalid canonical variant" {
