            Assert-Equal $before (Get-FileBase64 -Path $fixture.Canonical) "$($case.Name) canonical unchanged by planning"

            Assert-Throws {
                Initialize-DevWSWorkspaceConfig -Plan $plan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $v1Path -BackupRoot $fixture.Backups
            } "invalid" "$($case.Name) execution refuses"
