        Assert-Contains $plan.Message "-ResetConfig" "message suggests the explicit reset"

        Assert-Throws {
            Initialize-DevWSWorkspaceConfig -Plan $plan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $v1Path -BackupRoot $fixture.Backups
        } "invalid"
        Assert-Equal $before (Get-FileBase64 -Path $fixture.Canonical) "invalid canonical left byte-identical"

        # An invalid canonical file never falls through to v1/default
        # migration, even when a recognized v1 config exists.
        $v1Fallback = New-V1ConfigFixture "config-invalid-v1"
        $v1FallbackBefore = Get-FileBase64 -Path $v1Fallback

        $planNoFallback = Get-DevWSInstallConfigPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $v1Fallback
        Assert-Equal "fail" $planNoFallback.Action "invalid canonical blocks v1 fallback"
        Assert-Equal $before (Get-FileBase64 -Path $fixture.Canonical) "invalid canonical untouched after fallback check"
        Assert-Equal $v1FallbackBefore (Get-FileBase64 -Path $v1Fallback) "v1 untouched after fallback check"

        $resetPlan = Get-DevWSInstallConfigPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $v1Path -ResetConfig
        Assert-Equal "reset" $resetPlan.Action "explicit reset plan"

        $result = Initialize-DevWSWorkspaceConfig -Plan $resetPlan -CanonicalPath $fixture.Canonical -BundledPath $WorkspaceFixturePath -V1Path $v1Path -BackupRoot $fixture.Backups
        Assert-Equal "reset" $result.Action "reset executed"
        Assert-True (Test-Path -LiteralPath $result.Backup -PathType Leaf) "previous canonical backed up"
        Assert-True ($result.Backup.StartsWith($fixture.Backups)) "backup lives under state\backups"
        Assert-Equal (Get-FileBase64 -Path $WorkspaceFixturePath) (Get-FileBase64 -Path $fixture.Canonical) "reset installed the v3 default"

        $resetConfig = Read-DevWSConfigFile -Path $fixture.Canonical
        Assert-Equal 3 $resetConfig.version "reset default is v3"
    }

