    Test-Case "task repair preflight requires a sufficiently installed instance" {
        $f = New-TestTaskRepairFixture "preflight"

        $ok = Get-DevWSTaskRepairPreflight `
            -TaskSpecs $f.Specs `
            -Metadata $f.Metadata `
            -MetadataPath $f.MetadataPath `
            -InstallRoot $f.Fixture.Root `
            -PrivilegedRoot $f.Fixture.Privileged

        Assert-Equal $true $ok.Ok "a complete fixture passes"
        Assert-Equal 0 @($ok.Errors).Count "no errors"

        # Missing application host.
        Rename-Item -LiteralPath (Join-Path $f.Fixture.Root 'app\ws.ps1') -NewName 'ws.ps1.off'

        $result = Get-DevWSTaskRepairPreflight -TaskSpecs $f.Specs -Metadata $f.Metadata -MetadataPath $f.MetadataPath -InstallRoot $f.Fixture.Root -PrivilegedRoot $f.Fixture.Privileged
        Assert-Equal $false $result.Ok "a missing application fails"
        Assert-Contains (@($result.Errors) -join ' ') "not installed" "the error names the missing installation"

        Rename-Item -LiteralPath (Join-Path $f.Fixture.Root 'app\ws.ps1.off') -NewName 'ws.ps1'

        # Missing protected worker.
        Rename-Item -LiteralPath (Join-Path $f.Fixture.Privileged 'workers\elevated-focus.ps1') -NewName 'elevated-focus.ps1.off'

        $result = Get-DevWSTaskRepairPreflight -TaskSpecs $f.Specs -Metadata $f.Metadata -MetadataPath $f.MetadataPath -InstallRoot $f.Fixture.Root -PrivilegedRoot $f.Fixture.Privileged
        Assert-Equal $false $result.Ok "a missing protected worker fails"
        Assert-Contains (@($result.Errors) -join ' ') "worker script" "the error names the missing worker"

        Rename-Item -LiteralPath (Join-Path $f.Fixture.Privileged 'workers\elevated-focus.ps1.off') -NewName 'elevated-focus.ps1'

        # Missing metadata.
        $savedMetadata = [System.IO.File]::ReadAllBytes($f.MetadataPath)
        Remove-Item -LiteralPath $f.MetadataPath -Force

        $result = Get-DevWSTaskRepairPreflight -TaskSpecs $f.Specs -Metadata $f.Metadata -MetadataPath $f.MetadataPath -InstallRoot $f.Fixture.Root -PrivilegedRoot $f.Fixture.Privileged
        Assert-Equal $false $result.Ok "missing metadata fails"
        Assert-Contains (@($result.Errors) -join ' ') "install metadata is missing" "the error names the metadata"

        [System.IO.File]::WriteAllBytes($f.MetadataPath, $savedMetadata)

        # Legacy metadata without the recorded privileged root.
        $legacy = $f.Metadata
        $legacy.privileged.root = ''

        $result = Get-DevWSTaskRepairPreflight -TaskSpecs $f.Specs -Metadata $legacy -MetadataPath $f.MetadataPath -InstallRoot $f.Fixture.Root -PrivilegedRoot $f.Fixture.Privileged
        Assert-Equal $false $result.Ok "legacy metadata fails"
        Assert-Contains (@($result.Errors) -join ' ') "no recorded privileged root" "the error names the missing record"

        $legacy.privileged.root = $f.Fixture.Privileged

        # Recorded root that does not match the resolved root.
        $mismatch = New-DevWSInstallMetadata
        $mismatch.privileged.root = 'C:\Program Files\SomewhereElse\privileged'
        $mismatch.privileged.powerShellPath = $f.NewPath

        $result = Get-DevWSTaskRepairPreflight -TaskSpecs $f.Specs -Metadata $mismatch -MetadataPath $f.MetadataPath -InstallRoot $f.Fixture.Root -PrivilegedRoot $f.Fixture.Privileged
        Assert-Equal $false $result.Ok "a mismatched privileged root fails"
        Assert-Contains (@($result.Errors) -join ' ') "does not match the resolved privileged root" "the error names the mismatch"
    }

    Test-Case "a registration failure restores every changed task definition" {
        $f = New-TestTaskRepairFixture "registration-failure" -StaleMetadata
        $store = New-TestTaskRepairStore -Tasks $f.Tasks -BrokerRunning $true -FailRegistrationFor 'DevWorkspace-ElevatedReset'

        $threw = $null

        try { $null = Invoke-DevWSTaskPowerShellRepair -TaskSpecs $f.Specs -Metadata $f.Metadata -MetadataPath $f.MetadataPath -Store $store }
        catch { $threw = $_.Exception.Message }

        Assert-True ($null -ne $threw) "repair fails"
        Assert-Contains $threw "simulated registration failure for 'DevWorkspace-ElevatedReset'" "the original failure is reported"
        Assert-Contains $threw "all changed task definitions" "the rollback result is reported"

        Assert-Equal 3 $script:TestTaskRepairStore.Registrations.Count "three registrations before the failure"
        Assert-Equal 3 $script:TestTaskRepairStore.Restores.Count "three tasks restored"
        Assert-Equal 0 $script:TestTaskRepairStore.MetadataWrites "metadata never written"

        foreach ($spec in $f.Specs) {
            Assert-Equal $f.Tasks[$spec.TaskName] $script:TestTaskRepairStore.Tasks[$spec.TaskName] "task definition restored exactly: $($spec.TaskName)"
        }

        Assert-Equal 1 $script:TestTaskRepairStore.Starts.Count "the broker was restarted after rollback"
        Assert-Equal $true $script:TestTaskRepairStore.BrokerRunning "the broker running state was restored"
    }

    Test-Case "a metadata persistence failure rolls the task definitions back" {
        $f = New-TestTaskRepairFixture "metadata-failure" -StaleMetadata
        $store = New-TestTaskRepairStore -Tasks $f.Tasks -FailMetadataSave

        $before = [System.IO.File]::ReadAllBytes($f.MetadataPath)
        $threw = $null

        try { $null = Invoke-DevWSTaskPowerShellRepair -TaskSpecs $f.Specs -Metadata $f.Metadata -MetadataPath $f.MetadataPath -Store $store }
        catch { $threw = $_.Exception.Message }

        Assert-True ($null -ne $threw) "repair fails"
        Assert-Contains $threw "simulated metadata write failure" "the metadata failure is reported"
        Assert-Equal 5 $script:TestTaskRepairStore.Registrations.Count "all five tasks registered first"
        Assert-Equal 5 $script:TestTaskRepairStore.Restores.Count "all five tasks rolled back"

        foreach ($spec in $f.Specs) {
            Assert-Equal $f.Tasks[$spec.TaskName] $script:TestTaskRepairStore.Tasks[$spec.TaskName] "task restored: $($spec.TaskName)"
        }

        $after = [System.IO.File]::ReadAllBytes($f.MetadataPath)

        Assert-Equal ([System.Convert]::ToBase64String($before)) ([System.Convert]::ToBase64String($after)) "metadata bytes unchanged"
        Assert-Equal $f.OldPath $f.Metadata.privileged.powerShellPath "in-memory metadata restored"

        $reread = Read-DevWSInstallMetadata -Path $f.MetadataPath
        Assert-Equal $f.OldPath $reread.privileged.powerShellPath "metadata on disk still records the old path"
    }

    Test-Case "broker lifecycle follows the state observed before the repair" {
        # Running before repair: stopped and restarted through exact task control.
        $f = New-TestTaskRepairFixture "broker-running" -StaleMetadata
        $store = New-TestTaskRepairStore -Tasks $f.Tasks -BrokerRunning $true

        $result = Invoke-DevWSTaskPowerShellRepair -TaskSpecs $f.Specs -Metadata $f.Metadata -MetadataPath $f.MetadataPath -Store $store

        Assert-Equal 1 $script:TestTaskRepairStore.Stops.Count "the managed broker was stopped"
        Assert-Equal 1 $script:TestTaskRepairStore.Starts.Count "the managed broker was restarted"
        Assert-Equal $true $result.BrokerWasRunning "reported as previously running"
        Assert-Equal $true $result.BrokerRestarted "reported as restarted"

        # Not running before repair: never manufactured.
        $f2 = New-TestTaskRepairFixture "broker-stopped" -StaleMetadata
        $store2 = New-TestTaskRepairStore -Tasks $f2.Tasks -BrokerRunning $false

        $result2 = Invoke-DevWSTaskPowerShellRepair -TaskSpecs $f2.Specs -Metadata $f2.Metadata -MetadataPath $f2.MetadataPath -Store $store2

        Assert-Equal 0 $script:TestTaskRepairStore.Stops.Count "no stop when the broker was not running"
        Assert-Equal 0 $script:TestTaskRepairStore.Starts.Count "repair does not manufacture a running broker"
        Assert-Equal $false $result2.BrokerWasRunning "reported as not previously running"

        # A restart failure after a successful repair is surfaced, not rolled back.
        $f3 = New-TestTaskRepairFixture "broker-start-fails" -StaleMetadata
        $store3 = New-TestTaskRepairStore -Tasks $f3.Tasks -BrokerRunning $true -FailBrokerStart

        $result3 = Invoke-DevWSTaskPowerShellRepair -TaskSpecs $f3.Specs -Metadata $f3.Metadata -MetadataPath $f3.MetadataPath -Store $store3

        Assert-Equal 'repaired' $result3.Status "the repair itself still succeeds"
        Assert-Equal 0 $script:TestTaskRepairStore.Restores.Count "a broker restart failure does not roll back the definitions"
        Assert-Equal 1 @($result3.Warnings).Count "the restart failure is surfaced as a warning"
    }

    Test-Case "health points at -RepairTasks only for a repairable stale interpreter" {
        $f = New-TestTaskRepairFixture "health"

        $makeContext = {
            param([string]$Recorded)

            $context = [pscustomobject]@{
                InstallRoot         = $f.Fixture.Root
                StateRoot           = Join-Path $f.Fixture.Root 'state'
                CanonicalPath       = Join-Path $f.Fixture.Root 'canonical.json'
                StartupPath         = Join-Path $f.Fixture.Root 'Startup'
                LegacyShimPath      = Join-Path $f.Fixture.Root 'local-bin\ws.cmd'
                WindowsTerminalPath = Join-Path $f.Fixture.Root 'wt.exe'
                AutoHotkeyPath      = Join-Path $f.Fixture.Root 'AutoHotkey64.exe'
                MetadataPath        = $f.MetadataPath
                PrivilegedRoot      = $f.Fixture.Privileged
            }

            $context | Add-Member -NotePropertyName 'PrivilegedPowerShellPath' -NotePropertyValue $Recorded

            return $context
        }

        $taskObjects = @($f.Specs | ForEach-Object {
            [pscustomobject]@{
                TaskName  = $_.TaskName
                TaskPath  = '\'
                Actions   = @([pscustomobject]@{ Execute = $f.OldPath; Arguments = (Get-DevWSScheduledTaskActionArguments -Spec $_) })
                Principal = [pscustomobject]@{ RunLevel = 'Highest' }
                Settings  = [pscustomobject]@{ MultipleInstances = 'IgnoreNew' }
                Triggers  = @()
            }
        })

        $xmlByName = @{}

        foreach ($spec in $f.OldSpecs) {
            $xmlByName[$spec.TaskName] = New-TestManagedTaskXml `
                -Spec $spec `
                -Execute $f.OldPath `
                -Broker:($spec.TaskName -eq 'DevWorkspace-ElevatedBroker')
        }

        function Get-ScheduledTask {
            param([string]$TaskName, [string]$TaskPath, $ErrorAction)
            return $taskObjects
        }

        function Export-ScheduledTask {
            param([string]$TaskName, $ErrorAction)
            return $xmlByName[$TaskName]
        }

        # A: the recorded interpreter itself is gone.
        $summary = Invoke-DevWSHealthCheck -Context (& $makeContext $f.OldPath)
        $result = @($summary.Results | Where-Object { $_.Id -eq 'task-executable' })[0]

        Assert-Equal $false $result.Ok "a stale recorded interpreter fails"
        Assert-Contains $result.Message "-RepairTasks" "the message names the repair command"

        # B: tasks drift from a valid recorded interpreter, shape intact.
        $summary = Invoke-DevWSHealthCheck -Context (& $makeContext $f.NewPath)
        $result = @($summary.Results | Where-Object { $_.Id -eq 'task-executable' })[0]

        Assert-Equal $false $result.Ok "task drift fails"
        Assert-Contains $result.Message "-RepairTasks" "repairable drift suggests the repair"

        # C: definition damage is NOT presented as a routine package update.
        $xmlByName['DevWorkspace-ElevatedHelper'] = $xmlByName['DevWorkspace-ElevatedHelper'] -replace '<Arguments>[^<]+</Arguments>', '<Arguments>-NoProfile -WindowStyle Hidden -File "C:\evil\evil.ps1"</Arguments>'

        $summary = Invoke-DevWSHealthCheck -Context (& $makeContext $f.NewPath)
        $result = @($summary.Results | Where-Object { $_.Id -eq 'task-executable' })[0]

        Assert-Equal $false $result.Ok "definition damage fails"
        Assert-NotContains $result.Message "-RepairTasks" "definition damage is not a routine package update"
        Assert-Contains $result.Message "install.ps1" "definition damage points at the installer"
    }

    Test-Case "the repair path preserves the absolute trusted-executable contract" {
        $lib = Get-SourceOf "src\lib\devws-install.ps1"
        $start = $lib.IndexOf('function Get-DevWSRootScheduledTaskXml')
        $end   = $lib.IndexOf('# Uninstall decision model and execution')

        Assert-True ($start -ge 0 -and $end -gt $start) "the repair region is located"

        $region = $lib.Substring($start, $end - $start)

        Assert-Contains $region 'Test-DevWSTrustedExecutablePath' "the repair target must satisfy the trusted-executable policy"
        Assert-Contains $region 'New-DevWSScheduledTaskDefinition' "the repair builds definitions through the canonical owner"
        Assert-Contains $region 'Get-DevWSScheduledTaskActionArguments' "the repair uses the canonical arguments"

        foreach ($forbidden in @('Get-Command', '$env:PATH', 'Invoke-Expression', 'LOCALAPPDATA', 'WindowsApps')) {
            Assert-NotContains $region $forbidden "the repair never resolves the interpreter through $forbidden"
        }

        # Worker authentication still derives its expectation from the
        # administrator-controlled declaration; repair adds no dynamic path.
        $protocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        Assert-Contains $protocol 'Get-DevWSScheduledTaskDeclaration -TaskName $taskName' "worker authentication still reads the task declaration"
        Assert-Contains $protocol 'Get-DevWSWorkerFixedArgumentPrefix' "worker authentication still checks the fixed argv prefix"
    }

    Write-Host ""
    Start-TestGroup -Name 'protected-state' -Title 'Protected privileged-state foundation (Security Phase 2-A)'

    Test-Case "protected state path policy is SID-scoped and environment-proof" {
        $sid = Get-DevWSCurrentUserSid
        Assert-Equal ([System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value) $sid "the current user SID is the Windows identity SID"
        Assert-True ($sid -like "S-1-*") "the identity is a SID, never a username"

        $expectedBase = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) "DevWS\privileged-state"
        # The suite sets the repository-only protected-state fixture seam; clear
        # it for the ProgramData-derivation assertions (restored afterwards).
        $savedSeam = $env:DEVWS_PROTECTED_STATE_ROOT
        try {
            Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue
            Assert-Equal $expectedBase (Get-DevWSPrivilegedStateBaseRoot) "the base root derives from the ProgramData known folder"
            Assert-Equal (Join-Path $expectedBase $sid) (Get-DevWSPrivilegedStateRoot) "the protected root is SID-scoped"
            Assert-True ((Get-DevWSPrivilegedStateRoot) -ne (Get-DevWSStateRoot)) "the user state root and the protected state root are distinct"
        }
        finally {
            $env:DEVWS_PROTECTED_STATE_ROOT = $savedSeam
        }

        $syntheticA = "S-1-5-21-111111111-222222222-333333333-1001"
        $syntheticB = "S-1-5-21-111111111-222222222-333333333-1002"
        $rootA = Get-DevWSPrivilegedStateRoot -TestBaseRoot (Join-Path $TestRoot "p2a-synth") -UserSid $syntheticA
        $rootB = Get-DevWSPrivilegedStateRoot -TestBaseRoot (Join-Path $TestRoot "p2a-synth") -UserSid $syntheticB
        Assert-True ($rootA -ne $rootB) "synthetic SIDs produce distinct roots"
        Assert-Contains $rootA $syntheticA "the root carries its own SID"

        $securityA = New-DevWSPrivilegedStateDirectorySecurity -Kind User -UserSid $syntheticA
        Assert-True ((Test-DevWSPrivilegedStateSecurity -Security $securityA -Kind User -UserSid $syntheticA).Ok) "the synthetic SID policy validates for its own SID"
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $securityA -Kind User -UserSid $syntheticB).Ok "the same policy does not validate for another SID"

        # The installed chain creates/validates the DevWS container itself
        # instead of treating it as a trusted anchor.
        $installedChain = Get-DevWSProtectedStateComponentChain -Root (Join-Path $expectedBase (Get-DevWSCurrentUserSid))
        Assert-Equal ([Environment]::GetFolderPath('CommonApplicationData')) $installedChain.Anchor "the installed anchor is the ProgramData known folder"
        Assert-Equal 3 @($installedChain.Components).Count "the installed chain is DevWS + privileged-state + SID"
        Assert-Equal "DevWS" (Split-Path -Leaf ([string]$installedChain.Components[0])) "the DevWS container is part of the chain"
        Assert-Equal "privileged-state" (Split-Path -Leaf ([string]$installedChain.Components[1])) "the privileged-state container is part of the chain"

        $fixtureChain = Get-DevWSProtectedStateComponentChain -Root (Join-Path (Join-Path $TestRoot "p2a-chain") "privileged-state\S-1-5-21-111111111-222222222-333333333-1001")
        Assert-Equal (Join-Path $TestRoot "p2a-chain") $fixtureChain.Anchor "the fixture anchor is the fixture base"
        Assert-Equal 2 @($fixtureChain.Components).Count "the fixture chain is privileged-state + SID"

        $saved = @{}
        foreach ($name in @("DEVWS_STATE_ROOT", "DEVWS_RUNTIME_ROOT", "DEVWS_LAUNCH_TRACE", "DEVWS_PROTECTED_STATE_ROOT")) {
            $saved[$name] = [Environment]::GetEnvironmentVariable($name)
        }

        try {
            Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue
            $env:DEVWS_STATE_ROOT   = "C:\hostile-state"
            $env:DEVWS_RUNTIME_ROOT = "C:\hostile-runtime"
            $env:DEVWS_LAUNCH_TRACE = "C:\hostile-trace.log"

            Assert-Equal $expectedBase (Get-DevWSPrivilegedStateBaseRoot) "the base root ignores every legacy DEVWS_* override"
            Assert-Equal (Join-Path $expectedBase $sid) (Get-DevWSPrivilegedStateRoot) "the protected root ignores every legacy DEVWS_* override"

            # The explicit repository-only fixture seam is honored in the
            # repository layout; the installed-layout probes below prove that
            # installed-normal and installed-privileged layouts ignore it.
            $env:DEVWS_PROTECTED_STATE_ROOT = "C:\hostile-protected-seam"
            Assert-Equal (Join-Path "C:\hostile-protected-seam" "privileged-state") (Get-DevWSPrivilegedStateBaseRoot) "the repository-only fixture seam is an explicit repository route"
        }
        finally {
            foreach ($name in $saved.Keys) {
                [Environment]::SetEnvironmentVariable($name, $saved[$name])
            }
        }
    }

    Test-Case "installed layouts cannot redirect the protected state root" {
        $fixture = New-InstallFixture "p2a-path"
        $normalLibDir = Join-Path $fixture.Root "app\lib"
        $privilegedLibDir = Join-Path $fixture.Privileged "lib"
        New-Item -ItemType Directory -Path $normalLibDir, $privilegedLibDir -Force | Out-Null
        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\lib\devws-paths.ps1") -Destination (Join-Path $normalLibDir "devws-paths.ps1")
        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\lib\devws-paths.ps1") -Destination (Join-Path $privilegedLibDir "devws-paths.ps1")

        $expectedBase = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) "DevWS\privileged-state"
        $expectedRoot = Join-Path $expectedBase (Get-DevWSCurrentUserSid)

        $probeTemplate = @'
. '@LIB@'
$refused = $false
try { $null = Get-DevWSPrivilegedStateRoot -TestBaseRoot 'C:\evil' } catch { $refused = $true }
"layout=$(Get-DevWSPathsLayout)"
"base=$(Get-DevWSPrivilegedStateBaseRoot)"
"root=$(Get-DevWSPrivilegedStateRoot)"
"refused=$refused"
'@

        $saved = @{}
        foreach ($name in @("DEVWS_STATE_ROOT", "DEVWS_RUNTIME_ROOT", "DEVWS_LAUNCH_TRACE", "DEVWS_PROTECTED_STATE_ROOT")) {
            $saved[$name] = [Environment]::GetEnvironmentVariable($name)
        }

        try {
            $env:DEVWS_STATE_ROOT   = "C:\hostile-state"
            $env:DEVWS_RUNTIME_ROOT = "C:\hostile-runtime"
            $env:DEVWS_LAUNCH_TRACE = "C:\hostile-trace.log"
            $env:DEVWS_PROTECTED_STATE_ROOT = "C:\hostile-protected-seam"

            foreach ($lib in @((Join-Path $normalLibDir "devws-paths.ps1"), (Join-Path $privilegedLibDir "devws-paths.ps1"))) {
                $probePath = Join-Path $TestRoot ("p2a-layout-probe-" + [guid]::NewGuid().ToString("N") + ".ps1")
                Set-Content -LiteralPath $probePath -Value ($probeTemplate.Replace("@LIB@", $lib)) -NoNewline

                $probeOutput = & pwsh -NoLogo -NoProfile -File $probePath 2>&1 | Out-String

                Assert-Contains $probeOutput "base=$expectedBase" "the installed layout resolves the ProgramData base root ($lib)"
                Assert-Contains $probeOutput "root=$expectedRoot" "the installed layout resolves the SID root ($lib)"
                Assert-Contains $probeOutput "refused=True" "the installed layout refuses the fixture override ($lib)"
                Assert-NotContains $probeOutput "hostile" "no DEVWS_* override is honored ($lib)"
            }
        }
        finally {
            foreach ($name in $saved.Keys) {
                [Environment]::SetEnvironmentVariable($name, $saved[$name])
            }
        }
    }

    Test-Case "protected state security policy is semantic and fail-closed" {
        $sid = Get-DevWSCurrentUserSid
        $sidObject = [System.Security.Principal.SecurityIdentifier]::new($sid)
        $admins = [System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-544")
        $system = [System.Security.Principal.SecurityIdentifier]::new("S-1-5-18")

        Assert-True ((Test-DevWSPrivilegedStateSecurity -Security (New-DevWSPrivilegedStateDirectorySecurity -Kind Base) -Kind Base).Ok) "the base policy validates"
        Assert-True ((Test-DevWSPrivilegedStateSecurity -Security (New-DevWSPrivilegedStateDirectorySecurity -Kind User) -Kind User).Ok) "the user policy validates"

        # Semantic ACE ordering: adding the same rules in a different order must
        # not cause a false failure.
        $reordered = New-Object System.Security.AccessControl.DirectorySecurity
        $reordered.SetAccessRuleProtection($true, $false)
        $reordered.SetOwner($admins)
        $reordered.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Allow")))
        $reordered.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($admins, "FullControl", "ContainerInherit, ObjectInherit", "None", "Allow")))
        $reordered.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($system, "FullControl", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Assert-True ((Test-DevWSPrivilegedStateSecurity -Security $reordered -Kind User).Ok) "ACE enumeration order is irrelevant"

        foreach ($rights in @("Write", "Modify", "Delete", "DeleteSubdirectoriesAndFiles", "ChangePermissions", "TakeOwnership", "FullControl")) {
            $mutated = New-DevWSPrivilegedStateDirectorySecurity -Kind User
            $mutated.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, $rights, "ContainerInherit, ObjectInherit", "None", "Allow")))
            Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $mutated -Kind User).Ok "user right '$rights' is rejected"
        }

        $writePolicy = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $writePolicy.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        $writeResult = Test-DevWSPrivilegedStateSecurity -Security $writePolicy -Kind User
        Assert-Contains ($writeResult.Errors -join " ") "write-capable" "the user-write error names the write rights"

        $unprotected = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $unprotected.SetAccessRuleProtection($false, $true)
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $unprotected -Kind User).Ok "an unprotected DACL is rejected"

        # SYSTEM and Administrators must retain FullControl.
        $weakenedSystem = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $weakenedSystem.PurgeAccessRules($system)
        $weakenedSystem.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($system, "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $weakenedSystem -Kind User).Ok "a weakened SYSTEM ACE is rejected"

        $weakenedAdmins = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $weakenedAdmins.PurgeAccessRules($admins)
        $weakenedAdmins.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($admins, "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $weakenedAdmins -Kind User).Ok "a weakened Administrators ACE is rejected"

        $missingUser = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $missingUser.PurgeAccessRules($sidObject)
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $missingUser -Kind User).Ok "a missing user ACE is rejected"

        # Partial read masks are never acceptable: the complete read+execute/list
        # mask is required, not merely an overlapping bit.
        foreach ($partial in @("ReadData", "ReadAttributes", "ExecuteFile")) {
            $partialPolicy = New-DevWSPrivilegedStateDirectorySecurity -Kind User
            $partialPolicy.PurgeAccessRules($sidObject)
            $partialPolicy.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, $partial, "ContainerInherit, ObjectInherit", "None", "Allow")))
            $partialResult = Test-DevWSPrivilegedStateSecurity -Security $partialPolicy -Kind User
            Assert-Equal $false $partialResult.Ok "a partial user read mask ($partial) is rejected"
            Assert-Contains ($partialResult.Errors -join " ") "missing part of the required read+execute" "the partial-mask error is actionable ($partial)"
        }

        $completePolicy = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $completePolicy.PurgeAccessRules($sidObject)
        $completePolicy.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Assert-Equal $true (Test-DevWSPrivilegedStateSecurity -Security $completePolicy -Kind User).Ok "the complete read+execute mask is accepted"

        # Inheritance flags and propagation flags must be exactly as intended.
        $variantCases = @(
            ,@("OI only",            [System.Security.AccessControl.InheritanceFlags]::ContainerInherit,                  [System.Security.AccessControl.PropagationFlags]::None,                "exactly ContainerInherit|ObjectInherit")
            ,@("CI only",            [System.Security.AccessControl.InheritanceFlags]::ObjectInherit,                     [System.Security.AccessControl.PropagationFlags]::None,                "exactly ContainerInherit|ObjectInherit")
            ,@("OI+CI inherit-only", [System.Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit',   [System.Security.AccessControl.PropagationFlags]::InheritOnly,         "must not use propagation flags")
            ,@("OI+CI no-propagate", [System.Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit',   [System.Security.AccessControl.PropagationFlags]::NoPropagateInherit,  "must not use propagation flags")
        )

        foreach ($variant in $variantCases) {
            $variantPolicy = New-DevWSPrivilegedStateDirectorySecurity -Kind User
            $variantPolicy.PurgeAccessRules($sidObject)
            $variantPolicy.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "ReadAndExecute", $variant[1], $variant[2], "Allow")))
            $variantResult = Test-DevWSPrivilegedStateSecurity -Security $variantPolicy -Kind User
            Assert-Equal $false $variantResult.Ok "inheritance variant '$($variant[0])' is rejected"
            Assert-Contains ($variantResult.Errors -join " ") $variant[3] "the inheritance error is explicit ($($variant[0]))"
        }

        # A fully inherited user ACE (real descriptor) is rejected.
        $inheritBase = Join-Path $TestRoot "p2a-inherited-ace"
        $inheritParent = Join-Path $inheritBase "parent"
        New-Item -ItemType Directory -Path $inheritParent -Force | Out-Null
        $parentAcl = Get-Acl -LiteralPath $inheritParent
        $parentAcl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $inheritParent -AclObject $parentAcl
        $childDir = Join-Path $inheritParent "child"
        New-Item -ItemType Directory -Path $childDir -Force | Out-Null
        $inheritedResult = Test-DevWSPrivilegedStateSecurity -Security (Get-Acl -LiteralPath $childDir) -Kind User
        Assert-Equal $false $inheritedResult.Ok "an inherited user ACE is rejected"
        Assert-Contains ($inheritedResult.Errors -join " ") "is inherited" "the inherited ACE is named"
        Assert-Contains ($inheritedResult.Errors -join " ") "not protected" "the inherited descriptor is rejected as unprotected"

        # Parent DELETE_CHILD semantics, expressed structurally: the user ACE
        # must never carry Delete or DeleteSubdirectoriesAndFiles.
        $userPolicy = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $userRules = @($userPolicy.GetAccessRules($true, $false, [System.Security.Principal.SecurityIdentifier]))
        $userRule = @($userRules | Where-Object { $_.IdentityReference.Value -eq $sid })[0]
        Assert-True ($null -ne $userRule) "the user ACE exists in the constructed policy"
        Assert-Equal 0 ([int]$userRule.FileSystemRights -band [int][System.Security.AccessControl.FileSystemRights]::Delete) "the user ACE grants no Delete"
        Assert-Equal 0 ([int]$userRule.FileSystemRights -band [int][System.Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles) "the user ACE grants no DeleteSubdirectoriesAndFiles"
        Assert-Equal 0 ([int]$userRule.FileSystemRights -band [int][System.Security.AccessControl.FileSystemRights]::ChangePermissions) "the user ACE grants no ChangePermissions"
        Assert-Equal 0 ([int]$userRule.FileSystemRights -band [int][System.Security.AccessControl.FileSystemRights]::TakeOwnership) "the user ACE grants no TakeOwnership"

        $wrongOwner = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $wrongOwner.SetOwner($sidObject)
        $ownerResult = Test-DevWSPrivilegedStateSecurity -Security $wrongOwner -Kind User
        Assert-Equal $false $ownerResult.Ok "a user-owned descriptor is rejected"
        Assert-Contains ($ownerResult.Errors -join " ") "expected BUILTIN\Administrators" "the owner error is actionable"

        $systemOwned = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $systemOwned.SetOwner($system)
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $systemOwned -Kind User).Ok "a SYSTEM owner is not accepted without explicit justification"

        $deny = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $deny.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Deny")))
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $deny -Kind User).Ok "a DENY ACE is rejected (no DENY is required or accepted)"

        $broad = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $broad.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-545"), "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $broad -Kind User).Ok "an unexpected write-capable trustee is rejected"

        $inheritOnly = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $inheritOnly.PurgeAccessRules($sidObject)
        $inheritOnly.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "ReadAndExecute", "ContainerInherit, ObjectInherit", "InheritOnly", "Allow")))
        $inheritResult = Test-DevWSPrivilegedStateSecurity -Security $inheritOnly -Kind User
        Assert-Equal $false $inheritResult.Ok "an inherit-only user ACE is rejected"
        Assert-Contains ($inheritResult.Errors -join " ") "must not use propagation flags" "the inherit-only error explains the rule"
    }

    Test-Case "protected state path safety rejects files, reparse points and unsafe owners" {
        $fixtureBase = Join-Path $TestRoot "p2a-safety"
        New-Item -ItemType Directory -Path $fixtureBase -Force | Out-Null

        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        Assert-Equal (Join-Path $fixtureBase "privileged-state") $state.BaseRoot "the base container shape"
        Assert-Equal (Join-Path $state.BaseRoot (Get-DevWSCurrentUserSid)) $state.Root "the SID root shape"
        Assert-True (@($state.Created).Count -ge 2) "missing components were created"
        Assert-True (@($state.Created) -contains $state.Root) "the created set includes the SID root"

        $createdSecurity = Get-Acl -LiteralPath $state.Root
        Assert-Equal "BUILTIN\Administrators" $createdSecurity.Owner "created directories are Administrators-owned"
        Assert-True ((Test-DevWSPrivilegedStateRoot -Root $state.Root).Ok) "the created foundation validates read-only"

        $again = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        Assert-Equal 0 @($again.Created).Count "re-running creation is idempotent"
        Assert-True ($null -eq $again.PSObject.Properties["Repaired"]) "the initializer no longer reports automatic repairs"
        Assert-Equal (@($state.Created).Count) @($again.Existing).Count "the components are recognized as existing"

        # High-created children inherit the token owner at kernel create time,
        # which is exactly why no post-create Set-Acl is used for runtime
        # writers (the elevated audit token's owner is BUILTIN\Administrators).
        $ownerProbe = Join-Path $state.Root "owner-probe.txt"
        [System.IO.File]::WriteAllText($ownerProbe, "probe")
        $fileOwnerSid = Resolve-DevWSSecurityIdentifier -Identity ([string](Get-Acl -LiteralPath $ownerProbe).Owner)
        $tokenOwner = [System.Security.Principal.WindowsIdentity]::GetCurrent().Owner
        Assert-True ($null -ne $fileOwnerSid) "the created file owner resolves to a SID"
        Assert-Equal $tokenOwner.Value $fileOwnerSid.Value "created children inherit the token owner at create time"
        Remove-Item -LiteralPath $ownerProbe -Force

        # A file where the container must be a directory.
        $fileBase = Join-Path $TestRoot "p2a-filepath"
        New-Item -ItemType Directory -Path $fileBase -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $fileBase "privileged-state") -Value "not a directory" -NoNewline
        Assert-Throws { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fileBase } "not a directory" "a file at the container path fails closed"

        # A junction where a component must be an ordinary directory.
        $linkBase = Join-Path $TestRoot "p2a-reparse"
        New-Item -ItemType Directory -Path $linkBase -Force | Out-Null
        $junction = New-Item -ItemType Junction -Path (Join-Path $linkBase "privileged-state") -Target $fixtureBase
        $reparseSafety = Test-DevWSProtectedStatePathSafety -Root (Join-Path $linkBase "privileged-state\S-1-5-21-111111111-222222222-333333333-1001")
        Assert-Equal $false $reparseSafety.Ok "the shared safety walk rejects a reparse component"
        Assert-Contains ($reparseSafety.Errors -join " ") "reparse point" "the reparse error is explicit"
        Assert-Throws { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $linkBase } "reparse point" "creation refuses a junction component"
        [System.IO.Directory]::Delete($junction.FullName, $false)

        # A user-owned pre-created container is never adopted.
        $ownedBase = Join-Path $TestRoot "p2a-owned"
        $ownedContainer = Join-Path $ownedBase "privileged-state"
        New-Item -ItemType Directory -Path $ownedContainer -Force | Out-Null
        $ownedAcl = Get-Acl -LiteralPath $ownedContainer
        $ownedAcl.SetOwner([System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid)))
        Set-Acl -LiteralPath $ownedContainer -AclObject $ownedAcl
        Assert-Throws { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $ownedBase } "owned by" "a user-owned component is refused, never adopted"

        # Unknown owner is rejected by the pure policy as well.
        $unknownOwner = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $unknownOwner.SetOwner([System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-545"))
        Assert-Equal $false (Test-DevWSPrivilegedStateSecurity -Security $unknownOwner -Kind User).Ok "an unknown owner is rejected"

        Assert-Throws { Get-DevWSPrivilegedStateRoot -TestBaseRoot (Join-Path $TestRoot "p2a-sid") -UserSid "not-a-sid" } "not a valid security identifier" "invalid SID text fails closed"
    }

    Test-Case "protected state removal planning is empty-only, SID-scoped and reparse-safe" {
        $fixtureBase = Join-Path $TestRoot "p2a-removal"
        New-Item -ItemType Directory -Path $fixtureBase -Force | Out-Null
        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        Assert-Equal $true (Test-DevWSProtectedStateRootRemovable -Root $state.Root).Ok "an empty valid root is removable"

        Set-Content -LiteralPath (Join-Path $state.Root "future-state.json") -Value "{}" -NoNewline
        $nonEmpty = Test-DevWSProtectedStateRootRemovable -Root $state.Root
        Assert-Equal $false $nonEmpty.Ok "a non-empty root is preserved"
        Assert-Contains $nonEmpty.Reason "not empty" "the reason explains the preserved state"
        Remove-Item -LiteralPath (Join-Path $state.Root "future-state.json") -Force

        $plan = Get-DevWSUninstallPlan -InstallRoot (Join-Path $TestRoot "p2a-removal-install") -CanonicalPath (Join-Path $TestRoot "p2a-removal-install\canonical.json") -LegacyShimPath (Join-Path $TestRoot "p2a-removal-install\local-bin\ws.cmd") -HotkeyPath (Join-Path $TestRoot "p2a-removal-install\Startup\TerminalShortcut.ahk") -Metadata (New-DevWSInstallMetadata) -PrivilegedStateRoot $state.Root
        Assert-Equal $true $plan.RemoveProtectedState "an empty valid root is planned for removal"
        Assert-Equal $state.Root $plan.ProtectedStatePath "the explicit fixture root is the removal target"
        Assert-Equal (Split-Path -Parent $state.Root) $plan.ProtectedStateBasePath "the base container is tracked"

        $implicitPlan = Get-DevWSUninstallPlan -InstallRoot (Join-Path $TestRoot "p2a-removal-install") -CanonicalPath (Join-Path $TestRoot "p2a-removal-install\canonical.json") -LegacyShimPath (Join-Path $TestRoot "p2a-removal-install\local-bin\ws.cmd") -HotkeyPath (Join-Path $TestRoot "p2a-removal-install\Startup\TerminalShortcut.ahk") -Metadata (New-DevWSInstallMetadata)
        Assert-Equal $null $implicitPlan.ProtectedStatePath "fixture plans never default to the real protected state root"

        $removal = Remove-DevWSProtectedStateRootSafe -Root $state.Root
        Assert-True (@($removal.Removed) -contains $state.Root) "the empty SID root is removed"
        Assert-True (@($removal.Removed) -contains $state.BaseRoot) "the empty base container is removed"
        Assert-True (-not (Test-Path -LiteralPath $state.Root)) "the SID root is gone"

        # Another user's SID root is never removed or invalidated.
        $syntheticA = "S-1-5-21-111111111-222222222-333333333-1001"
        $syntheticB = "S-1-5-21-111111111-222222222-333333333-1002"
        $stateA = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase -UserSid $syntheticA
        $stateB = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase -UserSid $syntheticB
        Assert-True ($stateA.Root -ne $stateB.Root) "synthetic SID roots are distinct"
        Assert-True ((Test-DevWSPrivilegedStateRoot -Root $stateB.Root -UserSid $syntheticB).Ok) "the second SID root validates for its own SID"

        $removalA = Remove-DevWSProtectedStateRootSafe -Root $stateA.Root -UserSid $syntheticA
        Assert-True (@($removalA.Removed) -contains $stateA.Root) "the targeted SID root is removed"
        Assert-True (Test-Path -LiteralPath $stateB.Root) "the other SID root is untouched"
        Assert-True (Test-Path -LiteralPath $state.BaseRoot) "the base container remains while another SID root exists"

        # A reparse SID root is never removable.
        $stateC = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        [System.IO.Directory]::Delete($stateC.Root, $false)
        $junction = New-Item -ItemType Junction -Path $stateC.Root -Target $fixtureBase
        $reparseRemoval = Test-DevWSProtectedStateRootRemovable -Root $stateC.Root
        Assert-Equal $false $reparseRemoval.Ok "a reparse SID root is never removable"
        Assert-Contains $reparseRemoval.Reason "reparse" "the reason names the reparse point"
        [System.IO.Directory]::Delete($junction.FullName, $false)
    }

    Test-Case "installer, uninstaller and health wire the protected state foundation safely" {
        $installer = Get-SourceOf "install.ps1"
        $installLib = Get-SourceOf "src\lib\devws-install.ps1"
        $uninstaller = Get-SourceOf "uninstall.ps1"
        $pathsLib = Get-SourceOf "src\lib\devws-paths.ps1"
        $healthLib = Get-SourceOf "src\lib\devws-health.ps1"

        Assert-Contains $installer "Initialize-DevWSPrivilegedStateRoot" "the installer creates/validates the foundation"
        Assert-Contains $installer "Undo-DevWSProtectedStateCreation" "the installer rolls back via the exact created-set helper"
        Assert-Contains $installer '@($protectedState.Created).Count -gt 0' "the rollback only runs for foundations created in this invocation"
        Assert-Contains $installer "Get-DevWSPrivilegedStateRoot" "the -HealthCheck mode enforces the protected root"
        Assert-Contains $installer '$healthContext.PrivilegedStateRoot = [string]$protectedState.Root' "installer health enforces the protected root"
        Assert-Contains $uninstaller "ProtectedStatePath" "the uninstaller reports the protected-state decision"
        Assert-Contains $installLib "Remove-DevWSProtectedStateRootSafe" "the uninstall execution uses the safe removal helper"
        Assert-Contains $installLib "Test-DevWSProtectedStateRootRemovable" "the uninstall plan validates before removal"
        Assert-Contains $healthLib 'Id             = "privileged-state"' "health carries the protected-state check"

        $initIndex = $installer.IndexOf("Initialize-DevWSPrivilegedStateRoot")
        $stageIndex = $installer.IndexOf("Install-DevWSPrivilegedFiles")
        $taskIndex = $installer.IndexOf("Install-DevWSScheduledTasks")
        Assert-True ($initIndex -gt $stageIndex -and $initIndex -lt $taskIndex) "creation happens after candidate staging and before task registration"

        # Race-safe exclusive creation: the authoritative native primitive (no
        # FileSystemAclExtensions as the security decision), no New-Item path.
        $start = $pathsLib.IndexOf("function Initialize-DevWSPrivilegedStateRoot {")
        Assert-True ($start -ge 0) "the initializer is located"
        $next = $pathsLib.IndexOf("`nfunction ", $start + 1)
        if ($next -lt 0) { $next = $pathsLib.Length }
        $initBody = $pathsLib.Substring($start, $next - $start)
        Assert-Contains $initBody "New-DevWSProtectedStateExclusiveDirectory" "the initializer uses the exclusive secure-create primitive"
        Assert-NotContains $initBody "FileSystemAclExtensions" "FileSystemAclExtensions is no longer the creation decision"
        Assert-NotContains $initBody "New-Item -ItemType Directory" "the initializer never creates an unsecured directory first"
        Assert-NotContains $initBody "Set-Acl -LiteralPath" "the initializer never repairs existing security automatically"
        Assert-Contains $initBody "Refusing to repair it automatically" "ACL drift fails closed with the explicit refusal message"
        Assert-Contains $pathsLib "SecureCreateDirectory" "the native exclusive-create primitive is wired"
        Assert-Contains $pathsLib "TryOpenPathIdentity" "the stable handle identity primitive is wired"
        Assert-Contains $pathsLib "OpenAndInspectPath" "the handle-bound identity+security inspection is wired"

        # Handle-bound validation: identity AND security come from one open
        # handle; the path-based ACL lookup and the before/after identity dance
        # are gone; the handle stays open for the COMPLETE semantic decision
        # and is disposed exactly once in a finally block.
        $componentStart = $pathsLib.IndexOf("function Test-DevWSProtectedStateComponent {")
        Assert-True ($componentStart -ge 0) "the component validator is located"
        $componentEnd = $pathsLib.IndexOf("`nfunction ", $componentStart + 1)
        if ($componentEnd -lt 0) { $componentEnd = $pathsLib.Length }
        $componentBody = $pathsLib.Substring($componentStart, $componentEnd - $componentStart)
        Assert-Contains $componentBody "Get-DevWSProtectedStateObjectInspection" "the validator uses the handle-bound inspection"
        Assert-NotContains $componentBody "Get-Acl" "no path-based Get-Acl remains in the component validator"
        Assert-NotContains $componentBody "Get-DevWSProtectedStateObjectIdentity" "the before/after identity dance is removed"
        Assert-Contains $componentBody "finally" "the validation handle is released in a finally block"
        Assert-Contains $componentBody "inspection.Dispose()" "the validation handle is disposed exactly through the owned scope"
        $semanticIndex = $componentBody.IndexOf("Test-DevWSPrivilegedStateSecurity")
        $disposeIndex = $componentBody.IndexOf("inspection.Dispose()")
        Assert-True (($semanticIndex -ge 0) -and ($disposeIndex -gt $semanticIndex)) "the semantic decision runs before the handle is released"

        # Anchor delete-child invariant: real Medium-token access check, gated
        # on the installed chain, with no environment bypass.
        Assert-Contains $pathsLib "Test-DevWSProtectedStateAnchorSafety" "the anchor safety check exists"
        Assert-Contains $pathsLib "TryInspectAnchorAccess" "the anchor check uses the native access check"
        Assert-Contains $pathsLib '$chain.Installed' "the anchor check is gated on the installed chain"
        $rootStart = $pathsLib.IndexOf("function Test-DevWSPrivilegedStateRoot {")
        Assert-True ($rootStart -ge 0) "the root validator is located"
        $rootEnd = $pathsLib.IndexOf("`nfunction ", $rootStart + 1)
        if ($rootEnd -lt 0) { $rootEnd = $pathsLib.Length }
        $rootValidator = $pathsLib.Substring($rootStart, $rootEnd - $rootStart)
        Assert-Contains $rootValidator "Test-DevWSProtectedStateAnchorSafety" "the root validator includes anchor safety"
        $anchorStart = $pathsLib.IndexOf("function Test-DevWSProtectedStateAnchorSafety {")
        Assert-True ($anchorStart -ge 0) "the anchor check is located"
        $anchorEnd = $pathsLib.IndexOf("`nfunction ", $anchorStart + 1)
        if ($anchorEnd -lt 0) { $anchorEnd = $pathsLib.Length }
        $anchorBody = $pathsLib.Substring($anchorStart, $anchorEnd - $anchorStart)
        Assert-NotContains $anchorBody "env:" "the anchor check has no environment bypass"
        Assert-Contains $anchorBody "FILE_DELETE_CHILD" "the anchor check names the delete-child invariant"

        # Health check: healthy fixture passes; drift fails; missing fails;
        # repository contexts without the property pass through.
        $fixtureBase = Join-Path $TestRoot "p2a-health"
        New-Item -ItemType Directory -Path $fixtureBase -Force | Out-Null
        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        $sparseRoot = Join-Path $TestRoot "p2a-health-install"
        New-Item -ItemType Directory -Path (Join-Path $sparseRoot "state") -Force | Out-Null

        $context = [pscustomobject]@{
            InstallRoot         = $sparseRoot
            StateRoot           = Join-Path $sparseRoot "state"
            CanonicalPath       = Join-Path $sparseRoot "canonical.json"
            StartupPath         = Join-Path $sparseRoot "Startup"
            LegacyShimPath      = Join-Path $sparseRoot "local-bin\ws.cmd"
            WindowsTerminalPath = Join-Path $sparseRoot "wt.exe"
            AutoHotkeyPath      = Join-Path $sparseRoot "AutoHotkey64.exe"
            MetadataPath        = Join-Path $sparseRoot "state\install-metadata.json"
            PrivilegedRoot      = Join-Path $sparseRoot "privileged"
            PrivilegedStateRoot = $state.Root
        }

        function Get-P2AHealthById($summary) {
            $byId = @{}
            foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }
            return $byId
        }

        $byId = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $true $byId["privileged-state"].Ok "a healthy foundation passes"

        $writeBack = Get-Acl -LiteralPath $state.Root
        $writeBack.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid)), "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $state.Root -AclObject $writeBack
        $byId = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $false $byId["privileged-state"].Ok "a user-write ACE fails the check"
        Assert-Contains $byId["privileged-state"].Message "write-capable" "the failure names the write grant"

        $protected = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        Set-Acl -LiteralPath $state.Root -AclObject $protected
        $byId = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $true $byId["privileged-state"].Ok "repairing the policy restores the check"

        $unprotectedAcl = Get-Acl -LiteralPath $state.Root
        $unprotectedAcl.SetAccessRuleProtection($false, $true)
        Set-Acl -LiteralPath $state.Root -AclObject $unprotectedAcl
        $byId = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $false $byId["privileged-state"].Ok "inheritance drift fails the check"
        Assert-Contains $byId["privileged-state"].Message "inherited ACEs" "the failure names the inheritance drift"
        Set-Acl -LiteralPath $state.Root -AclObject $protected

        $missingRoot = Join-Path $fixtureBase "missing-root\privileged-state\S-1-5-21-111111111-222222222-333333333-1001"
        $context.PrivilegedStateRoot = $missingRoot
        $byId = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $false $byId["privileged-state"].Ok "a missing root fails the check"
        Assert-Contains $byId["privileged-state"].Message "run install.ps1" "the missing-root failure is actionable"

        $context.PrivilegedStateRoot = $state.Root
        $reparseProbe = Join-Path $fixtureBase "reparse-probe"
        New-Item -ItemType Directory -Path $reparseProbe -Force | Out-Null
        [System.IO.Directory]::Delete($state.Root, $false)
        $junction = New-Item -ItemType Junction -Path $state.Root -Target $reparseProbe
        $byId = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $context)
        Assert-Equal $false $byId["privileged-state"].Ok "a reparse component fails the check"
        Assert-Contains $byId["privileged-state"].Message "reparse point" "the failure names the reparse component"
        [System.IO.Directory]::Delete($junction.FullName, $false)

        $legacyContext = [pscustomobject]@{ InstallRoot = $sparseRoot; StateRoot = Join-Path $sparseRoot "state" }
        $legacyById = Get-P2AHealthById (Invoke-DevWSHealthCheck -Context $legacyContext)
        Assert-Equal $true $legacyById["privileged-state"].Ok "repository/legacy contexts keep the pass-through"
    }

    Test-Case "state routing and runtime generation are unchanged by the foundation" {
        $savedState = $env:DEVWS_STATE_ROOT
        $savedRuntime = $env:DEVWS_RUNTIME_ROOT

        try {
            $env:DEVWS_STATE_ROOT = "C:\p2a-state"
            Remove-Item env:\DEVWS_RUNTIME_ROOT -ErrorAction SilentlyContinue

            Assert-Equal "C:\p2a-state" (Get-DevWSStateRoot) "the user state root keeps its current behavior"
            Assert-Equal "C:\p2a-state" (Get-DevWSRuntimeRoot) "the runtime root keeps its current behavior"
            Assert-Equal (Join-Path "C:\p2a-state" "runtime-state.json") (Get-DevWSStatePath) "the runtime-state path is unchanged"
            Assert-Equal (Join-Path (Join-Path "C:\p2a-state" "cwd-sessions") "main\t0.json") (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "t0") "the cwd session path is unchanged"
            Assert-Equal (Join-Path (Join-Path "C:\p2a-state" "cwd") "main\t0.json") (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "t0") "the cwd publication path is unchanged"

            # Public Security Phase 2-D: the historical request/result file
            # exchange is retired; the worker transport is an operation-scoped
            # single-instance pipe namespace and never resolves paths under the
            # user state root.
            $workerProtocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
            Assert-Contains $workerProtocol "function Get-DevWSWorkerOperationPipeName" "worker pipe namespace helper present"
            Assert-NotContains $workerProtocol "Get-DevWSExchangePaths" "request/result file exchange retired"
            Assert-NotContains $workerProtocol "Get-DevWSRuntimeRoot" "worker transport never resolves the user runtime root"
            Assert-True ((Get-DevWSWorkerOperationPipeName -Kind "launch") -like "DevWS.Worker.launch.*") "installed worker namespace shape"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_STATE_ROOT = $savedState }
            if ($null -eq $savedRuntime) { Remove-Item env:\DEVWS_RUNTIME_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_RUNTIME_ROOT = $savedRuntime }
        }

        # Runtime generation hashes deployment code only; protected state is not
        # part of either root and must never cause restart churn.
        $normalRoot = Join-Path $TestRoot "p2a-gen-normal"
        $privilegedRoot = Join-Path $TestRoot "p2a-gen-privileged"
        New-Item -ItemType Directory -Path $normalRoot, $privilegedRoot -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $normalRoot "ws.ps1") -Value "# normal" -NoNewline
        Set-Content -LiteralPath (Join-Path $privilegedRoot "elevated.ps1") -Value "# privileged" -NoNewline

        $before = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $normalRoot -PrivilegedRoot $privilegedRoot

        $genStateBase = Join-Path $TestRoot "p2a-gen-state"
        New-Item -ItemType Directory -Path $genStateBase -Force | Out-Null
        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $genStateBase
        Set-Content -LiteralPath (Join-Path $state.Root "runtime-state.json") -Value "{}" -NoNewline

        $after = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $normalRoot -PrivilegedRoot $privilegedRoot
        Assert-Equal $before $after "protected state content never changes the runtime generation"

        # Public Security Phase 2-D: the worker transport is pipe-only and no
        # longer resolves the user runtime root; the capture artifact lives in
        # the protected publication (Phase 2-B) and is never written under the
        # runtime root.
        $workerProtocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        Assert-NotContains $workerProtocol "Get-DevWSRuntimeRoot" "the worker transport never resolves the runtime root"
        Assert-Contains $workerProtocol "function New-DevWSWorkerPipeServer" "the worker transport creates the secure pipe"
        $captureWorker = Get-SourceOf "src\workers\elevated-capture.ps1"
        Assert-Contains $captureWorker "New-DevWSProtectedCaptureClaim" "the capture worker claims a protected publication"
        Assert-Contains $captureWorker "Set-DevWSProtectedPublicationIdentity" "the capture worker stamps the publication identity"
        Assert-Contains $captureWorker "ClaimPath" "the capture worker writes into the claimed directory"
        Assert-NotContains $captureWorker "capture-elevated.txt" "the capture worker never writes unprotected fixed-name geometry"
        Assert-NotContains $captureWorker "Get-DevWSRuntimeRoot" "the capture worker never resolves the user runtime root itself"
    }

    Test-Case "protected state ACL drift fails closed without automatic repair" {
        $sidObject = [System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid))
        $usersObject = [System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-545")

        $fixtureBase = Join-Path $TestRoot "p2a-drift"
        New-Item -ItemType Directory -Path $fixtureBase -Force | Out-Null

        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        $baseContainer = $state.BaseRoot
        [System.IO.Directory]::Delete($state.Root, $false)   # descendants missing

        # Existing valid base + missing descendant -> only the descendant is
        # created and the base is reused (no whole-chain repair path exists).
        $created = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase
        Assert-Equal 1 @($created.Created).Count "only the missing descendant is created"
        Assert-Equal $state.Root ([string]$created.Created[0]) "the created component is the SID root"
        Assert-Equal $baseContainer ([string]$created.Existing[0]) "the valid base component is reused"
        [System.IO.Directory]::Delete($state.Root, $false)

        function Reset-P2ABase {
            Set-Acl -LiteralPath $baseContainer -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind Base)
        }

        # Every drift variant is refused, never repaired, and never extended.
        $drifts = @(
            ,@("user full control", {
                $acl = Get-Acl -LiteralPath $baseContainer
                $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "FullControl", "ContainerInherit, ObjectInherit", "None", "Allow")))
                Set-Acl -LiteralPath $baseContainer -AclObject $acl
            })
            ,@("missing user read", {
                $acl = Get-Acl -LiteralPath $baseContainer
                $acl.PurgeAccessRules($usersObject)
                Set-Acl -LiteralPath $baseContainer -AclObject $acl
            })
            ,@("extra read-only trustee", {
                $acl = Get-Acl -LiteralPath $baseContainer
                $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.SecurityIdentifier]::new("S-1-5-11"), "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Allow")))
                Set-Acl -LiteralPath $baseContainer -AclObject $acl
            })
            ,@("no-propagate user ace", {
                $acl = Get-Acl -LiteralPath $baseContainer
                $acl.PurgeAccessRules($usersObject)
                $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($usersObject, "ReadAndExecute", [System.Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit', [System.Security.AccessControl.PropagationFlags]::NoPropagateInherit, "Allow")))
                Set-Acl -LiteralPath $baseContainer -AclObject $acl
            })
        )

        foreach ($drift in $drifts) {
            Reset-P2ABase
            & $drift[1]

            $before = (Get-Acl -LiteralPath $baseContainer).Sddl
            $message = Get-ThrownMessage { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase }

            Assert-Contains $message "Refusing to repair it automatically" "the drift fails closed with the explicit refusal ($($drift[0]))"
            Assert-Contains $message "Protected state component" "the refusal names the component ($($drift[0]))"
            Assert-True (-not (Test-Path -LiteralPath $state.Root)) "no descendants were created under the invalid base ($($drift[0]))"
            Assert-Equal $before (Get-Acl -LiteralPath $baseContainer).Sddl "the drifted ACL was never modified ($($drift[0]))"
        }

        Reset-P2ABase
        Assert-True ((Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fixtureBase).Created.Count -ge 1) "restoring the canonical policy allows creation again"
    }

    Test-Case "failed-install rollback removes only the exact created set" {
        $sid = Get-DevWSCurrentUserSid
        $syntheticB = "S-1-5-21-111111111-222222222-333333333-1002"

        function New-P2AProtectedComponent([string]$Path, [string]$Kind) {
            [void][System.IO.FileSystemAclExtensions]::CreateDirectory((New-DevWSPrivilegedStateDirectorySecurity -Kind $Kind), $Path)
        }

        # (a) Entire synthetic chain created in this invocation.
        $fxA = Join-Path $TestRoot "p2a-rollback-a"
        $devwsA = Join-Path $fxA "DevWS"
        $psA = Join-Path $devwsA "privileged-state"
        $rootA = Join-Path $psA $sid
        New-Item -ItemType Directory -Path $fxA -Force | Out-Null
        New-P2AProtectedComponent $devwsA "Base"
        New-P2AProtectedComponent $psA "Base"
        New-P2AProtectedComponent $rootA "User"
        $undoA = Undo-DevWSProtectedStateCreation -CreatedPaths @($devwsA, $psA, $rootA)
        Assert-Equal 3 @($undoA.Removed).Count "the whole newly created chain is removed"
        Assert-True (-not (Test-Path -LiteralPath $devwsA)) "nothing remains of the created chain"

        # (b) DevWS pre-existing: only the created descendants are removed.
        $fxB = Join-Path $TestRoot "p2a-rollback-b"
        $devwsB = Join-Path $fxB "DevWS"
        $psB = Join-Path $devwsB "privileged-state"
        $rootB = Join-Path $psB $sid
        New-Item -ItemType Directory -Path $fxB -Force | Out-Null
        New-P2AProtectedComponent $devwsB "Base"
        New-P2AProtectedComponent $psB "Base"
        New-P2AProtectedComponent $rootB "User"
        $undoB = Undo-DevWSProtectedStateCreation -CreatedPaths @($psB, $rootB)
        Assert-True (@($undoB.Removed) -contains $psB -and @($undoB.Removed) -contains $rootB) "created descendants are removed"
        Assert-True (Test-Path -LiteralPath $devwsB) "the pre-existing DevWS container survives even when empty"
        Assert-True (-not (Test-Path -LiteralPath $psB)) "the created privileged-state container is gone"

        # (c) DevWS + privileged-state pre-existing: only the SID root is removed.
        $fxC = Join-Path $TestRoot "p2a-rollback-c"
        $devwsC = Join-Path $fxC "DevWS"
        $psC = Join-Path $devwsC "privileged-state"
        $rootC = Join-Path $psC $sid
        New-Item -ItemType Directory -Path $fxC -Force | Out-Null
        New-P2AProtectedComponent $devwsC "Base"
        New-P2AProtectedComponent $psC "Base"
        New-P2AProtectedComponent $rootC "User"
        $undoC = Undo-DevWSProtectedStateCreation -CreatedPaths @($rootC)
        Assert-Equal 1 @($undoC.Removed).Count "only the created SID root is removed"
        Assert-True (Test-Path -LiteralPath $psC) "the pre-existing privileged-state container survives"
        Assert-True (Test-Path -LiteralPath $devwsC) "the pre-existing DevWS container survives"

        # (d) Pre-existing SID root: an empty created set removes nothing.
        $fxD = Join-Path $TestRoot "p2a-rollback-d"
        $devwsD = Join-Path $fxD "DevWS"
        $psD = Join-Path $devwsD "privileged-state"
        $rootD = Join-Path $psD $sid
        New-Item -ItemType Directory -Path $fxD -Force | Out-Null
        New-P2AProtectedComponent $devwsD "Base"
        New-P2AProtectedComponent $psD "Base"
        New-P2AProtectedComponent $rootD "User"
        $undoD = Undo-DevWSProtectedStateCreation -CreatedPaths @()
        Assert-Equal 0 @($undoD.Removed).Count "nothing is removed for a pre-existing foundation"
        Assert-True (Test-Path -LiteralPath $rootD) "the pre-existing SID root survives"

        # (e) A created component that became non-empty is preserved with its ancestors.
        $fxE = Join-Path $TestRoot "p2a-rollback-e"
        $psE = Join-Path $fxE "privileged-state"
        $rootE = Join-Path $psE $sid
        New-Item -ItemType Directory -Path $fxE -Force | Out-Null
        New-P2AProtectedComponent $psE "Base"
        New-P2AProtectedComponent $rootE "User"
        Set-Content -LiteralPath (Join-Path $rootE "state.json") -Value "{}" -NoNewline
        $undoE = Undo-DevWSProtectedStateCreation -CreatedPaths @($psE, $rootE)
        Assert-Equal 0 @($undoE.Removed).Count "a non-empty created root is never removed"
        Assert-True (Test-Path -LiteralPath (Join-Path $rootE "state.json")) "the state content is untouched"
        Assert-True (Test-Path -LiteralPath $psE) "the ancestor is preserved as well"

        # (f) A created component that became a reparse point is never followed.
        $fxF = Join-Path $TestRoot "p2a-rollback-f"
        $psF = Join-Path $fxF "privileged-state"
        $rootF = Join-Path $psF $sid
        $targetF = Join-Path $TestRoot "p2a-rollback-f-target"
        New-Item -ItemType Directory -Path $fxF, $targetF -Force | Out-Null
        New-P2AProtectedComponent $psF "Base"
        New-P2AProtectedComponent $rootF "User"
        [System.IO.Directory]::Delete($rootF, $false)
        $junction = New-Item -ItemType Junction -Path $rootF -Target $targetF
        $undoF = Undo-DevWSProtectedStateCreation -CreatedPaths @($psF, $rootF)
        Assert-Equal 0 @($undoF.Removed).Count "a reparse created component is preserved"
        Assert-True (Test-Path -LiteralPath $rootF) "the reparse point was not followed or deleted"
        [System.IO.Directory]::Delete($rootF, $false)

        # (g) Another user's SID root is never removed or altered.
        $fxG = Join-Path $TestRoot "p2a-rollback-g"
        $psG = Join-Path $fxG "privileged-state"
        $rootG1 = Join-Path $psG $sid
        $rootG2 = Join-Path $psG $syntheticB
        New-Item -ItemType Directory -Path $fxG -Force | Out-Null
        New-P2AProtectedComponent $psG "Base"
        New-P2AProtectedComponent $rootG1 "User"
        New-P2AProtectedComponent $rootG2 "User"
        $undoG = Undo-DevWSProtectedStateCreation -CreatedPaths @($psG, $rootG1)
        Assert-True (@($undoG.Removed) -contains $rootG1) "the created SID root is removed"
        Assert-True (Test-Path -LiteralPath $rootG2) "the other SID root is untouched"
        Assert-True (Test-Path -LiteralPath $psG) "the base is kept while another SID root exists"

        # Uninstall keeps its own validated-empty cleanup helper (separate from
        # failed-install rollback).
        Assert-True ((Get-Command Remove-DevWSProtectedStateRootSafe -ErrorAction SilentlyContinue) -ne $null) "the uninstall helper remains available"
    }

    Test-Case "protected state exclusive creation distinguishes creation from raced objects" {
        $sid = Get-DevWSCurrentUserSid
        $sidObject = [System.Security.Principal.SecurityIdentifier]::new($sid)

        function New-P2XFixture([string]$Name) {
            $fx = Join-Path $TestRoot $Name
            New-Item -ItemType Directory -Path $fx -Force | Out-Null
            return $fx
        }

        # (1) missing observation + exclusive create Created -> validated and recorded as Created.
        $fx1 = New-P2XFixture "p2x-matrix-created"
        $r1 = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx1
        Assert-Equal 2 @($r1.Created).Count "a fresh fixture securely creates both components"
        Assert-Equal 0 @($r1.Existing).Count "nothing is reported as existing on a fresh fixture"
        Assert-Equal $r1.Root ([string]$r1.Created[1]) "the SID root is in the created set"
        Assert-True ((Test-DevWSPrivilegedStateRoot -Root $r1.Root).Ok) "the created root validates"

        # (2) missing observation + AlreadyExists + exact-valid existing -> reuse, NOT Created.
        $fx2 = New-P2XFixture "p2x-matrix-raced-valid"
        $baseSecurity = New-DevWSPrivilegedStateDirectorySecurity -Kind Base
        $baseSddl = $baseSecurity.GetSecurityDescriptorSddlForm([System.Security.AccessControl.AccessControlSections]::Owner -bor [System.Security.AccessControl.AccessControlSections]::Access)
        Assert-Equal "Created" (New-DevWSProtectedStateExclusiveDirectory -Path (Join-Path $fx2 "privileged-state") -Sddl $baseSddl) "the competitor created a valid container first"
        Assert-Equal "AlreadyExists" (New-DevWSProtectedStateExclusiveDirectory -Path (Join-Path $fx2 "privileged-state") -Sddl $baseSddl) "the primitive reports the existing object authoritatively"
        $r2 = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx2
        Assert-Equal 1 @($r2.Created).Count "only the SID root is created by this invocation"
        Assert-Equal 1 @($r2.Existing).Count "the raced valid container is existing, not created"
        Assert-Equal (Join-Path $fx2 "privileged-state") ([string]$r2.Existing[0]) "the raced container is never claimed as created"

        # (3) AlreadyExists + user-owned -> fail closed, no `Set-Acl`, no descent.
        $fx3 = New-P2XFixture "p2x-matrix-raced-owned"
        $ownedSeam = {
            param($path, $sddl)

            if ((Split-Path -Leaf $path) -eq "privileged-state") {
                New-Item -ItemType Directory -Path $path -Force | Out-Null
                $acl = Get-Acl -LiteralPath $path
                $acl.SetOwner($sidObject)
                Set-Acl -LiteralPath $path -AclObject $acl
                return "AlreadyExists"
            }

            return (New-DevWSProtectedStateExclusiveDirectory -Path $path -Sddl $sddl)
        }
        Assert-Throws { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx3 -CreateAction $ownedSeam } "Refusing to repair it automatically" "a raced user-owned object is refused"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fx3 "privileged-state\$sid"))) "no descendant is created under the raced user-owned object"

        # (4) AlreadyExists + Administrators-owned but user-writable drift -> fail closed.
        $fx4 = New-P2XFixture "p2x-matrix-raced-drift"
        $driftSeam = {
            param($path, $sddl)

            if ((Split-Path -Leaf $path) -eq "privileged-state") {
                New-Item -ItemType Directory -Path $path -Force | Out-Null
                $acl = Get-Acl -LiteralPath $path
                $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
                Set-Acl -LiteralPath $path -AclObject $acl
                return "AlreadyExists"
            }

            return (New-DevWSProtectedStateExclusiveDirectory -Path $path -Sddl $sddl)
        }
        $driftRefusal = ""
        try { $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx4 -CreateAction $driftSeam } catch { $driftRefusal = $_.Exception.Message }
        Assert-Contains $driftRefusal "Refusing to repair it automatically" "a raced writable object is refused explicitly"
        Assert-Contains $driftRefusal "privileged-state" "the refusal names the raced component"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fx4 "privileged-state\$sid"))) "no descendant is created under the raced writable object"

        # (5) AlreadyExists + junction/reparse -> fail closed.
        $fx5 = New-P2XFixture "p2x-matrix-raced-reparse"
        $reparseTarget = New-P2XFixture "p2x-matrix-raced-reparse-target"
        $reparseSeam = {
            param($path, $sddl)

            if ((Split-Path -Leaf $path) -eq "privileged-state") {
                $null = New-Item -ItemType Junction -Path $path -Target $reparseTarget
                return "AlreadyExists"
            }

            return (New-DevWSProtectedStateExclusiveDirectory -Path $path -Sddl $sddl)
        }
        Assert-Throws { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx5 -CreateAction $reparseSeam } "reparse point" "a raced junction is refused"
        [System.IO.Directory]::Delete((Join-Path $fx5 "privileged-state"), $false)

        # (6) Created reported but immediate validation fails -> fail closed, no descent.
        $fx6 = New-P2XFixture "p2x-matrix-created-invalid"
        $invalidSeam = { param($path, $sddl) return "Created" }
        Assert-Throws { Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx6 -CreateAction $invalidSeam } "failed immediate validation" "a created-but-invalid component fails closed"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fx6 "privileged-state"))) "no further components are attempted after a failed immediate validation"
    }

    Test-Case "ordinary competing creators cannot make an insecure component acceptable" {
        $sid = Get-DevWSCurrentUserSid
        $fx = Join-Path $TestRoot "p2x-race"
        New-Item -ItemType Directory -Path $fx -Force | Out-Null
        $target = Join-Path $fx "privileged-state"

        # Disposable competing creator: an ordinary create loop against the
        # exact component path (the same operation a Medium process could run).
        $racerSource = @'
param([string]$Path)
$deadline = [DateTime]::UtcNow.AddSeconds(4)
while ([DateTime]::UtcNow -lt $deadline) {
    try { [void][System.IO.Directory]::CreateDirectory($Path) } catch { }
    Start-Sleep -Milliseconds 5
}
'@
        $racerPath = Join-Path $TestRoot "p2x-racer.ps1"
        Set-Content -LiteralPath $racerPath -Value $racerSource -NoNewline
        $racer = Start-Process -FilePath (Join-Path $PSHOME "pwsh.exe") -ArgumentList @("-NoLogo", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $racerPath, "-Path", $target) -PassThru -WindowStyle Hidden

        try {
            Start-Sleep -Milliseconds 300

            $outcome = $null
            $refused = $false
            $refusal = ""

            try { $outcome = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx }
            catch { $refused = $true; $refusal = $_.Exception.Message }

            if ($refused) {
                Assert-Contains $refusal "Refusing to repair it automatically" "a raced component is refused explicitly"
                Assert-True (-not (Test-Path -LiteralPath (Join-Path $target $sid))) "no descendant is created under the refused component"

                $componentValidation = Test-DevWSProtectedStateComponent -Component $target -Kind Base
                Assert-Equal $false $componentValidation.Ok "the raced component is never accepted as valid"
            }
            else {
                Assert-True ((Test-DevWSPrivilegedStateRoot -Root $outcome.Root).Ok) "the created root validates despite the competitor"
                Assert-Equal "BUILTIN\Administrators" (Get-Acl -LiteralPath $outcome.Root).Owner "the created SID root is Administrators-owned"
                Assert-Equal "BUILTIN\Administrators" (Get-Acl -LiteralPath $target).Owner "the container stays Administrators-owned despite concurrent creates"
                Assert-Equal 1 @(@($outcome.Created) | Where-Object { $_ -ieq $target }).Count "the container is only reported as created when this invocation created it"
            }
        }
        finally {
            if ($null -ne $racer -and -not $racer.HasExited) {
                Stop-Process -Id $racer.Id -Force -ErrorAction SilentlyContinue
                [void]$racer.WaitForExit(5000)
            }
        }
    }

    Test-Case "protected state validation is bound to one stable handle" {
        function New-P2HFixture([string]$Name) {
            $fx = Join-Path $TestRoot $Name
            New-Item -ItemType Directory -Path $fx -Force | Out-Null
            return $fx
        }

        # Identity and ACL come from the same open handle for a valid component.
        $fx = New-P2HFixture "p2h-bound"
        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx

        if ($null -eq ([System.Management.Automation.PSTypeName]'P2HDirHandle').Type) {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class P2HDirHandle {
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern IntPtr CreateFileW(string fileName, uint desiredAccess, uint shareMode, IntPtr securityAttributes, uint creationDisposition, uint flagsAndAttributes, IntPtr templateFile);
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CloseHandle(IntPtr handle);

    const uint FILE_LIST_DIRECTORY = 0x1;
    const uint FILE_READ_ATTRIBUTES = 0x80;
    const uint DELETE = 0x10000;
    const uint FILE_SHARE_READ_WRITE_DELETE = 0x7;
    const uint FILE_SHARE_READ_WRITE = 0x3;   // no FILE_SHARE_DELETE
    const uint OPEN_EXISTING = 3;
    const uint FILE_FLAG_BACKUP_SEMANTICS = 0x02000000;

    // A competing creator/renamer holding DELETE access on the object.
    public static IntPtr OpenWithDeleteAccess(string path) {
        return CreateFileW(path, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | DELETE, FILE_SHARE_READ_WRITE_DELETE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, IntPtr.Zero);
    }

    // An inspection-style holder: no delete sharing, as the validator uses
    // (FILE_LIST_DIRECTORY included so the hold participates in sharing).
    public static IntPtr OpenWithoutDeleteShare(string path) {
        return CreateFileW(path, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES, FILE_SHARE_READ_WRITE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, IntPtr.Zero);
    }

    // A would-be deleter/renamer: requires DELETE access and delete sharing.
    public static IntPtr TryOpenForDelete(string path) {
        return CreateFileW(path, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | DELETE, FILE_SHARE_READ_WRITE_DELETE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, IntPtr.Zero);
    }

    public static void Close(IntPtr handle) { CloseHandle(handle); }
    public static int LastError() { return Marshal.GetLastWin32Error(); }
}
"@
        }

        $inspection = Get-DevWSProtectedStateObjectInspection -Path $state.Root
        Assert-Equal $true $inspection.Ok "the component opens for handle-bound inspection"
        Assert-Equal $true $inspection.IsDirectory "the inspection reports a directory"
        Assert-Equal $false $inspection.IsReparse "the inspection reports no reparse"
        Assert-True (-not [string]::IsNullOrWhiteSpace([string]$inspection.Sddl)) "the inspection returns the handle's own security descriptor"
        Assert-Contains $inspection.Sddl "D:P" "the handle descriptor is a protected DACL"

        $parsedSecurity = New-Object System.Security.AccessControl.DirectorySecurity
        $parsedSecurity.SetSecurityDescriptorSddlForm([string]$inspection.Sddl)
        $parsedOwner = $parsedSecurity.GetOwner([System.Security.Principal.SecurityIdentifier])
        Assert-Equal "S-1-5-32-544" $parsedOwner.Value "the handle descriptor carries the Administrators owner"

        # The owned scope holds a real no-delete-share handle until disposed;
        # Dispose() is idempotent and is the single release point.
        $heldProbe = [P2HDirHandle]::TryOpenForDelete($state.Root)
        Assert-True ($heldProbe.ToInt64() -eq -1) "a delete-capable open is blocked while the inspection scope is held"
        $inspection.Dispose()
        $inspection.Dispose()
        $releasedProbe = [P2HDirHandle]::TryOpenForDelete($state.Root)
        Assert-True ($releasedProbe.ToInt64() -ne -1) "the handle is released exactly by Dispose"
        [P2HDirHandle]::Close($releasedProbe)

        $component = Test-DevWSProtectedStateComponent -Component $state.Root -Kind User
        Assert-Equal $true $component.Ok "the handle-bound component validation passes"
        Assert-Equal $true $component.Stable "a single-handle validation is structurally stable"

        # Reparse object rejected.
        $linkTarget = New-P2HFixture "p2h-bound-target"
        [System.IO.Directory]::Delete($state.Root, $false)
        $junction = New-Item -ItemType Junction -Path $state.Root -Target $linkTarget
        $reparse = Test-DevWSProtectedStateComponent -Component $state.Root -Kind User
        Assert-Equal $false $reparse.Ok "a reparse object is rejected"
        Assert-Contains ($reparse.Errors -join " ") "reparse point" "the reparse rejection is explicit"
        [System.IO.Directory]::Delete($junction.FullName, $false)

        # Non-directory rejected.
        $filePath = Join-Path $fx "a-file"
        Set-Content -LiteralPath $filePath -Value "x" -NoNewline
        $fileResult = Test-DevWSProtectedStateComponent -Component $filePath -Kind User
        Assert-Equal $false $fileResult.Ok "a non-directory is rejected"
        Assert-Contains ($fileResult.Errors -join " ") "not a directory" "the non-directory rejection is explicit"

        # A security descriptor the inspection cannot accept fails closed.
        $locked = Join-Path $fx "locked"
        New-Item -ItemType Directory -Path $locked -Force | Out-Null
        $lockedAcl = Get-Acl -LiteralPath $locked
        $lockedAcl.SetAccessRuleProtection($true, $false)
        $lockedAcl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-544"), "ReadAndExecute", "ContainerInherit, ObjectInherit", "None", "Deny")))
        Set-Acl -LiteralPath $locked -AclObject $lockedAcl
        $lockedResult = Test-DevWSProtectedStateComponent -Component $locked -Kind Base
        Assert-Equal $false $lockedResult.Ok "an unacceptable security descriptor fails closed"
        Assert-True (($lockedResult.Errors -join " ") -match "stable handle-bound open|DENY access rule") "the failure is explicit"

        $resetAcl = New-Object System.Security.AccessControl.DirectorySecurity
        $resetAcl.SetAccessRuleProtection($true, $false)
        $resetAcl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-544"), "FullControl", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $locked -AclObject $resetAcl

        # Delete-sharing conflict: an existing delete-capable handle makes the
        # no-delete-share inspection open fail closed (sharing violation); it
        # succeeds again after the competing handle closes.
        $shareDir = Join-Path $fx "share"
        New-Item -ItemType Directory -Path $shareDir -Force | Out-Null

        # Direction 1: an existing delete-capable handle makes the validator's
        # no-delete-share open fail closed (sharing violation).
        $holder = [P2HDirHandle]::OpenWithDeleteAccess($shareDir)
        Assert-True ($holder -ne [IntPtr]::Zero -and $holder.ToInt64() -ne -1) "the competing delete-capable handle is open"

        try {
            $blocked = Get-DevWSProtectedStateObjectInspection -Path $shareDir
            Assert-Equal $false $blocked.Ok "the no-delete-share inspection fails while a delete-capable handle exists"
            Assert-Equal 32 $blocked.Error "the failure is a sharing violation"
            $blocked.Dispose()
        }
        finally {
            [P2HDirHandle]::Close($holder)
        }

        $afterRelease = Get-DevWSProtectedStateObjectInspection -Path $shareDir
        Assert-Equal $true $afterRelease.Ok "the inspection succeeds after the competing handle closes"
        $afterRelease.Dispose()

        # Direction 2: while the validator's held handle (no delete sharing) is
        # open, a delete-capable open cannot coexist with it.
        $validationHolder = [P2HDirHandle]::OpenWithoutDeleteShare($shareDir)
        Assert-True ($validationHolder -ne [IntPtr]::Zero -and $validationHolder.ToInt64() -ne -1) "the inspection-style holder is open"

        try {
            $wouldBeDeleter = [P2HDirHandle]::TryOpenForDelete($shareDir)
            Assert-True ($wouldBeDeleter.ToInt64() -eq -1) "a delete-capable open is blocked while the validation-style handle is held"
        }
        finally {
            [P2HDirHandle]::Close($validationHolder)
        }

        $afterHolderRelease = [P2HDirHandle]::TryOpenForDelete($shareDir)
        Assert-True ($afterHolderRelease.ToInt64() -ne -1) "a delete-capable open succeeds after the validation-style handle closes"
        [P2HDirHandle]::Close($afterHolderRelease)
    }

    Test-Case "the validation handle is held through the semantic decision and released once" {
        # Deterministic adversarial proof against the REAL validator. The
        # in-body function declaration below creates a process-local shadow of
        # the semantic ACL validator (torn down with the test body; PowerShell
        # resolves commands dynamically through the caller's scope chain, so
        # the REAL Test-DevWSProtectedStateComponent calls the shadow), and the
        # shadow attempts a delete-capable competing open EXACTLY while the
        # production semantic decision is running - no imitation handle is
        # involved: the blocking handle is the one the production validator
        # owns and must release in its finally block.
        function New-P2LFixture([string]$Name) {
            $fx = Join-Path $TestRoot $Name
            New-Item -ItemType Directory -Path $fx -Force | Out-Null
            return $fx
        }

        if ($null -eq ([System.Management.Automation.PSTypeName]'P2HDirHandle').Type) {
            Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class P2HDirHandle {
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern IntPtr CreateFileW(string fileName, uint desiredAccess, uint shareMode, IntPtr securityAttributes, uint creationDisposition, uint flagsAndAttributes, IntPtr templateFile);
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CloseHandle(IntPtr handle);

    const uint FILE_LIST_DIRECTORY = 0x1;
    const uint FILE_READ_ATTRIBUTES = 0x80;
    const uint DELETE = 0x10000;
    const uint FILE_SHARE_READ_WRITE_DELETE = 0x7;
    const uint FILE_SHARE_READ_WRITE = 0x3;   // no FILE_SHARE_DELETE
    const uint OPEN_EXISTING = 3;
    const uint FILE_FLAG_BACKUP_SEMANTICS = 0x02000000;

    // A competing creator/renamer holding DELETE access on the object.
    public static IntPtr OpenWithDeleteAccess(string path) {
        return CreateFileW(path, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | DELETE, FILE_SHARE_READ_WRITE_DELETE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, IntPtr.Zero);
    }

    // An inspection-style holder: no delete sharing, as the validator uses
    // (FILE_LIST_DIRECTORY included so the hold participates in sharing).
    public static IntPtr OpenWithoutDeleteShare(string path) {
        return CreateFileW(path, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES, FILE_SHARE_READ_WRITE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, IntPtr.Zero);
    }

    // A would-be deleter/renamer: requires DELETE access and delete sharing.
    public static IntPtr TryOpenForDelete(string path) {
        return CreateFileW(path, FILE_LIST_DIRECTORY | FILE_READ_ATTRIBUTES | DELETE, FILE_SHARE_READ_WRITE_DELETE, IntPtr.Zero, OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, IntPtr.Zero);
    }

    public static void Close(IntPtr handle) { CloseHandle(handle); }
    public static int LastError() { return Marshal.GetLastWin32Error(); }
}
"@
        }

        $fx = New-P2LFixture "p2l-lifetime"
        $state = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $fx

        # Baseline: with nothing holding the component, the competing open works.
        $free = [P2HDirHandle]::TryOpenForDelete($state.Root)
        Assert-True ($free.ToInt64() -ne -1) "a delete-capable open succeeds while nothing holds the component"
        [P2HDirHandle]::Close($free)

        $script:P2LComponent = $state.Root
        $script:P2LOriginal = (Get-Command -Name Test-DevWSPrivilegedStateSecurity -CommandType Function).ScriptBlock
        $script:P2LProbe = [pscustomobject]@{ Blocked = $null; Win32Error = $null; Delegated = $null }

        function Test-DevWSPrivilegedStateSecurity {
            param($Security, $Kind, $UserSid)

            $attempt = [P2HDirHandle]::TryOpenForDelete($script:P2LComponent)
            $script:P2LProbe.Blocked = ($attempt.ToInt64() -eq -1)
            $script:P2LProbe.Win32Error = $(if ($attempt.ToInt64() -eq -1) { [P2HDirHandle]::LastError() } else { 0 })
            if ($attempt.ToInt64() -ne -1) { [P2HDirHandle]::Close($attempt) }

            $delegated = & $script:P2LOriginal -Security $Security -Kind $Kind -UserSid $UserSid
            $script:P2LProbe.Delegated = $delegated
            return $delegated
        }

        $result = Test-DevWSProtectedStateComponent -Component $state.Root -Kind User

        Assert-True ($null -ne $script:P2LProbe.Blocked) "the semantic validator executed inside the real component validation"
        Assert-Equal $true $script:P2LProbe.Blocked "a delete-capable competing open is rejected while semantic ACL validation executes"
        Assert-Equal 32 $script:P2LProbe.Win32Error "the in-decision rejection is a sharing violation"
        Assert-True ($null -ne $script:P2LProbe.Delegated) "the shadow delegated to the real semantic validator"
        Assert-Equal $true $result.Ok "the real component validation still completed successfully"
        Assert-Equal 0 @($result.Errors).Count "no errors under the probe"

        # The production handle is released exactly when the decision completes.
        $after = [P2HDirHandle]::TryOpenForDelete($state.Root)
        Assert-True ($after.ToInt64() -ne -1) "a delete-capable open becomes possible after validation releases the handle"
        [P2HDirHandle]::Close($after)

        # The same hold-and-release applies to a REJECTED decision.
        $bad = Join-Path $fx "bad-component"
        New-Item -ItemType Directory -Path $bad -Force | Out-Null
        $script:P2LComponent = $bad
        $script:P2LProbe = [pscustomobject]@{ Blocked = $null; Win32Error = $null; Delegated = $null }

        $badResult = Test-DevWSProtectedStateComponent -Component $bad -Kind Base
        Assert-Equal $false $badResult.Ok "the user-owned component is rejected"
        Assert-Equal $true $script:P2LProbe.Blocked "the handle is held during a rejecting semantic decision too"
        $badAfter = [P2HDirHandle]::TryOpenForDelete($bad)
        Assert-True ($badAfter.ToInt64() -ne -1) "the rejection path also releases the handle"
        [P2HDirHandle]::Close($badAfter)

        Remove-Item -LiteralPath $fx -Recurse -Force -ErrorAction SilentlyContinue
    }

    Test-Case "anchor safety uses the real Medium-token access check" {
        $programData = [Environment]::GetFolderPath('CommonApplicationData')

        # The real anchor on this machine is inspected read-only with the
        # production Medium-token subject. Production accepts either genuine
        # Medium authority (the linked filtered token of an elevated caller, or
        # a caller that is already Medium) and fails closed when neither can be
        # obtained. A host in the last category cannot execute the integration
        # coverage at all, so it must still prove the fail-closed contract and
        # then report the missing execution as a visible runtime skip.
        $realAnchor = Test-DevWSProtectedStateAnchorSafety -Anchor $programData

        if ([string]$realAnchor.TokenSource -eq 'unavailable') {
            Assert-Equal $false ([bool]$realAnchor.Ok) "an unavailable Medium authority must fail closed"
            $anchorErrors = @($realAnchor.Errors) -join " "
            Assert-Contains $anchorErrors "could not be obtained reliably" "the refusal names the unobtainable Medium token"
            Assert-Contains $anchorErrors "refusing to assume the anchor is safe" "the refusal states it will not assume safety"
            Skip-Test "a reliable Medium (filtered) token authority is unavailable on this host (TokenSource=unavailable); the real anchor access check cannot execute"
        }

        Assert-True (@('linked-medium', 'duplicate-medium') -contains [string]$realAnchor.TokenSource) `
            "the checked subject is a Medium authority production recognizes"
        Assert-Equal $true ([bool]$realAnchor.Ok) "the real ProgramData anchor satisfies the delete-child invariant"

        # A synthetic anchor granting the Medium authority dangerous rights is rejected.
        function New-P2HAnchor([string]$Name, [string]$Right) {
            $path = Join-Path $TestRoot $Name
            New-Item -ItemType Directory -Path $path -Force | Out-Null
            $acl = Get-Acl -LiteralPath $path
            $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.SecurityIdentifier]::new("S-1-5-32-545"), $Right, "ContainerInherit, ObjectInherit", "None", "Allow")))
            Set-Acl -LiteralPath $path -AclObject $acl
            return $path
        }

        $deleteChildAnchor = New-P2HAnchor "p2h-anchor-dc" "DeleteSubdirectoriesAndFiles"
        $deleteChildResult = Test-DevWSProtectedStateAnchorSafety -Anchor $deleteChildAnchor
        Assert-Equal $false $deleteChildResult.Ok "a delete-child-granting anchor is rejected"
        Assert-Contains ($deleteChildResult.Errors -join " ") "FILE_DELETE_CHILD" "the failure names FILE_DELETE_CHILD"

        $writeDacAnchor = New-P2HAnchor "p2h-anchor-wd" "ChangePermissions"
        $writeDacResult = Test-DevWSProtectedStateAnchorSafety -Anchor $writeDacAnchor
        Assert-Equal $false $writeDacResult.Ok "a WRITE_DAC-granting anchor is rejected"
        Assert-Contains ($writeDacResult.Errors -join " ") "WRITE_DAC" "the failure names WRITE_DAC"
    }

    Test-Case "protected state fixture routing never bypasses the installed anchor" {
        $programData = [Environment]::GetFolderPath('CommonApplicationData')

        # Fixture chains are never "installed": the repository seam cannot
        # bypass the production anchor check, and the installed shape is
        # recognized purely from the trusted ProgramData known folder.
        $fixtureRoot = Join-Path (Join-Path $TestRoot "p2h-anchor-fixture") "privileged-state\S-1-5-21-111111111-222222222-333333333-1001"
        $fixtureChain = Get-DevWSProtectedStateComponentChain -Root $fixtureRoot
        Assert-Equal $false $fixtureChain.Installed "a fixture chain is not installed"

        $installedRoot = Join-Path (Join-Path $programData "DevWS\privileged-state") "S-1-5-21-111111111-222222222-333333333-1001"
        $installedChain = Get-DevWSProtectedStateComponentChain -Root $installedRoot
        Assert-Equal $true $installedChain.Installed "the installed shape is recognized"
        Assert-Equal $programData $installedChain.Anchor "the installed anchor is the ProgramData known folder"

        # The repository fixture seam still creates foundations even though its
        # fixture anchor is user-writable (fixture route only).
        $seamFixture = Join-Path $TestRoot "p2h-anchor-seam"
        New-Item -ItemType Directory -Path $seamFixture -Force | Out-Null
        $seamState = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $seamFixture
        Assert-True (@($seamState.Created).Count -ge 1) "the repository fixture seam still creates foundations"
    }

    Write-Host ""
    Start-TestGroup -Name 'protected-capture' -Title 'Protected capture publications (Security Phase 2-B)'

    Test-Case "protected capture accessors derive only from trusted authority" {
        $sid = Get-DevWSCurrentUserSid
        $fixtureBase = $env:DEVWS_PROTECTED_STATE_ROOT
        Assert-Equal (Join-Path (Join-Path $fixtureBase "privileged-state") $sid) (Get-DevWSPrivilegedStateRoot) "the repository seam resolves the protected root"
        Assert-Equal (Join-Path (Get-DevWSPrivilegedStateRoot) "runtime-state.json") (Get-DevWSProtectedRuntimeStatePath) "the protected runtime-cache path stays inside the protected root"
        Assert-Equal (Join-Path (Get-DevWSPrivilegedStateRoot) "captures") (Get-DevWSProtectedCapturesRoot) "the captures container stays inside the protected root"
        Assert-Equal (Join-Path (Get-DevWSProtectedCapturesRoot) "1789000000001") (Get-DevWSProtectedCaptureClaimPath -OperationId "1789000000001") "numeric claim paths are claim-scoped"
        $guidId = [guid]::NewGuid().ToString()
        Assert-Equal (Join-Path (Get-DevWSProtectedCapturesRoot) $guidId) (Get-DevWSProtectedCaptureClaimPath -OperationId $guidId) "GUID claim paths are claim-scoped"

        foreach ($bad in @("../x", "..\x", "x.txt", "ABC", "178-900", "$guidId ")) {
            $refused = $false
            try { $null = Get-DevWSProtectedCaptureClaimPath -OperationId $bad } catch { $refused = $true }
            Assert-Equal $true $refused "grammar refuses '$bad'"
        }

        # Installed layouts ignore every override, including the fixture seam.
        $fixture = New-InstallFixture "p2b-path"
        $normalLibDir = Join-Path $fixture.Root "app\lib"
        New-Item -ItemType Directory -Path $normalLibDir -Force | Out-Null
        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\lib\devws-paths.ps1") -Destination (Join-Path $normalLibDir "devws-paths.ps1")

        $probeTemplate = @'
. '@LIB@'
$expectedBase = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) "DevWS\privileged-state"
"layout=$(Get-DevWSPathsLayout)"
"runtime=$(Get-DevWSProtectedRuntimeStatePath)"
"captures=$(Get-DevWSProtectedCapturesRoot)"
$redirectRefused = $false
try { Assert-DevWSRuntimeStatePathAllowed -Path 'C:\evil\runtime-state.json' } catch { $redirectRefused = $true }
"redirectRefused=$redirectRefused"
$allowed = $false
try { Assert-DevWSRuntimeStatePathAllowed -Path (Get-DevWSProtectedRuntimeStatePath); $allowed = $true } catch { }
"allowed=$allowed"
$boundaryRefused = $false
try { Assert-DevWSProtectedStateWritable -Root 'C:\evil\p2b-boundary' } catch { $boundaryRefused = $true }
"boundaryRefused=$boundaryRefused"
'@

        $savedSeam = $env:DEVWS_PROTECTED_STATE_ROOT
        $savedState = $env:DEVWS_STATE_ROOT
        try {
            $env:DEVWS_PROTECTED_STATE_ROOT = "C:\hostile-protected-seam"
            $env:DEVWS_STATE_ROOT = "C:\hostile-state"

            $probePath = Join-Path $TestRoot ("p2b-path-probe-" + [guid]::NewGuid().ToString("N") + ".ps1")
            Set-Content -LiteralPath $probePath -Value ($probeTemplate.Replace("@LIB@", (Join-Path $normalLibDir "devws-paths.ps1"))) -NoNewline

            $probeOutput = & pwsh -NoLogo -NoProfile -File $probePath 2>&1 | Out-String

            $expectedRoot = Join-Path (Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) "DevWS\privileged-state") $sid
            Assert-Contains $probeOutput "layout=installed-normal" "the probe runs in the installed-normal layout"
            Assert-Contains $probeOutput "runtime=$(Join-Path $expectedRoot 'runtime-state.json')" "installed runtime-cache authority ignores every override"
            Assert-Contains $probeOutput "captures=$(Join-Path $expectedRoot 'captures')" "installed captures authority ignores every override"
            Assert-Contains $probeOutput "redirectRefused=True" "installed runtime-cache redirection is refused"
            Assert-Contains $probeOutput "allowed=True" "the protected runtime-cache path is the only installed target"
            Assert-Contains $probeOutput "boundaryRefused=True" "installed writes refuse a missing/drifted protected chain"
            Assert-NotContains $probeOutput "hostile" "no hostile override is honored"
        }
        finally {
            if ($null -eq $savedSeam) { Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_PROTECTED_STATE_ROOT = $savedSeam }
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "runtime cache routes to the protected publication and never promotes legacy state" {
        $savedState = $env:DEVWS_STATE_ROOT
        $stateRoot = Join-Path $TestRoot "p2b-runtime-repo"
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null
        try {
            $env:DEVWS_STATE_ROOT = $stateRoot
            Assert-Equal (Join-Path $stateRoot "runtime-state.json") (Get-DevWSStatePath) "the repository state path keeps the user state root"

            # Legacy state is never authority for the protected runtime cache.
            $legacy = Join-Path $stateRoot "runtime-state.json"
            Set-Content -LiteralPath $legacy -Value '{"version":2,"terminals":{"main/slot":{"windowId":"legacy","hwnd":999}}}' -NoNewline
            $protectedPath = Get-DevWSProtectedRuntimeStatePath
            Assert-True (-not (Test-Path -LiteralPath $protectedPath)) "the protected runtime cache starts absent"
            $empty = Read-DevWSRuntimeState -Path $protectedPath
            Assert-Equal 0 @($empty.terminals.Keys).Count "a missing protected cache is empty v2 (legacy is never promoted)"
            Assert-Equal 999 (Read-DevWSRuntimeState -Path $legacy).terminals['main/slot'].hwnd "the legacy file itself is untouched"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_STATE_ROOT = $savedState }
        }

        # Protected round trip with atomic replacement and v2 disposition.
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "slot" -WindowId "P2B" -Hwnd 123
        Save-DevWSRuntimeState -State $state -Path $protectedPath
        Assert-Equal 123 (Read-DevWSRuntimeState -Path $protectedPath).terminals['main/slot'].hwnd "the protected runtime cache round-trips"
        Assert-True (-not (Test-Path -LiteralPath "$protectedPath.tmp")) "no temp leftovers after the protected save"

        $state2 = Read-DevWSRuntimeState -Path $protectedPath
        Set-DevWSRuntimeTerminal -State $state2 -SetId "main" -Id "slot" -WindowId "P2B" -Hwnd 456
        Save-DevWSRuntimeState -State $state2 -Path $protectedPath
        Assert-Equal 456 (Read-DevWSRuntimeState -Path $protectedPath).terminals['main/slot'].hwnd "the protected runtime cache replaces atomically"

        Set-Content -LiteralPath $protectedPath -Value "{broken" -NoNewline
        Assert-Equal 0 @((Read-DevWSRuntimeState -Path $protectedPath).terminals.Keys).Count "corrupt protected state stays disposable"

        # Runtime generation never depends on protected-state contents.
        $normalRoot = Join-Path $TestRoot "p2b-gen-normal"
        $privilegedRoot = Join-Path $TestRoot "p2b-gen-privileged"
        New-Item -ItemType Directory -Path $normalRoot, $privilegedRoot -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $normalRoot "ws.ps1") -Value "# normal" -NoNewline
        Set-Content -LiteralPath (Join-Path $privilegedRoot "elevated.ps1") -Value "# privileged" -NoNewline
        $beforeGen = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $normalRoot -PrivilegedRoot $privilegedRoot
        Set-Content -LiteralPath $protectedPath -Value "{}" -NoNewline
        $afterGen = Get-DevWSEffectiveRuntimeGeneration -InstallRoot $normalRoot -PrivilegedRoot $privilegedRoot
        Assert-Equal $beforeGen $afterGen "protected runtime-cache contents never change the runtime generation"
    }

    Test-Case "protected claims are atomic, identity-stamped and replay-safe" {
        $base = Join-Path $TestRoot "p2b-claims"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base

        $brokerId = '1789000000101'
        $claim = New-DevWSProtectedCaptureClaim -OperationId $brokerId -TestBaseRoot $base
        $publication = $null
        try {
            # The claim-to-handle transition is covered: the freshly returned
            # claim is already held (delete probe fails with a sharing
            # violation) and retention cannot take it.
            Initialize-DevWSPrivilegeNativeRuntime
            $probe = [DevWSPrivilegeNative]::OpenClaimDeleteProbe($claim.ClaimPath)
            Assert-Equal $false $probe.IsOpen "the lifetime scope blocks the delete probe"
            Assert-Equal 32 $probe.Win32Error "the blocked probe is a sharing violation"
            $probe.Dispose()

            $publication = [guid]::NewGuid().ToString()
            Set-DevWSProtectedPublicationIdentity -ClaimPath $claim.ClaimPath -Publication $publication
            [System.IO.File]::WriteAllLines((Join-Path $claim.ClaimPath "capture-elevated.txt"), @("slot|1|2|3|4"), [System.Text.UTF8Encoding]::new($false))
        }
        finally {
            $claim.Scope.Dispose()
        }

        $read = Read-DevWSProtectedCapturePublication -OperationId $brokerId -ExpectedPublication $publication -TestBaseRoot $base
        Assert-Equal 1 $read.Geometry['slot'].x "the protected publication reads back"

        # Duplicate, replayed and grammar-invalid ids fail closed without
        # overwriting or adopting the existing publication.
        foreach ($dup in @($brokerId, "../evil", "ABC")) {
            $refused = $false
            try { $null = New-DevWSProtectedCaptureClaim -OperationId $dup -TestBaseRoot $base } catch { $refused = $true }
            Assert-Equal $true $refused "claim refusal for '$dup'"
        }
        Assert-Equal 1 (Read-DevWSProtectedCapturePublication -OperationId $brokerId -ExpectedPublication $publication -TestBaseRoot $base).Geometry['slot'].x "the duplicate attempt never overwrote the publication"

        # Worker GUID and replay parity.
        $workerId = [guid]::NewGuid().ToString()
        $workerPublication = New-DevWSTestCapturePublication -OperationId $workerId -Lines @("term|7|7|7|7") -TestBaseRoot $base
        $workerRefused = $false
        try { $null = New-DevWSTestCapturePublication -OperationId $workerId -TestBaseRoot $base } catch { $workerRefused = $true }
        Assert-Equal $true $workerRefused "a replayed worker GUID is refused"
        Assert-Equal 7 (Read-DevWSProtectedCapturePublication -OperationId $workerId -ExpectedPublication $workerPublication -TestBaseRoot $base).Geometry['term'].x "the worker publication is intact"

        # Identity failure modes: mismatch, missing and corrupt.
        $mismatch = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $brokerId -ExpectedPublication ([guid]::NewGuid().ToString()) -TestBaseRoot $base } catch { $mismatch = $true }
        Assert-Equal $true $mismatch "a mismatched identity refuses"
        $missing = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId '1789000000102' -ExpectedPublication $publication -TestBaseRoot $base } catch { $missing = $true }
        Assert-Equal $true $missing "a missing claim refuses"

        $corruptId = '1789000000103'
        $null = New-DevWSTestCapturePublication -OperationId $corruptId -Lines @("slot|1|1|1|1") -TestBaseRoot $base
        Set-Content -LiteralPath (Join-Path (Join-Path (Get-DevWSProtectedCapturesRoot -TestBaseRoot $base) $corruptId) "publication.identity.json") -Value "{corrupt" -NoNewline
        $corrupt = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $corruptId -ExpectedPublication $publication -TestBaseRoot $base } catch { $corrupt = $true }
        Assert-Equal $true $corrupt "a corrupt identity refuses"

        # Reparse objects refuse the publication scope.
        $junctionTarget = Join-Path $TestRoot "p2b-claims-target"
        New-Item -ItemType Directory -Path $junctionTarget -Force | Out-Null
        $junctionPath = Join-Path (Get-DevWSProtectedCapturesRoot -TestBaseRoot $base) '1789000000104'
        $junction = New-Item -ItemType Junction -Path $junctionPath -Target $junctionTarget
        $reparseRefused = $false
        try { $null = Get-DevWSProtectedPublicationScope -ClaimPath $junctionPath } catch { $reparseRefused = $true }
        Assert-Equal $true $reparseRefused "a reparse claim path refuses the scope"
        [System.IO.Directory]::Delete($junction.FullName, $false)
    }

    Test-Case "post-retention ABA replay can never consume a later publication" {
        $base = Join-Path $TestRoot "p2b-aba"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base

        $id = '1789000000201'
        $publicationA = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|10|20|30|40") -SnapshotJson '{"version":1,"terminals":[{"id":"slot","windowId":"W","status":"available","selectedConfiguredTabIndex":1}]}' -TestBaseRoot $base

        # Retention-authentic eviction of A.
        [System.IO.Directory]::SetCreationTimeUtc((Join-Path $capturesRoot $id), [DateTime]::UtcNow.AddMinutes(-120))
        $sweep = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -CurrentOperationId '' -KeepRecent 50 -RetentionMinutes 60
        Assert-Equal $true ($sweep.Removed -contains $id) "the aged publication is evicted"

        $publicationB = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|90|80|70|60") -TestBaseRoot $base
        $aRefused = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publicationA -TestBaseRoot $base } catch { $aRefused = $true }
        Assert-Equal $true $aRefused "A can never consume B's publication"
        Assert-Equal 90 (Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publicationB -TestBaseRoot $base).Geometry['slot'].x "B consumes its own publication"

        # Worker GUID parity.
        $workerId = [guid]::NewGuid().ToString()
        $workerA = New-DevWSTestCapturePublication -OperationId $workerId -Lines @("term|1|1|1|1") -TestBaseRoot $base
        [System.IO.Directory]::SetCreationTimeUtc((Join-Path $capturesRoot $workerId), [DateTime]::UtcNow.AddMinutes(-120))
        $null = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -CurrentOperationId '' -KeepRecent 50 -RetentionMinutes 60
        $workerB = New-DevWSTestCapturePublication -OperationId $workerId -Lines @("term|2|2|2|2") -TestBaseRoot $base
        $workerRefused = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $workerId -ExpectedPublication $workerA -TestBaseRoot $base } catch { $workerRefused = $true }
        Assert-Equal $true $workerRefused "a replayed worker id cannot consume the newer publication"
        Assert-Equal 2 (Read-DevWSProtectedCapturePublication -OperationId $workerId -ExpectedPublication $workerB -TestBaseRoot $base).Geometry['term'].x "the newer worker publication reads own"
    }

    Test-Case "the reader holds one scope through geometry and snapshot consumption" {
        $base = Join-Path $TestRoot "p2b-reader-hold"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base

        $id = '1789000000301'
        $publication = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|5|6|7|8") -SnapshotJson '{"version":1,"terminals":[]}' -TestBaseRoot $base
        $claimPath = Join-Path (Get-DevWSProtectedCapturesRoot -TestBaseRoot $base) $id

        # In-body shadows observe the REAL reader while it runs: the claim must
        # be held (no-delete-share) during BOTH artifact reads. The probe is the
        # production holder-detection primitive; a raw recursive delete is
        # deliberately NOT attempted here (retention never attempts one without
        # a successful probe - proven in the retention case).
        $script:p2bScopeProbe = [pscustomobject]@{ GeometryBlocked = $null; SnapshotBlocked = $null }
        $script:p2bOriginalGeometryRead = (Get-Command -Name Read-DevWSCaptureFile -CommandType Function).ScriptBlock
        $script:p2bOriginalSnapshotRead = (Get-Command -Name Read-DevWSTabSnapshotFile -CommandType Function).ScriptBlock

        function Read-DevWSCaptureFile {
            param([Parameter(Mandatory)][string]$Path)
            $claimDir = Split-Path -Parent $Path
            Initialize-DevWSPrivilegeNativeRuntime
            $probe = [DevWSPrivilegeNative]::OpenClaimDeleteProbe($claimDir)
            $script:p2bScopeProbe.GeometryBlocked = (-not $probe.IsOpen)
            $probe.Dispose()
            return (& $script:p2bOriginalGeometryRead -Path $Path)
        }

        function Read-DevWSTabSnapshotFile {
            param([Parameter(Mandatory)][string]$Path)
            $claimDir = Split-Path -Parent $Path
            Initialize-DevWSPrivilegeNativeRuntime
            $probe = [DevWSPrivilegeNative]::OpenClaimDeleteProbe($claimDir)
            $script:p2bScopeProbe.SnapshotBlocked = (-not $probe.IsOpen)
            $probe.Dispose()
            return (& $script:p2bOriginalSnapshotRead -Path $Path)
        }

        $read = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base
        Assert-Equal 5 $read.Geometry['slot'].x "the geometry is consumed under the held scope"
        Assert-Equal $true $script:p2bScopeProbe.GeometryBlocked "the claim is held while the geometry is consumed"
        Assert-Equal $true $script:p2bScopeProbe.SnapshotBlocked "the claim is held while the snapshot is consumed"
        Assert-Equal $true (Test-Path -LiteralPath (Join-Path $claimPath "capture-elevated.txt")) "the publication survives the consumption"

        # After the reader returns, the claim is releasable.
        $sweep = Invoke-DevWSProtectedCaptureRetention -CapturesRoot (Get-DevWSProtectedCapturesRoot -TestBaseRoot $base) -CurrentOperationId '' -KeepRecent 0 -RetentionMinutes 1
        Assert-Equal $true ($sweep.Removed -contains $id) "the claim is releasable after the reader completes"
    }

    Test-Case "capture retention is bounded and never touches held claims" {
        $base = Join-Path $TestRoot "p2b-retention"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base

        # Held claim: aged and probe-blocked -> skipped with contents intact.
        $current = '1789000000401'
        $claim = New-DevWSProtectedCaptureClaim -OperationId $current -TestBaseRoot $base
        try {
            Set-DevWSProtectedPublicationIdentity -ClaimPath $claim.ClaimPath -Publication ([guid]::NewGuid().ToString())
            [System.IO.File]::WriteAllLines((Join-Path $claim.ClaimPath "capture-elevated.txt"), @("slot|1|1|1|1"), [System.Text.UTF8Encoding]::new($false))
            [System.IO.Directory]::SetCreationTimeUtc($claim.ClaimPath, [DateTime]::UtcNow.AddMinutes(-120))

            $sweep = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -CurrentOperationId '' -KeepRecent 50 -RetentionMinutes 60
            Assert-Equal $true ($sweep.Skipped -contains $current) "a held claim is skipped"
            Assert-Equal $false ($sweep.Removed -contains $current) "a held claim is never removed"
            Assert-Equal $true (Test-Path -LiteralPath (Join-Path $claim.ClaimPath "capture-elevated.txt")) "held contents are never deleted"
        }
        finally {
            $claim.Scope.Dispose()
        }

        $sweep2 = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -CurrentOperationId '' -KeepRecent 50 -RetentionMinutes 60
        Assert-Equal $true ($sweep2.Removed -contains $current) "the released claim is evictable"

        # Rank leg with raw fixture directories: the newest KeepRecent survive.
        $prefix = 1789000000500
        for ($i = 0; $i -lt 10; $i++) {
            $dir = Join-Path $capturesRoot ([string]($prefix + $i))
            New-Item -ItemType Directory -Path $dir -Force | Out-Null
            [System.IO.Directory]::SetCreationTimeUtc($dir, [DateTime]::UtcNow.AddSeconds($i))
        }

        $sweep3 = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -CurrentOperationId '' -KeepRecent 3 -RetentionMinutes 100000
        Assert-Equal 7 $sweep3.Removed.Count "the rank leg removes everything beyond the newest three"
        foreach ($keep in @(8, 9)) {
            Assert-Equal $true (Test-Path -LiteralPath (Join-Path $capturesRoot ([string]($prefix + $keep)))) "the newest claims survive"
        }

        # Capacity: hard-cap refusal instead of deleting active claims.
        $capBase = Join-Path $TestRoot "p2b-capacity"
        New-Item -ItemType Directory -Path $capBase -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $capBase
        for ($i = 0; $i -lt 4; $i++) {
            $capClaim = New-DevWSProtectedCaptureClaim -OperationId ([string](1789000000600 + $i)) -TestBaseRoot $capBase -MaxPublications 4
            $capClaim.Scope.Dispose()
        }
        $refused = $false
        $capacityMessage = ""
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000700' -TestBaseRoot $capBase -MaxPublications 4 } catch { $refused = $true; $capacityMessage = $_.Exception.Message }
        Assert-Equal $true $refused "the hard capacity refuses new claims"
        Assert-Contains $capacityMessage "bounded capacity" "the refusal is actionable"

        # Repeated failed operations stay bounded.
        $growthBase = Join-Path $TestRoot "p2b-growth"
        New-Item -ItemType Directory -Path $growthBase -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $growthBase
        for ($i = 0; $i -lt 30; $i++) {
            $failId = [string]([long](1789000001000 + $i))
            $failClaim = New-DevWSProtectedCaptureClaim -OperationId $failId -TestBaseRoot $growthBase
            $failClaim.Scope.Dispose()
        }
        $growthCount = @(Get-ChildItem -LiteralPath (Get-DevWSProtectedCapturesRoot -TestBaseRoot $growthBase) -Directory).Count
        Assert-True ($growthCount -le 9) "failed operations stay bounded (count=$growthCount)"
    }

    Test-Case "the claim transition is serialized against retention across processes" {
        $base = Join-Path $TestRoot "p2b-lock"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base

        $mutexName = "Local\DevWS.Tests.P2B." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $holderScript = Join-Path $TestRoot "p2b-claim-lock-holder.ps1"
        Set-Content -LiteralPath $holderScript -NoNewline -Value @'
param([string]$MutexName, [string]$ReadyPath, [int]$HoldSeconds)
$mutex = [System.Threading.Mutex]::new($false, $MutexName)
[void]$mutex.WaitOne([TimeSpan]::FromSeconds(10))
Set-Content -LiteralPath $ReadyPath -Value "held" -NoNewline
Start-Sleep -Seconds $HoldSeconds
$mutex.ReleaseMutex()
$mutex.Dispose()
'@

        $ready = Join-Path $TestRoot "p2b-lock-ready.txt"
        Remove-Item -LiteralPath $ready -Force -ErrorAction SilentlyContinue
        $holder = Start-Process -FilePath "pwsh" -ArgumentList @('-NoProfile', '-File', "`"$holderScript`"", '-MutexName', $mutexName, '-ReadyPath', "`"$ready`"", '-HoldSeconds', '8') -PassThru -WindowStyle Hidden

        try {
            $deadline = (Get-Date).AddSeconds(20)
            while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $ready)) { Start-Sleep -Milliseconds 100 }
            Assert-Equal $true (Test-Path -LiteralPath $ready) "the foreign process holds the claim lock"

            $lockTimedOut = $false
            try {
                $null = Invoke-DevWSWithCaptureClaimLock -MutexName $mutexName -TimeoutSeconds 1 -ScriptBlock { "never" }
            }
            catch { $lockTimedOut = $true }
            Assert-Equal $true $lockTimedOut "the claim lock waits fail closed instead of racing a held transition"

            $retentionTimedOut = $false
            try {
                $null = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -LockTimeoutSeconds 1 -MutexName $mutexName
            }
            catch { $retentionTimedOut = $true }
            Assert-Equal $true $retentionTimedOut "retention refuses to run while a transition is held"
        }
        finally {
            if ($null -ne $holder -and -not $holder.HasExited) {
                Assert-True $holder.WaitForExit(20000) "the lock holder exits"
            }
        }

        $free = Invoke-DevWSWithCaptureClaimLock -MutexName $mutexName -TimeoutSeconds 10 -ScriptBlock { "free" }
        Assert-Equal "free" $free "the claim lock is available after the holder exits"
    }

    Test-Case "capture completion correlation is exact and fail-closed" {
        $publication = [guid]::NewGuid().ToString()

        $okOp = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $true; Message = "OK"; Publication = $publication }
        Assert-Equal $publication (Get-DevWSBrokerCapturePublication -Operation $okOp) "a completed broker operation surfaces its identity"

        $brokerCases = @(
            @{ Name = "uncertain"; Op = [pscustomobject]@{ Status = "AcceptedButUncertain"; Ok = $false; Message = ""; Publication = "" }; Needle = "uncertain" },
            @{ Name = "not-accepted"; Op = [pscustomobject]@{ Status = "NotAccepted"; Ok = $false; Message = ""; Publication = "" }; Needle = "did not accept" },
            @{ Name = "failed"; Op = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $false; Message = "capture broke"; Publication = $publication }; Needle = "Elevated capture failed" },
            @{ Name = "identity-missing"; Op = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $true; Message = "OK"; Publication = "" }; Needle = "without a publication identity" }
        )

        foreach ($case in $brokerCases) {
            $refused = $false
            $message = ""
            try { $null = Get-DevWSBrokerCapturePublication -Operation $case.Op } catch { $refused = $true; $message = $_.Exception.Message }
            Assert-Equal $true $refused "broker '$($case.Name)' refuses"
            Assert-Contains $message $case.Needle "broker '$($case.Name)' message"
        }

        $workerId = [guid]::NewGuid().ToString()
        $okResult = [pscustomobject]@{ requestId = $workerId; ok = $true; message = "OK"; data = [pscustomobject]@{ publication = $publication } }
        $correlated = Get-DevWSWorkerCapturePublication -Result $okResult
        Assert-Equal $workerId $correlated.OperationId "the worker operation id is exact"
        Assert-Equal $publication $correlated.Publication "the worker identity is exact"

        $workerCases = @(
            @{ Name = "non-guid-id"; Result = [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK"; data = [pscustomobject]@{ publication = $publication } }; Needle = "canonical worker operation id" },
            @{ Name = "missing-data"; Result = [pscustomobject]@{ requestId = $workerId; ok = $true; message = "OK" }; Needle = "without a publication identity" },
            @{ Name = "missing-identity-field"; Result = [pscustomobject]@{ requestId = $workerId; ok = $true; message = "OK"; data = [pscustomobject]@{} }; Needle = "without a publication identity" }
        )

        foreach ($case in $workerCases) {
            $refused = $false
            $message = ""
            try { $null = Get-DevWSWorkerCapturePublication -Result $case.Result } catch { $refused = $true; $message = $_.Exception.Message }
            Assert-Equal $true $refused "worker '$($case.Name)' refuses"
            Assert-Contains $message $case.Needle "worker '$($case.Name)' message"
        }
    }

    Test-Case "no canonical save follows any publication failure" {
        $base = Join-Path $TestRoot "p2b-no-save"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $marker = Join-Path $TestRoot "p2b-canonical-marker.txt"
        Remove-Item -LiteralPath $marker -Force -ErrorAction SilentlyContinue

        $id = '1789000000801'
        $publication = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|1|2|3|4") -TestBaseRoot $base

        # Failure modes: identity mismatch, missing claim, missing geometry,
        # uncertain and identity-less completions. The marker stands in for the
        # canonical save and must never be written.
        $scenarios = @(
            @{ Name = "identity-mismatch"; Run = { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication ([guid]::NewGuid().ToString()) -TestBaseRoot $base } },
            @{ Name = "missing-claim"; Run = { $null = Read-DevWSProtectedCapturePublication -OperationId '1789000000899' -ExpectedPublication $publication -TestBaseRoot $base } },
            @{ Name = "uncertain-final"; Run = { $null = Get-DevWSBrokerCapturePublication -Operation ([pscustomobject]@{ Status = "AcceptedButUncertain"; Ok = $false; Message = ""; Publication = "" }) } },
            @{ Name = "missing-identity"; Run = { $null = Get-DevWSWorkerCapturePublication -Result ([pscustomobject]@{ requestId = [guid]::NewGuid().ToString(); ok = $true; message = "OK" }) } }
        )

        foreach ($scenario in $scenarios) {
            $refused = $false
            try { & $scenario.Run; Set-Content -LiteralPath $marker -Value "CANONICAL-SAVE" -NoNewline } catch { $refused = $true }
            Assert-Equal $true $refused "$($scenario.Name) refuses"
            Assert-Equal $false (Test-Path -LiteralPath $marker) "$($scenario.Name) never reaches a canonical save"
        }

        # A complete verified publication is the only path that proceeds.
        $verified = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base
        Set-Content -LiteralPath $marker -Value ("CANONICAL-SAVE x=" + $verified.Geometry['slot'].x) -NoNewline
        Assert-Equal "CANONICAL-SAVE x=1" (Get-Content -LiteralPath $marker -Raw) "the verified publication proceeds"
        Remove-Item -LiteralPath $marker -Force -ErrorAction SilentlyContinue
    }

    Test-Case "the full protected chain guards every publication write and read" {
        $base = Join-Path $TestRoot "p2b-chain-guard"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $stateRoot = Get-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $containerPath = Join-Path $base "privileged-state"
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base
        $sidObject = [System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid))

        # Drifted intermediate container (the Base-kind component): the full
        # chain validation must refuse before any file is created.
        $drift = Get-Acl -LiteralPath $containerPath
        $drift.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $containerPath -AclObject $drift

        $refused = $false
        $message = ""
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000951' -TestBaseRoot $base } catch { $refused = $true; $message = $_.Exception.Message }
        Assert-Equal $true $refused "a drifted intermediate ancestor refuses the publication"
        Assert-True (($message -match "write-capable") -or ($message -match "unexpected access rule")) "the refusal names the drifted policy"
        Assert-Equal $false (Test-Path -LiteralPath $capturesRoot) "no captures container is created under a drifted chain"

        Set-Acl -LiteralPath $containerPath -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind Base)

        # Drifted SID root.
        $rootDrift = Get-Acl -LiteralPath $stateRoot
        $rootDrift.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $stateRoot -AclObject $rootDrift

        $refused = $false
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000951' -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "a drifted SID root refuses the publication"
        Assert-Equal $false (Test-Path -LiteralPath $capturesRoot) "no captures container is created under a drifted SID root"

        Set-Acl -LiteralPath $stateRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)

        # The restored chain accepts; a later drift refuses the protected read.
        $id = '1789000000951'
        $publication = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|1|1|1|1") -TestBaseRoot $base

        Set-Acl -LiteralPath $stateRoot -AclObject $rootDrift
        $readRefused = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base } catch { $readRefused = $true }
        Assert-Equal $true $readRefused "a drifted root refuses the protected read"

        Set-Acl -LiteralPath $stateRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)
        Assert-Equal 1 (Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base).Geometry['slot'].x "the restored chain reads again"
    }

    Test-Case "an insecure existing captures container is never adopted" {
        $base = Join-Path $TestRoot "p2b-container-guard"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base
        $sidObject = [System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid))

        # Variant 1: an ordinary directory (inherited DACL, unproven owner).
        New-Item -ItemType Directory -Path $capturesRoot -Force | Out-Null
        $refused = $false
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000961' -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "an ordinary directory is never adopted as the captures container"
        Assert-Equal $true (Test-Path -LiteralPath $capturesRoot) "the insecure container is preserved"
        Assert-Equal $false (Get-Acl -LiteralPath $capturesRoot).AreAccessRulesProtected "the insecure container is never modified"

        # Variant 2: exact policy plus a user-write ACE.
        Set-Acl -LiteralPath $capturesRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)
        $userWrite = Get-Acl -LiteralPath $capturesRoot
        $userWrite.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $capturesRoot -AclObject $userWrite

        $refused = $false
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000961' -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "a user-writable container is refused"
        Assert-Equal $true (Get-Acl -LiteralPath $capturesRoot).AreAccessRulesProtected "the drifted container is never repaired"

        # Variant 3: an unprotected (inherited-access) DACL on the exact policy.
        Set-Acl -LiteralPath $capturesRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)
        $unprotected = Get-Acl -LiteralPath $capturesRoot
        $unprotected.SetAccessRuleProtection($false, $true)
        Set-Acl -LiteralPath $capturesRoot -AclObject $unprotected

        $refused = $false
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000961' -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "an unprotected container is refused"
        Assert-Equal $false (Get-Acl -LiteralPath $capturesRoot).AreAccessRulesProtected "the unprotected container is never repaired"

        # Variant 4: a reparse container.
        [System.IO.Directory]::Delete($capturesRoot, $false)
        $junction = New-Item -ItemType Junction -Path $capturesRoot -Target $TestRoot

        $refused = $false
        try { $null = New-DevWSProtectedCaptureClaim -OperationId '1789000000961' -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "a reparse container is refused"
        [System.IO.Directory]::Delete($junction.FullName, $false)

        # A genuinely valid existing container is reused successfully.
        $security = New-DevWSPrivilegedStateDirectorySecurity -Kind User
        $sddl = $security.GetSecurityDescriptorSddlForm([System.Security.AccessControl.AccessControlSections]::Owner -bor [System.Security.AccessControl.AccessControlSections]::Access)
        $null = New-DevWSProtectedStateExclusiveDirectory -Path $capturesRoot -Sddl $sddl

        $claim = New-DevWSProtectedCaptureClaim -OperationId '1789000000961' -TestBaseRoot $base
        $claim.Scope.Dispose()
        Assert-Equal $true (Test-Path -LiteralPath (Join-Path $capturesRoot '1789000000961')) "a valid existing container is reused"
    }

