    Test-Case "retention skips unexpected reparse candidates" {
        $base = Join-Path $TestRoot "p2b-reparse-retention"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base

        # Ensure the (validated) container exists.
        $null = New-DevWSTestCapturePublication -OperationId '1789000000981' -Lines @("slot|1|1|1|1") -TestBaseRoot $base

        $targetDir = Join-Path $TestRoot "p2b-reparse-target"
        New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $targetDir "sentinel.txt") -Value "sentinel" -NoNewline

        $candidateId = '1789000000982'
        $junction = New-Item -ItemType Junction -Path (Join-Path $capturesRoot $candidateId) -Target $targetDir
        [System.IO.Directory]::SetCreationTimeUtc((Join-Path $capturesRoot $candidateId), [DateTime]::UtcNow.AddMinutes(-120))

        $sweep = Invoke-DevWSProtectedCaptureRetention -CapturesRoot $capturesRoot -CurrentOperationId '' -KeepRecent 50 -RetentionMinutes 60
        Assert-Equal $true ($sweep.Skipped -contains $candidateId) "a reparse candidate is skipped"
        Assert-Equal $false ($sweep.Removed -contains $candidateId) "a reparse candidate is never recursively removed"
        Assert-Equal $true (Test-Path -LiteralPath (Join-Path $capturesRoot $candidateId)) "the reparse candidate is preserved"
        Assert-Equal $true (Test-Path -LiteralPath (Join-Path $targetDir "sentinel.txt")) "the reparse target is untouched"

        [System.IO.Directory]::Delete($junction.FullName, $false)
    }

    Test-Case "operation ids are domain-exact and case-sensitive" {
