        Assert-True ($start -ge 0) "the save function is located"
        $end = $stateSource.IndexOf("`nfunction ", $start + 1)
        if ($end -lt 0) { $end = $stateSource.Length }
        $saveBody = $stateSource.Substring($start, $end - $start)
        Assert-Contains $saveBody "Assert-DevWSProtectedStateWritable" "installed saves validate the full protected chain"
        Assert-Contains $saveBody "Refusing a runtime-cache write through an unexpected filesystem object" "unexpected objects at the temp/destination are refused"

        # Behavioral (repository layout): a reparse destination refuses the
        # write and never follows the link; the normal protected save works.
        $fixturePath = Get-DevWSProtectedRuntimeStatePath
        $decoy = Join-Path $TestRoot "p2b-save-decoy.json"
        Set-Content -LiteralPath $decoy -Value "{}" -NoNewline
        if (Test-Path -LiteralPath $fixturePath) { Remove-Item -LiteralPath $fixturePath -Force }

        $link = New-Item -ItemType SymbolicLink -Path $fixturePath -Target $decoy
        $refused = $false
        try { Save-DevWSRuntimeState -State (New-DevWSRuntimeState) -Path $fixturePath } catch { $refused = $true }
        Assert-Equal $true $refused "a reparse destination refuses the save"
        Assert-Equal "{}" (Get-Content -LiteralPath $decoy -Raw) "the reparse target is untouched"
        [System.IO.File]::Delete($link.FullName)

        Save-DevWSRuntimeState -State (New-DevWSRuntimeState) -Path $fixturePath
        Assert-Equal $true (Test-Path -LiteralPath $fixturePath) "the normal protected save succeeds"
        Remove-Item -LiteralPath $fixturePath -Force -ErrorAction SilentlyContinue
    }

    Test-Case "a drifted captures parent refuses existing publications" {
        $base = Join-Path $TestRoot "p2b-parent-guard"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base
        $capturesRoot = Get-DevWSProtectedCapturesRoot -TestBaseRoot $base
        $sidObject = [System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid))

        $id = '1789000000991'
        $publication = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|1|1|1|1") -TestBaseRoot $base
        Assert-Equal 1 (Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base).Geometry['slot'].x "the baseline read succeeds"

        # Variant 1: user-write ACE on the parent.
        $drift = Get-Acl -LiteralPath $capturesRoot
        $drift.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "Write", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $capturesRoot -AclObject $drift

        $refused = $false
        $message = ""
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base } catch { $refused = $true; $message = $_.Exception.Message }
        Assert-Equal $true $refused "a user-writable captures parent refuses the publication"
        Assert-True (($message -match "write-capable") -or ($message -match "unexpected access rule")) "the parent refusal names the drift"
        Assert-Equal $true (Test-Path -LiteralPath (Join-Path $capturesRoot $id)) "the drifted parent and its claim are preserved"

        $stillDrifted = @((Get-Acl -LiteralPath $capturesRoot).Access | Where-Object { (-not $_.IsInherited) -and (($_.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::Write) -ne 0) })
        Assert-True ($stillDrifted.Count -ge 1) "the drifted parent is never repaired"

        Set-Acl -LiteralPath $capturesRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)
        Assert-Equal 1 (Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base).Geometry['slot'].x "the restored parent reads successfully"

        # Variant 2: delete-child grant on the parent.
        $deleteChild = Get-Acl -LiteralPath $capturesRoot
        $deleteChild.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, "DeleteSubdirectoriesAndFiles", "ContainerInherit, ObjectInherit", "None", "Allow")))
        Set-Acl -LiteralPath $capturesRoot -AclObject $deleteChild

        $refused = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "a delete-child grant on the parent refuses the publication"
        Set-Acl -LiteralPath $capturesRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)

        # Variant 3: wrong owner.
        $ownerDrift = Get-Acl -LiteralPath $capturesRoot
        $ownerDrift.SetOwner($sidObject)
        Set-Acl -LiteralPath $capturesRoot -AclObject $ownerDrift

        $refused = $false
        $message = ""
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base } catch { $refused = $true; $message = $_.Exception.Message }
        Assert-Equal $true $refused "a wrong-owner parent refuses the publication"
        Assert-Contains $message "owned by" "the owner refusal is explicit"
        Set-Acl -LiteralPath $capturesRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)

        # Variant 4: unprotected (inherited-access) DACL.
        $unprotected = Get-Acl -LiteralPath $capturesRoot
        $unprotected.SetAccessRuleProtection($false, $true)
        Set-Acl -LiteralPath $capturesRoot -AclObject $unprotected

        $refused = $false
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base } catch { $refused = $true }
        Assert-Equal $true $refused "an unprotected parent refuses the publication"
        Set-Acl -LiteralPath $capturesRoot -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind User)

        # Variant 5: unexpected reparse (the whole parent moved and linked).
        $reparseTarget = Join-Path $TestRoot "p2b-parent-reparse-target"
        if (Test-Path -LiteralPath $reparseTarget) { Remove-Item -LiteralPath $reparseTarget -Recurse -Force }
        Move-Item -LiteralPath $capturesRoot -Destination $reparseTarget
        $junction = New-Item -ItemType Junction -Path $capturesRoot -Target $reparseTarget

        $refused = $false
        $message = ""
        try { $null = Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base } catch { $refused = $true; $message = $_.Exception.Message }
        Assert-Equal $true $refused "a reparse parent refuses the publication"
        Assert-Contains $message "reparse point" "the reparse refusal is explicit"
        Assert-Equal $true (Test-Path -LiteralPath (Join-Path $reparseTarget $id)) "the claim survives inside the moved parent"

        [System.IO.Directory]::Delete($junction.FullName, $false)
        Move-Item -LiteralPath $reparseTarget -Destination $capturesRoot
        Assert-Equal 1 (Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base).Geometry['slot'].x "the fully restored parent reads successfully"
    }

    Test-Case "an exception inside claim validation releases the native handle promptly" {
        $base = Join-Path $TestRoot "p2b-lifetime-exception"
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base

        $id = '1789000000992'
        $publication = New-DevWSTestCapturePublication -OperationId $id -Lines @("slot|1|1|1|1") -TestBaseRoot $base
        $claimPath = Join-Path (Get-DevWSProtectedCapturesRoot -TestBaseRoot $base) $id

        # Baseline read proves the claim is valid before the injection.
        Assert-Equal 1 (Read-DevWSProtectedCapturePublication -OperationId $id -ExpectedPublication $publication -TestBaseRoot $base).Geometry['slot'].x "the baseline read succeeds"

        # Inject a THROWING semantic validator: the scope must release its
        # native handle in its finally block - not via garbage collection.
        $script:p2bLifetimeOriginal = (Get-Command -Name Test-DevWSPrivilegedStateSecurity -CommandType Function).ScriptBlock

        function Test-DevWSPrivilegedStateSecurity {
            param($Security, $Kind, $UserSid = "")
            throw "injected-semantic-validation-failure"
        }

        $process = [System.Diagnostics.Process]::GetCurrentProcess()
        $handleBefore = $process.HandleCount

        for ($i = 0; $i -lt 20; $i++) {
            $threw = $false
            try { $null = Get-DevWSProtectedPublicationScope -ClaimPath $claimPath } catch { $threw = $true }
            Assert-Equal $true $threw "the injected validation failure surfaces (iteration $i)"
        }

        Start-Sleep -Milliseconds 300
        $handleAfter = $process.HandleCount
        Assert-True (($handleAfter - $handleBefore) -le 10) "the exceptional path leaks no handles (delta $($handleAfter - $handleBefore))"

        # The claim is immediately deletable: no no-delete-share hold remains.
        Initialize-DevWSPrivilegeNativeRuntime
        $probe = [DevWSPrivilegeNative]::OpenClaimDeleteProbe($claimPath)
        Assert-Equal $true $probe.IsOpen "the native handle is released promptly on the exceptional path"
        $probe.Dispose()

        Remove-Item -LiteralPath $claimPath -Recurse -Force
        Assert-Equal $false (Test-Path -LiteralPath $claimPath) "the released claim is deletable without waiting for collection"
    }

    Test-Case "phase 2-B native, installer and capture wiring contracts" {
        $installLib = Get-SourceOf "src\lib\devws-install.ps1"
        Assert-Contains $installLib "OpenClaimDeleteProbe" "the DLL contract requires the delete probe"

        $pathsLib = Get-SourceOf "src\lib\devws-paths.ps1"
        foreach ($fn in @(
            "Get-DevWSProtectedRuntimeStatePath",
            "Assert-DevWSProtectedOperationId",
            "Get-DevWSProtectedCapturesRoot",
            "Get-DevWSProtectedCaptureClaimPath",
            "Get-DevWSProtectedPublicationScope",
            "Set-DevWSProtectedPublicationIdentity",
            "Get-DevWSProtectedPublicationIdentity",
            "New-DevWSProtectedCaptureClaim",
            "Invoke-DevWSProtectedCaptureRetention",
            "Invoke-DevWSWithCaptureClaimLock",
            "Assert-DevWSRuntimeStatePathAllowed"
        )) {
            Assert-Contains $pathsLib ("function " + $fn) "paths exposes $fn"
        }

        $ws = Get-SourceOf "src\ws.ps1"
        Assert-Contains $ws "New-DevWSCaptureRequestId" "capture uses the capture-specific id generator"
        Assert-Contains $ws "Read-DevWSProtectedCapturePublication" "capture reads through the protected publication"
        Assert-NotContains $ws "capture-elevated.txt" "no unprotected elevated capture pathname remains in the orchestration"

        $launchLib = Get-SourceOf "src\lib\devws-launch.ps1"
        Assert-Contains $launchLib "function New-DevWSLaunchRequestId" "the launch id generator is preserved"
        Assert-Contains $launchLib "function New-DevWSCaptureRequestId" "the capture id generator exists"

        $brokerSource = Get-SourceOf "src\workers\elevated-broker.ps1"
        Assert-Contains $brokerSource "New-DevWSProtectedCaptureClaim" "the broker claims protected publications"
        Assert-Contains $brokerSource "finalPayload[`"publication`"]" "the broker FINAL carries the publication identity"

        $protocol = Get-SourceOf "src\lib\devws-broker-protocol.ps1"
        Assert-Contains $protocol 'Publication = [string]$final.publication' "the client surfaces the FINAL identity"
        Assert-Equal 1 (Get-DevWSBrokerProtocolVersion) "broker protocol version stays 1"

        $operations = Get-SourceOf "src\lib\devws-terminal-operations.ps1"
        Assert-Contains $operations "ClaimPath" "the capture core writes into the claimed directory"
        Assert-Contains $operations 'Join-Path $ClaimPath "capture-elevated.txt"' "the capture core derives claim-scoped geometry"
        Assert-Contains $operations 'Join-Path $ClaimPath "capture-elevated.snapshots.json"' "the capture core derives the claim-scoped sidecar"

        $captureLib = Get-SourceOf "src\lib\devws-capture.ps1"
        Assert-Contains $captureLib "The protected captures parent refused the publication read" "the reader validates the captures parent semantically"

        $scopeStart = $pathsLib.IndexOf("function Get-DevWSProtectedPublicationScope {")
        Assert-True ($scopeStart -ge 0) "the publication scope is located"
        $scopeEnd = $pathsLib.IndexOf("`nfunction ", $scopeStart + 1)
        if ($scopeEnd -lt 0) { $scopeEnd = $pathsLib.Length }
        $scopeBody = $pathsLib.Substring($scopeStart, $scopeEnd - $scopeStart)
        Assert-Contains $scopeBody "if (-not `$transferred)" "the scope disposes on every unsuccessful exit through a finally"
        $transferIndex = $scopeBody.IndexOf("`$transferred = `$true")
        $finallyIndex = $scopeBody.IndexOf("finally {")
        Assert-True (($transferIndex -ge 0) -and ($finallyIndex -ge 0) -and ($transferIndex -lt $finallyIndex)) "ownership transfers only on the successful exit"
    }

    Start-TestGroup -Name 'protected-cwd' -Title 'Protected cwd authority (Security Phase 2-C)'

    # Protected fixtures must live under a SHORT base: the accepted support
    # contract bounds the protected SID root at 117 characters, and the
    # standard deep test root cannot host a valid protected chain. A user
    # profile (%TEMP%) is NOT a portable length across Windows hosts, so the
    # base is a unique disposable directory at the root of the system volume.
    # That makes the exact-root-length cases a function of the product's
    # pathname contract rather than of the length of the current Windows
    # username. The GUID suffix keeps concurrent suite invocations from
    # colliding, and the suite's finally block removes exactly this directory.
    $script:P2CCwdFixtureRoot = $null

    function Get-P2CCwdFixtureRoot {
        if (-not [string]::IsNullOrWhiteSpace($script:P2CCwdFixtureRoot)) { return $script:P2CCwdFixtureRoot }

        $systemDrive = [string]$env:SystemDrive

        if ([string]::IsNullOrWhiteSpace($systemDrive) -or -not [System.IO.Path]::IsPathRooted($systemDrive)) {
            throw "the protected-cwd fixture base requires a rooted system volume; SystemDrive is '$systemDrive'"
        }

        $root = $systemDrive.TrimEnd('\') + '\dwp2c-' + [guid]::NewGuid().ToString('N').Substring(0, 8)

        try {
            New-Item -ItemType Directory -Path $root -Force -ErrorAction Stop | Out-Null
        }
        catch {
            throw ("the protected-cwd fixture base '{0}' could not be created ({1}); these fixtures require an elevated test process and a writable system-volume root" -f $root, $_.Exception.Message)
        }

        $script:P2CCwdFixtureRoot = $root
        return $root
    }

    function New-P2CCwdFixture {
        param(
            [Parameter(Mandatory)][string]$Name,
            [int]$ExactRootLength = 0
        )

        if ($Name.Length -gt 11) { throw "protected fixture name '$Name' is too long for the 117-character root contract" }

        $base = Join-Path (Get-P2CCwdFixtureRoot) $Name
        $sidLength = (Get-DevWSCurrentUserSid).Length
        $pad = 0

        if ($ExactRootLength -gt 0) {
            $pad = $ExactRootLength - (18 + $sidLength) - $base.Length - 1

            if ($pad -lt 1) {
                throw "fixture base path '$base' is too long for an exact root length of $ExactRootLength (18 + SID $sidLength leaves no padding for $($base.Length) base characters)"
            }
        }
        else {
            # Fail actionably instead of silently weakening the 117-character
            # boundary assertions when a host cannot provide a short enough base.
            $rootLength = $base.Length + 18 + $sidLength

            if ($rootLength -gt 117) {
                throw "the protected-cwd fixture base '$base' produces a $rootLength-character protected SID root; the production contract supports at most 117"
            }
        }

        New-Item -ItemType Directory -Path $base -Force | Out-Null

        if ($ExactRootLength -gt 0) {
            $base = Join-Path $base ('r' * $pad)
            New-Item -ItemType Directory -Path $base -Force | Out-Null
        }

        $null = Initialize-DevWSPrivilegedStateRoot -TestBaseRoot $base

        return [pscustomobject]@{
            Base    = $base
            SidRoot = (Get-DevWSPrivilegedStateRoot -TestBaseRoot $base)
        }
    }

    function New-P2CCwdPair {
        # A genuine High-authored protected pair whose publisher identity is the
        # live test process itself (deterministic liveness).
        param(
            [Parameter(Mandatory)]$Fixture,
            [string]$SetId = 'main',
            [string]$TerminalId = 'slot',
            [int]$TabIndex = 0
        )

        $tracking = New-DevWSCwdTrackingSession -SetId $SetId -TerminalId $TerminalId -WindowId ("DevWS-" + $TerminalId) -TabIndex $TabIndex -TestBaseRoot $Fixture.Base
        $publication = [ordered]@{
            version           = 1
            setId             = $SetId
            terminalId        = $TerminalId
            windowId          = "DevWS-" + $TerminalId
            sessionId         = $tracking.SessionId
            cwd               = $TestRoot
            startupState      = 'idle'
            shellPid          = $PID
            shellStartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString('o')
            updatedAtUtc      = (Get-Date).ToUniversalTime().ToString('o')
        }

        if ($TabIndex -gt 0) { $publication.tabIndex = $TabIndex }

        Write-DevWSCwdPublication -Path $tracking.PublicationPath -Record $publication
        return $tracking
    }

    function Add-P2CCwdDriftAce {
        param([string]$Path, [string]$Rights)

        $sidObject = [System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid))
        $acl = Get-Acl -LiteralPath $Path
        $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidObject, $Rights, 'ContainerInherit, ObjectInherit', 'None', 'Allow')))
        Set-Acl -LiteralPath $Path -AclObject $acl
    }

    function Invoke-P2CCwdDrift {
        param([string]$Path, [string]$Class)

        switch ($Class) {
            'user-write'   { Add-P2CCwdDriftAce -Path $Path -Rights 'Write' }
            'delete-child' { Add-P2CCwdDriftAce -Path $Path -Rights 'DeleteSubdirectoriesAndFiles' }
            'wrong-owner'  { $acl = Get-Acl -LiteralPath $Path; $acl.SetOwner([System.Security.Principal.SecurityIdentifier]::new((Get-DevWSCurrentUserSid))); Set-Acl -LiteralPath $Path -AclObject $acl }
            'unprotected'  { $acl = Get-Acl -LiteralPath $Path; $acl.SetAccessRuleProtection($false, $true); Set-Acl -LiteralPath $Path -AclObject $acl }
            'reparse'      { Move-Item -LiteralPath $Path -Destination ($Path + '.bak'); $null = New-Item -ItemType Junction -Path $Path -Target ($Path + '.bak') }
            default        { throw "unknown drift class '$Class'" }
        }
    }

    function Restore-P2CCwdDrift {
        param([string]$Path, [string]$Class, [ValidateSet('Base', 'User')][string]$Kind = 'User')

        if ($Class -eq 'reparse') {
            [System.IO.Directory]::Delete($Path, $false)
            Move-Item -LiteralPath ($Path + '.bak') -Destination $Path
        }
        else {
            Set-Acl -LiteralPath $Path -AclObject (New-DevWSPrivilegedStateDirectorySecurity -Kind $Kind)
        }
    }

    Test-Case "protected cwd key mapping is bounded, deterministic and injection-safe" {
        $katIds = @('main', 'MAIN', 'Main', '.', '..', 'CON', 'con', 'CON.txt', 'NUL', 'COM1', 'LPT9', 'slot.', 'slot')

        foreach ($id in $katIds) {
            $key = ConvertTo-DevWSCwdProtectedKey -Id $id
            Assert-True ($key -cmatch '^[a-z0-9_~\-]{1,33}$') "key for '$id' satisfies the safe component grammar"
            Assert-True (-not $key.Contains('.')) "key for '$id' contains no dot"
            Assert-True (-not ($key -cmatch '^(con|prn|aux|nul|com[1-9]|lpt[1-9])$')) "key for '$id' can never be a reserved device name"
        }

        $keyMain = ConvertTo-DevWSCwdProtectedKey -Id 'main'
        Assert-Equal $keyMain (ConvertTo-DevWSCwdProtectedKey -Id 'MAIN') "case variants map to one key"
        Assert-Equal $keyMain (ConvertTo-DevWSCwdProtectedKey -Id 'Main') "mixed case maps to one key"
        Assert-Equal (ConvertTo-DevWSCwdProtectedKey -Id 'CON') (ConvertTo-DevWSCwdProtectedKey -Id 'con') "device-name case variants map to one key"
        Assert-True ((ConvertTo-DevWSCwdProtectedKey -Id 'slot.') -ne (ConvertTo-DevWSCwdProtectedKey -Id 'slot')) "trailing dot is a distinct identity"
        Assert-True ((ConvertTo-DevWSCwdProtectedKey -Id '.') -ne (ConvertTo-DevWSCwdProtectedKey -Id '..')) "dot and dotdot are distinct"
        Assert-True ((ConvertTo-DevWSCwdProtectedKey -Id '..') -cmatch '^~2e~2e-') "dotdot is escaped, never traversal"
        Assert-True ((ConvertTo-DevWSCwdProtectedKey -Id 'CON.txt') -cmatch '^con~2etx?') "the dot is escaped as ~2e"

        # Fuzz: pattern, bound, case-fold and uniqueness over the grammar.
        $alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-'
        $rng = [System.Random]::new(20261015)
        $seen = @{}
        $problems = 0

        for ($i = 0; $i -lt 2000; $i++) {
            $length = $rng.Next(1, 60)
            $sb = [System.Text.StringBuilder]::new()

            for ($j = 0; $j -lt $length; $j++) { [void]$sb.Append($alphabet[$rng.Next($alphabet.Length)]) }

            $id = $sb.ToString()
            $key = ConvertTo-DevWSCwdProtectedKey -Id $id
            $lower = $id.ToLowerInvariant()

            if (-not ($key -cmatch '^[a-z0-9_~\-]{1,33}$')) { $problems++; continue }
            if ($key.Contains('.')) { $problems++; continue }
            if ((ConvertTo-DevWSCwdProtectedKey -Id $id.ToUpperInvariant()) -ne $key) { $problems++; continue }

            if (-not $seen.ContainsKey($lower)) { $seen[$lower] = $key }
            elseif ($seen[$lower] -ne $key) { $problems++ }
        }

        Assert-Equal 0 $problems "no fuzz input violates the mapping invariants"
        Assert-True ($seen.Count -gt 1900) "the fuzz corpus produced distinct mapped identities"

        $longKey = ConvertTo-DevWSCwdProtectedKey -Id ('a' * 4000)
        $dotKey  = ConvertTo-DevWSCwdProtectedKey -Id ('.' * 4000)
        Assert-Equal 33 $longKey.Length "very long IDs map to the 33-character bound"
        Assert-True ($dotKey.Length -le 33) "all-dot IDs stay inside the 33-character bound (unit-boundary truncation)"
        Assert-Throws { ConvertTo-DevWSCwdProtectedKey -Id 'a/b' } "not a canonical stable identifier"
        Assert-Throws { ConvertTo-DevWSCwdProtectedKey -Id 'a b' } "not a canonical stable identifier"
    }

    Test-Case "protected cwd path shapes and the accepted budget contract" {
        $fixture = New-P2CCwdFixture -Name "shape"
        $surfaces = Get-DevWSCwdProtectedPath -SidRoot $fixture.SidRoot -Kind 'sessions' -SetId 'main' -TerminalId 'slot' -TabIndex 0
        $indexed  = Get-DevWSCwdProtectedPath -SidRoot $fixture.SidRoot -Kind 'sessions' -SetId 'main' -TerminalId 'slot' -TabIndex 3
        $setKey   = ConvertTo-DevWSCwdProtectedKey -Id 'main'
        $termKey  = ConvertTo-DevWSCwdProtectedKey -Id 'slot'

        Assert-Equal (Join-Path (Join-Path (Join-Path $fixture.SidRoot 'cwd\sessions') $setKey) ($termKey + '.json')) $surfaces "tab 0 keeps the terminal-level file shape"
        Assert-Equal (Join-Path (Join-Path (Join-Path (Join-Path $fixture.SidRoot 'cwd\sessions') $setKey) $termKey) '3.json') $indexed "indexed tabs keep the terminal-directory shape"
        Assert-Equal $surfaces (Get-DevWSCwdSessionPath -SetId 'main' -TerminalId 'slot' -TestBaseRoot $fixture.Base) "the routed session path is the protected path"
        Assert-Equal $indexed (Get-DevWSCwdSessionPath -SetId 'main' -TerminalId 'slot' -TabIndex 3 -TestBaseRoot $fixture.Base) "the routed indexed path is the protected path"

        $budgets = Get-DevWSCwdProtectedBudgets
        Assert-Equal 117 $budgets.MaxRootLength "supported root maximum"
        Assert-Equal 138 $budgets.MaxRelativePathLength "longest transient relative path"
        Assert-Equal 255 $budgets.MaxPathLength "absolute path maximum"
        Assert-Equal 33 $budgets.MaxKeyLength "key maximum"
        $maxTempName = '.cwd-' + ([int]::MaxValue).ToString() + '-' + ('f' * 32) + '.tmp'
        Assert-Equal 52 $maxTempName.Length "the maximum temporary filename is 52 characters"

        $root117 = New-P2CCwdFixture -Name "b117" -ExactRootLength 117
        $root118 = New-P2CCwdFixture -Name "b118" -ExactRootLength 118
        Assert-Equal 117 $root117.SidRoot.Length "the max fixture root is exactly 117"
        Assert-Equal 118 $root118.SidRoot.Length "the over fixture root is exactly 118"

        $budgetOk = Test-DevWSCwdProtectedPathBudget -SidRoot $root117.SidRoot
        Assert-Equal $true ([bool]$budgetOk.Ok) "117 is inside the supported envelope"
        Assert-Equal 255 ([int]$budgetOk.LongestPathLength) "the longest transient path at 117 is exactly 255"

        $budgetOver = Test-DevWSCwdProtectedPathBudget -SidRoot $root118.SidRoot
        Assert-Equal $false ([bool]$budgetOver.Ok) "118 is outside the supported envelope"
        Assert-Equal 'protected-root-budget' ([string]$budgetOver.Reason) "the refusal reason is explicit"

        $threw = $false
        $message = ''
        try { $null = Assert-DevWSCwdProtectedPathBudget -SidRoot $root118.SidRoot -Operation 'test' } catch { $threw = $true; $message = $_.Exception.Message }
        Assert-Equal $true $threw "the writer guard refuses the over-budget root"
        Assert-Contains $message "supported maximum is 117" "the refusal is actionable"
        Assert-Equal $false (Test-Path -LiteralPath (Join-Path $root118.SidRoot 'cwd')) "the over-budget refusal creates no descendant"

        $deepest = Join-Path $root117.SidRoot ('cwd\publications\' + ('a' * 8 + '-' + 'b' * 24) + '\' + ('c' * 8 + '-' + 'd' * 24) + '\' + '2147483647.json')
        $deepestTemp = Join-Path (Split-Path -Parent $deepest) $maxTempName
        Assert-Equal 255 $deepestTemp.Length "the deepest temporary path reaches exactly 255"
        Assert-Equal $true (Test-DevWSCwdProtectedContainment -SidRoot $root117.SidRoot -Path $deepestTemp) "the deepest temporary path is contained"
        Assert-Equal $false (Test-DevWSCwdProtectedContainment -SidRoot $root117.SidRoot -Path $root117.SidRoot) "the root itself is not a contained leaf"
    }

    Test-Case "protected cwd writer creates and validates the complete addressed chain" {
        $fixture = New-P2CCwdFixture -Name "writer"
        $legacyState = Join-Path $TestRoot "p2c-writer-legacy-state"
        New-Item -ItemType Directory -Path $legacyState -Force | Out-Null

        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $legacyState

            $tab0 = New-DevWSCwdTrackingSession -SetId 'main' -TerminalId 'slot' -WindowId 'DevWS-slot' -TabIndex 0 -TestBaseRoot $fixture.Base
            $tab1 = New-DevWSCwdTrackingSession -SetId 'main' -TerminalId 'slot' -WindowId 'DevWS-slot' -TabIndex 1 -StartupSpecSha256 ('AB' * 32) -TestBaseRoot $fixture.Base

            foreach ($component in @(
                (Join-Path $fixture.SidRoot 'cwd'),
                (Join-Path $fixture.SidRoot 'cwd\sessions'),
                (Join-Path $fixture.SidRoot 'cwd\publications'),
                (Join-Path $fixture.SidRoot ('cwd\sessions\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main'))),
                (Join-Path $fixture.SidRoot ('cwd\sessions\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main') + '\' + (ConvertTo-DevWSCwdProtectedKey -Id 'slot'))),
                (Join-Path $fixture.SidRoot ('cwd\publications\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main')))
            )) {
                $validation = Test-DevWSProtectedStateComponent -Component $component -Kind User
                Assert-Equal $true ([bool]$validation.Ok) "created component '$component' satisfies the Kind User policy"
            }

            $record = Read-DevWSCwdSessionRecord -Path $tab0.SessionPath
            Assert-Equal 1 ([int]$record.version) "expected record version 1"
            Assert-Equal 'main' ([string]$record.setId) "record setId"
            Assert-Equal 'slot' ([string]$record.terminalId) "record terminalId"
            Assert-Equal $tab0.SessionId ([string]$record.sessionId) "record sessionId"
            Assert-Equal $null $record.PSObject.Properties['tabIndex'] "tab 0 carries no tabIndex"

            $indexedRecord = Read-DevWSCwdSessionRecord -Path $tab1.SessionPath
            Assert-Equal 1 ([int]$indexedRecord.tabIndex) "indexed record carries its tabIndex"
            Assert-Equal ('AB' * 32) ([string]$indexedRecord.startupSpecSha256) "indexed record carries the startup fingerprint"

            $tempResidue = @(Get-ChildItem -LiteralPath $fixture.SidRoot -Recurse -File -Filter '*.tmp' -ErrorAction SilentlyContinue)
            Assert-Equal 0 $tempResidue.Count "no atomic temp residue remains"

            $legacyEntries = @(Get-ChildItem -LiteralPath $legacyState -Recurse -Force -ErrorAction SilentlyContinue)
            Assert-Equal 0 $legacyEntries.Count "the protected writer leaves the legacy user state untouched"

            $cwdLib = Get-SourceOf "src\lib\devws-cwd.ps1"
            Assert-Contains $cwdLib "New-DevWSProtectedStateExclusiveDirectory" "protected descendants are created through the exclusive primitive"
            Assert-Contains $cwdLib "Assert-DevWSProtectedStateWritable" "the full P2-A root contract precedes protected writes"
            Assert-NotContains $cwdLib ".Substring(0, 24)" "the key encoder is not duplicated in the cwd library"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "protected cwd descendant drift refuses readers and writers" {
        $fixture = New-P2CCwdFixture -Name "drift"
        $pair0 = New-P2CCwdPair -Fixture $fixture -TerminalId 'drift0' -TabIndex 0
        $pair1 = New-P2CCwdPair -Fixture $fixture -TerminalId 'drift1' -TabIndex 1

        $levels = @(
            @{ Name = 'cwd';                       Kind = 'sessions';     TerminalId = 'drift0'; TabIndex = 0; Path = (Join-Path $fixture.SidRoot 'cwd'); Leaf = $pair0.SessionPath },
            @{ Name = 'sessions';                  Kind = 'sessions';     TerminalId = 'drift0'; TabIndex = 0; Path = (Join-Path $fixture.SidRoot 'cwd\sessions'); Leaf = $pair0.SessionPath },
            @{ Name = 'publications';              Kind = 'publications'; TerminalId = 'drift0'; TabIndex = 0; Path = (Join-Path $fixture.SidRoot 'cwd\publications'); Leaf = $pair0.PublicationPath },
            @{ Name = 'set-dir-sessions';          Kind = 'sessions';     TerminalId = 'drift0'; TabIndex = 0; Path = (Join-Path $fixture.SidRoot ('cwd\sessions\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main'))); Leaf = $pair0.SessionPath },
            @{ Name = 'set-dir-publications';      Kind = 'publications'; TerminalId = 'drift0'; TabIndex = 0; Path = (Join-Path $fixture.SidRoot ('cwd\publications\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main'))); Leaf = $pair0.PublicationPath },
            @{ Name = 'terminal-dir-sessions';     Kind = 'sessions';     TerminalId = 'drift1'; TabIndex = 1; Path = (Join-Path $fixture.SidRoot ('cwd\sessions\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main') + '\' + (ConvertTo-DevWSCwdProtectedKey -Id 'drift1'))); Leaf = $pair1.SessionPath },
            @{ Name = 'terminal-dir-publications'; Kind = 'publications'; TerminalId = 'drift1'; TabIndex = 1; Path = (Join-Path $fixture.SidRoot ('cwd\publications\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main') + '\' + (ConvertTo-DevWSCwdProtectedKey -Id 'drift1'))); Leaf = $pair1.PublicationPath }
        )

        $classes = @('user-write', 'delete-child', 'wrong-owner', 'unprotected', 'reparse')
        $failed = [System.Collections.Generic.List[string]]::new()

        foreach ($level in $levels) {
            foreach ($class in $classes) {
                $label = "$($level.Name)|$class"
                $leafBefore = (Get-FileHash -LiteralPath $level.Leaf -Algorithm SHA256).Hash

                Invoke-P2CCwdDrift -Path $level.Path -Class $class

                $reader = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId $level.TerminalId -TabIndex $level.TabIndex -TestBaseRoot $fixture.Base
                $readerRefused = ([string]$reader.Status -eq 'unavailable') -and ([string]$reader.Reason -cmatch '^protected-')

                $writerRefused = $false
                try { $null = New-DevWSCwdTrackingSession -SetId 'main' -TerminalId $level.TerminalId -WindowId ('DevWS-' + $level.TerminalId) -TabIndex $level.TabIndex -TestBaseRoot $fixture.Base } catch { $writerRefused = $true }

                $leafAfter = (Get-FileHash -LiteralPath $level.Leaf -Algorithm SHA256).Hash
                $leafUntouched = ($leafBefore -eq $leafAfter)

                Restore-P2CCwdDrift -Path $level.Path -Class $class

                $reader = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId $level.TerminalId -TabIndex $level.TabIndex -TestBaseRoot $fixture.Base
                $restoredAvailable = ([string]$reader.Status -eq 'available')

                if (-not ($readerRefused -and $writerRefused -and $leafUntouched -and $restoredAvailable)) {
                    $failed.Add($label) | Out-Null
                }
            }
        }

        Assert-Equal 0 $failed.Count ("every descendant drift refuses fail-closed and restores (" + ($failed -join ', ') + ")")
    }

    Test-Case "protected cwd read authority requires the complete root trust" {
        $fixture = New-P2CCwdFixture -Name "roottrust"
        $pair = New-P2CCwdPair -Fixture $fixture -TerminalId 'rt' -TabIndex 0
        $setDir = Join-Path $fixture.SidRoot ('cwd\sessions\' + (ConvertTo-DevWSCwdProtectedKey -Id 'main'))

        $descendantValid = Test-DevWSProtectedStateComponent -Component $setDir -Kind User
        Assert-Equal $true ([bool]$descendantValid.Ok) "the descendant chain is valid before any root drift"

        $baseline = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'rt' -TabIndex 0 -TestBaseRoot $fixture.Base
        Assert-Equal 'available' ([string]$baseline.Status) "the baseline protected pair resolves"

        $targets = @(
            @{ Name = 'privileged-state'; Path = (Join-Path $fixture.Base 'privileged-state'); Kind = 'Base' },
            @{ Name = 'sid-root';         Path = $fixture.SidRoot;                             Kind = 'User' }
        )
        $classes = @('user-write', 'delete-child', 'wrong-owner', 'unprotected', 'reparse')
        $failed = [System.Collections.Generic.List[string]]::new()

        foreach ($target in $targets) {
            foreach ($class in $classes) {
                $label = "$($target.Name)|$class"

                Invoke-P2CCwdDrift -Path $target.Path -Class $class

                $reader = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'rt' -TabIndex 0 -TestBaseRoot $fixture.Base
                $refused = ([string]$reader.Status -eq 'unavailable') -and ([string]$reader.Reason -eq 'protected-root-invalid')

                # The refusal must come from the ROOT trust, not from the
                # descendants: the addressed chain stays untouched and valid.
                $descendantStillValid = Test-DevWSProtectedStateComponent -Component $setDir -Kind User

                $decision = [pscustomobject]@{
                    terminalId = 'rt'; tabIndex = 0; status = 'available'; reason = 'ok'
                    newCwd = [string]$baseline.Cwd; sessionId = [string]$pair.SessionId; windowId = 'DevWS-rt'
                    startupState = 'startup-child-returned'; startupSpecSha256 = ('AB' * 32)
                }
                Confirm-DevWSTerminalSaveDecisions -SetId 'main' -Decisions @{ rt = @($decision) } -TestBaseRoot $fixture.Base
                $gateDowngraded = ([string]$decision.status -eq 'unavailable') -and
                    ([string]$decision.reason -eq 'protected-root-invalid') -and
                    ([string]::IsNullOrEmpty([string]$decision.startupState)) -and
                    ([string]::IsNullOrEmpty([string]$decision.startupSpecSha256))

                Restore-P2CCwdDrift -Path $target.Path -Class $class -Kind $target.Kind

                $restored = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'rt' -TabIndex 0 -TestBaseRoot $fixture.Base
                $restoredOk = ([string]$restored.Status -eq 'available')

                if (-not ($refused -and [bool]$descendantStillValid.Ok -and $gateDowngraded -and $restoredOk)) {
                    $failed.Add($label) | Out-Null
                }
            }
        }

        Assert-Equal 0 $failed.Count ("every root/ancestor drift refuses reads and downgrades the gate while descendants stay valid (" + ($failed -join ', ') + ")")
    }

    Test-Case "protected cwd read authority invokes the authoritative full-root validator" {
        $fixture = New-P2CCwdFixture -Name "rootcall"
        $pair = New-P2CCwdPair -Fixture $fixture -TerminalId 'rc' -TabIndex 0

        $cwdLib = Get-SourceOf "src\lib\devws-cwd.ps1"
        Assert-Contains $cwdLib "Test-DevWSPrivilegedStateRoot" "the read-side chain trust calls the authoritative root validator"

        $savedValidator = (Get-Command -Name Test-DevWSPrivilegedStateRoot -CommandType Function).ScriptBlock

        try {
            function Test-DevWSPrivilegedStateRoot {
                param([string]$Root, [string]$UserSid = "")
                return [pscustomobject]@{ Ok = $false; Errors = @('shadowed-root-refusal'); Root = $Root; UserSid = $UserSid; Present = $true }
            }

            $reader = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'rc' -TabIndex 0 -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$reader.Status) "a refused root trust refuses the read"
            Assert-Equal 'protected-root-invalid' ([string]$reader.Reason) "the root refusal maps to the explicit reason"

            $decision = [pscustomobject]@{
                terminalId = 'rc'; tabIndex = 0; status = 'available'; reason = 'ok'
                newCwd = $TestRoot; sessionId = [string]$pair.SessionId; windowId = 'DevWS-rc'
                startupState = 'startup-child-returned'; startupSpecSha256 = ('CD' * 32)
            }
            Confirm-DevWSTerminalSaveDecisions -SetId 'main' -Decisions @{ rc = @($decision) } -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$decision.status) "the gate downgrades under a refused root trust"
            Assert-Equal 'protected-root-invalid' ([string]$decision.reason) "the gate uses the same root trust"
            Assert-True ([string]::IsNullOrEmpty([string]$decision.startupState)) "the gate clears startup state only on real downgrades"
        }
        finally {
            Set-Item -Path function:Test-DevWSPrivilegedStateRoot -Value $savedValidator -Force
        }
    }

    Test-Case "installed layouts refuse explicit cwd pathname overrides" {
        $fixture = New-InstallFixture "p2c-override-refusal"
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture

        $probe = Join-Path $fixture.Root "p2c-override-probe.ps1"
        Set-Content -LiteralPath $probe -Value @(
            'Set-StrictMode -Version Latest',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-paths.ps1")',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-cwd-paths.ps1")',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-cwd.ps1")',
            '$forged = Join-Path $PSScriptRoot "p2c-forged"',
            'New-Item -ItemType Directory -Path $forged -Force | Out-Null',
            '$session = Join-Path $forged "session.json"',
            '$publication = Join-Path $forged "publication.json"',
            '$sessionId = [guid]::NewGuid().ToString()',
            '$start = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")',
            'Write-DevWSCwdSessionRecord -Path $session -Record ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = $sessionId; startupSpecSha256 = ("AB" * 32) })',
            'Write-DevWSCwdPublication -Path $publication -Record ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = $sessionId; cwd = $PSScriptRoot; startupState = "startup-child-returned"; shellPid = $PID; shellStartTimeUtc = $start })',
            '"layout=$(Get-DevWSPathsLayout)"',
            '$r1 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot" -TabIndex 0 -SessionPath $session',
            '$r2 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot" -TabIndex 0 -PublicationPath $publication',
            '$r3 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot" -TabIndex 0 -SessionPath $session -PublicationPath $publication',
            '"r1=$($r1.Status)/$($r1.Reason)"',
            '"r2=$($r2.Status)/$($r2.Reason)"',
            '"r3=$($r3.Status)/$($r3.Reason)"'
        ) -Encoding UTF8

        $output = & pwsh -NoLogo -NoProfile -File $probe 2>&1 | Out-String
        Assert-Equal 0 $LASTEXITCODE "the override-refusal probe exits 0"
        Assert-Contains $output "layout=installed-privileged" "the probe runs an installed layout"
        Assert-Contains $output "r1=unavailable/explicit-path-refused" "a session-path-only override is refused"
        Assert-Contains $output "r2=unavailable/explicit-path-refused" "a publication-path-only override is refused"
        Assert-Contains $output "r3=unavailable/explicit-path-refused" "a combined override is refused"
        Assert-NotContains $output "/available" "no explicit-path variant resolves in the installed layout"

        # Repository compatibility: the same explicit paths still work for fixtures.
        $repoFixture = New-P2CCwdFixture -Name "overrideok"
        $repoPair = New-P2CCwdPair -Fixture $repoFixture -TerminalId 'ov' -TabIndex 0
        $repoRead = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'ov' -TabIndex 0 -SessionPath $repoPair.SessionPath -PublicationPath $repoPair.PublicationPath
        Assert-Equal 'available' ([string]$repoRead.Status) "repository fixtures keep explicit-path resolution"

        $cwdLib = Get-SourceOf "src\lib\devws-cwd.ps1"
        Assert-Contains $cwdLib "explicit-path-refused" "the refusal is part of the resolver source"
        Assert-Contains $cwdLib 'if ($layout -ne "repository"' "the refusal is gated on the actual runtime layout"
    }

    Test-Case "protected cwd ignores previously valid legacy pairs (Medium forgery regression)" {
        $savedState = $env:DEVWS_STATE_ROOT
        $savedProtected = $env:DEVWS_PROTECTED_STATE_ROOT

        try {
            # 1. Build the EXACT current-boundary forgery: a complete legacy pair
            #    with a live publisher identity, an attacker-chosen cwd and a
            #    matching configured-command fingerprint.
            $legacyRoot = Join-Path $TestRoot "p2c-forgery-legacy"
            New-Item -ItemType Directory -Path $legacyRoot -Force | Out-Null
            $forgedCwd = Join-Path $TestRoot "p2c-forged-cwd"
            New-Item -ItemType Directory -Path $forgedCwd -Force | Out-Null

            $env:DEVWS_STATE_ROOT = $legacyRoot
            Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue

            $fingerprint = Get-DevWSCwdChildSpecFingerprint -Command 'npm' -Arguments @('run', 'dev')
            $forgedSession = [guid]::NewGuid().ToString()
            $legacySessionPath = Get-DevWSCwdSessionPath -SetId 'main' -TerminalId 'slot' -TabIndex 0
            $legacyPublicationPath = Get-DevWSCwdPublicationPath -SetId 'main' -TerminalId 'slot' -TabIndex 0

            Write-DevWSCwdSessionRecord -Path $legacySessionPath -Record ([ordered]@{
                version = 1; setId = 'main'; terminalId = 'slot'; windowId = 'DevWS-slot'; sessionId = $forgedSession; startupSpecSha256 = $fingerprint
            })
            Write-DevWSCwdPublication -Path $legacyPublicationPath -Record ([ordered]@{
                version = 1; setId = 'main'; terminalId = 'slot'; windowId = 'DevWS-slot'; sessionId = $forgedSession
                cwd = $forgedCwd; startupState = 'startup-child-returned'
                shellPid = $PID; shellStartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString('o')
            })

            # 2. Prove the forgery is genuine for the OLD boundary: the legacy
            #    resolver accepts it and the old retirement path would retire.
            $legacyResolution = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'slot' -TabIndex 0
            Assert-Equal 'available' ([string]$legacyResolution.Status) "the forged pair is a genuine legacy-boundary forgery"
            Assert-Equal $forgedCwd ([string]$legacyResolution.Cwd) "the forgery controls the resolved cwd"

            $forgedDecision = [pscustomobject]@{
                terminalId = 'slot'; tabIndex = 0; status = 'available'; reason = 'ok'; newCwd = $forgedCwd
                sessionId = $forgedSession; windowId = 'DevWS-slot'
                startupState = 'startup-child-returned'; startupSpecSha256 = $fingerprint
            }
            $forgedTab = [pscustomobject]@{ command = 'npm'; args = @('run', 'dev') }
            $legacyRetire = Get-DevWSTabStartupRetirementDecision -Tab $forgedTab -Decision $forgedDecision
            Assert-Equal $true ([bool]$legacyRetire.Retire) "the legacy forgery would retire the configured startup command"

            # 3. Protected authority: the same forged legacy files are ignored.
            $fixture = New-P2CCwdFixture -Name "forg"

            $protectedResolution = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'slot' -TabIndex 0 -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$protectedResolution.Status) "protected authority ignores the forged legacy pair"
            Assert-Equal 'protected-chain-missing' ([string]$protectedResolution.Reason) "the protected failure is explicit"
            Assert-True ($null -eq $protectedResolution.Cwd) "no forged cwd is ever returned"

            # The final gate must downgrade even a decision that CLAIMS
            # availability from the forged session identity.
            $claimingDecision = [pscustomobject]@{
                terminalId = 'slot'; tabIndex = 0; status = 'available'; reason = 'ok'; newCwd = $forgedCwd
                sessionId = $forgedSession; windowId = 'DevWS-slot'
                startupState = 'startup-child-returned'; startupSpecSha256 = $fingerprint
            }
            $decisions = @{ slot = @($claimingDecision) }
            Confirm-DevWSTerminalSaveDecisions -SetId 'main' -Decisions $decisions -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$claimingDecision.status) "the final gate refuses the forged generation"
            Assert-True ([string]$claimingDecision.reason -cmatch '^protected-') "the gate downgrade reason is the protected refusal"
            Assert-True ($null -eq $claimingDecision.newCwd) "the gate clears the forged cwd"
            Assert-True ([string]::IsNullOrEmpty([string]$claimingDecision.startupState)) "the gate clears forged startup state"

            $gateRetire = Get-DevWSTabStartupRetirementDecision -Tab $forgedTab -Decision $claimingDecision
            Assert-Equal $false ([bool]$gateRetire.Retire) "no retirement is possible through protected authority"
            Assert-Equal 'cwd-unavailable' ([string]$gateRetire.Reason) "the retirement refusal reason"

            Assert-Equal $true (Test-Path -LiteralPath $legacySessionPath) "legacy files are never deleted"
            Assert-Equal $true (Test-Path -LiteralPath $legacyPublicationPath) "legacy publications are never deleted"

            # 4. A genuine protected pair still enables the intended path.
            $genuine = New-P2CCwdPair -Fixture $fixture -TerminalId 'slot' -TabIndex 0
            $genuineResolution = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'slot' -TabIndex 0 -TestBaseRoot $fixture.Base
            Assert-Equal 'available' ([string]$genuineResolution.Status) "a genuine protected pair resolves"
            Assert-Equal ([string]$genuine.SessionId) ([string]$genuineResolution.SessionId) "the genuine protected generation is authoritative"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_STATE_ROOT = $savedState }
            if ($null -eq $savedProtected) { Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_PROTECTED_STATE_ROOT = $savedProtected }
        }
    }

    Test-Case "protected cwd rotation and mixed generations stay fail-closed" {
        $savedProtected = $env:DEVWS_PROTECTED_STATE_ROOT

        try {
            $fixture = New-P2CCwdFixture -Name "rotation"

            $pair = New-P2CCwdPair -Fixture $fixture -TerminalId 'racer' -TabIndex 0
            $firstResolution = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'racer' -TabIndex 0 -TestBaseRoot $fixture.Base
            Assert-Equal 'available' ([string]$firstResolution.Status) "the initial protected pair resolves"

            # Final gate passes an accepted generation and rejects a rotation.
            $decision = [pscustomobject]@{
                terminalId = 'racer'; tabIndex = 0; status = 'available'; reason = 'ok'; newCwd = [string]$firstResolution.Cwd
                sessionId = [string]$firstResolution.SessionId; windowId = [string]$firstResolution.WindowId
                startupState = [string]$firstResolution.StartupState; startupSpecSha256 = [string]$firstResolution.StartupSpecSha256
            }
            Confirm-DevWSTerminalSaveDecisions -SetId 'main' -Decisions @{ racer = @($decision) } -TestBaseRoot $fixture.Base
            Assert-Equal 'available' ([string]$decision.status) "the gate accepts the exact accepted generation"

            $oldSessionId = [string]$pair.SessionId
            $oldPublicationText = [System.IO.File]::ReadAllText($pair.PublicationPath)

            $rotated = New-DevWSCwdTrackingSession -SetId 'main' -TerminalId 'racer' -WindowId 'DevWS-racer' -TabIndex 0 -TestBaseRoot $fixture.Base

            # Old shell republishes its old token after rotation: never accepted.
            [System.IO.File]::WriteAllText($pair.PublicationPath, $oldPublicationText, [System.Text.UTF8Encoding]::new($false))
            $mixed = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'racer' -TabIndex 0 -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$mixed.Status) "an old-generation publication after rotation is never accepted"
            Assert-Equal 'session-mismatch' ([string]$mixed.Reason) "the mixed generation fails on exact session identity"

            Confirm-DevWSTerminalSaveDecisions -SetId 'main' -Decisions @{ racer = @($decision) } -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$decision.status) "the final gate downgrades the rotated tab"
            Assert-True ([string]::IsNullOrEmpty([string]$decision.startupState)) "the downgrade clears startup metadata"

            # The new generation publishes and resolves again.
            $newPublication = [ordered]@{
                version = 1; setId = 'main'; terminalId = 'racer'; windowId = 'DevWS-racer'; sessionId = [string]$rotated.SessionId
                cwd = $TestRoot; startupState = 'startup-child-returned'; shellPid = $PID
                shellStartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString('o')
            }
            Write-DevWSCwdPublication -Path $rotated.PublicationPath -Record $newPublication
            $recovered = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'racer' -TabIndex 0 -TestBaseRoot $fixture.Base
            Assert-Equal 'available' ([string]$recovered.Status) "the new protected generation recovers"
            Assert-Equal ([string]$rotated.SessionId) ([string]$recovered.SessionId) "the recovered identity is the rotated generation"

            # Indexed tabs resolve independently with the maximum Int32 index.
            $indexed = New-P2CCwdPair -Fixture $fixture -TerminalId 'racer' -TabIndex 2147483647
            $indexedResolution = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'racer' -TabIndex 2147483647 -TestBaseRoot $fixture.Base
            Assert-Equal 'available' ([string]$indexedResolution.Status) "the maximum indexed tab resolves"
            Assert-Equal 2147483647 ([int]$indexedResolution.TabIndex) "the indexed identity is preserved"

            # Corrupt expected record: unavailable, never a fallback cwd.
            [System.IO.File]::WriteAllText($indexed.SessionPath, '{ not json', [System.Text.UTF8Encoding]::new($false))
            $corrupt = Resolve-DevWSTrackedCwd -SetId 'main' -TerminalId 'racer' -TabIndex 2147483647 -TestBaseRoot $fixture.Base
            Assert-Equal 'unavailable' ([string]$corrupt.Status) "a corrupt protected expected record is unavailable"
            Assert-Equal 'expected-malformed' ([string]$corrupt.Reason) "the corrupt record keeps the established reason vocabulary"
        }
        finally {
            if ($null -eq $savedProtected) { Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_PROTECTED_STATE_ROOT = $savedProtected }
        }
    }

    Test-Case "protected cwd bootstrap publication decision and installed derivation policy" {
        $fixture = New-P2CCwdFixture -Name "boot"
        $derived = Get-DevWSCwdProtectedPath -SidRoot $fixture.SidRoot -Kind 'publications' -SetId 'main' -TerminalId 'slot' -TabIndex 0

        $accept = Test-DevWSCwdBootstrapPublicationTarget -SidRoot $fixture.SidRoot -SetId 'main' -TerminalId 'slot' -TabIndex 0 -SuppliedPath $derived
        Assert-Equal $true ([bool]$accept.Ok) "the exact derived path is accepted"
        Assert-Equal $derived ([string]$accept.DerivedPath) "the derived path is returned"

        $caseAccept = Test-DevWSCwdBootstrapPublicationTarget -SidRoot $fixture.SidRoot -SetId 'MAIN' -TerminalId 'SLOT' -TabIndex 0 -SuppliedPath $derived
        Assert-Equal $true ([bool]$caseAccept.Ok) "case variants derive the same target"
        Assert-Equal $derived ([string]$caseAccept.DerivedPath) "case variants keep the exact derived path"

        $legacySupplied = Join-Path $TestRoot "p2c-legacy-publication.json"
        $refuse = Test-DevWSCwdBootstrapPublicationTarget -SidRoot $fixture.SidRoot -SetId 'main' -TerminalId 'slot' -TabIndex 0 -SuppliedPath $legacySupplied
        Assert-Equal $false ([bool]$refuse.Ok) "an arbitrary supplied path is refused"
        Assert-Equal 'publication-path-mismatch' ([string]$refuse.Reason) "the refusal reason is explicit"

        $overFixture = New-P2CCwdFixture -Name "bootover" -ExactRootLength 118
        $over = Test-DevWSCwdBootstrapPublicationTarget -SidRoot $overFixture.SidRoot -SetId 'main' -TerminalId 'slot' -TabIndex 0 -SuppliedPath (Join-Path $overFixture.SidRoot 'x.json')
        Assert-Equal $false ([bool]$over.Ok) "an over-budget root disables publication"
        Assert-Equal 'protected-root-budget' ([string]$over.Reason) "the budget refusal is explicit"

        $negative = Test-DevWSCwdBootstrapPublicationTarget -SidRoot $fixture.SidRoot -SetId 'main' -TerminalId 'slot' -TabIndex -1 -SuppliedPath $derived
        Assert-Equal $false ([bool]$negative.Ok) "a negative tab index disables publication"
        Assert-Equal 'tab-index-negative' ([string]$negative.Reason) "the negative index refusal is explicit"

        $invalid = Test-DevWSCwdBootstrapPublicationTarget -SidRoot $fixture.SidRoot -SetId 'a/b' -TerminalId 'slot' -TabIndex 0 -SuppliedPath $derived
        Assert-Equal $false ([bool]$invalid.Ok) "an invalid identity disables publication"
        Assert-Equal 'identity-invalid' ([string]$invalid.Reason) "the identity refusal is explicit"

        # The bootstrap consumes the canonical policy from its protected
        # sibling runtime and never duplicates the encoder.
        $bootstrap = Get-SourceOf "src\helpers\cwd-shell-bootstrap.ps1"
        Assert-Contains $bootstrap 'lib\devws-cwd-paths.ps1' "the installed bootstrap loads the protected path leaf"
        Assert-Contains $bootstrap 'DevWSCwdBootstrapInstalled' "the bootstrap discriminates its own layout"
        Assert-Contains $bootstrap 'Test-DevWSCwdBootstrapPublicationTarget' "the bootstrap uses the canonical derivation decision"
        Assert-Contains $bootstrap 'DevWSCwdBootstrapBlocked' "the bootstrap carries an explicit publication block state"
        Assert-Contains $bootstrap 'publication skipped (swallowed)' "a blocked publication is logged and swallowed"
        Assert-Contains $bootstrap 'a tracked shell never creates protected ancestors' "the installed shell never creates trusted ancestors"
        Assert-NotContains $bootstrap 'SHA256' "the bootstrap never embeds its own encoder"
        Assert-NotContains $bootstrap 'ConvertTo-DevWSCwdProtectedKey' "the bootstrap never duplicates the key mapping"
        Assert-NotContains $bootstrap 'New-Item -ItemType Directory' "the bootstrap never creates protected ancestors"

        $pathsLib = Get-SourceOf "src\lib\devws-cwd-paths.ps1"
        Assert-Contains $pathsLib 'SHA256' "the leaf owns the hash mapping"
        $cwdLib = Get-SourceOf "src\lib\devws-cwd.ps1"
        Assert-NotContains $cwdLib 'ConvertTo-DevWSCwdProtectedKey -Id $Id' "the cwd library delegates key derivation to the leaf"
    }

    Test-Case "installed layouts derive protected cwd paths only and refuse repository seams" {
        $fixture = New-InstallFixture "p2c-installed-derivation"
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture

        $probe = Join-Path $fixture.Root "p2c-probe.ps1"
        Set-Content -LiteralPath $probe -Value @(
            'Set-StrictMode -Version Latest',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-paths.ps1")',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-cwd-paths.ps1")',
            '. (Join-Path $PSScriptRoot "Program Files\DevWS\privileged\lib\devws-cwd.ps1")',
            '$env:DEVWS_STATE_ROOT = "C:\p2c-hostile-state"',
            '$env:DEVWS_PROTECTED_STATE_ROOT = "C:\p2c-hostile-protected"',
            '"layout=$(Get-DevWSPathsLayout)"',
            '"mode=$(Get-DevWSCwdStorageMode)"',
            '"session=$(Get-DevWSCwdSessionPath -SetId "main" -TerminalId "t0")"',
            '"publication=$(Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "t0" -TabIndex 2)"',
            '"seam=$(try { $null = Get-DevWSCwdSessionPath -SetId "main" -TerminalId "t0" -TestBaseRoot "C:\hostile"; "ERROR" } catch { "REFUSED" })"'
        ) -Encoding UTF8

        $output = & pwsh -NoLogo -NoProfile -File $probe 2>&1 | Out-String
        Assert-Equal 0 $LASTEXITCODE "the installed derivation probe exits 0"
        Assert-Contains $output "layout=installed-privileged" "the fixture is an installed privileged layout"
        Assert-Contains $output "mode=protected" "installed layouts are always protected"
        Assert-Contains $output "seam=REFUSED" "the repository fixture seam is refused in installed layouts"
        Assert-NotContains $output "p2c-hostile" "environment overrides never redirect protected cwd paths"

        $expectedSession = Get-DevWSCwdProtectedPath -SidRoot (Get-DevWSCwdProtectedSidRoot) -Kind 'sessions' -SetId 'main' -TerminalId 't0' -TabIndex 0
        $expectedPublication = Get-DevWSCwdProtectedPath -SidRoot (Get-DevWSCwdProtectedSidRoot) -Kind 'publications' -SetId 'main' -TerminalId 't0' -TabIndex 2
        Assert-Contains $output ("session=" + $expectedSession) "the session path derives from ProgramData plus the current SID only"
        Assert-Contains $output ("publication=" + $expectedPublication) "the indexed publication path derives from ProgramData plus the current SID only"
    }

    Test-Case "phase 2-C wiring, manifests and import order carry the shared leaf" {
        $leafName = "devws-cwd-paths.ps1"

        $required = @(Get-DevWSRequiredLibraryNames)
        Assert-Equal 35 $required.Count "the normal required set carries 35 libraries"
        Assert-True ($required -contains $leafName) "the normal required set carries the leaf"

        $privilegedNames = @(Get-DevWSPrivilegedLibraryNames)
        Assert-True ($privilegedNames -contains $leafName) "the privileged High-reachable set carries the leaf"

        $pathsLib = Get-SourceOf "src\lib\devws-paths.ps1"
        Assert-Contains $pathsLib $leafName "the privileged name list is owned by the paths library"

        $wsSource = Get-SourceOf "src\ws.ps1"
        $leafIndex = $wsSource.IndexOf($leafName)
        $cwdIndex  = $wsSource.IndexOf("devws-cwd.ps1")
        Assert-True (($leafIndex -ge 0) -and ($leafIndex -lt $cwdIndex)) "ws.ps1 loads the leaf before the cwd library"

        foreach ($workerName in @("elevated.ps1", "elevated-reset.ps1", "elevated-broker.ps1")) {
            $worker = Get-SourceOf ("src\workers\" + $workerName)
            $workerLeaf = $worker.IndexOf($leafName)
            $workerCwd  = $worker.IndexOf("devws-cwd.ps1")
            Assert-True (($workerLeaf -ge 0) -and ($workerLeaf -lt $workerCwd)) "$workerName loads the leaf before the cwd library"
        }

        $stubSection = Get-SourceOf "tests\run-tests.ps1"
        Assert-Contains $stubSection ('$stubFiles["' + $leafName + '"]') "the pass-2 stub fixture carries a leaf stub"

        $leaf = Get-SourceOf "src\lib\devws-cwd-paths.ps1"
        Assert-Contains $leaf "MaxRootLength" "the leaf owns the budget constants"
        Assert-Contains $leaf "Test-DevWSCwdBootstrapPublicationTarget" "the leaf owns the bootstrap decision"

        # Health keeps its count and picks the leaf up through the shared list.
        $health = Get-SourceOf "src\lib\devws-health.ps1"
        Assert-Contains $health "Get-DevWSRequiredLibraryNames" "health keeps consuming the shared required set"
    }

    Start-TestGroup -Name 'install-metadata' -Title 'Install metadata'

    Test-Case "install metadata round-trips atomically and retains ownership history" {
        $path = Join-Path $TestRoot "metadata\install-metadata.json"
        $metadata = New-DevWSInstallMetadata

        $metadata.installRoot = "X:\DevWS"
        $metadata.installedAt = "2026-01-01T00:00:00.0000000+01:00"
        $metadata.path.added = $true
        $metadata.path.entry = "X:\DevWS\bin"
        $metadata.legacyShim.replaced = $true
        $metadata.legacyShim.path = "X:\home\.local\bin\ws.cmd"
        $metadata.legacyShim.backup = "X:\backups\legacy.cmd"
        $metadata.hotkey.managed = $true
        $metadata.hotkey.backup = "X:\backups\TerminalShortcut.ahk"
        $metadata.tasks.backups | Add-Member -NotePropertyName "DevWorkspace-ElevatedHelper" -NotePropertyValue "X:\backups\helper.xml"
        $metadata.config.action = "migrate"
        $metadata.config.backup = "X:\backups\v1.json"

        Save-DevWSInstallMetadata -Path $path -Metadata $metadata
        Assert-True (-not (Test-Path -LiteralPath "$path.tmp")) "atomic metadata write cleaned its temp file"

        $loaded = Read-DevWSInstallMetadata -Path $path
        Assert-Equal 1 $loaded.version "schema version"
        Assert-Equal "X:\DevWS" $loaded.installRoot "install root retained"
        Assert-Equal "2026-01-01T00:00:00.0000000+01:00" $loaded.installedAt "original install time retained"
        Assert-Equal $true $loaded.path.added "PATH ownership retained"
        Assert-Equal $true $loaded.legacyShim.replaced "shim ownership retained"
        Assert-Equal "X:\backups\legacy.cmd" $loaded.legacyShim.backup "shim backup retained"
        Assert-Equal $true $loaded.hotkey.managed "hotkey ownership retained"
        Assert-Equal "X:\backups\helper.xml" $loaded.tasks.backups.PSObject.Properties["DevWorkspace-ElevatedHelper"].Value "task backup retained"
        Assert-Equal "migrate" $loaded.config.action "config action retained"
        Assert-True (-not [string]::IsNullOrWhiteSpace($loaded.updatedAt)) "updated timestamp written"

        # Additive Security Phase 1 record: empty by default, round-trips.
        Assert-Equal "" $loaded.privileged.root "privileged root defaults empty"
        Assert-Equal "" $loaded.privileged.powerShellPath "privileged PowerShell path defaults empty"
        $loaded.privileged.root = "C:\Program Files\DevWS\privileged"
        $loaded.privileged.powerShellPath = "C:\Program Files\PowerShell\7\pwsh.exe"
        Save-DevWSInstallMetadata -Path $path -Metadata $loaded
        $privilegedReload = Read-DevWSInstallMetadata -Path $path
        Assert-Equal "C:\Program Files\DevWS\privileged" $privilegedReload.privileged.root "privileged root retained"
        Assert-Equal "C:\Program Files\PowerShell\7\pwsh.exe" $privilegedReload.privileged.powerShellPath "privileged PowerShell path retained"
        $loaded = $privilegedReload

        $loaded.hotkey.managed = $false
        $loaded.installRoot = "X:\DevWS2"
        Save-DevWSInstallMetadata -Path $path -Metadata $loaded

        $reloaded = Read-DevWSInstallMetadata -Path $path
        Assert-Equal "X:\DevWS2" $reloaded.installRoot "update applied"
        Assert-Equal "X:\backups\TerminalShortcut.ahk" $reloaded.hotkey.backup "backup history retained across updates"
        Assert-Equal "2026-01-01T00:00:00.0000000+01:00" $reloaded.installedAt "install time not destroyed by updates"

        Set-Content -LiteralPath $path -Value "{not valid json" -Encoding UTF8
        $fallback = Read-DevWSInstallMetadata -Path $path
        Assert-Equal $false $fallback.path.added "corrupt metadata yields safe defaults"
        Assert-Equal 1 $fallback.version "fallback schema version"
    }

    Write-Host ""
    Start-TestGroup -Name 'uninstall' -Title 'Uninstall'

    Test-Case "uninstall plan preserves config and v1, and only purges with -Purge" {
        $fixture = New-InstallFixture "uninstall"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $canonical = Join-Path $fixture.Root "canonical.json"
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $canonical

        New-Item -ItemType Directory -Path $fixture.Backups -Force | Out-Null
        New-Item -ItemType Directory -Path (Join-Path $fixture.Root "local-bin") -Force | Out-Null

        $shimPath = Join-Path $fixture.Root "local-bin\ws.cmd"
        Set-Content -LiteralPath $shimPath -Value (New-DevWSShimContent -InstallRoot $fixture.Root) -NoNewline

        $shimBackup = Join-Path $fixture.Backups "legacy-ws-cmd-prev.cmd"
        Set-Content -LiteralPath $shimBackup -Value "@echo off`r`npwsh.exe -NoLogo -NoProfile -File `"%USERPROFILE%\.ws\ws.ps1`" %*`r`n" -NoNewline

        New-Item -ItemType Directory -Path (Join-Path $fixture.Root "Startup") -Force | Out-Null
        $hotkeyPath = Join-Path $fixture.Root "Startup\TerminalShortcut.ahk"
        Set-Content -LiteralPath $hotkeyPath -Value (New-DevWSTerminalShortcutContent -AppScriptPath (Join-Path $fixture.Root "app\ws.ps1") -BindingsPath (Join-Path $fixture.State "hotkeys\bindings.ahk")) -NoNewline

        $hotkeyBackup = Join-Path $fixture.Backups "TerminalShortcut-prev.ahk"
        Set-Content -LiteralPath $hotkeyBackup -Value "!z::Run('previous')`r`n" -NoNewline

        $metadata = New-DevWSInstallMetadata
        $metadata.installRoot = $fixture.Root
        $metadata.path.added = $false
        $metadata.path.entry = Join-Path $fixture.Root "bin"
        $metadata.legacyShim.replaced = $true
        $metadata.legacyShim.backup = $shimBackup
        $metadata.hotkey.managed = $true
        $metadata.hotkey.backup = $hotkeyBackup

        New-Item -ItemType Directory -Path (Join-Path $fixture.Privileged "workers") -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $fixture.Privileged "workers\elevated.ps1") -Value "# fixture" -NoNewline

        $plan = Get-DevWSUninstallPlan -InstallRoot $fixture.Root -PrivilegedRoot $fixture.Privileged -CanonicalPath $canonical -LegacyShimPath $shimPath -HotkeyPath $hotkeyPath -Metadata $metadata

        Assert-Equal $fixture.Privileged $plan.PrivilegedPath "explicit privileged root is planned for removal"

        $implicitPlan = Get-DevWSUninstallPlan -InstallRoot $fixture.Root -CanonicalPath $canonical -LegacyShimPath $shimPath -HotkeyPath $hotkeyPath -Metadata $metadata
        Assert-Equal $null $implicitPlan.PrivilegedPath "fixture plans never default to the real privileged root"

        Assert-Equal $false $plan.RemoveCanonicalConfig "default preserves canonical config"
        Assert-Equal $false $plan.RemoveState "default preserves disposable state"
        Assert-Equal $false $plan.RemovePathEntry "PATH entry not owned by the installer"
        Assert-Equal $true $plan.RestoreLegacyShim "recognized shim restored from backup"
        Assert-Equal $true $plan.RestoreHotkey "previous hotkey restored from backup"
        Assert-Equal $false $plan.RemoveHotkey "no hotkey removal when a backup exists"
        Assert-Equal $true $plan.PreserveV1 "v1 rollback directory preserved"
        Assert-Equal 5 @($plan.TaskNames).Count "five tasks are removed"
        Assert-True (@($plan.TaskNames) -contains "DevWorkspace-ElevatedBroker") "the persistent broker task is removed"
        Assert-Equal $null $plan.CoordinatorPipeName "fixture plan never targets the production coordinator pipe"
        Assert-Equal $false $plan.StopManagedHotkeyProcess "fixture plan never stops a production hotkey process"

        foreach ($name in @("AppPath", "HelpersPath", "WorkersPath", "BinPath", "StatePath")) {
            $target = $plan.$name
            Assert-True ($target.StartsWith($fixture.Root, [StringComparison]::OrdinalIgnoreCase)) "$name stays inside the install root"
            Assert-True ($target.IndexOf("\.ws\", [StringComparison]::OrdinalIgnoreCase) -lt 0) "$name never points at the v1 directory"
        }

        $ownedMetadata = New-DevWSInstallMetadata
        $ownedMetadata.path.added = $true
        $ownedMetadata.path.entry = Join-Path $fixture.Root "bin"

        $ownedPlan = Get-DevWSUninstallPlan -InstallRoot $fixture.Root -CanonicalPath $canonical -LegacyShimPath $shimPath -HotkeyPath $hotkeyPath -Metadata $ownedMetadata
        Assert-Equal $true $ownedPlan.RemovePathEntry "installer-owned PATH entry is planned for removal"

        $purgePlan = Get-DevWSUninstallPlan -InstallRoot $fixture.Root -CanonicalPath $canonical -LegacyShimPath $shimPath -HotkeyPath $hotkeyPath -Metadata $metadata -Purge
        Assert-Equal $true $purgePlan.RemoveCanonicalConfig "purge removes canonical config"
        Assert-Equal $true $purgePlan.RemoveState "purge removes disposable state"
        Assert-Equal $true $purgePlan.PreserveV1 "purge still preserves the v1 rollback directory"

        # Execute against the fixture (tasks intentionally skipped; the real user
        # PATH is never written by tests).
        $actions = @(Invoke-DevWSUninstall -Plan $plan -SkipTasks)

        Assert-True (-not (Test-Path -LiteralPath $fixture.App)) "app removed"
        Assert-True (-not (Test-Path -LiteralPath $fixture.Helpers)) "helpers removed"
        Assert-True (-not (Test-Path -LiteralPath $fixture.Workers)) "workers removed"
        Assert-True (-not (Test-Path -LiteralPath $fixture.Bin)) "bin removed"
        Assert-True (Test-Path -LiteralPath $fixture.State -PathType Container) "state preserved by default"
        Assert-True (Test-Path -LiteralPath $canonical -PathType Leaf) "canonical config preserved"
        Assert-True (Test-DevWSLegacyShimContent -Content (Get-Content -LiteralPath $shimPath -Raw)) "pre-install shim restored"
        Assert-Equal "!z::Run('previous')`r`n" (Get-Content -LiteralPath $hotkeyPath -Raw) "pre-install hotkey restored"
        Assert-True (-not (Test-Path -LiteralPath $fixture.Privileged)) "privileged root removed"
        Assert-True (-not (Test-Path -LiteralPath (Split-Path -Parent $fixture.Privileged))) "empty Program Files\DevWS parent removed"
        Assert-True ($actions.Count -gt 0) "actions reported"
    }

