        Set-Content -LiteralPath $hotkeyPath -Value (New-DevWSTerminalShortcutContent -AppScriptPath (Join-Path $fixture.Root "app\ws.ps1") -BindingsPath (Join-Path $fixture.State "hotkeys\bindings.ahk")) -NoNewline

