    Test-Case "CLI bind and unbind save canonical config then sync derived hotkeys" {
        $fixture = New-InstallFixture "bindings-cli"
        New-Item -ItemType Directory -Path (Join-Path $fixture.Root "app") -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $fixture.Root "app\ws.ps1") -Value "# fixture app script" -NoNewline

        $startup = Join-Path $fixture.Root "Startup"
        New-Item -ItemType Directory -Path $startup -Force | Out-Null
        $bindingsPath = Join-Path $fixture.State "hotkeys\bindings.ahk"
        Set-Content -LiteralPath (Join-Path $startup "TerminalShortcut.ahk") -Value (New-DevWSTerminalShortcutContent -AppScriptPath (Join-Path $fixture.Root "app\ws.ps1") -BindingsPath $bindingsPath) -NoNewline

        $target = Join-Path $fixture.Root "workspace.json"
        ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"), (New-TestSet -Id "secondary")) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

        $previous = [pscustomobject]@{
            Config      = $env:DEVWS_CONFIG
            InstallRoot = $env:DEVWS_INSTALL_ROOT
            StateRoot   = $env:DEVWS_STATE_ROOT
            StartupPath = $env:DEVWS_STARTUP_PATH
        }

        $env:DEVWS_CONFIG = $target
        $env:DEVWS_INSTALL_ROOT = $fixture.Root
        $env:DEVWS_STATE_ROOT = $fixture.State
        $env:DEVWS_STARTUP_PATH = $startup
        $script:bindingReloads = 0

        try {
            function Start-DevWSInstalledHotkey {
                param([Parameter(Mandatory)][string]$HotkeyPath)
                $script:bindingReloads++
                return $true
            }

            Invoke-DevWSBind -SetReference "SECONDARY" -Hotkey "SHIFT+ALT+Y"

            $saved = Read-DevWSConfigFile -Path $target
            Assert-Equal 1 @($saved.bindings).Count "binding saved"
            Assert-Equal "alt+shift+y" $saved.bindings[0].hotkey "canonical hotkey stored"
            Assert-Equal "secondary" $saved.bindings[0].setId "configured set casing stored"
            Assert-Equal 1 $script:bindingReloads "bind reloads derived hotkeys after save"
            Assert-True (Test-Path -LiteralPath $bindingsPath -PathType Leaf) "generated bindings written"
            Assert-Contains (Get-Content -LiteralPath $bindingsPath -Raw) "launch secondary" "generated handler targets the explicit set"
            Assert-True (Test-DevWSBindingsInSync -Config $saved -AppScriptPath (Join-Path $fixture.Root "app\ws.ps1") -Path $bindingsPath) "generated content matches canonical config"

            Invoke-DevWSUnbind -Hotkey "SHIFT+ALT+Y"

            $saved = Read-DevWSConfigFile -Path $target
            Assert-Equal 0 @($saved.bindings).Count "binding removed"
            Assert-Equal 2 $script:bindingReloads "unbind reloads derived hotkeys after save"
            Assert-NotContains (Get-Content -LiteralPath $bindingsPath -Raw) "launch secondary" "generated handler removed"
        }
        finally {
            if ($null -eq $previous.Config) { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue } else { $env:DEVWS_CONFIG = $previous.Config }
            if ($null -eq $previous.InstallRoot) { Remove-Item Env:\DEVWS_INSTALL_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_INSTALL_ROOT = $previous.InstallRoot }
            if ($null -eq $previous.StateRoot) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue } else { $env:DEVWS_STATE_ROOT = $previous.StateRoot }
            if ($null -eq $previous.StartupPath) { Remove-Item Env:\DEVWS_STARTUP_PATH -ErrorAction SilentlyContinue } else { $env:DEVWS_STARTUP_PATH = $previous.StartupPath }
        }
    }

    Test-Case "bind failures never touch config or derived state and sync failures report drift recovery" {
        $fixture = New-InstallFixture "bindings-failures"
        New-Item -ItemType Directory -Path (Join-Path $fixture.Root "app") -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $fixture.Root "app\ws.ps1") -Value "# fixture app script" -NoNewline

        $target = Join-Path $fixture.Root "workspace.json"
        ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"), (New-TestSet -Id "secondary")) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

        $previousConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target
        $script:syncAttempts = 0
        $script:failSync = $false

        try {
            function Sync-DevWSBindings {
                param($Config, [string]$InstallRoot, [string]$StateRoot, [string]$StartupPath, [switch]$SkipReload)

                $script:syncAttempts++

                if ($script:failSync) {
                    throw "simulated hotkey integration failure"
                }

                return [pscustomobject]@{ Status = "current"; Path = $null; CorePath = $null; Reloaded = $true }
            }

            $before = Get-FileBase64 -Path $target

            $message = Get-ThrownMessage { Invoke-DevWSBind -SetReference "secondary" -Hotkey "alt+shift+t" }
            Assert-Contains $message "reserved" "reserved bind rejected"
            Assert-Equal $before (Get-FileBase64 -Path $target) "reserved bind leaves config bytes unchanged"
            Assert-Equal 0 $script:syncAttempts "no sync before a successful save"

            $message = Get-ThrownMessage { Invoke-DevWSBind -SetReference "missing" -Hotkey "ctrl+alt+r" }
            Assert-Contains $message "Unknown workspace set" "unknown set bind rejected"
            Assert-Equal 0 $script:syncAttempts "unknown set never reaches sync"

            Invoke-DevWSBind -SetReference "secondary" -Hotkey "alt+shift+y"
            Assert-Equal 1 $script:syncAttempts "successful bind syncs after save"

            $afterBind = Get-FileBase64 -Path $target

            $message = Get-ThrownMessage { Invoke-DevWSBind -SetReference "main" -Hotkey "ALT+SHIFT+Y" }
            Assert-Contains $message "already bound" "duplicate bind rejected"
            Assert-Equal $afterBind (Get-FileBase64 -Path $target) "duplicate bind leaves config bytes unchanged"
            Assert-Equal 1 $script:syncAttempts "duplicate bind never reaches sync"

            $script:failSync = $true
            $message = Get-ThrownMessage { Invoke-DevWSBind -SetReference "main" -Hotkey "ctrl+alt+r" }

            Assert-Contains $message "WAS updated" "sync failure states config was updated"
            Assert-Contains $message "out of sync" "sync failure states derived state is stale"
            Assert-Contains $message "ws sync-hotkeys" "sync failure names the recovery command"
            Assert-Equal 2 $script:syncAttempts "sync attempted after the saved mutation"

            $saved = Read-DevWSConfigFile -Path $target
            Assert-Equal 2 @($saved.bindings).Count "sync failure does not roll config back"
        }
        finally {
            if ($null -eq $previousConfig) { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue } else { $env:DEVWS_CONFIG = $previousConfig }
        }
    }

