    Test-Case "remove-set refuses bound sets, -Force cannot bypass it, and clones never copy bindings" {
        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main"),
            (New-TestSet -Id "secondary"),
            (New-TestSet -Id "third")
        ) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" })

        $message = Get-ThrownMessage { Remove-DevWSSet -Config $config -Reference "secondary" }
        Assert-Contains $message "launch bindings still target it" "bound set removal refused"
        Assert-Contains $message "alt+shift+y" "refusal lists the bound hotkey"
        Assert-Contains $message "Unbind" "refusal names the unbind command"
        Assert-Equal 3 @($config.sets).Count "bound set not removed"

        $dir = Join-Path $TestRoot "remove-set-bound"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $file = Join-Path $dir "workspace.json"
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $file -Encoding UTF8
        $before = Get-FileBase64 -Path $file

        $result = Invoke-WsCli -ConfigPath $file -Arguments @("remove-set", "secondary", "-Force")
        Assert-Equal 1 $result.ExitCode "-Force cannot bypass the binding invariant"
        Assert-Contains $result.Output "Unbind them first" "CLI names the required unbind"
        Assert-Equal $before (Get-FileBase64 -Path $file) "refused removal leaves config bytes unchanged"

        $null = Remove-DevWSBinding -Config $config -Hotkey "alt+shift+y"
        $removed = Remove-DevWSSet -Config $config -Reference "secondary"

        Assert-Equal "secondary" $removed.id "set removal works after unbinding"
        Assert-Equal 2 @($config.sets).Count "one set removed after unbinding"

        $cloneConfig = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main"),
            (New-TestSet -Id "secondary")
        ) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "main" })

        $cloneResult = Clone-DevWSSet -Config $cloneConfig -SourceId "main" -NewId "copy"

        Assert-Equal 1 @($cloneConfig.bindings).Count "clone-set never adds or removes bindings"
        Assert-Equal "alt+shift+y" $cloneConfig.bindings[0].hotkey "existing binding preserved"
        Assert-Equal "copy" $cloneResult.Clone.id "clone created"
        Assert-True ($null -eq $cloneResult.Clone.PSObject.Properties["bindings"]) "cloned set owns no bindings"

        $lines = @(Get-DevWSSetsLines -Config $cloneConfig)
        $mainLine      = @($lines | Where-Object { $_ -match '\bmain\b' })[0]
        $secondaryLine = @($lines | Where-Object { $_ -match '\bsecondary\b' })[0]

        Assert-Contains $mainLine "[alt+shift+y]" "ws sets exposes the set's launch hotkeys"
        Assert-NotContains $secondaryLine "[alt+shift+y]" "ws sets keeps hotkeys on the bound set only"
    }

    Test-Case "generated bindings content is deterministic, ordered, and launch-only" {
        $appScript = "C:\Program Files\Dev WS\app\ws.ps1"

        $empty = New-DevWSBindingsAhkContent -Bindings @() -AppScriptPath $appScript
        $expectedEmpty = "; Generated by DevWS from workspace config. Do not edit.`r`n; Derived state; regenerate with: ws sync-hotkeys`r`n"

        Assert-Equal $expectedEmpty $empty "empty generated content is exactly the deterministic header"
        Assert-Equal $empty (New-DevWSBindingsAhkContent -Bindings @() -AppScriptPath $appScript) "empty generated content is deterministic"
        Assert-NotContains $empty "::" "no hotkeys when no bindings are configured"

        $bindings = @(
            [pscustomobject]@{ hotkey = "alt+shift+y"; setId = "secondary" },
            [pscustomobject]@{ hotkey = "ctrl+alt+r"; setId = "research" }
        )

        $content = New-DevWSBindingsAhkContent -Bindings $bindings -AppScriptPath $appScript
        $lines = @($content -split "`r`n" | Where-Object { $_ -ne "" })

        Assert-Equal 4 $lines.Count "header plus one line per binding"
        Assert-Equal '!+y::Run(''pwsh.exe -NoLogo -NoProfile -WindowStyle Hidden -File "C:\Program Files\Dev WS\app\ws.ps1" launch secondary'', , "Hide")' $lines[2] "first handler is exact and quotes the spaced path"
        Assert-Equal '^!r::Run(''pwsh.exe -NoLogo -NoProfile -WindowStyle Hidden -File "C:\Program Files\Dev WS\app\ws.ps1" launch research'', , "Hide")' $lines[3] "second handler is exact"
        Assert-Equal $content (New-DevWSBindingsAhkContent -Bindings $bindings -AppScriptPath $appScript) "multi-binding content is deterministic"

        $reversed = New-DevWSBindingsAhkContent -Bindings @($bindings[1], $bindings[0]) -AppScriptPath $appScript
        Assert-True ($reversed -ne $content) "generated order follows config order"
        Assert-True ($reversed.IndexOf("launch research") -lt $reversed.IndexOf("launch secondary")) "reversed input reverses handlers"

        Assert-NotContains $content "#SingleInstance" "generated include never owns #SingleInstance"
        Assert-NotContains $content "!+t::" "generated include never owns Alt+Shift+T"
        Assert-NotContains $content "AdminTerminal" "generated include never runs scheduled tasks"
        Assert-NotContains $content "schtasks" "generated include never runs scheduled tasks"
        Assert-NotContains $content "#Requires" "generated include carries no version requirement"

        $tricky = New-DevWSBindingsAhkContent -Bindings @([pscustomobject]@{ hotkey = "alt+shift+y"; setId = "secondary" }) -AppScriptPath "C:\Apps\O'Brien\ws.ps1"
        Assert-Contains $tricky "O``'Brien" "single quotes in paths are escaped for AutoHotkey"

        $path = Join-Path $TestRoot "bindings-in-sync\bindings.ahk"
        New-Item -ItemType Directory -Path (Split-Path -Parent $path) -Force | Out-Null
        Set-Content -LiteralPath $path -Value $content -NoNewline

        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"), (New-TestSet -Id "secondary")) -Bindings @(
            [ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" },
            [ordered]@{ hotkey = "ctrl+alt+r"; setId = "research" }
        )

        # Research set intentionally absent: comparison is pure content, so add it.
        $config.sets = @($config.sets) + [pscustomobject][ordered]@{ id = "research"; windows = @() }

        Assert-Equal $true (Test-DevWSBindingsInSync -Config $config -AppScriptPath $appScript -Path $path) "exact generated content is in sync"

        Set-Content -LiteralPath $path -Value "stale" -NoNewline
        Assert-Equal $false (Test-DevWSBindingsInSync -Config $config -AppScriptPath $appScript -Path $path) "stale generated content is out of sync"

        Remove-Item -LiteralPath $path -Force
        Assert-Equal $false (Test-DevWSBindingsInSync -Config $config -AppScriptPath $appScript -Path $path) "missing generated content is out of sync"

        $geometryConfig = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox" -InstanceMode "dedicated"))),
            (New-TestSet -Id "secondary")
        ) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" })

        $contentA = Get-DevWSBindingsContentFromConfig -Config $geometryConfig -AppScriptPath $appScript
        $geometryConfig.sets[0].windows[0].layout.x = 999
        $contentB = Get-DevWSBindingsContentFromConfig -Config $geometryConfig -AppScriptPath $appScript

        Assert-Equal $contentA $contentB "geometry-only changes never alter generated content"
    }

