        $message = Get-ThrownMessage { Sync-DevWSBindings -Config $config -InstallRoot $fixture.Root -StateRoot $fixture.State -StartupPath $startup }
        Assert-Contains $message "include" "managed core without the Phase 8 include contract fails safely"
        Assert-Equal $noIncludeBefore (Get-FileBase64 -Path $corePath) "stale managed core is never overwritten by sync"
    }

    Test-Case "health reports generated bindings drift with ws sync-hotkeys guidance and never repairs" {
        $fixture = New-InstallFixture "health-bindings"
        $canonical = Join-Path $fixture.Root "canonical.json"
        $appScript = Join-Path $fixture.Root "app\ws.ps1"

        $config = ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @((New-AppDefinition -Id "firefox" -InstanceMode "dedicated"))),
            (New-TestSet -Id "secondary")
        ) -Bindings @([ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" })

        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $canonical -Encoding UTF8

        $startup = Join-Path $fixture.Root "Startup"
        New-Item -ItemType Directory -Path $startup -Force | Out-Null
        $corePath = Join-Path $startup "TerminalShortcut.ahk"
        $bindingsPath = Join-Path $fixture.State "hotkeys\bindings.ahk"
        Set-Content -LiteralPath $corePath -Value (New-DevWSTerminalShortcutContent -AppScriptPath $appScript -BindingsPath $bindingsPath) -NoNewline

        $null = Write-DevWSBindingsState -Config $config -AppScriptPath $appScript -Path $bindingsPath

        $stubs = Join-Path $fixture.Root "stubs"
        New-Item -ItemType Directory -Path $stubs -Force | Out-Null
        $wtStub  = Join-Path $stubs "wt.exe"
        $ahkStub = Join-Path $stubs "AutoHotkey64.exe"
        Set-Content -LiteralPath $wtStub -Value ""
        Set-Content -LiteralPath $ahkStub -Value ""

        $context = [pscustomobject]@{
            InstallRoot         = $fixture.Root
            StateRoot           = $fixture.State
            CanonicalPath       = $canonical
            StartupPath         = $startup
            LegacyShimPath      = Join-Path $fixture.Root "local-bin\ws.cmd"
            WindowsTerminalPath = $wtStub
            AutoHotkeyPath      = $ahkStub
            MetadataPath        = Join-Path $fixture.State "install-metadata.json"
            PrivilegedRoot      = $fixture.Privileged
        }

        $bindingsBefore = Get-FileBase64 -Path $bindingsPath
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal $true $byId["hotkey-bindings"].Ok "exact generated content passes"
        Assert-Equal $true $byId["hotkey-target"].Ok "phase 8 include contract passes"
        Assert-Equal $bindingsBefore (Get-FileBase64 -Path $bindingsPath) "health never rewrites generated content"

        Remove-Item -LiteralPath $bindingsPath -Force
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal $false $byId["hotkey-bindings"].Ok "missing generated file fails"
        Assert-Contains $byId["hotkey-bindings"].Message "ws sync-hotkeys" "missing drift names the recovery command"

        Set-Content -LiteralPath $bindingsPath -Value "stale content" -NoNewline
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal $false $byId["hotkey-bindings"].Ok "stale generated file fails"
        Assert-Contains $byId["hotkey-bindings"].Message "ws sync-hotkeys" "stale drift names the recovery command"

        # Geometry-only config edits must not look like binding drift.
        $null = Write-DevWSBindingsState -Config (Read-DevWSConfigFile -Path $canonical) -AppScriptPath $appScript -Path $bindingsPath

        $mutated = Read-DevWSConfigFile -Path $canonical
        $mutated.sets[0].windows[0].layout.x = 321
        $mutated | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $canonical -Encoding UTF8

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal $true $byId["hotkey-bindings"].Ok "geometry changes never create binding drift"

        # A managed core without the include contract fails hotkey-target.
        $noInclude = (New-DevWSTerminalShortcutContent -AppScriptPath $appScript -BindingsPath $bindingsPath) -replace '(?m)^#Include.*\r?\n', ''
        Set-Content -LiteralPath $corePath -Value $noInclude -NoNewline

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal $false $byId["hotkey-target"].Ok "missing include contract fails hotkey-target"
        Assert-Contains $byId["hotkey-target"].Message "install.ps1" "include drift names the installer recovery"
    }

