    Test-Case "lifecycle mutex serializes concurrent child processes without overlap" {
        $childPath = Join-Path $TestRoot "lifecycle-child.ps1"
        $childSource = @'
param(
    [Parameter(Mandatory)][string]$MutexName,
    [Parameter(Mandatory)][string]$Id,
    [Parameter(Mandatory)][string]$LogPath,
    [double]$HoldSeconds = 1,
    [int]$TimeoutSeconds = 120,
    [switch]$Abandon
)

. "@@LIBDIR@@/devws-lifecycle.ps1"

Invoke-DevWSWithLifecycleLock -MutexName $MutexName -TimeoutSeconds $TimeoutSeconds -ScriptBlock {
    Add-Content -LiteralPath $LogPath -Value "enter $Id"

    if ($Abandon) {
        [System.Environment]::Exit(0)
    }

    Start-Sleep -Milliseconds ([int]($HoldSeconds * 1000))
    Add-Content -LiteralPath $LogPath -Value "exit $Id"
} | Out-Null
'@

        Set-Content -LiteralPath $childPath -Value $childSource.Replace("@@LIBDIR@@", $LibDir) -NoNewline

        $logPath   = Join-Path $TestRoot "lifecycle-serial.log"
        $mutexName = "Local\DevWS.Tests." + [guid]::NewGuid().ToString("N")

        $childA = Start-Process -FilePath "pwsh" -ArgumentList @(
            "-NoLogo", "-NoProfile", "-File", "`"$childPath`"",
            "-MutexName", $mutexName, "-Id", "A", "-LogPath", "`"$logPath`"",
            "-HoldSeconds", "2", "-TimeoutSeconds", "60"
        ) -PassThru

        $deadline = (Get-Date).AddSeconds(30)

        while ((Get-Date) -lt $deadline) {
            if ((Test-Path -LiteralPath $logPath) -and ((Get-Content -LiteralPath $logPath -Raw) -match 'enter A')) {
                break
            }

            Start-Sleep -Milliseconds 100
        }

        Assert-True ((Test-Path -LiteralPath $logPath) -and ((Get-Content -LiteralPath $logPath -Raw) -match 'enter A')) "first child acquired the mutex"

        $childB = Start-Process -FilePath "pwsh" -ArgumentList @(
            "-NoLogo", "-NoProfile", "-File", "`"$childPath`"",
            "-MutexName", $mutexName, "-Id", "B", "-LogPath", "`"$logPath`"",
            "-HoldSeconds", "0.2", "-TimeoutSeconds", "60"
        ) -PassThru

        Assert-True $childA.WaitForExit(60000) "first child exits"
        Assert-True $childB.WaitForExit(60000) "second child exits"
        Assert-Equal 0 $childA.ExitCode "first child exit code"
        Assert-Equal 0 $childB.ExitCode "second child exit code"

        $lines = @(Get-Content -LiteralPath $logPath | Where-Object { $_ -ne "" })
        Assert-Equal "enter A,exit A,enter B,exit B" ($lines -join ",") "critical sections never overlap and execution is serialized"
    }

    Test-Case "lifecycle lock timeout is actionable and the lock frees afterwards" {
