        $child = Start-Process -FilePath "pwsh" -ArgumentList @(
            "-NoLogo", "-NoProfile", "-File", "`"$childPath`"",
            "-MutexName", $mutexName, "-Id", "H", "-LogPath", "`"$logPath`"",
            "-HoldSeconds", "5", "-TimeoutSeconds", "60"
        ) -PassThru

        $deadline = (Get-Date).AddSeconds(30)

