    Test-Case "launch live side effects stay inside the lock while validation stays outside" {
        $target = New-LifecycleConfigCopy "lifecycle-lock-launch"
        $calls  = [System.Collections.Generic.List[object]]::new()

        $previousConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        $script:lockInvocations = 0
        $script:lockHeld = $false

        try {
            function Invoke-DevWSWithLifecycleLock {
                param([Parameter(Mandatory)][scriptblock]$ScriptBlock, [int]$TimeoutSeconds = 300, [string]$MutexName = "test")

                $script:lockInvocations++
                $script:lockHeld = $true

                try {
                    return (& $ScriptBlock)
                }
                finally {
                    $script:lockHeld = $false
                }
            }

            function Start-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = "worker-start"; LockHeld = $script:lockHeld })
                return [pscustomobject]@{ Kind = $Kind; TaskName = $TaskName; RequestId = "stub"; RequestPath = "stub-req"; ResultPath = "stub-res"; TimeoutSeconds = $TimeoutSeconds }
            }

            function Complete-DevWSWorkerRequest {
                param($Request)
                $calls.Add([pscustomobject]@{ Kind = "worker-complete"; LockHeld = $script:lockHeld })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                return @()
            }

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                $calls.Add([pscustomobject]@{ Kind = "resolve"; SetId = $SetId; AppId = [string]$App.id; LockHeld = $script:lockHeld })
                return [long](600000 + $calls.Count)
            }

            function Move-DevWSWindowHwnd {
                param([long]$Hwnd, $Layout, [string]$Context)
                $calls.Add([pscustomobject]@{ Kind = "move"; Context = $Context; X = $Layout.x; LockHeld = $script:lockHeld })
            }

            Invoke-DevWSLaunch -SetId "secondary"

            Assert-Equal 1 $script:lockInvocations "launch acquires the lifecycle lock exactly once"
            Assert-True ($calls.Count -gt 0) "launch performed live work"
            Assert-Equal $false $script:lockHeld "lock released after the launch"

            foreach ($call in $calls) {
                Assert-Equal $true $call.LockHeld "live side effect '$($call.Kind)' ran inside the lock"
            }

            # Pure validation must fail before the lock and without live effects.
            $config = Read-DevWSConfigFile -Path $target
            $mainTerminal = @((@($config.sets | Where-Object { $_.id -eq "main" })[0].windows) | Where-Object { $_.type -eq "terminal" })[0]
            $mainTerminal.path = Join-Path $TestRoot "lifecycle-missing-dir"
            $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

            $script:lockInvocations = 0
            $calls.Clear()

            Assert-Throws { Invoke-DevWSLaunch -SetId "main" } "does not exist" "missing path fails validation"

            Assert-Equal 0 $script:lockInvocations "validation failure occurs before the lock"
            Assert-Equal 0 $calls.Count "validation failure performs no live side effects"
        }
        finally {
            if ($null -eq $previousConfig) { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue } else { $env:DEVWS_CONFIG = $previousConfig }
        }
    }

