    Test-Case "Phase 10 split worker Start obtains ACCEPTED and never waits for the result" {
        $case = New-WorkerPipeFixtureCase -Name "p10-start-accepted" -Kind "launch" -Mode "wait-release"
        . (New-WorkerPipeFixtureExpectation -Case $case -Kind "launch")

        try {
            $watch = [System.Diagnostics.Stopwatch]::StartNew()
            $handle = Start-DevWSWorkerRequest -Kind "launch" -TaskName "DevWorkspace-ElevatedHelper" -Payload @{ setId = "probe"; terminalPlacements = @() } -TimeoutSeconds 60
            $watch.Stop()

            Assert-Equal "launch" $handle.Kind "handle kind"
            Assert-Equal "DevWorkspace-ElevatedHelper" $handle.TaskName "handle task binding"
            Assert-Equal 60 $handle.TimeoutSeconds "handle timeout"
            Assert-True (-not [string]::IsNullOrWhiteSpace([string]$handle.RequestId)) "fresh request id"
            Assert-True ($null -ne $handle.Connection) "live connection carried by the handle"
            Assert-True ($handle.ServerPid -gt 0) "authenticated server pid recorded"

            # Start returned at ACCEPTED: the terminal operation is still in its
            # execution window (wait-release), so Start cannot have waited for
            # the FINAL result.
            $logMid = Get-Content -LiteralPath $case.Log -Raw
            Assert-True ($logMid -notmatch [regex]::Escape("final-sent")) "Start returned before FINAL was produced"

            Set-Content -LiteralPath $case.Release -Value "go" -Encoding UTF8
            $result = Complete-DevWSWorkerRequest -Request $handle
            Assert-Equal $true $result.ok "completion settled"
            Assert-Equal $handle.RequestId $result.requestId "result correlation"
        }
        finally { Stop-WorkerPipeFixtureProcess -Case $case }
    }

