    Test-Case "Phase 10 Pass 1 source guards keep the overlap protocol-only" {
        $protocol = Get-SourceOf "src\lib\devws-worker-protocol.ps1"
        $ws = Get-SourceOf "src\ws.ps1"
        $launch = Get-SourceOf "src\lib\devws-launch.ps1"

        Assert-Contains $protocol "function Start-DevWSWorkerRequest" "split start implemented"
        Assert-Contains $protocol "function Complete-DevWSWorkerRequest" "split completion implemented"
        Assert-Contains $protocol "function Start-DevWSScheduledTask" "scheduled task invocation factored"
        Assert-Contains $protocol "function Invoke-DevWSWorkerRequest" "compatibility wrapper preserved"
        Assert-Contains $ws "Invoke-DevWSLaunchTransaction" "the CLI delegates to the canonical launch transaction"
        Assert-Contains $launch "Start-DevWSWorkerRequest" "launch begins the worker"
        Assert-Contains $launch "Complete-DevWSWorkerRequest" "launch settles the worker"
        Assert-Contains $launch "-TimeoutSeconds 120" "launch worker timeout unchanged"

        $engine = $launch + "`n" + $protocol

        foreach ($forbidden in @(
            "Start-Job", "ThreadJob", "Runspace", "ForEach-Object -Parallel",
            "firefox", "codex", "antigravity", "scratch", "studio", "chrome", "davinci", "blender"
        )) {
            Assert-NotContains $engine $forbidden "overlap stays protocol-only: $forbidden"
        }

        Assert-Equal 1 ([regex]::Matches($launch, "DevWorkspace-ElevatedHelper")).Count "exactly one launch worker task"
        Assert-Equal 0 ([regex]::Matches($engine, [regex]::Escape("Local\DevWS.Lifecycle"))).Count "no second lifecycle mutex in the launch engine"

        # Stage 2: the transaction drives the broker first and keeps the Helper
        # strictly as the pre-GO fallback with the post-GO no-fallback boundary.
        Assert-Contains $launch "New-DevWSElevatedBrokerPrepare" "broker prepare initiated"
        Assert-Contains $launch "Wait-DevWSElevatedBrokerPrepare" "broker READY settled after the concurrent app prepare"
        Assert-Contains $launch "Send-DevWSElevatedBrokerGo" "GO barrier sent"
        Assert-Contains $launch "Read-DevWSElevatedBrokerFinal" "broker FINAL read after GO-ACK"
        Assert-Contains $launch "stage2-helper-fallback" "pre-GO helper fallback marker"
        Assert-Contains $launch "BrokerUncertain" "post-GO-ACK uncertainty is explicit"
        Assert-Contains $launch "no terminal work will be repeated" "post-GO-ACK failure never repeats terminal work"

        # The fallback block must be reachable only when no GO-ACK was received:
        # the go-ack branch returns before the fallback marker in source order.
        $goAckIndex = $launch.IndexOf('type -eq "go-ack"')
        $fallbackIndex = $launch.IndexOf("stage2-helper-fallback")
        Assert-True ($goAckIndex -ge 0 -and $fallbackIndex -gt $goAckIndex) "the fallback path follows the GO-ACK branch"

        # Timeouts, polling and readiness rules unchanged.
        Assert-Contains $protocol "Start-Sleep -Milliseconds 100" "worker result polling unchanged"
        Assert-Contains (Get-SourceOf "src\lib\devws-app-window.ps1") "DevWSAppLaunchTimeoutSecondsDefault = 12" "app launch ceiling unchanged"
        Assert-Contains (Get-SourceOf "src\lib\devws-app-window.ps1") "DevWSAppLaunchPollMillisecondsDefault = 500" "app polling unchanged"
        Assert-Contains (Get-SourceOf "src\lib\devws-lifecycle.ps1") "Local\DevWS.Lifecycle.v1" "lifecycle mutex name unchanged"
        Assert-Contains (Get-SourceOf "src\lib\devws-lifecycle.ps1") "return 300" "lifecycle timeout unchanged"
        $terminalLib = Get-SourceOf "src\lib\devws-terminal-launch.ps1"
        Assert-Contains $terminalLib "IdentityTimeoutSecondsDefault = 15" "terminal identity ceiling unchanged"
        Assert-Contains $terminalLib "Test-DevWSCreatedTabCount" "raw tab-count guard retained"
        Assert-Contains $terminalLib "PollMilliseconds = `$script:DevWSTerminalLaunchPollMillisecondsDefault" "terminal polling retained"
    }

    Write-Host ""
    Start-TestGroup -Name 'p10-pass2' -Title 'Phase 10 Pass 2 terminal batching'

    Test-Case "Phase 10 Pass 2 kickoff starts every missing terminal before any finalization" {
        $fixture = New-BatchedWorkerFixture -Name "p2-all-missing" -Terminals @(
            (New-TerminalDefinition -Id "api"   -WindowId "DevWS-p2-api"   -Path $TestRoot),
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2-build" -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"  -WindowId "DevWS-p2-logs"  -Path $TestRoot)
        )

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 0 $run.ExitCode "worker exits cleanly"
        Assert-Equal $true ([bool]$run.Result.ok) "worker reports success"
        Assert-Equal "OK" ([string]$run.Result.message) "success message unchanged"

        $events = @(Get-BatchedWorkerEvents $run)
        $expected = @(
            "tracking api", "create-args api",
            "tracking build", "create-args build",
            "tracking logs", "create-args logs",
            "kick api", "kick build", "kick logs",
            "move api", "state api",
            "move build", "state build",
            "move logs", "state logs"
        )
        Assert-Equal ($expected -join "|") ($events -join "|") "all creates precede all kickoffs and one shared loop finalizes in configured order"

        $firstKick = [array]::IndexOf($events, "kick api")
        foreach ($id in @("api", "build", "logs")) {
            $createIndex = [array]::IndexOf($events, "create-args $id")
            Assert-True ($createIndex -ge 0 -and $createIndex -lt $firstKick) "create-args $id precedes the first kickoff"
        }

        Assert-Equal 3 @($run.Calls | Where-Object { $_.e -eq "create-args" }).Count "one create-argument build per missing terminal"
        Assert-Equal 3 @($run.Calls | Where-Object { $_.e -eq "kick" }).Count "one WT invocation per missing terminal"
        Assert-Equal 3 @($run.Calls | Where-Object { $_.e -eq "tabguard" }).Count "tab-count guard ran for every created terminal"

        foreach ($id in @("api", "build", "logs")) {
            Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "kick" -and $_.id -eq $id }).Count "one kick for $id"
            Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "move" -and $_.id -eq $id }).Count "one move for $id"
            Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq $id }).Count "one runtime-state update for $id"
        }
    }

    Test-Case "Phase 10 Pass 2 mixed present and missing terminals keep identity semantics" {
        $fixture = New-BatchedWorkerFixture -Name "p2-mixed" -Terminals @(
            (New-TerminalDefinition -Id "api"      -WindowId "DevWS-p2m-api"      -Path $TestRoot),
            (New-TerminalDefinition -Id "build"    -WindowId "DevWS-p2m-build"    -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"     -WindowId "DevWS-p2m-logs"     -Path $TestRoot),
            (New-TerminalDefinition -Id "worker42" -WindowId "DevWS-p2m-worker42" -Path $TestRoot)
        ) -Control @{ present = @("api", "logs"); presentSource = @{ api = "uia"; logs = "state" } }

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 0 $run.ExitCode "worker exits cleanly"
        Assert-Equal $true ([bool]$run.Result.ok) "worker reports success"

        $events = @(Get-BatchedWorkerEvents $run)
        $expected = @(
            "tracking build", "create-args build",
            "tracking worker42", "create-args worker42",
            "kick build", "kick worker42",
            "move api", "select api", "state api",
            "move logs", "select logs",
            "move build", "state build",
            "move worker42", "state worker42"
        )
        Assert-Equal ($expected -join "|") ($events -join "|") "missing kickoff precedes present finalization"

        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -in @("tracking", "create-args") -and $_.id -in @("api", "logs") }).Count "present terminals are never tracked or created"
        Assert-Equal 2 @($run.Calls | Where-Object { $_.e -eq "kick" }).Count "one WT invocation per missing terminal"

        $firstMove = [array]::IndexOf($events, "move api")
        Assert-True ([array]::IndexOf($events, "kick worker42") -lt $firstMove) "the last missing kickoff precedes the first present finalization"

        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "select" -and $_.id -eq "api" }).Count "present activeTab selected once"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "api" }).Count "UIA-sourced present identity refreshes runtime state"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "logs" }).Count "state-sourced present identity performs no refresh"

        $tracking = @($run.Calls | Where-Object { $_.e -eq "tracking" })
        Assert-Equal 2 $tracking.Count "one fresh generation per missing terminal"
        Assert-True (-not [string]::IsNullOrWhiteSpace([string]$tracking[0].d)) "tracking context carries a session id"
        Assert-True ($tracking[0].d -ne $tracking[1].d) "missing terminals receive distinct tracking sessions"
    }

    Test-Case "Phase 10 Pass 2 all-present launches never track, create, or kick" {
        $fixture = New-BatchedWorkerFixture -Name "p2-all-present" -Terminals @(
            (New-TerminalDefinition -Id "api"   -WindowId "DevWS-p2p-api"   -Path $TestRoot),
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2p-build" -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"  -WindowId "DevWS-p2p-logs"  -Path $TestRoot)
        ) -Control @{ present = @("api", "build", "logs"); presentSource = @{ api = "uia" } }

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 0 $run.ExitCode "worker exits cleanly"
        Assert-Equal $true ([bool]$run.Result.ok) "worker reports success"

        $events = @(Get-BatchedWorkerEvents $run)
        $expected = @(
            "move api", "select api", "state api",
            "move build", "select build",
            "move logs", "select logs"
        )
        Assert-Equal ($expected -join "|") ($events -join "|") "present terminals are only moved and selected"

        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -in @("tracking", "create-args", "kick", "tabguard") }).Count "no tracking, creation, kickoff or count guard for present terminals"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" }).Count "only UIA-sourced identity refreshes runtime state"
    }

    Test-Case "Phase 10 Pass 2 a single missing terminal keeps the classic sequence" {
        $fixture = New-BatchedWorkerFixture -Name "p2-single" -Terminals @(
            (New-TerminalDefinition -Id "api" -WindowId "DevWS-p2s-api" -Path $TestRoot))

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 0 $run.ExitCode "worker exits cleanly"
        Assert-Equal $true ([bool]$run.Result.ok) "worker reports success"
        Assert-Equal "tracking api|create-args api|kick api|move api|state api" ((Get-BatchedWorkerEvents $run) -join "|") "single-terminal behavior unchanged"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "kick" }).Count "one WT invocation"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "tabguard" }).Count "tab guard ran once"
    }

    Test-Case "Phase 10 Pass 2 tracking failure does not block other terminals" {
        $fixture = New-BatchedWorkerFixture -Name "p2-tracking-fail" -Terminals @(
            (New-TerminalDefinition -Id "api"   -WindowId "DevWS-p2t-api"   -Path $TestRoot),
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2t-build" -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"  -WindowId "DevWS-p2t-logs"  -Path $TestRoot)
        ) -Control @{ trackingFail = @("build") }

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 1 $run.ExitCode "worker fails"
        Assert-Equal $false ([bool]$run.Result.ok) "result reports failure"
        Assert-Contains ([string]$run.Result.message) "Terminal 'build'" "failed terminal named"
        Assert-Contains ([string]$run.Result.message) "tracking-boom" "tracking error surfaced"

        $events = @(Get-BatchedWorkerEvents $run)
        Assert-Equal "tracking api|create-args api|tracking logs|create-args logs|kick api|kick logs|move api|state api|move logs|state logs" ($events -join "|") "later terminals still start and finalize"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "kick" -and $_.id -eq "build" }).Count "failed terminal is never kicked"
        Assert-Equal 2 @($run.Calls | Where-Object { $_.e -eq "kick" }).Count "only successful kickoffs invoke WT"
    }

    Test-Case "Phase 10 Pass 2 create kickoff failure does not block other terminals" {
        $fixture = New-BatchedWorkerFixture -Name "p2-createarg-fail" -Terminals @(
            (New-TerminalDefinition -Id "api"   -WindowId "DevWS-p2c-api"   -Path $TestRoot),
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2c-build" -Path $TestRoot),
