        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 1 $run.ExitCode "worker fails"
        Assert-Equal $false ([bool]$run.Result.ok) "result reports failure"
        Assert-Contains ([string]$run.Result.message) "create-arg-boom" "create kickoff error surfaced"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "kick" -and $_.id -eq "build" }).Count "failed terminal is never kicked"
        Assert-Equal 2 @($run.Calls | Where-Object { $_.e -eq "kick" }).Count "later terminals still create"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "logs" }).Count "later terminals still finalize"
    }

    Test-Case "Phase 10 Pass 2 WT invocation failure is recorded without awaiting that terminal" {
        $fixture = New-BatchedWorkerFixture -Name "p2-wt-throw" -Terminals @(
            (New-TerminalDefinition -Id "api" -WindowId "DevWS-p2w-api" -Path $TestRoot)) `
