        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 1 $run.ExitCode "worker fails"
        Assert-Equal $false ([bool]$run.Result.ok) "result reports failure"
        Assert-Contains ([string]$run.Result.message) "Terminal 'api'" "failed terminal named"
        Assert-Contains ([string]$run.Result.message) "wt-boom" "invocation error surfaced"
        Assert-Equal "tracking api|create-args api" ((Get-BatchedWorkerEvents $run) -join "|") "no finalization after a failed invocation"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "move" }).Count "failed invocation is never awaited"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "tabguard" }).Count "no count guard after a failed invocation"
    }

    Test-Case "Phase 10 Pass 2 first finalization failure settles the remaining terminals" {
        $fixture = New-BatchedWorkerFixture -Name "p2-hwnd-fail" -Terminals @(
            (New-TerminalDefinition -Id "api"   -WindowId "DevWS-p2h-api"   -Path $TestRoot),
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2h-build" -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"  -WindowId "DevWS-p2h-logs"  -Path $TestRoot)
        ) -Control @{ hwndFail = @("api") }

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 1 $run.ExitCode "worker fails"
        Assert-Contains ([string]$run.Result.message) "could not be identified" "actionable identity failure"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "move" -and $_.id -eq "build" }).Count "second terminal still finalized"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "logs" }).Count "third terminal still finalized"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "move" -and $_.id -eq "api" }).Count "failed terminal is not moved"
        Assert-Equal 3 @($run.Calls | Where-Object { $_.e -eq "kick" }).Count "all kickoffs already happened"
    }

    Test-Case "Phase 10 Pass 2 tab-count safety failure stops only that terminal" {
        $fixture = New-BatchedWorkerFixture -Name "p2-tabcount-fail" -Terminals @(
            (New-TerminalDefinition -Id "api"   -WindowId "DevWS-p2b-api"   -Path $TestRoot),
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2b-build" -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"  -WindowId "DevWS-p2b-logs"  -Path $TestRoot)
        ) -Control @{ tabCounts = @{ logs = 3 } }

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 1 $run.ExitCode "worker fails"
        Assert-Contains ([string]$run.Result.message) "the window reports 3 tabs for 2 configured tabs" "existing safety error preserved"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "move" -and $_.id -eq "logs" }).Count "failed terminal is not moved"
        Assert-Equal 0 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "logs" }).Count "failed terminal does not update runtime state"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "api" }).Count "earlier terminal finalized"
        Assert-Equal 1 @($run.Calls | Where-Object { $_.e -eq "state" -and $_.id -eq "build" }).Count "later terminal finalized"
    }

    Test-Case "Phase 10 Pass 2 invalid elevation fails the request before any terminal work" {
        $badTerminal = New-TerminalDefinition -Id "api" -WindowId "DevWS-p2e-api" -Path $TestRoot
        $badTerminal.elevated = $false

        $fixture = New-BatchedWorkerFixture -Name "p2-elevated-false" -Terminals @(
            $badTerminal,
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2e-build" -Path $TestRoot)
        )

