        Assert-Equal 1 $run.ExitCode "worker fails"
        Assert-Contains ([string]$run.Result.message) "has elevated=false" "elevation error preserved"
        Assert-Equal 0 @($run.Calls).Count "no terminal work at all for an invalid elevation configuration"
    }

    Test-Case "Phase 10 Pass 2 aggregated errors follow configured terminal order" {
        $fixture = New-BatchedWorkerFixture -Name "p2-error-order" -Terminals @(
            (New-TerminalDefinition -Id "build" -WindowId "DevWS-p2o-build" -Path $TestRoot),
            (New-TerminalDefinition -Id "logs"  -WindowId "DevWS-p2o-logs"  -Path $TestRoot)
        ) -Control @{ trackingFail = @("build"); hwndFail = @("logs") }

        $run = Invoke-BatchedWorkerRun -Fixture $fixture

        Assert-Equal 1 $run.ExitCode "worker fails"
        $message = [string]$run.Result.message
        $buildIndex = $message.IndexOf("Terminal 'build'", [StringComparison]::Ordinal)
        $logsIndex  = $message.IndexOf("Terminal 'logs'", [StringComparison]::Ordinal)
        Assert-True ($buildIndex -ge 0 -and $logsIndex -gt $buildIndex) "classification error precedes finalization error in configured order"
        Assert-Contains $message "tracking-boom" "classification error included"
        Assert-Contains $message "could not be identified" "finalization error included"
    }

    Test-Case "Phase 10 Pass 2 source guards keep batching loop-thread-free" {
        $worker = Get-SourceOf "src\workers\elevated.ps1"

        foreach ($forbidden in @("Start-Job", "ThreadJob", "Runspace", "ForEach-Object -Parallel", "Start-ThreadJob")) {
            Assert-NotContains $worker $forbidden "batching must not introduce thread concurrency: $forbidden"
        }

        foreach ($forbidden in @("firefox", "codex", "antigravity", "slot", "studio", "scratch", "chrome", "davinci", "blender", "api", "build", "logs", "worker42")) {
            Assert-NotContains $worker $forbidden "batching must stay item-id agnostic: $forbidden"
        }

        Assert-Equal 0 ([regex]::Matches($worker, "Start-Sleep").Count) "worker adds no fixed sleep"
        Assert-Equal 1 ([regex]::Matches($worker, "Get-DevWSTerminalLaunchPlan").Count) "single canonical plan call site"
        Assert-Equal 1 ([regex]::Matches($worker, "Start-DevWSTerminalLaunchPlan").Count) "single canonical kickoff call site"
        Assert-Equal 1 ([regex]::Matches($worker, "Complete-DevWSTerminalLaunchPlan").Count) "single canonical completion call site"
        Assert-NotContains $worker "Wait-DevWSTerminalHwnd" "the worker no longer waits per terminal"
        Assert-NotContains $worker "New-DevWSTerminalCreateArguments" "creation arguments live in the canonical library"
        Assert-NotContains $worker "New-DevWSCwdTrackingContext" "tracking policy lives in the canonical library"

        $library = Get-SourceOf "src\lib\devws-terminal-launch.ps1"
        Assert-Equal 1 ([regex]::Matches($library, "Start-DevWSTerminalLaunchPlan").Count) "single kickoff implementation"
        Assert-Equal 1 ([regex]::Matches($library, "Complete-DevWSTerminalLaunchPlan").Count) "single completion implementation"
        Assert-Contains $library "refusing to choose" "duplicate windowId refuses instead of guessing"
        Assert-Contains $library "State -ne `"missing`"" "only missing terminals are kicked"
        Assert-Contains $library "EmptyRetryCount" "zero-tab retry policy retained"
        Assert-Contains $library "EmptyRetryDelayMilliseconds" "zero-tab retry delay retained"
    }


    Write-Host ""
    Start-TestGroup -Name 'p10-pass3' -Title 'Phase 10 Pass 3 shared app discovery'

    Test-Case "Phase 10 Pass 3 warm multi-app launch takes one shared probe" {
        $target = New-Pass3ProbeConfig "p3-warm-apps"
        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target
        $script:p3ProbeCount = 0
        $script:p3Resolved = [System.Collections.Generic.List[string]]::new()
        $script:p3Moved = [System.Collections.Generic.List[string]]::new()
        $script:p3Launches = 0

        try {
            function Invoke-DevWSWithLifecycleLock {
                param([Parameter(Mandatory)][scriptblock]$ScriptBlock, [int]$TimeoutSeconds = 300, [string]$MutexName = "test")
                return (& $ScriptBlock)
            }

            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                $script:p3ProbeCount++
                return @()
            }

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                $script:p3Resolved.Add([string]$App.id)
                return [long](810000 + $script:p3Resolved.Count)
            }

            function Move-DevWSWindowHwnd {
                param([long]$Hwnd, $Layout, [string]$Context)
                $script:p3Moved.Add($Context)
            }

            function Invoke-DevWSAppLaunchCommand {
                param($App)
                $script:p3Launches++
            }

            Invoke-DevWSLaunch -SetId "apps3"

            Assert-Equal 1 $script:p3ProbeCount "one shared initial app probe for the three-app set"
            Assert-Equal "renderer,editor42,browser" ($script:p3Resolved -join ",") "apps resolved in configured order"
            Assert-Equal 3 $script:p3Moved.Count "each resolved app moved exactly once"
            Assert-Equal 0 $script:p3Launches "no launch command for already-present apps"
        }
        finally {
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

