    Test-Case "Phase 10 Pass 3 terminal-only launch performs zero app probes" {
        $target = New-Pass3ProbeConfig "p3-no-apps"
        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target
        $script:p3ProbeCount = 0
        $script:p3WorkerStarts = 0
        $script:p3WorkerCompletes = 0

        try {
            function Invoke-DevWSWithLifecycleLock {
                param([Parameter(Mandatory)][scriptblock]$ScriptBlock, [int]$TimeoutSeconds = 300, [string]$MutexName = "test")
                return (& $ScriptBlock)
            }

            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                $script:p3ProbeCount++
                throw "app probe must not run for a terminal-only set"
            }

            function Start-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $script:p3WorkerStarts++
                return [pscustomobject]@{ Kind = $Kind; TaskName = $TaskName; RequestId = "r"; RequestPath = "rp"; ResultPath = "rn"; TimeoutSeconds = $TimeoutSeconds }
            }

            function Complete-DevWSWorkerRequest {
                param($Request)
                $script:p3WorkerCompletes++
                return [pscustomobject]@{ requestId = $Request.RequestId; ok = $true; message = "OK" }
            }

            Invoke-DevWSLaunch -SetId "termsonly"

            Assert-Equal 0 $script:p3ProbeCount "no app probe for a terminal-only set"
            Assert-Equal 1 $script:p3WorkerStarts "terminal worker still starts"
            Assert-Equal 1 $script:p3WorkerCompletes "terminal worker still settles"
        }
        finally {
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

