                    (New-TestProbedWindow -Hwnd 20 -ProcessName "other" -ProcessPath "C:\Apps\other.exe"),
                    (New-TestProbedWindow -Hwnd 30 -ProcessName "other" -ProcessPath "C:\Apps\other.exe")
                )
            }

            return @(
                (New-TestProbedWindow -Hwnd 10 -ProcessName "other" -ProcessPath "C:\Apps\other.exe"),
                (New-TestProbedWindow -Hwnd 20 -ProcessName "other" -ProcessPath "C:\Apps\other.exe"),
                (New-TestProbedWindow -Hwnd 30 -ProcessName "other" -ProcessPath "C:\Apps\other.exe"),
