    Test-Case "Phase 10 Pass 3 source guards keep probing config-driven" {
        $ws = Get-SourceOf "src\ws.ps1"
        $launch = Get-SourceOf "src\lib\devws-launch.ps1"
        $appWindow = Get-SourceOf "src\lib\devws-app-window.ps1"

        # The canonical transaction batch has exactly four probe call sites:
        # Phase A (shared classification), Phase B (one fresh refresh), the
        # Stage 2 age-guard refresh (exactly once) and Phase D (one shared
        # probe per finalization tick).
        Assert-Equal 4 ([regex]::Matches($launch, "Get-DevWSAppWindowProbe")).Count "four batch probe call sites"
        Assert-Equal 3 ([regex]::Matches($launch, "-InitialProbe")).Count "shared, fresh and age-guard probes passed to classification"
        Assert-Contains $launch "one shared snapshot classifies every app" "Phase A documented"
        Assert-Contains $launch "exactly one fresh batch refresh" "Phase B documented"
        Assert-Contains $launch "move every present app, then invoke every genuinely missing" "Phase C documented"
        Assert-Contains $launch "one shared polling loop for every kicked app" "Phase D documented"
        Assert-Equal 1 ([regex]::Matches($launch, "Start-Sleep")).Count "one shared finalization tick sleep"
        Assert-Contains $ws "Invoke-DevWSLaunchTransaction" "CLI uses the canonical transaction"

        Assert-Contains $appWindow "function Set-DevWSProbedWindowOwnership" "snapshot ownership helper exists"
        Assert-Contains $appWindow 'if ($selection.Status -eq "missing" -and $Operation -eq "launch" -and $hasInitialProbe)' "launch-time refresh guard present"
        Assert-Equal 1 ([regex]::Matches($appWindow, "Start-Sleep")).Count "only the existing resolver poll sleep remains"
        Assert-Contains $appWindow "DevWSAppLaunchTimeoutSecondsDefault = 12" "app launch ceiling unchanged"
        Assert-Contains $appWindow "DevWSAppLaunchPollMillisecondsDefault = 500" "app poll unchanged"
        Assert-Contains $launch "-LaunchTimeoutSeconds `$script:DevWSAppLaunchTimeoutSecondsDefault" "canonical finalization honors the app launch ceiling"
        Assert-NotContains $launch "Invoke-DevWSAppBatch" "the dead compatibility wrapper stays removed"

        foreach ($forbidden in @("Start-Job", "ThreadJob", "Runspace", "ForEach-Object -Parallel", "Start-ThreadJob")) {
            Assert-NotContains $appWindow $forbidden "app probing stays single-threaded: $forbidden"
            Assert-NotContains $launch $forbidden "launch stays single-threaded: $forbidden"
        }

        foreach ($forbidden in @("firefox", "codex", "antigravity", "chrome", "davinci", "blender", "renderer", "editor42", "browser")) {
            Assert-NotContains $appWindow $forbidden "app probing stays item-id agnostic: $forbidden"
            Assert-NotContains $launch $forbidden "launch stays item-id agnostic: $forbidden"
        }

        $worker = Get-SourceOf "src\workers\elevated.ps1"
        Assert-Contains $worker "Get-DevWSTerminalLaunchPlan" "Pass 2 policy now lives in the canonical terminal-launch library"
        Assert-NotContains $worker "InitialProbe" "terminal worker untouched by Pass 3"
    }


