    Test-Case "focus resolves every app from one shared probe snapshot" {
        $target = New-Pass3ProbeConfig "sfp-focus-snapshot"
        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            $script:sfpProbeCount = 0
            $script:sfpProbedReceived = [System.Collections.Generic.List[object]]::new()
            $script:sfpFocused = [System.Collections.Generic.List[long]]::new()
            $script:sfpRecords = @(
                (New-TestProbedWindow -Hwnd 7001 -ProcessName "renderer" -ProcessPath "C:\Apps\renderer.exe" -OwnerKey "apps3/renderer"),
                (New-TestProbedWindow -Hwnd 7002 -ProcessName "editor42" -ProcessPath "C:\Apps\editor42.exe"),
                (New-TestProbedWindow -Hwnd 7003 -ProcessName "browser" -ProcessPath "C:\Apps\browser.exe" -OwnerKey "apps3/browser")
            )

            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                $script:sfpProbeCount++
                return $script:sfpRecords
            }

            function Resolve-DevWSAppWindowSelection {
                param($Probed, [string]$SetId, [string]$ItemId, $Match, [string]$Mode, [string]$Operation)
                $script:sfpProbedReceived.Add([object[]]@($Probed))
                $hwnd = if ($ItemId -eq "renderer") { [long]7001 } elseif ($ItemId -eq "editor42") { [long]7002 } else { [long]7003 }
                return [pscustomobject]@{ Status = "resolved"; Hwnd = $hwnd; Message = $null }
            }

            function Focus-DevWSWindowHwnd {
                param([long]$Hwnd, [string]$Context)
                $script:sfpFocused.Add($Hwnd)
            }

            Invoke-DevWSFocus -SetId "apps3"

            Assert-Equal 1 $script:sfpProbeCount "focus probes exactly once"
            Assert-Equal 3 $script:sfpProbedReceived.Count "every app resolved through the shared snapshot"

            for ($i = 1; $i -lt $script:sfpProbedReceived.Count; $i++) {
                Assert-True ([object]::ReferenceEquals($script:sfpProbedReceived[0][0], $script:sfpProbedReceived[$i][0])) "app $i receives the same first probe record object"
                Assert-True ([object]::ReferenceEquals($script:sfpProbedReceived[0][2], $script:sfpProbedReceived[$i][2])) "app $i receives the same last probe record object"
            }

            Assert-Equal "7001,7002,7003" (($script:sfpFocused) -join ",") "resolved HWNDs focused in configured order"
        }
        finally {
            if ($null -eq $savedEnv) {
                Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue
            }
            else {
                $env:DEVWS_CONFIG = $savedEnv
            }
        }
    }

