        $ws = Get-SourceOf "src\ws.ps1"

        function Get-SfpRegion([string]$Source, [string]$From, [string]$To) {
            $start = $Source.IndexOf("function $From")
            $end   = $Source.IndexOf("function $To")
            Assert-True ($start -ge 0 -and $end -gt $start) "$From region located"
            return $Source.Substring($start, $end - $start)
        }

        $focusRegion = Get-SfpRegion $ws "Invoke-DevWSFocus" "Get-DevWSLiveLayoutCapture"
        Assert-Equal 1 ([regex]::Matches($focusRegion, "Get-DevWSAppWindowProbe").Count) "exactly one focus probe call site"
        Assert-Equal 1 ([regex]::Matches($focusRegion, "-InitialProbe").Count) "focus passes the shared probe to app resolution"
        Assert-True ($focusRegion.IndexOf("Get-DevWSAppWindowProbe") -lt $focusRegion.IndexOf('foreach ($app in $apps)')) "focus probes before its app loop"

        $captureRegion = Get-SfpRegion $ws "Get-DevWSLiveLayoutCapture" "Get-DevWSTerminalSaveDecisions"
        Assert-Equal 1 ([regex]::Matches($captureRegion, "Get-DevWSAppWindowProbe").Count) "exactly one capture probe call site"
        Assert-Equal 1 ([regex]::Matches($captureRegion, "-InitialProbe").Count) "capture passes the shared probe to app resolution"
        Assert-True ($captureRegion.IndexOf("Get-DevWSAppWindowProbe") -lt $captureRegion.IndexOf('foreach ($app in $apps)')) "capture probes before its app loop"

        $launchRegion = Get-SfpRegion $ws "Invoke-DevWSLaunch" "Invoke-DevWSFocus"
        Assert-Equal 0 ([regex]::Matches($launchRegion, "Get-DevWSAppWindowProbe").Count) "the CLI wrapper owns no probe; the canonical batch does"

        $launchLib = Get-SourceOf "src\lib\devws-launch.ps1"
        Assert-Equal 4 ([regex]::Matches($launchLib, "Get-DevWSAppWindowProbe").Count) "batch probes: shared classification, exactly one fresh refresh, the bounded age-guard refresh, and one shared per-tick probe"

        $appWindow = Get-SourceOf "src\lib\devws-app-window.ps1"
        Assert-Contains $appWindow 'if ($selection.Status -eq "missing" -and $Operation -eq "launch" -and $hasInitialProbe)' "non-launch operations never refresh from a hidden probe"
    }


    Write-Host ""
    Start-TestGroup -Name 'p10-pass4' -Title 'Phase 10 Pass 4 in-process window operations'

    Test-Case "Phase 10 Pass 4 HWND existence is in-process" {
        Assert-Equal $false (Test-DevWSWindowHwnd -Hwnd 0) "zero HWND is not a window"
        Assert-Equal $false (Test-DevWSWindowHwnd -Hwnd -5) "negative HWND is not a window"
        Assert-Equal $false (Test-DevWSWindowHwnd -Hwnd 999999999) "dead HWND is not a window"

        $window = [DevWSTestOwnershipWindow]::Create()
        Assert-True ($window -ne [IntPtr]::Zero) "disposable test window created"

        try {
            Assert-Equal $true (Test-DevWSWindowHwnd -Hwnd ([long]$window)) "live HWND reported existing"
            Assert-Equal $PID (Get-DevWSWindowProcessId -Hwnd ([long]$window)) "PID resolved from the live HWND"
            Assert-Equal (Get-Process -Id $PID).ProcessName (Get-DevWSWindowHwndProcessName -Hwnd ([long]$window)) "process name resolved for the live HWND"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($window)
        }

        Assert-Equal $false (Test-DevWSWindowHwnd -Hwnd ([long]$window)) "destroyed HWND reported gone"
        Assert-True ($null -eq (Get-DevWSWindowHwndProcessName -Hwnd ([long]$window))) "destroyed HWND has no process name"
    }

    Test-Case "Phase 10 Pass 4 process lookup handles zero and stale PIDs" {
        Assert-True ($null -eq (Get-DevWSProcessNameById -ProcessId 0)) "zero PID returns null"
        Assert-True ($null -eq (Get-DevWSProcessNameById -ProcessId -7)) "negative PID returns null"
        Assert-True ($null -eq (Get-DevWSProcessNameById -ProcessId 999999)) "stale PID returns null"
        Assert-Equal (Get-Process -Id $PID).ProcessName (Get-DevWSProcessNameById -ProcessId $PID) "current PID resolves to the test process"

        Assert-Equal 0 (Get-DevWSWindowProcessId -Hwnd 0) "zero HWND has no PID"
        Assert-Equal 0 (Get-DevWSWindowProcessId -Hwnd 999999999) "dead HWND has no PID"

        $source = Get-SourceOf "src\lib\devws-window-ops.ps1"
        Assert-NotContains $source "CimInstance" "no CIM in the hot path"
        Assert-NotContains $source "Win32_Process" "no global process snapshot"
    }

    Test-Case "Phase 10 Pass 4 native move applies the configured outer rectangle" {
        Initialize-DevWSWindowOpsNative
        $window = [DevWSTestOwnershipWindow]::CreatePopup()
        Assert-True ($window -ne [IntPtr]::Zero) "disposable popup created"
        $h = [long]$window

        try {
            Move-DevWSWindowHwnd -Hwnd $h -Layout ([pscustomobject]@{ x = 140; y = 90; w = 520; h = 340 }) -Context "popup 'p4'"
            $rect = [DevWSTestOwnershipWindow]::Rect($window)
            Assert-True ($null -ne $rect) "outer rectangle readable in process"
            Assert-Equal 140 $rect[0] "x applied"
            Assert-Equal 90 $rect[1] "y applied"
            Assert-Equal 520 $rect[2] "w applied"
            Assert-Equal 340 $rect[3] "h applied"

            # The restore helper must be a no-op for a normal (non-minimized,
            # non-maximized) target.
            Restore-DevWSWindowHwnd -Hwnd $h
            Assert-Equal $false ([DevWSWindowOpsNative]::IsIconic([IntPtr]$h)) "normal window stays normal"
            Assert-Equal $false ([DevWSWindowOpsNative]::IsZoomed([IntPtr]$h)) "normal window stays non-maximized"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($window)
        }
    }

    Test-Case "Phase 10 Pass 4 move restores then places with no-activate flags" {
        $script:p4Order = [System.Collections.Generic.List[string]]::new()
        $script:p4Pos = $null

        function Restore-DevWSWindowHwnd {
            param([long]$Hwnd)
            $script:p4Order.Add("restore")
        }

        function Set-DevWSWindowHwndPos {
            param([long]$Hwnd, [int]$X, [int]$Y, [int]$Width, [int]$Height)
            $script:p4Order.Add("setpos")
            $script:p4Pos = [pscustomobject]@{ x = $X; y = $Y; w = $Width; h = $Height }
        }

        $window = [DevWSTestOwnershipWindow]::Create()
        try {
            Move-DevWSWindowHwnd -Hwnd ([long]$window) -Layout ([pscustomobject]@{ x = 120; y = 80; w = 640; h = 360 }) -Context "shaped 'p4'"
        }
        finally {
            [void][DevWSTestOwnershipWindow]::Destroy($window)
        }

        Assert-Equal "restore|setpos" ($script:p4Order -join "|") "restore happens before placement"
        Assert-Equal 120 $script:p4Pos.x "x forwarded"
        Assert-Equal 80 $script:p4Pos.y "y forwarded"
        Assert-Equal 640 $script:p4Pos.w "width forwarded"
        Assert-Equal 360 $script:p4Pos.h "height forwarded"

        $script:p4Order.Clear()
        $message = Get-ThrownMessage {
            Move-DevWSWindowHwnd -Hwnd 999999999 -Layout ([pscustomobject]@{ x = 1; y = 1; w = 10; h = 10 }) -Context "dead 'p4'"
        }
        Assert-Contains $message "Could not position dead 'p4' by HWND 999999999" "dead HWND fails actionably"
        Assert-Equal 0 $script:p4Order.Count "no native placement for a dead HWND"

        $badGeometry = Get-ThrownMessage {
            $probeWindow = [DevWSTestOwnershipWindow]::Create()
            try {
                Move-DevWSWindowHwnd -Hwnd ([long]$probeWindow) -Layout ([pscustomobject]@{ x = 1; y = 1; w = 0; h = 10 }) -Context "bad 'p4'"
            }
            finally {
                [void][DevWSTestOwnershipWindow]::Destroy($probeWindow)
            }
        }
        Assert-Contains $badGeometry "invalid geometry" "invalid geometry fails actionably"

        $source = Get-SourceOf "src\lib\devws-window-ops.ps1"
        Assert-Contains $source "SWP_NOZORDER" "no z-order flag"
        Assert-Contains $source "SWP_NOACTIVATE" "no-activate flag"
        Assert-Contains $source "SW_RESTORE" "restore constant"
    }

    Test-Case "Phase 10 Pass 4 hot path has no AHK process spawns" {
        $source = Get-SourceOf "src\lib\devws-window-ops.ps1"

        function Get-Pass4Body([string]$Source, [string]$Name) {
            $start = $Source.IndexOf("function $Name {")
            Assert-True ($start -ge 0) "function $Name located"
            $next = $Source.IndexOf("`nfunction ", $start + 1)
            if ($next -lt 0) { $next = $Source.Length }
            return $Source.Substring($start, $next - $start)
        }

        foreach ($hot in @("Test-DevWSWindowHwnd", "Get-DevWSWindowHwndProcessName", "Move-DevWSWindowHwnd")) {
            $body = Get-Pass4Body $source $hot
            Assert-NotContains $body "Invoke-DevWSWindowHelper" "$hot must not use the AHK helper"
            Assert-NotContains $body "Invoke-DevWSAhk" "$hot must not invoke AHK"
            Assert-NotContains $body "Start-Process" "$hot must not spawn a process"
        }

        Assert-Contains (Get-Pass4Body $source "Test-DevWSWindowHwnd") "IsWindow" "existence uses IsWindow"
        Assert-Contains (Get-Pass4Body $source "Get-DevWSWindowHwndProcessName") "Get-DevWSProcessNameById" "process name uses the single-PID lookup"
        Assert-Contains (Get-Pass4Body $source "Move-DevWSWindowHwnd") "Restore-DevWSWindowHwnd" "move restores first"
        Assert-Contains (Get-Pass4Body $source "Move-DevWSWindowHwnd") "Set-DevWSWindowHwndPos" "move places through the native wrapper"
        Assert-Contains (Get-Pass4Body $source "Set-DevWSWindowHwndPos") "SetWindowPos" "native placement"
        Assert-Contains (Get-Pass4Body $source "Restore-DevWSWindowHwnd") "SW_RESTORE" "native restore"
        Assert-Contains (Get-Pass4Body $source "Restore-DevWSWindowHwnd") "IsIconic" "restore only when needed"
        Assert-Contains (Get-Pass4Body $source "Restore-DevWSWindowHwnd") "IsZoomed" "maximized targets are restored"
    }

    Test-Case "retained window operations keep native rect and AHK focus/close" {
        $source = Get-SourceOf "src\lib\devws-window-ops.ps1"

        function Get-Pass4Body2([string]$Source, [string]$Name) {
            $start = $Source.IndexOf("function $Name {")
            Assert-True ($start -ge 0) "function $Name located"
            $next = $Source.IndexOf("`nfunction ", $start + 1)
            if ($next -lt 0) { $next = $Source.Length }
            return $Source.Substring($start, $next - $start)
        }

        Assert-Contains (Get-Pass4Body2 $source "Get-DevWSWindowHwndRect") "GetWindowRect" "rect is native"
        Assert-Contains (Get-Pass4Body2 $source "Get-DevWSWindowHwndRect") "IsWindowVisible" "rect keeps hidden-window semantics"
        Assert-NotContains (Get-Pass4Body2 $source "Get-DevWSWindowHwndRect") "Invoke-DevWSWindowHelper" "rect no longer spawns the AHK helper"
        Assert-Contains (Get-Pass4Body2 $source "Focus-DevWSWindowHwnd") "Invoke-DevWSWindowHelper" "focus stays helper-backed"
        Assert-Contains (Get-Pass4Body2 $source "Close-DevWSWindowHwnd") "Invoke-DevWSResetWindowHelper" "close stays reset-helper-backed"

        $helper = Get-SourceOf "src\helpers\window-helper.ahk"
        Assert-Contains $helper "focus-hwnd" "window-helper keeps focus-hwnd"

        $reset = Get-SourceOf "src\helpers\reset-window.ahk"
        Assert-Contains $reset '"close-hwnd"' "reset helper keeps close-hwnd"
    }

    Test-Case "Phase 10 Pass 4 native type initialization is idempotent" {
        Initialize-DevWSWindowOpsNative
        Initialize-DevWSWindowOpsNative
        Initialize-DevWSWindowOpsNative

        Assert-True ($null -ne ([System.Management.Automation.PSTypeName]'DevWSWindowOpsNative').Type) "native type present"
        Assert-Equal $false (Test-DevWSWindowHwnd -Hwnd 0) "hot path usable after repeated initialization"

        $manifest = @(Get-DevWSInstallManifest -RepoRoot $RepoRoot)
