    Write-Host ""
    Start-TestGroup -Name 'native-ops' -Title 'Native locator and rectangle operations'

    # Test-only native helper: a real top-level window created off-screen but
    # with WS_VISIBLE, so visibility/minimize semantics can be exercised
    # without showing anything on the interactive desktop.
    if (-not ([System.Management.Automation.PSTypeName]'DevWSNativeWindowTestWindow').Type) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;

public static class DevWSNativeWindowTestWindow
{
    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr CreateWindowExW(uint dwExStyle, string lpClassName, string lpWindowName, uint dwStyle, int x, int y, int nWidth, int nHeight, IntPtr hWndParent, IntPtr hMenu, IntPtr hInstance, IntPtr lpParam);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool DestroyWindow(IntPtr hWnd);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool SetWindowPos(IntPtr hWnd, IntPtr hWndInsertAfter, int X, int Y, int cx, int cy, uint uFlags);

    private const uint WS_OVERLAPPEDWINDOW_VISIBLE = 0x10CF0000u;
    private const uint SWP_NOZORDER_NOACTIVATE = 0x0014u;

    public static long CreateVisible(string title)
    {
        return CreateWindowExW(0, "STATIC", title, WS_OVERLAPPEDWINDOW_VISIBLE, -2000, 100, 800, 600, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero).ToInt64();
    }

    public static bool Move(long hWnd, int x, int y, int width, int height)
    {
        return SetWindowPos((IntPtr)hWnd, IntPtr.Zero, x, y, width, height, SWP_NOZORDER_NOACTIVATE);
    }

    public static bool Hide(long hWnd) { return ShowWindow((IntPtr)hWnd, 0); }
    public static bool Show(long hWnd) { return ShowWindow((IntPtr)hWnd, 5); }
    public static bool Minimize(long hWnd) { return ShowWindow((IntPtr)hWnd, 6); }
    public static bool Restore(long hWnd) { return ShowWindow((IntPtr)hWnd, 9); }
    public static bool Destroy(long hWnd) { return DestroyWindow((IntPtr)hWnd); }
}
'@ -ErrorAction Stop
    }

    Test-Case "native rectangle capture preserves the capture contract" {
        $h = [DevWSNativeWindowTestWindow]::CreateVisible("DevWS-NativeRect-$([guid]::NewGuid().ToString('N'))")
        Assert-True ($h -ne 0) "test window created"

        try {
            $rect = Get-DevWSWindowHwndRect -Hwnd $h
            Assert-True ($null -ne $rect) "visible window returns a rect"
            Assert-True $rect.Valid "valid flag"
            Assert-Equal -2000 $rect.x "x"
            Assert-Equal 100 $rect.y "y"
            Assert-Equal 800 $rect.w "w"
            Assert-Equal 600 $rect.h "h"

            Assert-True ([DevWSNativeWindowTestWindow]::Move($h, -1900, 140, 900, 500)) "move test window"
            Start-Sleep -Milliseconds 150
            $moved = Get-DevWSWindowHwndRect -Hwnd $h
            Assert-Equal -1900 $moved.x "moved x"
            Assert-Equal 140 $moved.y "moved y"
            Assert-Equal 900 $moved.w "moved w"
            Assert-Equal 500 $moved.h "moved h"

            Assert-True ($null -eq (Get-DevWSWindowHwndRect -Hwnd 0)) "zero HWND returns null"
            Assert-True ($null -eq (Get-DevWSWindowHwndRect -Hwnd 987654321)) "missing HWND returns null"

            [void][DevWSNativeWindowTestWindow]::Hide($h)
            Assert-True ($null -eq (Get-DevWSWindowHwndRect -Hwnd $h)) "hidden window returns null"

            [void][DevWSNativeWindowTestWindow]::Show($h)
            [void][DevWSNativeWindowTestWindow]::Minimize($h)
            Start-Sleep -Milliseconds 150
            Assert-True ($null -eq (Get-DevWSWindowHwndRect -Hwnd $h)) "minimized window returns null"

            [void][DevWSNativeWindowTestWindow]::Restore($h)
            Start-Sleep -Milliseconds 150
            $restored = Get-DevWSWindowHwndRect -Hwnd $h
            Assert-Equal -1900 $restored.x "restored x"
            Assert-Equal 140 $restored.y "restored y"
            Assert-Equal 900 $restored.w "restored w"
            Assert-Equal 500 $restored.h "restored h"
        }
        finally {
            [void][DevWSNativeWindowTestWindow]::Destroy($h)
        }
    }

    Test-Case "native exact-title lookup resolves only visible exact matches" {
        $title = "DevWS-NativeTitle-$([guid]::NewGuid().ToString('N'))"
        $h = [DevWSNativeWindowTestWindow]::CreateVisible($title)
        Assert-True ($h -ne 0) "test window created"

        try {
            Assert-Equal $h (Find-DevWSVisibleWindowHwndByExactTitle -Title $title) "exact visible title resolves"
            Assert-Equal 0 (Find-DevWSVisibleWindowHwndByExactTitle -Title "$title-suffix") "near title does not resolve"
            Assert-Equal 0 (Find-DevWSVisibleWindowHwndByExactTitle -Title "DevWS-NativeTitle-NOPE-$([guid]::NewGuid().ToString('N'))") "nonexistent title resolves to 0"

            [void][DevWSNativeWindowTestWindow]::Hide($h)
            Assert-True ((([long][DevWSWindowOpsNative]::FindWindowByExactTitle($title)) -ne 0)) "raw native lookup still sees the hidden window"
            Assert-Equal 0 (Find-DevWSVisibleWindowHwndByExactTitle -Title $title) "hidden exact-title window is not a valid locator target"
        }
        finally {
            [void][DevWSNativeWindowTestWindow]::Destroy($h)
        }
    }

    Test-Case "native locator and rectangle replaced their AHK call sites" {
        $windowOps = Get-SourceOf "src\lib\devws-window-ops.ps1"
        $locator   = Get-SourceOf "src\lib\devws-locator.ps1"

        function Get-NativeTestFunctionBody([string]$Source, [string]$Name) {
            $start = $Source.IndexOf("function $Name {")
            Assert-True ($start -ge 0) "function $Name located"
            $next = $Source.IndexOf("`nfunction ", $start + 1)
            if ($next -lt 0) { $next = $Source.Length }
            return $Source.Substring($start, $next - $start)
        }

        $rectBody = Get-NativeTestFunctionBody $windowOps "Get-DevWSWindowHwndRect"
        Assert-Contains $rectBody "GetWindowRect" "rect uses the native GetWindowRect"
        Assert-Contains $rectBody "IsWindowVisible" "rect keeps hidden-window semantics"
        Assert-Contains $rectBody "IsIconic" "rect keeps minimized semantics"
        Assert-NotContains $rectBody "Invoke-DevWSWindowHelper" "rect no longer spawns the AHK helper"
        Assert-NotContains $rectBody "rect-hwnd" "rect-hwnd removed from the call path"

        $locatorBody = Get-NativeTestFunctionBody $locator "Start-DevWSLocator"
        Assert-Contains $locatorBody "Find-DevWSVisibleWindowHwndByExactTitle" "locator uses the native exact-title lookup"
        Assert-NotContains $locatorBody "Invoke-DevWSWindowHelper" "locator no longer spawns the AHK helper"
        Assert-NotContains $locatorBody 'Arguments @("hwnd"' "old AHK locator mode removed"

        $ahkLib = Get-SourceOf "src\lib\devws-ahk.ps1"
        Assert-Contains $ahkLib "Invoke-DevWSWindowHelper" "focus helper wiring retained"
        Assert-Contains $ahkLib "Invoke-DevWSResetWindowHelper" "reset helper wiring retained"
        Assert-NotContains $ahkLib "function ConvertFrom-DevWSHwndText" "dead hwnd output parser removed"
        Assert-NotContains $ahkLib "function ConvertFrom-DevWSRectText" "dead rect output parser removed"

        $uia = Get-SourceOf "src\lib\devws-uia.ps1"
        Assert-Contains $uia "function Get-DevWSPresentTabNamesFromHwnd {" "HWND-scoped presence helper retained"
        Assert-NotContains $uia "function Get-DevWSPresentTabNames {" "unscoped dead presence helper removed"

        # Cold-start contract: the HWND-scoped read must initialize
        # UIAutomationClient before referencing AutomationElement, and that
        # initialization must stay outside the per-HWND try/catch so an
        # assembly-load failure cannot masquerade as "window has no tabs".
        $presentBody     = Get-NativeTestFunctionBody $uia "Get-DevWSPresentTabNamesFromHwnd"
        $addTypeIndex    = $presentBody.IndexOf("Add-Type -AssemblyName UIAutomationClient", [System.StringComparison]::Ordinal)
        $fromHandleIndex = $presentBody.IndexOf("AutomationElement]::FromHandle", [System.StringComparison]::Ordinal)
        $tryIndex        = $presentBody.IndexOf("try {", [System.StringComparison]::Ordinal)

        Assert-True ($addTypeIndex -ge 0) "HWND tab helper explicitly initializes UIAutomationClient"
        Assert-True ($fromHandleIndex -gt $addTypeIndex) "Add-Type precedes the FromHandle reference"
        Assert-True ($tryIndex -gt $addTypeIndex) "Add-Type stays outside the FromHandle try/catch"
        Assert-Contains $presentBody "New-DevWSPresentTabNameSet -Names @()" "per-HWND access failure still degrades to an empty set"

        foreach ($workerName in @("elevated.ps1", "elevated-focus.ps1", "elevated-capture.ps1", "elevated-reset.ps1")) {
            Assert-NotContains (Get-SourceOf "src\workers\$workerName") "Add-Type -AssemblyName UIAutomationClient" "$workerName does not preload UIA"
        }
    }

