                "QueryFullProcessImageNameW",
                "GetProcessTimes",
                "PeekNamedPipe",
                "public static bool TryGetCommandLine(",
                "public static string[] SplitCommandLine(",
                "public static bool TryFlushFileBuffers(IntPtr handle, int timeoutMilliseconds)",
                "FlushFileBuffers",
                "DuplicateHandle"
            )
        }

        foreach ($entry in $declarationSets.GetEnumerator()) {
            $sourcePath = Join-Path $RepoRoot "src\native\$($entry.Key)"
            Assert-True (Test-Path -LiteralPath $sourcePath -PathType Leaf) "tracked native source exists: $($entry.Key)"

            $declaration = Get-Content -LiteralPath $sourcePath -Raw

            foreach ($needle in @($entry.Value)) {
                Assert-Contains $declaration $needle "tracked declaration $($entry.Key) contains $needle"
            }
        }

        # The embedded declarations are gone from the PowerShell libraries.
        Assert-NotContains (Get-SourceOf "src\lib\devws-app-window.ps1") "Add-Type -TypeDefinition" "app-window no longer compiles an embedded TypeDefinition"
        Assert-NotContains (Get-SourceOf "src\lib\devws-app-ownership.ps1") "Add-Type -TypeDefinition" "ownership no longer compiles an embedded TypeDefinition"
        Assert-NotContains (Get-SourceOf "src\lib\devws-app-window.ps1") "public static class DevWSAppWindowNative" "app-window C# removed from the library"
        Assert-NotContains (Get-SourceOf "src\lib\devws-app-ownership.ps1") "public static class DevWSAppOwnershipNative" "ownership C# removed from the library"

        # The shared loader owns layout, compilation and byte loading; the
        # window-ops subsystem only delegates to it.
        $loader = Get-SourceOf "src\lib\devws-native.ps1"
        Assert-Contains $loader "Add-Type -Path" "repository mode compiles the tracked source files"
        Assert-Contains $loader "native\DevWS.Native.dll" "installed mode targets the generated DLL"
        Assert-Contains $loader "[System.Reflection.Assembly]::Load" "installed mode byte-loads the generated DLL"
        Assert-NotContains $loader "::LoadFrom" "installed loader never locks the DLL"
        Assert-NotContains $loader "Add-Type -TypeDefinition" "no runtime TypeDefinition compilation remains"

        $windowOps = Get-SourceOf "src\lib\devws-window-ops.ps1"
        Assert-Contains $windowOps "Initialize-DevWSNativeRuntime" "window ops delegate to the shared native runtime"
        Assert-NotContains $windowOps "Add-Type" "window ops never compile"
        Assert-NotContains $windowOps "[System.Reflection.Assembly]::Load" "window ops no longer load the DLL"

        $embedded = @(Get-ChildItem -Path (Join-Path $RepoRoot "src") -Recurse -Filter "*.ps1" -File |
            Select-String -Pattern "public static class DevWS" -SimpleMatch)
        Assert-Equal 0 $embedded.Count "the C# declarations exist only under src\native"
    }

    Test-Case "native source list is deterministic and matches src\native" {
        $sourcePaths = @(Get-DevWSNativeSourcePaths -RepoRoot $RepoRoot)
        $sourceNames = @($sourcePaths | ForEach-Object { Split-Path -Leaf $_ })

        Assert-Equal 9 $sourcePaths.Count "installer compiles nine native sources"
        Assert-Equal $sourceNames.Count @($sourceNames | Sort-Object -Unique).Count "native source list has no duplicates"

        $actual = @(Get-ChildItem -Path (Join-Path $RepoRoot "src\native") -Filter "*.cs" -File | ForEach-Object { $_.Name } | Sort-Object)
        Assert-Equal (($actual) -join ",") (($sourceNames | Sort-Object) -join ",") "native source list matches src\native exactly"

        $again = @(Get-DevWSNativeSourcePaths -RepoRoot $RepoRoot | ForEach-Object { Split-Path -Leaf $_ })
        Assert-Equal ($sourceNames -join ",") ($again -join ",") "native source order is deterministic"

        $layout = Get-DevWSNativeRuntimeLayout
        $layoutNames = @($layout.SourcePaths | ForEach-Object { Split-Path -Leaf $_ })
        Assert-Equal ($sourceNames -join ",") ($layoutNames -join ",") "loader and installer agree on the native source set"
    }

    Test-Case "shared native runtime layout resolves repository and installed modes" {
        $layout = Get-DevWSNativeRuntimeLayout

        Assert-Equal "repository" $layout.Mode "repository layout detected"
        Assert-True ($null -eq $layout.DllPath) "repository mode never targets the installed DLL"
        Assert-Equal 9 @($layout.SourcePaths).Count "repository layout lists all tracked sources"

        $fixture = New-InstallFixture "native-layout"
        $installedLayout = Get-DevWSNativeRuntimeLayout -LibRoot (Join-Path $fixture.Root "app\lib")

        Assert-Equal "installed" $installedLayout.Mode "installed layout detected"
        Assert-Equal (Join-Path $fixture.Root "app\native\DevWS.Native.dll") $installedLayout.DllPath "installed layout targets the generated DLL"
        Assert-Equal 0 @($installedLayout.SourcePaths).Count "installed layout carries no compile sources"

        $message = Get-ThrownMessage { Get-DevWSNativeRuntimeLayout -LibRoot (Join-Path $TestRoot "somewhere\lib") }
        Assert-Contains $message "Unrecognized DevWS native layout" "unknown layouts fail actionably"
    }

    Test-Case "repository native runtime compiles the whole source set once" {
        $probePath = Join-Path $TestRoot "native-repository-probe.ps1"
        $probeSource = @'
param(
    [Parameter(Mandatory)][string]$LibPath
)

$ErrorActionPreference = "Stop"

$script:addTypeCalls = [System.Collections.Generic.List[object]]::new()
$realAddType = Get-Command -Name Add-Type -CommandType Cmdlet

function Add-Type {
    $script:addTypeCalls.Add(@($args)) | Out-Null
    & $realAddType @args
}

. $LibPath

$layout = Get-DevWSNativeRuntimeLayout

if ($layout.Mode -ne "repository") { throw "unexpected mode: $($layout.Mode)" }
if (@($layout.SourcePaths).Count -ne 9) { throw "unexpected source count: $(@($layout.SourcePaths).Count)" }
if ($layout.DllPath) { throw "repository mode must not target an installed DLL" }

Initialize-DevWSNativeRuntime

if ($script:addTypeCalls.Count -ne 1) { throw "expected exactly one Add-Type call, got $($script:addTypeCalls.Count)" }

$firstArgs = (@($script:addTypeCalls[0][1]) -join "|")

foreach ($name in @("devws-window-ops.cs", "devws-app-window.cs", "devws-app-ownership.cs", "devws-app-candidates.cs", "devws-terminal-candidates.cs", "devws-broker-pipe.cs", "devws-monitor.cs", "devws-privilege-identity.cs", "devws-worker-pipe-identity.cs")) {
    if ($firstArgs.IndexOf($name, [System.StringComparison]::Ordinal) -lt 0) { throw "first Add-Type call missed $name" }
}

foreach ($typeName in @(Get-DevWSNativeRequiredTypeNames)) {
    if ($null -eq ([System.Management.Automation.PSTypeName]$typeName).Type) { throw "native type missing: $typeName" }
}

Initialize-DevWSNativeRuntime
Initialize-DevWSNativeRuntime

if ($script:addTypeCalls.Count -ne 1) { throw "repeated initialization compiled again ($($script:addTypeCalls.Count))" }

if ([DevWSWindowOpsNative]::IsWindow([IntPtr]::Zero)) { throw "unexpected live window" }

Write-Output "REPOSITORY-COMPILE-OK"
'@

        Set-Content -LiteralPath $probePath -Value $probeSource -NoNewline

        $output = & pwsh -NoLogo -NoProfile -File $probePath -LibPath (Join-Path $RepoRoot "src\lib\devws-native.ps1") 2>&1 | Out-String

        Assert-Equal 0 $LASTEXITCODE "repository probe exits cleanly: $output"
        Assert-Contains $output "REPOSITORY-COMPILE-OK" "repository mode compiled the whole native set once"
    }

    Test-Case "installed native mode byte-loads and never compiles" {
        $fixture = New-InstallFixture "native-installed"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $dllPath = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        Assert-Equal (Join-Path $fixture.Root "app\native\DevWS.Native.dll") $dllPath "generated DLL path"
        Assert-True (Test-Path -LiteralPath $dllPath -PathType Leaf) "generated DLL exists"

        $validation = Test-DevWSNativeAssemblyBytes -Bytes ([System.IO.File]::ReadAllBytes($dllPath))
        Assert-Equal $true $validation.Ok "generated DLL exposes the full native contract"

        $probe = Invoke-InstalledNativeProbe -NativeLibPath (Join-Path $fixture.Root "app\lib\devws-native.ps1") -Label "valid"

        Assert-Equal 0 $probe.ExitCode "installed probe exits cleanly: $($probe.Output)"
        Assert-Contains $probe.Output "INSTALLED-NATIVE-OK" "installed mode loaded every native type from bytes"
        Assert-NotContains $probe.Output "invoked Add-Type" "installed mode never invoked the compiler"
    }

    Test-Case "installed native mode fails actionably without the generated DLL" {
        $fixture = New-InstallFixture "native-missing"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

