        Assert-Contains $probe.Output "DevWS.Native.dll" "missing DLL names the expected artifact"
        Assert-Contains $probe.Output "install.ps1" "missing DLL names the recovery action"
    }

    Test-Case "installed native mode rejects a corrupt generated DLL" {
        $fixture = New-InstallFixture "native-corrupt"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $dllPath = Get-DevWSInstalledNativeDllPath -InstallRoot $fixture.Root
        New-Item -ItemType Directory -Path (Split-Path -Parent $dllPath) -Force | Out-Null
        [System.IO.File]::WriteAllBytes($dllPath, [byte[]](1, 2, 3, 4, 5, 6, 7, 8))

        $probe = Invoke-InstalledNativeProbe -NativeLibPath (Join-Path $fixture.Root "app\lib\devws-native.ps1") -Label "corrupt"

        Assert-Contains $probe.Output "INSTALLED-NATIVE-ERROR" "corrupt DLL fails"
