        Assert-Contains $probe.Output "install.ps1" "corrupt DLL names the recovery action"
        Assert-NotContains $probe.Output "invoked Add-Type" "corrupt DLL never falls back to compilation"
    }

    Test-Case "installed native mode rejects a structurally incomplete DLL" {
        $fixture = New-InstallFixture "native-incomplete"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

