    Test-Case "native assembly validation rejects wrong type and missing surface" {
        $fixture = New-InstallFixture "native-validator"
        $dllPath = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $valid = Test-DevWSNativeAssemblyBytes -Bytes ([System.IO.File]::ReadAllBytes($dllPath))
        Assert-Equal $true $valid.Ok "generated candidate validates"

