        $partialDll = Join-Path $decoyRoot "partial.dll"
        $null = Invoke-TestNativeCompile -SourcePath $partialSource -OutputPath $partialDll -Label "partial"

        $partial = Test-DevWSNativeAssemblyBytes -Bytes ([System.IO.File]::ReadAllBytes($partialDll))
        Assert-Equal $false $partial.Ok "missing surface rejected"
        Assert-Contains $partial.Message "SW_RESTORE" "missing surface reports the first missing field"

        $corrupt = Test-DevWSNativeAssemblyBytes -Bytes ([byte[]](9, 8, 7, 6, 5))
        Assert-Equal $false $corrupt.Ok "corrupt bytes rejected"
        Assert-Contains $corrupt.Message "failed to load" "corrupt bytes report a load failure"

        # Three real sources plus a DTO-only candidate file: the fact surface is
        # complete but the collector is missing and must be rejected.
        $realOps = Join-Path $RepoRoot "src\native\devws-window-ops.cs"
        $realAw  = Join-Path $RepoRoot "src\native\devws-app-window.cs"
        $realAo  = Join-Path $RepoRoot "src\native\devws-app-ownership.cs"

        $dtoOnlySource = Join-Path $decoyRoot "dto-only.cs"
