using System;

public sealed class DevWSAppWindowCandidate
{
    public long Hwnd { get; private set; }
    public uint Pid { get; private set; }
    public string ProcessName { get; private set; }
    public string ProcessPath { get; private set; }
    public bool PathUnavailable { get; private set; }
    public bool Visible { get; private set; }
    public string Class { get; private set; }
    public string Title { get; private set; }
}
'@ -NoNewline

        $noCollectorDll = Join-Path $decoyRoot "no-collector.dll"
        $null = Invoke-TestNativeCompile -SourcePath @($realOps, $realAw, $realAo, $dtoOnlySource) -OutputPath $noCollectorDll -Label "no-collector"
        $noCollector = Test-DevWSNativeAssemblyBytes -Bytes ([System.IO.File]::ReadAllBytes($noCollectorDll))
        Assert-Equal $false $noCollector.Ok "missing collector rejected"
        Assert-Contains $noCollector.Message "DevWSAppWindowCandidateCollector" "missing collector reports the missing type"

        # Candidate DTO missing a required fact property.
        $dtoMissingSource = Join-Path $decoyRoot "dto-missing-property.cs"
        Set-Content -LiteralPath $dtoMissingSource -Value @'
