        $collectorReturnDll = Join-Path $decoyRoot "collector-return.dll"
        $null = Invoke-TestNativeCompile -SourcePath @($realOps, $realAw, $realAo, $collectorReturnSource) -OutputPath $collectorReturnDll -Label "collector-return"
