    Test-Case "native generation failure preserves the installed DLL and cleans candidates" {
        $fixture = New-InstallFixture "native-preserve"
        $dllPath = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $before = Get-FileBase64 -Path $dllPath

        $sourceNames = @(
            "devws-window-ops.cs",
            "devws-app-window.cs",
            "devws-app-ownership.cs",
            "devws-app-candidates.cs",
            "devws-terminal-candidates.cs",
            "devws-broker-pipe.cs",
            "devws-monitor.cs",
            "devws-privilege-identity.cs",
            "devws-worker-pipe-identity.cs"
        )

        # A malformed source of ANY native file fails before any candidate is
        # promoted; the previously installed DLL survives untouched.
        foreach ($malformed in $sourceNames) {
            $badRepo = Join-Path $fixture.Root ("bad-repo-" + $malformed)
            $badNative = Join-Path $badRepo "src\native"
            New-Item -ItemType Directory -Path $badNative -Force | Out-Null

            foreach ($sourceName in $sourceNames) {
                if ($sourceName -eq $malformed) {
                    Set-Content -LiteralPath (Join-Path $badNative $sourceName) -Value "this is not valid C#" -NoNewline
                }
                else {
                    Copy-Item -LiteralPath (Join-Path $RepoRoot "src\native\$sourceName") -Destination (Join-Path $badNative $sourceName)
                }
            }

            $message = Get-ThrownMessage { Install-DevWSNativeRuntime -RepoRoot $badRepo -InstallRoot $fixture.Root }
            Assert-Contains $message "left unchanged" "malformed $malformed reports preservation"
            Assert-Equal $before (Get-FileBase64 -Path $dllPath) "malformed $malformed preserves the good DLL"
        }

        # Wrong type: the candidate compiles but never passes validation.
        $wrongRepo = Join-Path $fixture.Root "wrong-repo"
        $wrongNative = Join-Path $wrongRepo "src\native"
        New-Item -ItemType Directory -Path $wrongNative -Force | Out-Null

        foreach ($sourceName in $sourceNames) {
            Copy-Item -LiteralPath (Join-Path $RepoRoot "src\native\$sourceName") -Destination (Join-Path $wrongNative $sourceName)
        }

        Set-Content -LiteralPath (Join-Path $wrongNative "devws-app-candidates.cs") -Value "public static class NotDevWSAppWindowCandidateCollector { }" -NoNewline

        $message = Get-ThrownMessage { Install-DevWSNativeRuntime -RepoRoot $wrongRepo -InstallRoot $fixture.Root }
        Assert-Contains $message "validation failed" "wrong surface reports validation"
        Assert-Equal $before (Get-FileBase64 -Path $dllPath) "validation failure preserves the good DLL"

        $leftovers = @(Get-ChildItem -LiteralPath (Split-Path -Parent $dllPath) -File | Where-Object { $_.Name -ne "DevWS.Native.dll" })
        Assert-Equal 0 $leftovers.Count "no candidate artifacts remain ($($leftovers.Name -join ', '))"
    }

    Test-Case "byte-loaded native runtime never locks the installed DLL" {
        $fixture = New-InstallFixture "native-update"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $dllPath = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        # Load the installed bytes exactly like the installed runtime does.
        $loadedAssembly = [System.Reflection.Assembly]::Load([System.IO.File]::ReadAllBytes($dllPath))
        $loadedType = $loadedAssembly.GetType("DevWSWindowOpsNative", $false)
        Assert-True ($null -ne $loadedType) "loaded assembly exposes the type"
        Assert-Equal $false ([bool]$loadedType.GetMethod("IsWindow").Invoke($null, @([IntPtr]::Zero))) "loaded assembly is usable"

        # Build a distinguishable replacement: the same contract plus a marker.
        $markerRoot = Join-Path $fixture.Root "marker"
        $markerNative = Join-Path $markerRoot "native"
        New-Item -ItemType Directory -Path $markerNative -Force | Out-Null

        $sourceNames = @(
            "devws-window-ops.cs",
            "devws-app-window.cs",
            "devws-app-ownership.cs",
            "devws-app-candidates.cs",
            "devws-terminal-candidates.cs",
            "devws-broker-pipe.cs",
            "devws-monitor.cs",
            "devws-privilege-identity.cs",
            "devws-worker-pipe-identity.cs"
        )

        foreach ($sourceName in $sourceNames) {
            Copy-Item -LiteralPath (Join-Path $RepoRoot "src\native\$sourceName") -Destination (Join-Path $markerNative $sourceName)
        }

        $markerSourcePath = Join-Path $markerNative "devws-window-ops.cs"
        $markerSource = Get-Content -LiteralPath $markerSourcePath -Raw
        $insertAt = $markerSource.LastIndexOf("}")
        Assert-True ($insertAt -gt 0) "class closing brace located"
        $markerSource = $markerSource.Substring(0, $insertAt) + "    public const int DevWSUpdateMarker = 424242;`r`n" + $markerSource.Substring($insertAt)
        Set-Content -LiteralPath $markerSourcePath -Value $markerSource -NoNewline

        $markerDll = Join-Path $markerRoot "marker.dll"
        $null = Invoke-TestNativeCompile -SourcePath @(
            (Join-Path $markerNative "devws-window-ops.cs"),
            (Join-Path $markerNative "devws-app-window.cs"),
            (Join-Path $markerNative "devws-app-ownership.cs"),
            (Join-Path $markerNative "devws-app-candidates.cs"),
            (Join-Path $markerNative "devws-terminal-candidates.cs"),
            (Join-Path $markerNative "devws-broker-pipe.cs"),
            (Join-Path $markerNative "devws-monitor.cs"),
            (Join-Path $markerNative "devws-privilege-identity.cs"),
            (Join-Path $markerNative "devws-worker-pipe-identity.cs")
        ) -OutputPath $markerDll -Label "marker"
        $markerBytes = [System.IO.File]::ReadAllBytes($markerDll)

        # Replacing the installed DLL while the old assembly is loaded proves
        # byte loading holds no file lock.
        [System.IO.File]::Move($markerDll, $dllPath, $true)
        Assert-Equal ([Convert]::ToBase64String($markerBytes)) (Get-FileBase64 -Path $dllPath) "installed DLL was replaced while loaded"
        Assert-Equal $false ([bool]$loadedType.GetMethod("IsWindow").Invoke($null, @([IntPtr]::Zero))) "old in-memory assembly stays usable after replacement"

        # A fresh installed-layout process sees the replacement file.
        $probePath = Join-Path $TestRoot "native-replacement-probe.ps1"
        $probeSource = @'
param([Parameter(Mandatory)][string]$NativeLibPath)

$ErrorActionPreference = "Stop"

function Add-Type {
    throw "installed runtime invoked Add-Type: $args"
}

. $NativeLibPath
Initialize-DevWSNativeRuntime

$type = ([System.Management.Automation.PSTypeName]'DevWSWindowOpsNative').Type

if ($null -eq $type) { throw "native type missing" }
if ($null -eq $type.GetField("DevWSUpdateMarker")) { throw "replacement marker missing" }

Write-Output "REPLACEMENT-LOADED"
'@

        Set-Content -LiteralPath $probePath -Value $probeSource -NoNewline

        $output = & pwsh -NoLogo -NoProfile -File $probePath -NativeLibPath (Join-Path $fixture.Root "app\lib\devws-native.ps1") 2>&1 | Out-String

        Assert-Equal 0 $LASTEXITCODE "replacement probe exits cleanly: $output"
        Assert-Contains $output "REPLACEMENT-LOADED" "a fresh process loads the replacement DLL"
    }

