    Test-Case "health app-libs validates the generated native runtime" {
        $fixture = New-InstallFixture "health-native"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $dllPath = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture -SkipNative

        $stubs = Join-Path $fixture.Root "stubs"
        New-Item -ItemType Directory -Path $stubs -Force | Out-Null
        $wtStub  = Join-Path $stubs "wt.exe"
        $ahkStub = Join-Path $stubs "AutoHotkey64.exe"
        Set-Content -LiteralPath $wtStub -Value "" -NoNewline
        Set-Content -LiteralPath $ahkStub -Value "" -NoNewline

        $context = [pscustomobject]@{
            InstallRoot         = $fixture.Root
            StateRoot           = $fixture.State
            CanonicalPath       = Join-Path $fixture.Root "canonical.json"
            StartupPath         = Join-Path $fixture.Root "Startup"
            LegacyShimPath      = Join-Path $fixture.Root "local-bin\ws.cmd"
            WindowsTerminalPath = $wtStub
            AutoHotkeyPath      = $ahkStub
            MetadataPath        = Join-Path $fixture.State "install-metadata.json"
            PrivilegedRoot      = $fixture.Privileged
        }

        function Get-NativeHealthById($summary) {
            $byId = @{}
            foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }
            return $byId
        }

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-NativeHealthById $summary

        Assert-Equal 25 @($summary.Results).Count "health keeps exactly 25 checks"
        Assert-Equal $true $byId["app-libs"].Ok "valid native runtime passes app-libs"

        # Missing DLL fails app-libs with the installer guidance.
        Move-Item -LiteralPath $dllPath -Destination "$dllPath.off"
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-NativeHealthById $summary
        Assert-Equal $false $byId["app-libs"].Ok "missing native DLL fails app-libs"
        Assert-Contains $byId["app-libs"].Message "install.ps1" "missing DLL names the installer recovery"
        Move-Item -LiteralPath "$dllPath.off" -Destination $dllPath

        # Corrupt DLL fails app-libs.
        [System.IO.File]::WriteAllBytes($dllPath, [byte[]](1, 2, 3, 4))
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-NativeHealthById $summary
        Assert-Equal $false $byId["app-libs"].Ok "corrupt native DLL fails app-libs"
        Assert-Contains $byId["app-libs"].Message "invalid" "corrupt DLL reports an invalid runtime"

        # Wrong surface (type present, contract incomplete) fails app-libs.
        $decoySource = Join-Path $fixture.Root "wrong-native.cs"
        Set-Content -LiteralPath $decoySource -Value "public static class DevWSWindowOpsNative { }" -NoNewline
        $decoyDll = Join-Path $fixture.Root "wrong-native.dll"
        $null = Invoke-TestNativeCompile -SourcePath $decoySource -OutputPath $decoyDll -Label "wrong-surface"
        [System.IO.File]::Copy($decoyDll, $dllPath, $true)

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-NativeHealthById $summary
        Assert-Equal $false $byId["app-libs"].Ok "wrong native surface fails app-libs"
        Assert-Contains $byId["app-libs"].Message "SW_RESTORE" "wrong surface reports the missing field"

        # Health never repairs or rewrites the artifact.
        Assert-Equal (Get-FileBase64 -Path $decoyDll) (Get-FileBase64 -Path $dllPath) "health leaves the native DLL untouched"
    }

    Test-Case "installer generates the native runtime before staging application files" {
