        Assert-Contains $lib "function Get-DevWSInstalledNativeDllPath" "installed DLL path helper"
        Assert-Contains $lib "function Test-DevWSNativeAssemblyBytes" "candidate validator"
        Assert-Contains $lib "function Install-DevWSNativeRuntime" "generation helper"
        Assert-Contains $lib "-OutputAssembly" "generation compiles a candidate assembly"
        Assert-Contains $lib "-OutputType Library" "candidate is a library"
        Assert-Contains $lib "[System.IO.File]::Move" "promotion uses an atomic move"
        Assert-NotContains $lib "::LoadFrom" "generation never locks candidates with LoadFrom"

        $loader = Get-SourceOf "src\lib\devws-native.ps1"
