    Test-Case "generated hotkey content parses in the installed AutoHotkey v2" {
        $ahk = $null
        try { $ahk = Get-DevWSAutoHotkeyPath } catch { $ahk = $null }

        if ([string]::IsNullOrWhiteSpace([string]$ahk) -or -not (Test-Path -LiteralPath $ahk -PathType Leaf)) {
            return
        }

        $dir = Join-Path $TestRoot "ahk-parse"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $appScript = Join-Path $dir "app ws.ps1"
        Set-Content -LiteralPath $appScript -Value "# stub" -NoNewline
        $bindingsPath = Join-Path $dir "bindings dir\bindings.ahk"

        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main"), (New-TestSet -Id "secondary")) -Bindings @(
            [ordered]@{ hotkey = "alt+shift+y"; setId = "secondary" }
        )

        $null = Write-DevWSBindingsState -Config $config -AppScriptPath $appScript -Path $bindingsPath

        $core = New-DevWSTerminalShortcutContent -AppScriptPath $appScript -BindingsPath $bindingsPath
        $scriptPath = Join-Path $dir "parse-core.ahk"
        Set-Content -LiteralPath $scriptPath -Value ($core + "ExitApp 0`r`n") -NoNewline

        $process = Start-Process -FilePath $ahk -ArgumentList "/ErrorStdOut", "`"$scriptPath`"" -PassThru
        $exited = $process.WaitForExit(20000)

        if (-not $exited) { $process.Kill() }

        Assert-True $exited "AutoHotkey parse run exits"
        Assert-Equal 0 $process.ExitCode "core plus generated bindings parse cleanly"

        # Optional include: a missing generated file must not break the core.
        Remove-Item -LiteralPath $bindingsPath -Force
        $process = Start-Process -FilePath $ahk -ArgumentList "/ErrorStdOut", "`"$scriptPath`"" -PassThru
        $exited = $process.WaitForExit(20000)

        if (-not $exited) { $process.Kill() }

        Assert-True $exited "AutoHotkey parse run exits with a missing include"
        Assert-Equal 0 $process.ExitCode "missing generated include is skipped safely"

        # A real load error inside an existing include still fails.
        Set-Content -LiteralPath $bindingsPath -Value "#NoSuchDirectiveHere xyz" -NoNewline
        $process = Start-Process -FilePath $ahk -ArgumentList "/ErrorStdOut", "`"$scriptPath`"" -PassThru
        $exited = $process.WaitForExit(20000)

        if (-not $exited) { $process.Kill() }

        Assert-True $exited "AutoHotkey parse run exits with an invalid include"
        Assert-True ($process.ExitCode -ne 0) "included-file load errors still fail"
    }

