    Test-Case "health reads scheduled task state once and shares it across task checks" {
        $fixture = New-InstallFixture "health-task-snapshot"

        $context = [pscustomobject]@{
            InstallRoot         = $fixture.Root
            StateRoot           = $fixture.State
            CanonicalPath       = Join-Path $fixture.Root "canonical.json"
            StartupPath         = Join-Path $fixture.Root "Startup"
            LegacyShimPath      = Join-Path $fixture.Root "local-bin\ws.cmd"
            WindowsTerminalPath = Join-Path $fixture.Root "wt.exe"
            AutoHotkeyPath      = Join-Path $fixture.Root "AutoHotkey64.exe"
            MetadataPath        = Join-Path $fixture.State "install-metadata.json"
            PrivilegedRoot      = $fixture.Privileged
        }

        $expectedPowerShell = Resolve-DevWSTrustedPowerShellPath
        $context | Add-Member -NotePropertyName "PrivilegedPowerShellPath" -NotePropertyValue $expectedPowerShell

        $specs   = @(Get-DevWSScheduledTaskSpecs -InstallRoot $fixture.Root -PrivilegedRoot $fixture.Privileged -PowerShellPath $expectedPowerShell)
        $queries = [System.Collections.Generic.List[object]]::new()

        function Get-ScheduledTask {
            param([string]$TaskName, $TaskPath, $ErrorAction)

            $queries.Add([pscustomobject]@{ TaskName = $TaskName })

            return @($specs | ForEach-Object {
                $isBroker = [string]$_.TaskName -eq "DevWorkspace-ElevatedBroker"

                [pscustomobject]@{
                    TaskName  = $_.TaskName
                    TaskPath  = "\"
                    Actions   = @([pscustomobject]@{ Execute = $_.PowerShellPath; Arguments = "-NoProfile -WindowStyle Hidden -File `"$($_.Worker)`"" })
                    Principal = [pscustomobject]@{ RunLevel = "Highest" }
                    Settings  = [pscustomobject]@{
                        MultipleInstances          = "IgnoreNew"
                        ExecutionTimeLimit         = if ($isBroker) { "PT0S" } else { "PT72H" }
                        DisallowStartIfOnBatteries = -not $isBroker
                        StopIfGoingOnBatteries     = -not $isBroker
                        RestartCount               = if ($isBroker) { 3 } else { 0 }
                    }
                    Triggers  = if ($isBroker) { @([pscustomobject]@{ UserId = $env:USERNAME }) } else { @() }
                }
            })
        }

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal 1 $queries.Count "one scheduled-task query per health run"
        Assert-Equal $true $byId["scheduled-tasks"].Ok "snapshot satisfies task existence"
        Assert-Equal $true $byId["task-workers"].Ok "snapshot satisfies worker-path validation"
        Assert-Equal $true $byId["task-runlevel"].Ok "snapshot satisfies run-level validation"
        Assert-Equal $true $byId["task-executable"].Ok "snapshot satisfies absolute executable validation"

        # A snapshot without the tasks fails all three checks from one query.
        $specs = @()
        $queries.Clear()

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = @{}
        foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }

        Assert-Equal 1 $queries.Count "missing tasks still use a single query"
        Assert-Equal $false $byId["scheduled-tasks"].Ok "missing task fails existence"
        Assert-Equal $false $byId["task-workers"].Ok "missing task fails worker path"
        Assert-Equal $false $byId["task-runlevel"].Ok "missing task fails run level"
        Assert-Equal $false $byId["task-executable"].Ok "missing task fails executable validation"

        $health = Get-SourceOf "src\lib\devws-health.ps1"
        Assert-NotContains $health "Get-ScheduledTask -TaskName" "task checks no longer query by name"
    }

    Write-Host ""
    Start-TestGroup -Name 'installer-wiring' -Title 'Installer wiring'

    Test-Case "installer scripts wire the expected steps and stay inside DevWS paths" {
