    Test-Case "prerequisite detection runs inside this PowerShell process" {
        # A locally assigned $isWindows (same case-insensitive variable as the
        # read-only automatic $IsWindows) used to throw here. Executing this
        # exact call path is the regression proof.
        $results = @(Get-DevWSPrerequisiteResults)

        Assert-True ($results.Count -ge 4) "prerequisite results returned"

