        Assert-Equal 1 $windowsResult.Count "a Windows prerequisite result is returned"
        Assert-True ($windowsResult[0].Ok -is [bool]) "Windows detection is boolean"
        Assert-Equal ([System.Environment]::OSVersion.Platform -eq [System.PlatformID]::Win32NT) $windowsResult[0].Ok "Windows detection reflects the OS"

        foreach ($result in $results) {
