            $code = $LASTEXITCODE

            Assert-Equal 1 $code "install package mode refuses $extra"
            Assert-Contains $output "cannot be combined" "the $extra refusal is explicit"
            Assert-NotContains $output "Prerequisites:" "the $extra refusal precedes prerequisite checks"
            Assert-NotContains $output "1/9 Application files" "the $extra refusal precedes installer mutation"
            Assert-NotContains $output "must run from an Administrator" "the $extra refusal precedes elevation"
        }
    }

    Write-Host ""
    Start-TestGroup -Name 'cwd' -Title 'Phase 9 cwd tracking'

    Test-Case "cwd session and publication records are atomic, BOM-free, and temp-clean" {
        $stateRoot  = Join-Path $TestRoot "p9-records-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $tracking = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId "DevWS-slot"

            Assert-True (Test-Path -LiteralPath $tracking.SessionPath -PathType Leaf) "expected session record written"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\slot.json") $tracking.SessionPath "session path layout"
            Assert-Equal (Join-Path $stateRoot "cwd\main\slot.json") $tracking.PublicationPath "publication path layout"

            $session = Read-DevWSCwdSessionRecord -Path $tracking.SessionPath
            Assert-Equal 1 $session.version "session version"
            Assert-Equal "main" $session.setId "session set"
            Assert-Equal "slot" $session.terminalId "session terminal"
            Assert-Equal "DevWS-slot" $session.windowId "session window"
            Assert-Equal $tracking.SessionId $session.sessionId "session id matches context"
            Assert-True ($session.sessionId -match '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') "guid session id"

            $bytes = [System.IO.File]::ReadAllBytes($tracking.SessionPath)
            $hasBom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
            Assert-True (-not $hasBom) "session record has no UTF-8 BOM"

            Write-DevWSCwdPublication -Path $tracking.PublicationPath -Record ([ordered]@{
                version           = 1
                setId             = "main"
                terminalId        = "slot"
                windowId          = "DevWS-slot"
                sessionId         = $tracking.SessionId
                cwd               = $TestRoot
                shellPid          = $PID
                shellStartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
                updatedAtUtc      = (Get-Date).ToUniversalTime().ToString("o")
            })

            $publication = Read-DevWSCwdPublication -Path $tracking.PublicationPath
            Assert-Equal 1 $publication.version "publication version"
            Assert-Equal $tracking.SessionId $publication.sessionId "publication session id"

            $tempFiles = @(Get-ChildItem -Path (Join-Path $stateRoot "cwd-sessions") -Recurse -File | Where-Object { $_.Name -like "*.tmp" })
            $tempFiles += @(Get-ChildItem -Path (Join-Path $stateRoot "cwd") -Recurse -File | Where-Object { $_.Name -like "*.tmp" })
            Assert-Equal 0 $tempFiles.Count "no temp files remain after writes"

            $cwdLib = Get-SourceOf "src\lib\devws-cwd.ps1"
            Assert-NotContains $cwdLib '$Path.tmp' "cwd writer never uses one fixed .tmp path"
            Assert-Contains $cwdLib '.cwd-' "cwd writer uses unique prefixed temp files"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "resolver accepts a live matching pair and rejects every stale or malformed case" {
        $stateRoot  = Join-Path $TestRoot "p9-resolver-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $existingDir = Join-Path $TestRoot "p9-resolver-dirs\existing"
            $missingDir  = Join-Path $TestRoot "p9-resolver-dirs\does-not-exist"
            New-Item -ItemType Directory -Path $existingDir -Force | Out-Null
            $filePath = Join-Path $TestRoot "p9-resolver-dirs\a-file.txt"
            Set-Content -LiteralPath $filePath -Value "not a directory" -Encoding ASCII

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            $nowIso   = (Get-Date).ToUniversalTime().ToString("o")

            $liveIdentity = [pscustomobject]@{ Alive = $true; StartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime() }
            $deadIdentity = [pscustomobject]@{ Alive = $false; StartTimeUtc = $null }
            $staleIdentity = [pscustomobject]@{ Alive = $true; StartTimeUtc = (Get-Date).ToUniversalTime().AddHours(-5) }

            function New-P9Expected {
                param([hashtable]$Overrides = @{})

                $record = [ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }

                foreach ($key in $Overrides.Keys) { $record[$key] = $Overrides[$key] }
                return $record
            }

            function New-P9Publication {
                param([hashtable]$Overrides = @{})

                $record = [ordered]@{
                    version           = 1
                    setId             = "main"
                    terminalId        = "slot"
                    windowId          = "DevWS-slot"
                    sessionId         = "S1"
                    cwd               = $existingDir
                    shellPid          = $PID
                    shellStartTimeUtc = $startIso
                    updatedAtUtc      = $nowIso
                }

                foreach ($key in $Overrides.Keys) { $record[$key] = $Overrides[$key] }
                return $record
            }

            $cases = @(
                @{ Name = "valid";                     Expect = "ok";                       Available = $true;  Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-missing";          Expect = "expected-missing";          Available = $false; Expected = $null;                                     ExpectedError = "missing";   Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-empty";            Expect = "expected-empty";            Available = $false; Expected = $null;                                     ExpectedError = "empty";     Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-malformed";        Expect = "expected-malformed";        Available = $false; Expected = $null;                                     ExpectedError = "malformed"; Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-version";          Expect = "expected-version";          Available = $false; Expected = (New-P9Expected @{ version = 2 });          ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-schema";           Expect = "expected-schema";           Available = $false; Expected = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot" }); ExpectedError = ""; Pub = (New-P9Publication);               PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-set-mismatch";     Expect = "set-mismatch";              Available = $false; Expected = (New-P9Expected @{ setId = "other" });      ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "expected-terminal-mismatch"; Expect = "terminal-mismatch";        Available = $false; Expected = (New-P9Expected @{ terminalId = "other" }); ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $liveIdentity },
                @{ Name = "publication-missing";       Expect = "publication-missing";       Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = $null;                                                  PubError = "missing";   Identity = $liveIdentity },
                @{ Name = "publication-malformed";     Expect = "publication-malformed";     Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = $null;                                                  PubError = "malformed"; Identity = $liveIdentity },
                @{ Name = "publication-version";       Expect = "publication-version";       Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ version = 9 });                   PubError = "";          Identity = $liveIdentity },
                @{ Name = "publication-schema";        Expect = "publication-schema";        Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ shellStartTimeUtc = $null });     PubError = "";          Identity = $liveIdentity },
                @{ Name = "publication-pid-invalid";   Expect = "publication-schema";        Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ shellPid = "abc" });              PubError = "";          Identity = $liveIdentity },
                @{ Name = "publication-set-mismatch";  Expect = "set-mismatch";              Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ setId = "other" });               PubError = "";          Identity = $liveIdentity },
                @{ Name = "publication-terminal-mismatch"; Expect = "terminal-mismatch";     Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ terminalId = "other" });          PubError = "";          Identity = $liveIdentity },
                @{ Name = "window-mismatch";           Expect = "window-mismatch";           Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ windowId = "DevWS-other" });      PubError = "";          Identity = $liveIdentity },
                @{ Name = "session-mismatch";          Expect = "session-mismatch";          Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ sessionId = "T2" });              PubError = "";          Identity = $liveIdentity },
                @{ Name = "cwd-empty";                 Expect = "cwd-empty";                 Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ cwd = "" });                      PubError = "";          Identity = $liveIdentity },
                @{ Name = "cwd-relative";              Expect = "cwd-relative";              Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ cwd = "relative\path" });         PubError = "";          Identity = $liveIdentity },
                @{ Name = "cwd-missing";               Expect = "cwd-missing";               Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ cwd = $missingDir });             PubError = "";          Identity = $liveIdentity },
                @{ Name = "cwd-not-directory";         Expect = "cwd-not-directory";         Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ cwd = $filePath });               PubError = "";          Identity = $liveIdentity },
                @{ Name = "shell-dead";                Expect = "shell-dead";                Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $deadIdentity },
                @{ Name = "shell-identity-null";       Expect = "shell-dead";                Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $null },
                @{ Name = "shell-identity-malformed";  Expect = "shell-identity-malformed";  Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication @{ shellStartTimeUtc = "not-a-date" }); PubError = "";       Identity = $liveIdentity },
                @{ Name = "shell-identity-mismatch";   Expect = "shell-identity-mismatch";   Available = $false; Expected = (New-P9Expected);                          ExpectedError = "";          Pub = (New-P9Publication);                                    PubError = "";          Identity = $staleIdentity }
            )

            foreach ($case in $cases) {
                $result = Test-DevWSCwdRecordPair `
                    -Expected $case.Expected `
                    -ExpectedReadError $case.ExpectedError `
                    -Publication $case.Pub `
                    -PublicationReadError $case.PubError `
                    -SetId "main" `
                    -TerminalId "slot" `
                    -ProcessIdentity $case.Identity

                Assert-Equal $case.Expect ([string]$result.Reason) "reason: $($case.Name)"
                Assert-Equal $case.Available ([bool]($result.Status -eq "available")) "availability: $($case.Name)"

                if (-not $case.Available) {
                    Assert-True ($null -eq $result.Cwd) "no cwd invented: $($case.Name)"
                }
            }

            # The valid case carries the exact cwd.
            $valid = Test-DevWSCwdRecordPair -Expected (New-P9Expected) -Publication (New-P9Publication) -SetId "main" -TerminalId "slot" -ProcessIdentity $liveIdentity
            Assert-Equal $existingDir $valid.Cwd "valid cwd value"

            # File-based resolver paths (missing/malformed on disk) never throw.
            $missingResolve = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "nothing-here"
            Assert-Equal "unavailable" ([string]$missingResolve.Status) "missing files resolve unavailable"
            Assert-Equal "expected-missing" ([string]$missingResolve.Reason) "missing expected reason"

            $malformedExpectedPath = Join-Path $stateRoot "cwd-sessions\main\malformed.json"
            New-Item -ItemType Directory -Path (Split-Path -Parent $malformedExpectedPath) -Force | Out-Null
            [System.IO.File]::WriteAllText($malformedExpectedPath, "{ not json", [System.Text.UTF8Encoding]::new($false))
            $malformedResolve = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "malformed"
            Assert-Equal "expected-malformed" ([string]$malformedResolve.Reason) "malformed expected reason"
            Assert-True ($null -eq $malformedResolve.Cwd) "malformed expected invents no cwd"

            $malformedPublicationPath = Join-Path $stateRoot "cwd\main\malformed.json"
            $tracking = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "malformed" -WindowId "DevWS-slot"
            New-Item -ItemType Directory -Path (Split-Path -Parent $malformedPublicationPath) -Force | Out-Null
            [System.IO.File]::WriteAllText($malformedPublicationPath, "{ broken", [System.Text.UTF8Encoding]::new($false))
            $malformedPublicationResolve = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "malformed"
            Assert-Equal "publication-malformed" ([string]$malformedPublicationResolve.Reason) "malformed publication reason"
            Assert-True ($null -eq $malformedPublicationResolve.Cwd) "malformed publication invents no cwd"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "stale generations and dead publishers cannot satisfy the resolver" {
        $stateRoot  = Join-Path $TestRoot "p9-stale-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $dir1 = Join-Path $TestRoot "p9-stale-dirs\t1"
            $dir2 = Join-Path $TestRoot "p9-stale-dirs\t2"
            New-Item -ItemType Directory -Path $dir1, $dir2 -Force | Out-Null

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            function New-P9StalePublication {
                param([string]$SessionId, [string]$Cwd, [int]$ProcessId)

                return [ordered]@{
                    version           = 1
                    setId             = "main"
                    terminalId        = "slot"
                    windowId          = "DevWS-slot"
                    sessionId         = $SessionId
                    cwd               = $Cwd
                    shellPid          = $ProcessId
                    shellStartTimeUtc = $startIso
                    updatedAtUtc      = (Get-Date).ToUniversalTime().ToString("o")
                }
            }

            # T1 expected + T1 publication (live publisher) -> available.
            $t1 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId "DevWS-slot"
            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P9StalePublication -SessionId $t1.SessionId -Cwd $dir1 -ProcessId $PID)
            $r1 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot"
            Assert-Equal "available" ([string]$r1.Status) "T1 session resolves"
            Assert-Equal $dir1 ([string]$r1.Cwd) "T1 cwd"

            # DevWS declares T2 (same window identity); the stale T1 publication fails.
            $t2SessionId = New-DevWSCwdSessionId
            Write-DevWSCwdSessionRecord -Path $t1.SessionPath -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = $t2SessionId
            })
            $r2 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot"
            Assert-Equal "session-mismatch" ([string]$r2.Reason) "stale T1 rejected after T2 expected"
            Assert-True ($null -eq $r2.Cwd) "stale T1 never returns cwd"

            # An old shell may keep publishing T1 AFTER T2 exists; still rejected.
            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P9StalePublication -SessionId $t1.SessionId -Cwd $dir1 -ProcessId $PID)
            $r3 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot"
            Assert-Equal "session-mismatch" ([string]$r3.Reason) "old-shell T1 rewrite still rejected"
            Assert-True ($null -eq $r3.Cwd) "old-shell rewrite never returns cwd"

            # T2 publication is accepted normally.
            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P9StalePublication -SessionId $t2SessionId -Cwd $dir2 -ProcessId $PID)
            $r4 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot"
            Assert-Equal "available" ([string]$r4.Status) "T2 publication accepted"
            Assert-Equal $dir2 ([string]$r4.Cwd) "T2 cwd"

            # A dead publisher is rejected even with a token-matching pair.
            $deadProc = Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList "-NoLogo", "-NoProfile", "-Command", "exit" -PassThru
            $deadProc.WaitForExit()
            $deadPid = $deadProc.Id

            $dead = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "dead" -WindowId "DevWS-dead"
            Write-DevWSCwdPublication -Path $dead.PublicationPath -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "dead"; windowId = "DevWS-dead"; sessionId = $dead.SessionId
                cwd = $dir1; shellPid = $deadPid
                shellStartTimeUtc = (Get-Date).ToUniversalTime().ToString("o")
                updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })
            $rDead = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "dead"
            Assert-Equal "shell-dead" ([string]$rDead.Reason) "dead publisher rejected"
            Assert-True ($null -eq $rDead.Cwd) "dead publisher never returns cwd"

            # The shell side has no API/path for the controller-owned expected
            # generation: it cannot rewrite the session record.
            $bootstrapSource = Get-SourceOf "src\helpers\cwd-shell-bootstrap.ps1"
            Assert-NotContains $bootstrapSource "cwd-sessions" "bootstrap never addresses expected-session state"
            Assert-NotContains $bootstrapSource "Get-DevWSCwdSessionPath" "bootstrap has no expected-session API"
            Assert-NotContains $bootstrapSource "SessionPath" "bootstrap receives no session path"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "atomic cwd write retries a transient sharing block without corruption" {
        $target = Join-Path $TestRoot "p9-atomic\publication.json"
        New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null

        Write-DevWSCwdJsonAtomic -Path $target -Object ([ordered]@{ version = 1; marker = "seed" })

        $readyPath = Join-Path $TestRoot "p9-holder-ready.txt"
        $holderPath = Join-Path $TestRoot "p9-holder.ps1"
        Set-Content -LiteralPath $holderPath -Value @'
param([string]$Path, [int]$Milliseconds, [string]$ReadyPath)
$stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
Set-Content -LiteralPath $ReadyPath -Value locked
Start-Sleep -Milliseconds $Milliseconds
$stream.Close()
'@

        $holder = Start-Process `
            -FilePath (Get-Process -Id $PID).Path `
            -ArgumentList @("-NoLogo", "-NoProfile", "-File", $holderPath, "-Path", $target, "-Milliseconds", "800", "-ReadyPath", $readyPath) `
            -PassThru `
            -WindowStyle Hidden

        try {
            $deadline = (Get-Date).AddSeconds(15)

            while (-not (Test-Path -LiteralPath $readyPath -PathType Leaf) -and (Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 50
            }

            Assert-True (Test-Path -LiteralPath $readyPath -PathType Leaf) "holder acquired the blocking handle"

            $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
            Write-DevWSCwdJsonAtomic -Path $target -Object ([ordered]@{ version = 1; marker = "final" }) -RetryCount 30 -RetryDelayMilliseconds 50
            $stopwatch.Stop()

            Assert-True ($stopwatch.ElapsedMilliseconds -ge 150) "replace retried through the sharing block"
            $final = Get-Content -LiteralPath $target -Raw | ConvertFrom-Json
            Assert-Equal "final" $final.marker "final content complete"

            $tempFiles = @(Get-ChildItem -Path (Split-Path -Parent $target) -File | Where-Object { $_.Name -like "*.tmp" })
            Assert-Equal 0 $tempFiles.Count "no temp debris after retry"
        }
        finally {
            if (-not $holder.HasExited) { Stop-Process -Id $holder.Id -Force -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "cwd child spec encoding round-trips exact arguments" {
        $cases = @(
            @{ Command = "devws-shell";   Args = @() },
            @{ Command = "some-tool";  Args = @("-w", "5") },
            @{ Command = "some-tool";  Args = @("--foo", "hello world") },
            @{ Command = "tool";       Args = @("apostrophe's value") },
            @{ Command = "tool";       Args = @("café-ü漢字", 'say "hi"', "") },
            @{ Command = $null;        Args = @() },
            @{ Command = "";           Args = @() }
        )

        foreach ($case in $cases) {
            $encoded = ConvertTo-DevWSCwdChildSpecBase64 -Command $case.Command -Arguments $case.Args
            Assert-True (-not [string]::IsNullOrWhiteSpace($encoded)) "encoded payload: '$($case.Command)'"
            Assert-True (-not ($encoded -match '\s')) "base64 payload has no whitespace"

            $decoded = ConvertFrom-DevWSCwdChildSpecBase64 -Base64 $encoded
            Assert-True ([bool]$decoded.Ok) "decodes: '$($case.Command)'"

            $expectedCommand = $(if ([string]::IsNullOrWhiteSpace($case.Command)) { $null } else { [string]$case.Command })
            Assert-Equal $expectedCommand $decoded.Command "command round-trip: '$($case.Command)'"

            $expectedArgs = @($case.Args)
            $actualArgs   = @($decoded.Arguments)
            Assert-Equal $expectedArgs.Count $actualArgs.Count "arg count: '$($case.Command)'"

            for ($i = 0; $i -lt $expectedArgs.Count; $i++) {
                Assert-Equal ([string]$expectedArgs[$i]) ([string]$actualArgs[$i]) "arg $i round-trip: '$($case.Command)'"
            }
        }

        Assert-Equal "malformed" ([string](ConvertFrom-DevWSCwdChildSpecBase64 -Base64 "!!!not-base64!!!").Reason) "malformed base64 rejected"
        Assert-Equal "missing" ([string](ConvertFrom-DevWSCwdChildSpecBase64 -Base64 "").Reason) "empty payload rejected"
        Assert-Equal "schema" ([string](ConvertFrom-DevWSCwdChildSpecBase64 -Base64 ([Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes('{"command":"x"}')))).Reason) "schema-less payload rejected"
        Assert-Equal "schema" ([string](ConvertFrom-DevWSCwdChildSpecBase64 -Base64 ([Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes('{"command":"x","args":[42]}')))).Reason) "non-string arg rejected"

        $single = ConvertFrom-DevWSCwdChildSpecBase64 -Base64 (ConvertTo-DevWSCwdChildSpecBase64 -Command "tool" -Arguments @("only"))
        Assert-Equal 1 @($single.Arguments).Count "single argument stays an array"
    }

    Test-Case "every configured tab uses the static bootstrap with independent identity" {
        $stateRoot  = Join-Path $TestRoot "p9-tab0-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $terminal = New-TerminalDefinition -Id "tracked" -Path $TestRoot
            $terminal.tabs = @(
                [ordered]@{ command = "tool"; args = @("-w", "5", "--foo", "hello world", "apostrophe's value") },
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = "other"; args = @("--n") }
            )
            $terminal.activeTab = 2

            $item = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]

            $contexts = @(New-DevWSCwdTrackingContexts -SetId "main" -TerminalId "tracked" -WindowId "DevWS-tracked" -Terminal $item)
            $tracked   = @(New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $contexts)
            $legacy    = @(New-DevWSTerminalCreateArguments -Terminal $item)

            $joined = $tracked -join " "
            $bootstrap = Get-DevWSCwdBootstrapPath

            Assert-Equal 3 $contexts.Count "one tracking context per configured tab"
            Assert-Equal 3 ([regex]::Matches($joined, [regex]::Escape($bootstrap)).Count) "bootstrap appears once per tab"
            Assert-Contains $joined "pwsh -NoExit -File $bootstrap" "every tab uses pwsh -NoExit -File"
            Assert-NotContains $joined "-NoProfile" "tracked argv never uses -NoProfile"
            Assert-NotContains $joined "-Command &" "tracked tabs never use the legacy -Command construction"

            for ($tabIndex = 0; $tabIndex -lt 3; $tabIndex++) {
                $context = @($contexts | Where-Object { [int]$_.TabIndex -eq $tabIndex })[0]
                Assert-True ($null -ne $context) "context exists for tab $tabIndex"
                Assert-Contains $joined "-TabIndex $tabIndex" "tabIndex argument present for tab $tabIndex"
                Assert-Contains $joined "-ChildSpecBase64 $($context.ChildSpecBase64)" "child spec argument present for tab $tabIndex"
                Assert-Contains $joined "-PublicationPath $($context.PublicationPath)" "publication path argument present for tab $tabIndex"
                Assert-Contains $joined "-SessionId $($context.SessionId)" "session id argument present for tab $tabIndex"
            }

            Assert-Equal 3 (@($tracked | Where-Object { $_ -eq "new-tab" }).Count) "three tabs"
            Assert-Equal 3 (@($tracked | Where-Object { $_ -eq ";" }).Count) "one WT separator per tab"
            Assert-Contains $joined "focus-tab -t 2" "activeTab preserved"
            $focusIndex = [array]::IndexOf($tracked, "focus-tab")
            Assert-Equal ";" $tracked[$focusIndex - 1] "separator immediately before focus-tab"

            # Every tab still opens in the shared terminal.path: Pass 6B has no
            # per-tab canonical path yet.
            Assert-Equal 3 (@($tracked | Where-Object { $_ -eq $TestRoot }).Count) "all tabs use terminal.path"

            # Tab 0 keeps the historical terminal-level state paths; tabs 1+
            # use indexed disposable state.
            $tab0Context = @($contexts | Where-Object { [int]$_.TabIndex -eq 0 })[0]
            $tab1Context = @($contexts | Where-Object { [int]$_.TabIndex -eq 1 })[0]
            $tab2Context = @($contexts | Where-Object { [int]$_.TabIndex -eq 2 })[0]
            Assert-Equal (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "tracked") $tab0Context.SessionPath "tab 0 keeps the legacy session path"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\tracked\1.json") $tab1Context.SessionPath "tab 1 uses the indexed session path"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\tracked\2.json") $tab2Context.SessionPath "tab 2 uses the indexed session path"

            Assert-Equal 3 (@($contexts | ForEach-Object { $_.SessionId } | Sort-Object -Unique).Count) "three independent session ids"
            Assert-Equal 3 (@($contexts | ForEach-Object { $_.PublicationPath } | Sort-Object -Unique).Count) "three independent publication paths"

            $tab0Expected = Get-Content -LiteralPath $tab0Context.SessionPath -Raw | ConvertFrom-Json
            $tab1Expected = Get-Content -LiteralPath $tab1Context.SessionPath -Raw | ConvertFrom-Json
            Assert-True ($null -eq $tab0Expected.PSObject.Properties["tabIndex"]) "tab 0 expected record omits tabIndex"
            Assert-Equal 1 ([int]$tab1Expected.tabIndex) "tab 1 expected record carries tabIndex"

            $decoded = ConvertFrom-DevWSCwdChildSpecBase64 -Base64 $tab0Context.ChildSpecBase64
            Assert-Equal "tool" ([string]$decoded.Command) "tab-0 child command encoded"
            $decodedArgs = @($decoded.Arguments)
            Assert-Equal 5 $decodedArgs.Count "tab-0 child args count"
            Assert-Equal "-w" ([string]$decodedArgs[0]) "tab-0 arg 0 literal"
            Assert-Equal "--foo" ([string]$decodedArgs[2]) "tab-0 arg 2 literal"
            Assert-Equal "hello world" ([string]$decodedArgs[3]) "tab-0 spaced arg literal"

            $idleDecoded = ConvertFrom-DevWSCwdChildSpecBase64 -Base64 $tab1Context.ChildSpecBase64
            Assert-True ($null -eq $idleDecoded.Command) "idle tab child command is null"

            # The untracked raw construction remains available for the original
            # builder regression tests; it is never a production creation path.
            Assert-Equal 3 (@($legacy | Where-Object { $_ -eq "new-tab" }).Count) "untracked builder still builds tabs"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "tracked tabs cover idle, command-only, and arbitrary tab counts" {
        $stateRoot  = Join-Path $TestRoot "p9-tab0-shapes-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot
            $bootstrap = Get-DevWSCwdBootstrapPath

            # Idle tab 0: child spec is an explicit null command.
            $idle = New-TerminalDefinition -Id "idle0" -Path $TestRoot
            $idle.tabs = @(
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = "second"; args = @("-e") }
            )
            $idle.activeTab = 1
            $idleItem = (ConvertTo-TestConfig -Windows @($idle)).sets[0].windows[0]
            $idleContexts = @(New-DevWSCwdTrackingContexts -SetId "main" -TerminalId "idle0" -WindowId "DevWS-idle0" -Terminal $idleItem)
            $idleArgs = @(New-DevWSTerminalCreateArguments -Terminal $idleItem -TrackingContexts $idleContexts)
            $idleJoined = $idleArgs -join " "
            Assert-Equal 2 ([regex]::Matches($idleJoined, [regex]::Escape($bootstrap)).Count) "both idle/shape tabs track"
            $idleSpec = ConvertFrom-DevWSCwdChildSpecBase64 -Base64 (@($idleContexts | Where-Object { [int]$_.TabIndex -eq 0 })[0].ChildSpecBase64)
            Assert-True ($null -eq $idleSpec.Command) "idle child command is null"
            Assert-Equal 0 @($idleSpec.Arguments).Count "idle child args empty"
            Assert-NotContains $idleJoined "-Command &" "tracked tabs never use the legacy command construction"

            # Command-only single tab.
            $commandOnly = New-TerminalDefinition -Id "cmdonly" -Path $TestRoot
            $commandOnly.tabs = @([ordered]@{ command = "only"; args = @("--foo") })
            $commandOnly.activeTab = 0
            $commandItem = (ConvertTo-TestConfig -Windows @($commandOnly)).sets[0].windows[0]
            $commandContexts = @(New-DevWSCwdTrackingContexts -SetId "main" -TerminalId "cmdonly" -WindowId "DevWS-cmdonly" -Terminal $commandItem)
            $commandArgs = @(New-DevWSTerminalCreateArguments -Terminal $commandItem -TrackingContexts $commandContexts)
            $commandJoined = $commandArgs -join " "
            Assert-Equal 1 ([regex]::Matches($commandJoined, [regex]::Escape($bootstrap)).Count) "command-only tab tracks"
            Assert-NotContains $commandJoined "-Command &" "tracked tab never uses the old -Command form"
            $commandSpec = ConvertFrom-DevWSCwdChildSpecBase64 -Base64 $commandContexts[0].ChildSpecBase64
            Assert-Equal "only" ([string]$commandSpec.Command) "command-only child encoded"

            # Arbitrary tab counts.
            foreach ($tabCount in @(1, 2, 3, 4)) {
                $tabs = @()

                for ($i = 0; $i -lt $tabCount; $i++) {
                    if ($i % 2 -eq 0) { $tabs += [ordered]@{ command = "tool$i"; args = @("--n", "$i") } }
                    else { $tabs += [ordered]@{ command = $null; args = @() } }
                }

                $terminal = New-TerminalDefinition -Id "pt$tabCount" -Path $TestRoot
                $terminal.tabs = $tabs
                $terminal.activeTab = $tabCount - 1

                $item = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]

                $contexts = @(New-DevWSCwdTrackingContexts -SetId "main" -TerminalId "pt$tabCount" -WindowId "DevWS-pt$tabCount" -Terminal $item)
                $built = @(New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $contexts)
                $builtJoined = $built -join " "

                Assert-Equal $tabCount $contexts.Count "$tabCount contexts"
                Assert-Equal $tabCount (@($built | Where-Object { $_ -eq "new-tab" }).Count) "$tabCount tabs built"
                Assert-Equal $tabCount ([regex]::Matches($builtJoined, [regex]::Escape($bootstrap)).Count) "$tabCount tabs: one bootstrap per tab"
                Assert-Contains $builtJoined "focus-tab -t $($tabCount - 1)" "$tabCount tabs: activeTab preserved"

                $focusIndex = [array]::IndexOf($built, "focus-tab")
                Assert-Equal ";" $built[$focusIndex - 1] "$tabCount tabs: separator before focus-tab"
            }
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "tracking bundle guards reject mismatched, partial, or missing bootstrap wiring" {
        $stateRoot  = Join-Path $TestRoot "p9-guards-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $terminal = New-TerminalDefinition -Id "guarded" -Path $TestRoot
            $item = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]

            Assert-Throws { New-DevWSCwdTrackingContexts -SetId "main" -TerminalId "guarded" -WindowId "DevWS-guarded" -Terminal $item -BootstrapPath (Join-Path $TestRoot "no-such-bootstrap.ps1") } "bootstrap helper is missing"

            $contexts = @(New-DevWSCwdTrackingContexts -SetId "main" -TerminalId "guarded" -WindowId "DevWS-guarded" -Terminal $item)
            Assert-Equal @($item.tabs).Count $contexts.Count "one context per configured tab"

            function New-P9TamperedContexts {
                param($Contexts)
                return ,@($Contexts | ForEach-Object { $_.PSObject.Copy() })
            }

            $wrongWindow = New-P9TamperedContexts -Contexts $contexts
            $wrongWindow[0].WindowId = "DevWS-other"
            Assert-Throws { New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $wrongWindow } "windowId 'DevWS-other' does not match"

            $wrongTerminal = New-P9TamperedContexts -Contexts $contexts
            $wrongTerminal[0].TerminalId = "other"
            Assert-Throws { New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $wrongTerminal } "terminalId 'other' does not match"

            $missingBootstrap = New-P9TamperedContexts -Contexts $contexts
            $missingBootstrap[0].BootstrapPath = ""
            Assert-Throws { New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $missingBootstrap } "missing 'BootstrapPath'"

            $partial = @($contexts | Select-Object -First 1)
            Assert-Throws { New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $partial } "tracking context(s)"

            if ($contexts.Count -ge 2) {
                $duplicate = New-P9TamperedContexts -Contexts $contexts
                $duplicate[1].TabIndex = 0
                Assert-Throws { New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $duplicate } "duplicate tracking contexts"

                $outOfRange = New-P9TamperedContexts -Contexts $contexts
                $outOfRange[0].TabIndex = 99
                Assert-Throws { New-DevWSTerminalCreateArguments -Terminal $item -TrackingContexts $outOfRange } "does not address terminal"
            }
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "launch and reset workers create tracking exactly at the safe points" {
        $launch = Get-SourceOf "src\workers\elevated.ps1"
        $reset  = Get-SourceOf "src\workers\elevated-reset.ps1"
        $library = Get-SourceOf "src\lib\devws-terminal-launch.ps1"

        foreach ($worker in @(
            @{ Name = "elevated.ps1"; Source = $launch },
            @{ Name = "elevated-reset.ps1"; Source = $reset }
        )) {
            $configIndex = $worker.Source.IndexOf('devws-config.ps1')
            $cwdIndex    = $worker.Source.IndexOf('devws-cwd.ps1')

            Assert-True ($cwdIndex -gt $configIndex) "$($worker.Name) loads devws-cwd.ps1 after config"
        }

        # The launch worker delegates all tracking/creation policy to the
        # canonical library; reset keeps its own single call sites (Pass 6B:
        # one per-tab context bundle, never a single terminal-level context).
        Assert-Contains $launch "Get-DevWSTerminalLaunchPlan" "elevated.ps1 delegates to the canonical terminal plan"
        Assert-NotContains $launch "New-DevWSCwdTrackingContext" "elevated.ps1 has no local tracking call site"
        Assert-Contains $reset "New-DevWSCwdTrackingContext" "elevated-reset.ps1 uses the tracking context helper"
        Assert-Equal 1 ([regex]::Matches($reset, "New-DevWSCwdTrackingContext").Count) "elevated-reset.ps1 has exactly one tracking call site"
        Assert-Contains $reset "New-DevWSCwdTrackingContexts" "elevated-reset.ps1 builds one context per configured tab"
        Assert-Contains $reset "-TrackingContexts" "elevated-reset.ps1 passes the per-tab bundle to the shared builder"
        Assert-Equal 1 ([regex]::Matches($reset, [regex]::Escape("(New-DevWSTerminalCreateArguments -Terminal")).Count) "elevated-reset.ps1 has exactly one create-args call site"

        # Canonical library: tracking and creation arguments are built only in
        # the launch plan's missing-terminal record branch, after the shared
        # read-only classifier (which must contain no creation work at all).
        $snapshotStart = $library.IndexOf("function Get-DevWSTerminalPresenceSnapshot")
        $planStart     = $library.IndexOf("function Get-DevWSTerminalLaunchPlan")

        Assert-True ($snapshotStart -ge 0 -and $planStart -gt $snapshotStart) "classifier and launch plan located"

        $snapshotRegion = $library.Substring($snapshotStart, $planStart - $snapshotStart)

        Assert-NotContains $snapshotRegion "TrackingContextFactory" "classifier never builds tracking contexts"
        Assert-NotContains $snapshotRegion "CreateArgumentsFactory" "classifier never builds create arguments"
        Assert-NotContains $snapshotRegion "New-DevWSCwdTrackingContext" "classifier never creates cwd tracking contexts"
        Assert-NotContains $snapshotRegion "New-DevWSCwdTrackingSession" "classifier never writes cwd tracking state"

        $classifyIndex = $library.IndexOf("Step 1: state-first exact validation")
        $missingIndex  = $library.IndexOf('$entry.State -ne "missing"')
        $trackingIndex = $library.IndexOf('$tracking = & $TrackingContextFactory $terminal')
        $createIndex   = $library.IndexOf('$createArguments = [string[]]@(& $CreateArgumentsFactory')
        $kickIndex     = $library.IndexOf("function Start-DevWSTerminalLaunchPlan")
        $completeIndex = $library.IndexOf("function Complete-DevWSTerminalLaunchPlan")

        Assert-True ($classifyIndex -ge 0) "classification located"
        Assert-True ($missingIndex -gt $classifyIndex) "missing branch follows classification"
        Assert-True ($trackingIndex -gt $missingIndex) "tracking is created only for a missing terminal"
        Assert-True ($createIndex -gt $trackingIndex) "exact create arguments follow the tracking context"
        Assert-True ($kickIndex -gt $createIndex) "creation arguments exist before kickoff is defined"
        Assert-True ($completeIndex -gt $kickIndex) "completion follows kickoff in the canonical library"

        # Reset: bootstrap checked before the close, generation written only
        # after the old window is confirmed gone, recreation follows.
        $bootstrapIndex = $reset.IndexOf('Get-DevWSCwdBootstrapPath')
        $closeIndex     = $reset.IndexOf('Close-DevWSWindowHwnd')
        $goneIndex      = $reset.IndexOf('Wait-DevWSWindowHwndGone')
        $resetTracking  = $reset.IndexOf('New-DevWSCwdTrackingContext')
        $resetLaunch    = $reset.IndexOf('& $Wt @createArguments')

        Assert-True ($bootstrapIndex -ge 0) "reset resolves the bootstrap helper"
        Assert-True ($bootstrapIndex -lt $closeIndex) "reset refuses before closing when the bootstrap is missing"
        Assert-True ($goneIndex -gt $closeIndex) "reset waits for the old window to disappear"
        Assert-True ($resetTracking -gt $goneIndex) "reset creates the new generation only after the old window is gone"
        Assert-True ($resetLaunch -gt $resetTracking) "reset creates the generation before recreating"

        # A failed/cancelled close must abort before the new generation is
        # written; the throw is the deterministic gate.
        $closeFailIndex = $reset.IndexOf("did not close")
        Assert-True ($closeFailIndex -ge 0 -and $closeFailIndex -lt $resetTracking) "failed close aborts before the new generation"

        Assert-Contains $reset 'Refusing to reset terminal' "reset refuses before destructive work"
    }

    Test-Case "fresh processes load the cwd library and staged workers run with it" {
        $probePath = Join-Path $TestRoot "p9-cwd-lib-probe.ps1"
        Set-Content -LiteralPath $probePath -Value @'
param([Parameter(Mandatory)][string]$LibDir)
. (Join-Path $LibDir "devws-paths.ps1")
. (Join-Path $LibDir "devws-cwd.ps1")

$missing = @()

foreach ($name in @(
    "Get-DevWSCwdBootstrapPath",
    "Get-DevWSCwdSessionPath",
    "Get-DevWSCwdPublicationPath",
    "New-DevWSCwdSessionId",
    "Write-DevWSCwdSessionRecord",
    "Write-DevWSCwdPublication",
    "New-DevWSCwdTrackingSession",
    "Read-DevWSCwdSessionRecord",
    "Read-DevWSCwdPublication",
    "Resolve-DevWSTrackedCwd",
    "Test-DevWSCwdTabRecordPair",
    "ConvertTo-DevWSCwdChildSpecBase64",
    "ConvertTo-DevWSCwdChildSpecJson",
    "Get-DevWSCwdChildSpecFingerprint",
    "ConvertFrom-DevWSCwdChildSpecBase64",
    "New-DevWSCwdTrackingContext",
    "New-DevWSCwdTrackingContexts"
)) {
    if (-not (Get-Command $name -ErrorAction SilentlyContinue)) { $missing += $name }
}

if ($missing.Count -gt 0) {
    Write-Output ("MISSING " + ($missing -join ","))
    exit 1
}

Write-Output "OK"
exit 0
'@

        $output = & pwsh -NoLogo -NoProfile -File $probePath -LibDir (Join-Path $RepoRoot "src\lib") 2>&1 | Out-String
        $code = $LASTEXITCODE

        Assert-Equal 0 $code "cwd library loads in a fresh process"
        Assert-Contains $output "OK" "all cwd functions available in a fresh process"

        # Staged workers actually load the new library in fresh processes.
        $fixture = New-InstallFixture "p9-staged-workers"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture
        $probeFixture = New-WorkerProbeFixture -Name "p9-staged-worker-state"

        $launchRun = Invoke-FreshWorkerRun `
            -WorkerPath (Join-Path $fixture.Privileged "workers\elevated.ps1") `
            -ConfigPath $probeFixture.ConfigPath `
            -StateRoot $probeFixture.StateRoot `
            -Kind "launch" `
            -RequestId ([guid]::NewGuid().ToString()) `
            -Payload @{ setId = "main" }

        Assert-True ($null -ne $launchRun.Result) "staged launch worker wrote a result"
        Assert-Equal $true ([bool]$launchRun.Result.ok) "staged launch worker succeeds with an empty workspace"
        Assert-NotContains ([string]$launchRun.Result.message) "devws-cwd" "staged launch has no cwd dependency failure"

        $resetRun = Invoke-FreshWorkerRun `
            -WorkerPath (Join-Path $fixture.Privileged "workers\elevated-reset.ps1") `
            -ConfigPath $probeFixture.ConfigPath `
            -StateRoot $probeFixture.StateRoot `
            -Kind "reset" `
            -RequestId ([guid]::NewGuid().ToString()) `
            -Payload @{ setId = "main"; terminalPlacements = @([ordered]@{ id = "probe"; move = $true; x = 0; y = 0; w = 100; h = 100 }) }

        Assert-True ($null -ne $resetRun.Result) "staged reset worker wrote a result"
        Assert-Contains ([string]$resetRun.Result.message) "No configured terminal with id 'probe'" "staged reset reaches its intended post-validation error"
        Assert-NotContains ([string]$resetRun.Result.message) "devws-cwd" "staged reset has no cwd dependency failure"

        # No-retroactive-tracking proof: a normal launch over an empty set
        # creates no tracking state at all.
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $probeFixture.StateRoot "cwd"))) "staged launch creates no publication state"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $probeFixture.StateRoot "cwd-sessions"))) "staged launch creates no session state"
    }

