    Test-Case "bootstrap publishes before a blocking child and stays interactive" {
        $root = Join-Path $TestRoot "p9-bootstrap-run"
        $work = Join-Path $root "work"
        $state = Join-Path $root "state"
        New-Item -ItemType Directory -Path $work, $state -Force | Out-Null

        $publicationPath = Join-Path $state "cwd\main\slot.json"
        $marker = Join-Path $root "child-done.txt"
        $childScriptPath = Join-Path $root "p9-child-args.ps1"
        $childBody = @'
Set-Content -LiteralPath '__MARKER__' -Value ($args -join '|')
Start-Sleep -Seconds 6
'@
        Set-Content -LiteralPath $childScriptPath -Value $childBody.Replace('__MARKER__', $marker)
        $childSpec = ConvertTo-DevWSCwdChildSpecBase64 -Command "pwsh" -Arguments @("-NoProfile", "-File", $childScriptPath, "-w", "5", "--foo", "hello world", "apostrophe's value", "café-ü漢字")

        $process = Start-FreshCwdBootstrapProcess `
            -BootstrapPath (Get-DevWSCwdBootstrapPath) `
            -SetId "main" `
            -TerminalId "slot" `
            -WindowId "DevWS-slot" `
            -SessionId "fresh-bootstrap-1" `
            -PublicationPath $publicationPath `
            -ChildSpecBase64 $childSpec `
            -WorkingDirectory $work

        try {
            $deadline = (Get-Date).AddSeconds(25)

            while (-not (Test-Path -LiteralPath $publicationPath -PathType Leaf) -and (Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 150
            }

            Assert-True (Test-Path -LiteralPath $publicationPath -PathType Leaf) "initial publication exists"

            $publication = Get-Content -LiteralPath $publicationPath -Raw | ConvertFrom-Json
            Assert-Equal $work ([string]$publication.cwd) "initial cwd is the shell start directory"
            Assert-Equal "fresh-bootstrap-1" ([string]$publication.sessionId) "session id published"
            Assert-Equal $process.Id ([int]$publication.shellPid) "publisher pid published"
            Assert-True (-not [string]::IsNullOrWhiteSpace([string]$publication.shellStartTimeUtc)) "publisher start time published"

            # The bootstrap publishes the initial record BEFORE it launches the
            # child, so publication existence does not imply the child is already
            # visible in the process table. A single snapshot here is a race on
            # a slow host; wait for the actual condition instead of assuming the
            # scheduler has run.
            $child = $null
            $childDeadline = (Get-Date).AddSeconds(10)

            while ($null -eq $child -and (Get-Date) -lt $childDeadline) {
                $child = @(Get-CimInstance Win32_Process -Filter "ParentProcessId=$($process.Id)" -ErrorAction SilentlyContinue |
                    Where-Object { $_.Name -eq "pwsh.exe" }) | Select-Object -First 1

                if ($null -eq $child) {
                    Start-Sleep -Milliseconds 100
                }
            }

            Assert-True ($null -ne $child) "blocking child is running after the initial publication"

            $deadline = (Get-Date).AddSeconds(30)

            while (-not (Test-Path -LiteralPath $marker -PathType Leaf) -and (Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 150
            }

            Assert-True (Test-Path -LiteralPath $marker -PathType Leaf) "blocking child completed"
            Assert-Equal "-w|5|--foo|hello world|apostrophe's value|café-ü漢字" (Get-Content -LiteralPath $marker -Raw).Trim() "child args decoded as an array in exact order (switch-looking, spaced, quoted, Unicode)"

            $publicationTime = (Get-Item -LiteralPath $publicationPath).LastWriteTimeUtc
            $markerTime      = (Get-Item -LiteralPath $marker).LastWriteTimeUtc
            Assert-True ($publicationTime -le $markerTime) "publication precedes the child side effect"

            Start-Sleep -Milliseconds 500
            Assert-True (-not $process.HasExited) "shell stays interactive after the child returns"
        }
        finally {
            if (-not $process.HasExited) { Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue }
        }

        $bootstrapSource = Get-SourceOf "src\helpers\cwd-shell-bootstrap.ps1"
        Assert-Contains $bootstrapSource '$global:DevWSCwdOriginalPrompt = $function:prompt' "original prompt captured"
        Assert-Contains $bootstrapSource '& $global:DevWSCwdOriginalPrompt' "original prompt delegated"

        $promptStart   = $bootstrapSource.IndexOf('function global:prompt')
        $saveIndex     = $bootstrapSource.IndexOf('$savedLastExitCode = $global:LASTEXITCODE', $promptStart)
        $publishIndex  = $bootstrapSource.IndexOf('Write-DevWSCwdBootstrapPublication', $promptStart)
        $restoreIndex  = $bootstrapSource.IndexOf('$global:LASTEXITCODE = $savedLastExitCode', $promptStart)
        $delegateIndex = $bootstrapSource.IndexOf('& $global:DevWSCwdOriginalPrompt', $promptStart)

        Assert-True ($promptStart -ge 0 -and $saveIndex -gt $promptStart -and $saveIndex -lt $publishIndex -and $publishIndex -lt $restoreIndex -and $restoreIndex -lt $delegateIndex) "prompt wrapper preserves LASTEXITCODE around publication"
    }

    Test-Case "bootstrap hands the exact decoded argv to script and native children" {
        # Execution-level regression for the tracked tab-0 child handoff. The
        # static bootstrap decodes ChildSpecBase64 itself; these cases run the
        # REAL helper and observe what the child process actually receives.
        #
        # A configured tab command such as an npm shim (`devws-shell`) resolves to
        # a PowerShell SCRIPT child. Invoking it with the decoded argument array
        # as a single token delivered the WHOLE array as one object argument:
        # `args = []` then reached the real child as one empty-string
        # positional argument (the tool treats that as a directory and fails in
        # chdir), while `["-w","5"]` collapsed into one joined argument. `[]`
        # (zero arguments) and `[""]` (one empty-string argument) must stay
        # distinct, and argv/cwd must match a manual invocation for both child
        # kinds.
        $root  = Join-Path $TestRoot "cwd-child-argv"
        $work  = Join-Path $root "work"
        $state = Join-Path $root "state"
        $out   = Join-Path $root "out"
        New-Item -ItemType Directory -Path $work, $state, $out -Force | Out-Null

        $pwshPath = (Get-Process -Id $PID).Path

        # Disposable probe: records the exact argv, OS current directory and
        # PowerShell location that the child process actually received.
        $dumpPath = Join-Path $root "argv-dump.ps1"
        $dumpBody = @'
$payload = [ordered]@{
    argc  = @($args).Count
    args  = @(@($args) | ForEach-Object { [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes([string]$_)) })
    cwd   = [Environment]::CurrentDirectory
    psCwd = (Get-Location).ProviderPath
    pwd   = [string]$env:PWD
}
Set-Content -LiteralPath $env:DEVWS_ARGV_DUMP_OUT -Value ($payload | ConvertTo-Json -Compress) -Encoding UTF8
'@
        Set-Content -LiteralPath $dumpPath -Value $dumpBody -Encoding UTF8

        # Mirror of a generated npm .ps1 shim: records the argument OBJECTS the
        # script child received, then forwards them to the native child exactly
        # the way the generated npm shim does.
        $shimPath = Join-Path $root "shim.ps1"
        $shimBody = @'
$received = @($args)
$shimRecord = [ordered]@{
    count = $received.Count
    types = @($received | ForEach-Object { if ($null -eq $_) { 'null' } else { $_.GetType().FullName } })
}
Set-Content -LiteralPath $env:DEVWS_SHIM_DUMP_OUT -Value ($shimRecord | ConvertTo-Json -Compress) -Encoding UTF8
& '__EXE__' -NoProfile -File '__DUMP__' $args
exit $LASTEXITCODE
'@
        $shimBody = $shimBody.Replace('__EXE__', $pwshPath).Replace('__DUMP__', $dumpPath)
        Set-Content -LiteralPath $shimPath -Value $shimBody -Encoding UTF8

        # Direct/manual-equivalent reference: an identical child started by a
        # plain pwsh from the same working directory, nothing overridden. The
        # child-visible PWD is compared against this reference (the bootstrap
        # must never invent a different cwd environment for the child).
        $referenceOut = Join-Path $out "reference.json"
        Remove-Item -LiteralPath $referenceOut -Force -ErrorAction SilentlyContinue
        $env:DEVWS_ARGV_DUMP_OUT = $referenceOut
        $reference = Start-Process -FilePath $pwshPath -ArgumentList @('-NoProfile','-File',$dumpPath) -WorkingDirectory $work -PassThru -WindowStyle Hidden
        $null = $reference.WaitForExit(30000)
        $refRecord = Get-Content -LiteralPath $referenceOut -Raw | ConvertFrom-Json
        Assert-True ($null -ne $refRecord) "manual reference child produced a record"

        $cases = @(
            @{ Name = "empty";      Args = @();                     Expected = @() },
            @{ Name = "one-empty";  Args = @("");                   Expected = @("") },
            @{ Name = "abc";        Args = @("abc");                Expected = @("abc") },
            @{ Name = "switch-w5";  Args = @("-w","5");             Expected = @("-w","5") },
            @{ Name = "hello";      Args = @("hello world");        Expected = @("hello world") },
            @{ Name = "apostrophe"; Args = @("apostrophe's value"); Expected = @("apostrophe's value") },
            @{ Name = "say-hi";     Args = @('say "hi"');           Expected = @('say "hi"') },
            @{ Name = "unicode";    Args = @("café-ü漢字");         Expected = @("café-ü漢字") }
        )

        foreach ($chain in @("native", "shim")) {
            foreach ($case in $cases) {
                $label = "$chain/$($case.Name)"
                $publicationPath = Join-Path $state ("cwd\main\$chain-$($case.Name).json")
                $dumpOut = Join-Path $out "$chain-$($case.Name).json"
                $shimOut = Join-Path $out "$chain-$($case.Name).shim.json"
                Remove-Item -LiteralPath $dumpOut, $shimOut -Force -ErrorAction SilentlyContinue
                $env:DEVWS_ARGV_DUMP_OUT = $dumpOut
                $env:DEVWS_SHIM_DUMP_OUT = $shimOut

                if ($chain -eq "native") {
                    # The child is a native process receiving the decoded argv.
                    $command = $pwshPath
                    $childArgs = @('-NoProfile', '-File', $dumpPath) + @($case.Args)
                }
                else {
                    # The child is a PowerShell script (the production shape for
                    # a configured npm shim) that forwards to a native process.
                    $command = $shimPath
                    $childArgs = @($case.Args)
                }

                $childSpec = ConvertTo-DevWSCwdChildSpecBase64 -Command $command -Arguments $childArgs
                $process = Start-FreshCwdBootstrapProcess `
                    -BootstrapPath (Get-DevWSCwdBootstrapPath) `
                    -SetId "main" `
                    -TerminalId "proxy" `
                    -WindowId "DevWS-proxy" `
                    -SessionId "argv-$chain-$($case.Name)" `
                    -PublicationPath $publicationPath `
                    -ChildSpecBase64 $childSpec `
                    -WorkingDirectory $work

                try {
                    $deadline = (Get-Date).AddSeconds(25)
                    while (-not (Test-Path -LiteralPath $dumpOut -PathType Leaf) -and (Get-Date) -lt $deadline) {
                        Start-Sleep -Milliseconds 100
                    }

                    Assert-True (Test-Path -LiteralPath $dumpOut -PathType Leaf) "$label child produced a record"
                    $record = Get-Content -LiteralPath $dumpOut -Raw | ConvertFrom-Json
                    $actual = @($record.args | ForEach-Object { [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($_)) })

                    Assert-Equal ([int]$case.Expected.Count) ([int]$record.argc) "$label argv count"
                    Assert-Equal (($case.Expected) -join "|") ($actual -join "|") "$label exact argv values and order"
                    Assert-Equal $work ([string]$record.cwd) "$label child-visible current directory"
                    Assert-Equal $work ([string]$record.psCwd) "$label child PowerShell location"
                    Assert-Equal ([string]$refRecord.pwd) ([string]$record.pwd) "$label child-visible PWD matches a manual child"

                    if ($chain -eq "shim") {
                        Assert-True (Test-Path -LiteralPath $shimOut -PathType Leaf) "$label shim produced a record"
                        $shimRecord = Get-Content -LiteralPath $shimOut -Raw | ConvertFrom-Json
                        Assert-Equal ([int]$case.Expected.Count) ([int]$shimRecord.count) "$label script child received the expected argument count"
                        Assert-Equal 0 @($shimRecord.types | Where-Object { $_ -eq "System.Object[]" }).Count "$label script child never receives the raw argument array as one object"
                    }
                }
                finally {
                    if (-not $process.HasExited) { Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue }
                }
            }
        }

        # The pair that must never collapse into each other, asserted straight
        # from the script-child chain records.
        $emptyRecord    = Get-Content -LiteralPath (Join-Path $out "shim-empty.json") -Raw | ConvertFrom-Json
        $oneEmptyRecord = Get-Content -LiteralPath (Join-Path $out "shim-one-empty.json") -Raw | ConvertFrom-Json
        Assert-Equal 0 ([int]$emptyRecord.argc) "empty args produce ZERO real child arguments"
        Assert-Equal 1 ([int]$oneEmptyRecord.argc) "one empty-string arg produces exactly ONE real child argument"
        Assert-Equal "" ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(@($oneEmptyRecord.args)[0]))) "the single argument is the empty string"

        Remove-Item Env:\DEVWS_ARGV_DUMP_OUT -ErrorAction SilentlyContinue
        Remove-Item Env:\DEVWS_SHIM_DUMP_OUT -ErrorAction SilentlyContinue
    }

    Test-Case "bootstrap rejects malformed child specs and survives publication failure" {
        # Malformed payload: stay alive, execute nothing, log the error.
        $root = Join-Path $TestRoot "p9-bootstrap-malformed"
        $work = Join-Path $root "work"
        $state = Join-Path $root "state"
        New-Item -ItemType Directory -Path $work, $state -Force | Out-Null

        $publicationPath = Join-Path $state "cwd\main\slot.json"
        $marker = Join-Path $root "should-not-exist.txt"

        $process = Start-FreshCwdBootstrapProcess `
            -BootstrapPath (Get-DevWSCwdBootstrapPath) `
            -SetId "main" `
            -TerminalId "slot" `
            -WindowId "DevWS-slot" `
            -SessionId "malformed-1" `
            -PublicationPath $publicationPath `
            -ChildSpecBase64 "!!!not-base64!!!" `
            -WorkingDirectory $work

        try {
            $logPath = Join-Path (Split-Path -Parent $publicationPath) "bootstrap-errors.log"
            $deadline = (Get-Date).AddSeconds(20)

            while (-not (Test-Path -LiteralPath $logPath -PathType Leaf) -and (Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 150
            }

            Assert-True (Test-Path -LiteralPath $logPath -PathType Leaf) "malformed spec logged"
            Assert-Contains (Get-Content -LiteralPath $logPath -Raw) "child spec rejected" "malformed spec rejection recorded"
            Assert-True (-not (Test-Path -LiteralPath $marker)) "malformed spec executes nothing"
            Assert-True (-not $process.HasExited) "malformed spec leaves the shell alive"
        }
        finally {
            if (-not $process.HasExited) { Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue }
        }

        # Publication failure: the configured child still runs.
        $root2 = Join-Path $TestRoot "p9-bootstrap-pubfail"
        $work2 = Join-Path $root2 "work"
        New-Item -ItemType Directory -Path $work2, $root2 -Force | Out-Null

        $blockedParent = Join-Path $root2 "blocked"
        Set-Content -LiteralPath $blockedParent -Value "a file where a directory is needed" -Encoding ASCII

        $publicationPath2 = Join-Path $blockedParent "cwd\main\slot.json"
        $marker2 = Join-Path $root2 "child-ran.txt"
        $childScriptPath2 = Join-Path $root2 "p9-child-ran.ps1"
        $childBody2 = @'
Set-Content -LiteralPath '__MARKER__' -Value ran
'@
        Set-Content -LiteralPath $childScriptPath2 -Value $childBody2.Replace('__MARKER__', $marker2)
        $childSpec2 = ConvertTo-DevWSCwdChildSpecBase64 -Command "pwsh" -Arguments @("-NoProfile", "-File", $childScriptPath2)

        $process2 = Start-FreshCwdBootstrapProcess `
            -BootstrapPath (Get-DevWSCwdBootstrapPath) `
            -SetId "main" `
            -TerminalId "slot" `
            -WindowId "DevWS-slot" `
            -SessionId "pubfail-1" `
            -PublicationPath $publicationPath2 `
            -ChildSpecBase64 $childSpec2 `
            -WorkingDirectory $work2

        try {
            $deadline = (Get-Date).AddSeconds(25)

            while (-not (Test-Path -LiteralPath $marker2 -PathType Leaf) -and (Get-Date) -lt $deadline) {
                Start-Sleep -Milliseconds 150
            }

            Assert-True (Test-Path -LiteralPath $marker2 -PathType Leaf) "configured child ran despite publication failure"
            Assert-True (-not (Test-Path -LiteralPath $publicationPath2 -PathType Leaf)) "impossible publication path was never written"
            Assert-True (-not $process2.HasExited) "shell stays alive after a publication failure"
        }
        finally {
            if (-not $process2.HasExited) { Stop-Process -Id $process2.Id -Force -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Phase 9 Pass 2 wires ws save and keeps save-layout geometry-only" {
        $wsSource = Get-SourceOf "src\ws.ps1"

        Assert-Contains $wsSource "ws save [set]" "help lists ws save"
        Assert-NotContains $wsSource "There is no ws save command yet" "old absence note removed"
        Assert-Contains $wsSource '"save" {' "save dispatch case exists"
        Assert-Contains $wsSource "Save-DevWSWorkspace" "save implementation present"
        Assert-Contains $wsSource "Get-DevWSLiveLayoutCapture" "shared geometry capture helper present"
        Assert-Contains $wsSource "Resolve-DevWSTrackedCwd" "save consumes the tracked-cwd resolver"
        Assert-Contains $wsSource "Confirm-DevWSTerminalSaveDecisions" "save revalidates the per-tab expected generation before commit"
        Assert-Contains $wsSource "Test-DevWSCwdExpectedGeneration" "save revalidates through the shared expected-generation validator"
        Assert-NotContains $wsSource "New-DevWSCwdTrackingSession" "save never creates tracking generations"
        Assert-NotContains $wsSource "Invoke-DevWSSave" "no legacy save implementation name"

        $pathsIndex = $wsSource.IndexOf("devws-paths.ps1")
        $cwdIndex   = $wsSource.IndexOf("devws-cwd.ps1")
        Assert-True ($cwdIndex -gt $pathsIndex) "ws.ps1 imports devws-cwd.ps1 after its paths prerequisite"

        # save-layout must not consume cwd behavior at all.
        $layoutStart = $wsSource.IndexOf("function Save-DevWSLayout")
        $layoutEnd   = $wsSource.IndexOf("function Save-DevWSWorkspace")
        Assert-True ($layoutStart -ge 0 -and $layoutEnd -gt $layoutStart) "save-layout function located"
        $layoutRegion = $wsSource.Substring($layoutStart, $layoutEnd - $layoutStart)
        Assert-NotContains $layoutRegion "Resolve-DevWSTrackedCwd" "save-layout never resolves cwd"
        Assert-NotContains $layoutRegion "cwd" "save-layout has no cwd behavior"
        Assert-NotContains $layoutRegion "activeTab" "save-layout never touches the active tab"
        Assert-NotContains $layoutRegion "Invoke-DevWSTerminalSaveState" "save-layout never applies the save-state planner"
        Assert-NotContains $layoutRegion "Get-DevWSTerminalActiveTabSaveDecision" "save-layout never correlates active-tab snapshots"

        $cwdLib = Get-SourceOf "src\lib\devws-cwd.ps1"
        Assert-NotContains $cwdLib "workspace.json" "cwd state never touches canonical config"
        Assert-NotContains $cwdLib "Save-DevWSConfig" "cwd library never saves canonical config"
        Assert-NotContains $cwdLib "runtime-state" "cwd state is separate from runtime state"
        Assert-NotContains $cwdLib "activeTab" "no active-tab cwd logic"
        Assert-NotContains $cwdLib "Win32_Process" "no child process cwd inspection"
        Assert-NotContains $cwdLib "GetCurrentDirectory" "no process cwd guessing"
        Assert-NotContains $cwdLib "PSReadLine" "no command interception"

        $bootstrapSource = Get-SourceOf "src\helpers\cwd-shell-bootstrap.ps1"
        Assert-NotContains $bootstrapSource '$PROFILE' "bootstrap never touches the user profile"
        Assert-NotContains $bootstrapSource 'Set-Location' "bootstrap does not intercept cd"
        Assert-NotContains $bootstrapSource 'activeTab' "bootstrap has no active-tab logic"
        Assert-NotContains $bootstrapSource 'Win32_Process' "bootstrap never inspects child processes"

        foreach ($file in @(Get-ChildItem -Path (Join-Path $RepoRoot "src") -Recurse -Filter "*.ps1" -File)) {
            $content = Get-Content -LiteralPath $file.FullName -Raw
            Assert-True (-not ($content -match '(Set-Content|Add-Content|Out-File)[^\r\n]*\$PROFILE')) "$($file.Name) never writes the user profile"
        }

        Assert-Equal 2 (New-DevWSRuntimeState).version "runtime state schema stays v2"
    }

    Test-Case "ws save applies geometry plus available cwd in one atomic write" {
        $target = New-LifecycleConfigCopy "p9-save-mix"
        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        $alphaCwd = Join-Path $TestRoot "p9-save-mix-alpha"
        New-Item -ItemType Directory -Path $alphaCwd -Force | Out-Null

        $script:P9SaveCapture = [ordered]@{
            TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
                editor  = @{ x = 61; y = 62; w = 63; h = 64 }
            }
            FailAppId     = $null
            InvalidAppId  = $null
        }
        $script:P9SaveRectByHwnd = @{}
        $script:P9SaveConfigCalls = 0
        $script:P9SaveResolverCalls = [System.Collections.Generic.List[object]]::new()
        $script:P9SaveCwdResults = @{
            termalpha = [pscustomobject]@{ Status = "available";   Reason = "ok";               Cwd = $alphaCwd; SessionId = "MIX-TA"; WindowId = "DevWS-secondary-termalpha" }
            termbeta  = [pscustomobject]@{ Status = "available";   Reason = "ok";               Cwd = $TestRoot; SessionId = "MIX-TB"; WindowId = "DevWS-secondary-termbeta" }
            "1"       = [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null;     SessionId = $null;    WindowId = $null }
        }

        $p9OriginalSaveConfig = ${function:Save-DevWSConfig}

        function Save-DevWSConfig {
            param($Config, $Location)
            $script:P9SaveConfigCalls++
            & $p9OriginalSaveConfig -Config $Config -Location $Location
        }

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)

            if ($script:P9SaveCapture.FailAppId -eq [string]$App.id) {
                throw "Application '$SetId/$($App.id)' window was not found; nothing was saved."
            }

            $hwnd = [long](800000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $valid = ($script:P9SaveCapture.InvalidAppId -ne [string]$App.id)
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{
                Valid = $valid
                x     = [int]$rect.x
                y     = [int]$rect.y
                w     = [int]$rect.w
                h     = [int]$rect.h
            }
            return $hwnd
        }

        function Get-DevWSWindowHwndRect {
            param([long]$Hwnd)
            return $script:P9SaveRectByHwnd[$Hwnd]
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)
            $script:P9SaveResolverCalls.Add([pscustomobject]@{ SetId = $SetId; TerminalId = $TerminalId; TabIndex = $TabIndex })

            if ($script:P9SaveCwdResults.ContainsKey($TerminalId)) {
                $result = $script:P9SaveCwdResults[$TerminalId]

                if ([string]$result.Status -eq "available") {
                    # A real available resolution implies the controller-owned
                    # expected generation exists; the save transaction
                    # revalidates it before committing.
                    Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId $SetId -TerminalId $TerminalId -TabIndex $TabIndex) -Record ([ordered]@{
                        version = 1; setId = $SetId; terminalId = $TerminalId; windowId = $result.WindowId; sessionId = $result.SessionId
                    })
                }

                return $result
            }

            return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null; SessionId = $null; WindowId = $null }
        }

        try {
            $configBefore = Read-DevWSConfigFile -Path $target
            $mainBefore   = ConvertTo-Json -InputObject @($configBefore.sets[0].windows) -Depth 20

            $text = (& { Save-DevWSWorkspace -SetId "secondary" } *>&1 | Out-String)

            Assert-Contains $text "State saved for set 'secondary'." "save names the set"
            Assert-Contains $text "cwd updated: $alphaCwd" "available new cwd reported as updated"
            Assert-Contains $text "cwd unchanged: $TestRoot" "available same cwd reported as unchanged"
            Assert-Contains $text "cwd unavailable (expected-missing); path kept: $TestRoot" "unavailable cwd reason reported"

            Assert-Equal 1 $script:P9SaveConfigCalls "exactly one canonical save"
            Assert-Equal 3 $script:P9SaveResolverCalls.Count "only enabled terminals are resolved"
            Assert-Equal "termalpha,termbeta,1" ((@($script:P9SaveResolverCalls | ForEach-Object { $_.TerminalId })) -join ",") "enabled terminal set"
            Assert-True (@($script:P9SaveResolverCalls | Where-Object { $_.SetId -ne "secondary" }).Count -eq 0) "resolver scoped to the target set"
            Assert-True (@($script:P9SaveResolverCalls | Where-Object { $_.TerminalId -eq "offterm" }).Count -eq 0) "disabled terminal never queried"

            $config = Read-DevWSConfigFile -Path $target
            $mainAfter = ConvertTo-Json -InputObject @($config.sets[0].windows) -Depth 20
            Assert-Equal $mainBefore $mainAfter "main set untouched by secondary save"
            Assert-Equal "main" $config.defaultSet "save never changes defaultSet"

            $secondary = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]
            Assert-Equal 11 @($secondary.windows | Where-Object { $_.id -eq "browser" })[0].layout.x "app geometry updated"
            Assert-Equal 21 @($secondary.windows | Where-Object { $_.id -eq "notes" })[0].layout.x "second app geometry updated"
            Assert-Equal 31 @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].layout.x "terminal geometry updated"
            Assert-Equal 51 @($secondary.windows | Where-Object { $_.id -eq "1" })[0].layout.x "literal-id terminal geometry updated"
            Assert-Equal 0  @($secondary.windows | Where-Object { $_.id -eq "offterm" })[0].layout.x "disabled item layout untouched"

            Assert-Equal $alphaCwd @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].path "available new cwd persisted"
            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "termbeta" })[0].path "available same cwd leaves path unchanged"
            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "1" })[0].path "unavailable cwd leaves path unchanged"
            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "offterm" })[0].path "disabled terminal path untouched"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "ws save geometry failure is atomic and never resolves cwd" {
        $target = New-LifecycleConfigCopy "p9-save-geometry-fail"
        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        $script:P9SaveCapture = [ordered]@{
            TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
            }
            FailAppId     = $null
            InvalidAppId  = $null
        }
        $script:P9SaveRectByHwnd = @{}
        $script:P9SaveConfigCalls = 0
        $script:P9SaveResolverCalls = 0

        $p9OriginalSaveConfig = ${function:Save-DevWSConfig}

        function Save-DevWSConfig {
            param($Config, $Location)
            $script:P9SaveConfigCalls++
            & $p9OriginalSaveConfig -Config $Config -Location $Location
        }

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)

            if ($script:P9SaveCapture.FailAppId -eq [string]$App.id) {
                throw "Application '$SetId/$($App.id)' window was not found; nothing was saved."
            }

            $hwnd = [long](810000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $valid = ($script:P9SaveCapture.InvalidAppId -ne [string]$App.id)
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{ Valid = $valid; x = [int]$rect.x; y = [int]$rect.y; w = [int]$rect.w; h = [int]$rect.h }
            return $hwnd
        }

        function Get-DevWSWindowHwndRect {
            param([long]$Hwnd)
            return $script:P9SaveRectByHwnd[$Hwnd]
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)
            $script:P9SaveResolverCalls++
            return [pscustomobject]@{ Status = "available"; Reason = "ok"; Cwd = $TestRoot }
        }

        try {
            $before = Get-FileBase64 -Path $target

            # 1. Unresolved app.
            $script:P9SaveCapture.FailAppId = "notes"
            Assert-Throws { Save-DevWSWorkspace -SetId "secondary" } "window was not found"
            Assert-Equal $before (Get-FileBase64 -Path $target) "unresolved app leaves canonical bytes unchanged"
            Assert-Equal 0 $script:P9SaveResolverCalls "cwd is never resolved after an app failure"
            Assert-Equal 0 $script:P9SaveConfigCalls "no canonical save after an app failure"

            # 2. Invalid (minimized) app geometry.
            $script:P9SaveCapture.FailAppId = $null
            $script:P9SaveCapture.InvalidAppId = "notes"
            Assert-Throws { Save-DevWSWorkspace -SetId "secondary" } "minimized or invalid"
            Assert-Equal $before (Get-FileBase64 -Path $target) "invalid app geometry leaves canonical bytes unchanged"
            Assert-Equal 0 $script:P9SaveResolverCalls "cwd is never resolved after invalid app geometry"
            Assert-Equal 0 $script:P9SaveConfigCalls "no canonical save after invalid app geometry"

            # 3. Incomplete terminal capture.
            $script:P9SaveCapture.InvalidAppId = $null
            $script:P9SaveCapture.TerminalLines = @("termalpha|31|32|33|34")
            Assert-Throws { Save-DevWSWorkspace -SetId "secondary" } "was not captured"
            Assert-Equal $before (Get-FileBase64 -Path $target) "incomplete terminal capture leaves canonical bytes unchanged"
            Assert-Equal 0 $script:P9SaveResolverCalls "cwd is never resolved after a terminal capture failure"
            Assert-Equal 0 $script:P9SaveConfigCalls "no canonical save after a terminal capture failure"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

