    Test-Case "ws save consumes the real resolver and leaves tracking state byte-identical" {
        $target = New-LifecycleConfigCopy "p9-save-real-resolver"
        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target

        $stateRoot = Join-Path $TestRoot "p9-save-real-state"
        $env:DEVWS_STATE_ROOT = $stateRoot

        $script:P9SaveCapture = [ordered]@{
            TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
            }
        }
        $script:P9SaveRectByHwnd = @{}
        $script:P9SaveConfigCalls = 0

        $p9OriginalSaveConfig = ${function:Save-DevWSConfig}

        function Save-DevWSConfig {
            param($Config, $Location)
            $script:P9SaveConfigCalls++
            & $p9OriginalSaveConfig -Config $Config -Location $Location
        }

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
            $hwnd = [long](830000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{ Valid = $true; x = [int]$rect.x; y = [int]$rect.y; w = [int]$rect.w; h = [int]$rect.h }
            return $hwnd
        }

        function Get-DevWSWindowHwndRect {
            param([long]$Hwnd)
            return $script:P9SaveRectByHwnd[$Hwnd]
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        try {
            $alphaCwd = Join-Path $TestRoot "p9-save-real-alpha"
            New-Item -ItemType Directory -Path $alphaCwd -Force | Out-Null

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            $nowIso   = (Get-Date).ToUniversalTime().ToString("o")

            # Available: secondary/termalpha has a matching live publisher.
            $alphaSession = Get-DevWSCwdSessionPath -SetId "secondary" -TerminalId "termalpha"
            $alphaPublication = Get-DevWSCwdPublicationPath -SetId "secondary" -TerminalId "termalpha"
            Write-DevWSCwdSessionRecord -Path $alphaSession -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "termalpha"; windowId = "DevWS-secondary-termalpha"; sessionId = "alpha-T1"
            })
            Write-DevWSCwdPublication -Path $alphaPublication -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "termalpha"; windowId = "DevWS-secondary-termalpha"; sessionId = "alpha-T1"
                cwd = $alphaCwd; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = $nowIso
            })

            # Stale: secondary/1 expected T2 with an old T1 publication.
            $staleSession = Get-DevWSCwdSessionPath -SetId "secondary" -TerminalId "1"
            $stalePublication = Get-DevWSCwdPublicationPath -SetId "secondary" -TerminalId "1"
            Write-DevWSCwdSessionRecord -Path $staleSession -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "1"; windowId = "DevWS-secondary-1"; sessionId = "one-T2"
            })
            Write-DevWSCwdPublication -Path $stalePublication -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "1"; windowId = "DevWS-secondary-1"; sessionId = "one-T1"
                cwd = $alphaCwd; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = $nowIso
            })

            # Disabled ofterm has fully valid tracking state that must not be consumed.
            $offSession = Get-DevWSCwdSessionPath -SetId "secondary" -TerminalId "offterm"
            $offPublication = Get-DevWSCwdPublicationPath -SetId "secondary" -TerminalId "offterm"
            Write-DevWSCwdSessionRecord -Path $offSession -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "offterm"; windowId = "DevWS-secondary-offterm"; sessionId = "off-T1"
            })
            Write-DevWSCwdPublication -Path $offPublication -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "offterm"; windowId = "DevWS-secondary-offterm"; sessionId = "off-T1"
                cwd = $alphaCwd; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = $nowIso
            })

            # termbeta intentionally has no tracking state (pre-Phase-9 terminal).

            $stateBefore = @{}
            foreach ($file in @(Get-ChildItem -LiteralPath $stateRoot -Recurse -File)) {
                $stateBefore[$file.FullName] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            }

            $text = (& { Save-DevWSWorkspace -SetId "secondary" } *>&1 | Out-String)

            Assert-Contains $text "State saved for set 'secondary'." "real-resolver save succeeds"
            Assert-Contains $text "cwd updated: $alphaCwd" "available cwd consumed"
            Assert-Contains $text "cwd unavailable (expected-missing); path kept: $TestRoot" "pretracking terminal reported unavailable"
            Assert-Contains $text "cwd unavailable (session-mismatch); path kept: $TestRoot" "stale publication reported unavailable"

            $config = Read-DevWSConfigFile -Path $target
            $secondary = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]

            Assert-Equal $alphaCwd @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].path "available cwd persisted"
            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "termbeta" })[0].path "pretracking path unchanged"
            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "1" })[0].path "stale path unchanged"
            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "offterm" })[0].path "disabled path unchanged"
            Assert-Equal 0 @($secondary.windows | Where-Object { $_.id -eq "offterm" })[0].layout.x "disabled layout unchanged"
            Assert-Equal 1 $script:P9SaveConfigCalls "exactly one canonical save"

            $stateAfter = @{}
            foreach ($file in @(Get-ChildItem -LiteralPath $stateRoot -Recurse -File)) {
                $stateAfter[$file.FullName] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            }

            $sameCount = ($stateBefore.Count -eq $stateAfter.Count)
            $sameBytes = $true
            foreach ($path in $stateBefore.Keys) {
                if (-not $stateAfter.ContainsKey($path) -or $stateAfter[$path] -ne $stateBefore[$path]) { $sameBytes = $false }
            }
            Assert-True ($sameCount -and $sameBytes) "ws save leaves tracking state byte-identical"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "ws save scopes cwd lookup to the target set only" {
        $target = New-LifecycleConfigCopy "p9-save-scoping"
        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target

        $stateRoot = Join-Path $TestRoot "p9-save-scoping-state"
        $env:DEVWS_STATE_ROOT = $stateRoot

        $script:P9SaveCapture = [ordered]@{
            TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
                editor  = @{ x = 61; y = 62; w = 63; h = 64 }
            }
        }
        $script:P9SaveRectByHwnd = @{}

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
            $hwnd = [long](840000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{ Valid = $true; x = [int]$rect.x; y = [int]$rect.y; w = [int]$rect.w; h = [int]$rect.h }
            return $hwnd
        }

        function Get-DevWSWindowHwndRect {
            param([long]$Hwnd)
            return $script:P9SaveRectByHwnd[$Hwnd]
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        try {
            $mainCwd = Join-Path $TestRoot "p9-save-scoping-main"
            New-Item -ItemType Directory -Path $mainCwd -Force | Out-Null

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            $nowIso   = (Get-Date).ToUniversalTime().ToString("o")

            # Only main/termalpha has valid tracking state. secondary/termalpha
            # shares the terminal id but must never consume main's state.
            $mainSession = Get-DevWSCwdSessionPath -SetId "main" -TerminalId "termalpha"
            $mainPublication = Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "termalpha"
            Write-DevWSCwdSessionRecord -Path $mainSession -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "termalpha"; windowId = "DevWS-main-termalpha"; sessionId = "main-T1"
            })
            Write-DevWSCwdPublication -Path $mainPublication -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "termalpha"; windowId = "DevWS-main-termalpha"; sessionId = "main-T1"
                cwd = $mainCwd; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = $nowIso
            })

            $configBefore = Read-DevWSConfigFile -Path $target
            $mainBefore = ConvertTo-Json -InputObject @($configBefore.sets[0].windows) -Depth 20

            # Saving secondary must not see main's tracking state.
            $secondaryText = (& { Save-DevWSWorkspace -SetId "secondary" } *>&1 | Out-String)
            Assert-Contains $secondaryText "State saved for set 'secondary'." "secondary save succeeds"
            Assert-Contains $secondaryText "cwd unavailable (expected-missing); path kept: $TestRoot" "secondary/termalpha has no state of its own"

            $configAfterSecondary = Read-DevWSConfigFile -Path $target
            $mainAfterSecondary = ConvertTo-Json -InputObject @($configAfterSecondary.sets[0].windows) -Depth 20
            Assert-Equal $mainBefore $mainAfterSecondary "main set untouched by the secondary save"

            $secondaryAfter = ConvertTo-Json -InputObject @(@($configAfterSecondary.sets | Where-Object { $_.id -eq "secondary" })[0].windows) -Depth 20

            # Saving main consumes main's own state.
            $mainText = (& { Save-DevWSWorkspace -SetId "main" } *>&1 | Out-String)
            Assert-Contains $mainText "State saved for set 'main'." "main save (default target) succeeds"
            Assert-Contains $mainText "cwd updated: $mainCwd" "main's own tracked cwd consumed"

            $configAfterMain = Read-DevWSConfigFile -Path $target
            Assert-Equal "main" $configAfterMain.defaultSet "defaultSet unchanged"
            Assert-Equal $mainCwd @($configAfterMain.sets[0].windows | Where-Object { $_.id -eq "termalpha" })[0].path "main/termalpha path updated"
            Assert-Equal $secondaryAfter (ConvertTo-Json -InputObject @(@($configAfterMain.sets | Where-Object { $_.id -eq "secondary" })[0].windows) -Depth 20) "secondary set untouched by the main save"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

