    Test-Case "ws save revalidates the expected generation before committing cwd" {
        $target = New-LifecycleConfigCopy "p9-save-race"
        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target

        $stateRoot = Join-Path $TestRoot "p9-save-race-state"
        $env:DEVWS_STATE_ROOT = $stateRoot
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        $script:P9SaveCapture = [ordered]@{
            TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
            }
        }
        $script:P9SaveRectByHwnd = @{}
        $script:P9RaceConfigCalls = 0

        $p9OriginalSaveConfig = ${function:Save-DevWSConfig}

        function Save-DevWSConfig {
            param($Config, $Location)
            $script:P9RaceConfigCalls++
            & $p9OriginalSaveConfig -Config $Config -Location $Location
        }

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
            $hwnd = [long](870000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{ Valid = $true; x = [int]$rect.x; y = [int]$rect.y; w = [int]$rect.w; h = [int]$rect.h }
            return $hwnd
        }

        function Get-DevWSWindowHwndRect {
            param([long]$Hwnd)
            return $script:P9SaveRectByHwnd[$Hwnd]
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        try {
            $alphaCwd = Join-Path $TestRoot "p9-save-race-alpha"
            $betaCwd  = Join-Path $TestRoot "p9-save-race-beta"
            New-Item -ItemType Directory -Path $alphaCwd, $betaCwd -Force | Out-Null

            function Resolve-DevWSTrackedCwd {
                param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)

                # Deterministic race: for termalpha the controller advances the
                # expected generation to T2 immediately after this resolution
                # returns a T1 decision. termbeta stays on its resolved T1.
                if ($TerminalId -eq "termalpha") {
                    Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId $SetId -TerminalId $TerminalId -TabIndex $TabIndex) -Record ([ordered]@{
                        version = 1; setId = $SetId; terminalId = $TerminalId; windowId = "DevWS-secondary-termalpha"; sessionId = "T2"
                    })
                    return [pscustomobject]@{ Status = "available"; Reason = "ok"; Cwd = $alphaCwd; SessionId = "T1"; WindowId = "DevWS-secondary-termalpha" }
                }

                if ($TerminalId -eq "termbeta") {
                    Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId $SetId -TerminalId $TerminalId -TabIndex $TabIndex) -Record ([ordered]@{
                        version = 1; setId = $SetId; terminalId = $TerminalId; windowId = "DevWS-secondary-termbeta"; sessionId = "TB1"
                    })
                    return [pscustomobject]@{ Status = "available"; Reason = "ok"; Cwd = $betaCwd; SessionId = "TB1"; WindowId = "DevWS-secondary-termbeta" }
                }

                return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null; SessionId = $null; WindowId = $null }
            }

            $text = (& { Save-DevWSWorkspace -SetId "secondary" } *>&1 | Out-String)

            Assert-Contains $text "State saved for set 'secondary'." "racing save still succeeds"
            Assert-Contains $text "cwd unavailable (session-mismatch); path kept: $TestRoot" "advanced generation downgraded"
            Assert-Contains $text "cwd updated: $betaCwd" "unchanged generation still committed"

            $config = Read-DevWSConfigFile -Path $target
            $secondary = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]

            Assert-Equal $TestRoot @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].path "stale T1 cwd never persisted"
            Assert-Equal $betaCwd @($secondary.windows | Where-Object { $_.id -eq "termbeta" })[0].path "valid cwd committed"
            Assert-Equal 31 @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].layout.x "geometry still saved"
            Assert-Equal 1 $script:P9RaceConfigCalls "exactly one canonical save"

            # The transaction only reads the expected record; the simulated
            # reset's T2 state is untouched by save.
            $alphaExpected = Read-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId "secondary" -TerminalId "termalpha")
            Assert-Equal "T2" ([string]$alphaExpected.sessionId) "save never rewrites the expected generation"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "cwd save confirmation downgrades changed, missing, and malformed generations" {
        $stateRoot  = Join-Path $TestRoot "p9-save-confirm-state"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = $stateRoot

        function New-P9ConfirmDecision {
            param([string]$terminalId = "slot", [int]$tabIndex = 0, [string]$sessionId = "S1", [string]$windowId = "DevWS-slot")

            return [pscustomobject]@{
                terminalId      = $terminalId
                tabIndex        = $tabIndex
                hadOverride     = $false
                oldExplicitPath = $null
                oldEffective    = "C:\old"
                status          = "available"
                reason          = "ok"
                newCwd          = "C:\new"
                sessionId       = $sessionId
                windowId        = $windowId
            }
        }

        function Write-P9ConfirmExpected {
            param([string]$terminalId = "slot", [int]$tabIndex = 0, [string]$windowId = "DevWS-slot", [string]$sessionId = "S1")

            $record = [ordered]@{
                version = 1; setId = "main"; terminalId = $terminalId; windowId = $windowId; sessionId = $sessionId
            }

            if ($tabIndex -gt 0) {
                $record["tabIndex"] = $tabIndex
            }

            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId "main" -TerminalId $terminalId -TabIndex $tabIndex) -Record $record
        }

        try {
            $expectedPath = Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot"

            # Matching generation: decision stays available.
            Write-P9ConfirmExpected
            $decisions = [ordered]@{ slot = @((New-P9ConfirmDecision)) }
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions
            Assert-Equal "available" ([string]$decisions["slot"][0].status) "matching generation stays available"
            Assert-Equal "C:\new" ([string]$decisions["slot"][0].newCwd) "matching generation keeps the path"

            # Advanced generation (same window, new session): downgraded.
            Write-P9ConfirmExpected -sessionId "S2"
            $decisions = [ordered]@{ slot = @((New-P9ConfirmDecision -sessionId "S1")) }
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions
            Assert-Equal "unavailable" ([string]$decisions["slot"][0].status) "advanced generation downgraded"
            Assert-Equal "session-mismatch" ([string]$decisions["slot"][0].reason) "advanced generation reason"
            Assert-True ($null -eq $decisions["slot"][0].newCwd) "advanced generation drops the path"

            # Missing expected record: downgraded.
            Remove-Item -LiteralPath $expectedPath -Force
            $decisions = [ordered]@{ slot = @((New-P9ConfirmDecision -sessionId "S1")) }
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions
            Assert-Equal "unavailable" ([string]$decisions["slot"][0].status) "missing generation downgraded"
            Assert-Equal "expected-missing" ([string]$decisions["slot"][0].reason) "missing generation reason"

            # Malformed expected record: downgraded.
            New-Item -ItemType Directory -Path (Split-Path -Parent $expectedPath) -Force | Out-Null
            [System.IO.File]::WriteAllText($expectedPath, "{ not json", [System.Text.UTF8Encoding]::new($false))
            $decisions = [ordered]@{ slot = @((New-P9ConfirmDecision -sessionId "S1")) }
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions
            Assert-Equal "unavailable" ([string]$decisions["slot"][0].status) "malformed generation downgraded"
            Assert-Equal "expected-malformed" ([string]$decisions["slot"][0].reason) "malformed generation reason"

            # Per-tab independence: a missing indexed sibling never downgrades
            # or re-reads the valid tab 0 decision.
            Write-P9ConfirmExpected
            $decisions = [ordered]@{ slot = @(
                (New-P9ConfirmDecision),
                (New-P9ConfirmDecision -tabIndex 1 -sessionId "T1")
            ) }
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions
            Assert-Equal "available" ([string]$decisions["slot"][0].status) "valid sibling stays available"
            Assert-Equal "C:\new" ([string]$decisions["slot"][0].newCwd) "valid sibling keeps its path"
            Assert-Equal "unavailable" ([string]$decisions["slot"][1].status) "missing indexed generation downgraded"
            Assert-Equal "expected-missing" ([string]$decisions["slot"][1].reason) "missing indexed generation reason"

            # Confirmation is read-only: no publication was created.
            Assert-True (-not (Test-Path -LiteralPath (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot"))) "confirmation never publishes"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "ws save never persists a wrong generation while publications flap" {
        $target = New-LifecycleConfigCopy "p9-save-flap"
        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target

        $stateRoot = Join-Path $TestRoot "p9-save-flap-state"
        $env:DEVWS_STATE_ROOT = $stateRoot

        $script:P9SaveCapture = [ordered]@{
            TerminalLines = @("termalpha|31|32|33|34", "termbeta|41|42|43|44", "1|51|52|53|54")
            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
            }
        }
        $script:P9SaveRectByHwnd = @{}

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
            $hwnd = [long](880000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{ Valid = $true; x = [int]$rect.x; y = [int]$rect.y; w = [int]$rect.w; h = [int]$rect.h }
            return $hwnd
        }

        function Get-DevWSWindowHwndRect {
            param([long]$Hwnd)
            return $script:P9SaveRectByHwnd[$Hwnd]
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        try {
            $alphaDir = Join-Path $TestRoot "p9-save-flap-alpha"
            $t2Dir    = Join-Path $TestRoot "p9-save-flap-t2"
            New-Item -ItemType Directory -Path $alphaDir, $t2Dir -Force | Out-Null

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            $expectedPath = Get-DevWSCwdSessionPath -SetId "secondary" -TerminalId "termalpha"
            $publicationPath = Get-DevWSCwdPublicationPath -SetId "secondary" -TerminalId "termalpha"

            # Expected generation is T2 (a reset already advanced it).
            Write-DevWSCwdSessionRecord -Path $expectedPath -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "termalpha"; windowId = "DevWS-secondary-termalpha"; sessionId = "T2"
            })

            # Publications flap between the stale T1 and the current T2.
            $observed = @()
            for ($i = 0; $i -lt 6; $i++) {
                $session = $(if ($i % 2 -eq 0) { "T1" } else { "T2" })
                $cwd     = $(if ($session -eq "T1") { $alphaDir } else { $t2Dir })

                Write-DevWSCwdPublication -Path $publicationPath -Record ([ordered]@{
                    version = 1; setId = "secondary"; terminalId = "termalpha"; windowId = "DevWS-secondary-termalpha"; sessionId = $session
                    cwd = $cwd; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
                })

                $resolution = Resolve-DevWSTrackedCwd -SetId "secondary" -TerminalId "termalpha"
                $observed += [pscustomobject]@{ Session = $session; Status = [string]$resolution.Status; Reason = [string]$resolution.Reason }

                if ($session -eq "T1") {
                    Assert-Equal "unavailable" ([string]$resolution.Status) "stale T1 publication rejected"
                    Assert-Equal "session-mismatch" ([string]$resolution.Reason) "stale T1 reason"
                }
                else {
                    Assert-Equal "available" ([string]$resolution.Status) "T2 publication accepted"
                    Assert-Equal $t2Dir ([string]$resolution.cwd) "T2 cwd"
                }
            }

            # Final T2 publication: full save consumes the current generation.
            Write-DevWSCwdPublication -Path $publicationPath -Record ([ordered]@{
                version = 1; setId = "secondary"; terminalId = "termalpha"; windowId = "DevWS-secondary-termalpha"; sessionId = "T2"
                cwd = $t2Dir; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            $stateBefore = @{}
            foreach ($file in @(Get-ChildItem -LiteralPath $stateRoot -Recurse -File)) {
                $stateBefore[$file.FullName] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            }

            $text = (& { Save-DevWSWorkspace -SetId "secondary" } *>&1 | Out-String)
            Assert-Contains $text "cwd updated: $t2Dir" "final T2 generation saved"

            $config = Read-DevWSConfigFile -Path $target
            $secondary = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]
            Assert-Equal $t2Dir @($secondary.windows | Where-Object { $_.id -eq "termalpha" })[0].path "T2 cwd persisted"

            $stateAfter = @{}
            foreach ($file in @(Get-ChildItem -LiteralPath $stateRoot -Recurse -File)) {
                $stateAfter[$file.FullName] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            }
            $same = ($stateBefore.Count -eq $stateAfter.Count)
            foreach ($path in $stateBefore.Keys) {
                if (-not $stateAfter.ContainsKey($path) -or $stateAfter[$path] -ne $stateBefore[$path]) { $same = $false }
            }
            Assert-True $same "flapping-save leaves tracking state byte-identical"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "publisher exit after resolution keeps decision-time semantics and mutates nothing" {
        $stateRoot  = Join-Path $TestRoot "p9-save-publisher-exit"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = $stateRoot

        $publisher = $null

        try {
            $cwdDir = Join-Path $TestRoot "p9-save-publisher-exit-cwd"
            New-Item -ItemType Directory -Path $cwdDir -Force | Out-Null

            # Disposable short-lived publisher process.
            $publisher = Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList @("-NoLogo", "-NoProfile", "-Command", "Start-Sleep -Seconds 30") -PassThru -WindowStyle Hidden
            Start-Sleep -Milliseconds 300

            $startIso = (Get-Process -Id $publisher.Id).StartTime.ToUniversalTime().ToString("o")

            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot") -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "P1"
            })
            Write-DevWSCwdPublication -Path (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot") -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "P1"
                cwd = $cwdDir; shellPid = $publisher.Id; shellStartTimeUtc = $startIso; updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            $decisions = Get-DevWSTerminalSaveDecisions -SetId "main" -Terminals @([pscustomobject]@{
                id       = "slot"
                windowId = "DevWS-slot"
                path     = "C:\old"
                tabs     = @([pscustomobject]@{ command = "pwsh"; args = @() })
            })
            Assert-Equal "available" ([string]$decisions["slot"][0].status) "live publisher resolves available"
            Assert-Equal "P1" ([string]$decisions["slot"][0].sessionId) "accepted generation carried"

            # The publisher exits after resolution. The locked design proves
            # liveness at decision time; the generation revalidation stays the
            # commit-time authority. Confirm must not touch any state.
            Stop-Process -Id $publisher.Id -Force
            $publisher = $null

            $stateBefore = @{}
            foreach ($file in @(Get-ChildItem -LiteralPath $stateRoot -Recurse -File)) {
                $stateBefore[$file.FullName] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            }

            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions
            Assert-Equal "available" ([string]$decisions["slot"][0].status) "decision-time liveness is accepted (generation unchanged)"

            $stateAfter = @{}
            foreach ($file in @(Get-ChildItem -LiteralPath $stateRoot -Recurse -File)) {
                $stateAfter[$file.FullName] = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            }
            $same = ($stateBefore.Count -eq $stateAfter.Count)
            foreach ($path in $stateBefore.Keys) {
                if (-not $stateAfter.ContainsKey($path) -or $stateAfter[$path] -ne $stateBefore[$path]) { $same = $false }
            }
            Assert-True $same "confirmation leaves tracking state byte-identical"
        }
        finally {
            if ($null -ne $publisher -and -not $publisher.HasExited) { Stop-Process -Id $publisher.Id -Force -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

