            AppRects      = @{
                browser = @{ x = 11; y = 12; w = 13; h = 14 }
                notes   = @{ x = 21; y = 22; w = 23; h = 24 }
            }
        }
        $script:P9SaveRectByHwnd = @{}

        function Resolve-DevWSAppLifecycleWindow {
            param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
            $hwnd = [long](890000 + $script:P9SaveRectByHwnd.Count + 1)
            $rect = $script:P9SaveCapture.AppRects[[string]$App.id]
            $script:P9SaveRectByHwnd[$hwnd] = [pscustomobject]@{ Valid = $true; x = [int]$rect.x; y = [int]$rect.y; w = [int]$rect.w; h = [int]$rect.h }
