            return (New-DevWSTestWorkerCaptureResult -Lines @($script:P9SaveCapture.TerminalLines))
        }

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)

            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId $SetId -TerminalId $TerminalId -TabIndex $TabIndex) -Record ([ordered]@{
                version = 1; setId = $SetId; terminalId = $TerminalId; windowId = "DevWS-secondary-$TerminalId"; sessionId = "W1"
            })
