            param($Config, $Location)
            throw "simulated canonical write failure"
        }

        try {
            $before = Get-FileBase64 -Path $target

            Assert-Throws { Save-DevWSWorkspace -SetId "secondary" } "simulated canonical write failure"
            Assert-Equal $before (Get-FileBase64 -Path $target) "failed canonical write leaves bytes intact"
        }
        finally {
