        }
    }

    Test-Case "install staging preserves tracked cwd state byte-for-byte" {
        $fixture = New-InstallFixture "p9-install-preserve"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $cwdSession = Join-Path $fixture.State "cwd-sessions\main\slot.json"
        $cwdPublication = Join-Path $fixture.State "cwd\main\slot.json"
        $sentinel = Join-Path $fixture.State "disposable\sentinel.txt"
        New-Item -ItemType Directory -Path (Split-Path -Parent $cwdSession), (Split-Path -Parent $cwdPublication), (Split-Path -Parent $sentinel) -Force | Out-Null
        Set-Content -LiteralPath $cwdSession -Value '{"sentinel":"session"}' -NoNewline
        Set-Content -LiteralPath $cwdPublication -Value '{"sentinel":"publication"}' -NoNewline
        Set-Content -LiteralPath $sentinel -Value "keep me" -NoNewline

        $before = [ordered]@{
            session     = Get-FileBase64 -Path $cwdSession
            publication = Get-FileBase64 -Path $cwdPublication
            sentinel    = Get-FileBase64 -Path $sentinel
        }

        # Reinstall twice: runtime binaries update, disposable cwd state stays.
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        Assert-Equal $before.session (Get-FileBase64 -Path $cwdSession) "tracked session state preserved across reinstall"
        Assert-Equal $before.publication (Get-FileBase64 -Path $cwdPublication) "tracked publication preserved across reinstall"
        Assert-Equal $before.sentinel (Get-FileBase64 -Path $sentinel) "unrelated disposable state preserved across reinstall"

        $stateFiles = @(Get-ChildItem -LiteralPath $fixture.State -Recurse -File)
        Assert-Equal 3 $stateFiles.Count "staging creates no additional state files"

        # Fresh staging creates no cwd state at all.
        $fresh = New-InstallFixture "p9-install-no-cwd"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fresh.Root

        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fresh.State "cwd"))) "staging creates no publication directory"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fresh.State "cwd-sessions"))) "staging creates no session directory"
    }

    Test-Case "uninstall preserves cwd state by default and purge removes it" {
        function New-P9UninstallFixture {
            param([string]$Name)

            $fixture = New-InstallFixture $Name
            $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

            New-Item -ItemType Directory -Path (Split-Path -Parent $fixture.Canonical) -Force | Out-Null
            Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $fixture.Canonical -Force

            $cwdSession = Join-Path $fixture.State "cwd-sessions\main\slot.json"
            $cwdPublication = Join-Path $fixture.State "cwd\main\slot.json"
            New-Item -ItemType Directory -Path (Split-Path -Parent $cwdSession), (Split-Path -Parent $cwdPublication) -Force | Out-Null
            Set-Content -LiteralPath $cwdSession -Value '{"sentinel":"session"}' -NoNewline
            Set-Content -LiteralPath $cwdPublication -Value '{"sentinel":"publication"}' -NoNewline

            $metadata = [pscustomobject]@{
                legacyShim = [pscustomobject]@{ replaced = $false; backup = "" }
                hotkey     = [pscustomobject]@{ managed = $false; backup = "" }
                path       = [pscustomobject]@{ entry = (Join-Path $fixture.Root "bin") }
            }

            return [pscustomobject]@{
                Fixture        = $fixture
                Canonical      = $fixture.Canonical
                CwdSession     = $cwdSession
                CwdPublication = $cwdPublication
                Metadata       = $metadata
            }
        }

        # Default uninstall: runtime files removed, state (including cwd) kept.
        $defaultFixture = New-P9UninstallFixture "p9-uninstall-default"
        $defaultPlan = Get-DevWSUninstallPlan `
            -InstallRoot $defaultFixture.Fixture.Root `
            -CanonicalPath $defaultFixture.Canonical `
            -LegacyShimPath (Join-Path $defaultFixture.Fixture.Root "local-bin\ws.cmd") `
            -HotkeyPath (Join-Path $defaultFixture.Fixture.Root "Startup\TerminalShortcut.ahk") `
            -Metadata $defaultFixture.Metadata

        $null = Invoke-DevWSUninstall -Plan $defaultPlan -SkipTasks

        Assert-True (-not (Test-Path -LiteralPath $defaultFixture.Fixture.App)) "default uninstall removes app files"
        Assert-True (Test-Path -LiteralPath $defaultFixture.CwdSession -PathType Leaf) "default uninstall preserves cwd session state"
        Assert-True (Test-Path -LiteralPath $defaultFixture.CwdPublication -PathType Leaf) "default uninstall preserves cwd publication state"
        Assert-True (Test-Path -LiteralPath $defaultFixture.Canonical -PathType Leaf) "default uninstall preserves canonical config"

        # Purge: disposable state (including cwd) and canonical are removed.
        $purgeFixture = New-P9UninstallFixture "p9-uninstall-purge"
        $purgePlan = Get-DevWSUninstallPlan `
            -InstallRoot $purgeFixture.Fixture.Root `
            -CanonicalPath $purgeFixture.Canonical `
            -LegacyShimPath (Join-Path $purgeFixture.Fixture.Root "local-bin\ws.cmd") `
            -HotkeyPath (Join-Path $purgeFixture.Fixture.Root "Startup\TerminalShortcut.ahk") `
            -Metadata $purgeFixture.Metadata `
            -Purge

        $null = Invoke-DevWSUninstall -Plan $purgePlan -SkipTasks

        Assert-True (-not (Test-Path -LiteralPath $purgeFixture.CwdSession)) "purge removes cwd session state"
        Assert-True (-not (Test-Path -LiteralPath $purgeFixture.CwdPublication)) "purge removes cwd publication state"
        Assert-True (-not (Test-Path -LiteralPath $purgeFixture.Canonical)) "purge removes canonical config"

        # Source audit: purge is the only path that removes state; default
        # uninstall keeps the generic disposable state root (no cwd-specific
        # branches anywhere).
        $uninstallSource = Get-SourceOf "uninstall.ps1"
        Assert-Contains $uninstallSource "-Purge" "uninstall exposes purge"
        Assert-NotContains $uninstallSource "cwd-sessions" "uninstall has no cwd-specific branches"
        Assert-NotContains $uninstallSource "cwd\" "uninstall has no cwd-specific branches"
    }

    Test-Case "health passes with Phase 9 libs and helpers, fails when they are missing, and stays read-only" {
        $fixture = New-InstallFixture "p9-health-phase9"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture -SkipNative

        New-Item -ItemType Directory -Path (Split-Path -Parent $fixture.Canonical) -Force | Out-Null
        Copy-Item -LiteralPath $WorkspaceFixturePath -Destination $fixture.Canonical -Force

        $stubs = Join-Path $fixture.Root "stubs"
        New-Item -ItemType Directory -Path $stubs -Force | Out-Null
        $wtStub  = Join-Path $stubs "wt.exe"
        $ahkStub = Join-Path $stubs "AutoHotkey64.exe"
        Set-Content -LiteralPath $wtStub -Value "" -NoNewline
        Set-Content -LiteralPath $ahkStub -Value "" -NoNewline

        $context = [pscustomobject]@{
            InstallRoot         = $fixture.Root
            StateRoot           = $fixture.State
            CanonicalPath       = $fixture.Canonical
            StartupPath         = (Join-Path $fixture.Root "Startup")
            LegacyShimPath      = (Join-Path $fixture.Root "local-bin\ws.cmd")
            WindowsTerminalPath = $wtStub
            AutoHotkeyPath      = $ahkStub
            MetadataPath        = (Join-Path $fixture.State "install-metadata.json")
            PrivilegedRoot      = $fixture.Privileged
        }

        function Get-P9HealthById($summary) {
            $byId = @{}
            foreach ($result in @($summary.Results)) { $byId[$result.Id] = $result }
            return $byId
        }

        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-P9HealthById $summary

        Assert-Equal $true $byId["app-libs"].Ok "25 installed libs pass app-libs"
        Assert-Equal $true $byId["helpers"].Ok "installed helpers pass helpers"

        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fixture.State "cwd"))) "health creates no publication state"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fixture.State "cwd-sessions"))) "health creates no session state"

        # Missing Phase 9 library fails app-libs only.
        $cwdLib = Join-Path $fixture.Root "app\lib\devws-cwd.ps1"
        Move-Item -LiteralPath $cwdLib -Destination "$cwdLib.off"
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-P9HealthById $summary
        Assert-Equal $false $byId["app-libs"].Ok "missing devws-cwd.ps1 fails app-libs"
        Assert-Equal $true $byId["helpers"].Ok "helpers still pass"
        Move-Item -LiteralPath "$cwdLib.off" -Destination $cwdLib

        # Missing privileged bootstrap fails helpers only.
        $bootstrap = Join-Path $fixture.Privileged "helpers\cwd-shell-bootstrap.ps1"
        Move-Item -LiteralPath $bootstrap -Destination "$bootstrap.off"
        $summary = Invoke-DevWSHealthCheck -Context $context
        $byId = Get-P9HealthById $summary
        Assert-Equal $false $byId["helpers"].Ok "missing cwd-shell-bootstrap.ps1 fails helpers"
        Assert-Equal $true $byId["app-libs"].Ok "app-libs still pass"
        Move-Item -LiteralPath "$bootstrap.off" -Destination $bootstrap

        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fixture.State "cwd"))) "health never creates publication state"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fixture.State "cwd-sessions"))) "health never creates session state"
    }

    Write-Host ""
    Start-TestGroup -Name 'per-tab-cwd' -Title 'Per-tab terminal tracking (Pass 6B)'

    Test-Case "per-tab state paths keep tab 0 legacy and index tabs 1+" {
        $stateRoot  = Join-Path $TestRoot "p6b-paths-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\studio.json") (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "studio") "tab 0 default session path is the legacy file"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\studio.json") (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "studio" -TabIndex 0) "explicit tab 0 keeps the legacy file"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\studio\1.json") (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "studio" -TabIndex 1) "tab 1 indexed session file"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\studio\2.json") (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "studio" -TabIndex 2) "tab 2 indexed session file"
            Assert-Equal (Join-Path $stateRoot "cwd\main\studio.json") (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "studio") "tab 0 default publication path is the legacy file"
            Assert-Equal (Join-Path $stateRoot "cwd\main\studio\1.json") (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "studio" -TabIndex 1) "tab 1 indexed publication file"

            Assert-Throws { Get-DevWSCwdSessionPath -SetId "main" -TerminalId "studio" -TabIndex -1 } "cannot be negative"
            Assert-Throws { Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "studio" -TabIndex -1 } "cannot be negative"

            $t0 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "studio" -WindowId "DevWS-studio" -StartupSpecSha256 "S0"
            $t1 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "studio" -WindowId "DevWS-studio" -TabIndex 1 -StartupSpecSha256 "S1"
            $t2 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "studio" -WindowId "DevWS-studio" -TabIndex 2 -StartupSpecSha256 "S2"

            Assert-True (Test-Path -LiteralPath $t0.SessionPath -PathType Leaf) "legacy session file exists"
            Assert-True (Test-Path -LiteralPath $t1.SessionPath -PathType Leaf) "indexed session file exists"
            Assert-True (Test-Path -LiteralPath (Split-Path -Parent $t1.SessionPath) -PathType Container) "indexed session directory exists"
            Assert-True ((Split-Path -Parent $t1.SessionPath) -ne (Split-Path -Parent $t0.SessionPath)) "legacy file and indexed directory coexist"

            $e0 = Get-Content -LiteralPath $t0.SessionPath -Raw | ConvertFrom-Json
            $e1 = Get-Content -LiteralPath $t1.SessionPath -Raw | ConvertFrom-Json
            Assert-True ($null -eq $e0.PSObject.Properties["tabIndex"]) "tab 0 expected record omits tabIndex"
            Assert-Equal 1 ([int]$e1.tabIndex) "tab 1 expected record carries tabIndex"
            Assert-Equal "S0" ([string]$e0.startupSpecSha256) "tab 0 spec hash recorded"
            Assert-Equal "S1" ([string]$e1.startupSpecSha256) "tab 1 spec hash recorded"

            1..3 | ForEach-Object { Write-DevWSCwdPublication -Path $t1.PublicationPath -Record ([ordered]@{ version = 1; marker = "x$_" }) }
            $pub1 = Get-Content -LiteralPath $t1.PublicationPath -Raw | ConvertFrom-Json
            Assert-Equal "x3" ([string]$pub1.marker) "indexed publication is atomically replaceable"
            $tempFiles = @(Get-ChildItem -Path (Split-Path -Parent $t1.PublicationPath) -File | Where-Object { $_.Name -like "*.tmp" })
            Assert-Equal 0 $tempFiles.Count "no temp debris in the indexed directory"

            Remove-Item -LiteralPath (Split-Path -Parent $t1.SessionPath) -Recurse -Force
            Assert-True (Test-Path -LiteralPath $t0.SessionPath -PathType Leaf) "legacy file survives indexed cleanup"
            Assert-True (-not (Test-Path -LiteralPath $t1.SessionPath)) "indexed session file removed"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "per-tab resolver proves independent generations and deterministic rejection" {
        $stateRoot  = Join-Path $TestRoot "p6b-resolver-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $dirA  = Join-Path $TestRoot "p6b-resolver-a"
            $dirB  = Join-Path $TestRoot "p6b-resolver-b"
            $dirC  = Join-Path $TestRoot "p6b-resolver-c"
            New-Item -ItemType Directory -Path $dirA, $dirB, $dirC -Force | Out-Null

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            function New-P6BResolverPublication {
                param(
                    [string]$TerminalId,
                    [string]$WindowId,
                    [string]$SessionId,
                    [string]$Cwd,
                    [int]$ProcessId,
                    [string]$StartTime,
                    [int]$TabIndex = -1,
                    [string]$StartupState = ""
                )

                $record = [ordered]@{
                    version           = 1
                    setId             = "main"
                    terminalId        = $TerminalId
                    windowId          = $WindowId
                    sessionId         = $SessionId
                    cwd               = $Cwd
                    shellPid          = $ProcessId
                    shellStartTimeUtc = $StartTime
                    updatedAtUtc      = (Get-Date).ToUniversalTime().ToString("o")
                }

                if ($TabIndex -ge 0) { $record.tabIndex = $TabIndex }
                if (-not [string]::IsNullOrWhiteSpace($StartupState)) { $record.startupState = $StartupState }

                return $record
            }

            $t0 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "multi" -WindowId "DevWS-multi" -StartupSpecSha256 "SPEC0"
            $t1 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "multi" -WindowId "DevWS-multi" -TabIndex 1 -StartupSpecSha256 "SPEC1"
            $t2 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "multi" -WindowId "DevWS-multi" -TabIndex 2 -StartupSpecSha256 "SPEC2"

            Write-DevWSCwdPublication -Path $t0.PublicationPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t0.SessionId -Cwd $dirA -ProcessId $PID -StartTime $startIso -StartupState "idle")
            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1.SessionId -Cwd $dirB -ProcessId $PID -StartTime $startIso -TabIndex 1 -StartupState "startup-child-returned")
            Write-DevWSCwdPublication -Path $t2.PublicationPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t2.SessionId -Cwd $dirC -ProcessId $PID -StartTime $startIso -TabIndex 2)

            $r0 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 0
            $r1 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1
            $r2 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 2

            Assert-Equal "available" ([string]$r0.Status) "tab 0 historical pair available"
            Assert-Equal $dirA ([string]$r0.Cwd) "tab 0 cwd"
            Assert-Equal 0 ([int]$r0.TabIndex) "tab 0 index reported"
            Assert-Equal "idle" ([string]$r0.StartupState) "tab 0 startup state"
            Assert-Equal "SPEC0" ([string]$r0.StartupSpecSha256) "tab 0 spec hash"
            Assert-Equal "available" ([string]$r1.Status) "tab 1 available"
            Assert-Equal $dirB ([string]$r1.Cwd) "tab 1 cwd"
            Assert-Equal "startup-child-returned" ([string]$r1.StartupState) "tab 1 startup state"
            Assert-Equal "SPEC1" ([string]$r1.StartupSpecSha256) "tab 1 spec hash"
            Assert-Equal "available" ([string]$r2.Status) "tab 2 available"
            Assert-Equal $dirC ([string]$r2.Cwd) "tab 2 cwd"
            Assert-Equal 3 (@($r0.SessionId, $r1.SessionId, $r2.SessionId) | Sort-Object -Unique).Count "three distinct session ids"

            # Cross-tab acceptance is impossible in either direction.
            $cross1 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $t0.PublicationPath
            Assert-Equal "tab-mismatch" ([string]$cross1.Reason) "tab 0 publication is never accepted as tab 1"
            $cross2 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 0 -PublicationPath $t1.PublicationPath
            Assert-Equal "tab-mismatch" ([string]$cross2.Reason) "tab 1 publication is never accepted as tab 0"
            $cross3 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -SessionPath $t0.SessionPath -PublicationPath $t1.PublicationPath
            Assert-Equal "tab-mismatch" ([string]$cross3.Reason) "tab 0 expected record is never accepted as tab 1"

            # Wrong tabIndex inside an otherwise valid pair.
            $wrongTabPath = Join-Path $TestRoot "p6b-wrongtab.json"
            Write-DevWSCwdPublication -Path $wrongTabPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t2.SessionId -Cwd $dirC -ProcessId $PID -StartTime $startIso -TabIndex 3)
            $wrongTab = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 2 -PublicationPath $wrongTabPath
            Assert-Equal "tab-mismatch" ([string]$wrongTab.Reason) "wrong tabIndex value is rejected"

            # Stale generation for tab 1 alone must not invalidate the others.
            # The rotation removes the old publication best-effort; an old shell
            # still running may republish its stale token afterwards.
            $t1new = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "multi" -WindowId "DevWS-multi" -TabIndex 1 -StartupSpecSha256 "SPEC1"
            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1.SessionId -Cwd $dirB -ProcessId $PID -StartTime $startIso -TabIndex 1)
            $stale1 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1
            Assert-Equal "session-mismatch" ([string]$stale1.Reason) "stale tab 1 publication rejected"
            Assert-Equal "available" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 0).Status) "tab 0 unaffected by stale tab 1"
            Assert-Equal "available" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 2).Status) "tab 2 unaffected by stale tab 1"

            # Malformed / missing state families.
            $badPubPath = Join-Path $TestRoot "p6b-badt1.json"
            Set-Content -LiteralPath $badPubPath -Value "{ not json" -NoNewline
            $malformed = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $badPubPath
            Assert-Equal "publication-malformed" ([string]$malformed.Reason) "malformed tab 1 publication"
            $missingExpected = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -SessionPath (Join-Path $TestRoot "p6b-no-such-session.json")
            Assert-Equal "expected-missing" ([string]$missingExpected.Reason) "missing tab 1 expected"
            $missingPub = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 2 -PublicationPath (Join-Path $TestRoot "p6b-no-such-pub.json")
            Assert-Equal "publication-missing" ([string]$missingPub.Reason) "missing tab 2 publication"

            # Dead publisher, malformed publisher identity, start-time mismatch.
            $deadProc = Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList "-NoLogo", "-NoProfile", "-Command", "exit" -PassThru
            $deadProc.WaitForExit()

            $deadPath = Join-Path $TestRoot "p6b-deadt1.json"
            Write-DevWSCwdPublication -Path $deadPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd $dirB -ProcessId $deadProc.Id -StartTime $startIso -TabIndex 1)
            $deadResolve = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $deadPath
            Assert-Equal "shell-dead" ([string]$deadResolve.Reason) "dead tab 1 publisher rejected"

            $badPidPath = Join-Path $TestRoot "p6b-badpidt1.json"
            Write-DevWSCwdPublication -Path $badPidPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd $dirB -ProcessId 0 -StartTime $startIso -TabIndex 1)
            $badPid = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $badPidPath
            Assert-Equal "publication-schema" ([string]$badPid.Reason) "malformed publisher pid"

            $wrongStartPath = Join-Path $TestRoot "p6b-wrongstartt1.json"
            $shiftedStart = (Get-Process -Id $PID).StartTime.ToUniversalTime().AddSeconds(-60).ToString("o")
            Write-DevWSCwdPublication -Path $wrongStartPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd $dirB -ProcessId $PID -StartTime $shiftedStart -TabIndex 1)
            $wrongStart = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $wrongStartPath
            Assert-Equal "shell-identity-mismatch" ([string]$wrongStart.Reason) "publisher start time mismatch"

            # cwd validity rules stay per-tab.
            $fileAsCwd = Join-Path $TestRoot "p6b-not-a-dir.txt"
            Set-Content -LiteralPath $fileAsCwd -Value "x" -NoNewline
            $relativePath = Join-Path $TestRoot "p6b-relt1.json"
            Write-DevWSCwdPublication -Path $relativePath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd "relative\dir" -ProcessId $PID -StartTime $startIso -TabIndex 1)
            $relative = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $relativePath
            Assert-Equal "cwd-relative" ([string]$relative.Reason) "relative cwd rejected"

            $missingDirPath = Join-Path $TestRoot "p6b-missingdir-t1.json"
            Write-DevWSCwdPublication -Path $missingDirPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd (Join-Path $TestRoot "p6b-does-not-exist") -ProcessId $PID -StartTime $startIso -TabIndex 1)
            $missingDir = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $missingDirPath
            Assert-Equal "cwd-missing" ([string]$missingDir.Reason) "missing cwd directory rejected"

            $fileCwdPath = Join-Path $TestRoot "p6b-filecwd-t1.json"
            Write-DevWSCwdPublication -Path $fileCwdPath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd $fileAsCwd -ProcessId $PID -StartTime $startIso -TabIndex 1)
            $fileCwd = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $fileCwdPath
            Assert-Equal "cwd-not-directory" ([string]$fileCwd.Reason) "file as cwd rejected"

            # Malformed startup metadata never erases an otherwise-valid cwd.
            $bogusStatePath = Join-Path $TestRoot "p6b-bogusstate-t1.json"
            Write-DevWSCwdPublication -Path $bogusStatePath -Record (New-P6BResolverPublication -TerminalId "multi" -WindowId "DevWS-multi" -SessionId $t1new.SessionId -Cwd $dirB -ProcessId $PID -StartTime $startIso -TabIndex 1 -StartupState "bogus-state")
            $bogusState = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1 -PublicationPath $bogusStatePath
            Assert-Equal "available" ([string]$bogusState.Status) "bogus startup state keeps cwd available"
            Assert-True ($null -eq $bogusState.StartupState) "bogus startup state reported unavailable"
            Assert-Equal "SPEC1" ([string]$bogusState.StartupSpecSha256) "expected spec hash survives malformed live metadata"

            # Historical tab 0 (no spec hash, no lifecycle) stays fully valid.
            $legacy = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "legacy" -WindowId "DevWS-legacy"
            Write-DevWSCwdPublication -Path $legacy.PublicationPath -Record (New-P6BResolverPublication -TerminalId "legacy" -WindowId "DevWS-legacy" -SessionId $legacy.SessionId -Cwd $dirA -ProcessId $PID -StartTime $startIso)
            $legacyResolve = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "legacy"
            Assert-Equal "available" ([string]$legacyResolve.Status) "historical tab 0 cwd available"
            Assert-True ($null -eq $legacyResolve.StartupState) "historical startup state unavailable"
            Assert-True ($null -eq $legacyResolve.StartupSpecSha256) "historical startup spec unavailable"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "startup-spec fingerprint identifies the exact intended child" {
        $same1 = Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("-w", "5")
        $same2 = Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("-w", "5")
        Assert-Equal $same1 $same2 "identical specs hash identically"
        Assert-Equal 64 $same1.Length "sha256 hex length"
        Assert-True ($same1 -match '^[0-9A-F]{64}$') "sha256 hex shape"

        Assert-True ($same1 -ne (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("-w", "6"))) "argument values matter"
        Assert-True ((Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @()) -ne (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @(""))) "zero args differ from one empty-string arg"
        Assert-True ((Get-DevWSCwdChildSpecFingerprint -Command $null -Arguments @()) -ne (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @())) "null command differs from a string command"
        Assert-Equal (Get-DevWSCwdChildSpecFingerprint -Command "" -Arguments @()) (Get-DevWSCwdChildSpecFingerprint -Command $null -Arguments @()) "empty command normalizes to null"
        Assert-True ((Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("a", "b")) -ne (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("b", "a"))) "argument order matters"
        Assert-True ((Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @('say "hi"')) -ne (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("say hi"))) "quote differences matter"
        Assert-Equal (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("café-ü漢字")) (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("café-ü漢字")) "Unicode hashing is stable"
        Assert-Equal (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("7")) (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @([int]7)) "numeric args hash as their canonical string form"

        # The fingerprint is SHA-256 over the exact base64-decoded child-spec
        # JSON bytes (the source of truth the bootstrap actually decodes).
        $base64 = ConvertTo-DevWSCwdChildSpecBase64 -Command "tool" -Arguments @("a b")
        $json   = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($base64))
        $sha    = [System.Security.Cryptography.SHA256]::Create()

        try {
            $expected = ([System.BitConverter]::ToString($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($json)))).Replace('-', '')
        }
        finally {
            $sha.Dispose()
        }

        Assert-Equal $expected (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("a b")) "fingerprint equals SHA-256 of the exact child-spec bytes"

        # Config-mutation race foundation (Pass 6E precondition): the expected
        # record identifies the LAUNCH-TIME spec even after a config-only
        # mutation to a different spec, because it is not derived from the live
        # session generation.
        $stateRoot  = Join-Path $TestRoot "p6b-race-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $terminal = New-TerminalDefinition -Id "racer" -Path $TestRoot
            $terminal.tabs = @(
                [ordered]@{ command = "commandA"; args = @("--a") },
                [ordered]@{ command = $null; args = @() }
            )
            $terminal.activeTab = 0
            $racerItem = (ConvertTo-TestConfig -Windows @($terminal)).sets[0].windows[0]

            $context = New-DevWSCwdTrackingContext -SetId "main" -TerminalId "racer" -WindowId "DevWS-racer" -Terminal $racerItem -TabIndex 0
            $expectedRecord = Get-Content -LiteralPath $context.SessionPath -Raw | ConvertFrom-Json

            $hashA = Get-DevWSCwdChildSpecFingerprint -Command "commandA" -Arguments @("--a")
            $hashB = Get-DevWSCwdChildSpecFingerprint -Command "commandB" -Arguments @()
            Assert-Equal $hashA ([string]$expectedRecord.startupSpecSha256) "expected record carries the launch-time spec hash"
            Assert-True ($hashB -ne $expectedRecord.startupSpecSha256) "a later config mutation hashes differently"

            # A live publication with the same session still surfaces the
            # launch-time hash through the resolver: a future gate can compare
            # hash(current config) against it even though the session id alone
            # would not detect the config-only mutation.
            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            Write-DevWSCwdPublication -Path $context.PublicationPath -Record ([ordered]@{
                version           = 1
                setId             = "main"
                terminalId        = "racer"
                windowId          = "DevWS-racer"
                sessionId         = $context.SessionId
                cwd               = $TestRoot
                shellPid          = $PID
                shellStartTimeUtc = $startIso
                updatedAtUtc      = (Get-Date).ToUniversalTime().ToString("o")
            })

            $resolved = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "racer" -TabIndex 0
            Assert-Equal "available" ([string]$resolved.Status) "live race pair resolves"
            Assert-Equal $hashA ([string]$resolved.StartupSpecSha256) "resolver surfaces the launch-time spec hash"
            Assert-True ($hashA -ne $hashB) "launch-time spec hash proves a config-only mismatch"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "bootstrap publishes startup lifecycle for an indexed tab" {
        $root       = Join-Path $TestRoot "p6b-lifecycle"
        $work       = Join-Path $root "work"
        $state      = Join-Path $root "state"
        New-Item -ItemType Directory -Path $work, $state -Force | Out-Null
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $state

            $marker      = Join-Path $root "child-started.txt"
            $childScript = Join-Path $root "p6b-sleep-child.ps1"
            $childBody   = @'
Set-Content -LiteralPath '__MARKER__' -Value running
Start-Sleep -Seconds 6
'@
            Set-Content -LiteralPath $childScript -Value $childBody.Replace('__MARKER__', $marker)
            $childSpec = ConvertTo-DevWSCwdChildSpecBase64 -Command "pwsh" -Arguments @("-NoProfile", "-File", $childScript)

            $context = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "multi" -WindowId "DevWS-multi" -TabIndex 1 -StartupSpecSha256 "SPEC1"

            $process = Start-FreshCwdBootstrapProcess `
                -BootstrapPath (Get-DevWSCwdBootstrapPath) `
                -SetId "main" `
                -TerminalId "multi" `
                -WindowId "DevWS-multi" `
                -TabIndex 1 `
                -SessionId $context.SessionId `
                -PublicationPath $context.PublicationPath `
                -ChildSpecBase64 $childSpec `
                -WorkingDirectory $work

            try {
                $deadline = (Get-Date).AddSeconds(25)
                $publication = $null

                while ((Get-Date) -lt $deadline) {
                    if (Test-Path -LiteralPath $context.PublicationPath -PathType Leaf) {
                        $candidate = Get-Content -LiteralPath $context.PublicationPath -Raw | ConvertFrom-Json
                        if ([string]$candidate.startupState -eq "startup-child-active") { $publication = $candidate; break }
                    }
                    Start-Sleep -Milliseconds 100
                }

                Assert-True ($null -ne $publication) "startup-child-active observed while the child runs"
                Assert-Equal 1 ([int]$publication.tabIndex) "indexed publication carries the configured tabIndex"
                Assert-Equal $context.SessionId ([string]$publication.sessionId) "publication session id"
                Assert-Equal $work ([string]$publication.cwd) "initial cwd is the shell start directory"
                Assert-Equal $process.Id ([int]$publication.shellPid) "publisher pid published"

                $markerDeadline = (Get-Date).AddSeconds(10)
                while (-not (Test-Path -LiteralPath $marker -PathType Leaf) -and (Get-Date) -lt $markerDeadline) { Start-Sleep -Milliseconds 100 }
                Assert-True (Test-Path -LiteralPath $marker -PathType Leaf) "child is running"

                $active = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1
                Assert-Equal "available" ([string]$active.Status) "live indexed pair resolves"
                Assert-Equal "startup-child-active" ([string]$active.StartupState) "resolver reports child-active"
                Assert-Equal "SPEC1" ([string]$active.StartupSpecSha256) "resolver reports the recorded spec hash"
                Assert-Equal $work ([string]$active.Cwd) "resolver cwd"

                $returnDeadline = (Get-Date).AddSeconds(30)
                while ((Get-Date) -lt $returnDeadline) {
                    if (Test-Path -LiteralPath $context.PublicationPath -PathType Leaf) {
                        $after = Get-Content -LiteralPath $context.PublicationPath -Raw | ConvertFrom-Json
                        if ([string]$after.startupState -eq "startup-child-returned") { break }
                    }
                    Start-Sleep -Milliseconds 150
                }

                $returned = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1
                Assert-Equal "startup-child-returned" ([string]$returned.StartupState) "resolver reports child-returned"
                Assert-Equal $work ([string]$returned.Cwd) "cwd preserved across the child lifecycle"

                Start-Sleep -Milliseconds 1200
                $settled = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multi" -TabIndex 1
                Assert-Equal "startup-child-returned" ([string]$settled.StartupState) "interactive prompt republish preserves the lifecycle state"
                Assert-True (-not $process.HasExited) "shell stays interactive after the child returns"
            }
            finally {
                if (-not $process.HasExited) { Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue }
            }

            # Idle indexed tab: the lifecycle stays idle and cwd is still tracked.
            $idleContext = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "multidle" -WindowId "DevWS-multidle" -TabIndex 2 -StartupSpecSha256 "SPEC-IDLE"
            $idleSpec    = ConvertTo-DevWSCwdChildSpecBase64 -Command $null -Arguments @()

            $idleProcess = Start-FreshCwdBootstrapProcess `
                -BootstrapPath (Get-DevWSCwdBootstrapPath) `
                -SetId "main" `
                -TerminalId "multidle" `
                -WindowId "DevWS-multidle" `
                -TabIndex 2 `
                -SessionId $idleContext.SessionId `
                -PublicationPath $idleContext.PublicationPath `
                -ChildSpecBase64 $idleSpec `
                -WorkingDirectory $work

            try {
                $deadline = (Get-Date).AddSeconds(20)
                while (-not (Test-Path -LiteralPath $idleContext.PublicationPath -PathType Leaf) -and (Get-Date) -lt $deadline) { Start-Sleep -Milliseconds 100 }
                Assert-True (Test-Path -LiteralPath $idleContext.PublicationPath -PathType Leaf) "idle indexed publication exists"

                $idleRead = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "multidle" -TabIndex 2
                Assert-Equal "available" ([string]$idleRead.Status) "idle indexed pair resolves"
                Assert-Equal "idle" ([string]$idleRead.StartupState) "idle lifecycle state"
                Assert-Equal "SPEC-IDLE" ([string]$idleRead.StartupSpecSha256) "idle spec hash"
            }
            finally {
                if (-not $idleProcess.HasExited) { Stop-Process -Id $idleProcess.Id -Force -ErrorAction SilentlyContinue }
            }
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "launch plan creates tracked contexts only for genuinely missing terminals" {
        $stateRoot  = Join-Path $TestRoot "p6b-plan-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $missingTerm = New-TerminalDefinition -Id "planmiss" -WindowId "P6B-miss" -Path $TestRoot
            $missingTerm.tabs = @(
                [ordered]@{ command = "tool"; args = @("--x") },
                [ordered]@{ command = $null; args = @() }
            )
            $missingTerm.activeTab = 1

            $presentTerm = New-TerminalDefinition -Id "planpres" -WindowId "P6B-pres" -Path $TestRoot

            $config = ConvertTo-TestConfig -Windows @($missingTerm, $presentTerm)
            $state  = New-DevWSRuntimeState
            Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "planpres" -WindowId "P6B-pres" -Hwnd 780000

            $plan = Get-DevWSTerminalLaunchPlan `
                -Config $config `
                -SetId "main" `
                -State $state `
                -Terminals @($missingTerm, $presentTerm) `
                -WtHwnds @(780000) `
                -CandidateReader { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("P6B-pres")); RawCount = 2 } } `
                -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" }

            $missRecord = @($plan.Terminals | Where-Object { [string]$_.TerminalId -eq "planmiss" })[0]
            $presRecord = @($plan.Terminals | Where-Object { [string]$_.TerminalId -eq "planpres" })[0]

            Assert-Equal "missing" ([string]$missRecord.State) "genuinely missing terminal"
            Assert-Equal 2 @($missRecord.TrackingContexts).Count "one tracking context per configured tab"

            $missContexts = @($missRecord.TrackingContexts | Sort-Object { [int]$_.TabIndex })
            Assert-Equal (Get-DevWSCwdChildSpecFingerprint -Command "tool" -Arguments @("--x")) ([string]$missContexts[0].StartupSpecSha256) "tab 0 spec hash matches config"
            Assert-Equal (Get-DevWSCwdChildSpecFingerprint -Command $null -Arguments @()) ([string]$missContexts[1].StartupSpecSha256) "tab 1 spec hash matches config"
            Assert-True (Test-Path -LiteralPath $missContexts[0].SessionPath -PathType Leaf) "tab 0 expected record written"
            Assert-True (Test-Path -LiteralPath $missContexts[1].SessionPath -PathType Leaf) "tab 1 expected record written"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\planmiss.json") $missContexts[0].SessionPath "tab 0 keeps the legacy path"
            Assert-Equal (Join-Path $stateRoot "cwd-sessions\main\planmiss\1.json") $missContexts[1].SessionPath "tab 1 uses the indexed path"

            $created = @($missRecord.CreateArguments)
            Assert-Equal 2 (@($created | Where-Object { $_ -eq "new-tab" }).Count) "two tabs built"
            Assert-Equal 2 ([regex]::Matches(($created -join " "), [regex]::Escape((Get-DevWSCwdBootstrapPath))).Count) "both tabs tracked"
            Assert-Contains ($created -join " ") "focus-tab -t 1" "activeTab preserved"
            Assert-Equal ";" $created[[array]::IndexOf($created, "focus-tab") - 1] "separator before focus-tab"

            Assert-Equal "present" ([string]$presRecord.State) "present terminal"
            Assert-True ($null -eq $presRecord.TrackingContexts) "present terminal creates zero contexts"
            Assert-True ($null -eq $presRecord.CreateArguments) "present terminal has no creation arguments"

            $sessionFiles = @(Get-ChildItem -Path (Join-Path $stateRoot "cwd-sessions") -Recurse -File)
            Assert-Equal 2 $sessionFiles.Count "exactly two expected records for the one missing terminal"
            Assert-True (@($sessionFiles | ForEach-Object { $_.Name }) -contains "planmiss.json") "tab 0 legacy file present"
            Assert-Equal 1 @($sessionFiles | Where-Object { $_.DirectoryName -like "*\planmiss" }).Count "tab 1 indexed file present"

            # Ambiguous terminals create zero contexts and never start.
            $ambTerm = New-TerminalDefinition -Id "planamb" -WindowId "P6B-amb" -Path $TestRoot
            $config2 = ConvertTo-TestConfig -Windows @($ambTerm)
            $shared  = { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("P6B-amb")); RawCount = 2 } }

            $plan2 = Get-DevWSTerminalLaunchPlan `
                -Config $config2 -SetId "main" -State $null -Terminals @($ambTerm) `
                -WtHwnds @(781000, 781010) `
                -CandidateReader $shared `
                -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" }

            Assert-Equal "ambiguous" ([string]$plan2.Terminals[0].State) "duplicate candidates are ambiguous"
            Assert-True ($null -eq $plan2.Terminals[0].TrackingContexts) "ambiguous terminal creates zero contexts"
            $kick2 = Start-DevWSTerminalLaunchPlan -Plan $plan2 -ProcessStarter { param($Record) throw "ambiguous must never start" }
            Assert-Equal 0 @($kick2.Kicks).Count "ambiguous terminal never starts"

            # Context failure: partial disposable creation fails only that
            # terminal and never starts a process.
            $failRoot = Join-Path $TestRoot "p6b-plan-fail"
            New-Item -ItemType Directory -Path (Join-Path $failRoot "cwd-sessions\main") -Force | Out-Null
            Set-Content -LiteralPath (Join-Path $failRoot "cwd-sessions\main\planfail") -Value "a file where the indexed directory belongs" -NoNewline

            $env:DEVWS_STATE_ROOT = $failRoot
            try {
                $failTerm = New-TerminalDefinition -Id "planfail" -WindowId "P6B-fail" -Path $TestRoot
                $config3  = ConvertTo-TestConfig -Windows @($failTerm)

                $plan3 = Get-DevWSTerminalLaunchPlan `
                    -Config $config3 -SetId "main" -State $null -Terminals @($failTerm) -WtHwnds @()

                Assert-Equal "failed" ([string]$plan3.Terminals[0].State) "context failure fails the terminal"
                Assert-True (-not [string]::IsNullOrWhiteSpace([string]$plan3.Terminals[0].Error)) "failure carries an error"
                Assert-Equal 0 ([int]$plan3.Counts.Missing) "failed terminal is not missing"

                $script:p6bPlanKicks = 0
                $kick3 = Start-DevWSTerminalLaunchPlan -Plan $plan3 -ProcessStarter { param($Record) $script:p6bPlanKicks++ }
                Assert-Equal 0 $script:p6bPlanKicks "failed terminal never starts a process"
                Assert-Equal 0 @($kick3.Failures).Count "plan failure is not a kick failure"

                # Documented behavior: tab 0's expected record may already exist
                # (disposable partial creation is acceptable; nothing started).
                Assert-True (Test-Path -LiteralPath (Join-Path $failRoot "cwd-sessions\main\planfail.json") -PathType Leaf) "partial disposable state is acceptable"
            }
            finally {
                $env:DEVWS_STATE_ROOT = $stateRoot
            }
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "old-runtime rollback keeps the legacy tab-0 pair authoritative" {
        $stateRoot  = Join-Path $TestRoot "p6b-rollback-state"
        $savedState = $env:DEVWS_STATE_ROOT

        try {
            $env:DEVWS_STATE_ROOT = $stateRoot

            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            $dirNew   = Join-Path $TestRoot "p6b-rollback-new"
            $dirB     = Join-Path $TestRoot "p6b-rollback-b"
            $dirC     = Join-Path $TestRoot "p6b-rollback-c"
            New-Item -ItemType Directory -Path $dirNew, $dirB, $dirC -Force | Out-Null

            function New-P6BRollbackPublication {
                param([string]$SessionId, [string]$Cwd, [int]$ProcessId, [string]$StartTime, [int]$TabIndex = -1, [string]$StartupState = "")
                $record = [ordered]@{
                    version = 1; setId = "main"; terminalId = "roll"; windowId = "DevWS-roll"
                    sessionId = $SessionId; cwd = $Cwd
                    shellPid = $ProcessId; shellStartTimeUtc = $StartTime
                    updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
                }
                if ($TabIndex -ge 0) { $record.tabIndex = $TabIndex }
                if (-not [string]::IsNullOrWhiteSpace($StartupState)) { $record.startupState = $StartupState }
                return $record
            }

            # Phase 1: a NEW runtime created this terminal (tab 0 legacy pair,
            # tabs 1/2 indexed pairs) and all three shells are alive.
            $t0 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "roll" -WindowId "DevWS-roll" -StartupSpecSha256 "S0"
            $t1 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "roll" -WindowId "DevWS-roll" -TabIndex 1 -StartupSpecSha256 "S1"
            $t2 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "roll" -WindowId "DevWS-roll" -TabIndex 2 -StartupSpecSha256 "S2"
            Write-DevWSCwdPublication -Path $t0.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t0.SessionId -Cwd $dirNew -ProcessId $PID -StartTime $startIso)
            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t1.SessionId -Cwd $dirB -ProcessId $PID -StartTime $startIso -TabIndex 1)
            Write-DevWSCwdPublication -Path $t2.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t2.SessionId -Cwd $dirC -ProcessId $PID -StartTime $startIso -TabIndex 2)

            foreach ($tabIndex in @(0, 1, 2)) {
                Assert-Equal "available" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex $tabIndex).Status) "new-runtime tab $tabIndex available"
            }

            # Phase 2: an OLD runtime (rollback) reset the terminal. It rotated
            # ONLY the legacy tab-0 pair and recreated tab 0 alone; the old
            # tab 1/2 shells died with the old window and their indexed state is
            # now stale/dead, while the indexed EXPECTED records were never
            # touched by the old build.
            $rotated = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "roll" -WindowId "DevWS-roll"
            Write-DevWSCwdPublication -Path $rotated.PublicationPath -Record (New-P6BRollbackPublication -SessionId $rotated.SessionId -Cwd $dirNew -ProcessId $PID -StartTime $startIso)

            $deadProc = Start-Process -FilePath (Get-Process -Id $PID).Path -ArgumentList "-NoLogo", "-NoProfile", "-Command", "exit" -PassThru
            $deadProc.WaitForExit()

            Write-DevWSCwdPublication -Path $t1.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t1.SessionId -Cwd $dirB -ProcessId $deadProc.Id -StartTime $startIso -TabIndex 1)
            Write-DevWSCwdPublication -Path $t2.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t2.SessionId -Cwd $dirC -ProcessId $deadProc.Id -StartTime $startIso -TabIndex 2)

            $roll0 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 0
            Assert-Equal "available" ([string]$roll0.Status) "tab 0 resolves the CURRENT legacy pair after the old-runtime reset"
            Assert-Equal $rotated.SessionId ([string]$roll0.SessionId) "tab 0 uses the rotated legacy session"
            Assert-True ($null -eq $roll0.StartupSpecSha256) "old-runtime tab 0 record carries no spec hash"

            $roll1 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 1
            $roll2 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 2
            Assert-Equal "unavailable" ([string]$roll1.Status) "tab 1 indexed state is stale"
            Assert-Equal "shell-dead" ([string]$roll1.Reason) "tab 1 old shell is dead"
            Assert-Equal "unavailable" ([string]$roll2.Status) "tab 2 indexed state is stale"
            Assert-Equal "shell-dead" ([string]$roll2.Reason) "tab 2 old shell is dead"

            # No alternate stale tab-0 generation exists: an indexed 0.json pair
            # is never consulted for tab 0 (the legacy path is authoritative).
            $staleZeroSession = Join-Path (Join-Path $stateRoot "cwd-sessions\main\roll") "0.json"
            $staleZeroPub     = Join-Path (Join-Path $stateRoot "cwd\main\roll") "0.json"
            Write-DevWSCwdSessionRecord -Path $staleZeroSession -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "roll"; windowId = "DevWS-roll"; tabIndex = 0; sessionId = "stale-alt"
            })
            Write-DevWSCwdPublication -Path $staleZeroPub -Record (New-P6BRollbackPublication -SessionId "stale-alt" -Cwd $dirC -ProcessId $PID -StartTime $startIso -TabIndex 0)

            $stillLegacy = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 0
            Assert-Equal "available" ([string]$stillLegacy.Status) "tab 0 still resolves"
            Assert-Equal $rotated.SessionId ([string]$stillLegacy.SessionId) "tab 0 never prefers an indexed alternate generation"
            Assert-Equal $dirNew ([string]$stillLegacy.Cwd) "tab 0 cwd stays on the legacy pair"

            # Phase 3: the NEW runtime runs again and refreshes ONLY tabs 1+
            # (a normal reset/recreation rotates the indexed pairs); tab 0 is
            # untouched and still resolves its current legacy pair.
            $t1new = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "roll" -WindowId "DevWS-roll" -TabIndex 1 -StartupSpecSha256 "S1b"
            $t2new = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "roll" -WindowId "DevWS-roll" -TabIndex 2 -StartupSpecSha256 "S2b"
            Write-DevWSCwdPublication -Path $t1new.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t1new.SessionId -Cwd $dirB -ProcessId $PID -StartTime $startIso -TabIndex 1 -StartupState "idle")
            Write-DevWSCwdPublication -Path $t2new.PublicationPath -Record (New-P6BRollbackPublication -SessionId $t2new.SessionId -Cwd $dirC -ProcessId $PID -StartTime $startIso -TabIndex 2 -StartupState "idle")

            Assert-Equal "available" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 1).Status) "refreshed tab 1 available"
            Assert-Equal "available" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 2).Status) "refreshed tab 2 available"
            $final0 = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "roll" -TabIndex 0
            Assert-Equal $rotated.SessionId ([string]$final0.SessionId) "tab 0 legacy generation untouched by the tabs 1+ refresh"
        }
        finally {
            if ($null -eq $savedState) { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
            else { $env:DEVWS_STATE_ROOT = $savedState }
        }
    }

    Test-Case "broker protocol stays plan-only with no tracking state on the wire" {
        Assert-Equal 1 (Get-DevWSBrokerProtocolVersion) "protocol version stays 1"
        Assert-Equal "DevWS.ElevatedBroker.v1" (Get-DevWSElevatedBrokerPipeName) "pipe name unchanged"
        Assert-Equal 65536 (Get-DevWSBrokerMaxLineLength) "line ceiling unchanged"

        $protocol = Get-SourceOf "src\lib\devws-broker-protocol.ps1"

        foreach ($token in @("tabIndex", "startupSpec", "TrackingContext", "shellPid", "cwd-sessions", "cwdPublication")) {
            Assert-NotContains $protocol $token "no tracking state crosses the broker pipe: $token"
        }

        # Phase 2-B: the only 'publication' the protocol carries is the
        # High-generated capture publication identity on the successful FINAL.
        Assert-Contains $protocol 'Publication = [string]$final.publication' "the FINAL publication identity is surfaced"

        # A prepare-launch request carrying tracking state is rejected outright.
        $tampered = '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"t1","move":false}],"trackingContexts":[]}'
        $test = Test-DevWSBrokerProtocolRequest -Line $tampered
        Assert-Equal $false ([bool]$test.Ok) "unknown wire fields are rejected"
        Assert-Contains ([string]$test.Error) "trackingContexts" "the rejection names the offending field"

        # The accepted prepare payload remains exactly the placement protocol.
        $valid = '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"t1","move":false}]}'
        $test2 = Test-DevWSBrokerProtocolRequest -Line $valid
        Assert-Equal $true ([bool]$test2.Ok) "placement-only prepare payload stays valid"
    }

    Write-Host ""
    Start-TestGroup -Name 'per-tab-paths' -Title 'Per-tab paths (Pass 6C)'

    Test-Case "optional tab paths validate structurally and round-trip" {
        function New-P6CPathJson {
            param([object[]]$Tabs)

            return ([ordered]@{
                version    = 3
                defaultSet = "main"
                bindings   = @()
                sets       = @([ordered]@{
                    id      = "main"
                    windows = @([ordered]@{
                        id        = "ptp"
                        type      = "terminal"
                        enabled   = $true
                        windowId  = "PT-A"
                        path      = $TestRoot
                        elevated  = $true
                        tabs      = $Tabs
                        activeTab = 0
                        layout    = [ordered]@{ x = 0; y = 0; w = 100; h = 100 }
                    })
                })
            } | ConvertTo-Json -Depth 20)
        }

        $baseTabs = {
            @(
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = $null; args = @() }
            )
        }

        $cases = @(
            @{ Name = "valid-one";        Expect = $null;              Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue $TestRoot -Force } },
            @{ Name = "valid-all";        Expect = $null;              Mutate = { param($tabs) foreach ($t in $tabs) { $t | Add-Member -NotePropertyName path -NotePropertyValue $TestRoot -Force } } },
            @{ Name = "valid-tab0";       Expect = $null;              Mutate = { param($tabs) $tabs[0] | Add-Member -NotePropertyName path -NotePropertyValue $TestRoot -Force } },
            @{ Name = "valid-nonexistent"; Expect = $null;             Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue (Join-Path $TestRoot "ptp-does-not-exist") -Force } },
            @{ Name = "invalid-null";     Expect = "must be a non-empty string"; Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue $null -Force } },
            @{ Name = "invalid-blank";    Expect = "must be a non-empty string"; Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue "" -Force } },
            @{ Name = "invalid-space";    Expect = "must be a non-empty string"; Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue "   " -Force } },
            @{ Name = "invalid-relative"; Expect = "must be an absolute path";   Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue "relative\dir" -Force } },
            @{ Name = "invalid-number";   Expect = "must be a non-empty string"; Mutate = { param($tabs) $tabs[1] | Add-Member -NotePropertyName path -NotePropertyValue 7 -Force } }
        )

        foreach ($case in $cases) {
            $json   = New-P6CPathJson -Tabs (& $baseTabs)
            $config = $json | ConvertFrom-Json
            $tabs   = @($config.sets[0].windows[0].tabs)
            & $case.Mutate $tabs

            $message = ""

            try { Assert-DevWSConfig -Config $config -Source "test" } catch { $message = $_.Exception.Message }

            if ($null -eq $case.Expect) {
                Assert-True ([string]::IsNullOrEmpty($message)) "$($case.Name) accepted: $message"
            }
            else {
                Assert-Contains $message $case.Expect "$($case.Name) rejected"
            }
        }

        # Round-trip: an explicit override persists and an absent one stays absent.
        $json   = New-P6CPathJson -Tabs (& $baseTabs)
        $config = $json | ConvertFrom-Json
        @($config.sets[0].windows[0].tabs)[1] | Add-Member -NotePropertyName path -NotePropertyValue "D:\RoundTrip" -Force
        $roundTripped = ($config | ConvertTo-Json -Depth 20 | ConvertFrom-Json)
        $roundTabs    = @($roundTripped.sets[0].windows[0].tabs)

        Assert-Equal 3 ([int]$roundTripped.version) "schema stays v3"
        Assert-Equal "D:\RoundTrip" ([string]$roundTabs[1].path) "override survives round-trip"
        Assert-True ($null -eq $roundTabs[0].PSObject.Properties["path"]) "absence survives round-trip"
    }

