    Test-Case "operation path validation covers every effective tab and stays scoped" {
        function Get-P6COptionalMessage {
            param([scriptblock]$Body)
            try { & $Body | Out-Null; return "" } catch { return $_.Exception.Message }
        }

        $dirOk   = Join-Path $TestRoot "p6c-op-ok"
        $fileBad = Join-Path $TestRoot "p6c-op-file.txt"
        $missing = Join-Path $TestRoot "p6c-op-missing"
        New-Item -ItemType Directory -Path $dirOk -Force | Out-Null
        Set-Content -LiteralPath $fileBad -Value "x" -NoNewline

        function New-P6COpTerminal {
            param([string]$Id, [string]$WindowId, [string]$TerminalPath, [object]$Tab1Path = $null, [bool]$AddTab1Path = $false)

            $tab1 = [ordered]@{ command = $null; args = @() }

            if ($AddTab1Path) { $tab1["path"] = $Tab1Path }

            return [ordered]@{
                id        = $Id
                type      = "terminal"
                enabled   = $true
                windowId  = $WindowId
                path      = $TerminalPath
                elevated  = $true
                tabs      = @([ordered]@{ command = $null; args = @() }, $tab1)
                activeTab = 0
                layout    = [ordered]@{ x = 0; y = 0; w = 100; h = 100 }
            }
        }

        $okConfig = ConvertTo-TestConfig -Windows @((New-P6COpTerminal -Id "ok" -WindowId "PT-OK" -TerminalPath $dirOk))
        $okItem   = $okConfig.sets[0].windows[0]
        Assert-True ([string]::IsNullOrEmpty((Get-P6COptionalMessage { Assert-DevWSTerminalPath -Terminal $okItem -SetId "main" }))) "all-valid terminal passes"

        # Missing inherited terminal.path keeps the historical message shape.
        $badInherit = ConvertTo-TestConfig -Windows @((New-P6COpTerminal -Id "bi" -WindowId "PT-BI" -TerminalPath $missing))
        $badInheritItem = $badInherit.sets[0].windows[0]
        $message1 = Get-ThrownMessage { Assert-DevWSTerminalPath -Terminal $badInheritItem -SetId "main" }
        Assert-Contains $message1 "working directory does not exist" "missing inherited path rejected"
        Assert-Contains $message1 $missing "missing inherited path named"

        # A missing explicit tab override names the exact tab index and path.
        $badOverride = ConvertTo-TestConfig -Windows @((New-P6COpTerminal -Id "bo" -WindowId "PT-BO" -TerminalPath $dirOk -Tab1Path $missing -AddTab1Path $true))
        $badOverrideItem = $badOverride.sets[0].windows[0]
        $message2 = Get-ThrownMessage { Assert-DevWSTerminalPath -Terminal $badOverrideItem -SetId "main" }
        Assert-Contains $message2 "tab 1 working directory does not exist" "missing override names the tab index"
        Assert-Contains $message2 $missing "missing override names the path"

        # A file masquerading as a directory fails for the exact tab.
        $badFile = ConvertTo-TestConfig -Windows @((New-P6COpTerminal -Id "bf" -WindowId "PT-BF" -TerminalPath $dirOk -Tab1Path $fileBad -AddTab1Path $true))
        $badFileItem = $badFile.sets[0].windows[0]
        $message3 = Get-ThrownMessage { Assert-DevWSTerminalPath -Terminal $badFileItem -SetId "main" }
        Assert-Contains $message3 "tab 1 working directory does not exist" "file as tab path rejected"

        # Set scoping: a broken terminal in another set never blocks the selected set.
        $setA = [ordered]@{ id = "seta"; windows = @(
            (New-P6COpTerminal -Id "ok" -WindowId "PT-SA" -TerminalPath $dirOk)
        ) }
        $setB = [ordered]@{ id = "setb"; windows = @(
            (New-P6COpTerminal -Id "broken" -WindowId "PT-SB" -TerminalPath $missing)
        ) }
        $scopedConfig = ConvertTo-TestConfig -Sets @($setA, $setB) -DefaultSet "seta"

        Assert-True ([string]::IsNullOrEmpty((Get-P6COptionalMessage { Assert-DevWSTerminalPaths -Config $scopedConfig -Set $scopedConfig.sets[0] }))) "valid set passes despite a broken other set"
        Assert-Throws { Assert-DevWSTerminalPaths -Config $scopedConfig -Set $scopedConfig.sets[1] } "working directory does not exist"

        # Single-terminal scoping inside one set.
        $pairConfig = ConvertTo-TestConfig -Windows @(
            (New-P6COpTerminal -Id "good" -WindowId "PT-G1" -TerminalPath $dirOk),
            (New-P6COpTerminal -Id "bad" -WindowId "PT-G2" -TerminalPath $missing)
        )
        $goodItem = $pairConfig.sets[0].windows[0]
        Assert-True ([string]::IsNullOrEmpty((Get-P6COptionalMessage { Assert-DevWSTerminalPath -Terminal $goodItem -SetId "main" }))) "good terminal unaffected by a broken sibling"
    }

    Test-Case "launch and single reset validate every tab path before any side effect" {
        $target = New-LifecycleConfigCopy "p6c-pretab"
        $dirOk  = Join-Path $TestRoot "p6c-pretab-ok"
        New-Item -ItemType Directory -Path $dirOk -Force | Out-Null
        $missing = Join-Path $TestRoot "p6c-pretab-missing"

        # secondary/termbeta stays valid at terminal.path but its LAST tab gains
        # a missing explicit override.
        $config = Read-DevWSConfigFile -Path $target
        $term   = @($config.sets[1].windows | Where-Object { $_.id -eq "termbeta" })[0]
        $term.path = $dirOk
        $lastTab   = @($term.tabs).Count - 1
        @($term.tabs)[$lastTab] | Add-Member -NotePropertyName path -NotePropertyValue $missing -Force
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

        $calls = [System.Collections.Generic.List[object]]::new()
        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            function Get-DevWSRootScheduledTaskState {
                param([string]$TaskName)
                return 3
            }

            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $calls.Add([pscustomobject]@{ Kind = $Kind; Payload = $Payload })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }

            function Start-Process {
                param($FilePath, $ArgumentList, [switch]$Wait, [switch]$PassThru)
                return [pscustomobject]@{ ExitCode = 0 }
            }

            $message = Get-ThrownMessage { Reset-DevWSTerminal -Reference "secondary/termbeta" }
            Assert-Contains $message "tab $lastTab working directory does not exist" "reset refuses before any close"
            Assert-Equal 0 $calls.Count "no worker request before complete validation"

            Assert-Throws { Invoke-DevWSLaunch -SetId "secondary" } "tab $lastTab working directory does not exist"
            Assert-Equal 0 $calls.Count "launch refuses before any side effect"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "set-path grammar: legacy, per-tab, tab-0 mirroring, clear, and refusals" {
        $target = New-WritableConfigCopy "p6c-setpath"
        $dirA   = Join-Path $TestRoot "p6c-sp-a"
        $dirA2  = Join-Path $TestRoot "p6c-sp-a2"
        $dirB   = Join-Path $TestRoot "p6c-sp-b"
        New-Item -ItemType Directory -Path $dirA, $dirA2, $dirB -Force | Out-Null

        # Per-tab override first, then a legacy terminal.path change.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "1", $dirB)
        Assert-Equal 0 $result.ExitCode "tab override exit"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", $dirA)
        Assert-Equal 0 $result.ExitCode "legacy exit"
        Assert-Contains $result.Output "keep their current directory until reset" "config only"
        Assert-Contains $result.Output "preserved" "override preservation reported"

        $config = Read-DevWSConfigFile -Path $target
        $slot   = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal (Resolve-Path -LiteralPath $dirA).Path ([string]$slot.path) "legacy set terminal.path"
        Assert-Equal (Resolve-Path -LiteralPath $dirB).Path ([string]@($slot.tabs)[1].path) "override preserved by legacy set-path"

        # Tab 0 mirrors into terminal.path.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "0", $dirA2)
        Assert-Equal 0 $result.ExitCode "tab0 exit"
        Assert-Contains $result.Output "mirrors the tab-0 override" "tab-0 mirror note"

        $config = Read-DevWSConfigFile -Path $target
        $slot   = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-Equal (Resolve-Path -LiteralPath $dirA2).Path ([string]$slot.path) "tab-0 override mirrors terminal.path"
        Assert-Equal (Resolve-Path -LiteralPath $dirA2).Path ([string]@($slot.tabs)[0].path) "tab-0 override stored"

        # Clear tab 1 removes the property only.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "1", "--clear")
        Assert-Equal 0 $result.ExitCode "clear tab 1 exit"
        $config = Read-DevWSConfigFile -Path $target
        $slot   = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-True ($null -eq @($slot.tabs)[1].PSObject.Properties["path"]) "tab 1 override removed"
        Assert-Equal (Resolve-Path -LiteralPath $dirA2).Path ([string]$slot.path) "terminal.path kept by clear tab 1"

        # Clear tab 0 removes the property but leaves terminal.path unchanged.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "0", "--clear")
        Assert-Equal 0 $result.ExitCode "clear tab 0 exit"
        $config = Read-DevWSConfigFile -Path $target
        $slot   = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
        Assert-True ($null -eq @($slot.tabs)[0].PSObject.Properties["path"]) "tab 0 override removed"
        Assert-Equal (Resolve-Path -LiteralPath $dirA2).Path ([string]$slot.path) "terminal.path unchanged by clear tab 0"

        # Refusals are atomic: no canonical bytes change.
        $before = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))

        foreach ($case in @(
            @{ Args = @("set-path", "slot", "--tab");                          Kind = "missing index" },
            @{ Args = @("set-path", "slot", "--tab", "-1", $dirB);             Kind = "negative index" },
            @{ Args = @("set-path", "slot", "--tab", "x", $dirB);              Kind = "non-integer index" },
            @{ Args = @("set-path", "slot", "--tab", "99", $dirB);             Kind = "out-of-range index" },
            @{ Args = @("set-path", "slot", "--tab", "1");                     Kind = "missing path" },
            @{ Args = @("set-path", "slot", "--tab", "1", "--clear", "extra"); Kind = "clear plus path" },
            @{ Args = @("set-path", "slot", "--tab", "1", "--tab", "2", $dirB); Kind = "duplicate --tab" },
            @{ Args = @("set-path", "slot", "--wat", "1");                     Kind = "unknown switch" }
        )) {
            $result = Invoke-WsCli -ConfigPath $target -Arguments $case.Args
            Assert-Equal 1 $result.ExitCode "refusal exit ($($case.Kind))"
        }

        # Oversized --tab indices: the Int32 maximum parses and then refuses as
        # out of configured range; larger decimals refuse deterministically
        # without a raw conversion failure.
        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "2147483647", $dirB)
        Assert-Equal 1 $result.ExitCode "Int32 max index refused as out of range"
        Assert-Contains $result.Output "does not address an existing tab" "range refusal is deterministic"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "2147483648", $dirB)
        Assert-Equal 1 $result.ExitCode "Int32 overflow index refused"
        Assert-Contains $result.Output "valid configured tab index" "overflow refusal is deterministic"

        $result = Invoke-WsCli -ConfigPath $target -Arguments @("set-path", "slot", "--tab", "999999999999999999999", $dirB)
        Assert-Equal 1 $result.ExitCode "oversized index refused"
        Assert-Contains $result.Output "valid configured tab index" "oversized refusal is deterministic"

        $after = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))
        Assert-Equal $before $after "refusals never modify canonical bytes"
    }

    Test-Case "copies and clones preserve explicit tab overrides exactly" {
        $tabs = @(
