        Assert-True ($null -eq @($copies)[0].PSObject.Properties["path"]) "absent stays absent"
        Assert-Equal "D:\B" ([string]@($copies)[1].path) "explicit override preserved"
        Assert-True ($null -eq @($copies)[2].PSObject.Properties["path"]) "absent stays absent again"

        $config = Get-TestWorkspaceConfig
        $slot   = Resolve-DevWSReference -Config $config -Reference "slot" -Type terminal
        @($slot.tabs)[0] | Add-Member -NotePropertyName path -NotePropertyValue "D:\Slot0" -Force
        @($slot.tabs)[1] | Add-Member -NotePropertyName path -NotePropertyValue "D:\Slot1" -Force

