    Write-Host ""
    Start-TestGroup -Name 'managed-tab-identity' -Title 'Managed tab identity (Pass 6C)'

    Test-Case "managed tab title generator and parser are exact" {
        Assert-Equal "W" (Get-DevWSTerminalTabTitle -WindowId "W" -TabIndex 0) "tab 0 title"
        Assert-Equal "W#DevWS:1" (Get-DevWSTerminalTabTitle -WindowId "W" -TabIndex 1) "tab 1 title"
        Assert-Equal "W#DevWS:27" (Get-DevWSTerminalTabTitle -WindowId "W" -TabIndex 27) "tab 27 title"
        Assert-Throws { Get-DevWSTerminalTabTitle -WindowId "W" -TabIndex -1 } "cannot be negative"

        $r0 = Resolve-DevWSTerminalTabTitle -WindowId "W" -Title "W"
        $r1 = Resolve-DevWSTerminalTabTitle -WindowId "W" -Title "W#DevWS:1"
        $r27 = Resolve-DevWSTerminalTabTitle -WindowId "W" -Title "W#DevWS:27"
        Assert-Equal $true ([bool]$r0.IsManaged); Assert-Equal 0 ([int]$r0.TabIndex) "exact base maps to tab 0"
        Assert-Equal $true ([bool]$r1.IsManaged); Assert-Equal 1 ([int]$r1.TabIndex) "canonical suffix maps to tab 1"
        Assert-Equal $true ([bool]$r27.IsManaged); Assert-Equal 27 ([int]$r27.TabIndex) "large index"

        $rejected = @(
            "W#DevWS:0", "W#DevWS:01", "W#DevWS:-1", "W#DevWS:+1", "W#DevWS:",
            "W#DevWS:x", "W#DevWS:1extra", "prefixW#DevWS:1", "W#DevWS:1suffix", "Other#DevWS:1",
            "W#DevWS:2147483648", "W#DevWS:999999999999999999999999"
        )
        foreach ($title in $rejected) {
            Assert-True (-not [bool](Resolve-DevWSTerminalTabTitle -WindowId "W" -Title $title).IsManaged) "rejected: $title"
        }

        # Bounded Int32 parsing: the maximum representable positive index is
        # managed; oversized decimals are simply unmanaged WITHOUT throwing.
        $maxIndex = Resolve-DevWSTerminalTabTitle -WindowId "W" -Title "W#DevWS:2147483647"
        Assert-Equal $true ([bool]$maxIndex.IsManaged) "Int32 max suffix is managed"
        Assert-Equal 2147483647 ([int]$maxIndex.TabIndex) "Int32 max index value"

        foreach ($overflowTitle in @("W#DevWS:2147483648", "W#DevWS:999999999999999999999999")) {
            $parsed  = $null
            $message = ""

            try { $parsed = Resolve-DevWSTerminalTabTitle -WindowId "W" -Title $overflowTitle } catch { $message = $_.Exception.Message }

            Assert-Equal "" $message "no exception for $overflowTitle"
            Assert-True (-not [bool]$parsed.IsManaged) "unmanaged: $overflowTitle"
            Assert-True ($null -eq $parsed.TabIndex) "no index reported: $overflowTitle"
        }

        Assert-True (-not [bool](Resolve-DevWSTerminalTabTitle -WindowId "W" -Title $null).IsManaged) "null title rejected"
        Assert-True (-not [bool](Resolve-DevWSTerminalTabTitle -WindowId "W" -Title "").IsManaged) "empty title rejected"

        # Case handling matches the existing case-insensitive windowId identity.
        $caseFold = Resolve-DevWSTerminalTabTitle -WindowId "W" -Title "w#devws:2"
        Assert-Equal $true ([bool]$caseFold.IsManaged); Assert-Equal 2 ([int]$caseFold.TabIndex) "case-insensitive family"
    }

    Test-Case "windowId collision invariant refuses cross-terminal family impersonation" {
        function New-P6CCollisionConfig {
            param([string[]]$WindowIds)

            $windows = @()
            $index   = 0

            foreach ($windowId in $WindowIds) {
                $windows += [ordered]@{
                    id        = "t$index"
                    type      = "terminal"
                    enabled   = $true
                    windowId  = $windowId
                    path      = "C:\Temp"
                    elevated  = $true
                    tabs      = @([ordered]@{ command = $null; args = @() }, [ordered]@{ command = $null; args = @() })
                    activeTab = 0
                    layout    = [ordered]@{ x = 0; y = 0; w = 100; h = 100 }
                }
                $index++
            }

            return ([ordered]@{
                version    = 3
                defaultSet = "main"
                bindings   = @()
                sets       = @([ordered]@{ id = "main"; windows = $windows })
            } | ConvertTo-Json -Depth 20 | ConvertFrom-Json)
        }

        function Get-P6CCollisionMessage {
            param([string[]]$WindowIds)
            $message = ""
            try { Assert-DevWSConfig -Config (New-P6CCollisionConfig -WindowIds $WindowIds) -Source "test" } catch { $message = $_.Exception.Message }
            return $message
        }

        # Valid: ordinary ids and the preserved historical DevWS-1/2/3 family.
        $valid = Get-P6CCollisionMessage -WindowIds @("A", "B", "DevWS-1", "DevWS-2")
        Assert-True ([string]::IsNullOrEmpty($valid)) "ordinary ids pass: $valid"

        $collision = Get-P6CCollisionMessage -WindowIds @("Foo", "Foo#DevWS:1")
        Assert-Contains $collision "collides with the managed tab-title family" "family base collision rejected"

        $caseCollision = Get-P6CCollisionMessage -WindowIds @("foo", "FOO#devws:2")
        Assert-Contains $caseCollision "collides with the managed tab-title family" "case-insensitive collision rejected"

        # Malformed base-like ids are not canonical family members and stay valid.
        $lookalikes = Get-P6CCollisionMessage -WindowIds @("Foo", "Foo#DevWS:x", "Foo#DevWS:01", "Foo#DevWS:0")
        Assert-True ([string]::IsNullOrEmpty($lookalikes)) "non-canonical lookalikes cannot impersonate: $lookalikes"

        # An Int32-overflow suffix is not representable as a configured tab
        # index, so validation must complete normally (no family collision and
        # no crash) while the real collision still refuses.
        $overflowLookalike = Get-P6CCollisionMessage -WindowIds @("Foo", "Foo#DevWS:2147483648")
        Assert-True ([string]::IsNullOrEmpty($overflowLookalike)) "Int32-overflow suffix is not a family member: $overflowLookalike"
    }

    Test-Case "family-aware association, presence, and candidate selection" {
        $familyTab1 = New-DevWSPresentTabNameSet -Names @("W#DevWS:1")

        Assert-True (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames (New-DevWSPresentTabNameSet -Names @("W")) -RequireProcess) "tab 0 association"
        Assert-True (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames $familyTab1 -RequireProcess) "tab 1 association"
        Assert-True (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames (New-DevWSPresentTabNameSet -Names @("W#DevWS:2")) -RequireProcess) "tab 2 association"
        Assert-True (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames (New-DevWSPresentTabNameSet -Names @("W", "W")) -RequireProcess) "legacy duplicate base titles still associate"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames (New-DevWSPresentTabNameSet -Names @("W#DevWS:01")) -RequireProcess)) "malformed lookalike rejected"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames (New-DevWSPresentTabNameSet -Names @("Other")) -RequireProcess)) "unrelated name rejected"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "W" -ExpectedWindowId "Other" -ProcessName "WindowsTerminal.exe" -TabNames $familyTab1 -RequireProcess)) "state recorded for another terminal rejected"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "notepad.exe" -TabNames $familyTab1 -RequireProcess)) "foreign process rejected"

        Assert-True (Test-DevWSTerminalPresent -PresentTabNames $familyTab1 -WindowId "W") "presence from a non-zero managed tab"
        Assert-True (Test-DevWSTerminalPresent -PresentTabNames (New-DevWSPresentTabNameSet -Names @("W", "W")) -WindowId "W") "legacy presence"
        Assert-True (-not (Test-DevWSTerminalPresent -PresentTabNames (New-DevWSPresentTabNameSet -Names @("W-manual")) -WindowId "W")) "unmanaged lookalike is not presence"
        Assert-True (-not (Test-DevWSTerminalPresent -PresentTabNames $familyTab1 -WindowId "Other")) "other windowId not present"

        $candidate = [pscustomobject]@{ Hwnd = 21; ExpectedWindowId = $null; ProcessName = "WindowsTerminal.exe"; TabNames = $familyTab1 }
        $selected  = Select-DevWSTerminalHwndCandidate -Candidates @($candidate) -WindowId "W" -RequireProcess
        Assert-Equal 21 ([long]$selected.Hwnd) "candidate with only a nonzero managed tab is accepted"

        $lookalike = [pscustomobject]@{ Hwnd = 22; ExpectedWindowId = $null; ProcessName = "WindowsTerminal.exe"; TabNames = (New-DevWSPresentTabNameSet -Names @("W#DevWS:0")) }
        Assert-True ($null -eq (Select-DevWSTerminalHwndCandidate -Candidates @($lookalike) -WindowId "W" -RequireProcess)) "malformed lookalike candidate rejected"

        # A locator-style exact title never impersonates a managed tab.
        $locatorTitle = New-DevWSLocatorTitle -WindowId "W"
        Assert-True (-not [bool](Resolve-DevWSTerminalTabTitle -WindowId "W" -Title $locatorTitle).IsManaged) "locator title is not a family member"
        Assert-True (-not (Test-DevWSTerminalPresent -PresentTabNames (New-DevWSPresentTabNameSet -Names @($locatorTitle)) -WindowId "W")) "locator-only window is not terminal presence"

        # Oversized live suffixes are external input: every caller must stay
        # safe (no exception, not present, not associated, not selected).
        $overflowNames = New-DevWSPresentTabNameSet -Names @("W#DevWS:999999999999999999999999")
        Assert-True (-not (Test-DevWSTerminalTitleFamily -WindowId "W" -TabNames $overflowNames)) "family check safe for an oversized suffix"
        Assert-True (-not (Test-DevWSTerminalPresent -PresentTabNames $overflowNames -WindowId "W")) "presence safe for an oversized suffix"
        Assert-True (-not (Test-DevWSHwndAssociation -WindowId "W" -ProcessName "WindowsTerminal.exe" -TabNames $overflowNames -RequireProcess)) "association safe for an oversized suffix"

        $overflowCandidate = [pscustomobject]@{ Hwnd = 23; ExpectedWindowId = $null; ProcessName = "WindowsTerminal.exe"; TabNames = $overflowNames }
        Assert-True ($null -eq (Select-DevWSTerminalHwndCandidate -Candidates @($overflowCandidate) -WindowId "W" -RequireProcess)) "candidate selection safe for an oversized suffix"
    }

    Test-Case "read-only tab snapshot maps configured identity without guessing" {
        function New-P6CSnapEntry {
            param([string]$Name, [bool]$IsSelected = $false)
            return [pscustomobject]@{ Name = $Name; IsSelected = $IsSelected }
        }

        # Three canonical managed tabs; each selection maps to its configured index.
        foreach ($selected in @(0, 1, 2)) {
            $entries = @()
            for ($i = 0; $i -lt 3; $i++) {
                $name = if ($i -eq 0) { "W" } else { "W#DevWS:$i" }
                $entries += (New-P6CSnapEntry -Name $name -IsSelected:($i -eq $selected))
            }

            $snap = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $entries
            Assert-Equal "available" ([string]$snap.Status) "selected visual $selected available"
            Assert-Equal $selected ([int]$snap.SelectedConfiguredTabIndex) "selected visual $selected maps to configured $selected"
            Assert-Equal $selected ([int]$snap.SelectedVisualIndex) "selected visual index reported"
            Assert-Equal 0 @($snap.MissingConfiguredIndexes).Count "nothing missing"
        }

        # Reordered visual order: titles move with the tabs.
        $reordered = @(
            (New-P6CSnapEntry -Name "W#DevWS:2" -IsSelected $true),
            (New-P6CSnapEntry -Name "W"),
            (New-P6CSnapEntry -Name "W#DevWS:1")
        )
        $snapReorder = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $reordered
        Assert-Equal "available" ([string]$snapReorder.Status) "reorder snapshot available"
        Assert-Equal 2 ([int]$snapReorder.SelectedConfiguredTabIndex) "reorder maps by title, not visual index"

        # Missing configured tab 1 while tab 2 is selected.
        $missingEntries = @(
            (New-P6CSnapEntry -Name "W"),
            (New-P6CSnapEntry -Name "W#DevWS:2" -IsSelected $true)
        )
        $snapMissing = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $missingEntries
        Assert-Equal 2 ([int]$snapMissing.SelectedConfiguredTabIndex) "missing tab 1 does not remap tab 2"
        Assert-Equal "1" (@($snapMissing.MissingConfiguredIndexes) -join ",") "missing configured index reported"

        # Extra unmanaged tab: managed selection still maps; unmanaged selection refuses.
        $extraEntries = @(
            (New-P6CSnapEntry -Name "W"),
            (New-P6CSnapEntry -Name "W-manual" -IsSelected $true),
            (New-P6CSnapEntry -Name "W#DevWS:1"),
            (New-P6CSnapEntry -Name "W#DevWS:2")
        )
        $snapExtra = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $extraEntries
        Assert-Equal "selected-unmanaged" ([string]$snapExtra.Status) "unmanaged selection refuses"
        Assert-True ($null -eq $snapExtra.SelectedConfiguredTabIndex) "no guessed index for unmanaged selection"
        Assert-Equal 1 ([int]$snapExtra.UnmanagedTabCount) "unmanaged count"

        $extraSelectedManaged = @(
            (New-P6CSnapEntry -Name "W"),
            (New-P6CSnapEntry -Name "W-manual"),
            (New-P6CSnapEntry -Name "W#DevWS:1" -IsSelected $true),
            (New-P6CSnapEntry -Name "W#DevWS:2")
        )
        $snapExtraManaged = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $extraSelectedManaged
        Assert-Equal "available" ([string]$snapExtraManaged.Status) "managed selection with an extra unmanaged tab still maps"
        Assert-Equal 1 ([int]$snapExtraManaged.SelectedConfiguredTabIndex) "managed index with extra tab"

        # Duplicate canonical index is a structural ambiguity.
        $duplicateEntries = @(
            (New-P6CSnapEntry -Name "W"),
            (New-P6CSnapEntry -Name "W#DevWS:1" -IsSelected $true),
            (New-P6CSnapEntry -Name "W#DevWS:1"),
            (New-P6CSnapEntry -Name "W#DevWS:2")
        )
        $snapDuplicate = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $duplicateEntries
        Assert-Equal "duplicate-managed-index" ([string]$snapDuplicate.Status) "duplicate managed index refuses"

        # Legacy live terminal: every tab is the exact base title.
        $legacyEntries = @(
            (New-P6CSnapEntry -Name "W" -IsSelected $true),
            (New-P6CSnapEntry -Name "W"),
            (New-P6CSnapEntry -Name "W")
        )
        $snapLegacy = Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $legacyEntries
        Assert-Equal "legacy-unmapped" ([string]$snapLegacy.Status) "legacy base-title terminal is unmapped"
        Assert-True ($null -eq $snapLegacy.SelectedConfiguredTabIndex) "legacy selection never guessed"
        Assert-True (Test-DevWSTerminalPresent -PresentTabNames (New-DevWSPresentTabNameSet -Names @("W")) -WindowId "W") "legacy terminal still present"

        # Selection edge cases.
        $noneSelected = @((New-P6CSnapEntry -Name "W"), (New-P6CSnapEntry -Name "W#DevWS:1"))
        Assert-Equal "no-selected-tab" ([string](Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 2 -Entries $noneSelected).Status) "no selected tab"

        $multiSelected = @((New-P6CSnapEntry -Name "W" -IsSelected $true), (New-P6CSnapEntry -Name "W#DevWS:1" -IsSelected $true))
        Assert-Equal "multiple-selected-tabs" ([string](Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 2 -Entries $multiSelected).Status) "multiple selected tabs"

        $outOfRange = @((New-P6CSnapEntry -Name "W#DevWS:5" -IsSelected $true))
        Assert-Equal "selected-out-of-range" ([string](Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $outOfRange).Status) "out-of-range selected index"

        $overflowSelected = @((New-P6CSnapEntry -Name "W#DevWS:999999999999999999999999" -IsSelected $true))
        Assert-Equal "selected-unmanaged" ([string](Resolve-DevWSTerminalTabSnapshot -WindowId "W" -ConfiguredTabCount 3 -Entries $overflowSelected).Status) "oversized selected suffix behaves as unmanaged"

        Assert-Equal "malformed-structure" ([string](Resolve-DevWSTerminalTabSnapshot -WindowId "W" -Entries @()).Status) "empty structure"

        # Read-only proof: the snapshot code never selects or focuses anything.
        $uiaLib = Get-SourceOf "src\lib\devws-uia.ps1"
        $pureStart = $uiaLib.IndexOf("function Resolve-DevWSTerminalTabSnapshot {")
        $hwndStart = $uiaLib.IndexOf("function Get-DevWSTerminalTabSnapshotFromHwnd {")
        Assert-True ($pureStart -ge 0 -and $hwndStart -gt $pureStart) "snapshot functions located"
        $pureRegion = $uiaLib.Substring($pureStart, $hwndStart - $pureStart)
        $hwndRegion = $uiaLib.Substring($hwndStart)
        Assert-NotContains $pureRegion ".Select(" "pure snapshot never selects"
        Assert-NotContains $hwndRegion ".Select(" "snapshot read never selects"
        Assert-NotContains $hwndRegion "SetFocus" "snapshot read never focuses"
        Assert-Contains $hwndRegion "GetCurrentPattern" "selection state is read only"

        # Shared-policy source guard: creation uses the one effective-path and
        # title helper; no duplicated fallback logic.
        $terminalLib = Get-SourceOf "src\lib\devws-terminal.ps1"
        Assert-Contains $terminalLib "Get-DevWSTerminalTabEffectivePath" "creation uses the shared effective-path helper"
        Assert-Contains $terminalLib "Get-DevWSTerminalTabTitle" "creation uses the shared title generator"
    }

    Write-Host ""
    Start-TestGroup -Name 'save-snapshot' -Title 'Managed terminal save snapshots (Pass 6D)'

    function New-P6DSaveTerminal {
        param(
            [string]$Id = "slot",
            [string]$WindowId = "",
            [string]$Path = "C:\old",
            [int]$TabCount = 3,
            [AllowEmptyCollection()][object[]]$TabOverrides = @(),
            [int]$ActiveTab = 0,
            [switch]$HashtableTabs
        )

        if ([string]::IsNullOrWhiteSpace($WindowId)) { $WindowId = "DevWS-P6D-$Id" }

        $tabs = @()

        for ($i = 0; $i -lt $TabCount; $i++) {
            $override = $null
            if ($i -lt @($TabOverrides).Count) { $override = $TabOverrides[$i] }

            if ($HashtableTabs) {
                $tab = [ordered]@{ command = $null; args = @() }
                if ($null -ne $override) { $tab["path"] = $override }
                $tabs += $tab
            }
            else {
                $tab = [pscustomobject]@{ command = $null; args = @() }
                if ($null -ne $override) { $tab | Add-Member -NotePropertyName "path" -NotePropertyValue $override }
                $tabs += $tab
            }
        }

        return [pscustomobject]@{
            id        = $Id
            type      = "terminal"
            enabled   = $true
            windowId  = $WindowId
            path      = $Path
            elevated  = $true
            tabs      = @($tabs)
            activeTab = $ActiveTab
            layout    = [pscustomobject]@{ x = 0; y = 1; w = 100; h = 101 }
        }
    }

    function New-P6DTabDecision {
        param(
            [int]$TabIndex = 0,
            [bool]$HadOverride = $false,
            [AllowNull()][string]$OldExplicitPath = $null,
            [string]$OldEffective = "C:\old",
            [string]$Status = "available",
            [string]$Reason = "ok",
            [AllowNull()][string]$NewCwd = $null,
            [AllowNull()][string]$SessionId = $null,
            [AllowNull()][string]$WindowId = $null
        )

        if ($Status -eq "available") {
            if ($null -eq $NewCwd) { $NewCwd = "C:\new" }
            if ($null -eq $SessionId) { $SessionId = "S1" }
            if ($null -eq $WindowId) { $WindowId = "DevWS-P6D-slot" }
        }

        return [pscustomobject]@{
            terminalId      = "slot"
            tabIndex        = $TabIndex
            hadOverride     = $HadOverride
            oldExplicitPath = $OldExplicitPath
            oldEffective    = $OldEffective
            status          = $Status
            reason          = $Reason
            newCwd          = $NewCwd
            sessionId       = $SessionId
            windowId        = $WindowId
        }
    }

    function Test-P6DTabHasPath {
        param($Terminal, [int]$TabIndex)

        $tab = @($Terminal.tabs)[$TabIndex]

        if ($null -eq $tab) { return $false }
        if ($tab -is [System.Collections.IDictionary]) { return [bool]$tab.Contains("path") }

        return ($null -ne $tab.PSObject.Properties["path"])
    }

    function Get-P6DTabPathValue {
        param($Terminal, [int]$TabIndex)

        $tab = @($Terminal.tabs)[$TabIndex]

        if ($null -eq $tab) { return $null }

        if ($tab -is [System.Collections.IDictionary]) {
            if ($tab.Contains("path")) { return [string]$tab["path"] }
            return $null
        }

        if ($null -ne $tab.PSObject.Properties["path"]) { return [string]$tab.path }

        return $null
    }

    function Assert-P6DEffectiveInvariant {
        param($Terminal, [object[]]$Desired)

        for ($i = 0; $i -lt @($Desired).Count; $i++) {
            Assert-Equal ([string]$Desired[$i]) ([string](Get-DevWSTerminalTabEffectivePath -Terminal $Terminal -TabIndex $i)) "effective path invariant for tab $i"
        }
    }

    function New-P6DSaveConfig {
        param([string]$Name, [object[]]$Terminals)

        $dir = Join-Path $TestRoot $Name
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $target = Join-Path $dir "workspace.json"

        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main" -Windows $Terminals))
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

        return $target
    }

    Test-Case "Pass 6D shared expected-generation validator keeps the reason vocabulary" {
        $cases = @(
            @{ Name = "missing-read";    Record = $null; ReadError = "missing";    TabIndex = 0; Expect = "expected-missing" },
            @{ Name = "unreadable-read"; Record = $null; ReadError = "unreadable"; TabIndex = 0; Expect = "expected-unreadable" },
            @{ Name = "malformed-read";  Record = $null; ReadError = "malformed";  TabIndex = 0; Expect = "expected-malformed" },
            @{ Name = "empty-read";      Record = $null; ReadError = "empty";      TabIndex = 0; Expect = "expected-empty" },
            @{ Name = "version";         Record = ([ordered]@{ version = 2; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }); ReadError = ""; TabIndex = 0; Expect = "expected-version" },
            @{ Name = "schema-window";   Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = " "; sessionId = "S1" }); ReadError = ""; TabIndex = 0; Expect = "expected-schema" },
            @{ Name = "schema-session";  Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "" }); ReadError = ""; TabIndex = 0; Expect = "expected-schema" },
            @{ Name = "set";             Record = ([ordered]@{ version = 1; setId = "other"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }); ReadError = ""; TabIndex = 0; Expect = "set-mismatch" },
            @{ Name = "terminal";        Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "other"; windowId = "DevWS-slot"; sessionId = "S1" }); ReadError = ""; TabIndex = 0; Expect = "terminal-mismatch" },
            @{ Name = "tab0-nonzero";    Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 3 }); ReadError = ""; TabIndex = 0; Expect = "tab-mismatch" },
            @{ Name = "tab0-zero";       Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 0 }); ReadError = ""; TabIndex = 0; Ok = $true },
            @{ Name = "tab0-empty";      Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = "" }); ReadError = ""; TabIndex = 0; Ok = $true },
            @{ Name = "tab0-missing";    Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }); ReadError = ""; TabIndex = 0; Ok = $true },
            @{ Name = "indexed-exact";   Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 2 }); ReadError = ""; TabIndex = 2; Ok = $true },
            @{ Name = "indexed-missing"; Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }); ReadError = ""; TabIndex = 2; Expect = "tab-mismatch" },
            @{ Name = "indexed-wrong";   Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 1 }); ReadError = ""; TabIndex = 2; Expect = "tab-mismatch" },
            @{ Name = "accepted-session"; Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S9" }); ReadError = ""; TabIndex = 0; AcceptedSession = "S1"; Expect = "session-mismatch" },
            @{ Name = "accepted-window";  Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-other"; sessionId = "S1" }); ReadError = ""; TabIndex = 0; AcceptedWindow = "DevWS-slot"; Expect = "window-mismatch" },
            @{ Name = "accepted-ok";      Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }); ReadError = ""; TabIndex = 0; AcceptedSession = "S1"; AcceptedWindow = "DevWS-slot"; Ok = $true }
        )

        foreach ($case in $cases) {
            $arguments = @{
                Expected          = $case.Record
                ExpectedReadError = [string]$case.ReadError
                SetId             = "main"
                TerminalId        = "slot"
                TabIndex          = [int]$case.TabIndex
            }

            if ($case.ContainsKey("AcceptedSession")) { $arguments["ExpectedSessionId"] = [string]$case.AcceptedSession }
            if ($case.ContainsKey("AcceptedWindow"))  { $arguments["ExpectedWindowId"]  = [string]$case.AcceptedWindow }

            $result = Test-DevWSCwdExpectedGeneration @arguments

            if ($case.ContainsKey("Expect")) {
                Assert-Equal $false ([bool]$result.Ok) "rejects: $($case.Name)"
                Assert-Equal ([string]$case.Expect) ([string]$result.Reason) "reason: $($case.Name)"
            }
            else {
                Assert-Equal $true ([bool]$result.Ok) "accepts: $($case.Name)"
                Assert-Equal "ok" ([string]$result.Reason) "ok reason: $($case.Name)"
            }
        }
    }

    Test-Case "Pass 6D validator split preserves pair and tab-wrapper semantics" {
        # Plain pair validation keeps ignoring tabIndex (historical behavior).
        $indexed = [ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 7 }

        $plain = Test-DevWSCwdRecordPair -Expected $indexed -Publication $null -PublicationReadError "missing" -SetId "main" -TerminalId "slot"
        Assert-Equal "publication-missing" ([string]$plain.Reason) "plain pair ignores tabIndex"

        # The tab wrapper enforces configured-tab identity.
        $tabbed = Test-DevWSCwdTabRecordPair -Expected $indexed -Publication $null -PublicationReadError "missing" -SetId "main" -TerminalId "slot" -TabIndex 0
        Assert-Equal "tab-mismatch" ([string]$tabbed.Reason) "tab 0 rejects a non-zero tabIndex"

        # Tab identity keeps precedence over the version check (historical order).
        $badTabAndVersion = [ordered]@{ version = 2; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 9 }
        $precedence = Test-DevWSCwdTabRecordPair -Expected $badTabAndVersion -SetId "main" -TerminalId "slot" -TabIndex 2
        Assert-Equal "tab-mismatch" ([string]$precedence.Reason) "tab identity precedes version"

        # Missing records are still reported by the read status, never as a tab mismatch.
        $missing = Test-DevWSCwdTabRecordPair -Expected $null -ExpectedReadError "missing" -SetId "main" -TerminalId "slot" -TabIndex 2
        Assert-Equal "expected-missing" ([string]$missing.Reason) "missing expected stays expected-missing"

        # The shared validator reproduces the wrapper's expected-side rules exactly.
        $expectedCases = @(
            @{ Record = $indexed; TabIndex = 0; Reason = "tab-mismatch" },
            @{ Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1"; tabIndex = 2 }); TabIndex = 2; Reason = "ok" },
            @{ Record = ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S1" }); TabIndex = 2; Reason = "tab-mismatch" }
        )

        foreach ($case in $expectedCases) {
            $check = Test-DevWSCwdExpectedGeneration -Expected $case.Record -SetId "main" -TerminalId "slot" -TabIndex $case.TabIndex
            Assert-Equal ([string]$case.Reason) ([string]$check.Reason) "shared expected-side parity"
        }
    }

    Test-Case "Pass 6D indexed resolver behavior is explicit and unchanged" {
        $stateRoot  = Join-Path $TestRoot "p6d-resolver-indexed"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = $stateRoot

        try {
            $cwdDir = Join-Path $TestRoot "p6d-resolver-indexed-cwd"
            New-Item -ItemType Directory -Path $cwdDir -Force | Out-Null
            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            function Write-P6DResolution {
                param([int]$TabIndex, [string]$SessionId, [int]$PublicationTabIndex, [bool]$WriteExpected)

                $expectedPath    = Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot" -TabIndex $TabIndex
                $publicationPath = Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot" -TabIndex $TabIndex

                if ($WriteExpected) {
                    $record = [ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = $SessionId }
                    if ($TabIndex -gt 0) { $record["tabIndex"] = $TabIndex }
                    Write-DevWSCwdSessionRecord -Path $expectedPath -Record $record
                }
                else {
                    Remove-Item -LiteralPath $expectedPath -Force -ErrorAction SilentlyContinue
                }

                $publication = [ordered]@{
                    version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = $SessionId
                    cwd = $cwdDir; shellPid = $PID; shellStartTimeUtc = $startIso
                    updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
                }

                if ($PublicationTabIndex -ge 0) { $publication["tabIndex"] = $PublicationTabIndex }
                if ($TabIndex -gt 0) { $publication["tabIndex"] = $PublicationTabIndex }

                Write-DevWSCwdPublication -Path $publicationPath -Record $publication
            }

            # Indexed tab 2: exact match resolves available.
            Write-P6DResolution -TabIndex 2 -SessionId "S2" -PublicationTabIndex 2 -WriteExpected $true
            $resolution = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot" -TabIndex 2
            Assert-Equal "available" ([string]$resolution.Status) "indexed tab resolves available"
            Assert-Equal $cwdDir ([string]$resolution.cwd) "indexed cwd"

            # Wrong publication tabIndex is rejected.
            Write-P6DResolution -TabIndex 2 -SessionId "S2" -PublicationTabIndex 3 -WriteExpected $true
            Assert-Equal "tab-mismatch" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot" -TabIndex 2).Reason) "publication tabIndex must match"

            # Missing expected indexed record.
            Write-P6DResolution -TabIndex 2 -SessionId "S2" -PublicationTabIndex 2 -WriteExpected $false
            Assert-Equal "expected-missing" ([string](Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot" -TabIndex 2).Reason) "missing indexed generation"

            # Tab 0 keeps the legacy terminal-level paths and record shape.
            $legacyExpected    = Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot"
            $legacyPublication = Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot"

            Write-DevWSCwdSessionRecord -Path $legacyExpected -Record ([ordered]@{ version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S0" })
            Write-DevWSCwdPublication -Path $legacyPublication -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-slot"; sessionId = "S0"
                cwd = $cwdDir; shellPid = $PID; shellStartTimeUtc = $startIso; updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            $legacy = Resolve-DevWSTrackedCwd -SetId "main" -TerminalId "slot"
            Assert-Equal "available" ([string]$legacy.Status) "tab 0 legacy shape resolves available"
            Assert-True ($legacyExpected -like "*\slot.json") "tab 0 keeps the historical terminal-level path"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Pass 6D per-tab decisions resolve every configured tab independently" {
        $stateRoot  = Join-Path $TestRoot "p6d-decisions-state"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = $stateRoot

        try {
            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            $cwds = @{}
            foreach ($name in @("d0", "d1", "d2", "other")) {
                $path = Join-Path $TestRoot "p6d-decisions-$name"
                New-Item -ItemType Directory -Path $path -Force | Out-Null
                $cwds[$name] = $path
            }

            function Write-P6DDecisionState {
                param([string]$SetId, [int]$TabIndex, [string]$SessionId, [string]$Cwd, [bool]$WithExpected = $true, [bool]$WithPublication = $true)

                $expectedPath    = Get-DevWSCwdSessionPath -SetId $SetId -TerminalId "slot" -TabIndex $TabIndex
                $publicationPath = Get-DevWSCwdPublicationPath -SetId $SetId -TerminalId "slot" -TabIndex $TabIndex

                if ($WithExpected) {
                    $record = [ordered]@{ version = 1; setId = $SetId; terminalId = "slot"; windowId = "DevWS-P6D-slot"; sessionId = $SessionId }
                    if ($TabIndex -gt 0) { $record["tabIndex"] = $TabIndex }
                    Write-DevWSCwdSessionRecord -Path $expectedPath -Record $record
                }
                else {
                    Remove-Item -LiteralPath $expectedPath -Force -ErrorAction SilentlyContinue
                }

                if ($WithPublication) {
                    $publication = [ordered]@{
                        version = 1; setId = $SetId; terminalId = "slot"; windowId = "DevWS-P6D-slot"; sessionId = $SessionId
                        cwd = $Cwd; shellPid = $PID; shellStartTimeUtc = $startIso
                        updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
                    }
                    if ($TabIndex -gt 0) { $publication["tabIndex"] = $TabIndex }
                    Write-DevWSCwdPublication -Path $publicationPath -Record $publication
                }
                else {
                    Remove-Item -LiteralPath $publicationPath -Force -ErrorAction SilentlyContinue
                }
            }

            Write-P6DDecisionState -SetId "main" -TabIndex 0 -SessionId "D0" -Cwd $cwds["d0"]
            Write-P6DDecisionState -SetId "main" -TabIndex 1 -SessionId "D1" -Cwd $cwds["d1"]
            Write-P6DDecisionState -SetId "main" -TabIndex 2 -SessionId "D2" -Cwd $cwds["d2"]

            # An unrelated set has state for the same id; it must be ignored.
            Write-P6DDecisionState -SetId "other" -TabIndex 0 -SessionId "X0" -Cwd $cwds["other"]

            $terminal = New-P6DSaveTerminal -Path "C:\old" -TabCount 3 -TabOverrides @($null, "C:\override1", $null)

            $decisions = Get-DevWSTerminalSaveDecisions -SetId "main" -Terminals @($terminal)
            $perTab = @($decisions["slot"])
            Assert-Equal 3 $perTab.Count "one decision per configured tab"

            Assert-Equal "available" ([string]$perTab[0].status) "tab 0 available"
            Assert-Equal $cwds["d0"] ([string]$perTab[0].newCwd) "tab 0 cwd comes from main-set state"
            Assert-Equal "C:\old" ([string]$perTab[0].oldEffective) "tab 0 inherits terminal.path"
            Assert-Equal $false ([bool]$perTab[0].hadOverride) "tab 0 has no override"
            Assert-Equal "D0" ([string]$perTab[0].sessionId) "tab 0 session"
            Assert-Equal "DevWS-P6D-slot" ([string]$perTab[0].windowId) "tab 0 windowId"

            Assert-Equal "available" ([string]$perTab[1].status) "tab 1 available"
            Assert-Equal $cwds["d1"] ([string]$perTab[1].newCwd) "tab 1 cwd"
            Assert-Equal $true ([bool]$perTab[1].hadOverride) "tab 1 override detected"
            Assert-Equal "C:\override1" ([string]$perTab[1].oldExplicitPath) "tab 1 explicit value captured"
            Assert-Equal "C:\override1" ([string]$perTab[1].oldEffective) "tab 1 override wins the effective path"

            Assert-Equal "available" ([string]$perTab[2].status) "tab 2 available"
            Assert-Equal $cwds["d2"] ([string]$perTab[2].newCwd) "tab 2 cwd"
            Assert-Equal "C:\old" ([string]$perTab[2].oldEffective) "tab 2 inherits terminal.path"

            # A broken tab-1 publication downgrades only that tab.
            Write-P6DDecisionState -SetId "main" -TabIndex 1 -SessionId "D1" -Cwd $cwds["d1"] -WithPublication $false
            $decisions = Get-DevWSTerminalSaveDecisions -SetId "main" -Terminals @($terminal)
            $perTab = @($decisions["slot"])
            Assert-Equal "available" ([string]$perTab[0].status) "sibling tab 0 unaffected"
            Assert-Equal "unavailable" ([string]$perTab[1].status) "missing publication downgrades only tab 1"
            Assert-Equal "publication-missing" ([string]$perTab[1].reason) "tab 1 reason"
            Assert-Equal "available" ([string]$perTab[2].status) "sibling tab 2 unaffected"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Pass 6D decisions enumerate configured tabs of enabled terminals only" {
        $script:p6dDecisionCalls = [System.Collections.Generic.List[string]]::new()

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)
            $script:p6dDecisionCalls.Add("$SetId/$TerminalId#$TabIndex") | Out-Null
            return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null; SessionId = $null; WindowId = $null }
        }

        $alpha = New-P6DSaveTerminal -Id "alpha" -TabCount 2
        $beta  = New-P6DSaveTerminal -Id "beta" -TabCount 1

        $decisions = Get-DevWSTerminalSaveDecisions -SetId "main" -Terminals @($alpha, $beta)

        Assert-Equal "main/alpha#0,main/alpha#1,main/beta#0" ($script:p6dDecisionCalls -join ",") "configured order, every tab, target set only"
        Assert-Equal 2 (@($decisions["alpha"]).Count) "alpha decisions"
        Assert-Equal 1 (@($decisions["beta"]).Count) "beta decisions"
        Assert-Equal $false ([bool]$decisions["alpha"][0].hadOverride) "no override detected"
        Assert-Equal "C:\old" ([string]$decisions["alpha"][0].oldEffective) "inherited effective path"
    }

    Test-Case "Pass 6D path encoding matrix preserves every effective path" {
        # Case A: tab 0 reliable, inherited sibling unavailable.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -OldEffective "C:\A" -NewCwd "C:\X"),
            (New-P6DTabDecision -TabIndex 1 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A")
        )
        Assert-Equal "C:\X" $terminal.path "A: fallback tracks live tab 0"
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 0) "A: tab 0 stays absent"
        Assert-Equal "C:\A" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 1) "A: sibling materialized"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\X", "C:\A")

        # Case B: nothing reliable; structure unchanged.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2 -TabOverrides @("C:\B", $null)
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -HadOverride $true -OldExplicitPath "C:\B" -OldEffective "C:\B" -Status "unavailable" -Reason "shell-dead"),
            (New-P6DTabDecision -TabIndex 1 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A")
        )
        Assert-Equal "C:\A" $terminal.path "B: fallback unchanged"
        Assert-Equal "C:\B" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 0) "B: explicit override preserved"
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 1) "B: absent sibling stays absent"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\B", "C:\A")

        # Case C: reliable tab 0 with an explicit override; sibling materializes.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2 -TabOverrides @("C:\B", $null)
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -HadOverride $true -OldExplicitPath "C:\B" -OldEffective "C:\B" -NewCwd "C:\X"),
            (New-P6DTabDecision -TabIndex 1 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A")
        )
        Assert-Equal "C:\X" $terminal.path "C: fallback tracks live tab 0"
        Assert-Equal "C:\X" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 0) "C: explicit override updated"
        Assert-Equal "C:\A" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 1) "C: sibling materialized"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\X", "C:\A")

        # Case D: only a sibling is reliable.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 1 -NewCwd "C:\Y" -OldEffective "C:\A")
        )
        Assert-Equal "C:\A" $terminal.path "D: fallback preserved"
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 0) "D: tab 0 stays absent"
        Assert-Equal "C:\Y" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 1) "D: sibling materializes its live cwd"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\A", "C:\Y")

        # Case E: a redundant explicit override is never normalized away.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2 -TabOverrides @($null, "C:\A")
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 1 -HadOverride $true -OldExplicitPath "C:\A" -OldEffective "C:\A" -Status "unavailable" -Reason "shell-dead")
        )
        Assert-True (Test-P6DTabHasPath -Terminal $terminal -TabIndex 1) "E: override property stays present"
        Assert-Equal "C:\A" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 1) "E: explicit equal override retained"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\A", "C:\A")

        # A reliable sibling equal to the resulting fallback stays absent.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 1 -NewCwd "C:\A" -OldEffective "C:\A")
        )
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 1) "equal reliable sibling stays absent"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\A", "C:\A")

        # A reliable explicit sibling keeps explicit intent even when equal.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2 -TabOverrides @($null, "C:\B")
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -NewCwd "C:\P" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 1 -HadOverride $true -OldExplicitPath "C:\B" -OldEffective "C:\B" -NewCwd "C:\P")
        )
        Assert-True (Test-P6DTabHasPath -Terminal $terminal -TabIndex 1) "explicit intent retained when equal to fallback"
        Assert-Equal "C:\P" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 1) "explicit value updated to the live cwd"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\P", "C:\P")

        # Multiple siblings materialize independently.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 4
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -NewCwd "C:\X" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 1 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 2 -Status "unavailable" -Reason "shell-dead" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 3 -NewCwd "C:\X" -OldEffective "C:\A")
        )
        Assert-Equal "C:\A" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 1) "multi: sibling 1 materialized"
        Assert-Equal "C:\A" (Get-P6DTabPathValue -Terminal $terminal -TabIndex 2) "multi: sibling 2 materialized"
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 3) "multi: equal reliable sibling stays absent"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\X", "C:\A", "C:\A", "C:\X")

        # Hashtable tab definitions take the dictionary path.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2 -HashtableTabs
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 0 -NewCwd "C:\X" -OldEffective "C:\A"),
            (New-P6DTabDecision -TabIndex 1 -Status "unavailable" -Reason "expected-missing" -OldEffective "C:\A")
        )
        Assert-Equal "C:\X" $terminal.path "hashtable: fallback tracks live tab 0"
        Assert-Equal "C:\A" ([string]@($terminal.tabs)[1]["path"]) "hashtable: sibling materialized"
        Assert-P6DEffectiveInvariant -Terminal $terminal -Desired @("C:\X", "C:\A")

        # No tab-0 decision: the planner never guesses.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @(
            (New-P6DTabDecision -TabIndex 1 -NewCwd "C:\Y" -OldEffective "C:\A")
        )
        Assert-Equal "C:\A" $terminal.path "missing tab-0 decision leaves the fallback"
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 1) "missing tab-0 decision leaves siblings"

        # No decisions at all: nothing happens.
        $terminal = New-P6DSaveTerminal -Path "C:\A" -TabCount 2
        Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions @()
        Assert-Equal "C:\A" $terminal.path "empty decisions leave the fallback"
        Assert-Equal $false (Test-P6DTabHasPath -Terminal $terminal -TabIndex 0) "empty decisions leave tab 0 absent"
    }

    Test-Case "Pass 6D final generation gate downgrades only the affected tab" {
        $stateRoot  = Join-Path $TestRoot "p6d-gate-state"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = $stateRoot

        function New-P6DGateDecision {
            param([int]$TabIndex = 0, [string]$SessionId = "S1", [string]$WindowId = "DevWS-P6D-slot")

            return [pscustomobject]@{
                terminalId      = "slot"
                tabIndex        = $TabIndex
                hadOverride     = $false
                oldExplicitPath = $null
                oldEffective    = "C:\old"
                status          = "available"
                reason          = "ok"
                newCwd          = "C:\new"
                sessionId       = $SessionId
                windowId        = $WindowId
            }
        }

        function Write-P6DGateExpected {
            param([int]$TabIndex = 0, [switch]$OmitTabIndex, [hashtable]$Mutate = @{})

            $record = [ordered]@{
                version    = 1
                setId      = "main"
                terminalId = "slot"
                windowId   = "DevWS-P6D-slot"
                sessionId  = "S1"
            }

            if ($TabIndex -gt 0 -and -not $OmitTabIndex) { $record["tabIndex"] = $TabIndex }
            foreach ($key in $Mutate.Keys) { $record[$key] = $Mutate[$key] }

            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot" -TabIndex $TabIndex) -Record $record
        }

        function Invoke-P6DGate {
            param([object[]]$TabDecisions)

            $decisions = [ordered]@{ slot = @($TabDecisions) }
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions $decisions

            return $decisions["slot"]
        }

        try {
            # Unchanged valid generation stays available.
            Write-P6DGateExpected
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "available" ([string]$result[0].status) "valid generation stays available"
            Assert-Equal "C:\new" ([string]$result[0].newCwd) "valid generation keeps the cwd"

            # T1 -> T2 race: downgraded with a precise reason.
            Write-P6DGateExpected -Mutate @{ sessionId = "T2" }
            $result = Invoke-P6DGate @((New-P6DGateDecision -SessionId "T1"))
            Assert-Equal "unavailable" ([string]$result[0].status) "advanced generation downgraded"
            Assert-Equal "session-mismatch" ([string]$result[0].reason) "advanced generation reason"
            Assert-True ($null -eq $result[0].newCwd) "advanced generation drops the live cwd"

            # Missing generation.
            Remove-Item -LiteralPath (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot") -Force
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "expected-missing" ([string]$result[0].reason) "missing generation"

            # Malformed generation.
            New-Item -ItemType Directory -Path (Split-Path -Parent (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot")) -Force | Out-Null
            [System.IO.File]::WriteAllText((Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot"), "{ not json", [System.Text.UTF8Encoding]::new($false))
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "expected-malformed" ([string]$result[0].reason) "malformed generation"

            # Same session, wrong structure/identity (unreadable is proven at
            # the validator level: a directory or IO failure never yields a
            # record, and every failure mode maps to its stable reason there).
            Write-P6DGateExpected -Mutate @{ version = 2 }
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "expected-version" ([string]$result[0].reason) "wrong version (same session)"

            Write-P6DGateExpected -Mutate @{ setId = "other" }
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "set-mismatch" ([string]$result[0].reason) "wrong set (same session)"

            Write-P6DGateExpected -Mutate @{ terminalId = "other" }
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "terminal-mismatch" ([string]$result[0].reason) "wrong terminal (same session)"

            Write-P6DGateExpected -Mutate @{ windowId = "DevWS-other" }
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "window-mismatch" ([string]$result[0].reason) "wrong window (same session)"

            # Indexed tabs require exact tab identity.
            Write-P6DGateExpected -TabIndex 2
            $result = Invoke-P6DGate @((New-P6DGateDecision -TabIndex 2))
            Assert-Equal "available" ([string]$result[0].status) "indexed identity matches"

            Write-P6DGateExpected -TabIndex 2 -OmitTabIndex
            $result = Invoke-P6DGate @((New-P6DGateDecision -TabIndex 2))
            Assert-Equal "tab-mismatch" ([string]$result[0].reason) "indexed missing tabIndex"

            Write-P6DGateExpected -TabIndex 2 -Mutate @{ tabIndex = 1 }
            $result = Invoke-P6DGate @((New-P6DGateDecision -TabIndex 2))
            Assert-Equal "tab-mismatch" ([string]$result[0].reason) "indexed wrong tabIndex"

            # Tab 0 accepts missing/empty/zero and rejects non-zero.
            Write-P6DGateExpected -OmitTabIndex
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "available" ([string]$result[0].status) "tab 0 missing tabIndex accepted"

            Write-P6DGateExpected -Mutate @{ tabIndex = 0 }
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "available" ([string]$result[0].status) "tab 0 explicit zero accepted"

            Write-P6DGateExpected -Mutate @{ tabIndex = 1 }
            $result = Invoke-P6DGate @((New-P6DGateDecision))
            Assert-Equal "tab-mismatch" ([string]$result[0].reason) "tab 0 non-zero rejected"

            # Per-tab independence: a missing indexed sibling never downgrades
            # or re-reads the valid tab 0 decision.
            Remove-Item -LiteralPath (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot" -TabIndex 1) -Force -ErrorAction SilentlyContinue
            Write-P6DGateExpected -OmitTabIndex
            $result = Invoke-P6DGate @(
                (New-P6DGateDecision),
                (New-P6DGateDecision -TabIndex 1 -SessionId "Q1")
            )
            Assert-Equal "available" ([string]$result[0].status) "tab 0 unaffected by a broken sibling"
            Assert-Equal "unavailable" ([string]$result[1].status) "missing indexed sibling downgraded"
            Assert-Equal "expected-missing" ([string]$result[1].reason) "missing indexed sibling reason"

            # And the reverse: a broken tab 0 never downgrades the indexed sibling.
            Remove-Item -LiteralPath (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot") -Force -ErrorAction SilentlyContinue
            Write-P6DGateExpected -TabIndex 1
            $result = Invoke-P6DGate @(
                (New-P6DGateDecision),
                (New-P6DGateDecision -TabIndex 1)
            )
            Assert-Equal "unavailable" ([string]$result[0].status) "broken tab 0 downgraded"
            Assert-Equal "available" ([string]$result[1].status) "indexed sibling unaffected"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Pass 6D activeTab correlation fails closed" {
        $terminal = New-P6DSaveTerminal -TabCount 3

        function New-P6DMap {
            param([hashtable]$Entries, [object]$DuplicateKey = $null)

            $map = [System.Collections.Hashtable]::new([System.StringComparer]::OrdinalIgnoreCase)

            foreach ($key in $Entries.Keys) { $map[$key] = $Entries[$key] }
            if ($null -ne $DuplicateKey) { $map[$DuplicateKey] = $null }

            return $map
        }

        function New-P6DEntry {
            param($WindowId = "DevWS-P6D-slot", $Status = "available", $Index = 2)

            return [pscustomobject]@{ id = "slot"; windowId = $WindowId; status = $Status; selectedConfiguredTabIndex = $Index }
        }

        # Valid available observation (a configured sibling may be missing live).
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Index 2) }
        $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
        Assert-Equal $true ([bool]$decision.Update) "available observation updates"
        Assert-Equal 2 ([int]$decision.Index) "configured index carried"

        # Case-insensitive window identity.
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -WindowId "devws-p6d-SLOT" -Index 1) }
        Assert-Equal $true ([bool](Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map).Update) "windowId comparison is case-insensitive"

        # Every non-available status preserves the old value.
        foreach ($status in @("selected-unmanaged", "selected-out-of-range", "legacy-unmapped", "duplicate-managed-index", "no-selected-tab", "multiple-selected-tabs", "malformed-structure", "hwnd-unavailable", "locator-active", "AVAILABLE")) {
            $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Status $status -Index $null) }
            $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
            Assert-Equal $false ([bool]$decision.Update) "status preserves: $status"
            Assert-Equal $status ([string]$decision.Reason) "status reason: $status"
        }

        # Duplicate records fail closed; never first-wins or last-wins.
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Index 2) } -DuplicateKey "slot"
        $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
        Assert-Equal $false ([bool]$decision.Update) "duplicate record refused"
        Assert-Equal "duplicate-record" ([string]$decision.Reason) "duplicate reason"

        # Wrong window, missing terminal record, absent map.
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -WindowId "DevWS-other") }
        Assert-Equal "window-mismatch" ([string](Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map).Reason) "wrong windowId"

        $map = New-P6DMap -Entries @{ other = (New-P6DEntry) }
        Assert-Equal "no-observation" ([string](Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map).Reason) "missing terminal record"

        Assert-Equal "no-observation" ([string](Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $null).Reason) "absent map"

        # Index shapes fail closed, including arbitrarily large integers.
        foreach ($bad in @($null, "abc", 2.5, -1, 3, 99, [long]::MaxValue, ([System.Numerics.BigInteger]::Parse("99999999999999999999")))) {
            $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Index $bad) }
            $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
            Assert-Equal $false ([bool]$decision.Update) ("index refused: " + [string]$bad)
        }

        # The selected index must be a GENUINE integer: every coercible form
        # (numeric strings, sign/space/zero-padding variants, a floating 2.0,
        # booleans) is rejected and the old activeTab is preserved.
        foreach ($coercible in @("2", "0", "+2", " 2 ", "02", [double]2.0, [single]2.0, $true, $false)) {
            $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Index $coercible) }
            $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
            Assert-Equal $false ([bool]$decision.Update) ("coercible index refused: " + [string]$coercible)
            Assert-Equal "selected-index-invalid" ([string]$decision.Reason) ("coercible index reason: " + [string]$coercible)
        }

        # Huge genuine integers are range-checked on the wide value, never
        # narrowed blindly.
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Index ([long]::MaxValue)) }
        Assert-Equal "selected-index-out-of-range" ([string](Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map).Reason) "huge integer is out of range"

        # Record identity/status fields must be genuine strings; coerced values
        # never become a configured identity.
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -WindowId 5) }
        $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
        Assert-Equal $false ([bool]$decision.Update) "numeric windowId refused"
        Assert-Equal "malformed-record" ([string]$decision.Reason) "numeric windowId reason"

        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Status 5) }
        $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map
        Assert-Equal $false ([bool]$decision.Update) "non-string status refused"
        Assert-Equal "malformed-record" ([string]$decision.Reason) "non-string status reason"

        # Unknown status token.
        $map = New-P6DMap -Entries @{ slot = (New-P6DEntry -Status "") }
        Assert-Equal "unknown-status" ([string](Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminal -SnapshotMap $map).Reason) "blank status token"
    }

    Test-Case "Pass 6D snapshot sidecar reader is tolerant and fail-closed" {
        $dir = Join-Path $TestRoot "p6d-sidecar-reader"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null

        function Write-P6DSidecar {
            param([string]$Name, [string]$Raw)

            $path = Join-Path $dir $Name
            [System.IO.File]::WriteAllText($path, $Raw, [System.Text.UTF8Encoding]::new($false))

            return $path
        }

        # Missing file / empty file / malformed JSON.
        $map = Read-DevWSTabSnapshotFile -Path (Join-Path $dir "absent.json")
        Assert-Equal 0 $map.Count "missing file yields no observations"

        $path = Write-P6DSidecar -Name "empty.json" -Raw ""
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "empty file yields no observations"

        $path = Write-P6DSidecar -Name "malformed.json" -Raw "{ not json"
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "malformed JSON yields no observations"

        # Unsupported version / wrong top-level shapes.
        $path = Write-P6DSidecar -Name "version.json" -Raw '{"version":2,"terminals":[]}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "unsupported version yields no observations"

        $path = Write-P6DSidecar -Name "scalar.json" -Raw '42'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "scalar top level yields no observations"

        $path = Write-P6DSidecar -Name "array.json" -Raw '[{"id":"slot"}]'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "array top level yields no observations"

        $path = Write-P6DSidecar -Name "terminals-scalar.json" -Raw '{"version":1,"terminals":5}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "non-array terminals yields no observations"

        # The shape is validated strictly, never coerced: the version must be
        # the genuine integer 1 and terminals must be an actual JSON array (a
        # single object is not an implicit one-element array).
        $path = Write-P6DSidecar -Name "version-string.json" -Raw '{"version":"1","terminals":[]}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "string version yields no observations"

        $path = Write-P6DSidecar -Name "version-float.json" -Raw '{"version":1.0,"terminals":[]}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "floating version yields no observations"

        $path = Write-P6DSidecar -Name "terminals-object.json" -Raw '{"version":1,"terminals":{"id":"slot","windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":2}}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "object-valued terminals is never an implicit one-element array"

        $path = Write-P6DSidecar -Name "terminals-string.json" -Raw '{"version":1,"terminals":"bad"}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "string terminals yields no observations"

        $path = Write-P6DSidecar -Name "terminals-null.json" -Raw '{"version":1,"terminals":null}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "null terminals yields no observations"

        $path = Write-P6DSidecar -Name "terminals-empty.json" -Raw '{"version":1,"terminals":[]}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "empty genuine array is accepted"

        # A numeric id is never a terminal identity.
        $path = Write-P6DSidecar -Name "numeric-id.json" -Raw '{"version":1,"terminals":[{"id":5,"windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":2}]}'
        Assert-Equal 0 (Read-DevWSTabSnapshotFile -Path $path).Count "numeric id is never a terminal identity"

        # Valid records and case-insensitive lookup.
        $path = Write-P6DSidecar -Name "valid.json" -Raw '{"version":1,"terminals":[{"id":"slot","windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":2}]}'
        $map = Read-DevWSTabSnapshotFile -Path $path
        Assert-Equal 1 $map.Count "valid record parsed"
        Assert-Equal "available" ([string]$map["slot"].status) "record preserved"
        Assert-Equal "available" ([string]$map["SLOT"].status) "lookup is case-insensitive"

        # Entries without an id are skipped; the rest of the file still parses.
        $path = Write-P6DSidecar -Name "mixed.json" -Raw '{"version":1,"terminals":[{"id":"slot","status":"available","selectedConfiguredTabIndex":1},{"status":"available"},{"id":"   "},{"id":"beta","status":"selected-unmanaged"}]}'
        $map = Read-DevWSTabSnapshotFile -Path $path
        Assert-Equal 2 $map.Count "entries without ids are skipped"
        Assert-Equal "available" ([string]$map["slot"].status) "first valid entry kept"
        Assert-Equal "selected-unmanaged" ([string]$map["beta"].status) "second id parsed"

        # A malformed sibling never hides a valid record; numeric ids are
        # skipped, not coerced.
        $path = Write-P6DSidecar -Name "mixed-types.json" -Raw '{"version":1,"terminals":[{"id":5,"windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":2},{"id":"slot","windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":2}]}'
        $map = Read-DevWSTabSnapshotFile -Path $path
        Assert-Equal 1 $map.Count "numeric-id sibling does not hide the valid record"
        Assert-Equal "available" ([string]$map["slot"].status) "valid sibling retained"

        # Duplicate ids mark the record invalid (never first/last wins).
        $path = Write-P6DSidecar -Name "duplicate.json" -Raw '{"version":1,"terminals":[{"id":"slot","status":"available","selectedConfiguredTabIndex":1},{"id":"slot","status":"available","selectedConfiguredTabIndex":2}]}'
        $map = Read-DevWSTabSnapshotFile -Path $path
        Assert-True ($map.ContainsKey("slot")) "duplicate id remains keyed"
        Assert-True ($null -eq $map["slot"]) "duplicate id marks the record invalid"
    }

    Test-Case "Pass 6D capture core snapshots before any locator and writes the sidecar" {
        $outDir = Join-Path $TestRoot "p6d-capture-core"
        New-Item -ItemType Directory -Path $outDir -Force | Out-Null
        $outPath = Join-Path $outDir "capture-elevated.txt"
        $snapshotsPath = Join-Path $outDir "capture-elevated.snapshots.json"

        $terminals = @(
            [pscustomobject]@{
                id        = "slot"
                windowId  = "DevWS-P6D-slot"
                activeTab = 0
                tabs      = @([pscustomobject]@{ command = $null; args = @() }, [pscustomobject]@{ command = $null; args = @() })
            }
        )

        $script:p6dCaptureCalls = [System.Collections.Generic.List[string]]::new()

        try {
            # Case 1: the initial identity is present; the snapshot observes that
            # exact HWND before any geometry processing.
            function Resolve-DevWSTerminalHwnd {
                param($WindowId, [string]$SetId, $State, [string]$TerminalId)
                return [pscustomobject]@{ Status = "present"; Hwnd = [long]910000; Source = "state" }
            }
            function Get-DevWSTerminalTabSnapshotFromHwnd {
                param([long]$Hwnd, [string]$WindowId, [int]$ConfiguredTabCount = -1)
                $script:p6dCaptureCalls.Add("snapshot $Hwnd $WindowId $ConfiguredTabCount") | Out-Null
                return [pscustomobject]@{ Status = "available"; SelectedConfiguredTabIndex = 1; MissingConfiguredIndexes = @() }
            }
            function Get-DevWSWindowHwndRect {
                param([long]$Hwnd)
                $script:p6dCaptureCalls.Add("rect $Hwnd") | Out-Null
                return [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4; Valid = $true }
            }
            function Update-DevWSRuntimeTerminal { param([string]$SetId, [string]$Id, [string]$WindowId, $Hwnd, [string]$Path) }

            $message = Invoke-DevWSTerminalCaptureOperation -SetId "main" -Terminals $terminals -State (New-DevWSRuntimeState) -OutputPath $outPath
            Assert-Equal "OK" $message "present capture ok"
            Assert-Equal "snapshot 910000 DevWS-P6D-slot 2,rect 910000" ($script:p6dCaptureCalls -join ",") "snapshot precedes geometry on the exact HWND"

            $snapshots = Read-DevWSTabSnapshotFile -Path $snapshotsPath
            $entry = $snapshots["slot"]
            Assert-True ($null -ne $entry) "sidecar record present"
            Assert-Equal "available" ([string]$entry.status) "sidecar carries the snapshot status"
            Assert-Equal 1 ([int]$entry.selectedConfiguredTabIndex) "sidecar carries the configured index"
            Assert-Equal "DevWS-P6D-slot" ([string]$entry.windowId) "sidecar carries the configured windowId"

            # The produced artifact is consumable by the fail-closed correlator.
            $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminals[0] -SnapshotMap $snapshots
            Assert-Equal $true ([bool]$decision.Update) "correlated snapshot updates activeTab"
            Assert-Equal 1 ([int]$decision.Index) "correlated configured index"

            # Case 2: locator-assisted recovery never snapshots the locator
            # window; the observation stays fail-closed.
            $script:p6dCaptureCalls.Clear()
            $locatorOut = Join-Path $outDir "locator.txt"

            function Resolve-DevWSTerminalHwnd {
                param($WindowId, [string]$SetId, $State, [string]$TerminalId)
                return [pscustomobject]@{ Status = "missing"; Hwnd = 0; Source = "missing" }
            }
            function Find-DevWSTerminalTopLevelHwnd { param([string]$WindowId) return 911000 }
            function Start-DevWSLocator {
                param([string]$WindowId, [int]$TimeoutSeconds = 10)
                $script:p6dCaptureCalls.Add("start $WindowId") | Out-Null
                return [pscustomobject]@{ WindowId = $WindowId; Title = "loc"; Hwnd = 911000; OwnsWindow = $false }
            }
            function Remove-DevWSLocator {
                param($Locator)
                $script:p6dCaptureCalls.Add("remove") | Out-Null
                return [pscustomobject]@{ Removed = $true; Message = "OK" }
            }
            function Select-DevWSTabByIndexFromHwnd {
                param([long]$Hwnd, [int]$Index, [string]$Context)
                $script:p6dCaptureCalls.Add("select $Index") | Out-Null
                return $true
            }

            $message = Invoke-DevWSTerminalCaptureOperation -SetId "main" -Terminals $terminals -State (New-DevWSRuntimeState) -OutputPath $locatorOut
            Assert-Equal "OK" $message "locator capture ok"
            Assert-True (-not (($script:p6dCaptureCalls -join ",").Contains("snapshot"))) "locator path never snapshots"

            $snapshots = Read-DevWSTabSnapshotFile -Path $snapshotsPath
            Assert-Equal "locator-active" ([string]$snapshots["slot"].status) "locator path records locator-active"
            Assert-True ($null -eq $snapshots["slot"].selectedConfiguredTabIndex) "locator-active carries no index"

            $decision = Get-DevWSTerminalActiveTabSaveDecision -Terminal $terminals[0] -SnapshotMap $snapshots
            Assert-Equal $false ([bool]$decision.Update) "locator observation never updates activeTab"
            Assert-Equal "locator-active" ([string]$decision.Reason) "locator-active reason preserved"

            # Source order: the snapshot read precedes any locator creation.
            $core = Get-SourceOf "src\lib\devws-terminal-operations.ps1"
            $snapshotIndex = $core.IndexOf("Get-DevWSTerminalTabSnapshotFromHwnd")
            $locatorIndex  = $core.IndexOf("Start-DevWSLocator")
            Assert-True ($snapshotIndex -ge 0 -and $locatorIndex -gt $snapshotIndex) "snapshot attempt precedes locator creation in source"
        }
        finally {
            Remove-Item -LiteralPath $outPath, $snapshotsPath, (Join-Path $outDir "locator.txt") -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath "$outPath.tmp", "$snapshotsPath.tmp", (Join-Path $outDir "locator.txt.tmp") -Force -ErrorAction SilentlyContinue
        }
    }

    Test-Case "Pass 6D ws save applies per-tab cwd and activeTab in one commit" {
        $dir = Join-Path $TestRoot "p6d-save-e2e"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null

        $slot = [ordered]@{
            id        = "slot"
            type      = "terminal"
            enabled   = $true
            windowId  = "DevWS-P6D-slot"
            path      = "C:\p6d-A"
            elevated  = $true
            tabs      = @(
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = $null; args = @() }
            )
            activeTab = 0
            layout    = [ordered]@{ x = 1; y = 2; w = 3; h = 4 }
        }

        $beta = [ordered]@{
            id        = "beta"
            type      = "terminal"
            enabled   = $true
            windowId  = "DevWS-P6D-beta"
            path      = "C:\p6d-A"
            elevated  = $true
            tabs      = @(
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = $null; args = @() }
            )
            activeTab = 0
            layout    = [ordered]@{ x = 5; y = 6; w = 7; h = 8 }
        }

        $target = New-P6DSaveConfig -Name "p6d-save-e2e" -Terminals @($slot, $beta)

        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target
        $stateRoot = Join-Path $dir "state"
        $env:DEVWS_STATE_ROOT = $stateRoot
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        $cwds = @{}
        foreach ($key in @("slot#0", "slot#1", "slot#2", "beta#0")) {
            $path = Join-Path $dir ("cwd-" + ($key -replace "#", "-"))
            New-Item -ItemType Directory -Path $path -Force | Out-Null
            $cwds[$key] = $path
        }

        $script:p6dSaveCalls = 0
        $p6dOriginalSaveConfig = ${function:Save-DevWSConfig}

        function Save-DevWSConfig {
            param($Config, $Location)
            $script:p6dSaveCalls++
            & $p6dOriginalSaveConfig -Config $Config -Location $Location
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)

            $sidecarJson = '{"version":1,"terminals":[{"id":"slot","windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":2}]}'
            return (New-DevWSTestWorkerCaptureResult -Lines @("slot|11|12|13|14", "beta|21|22|23|24") -SnapshotJson $sidecarJson)
        }

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)

            $key = "$TerminalId#$TabIndex"

            if ($key -eq "beta#1") {
                return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null; SessionId = $null; WindowId = $null }
            }

            $wid = "DevWS-P6D-$TerminalId"
            $record = [ordered]@{ version = 1; setId = $SetId; terminalId = $TerminalId; windowId = $wid; sessionId = "G-$key" }
            if ($TabIndex -gt 0) { $record["tabIndex"] = $TabIndex }
            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId $SetId -TerminalId $TerminalId -TabIndex $TabIndex) -Record $record

            return [pscustomobject]@{ Status = "available"; Reason = "ok"; Cwd = $cwds[$key]; SessionId = "G-$key"; WindowId = $wid }
        }

        try {
            $text = (& { Save-DevWSWorkspace -SetId "main" } *>&1 | Out-String)

            Assert-Contains $text "State saved for set 'main'." "save succeeds"
            Assert-Contains $text "activeTab 2 (was 0)" "activeTab updated from the correlated snapshot"
            Assert-Equal 1 $script:p6dSaveCalls "exactly one canonical save"

            $config = Read-DevWSConfigFile -Path $target
            $term = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]

            Assert-Equal $cwds["slot#0"] ([string]$term.path) "tab 0 cwd updates terminal.path"
            Assert-Equal 2 ([int]$term.activeTab) "configured activeTab persisted"
            Assert-Equal $cwds["slot#1"] ([string]$term.tabs[1].path) "tab 1 materializes its live cwd"
            Assert-Equal $cwds["slot#2"] ([string]$term.tabs[2].path) "tab 2 materializes its live cwd"
            Assert-Equal 11 ([int]$term.layout.x) "geometry applied"

            $betaTerm = @($config.sets[0].windows | Where-Object { $_.id -eq "beta" })[0]
            Assert-Equal $cwds["beta#0"] ([string]$betaTerm.path) "fallback updates from tab 0"
            Assert-Equal "C:\p6d-A" ([string]$betaTerm.tabs[1].path) "unavailable sibling preserves its inherited path explicitly"
            Assert-Equal 0 ([int]$betaTerm.activeTab) "terminal without an observation keeps its activeTab"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

