        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target
        $stateRoot = Join-Path $dir "state"
        $env:DEVWS_STATE_ROOT = $stateRoot
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        $runtimeRoot = Get-DevWSRuntimeRoot
        $staleSidecar = Join-Path $runtimeRoot "capture-elevated.snapshots.json"
        [System.IO.File]::WriteAllText($staleSidecar, '{"version":1,"terminals":[{"id":"slot","windowId":"DevWS-P6D-slot","status":"available","selectedConfiguredTabIndex":1}]}', [System.Text.UTF8Encoding]::new($false))

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)

            # Geometry only: the new operation produced NO snapshot observation
            # (the legacy state-root sidecar stays seeded and must never be
            # consumed).
            return (New-DevWSTestWorkerCaptureResult -Lines @("slot|31|32|33|34"))
        }

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)
            return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null; SessionId = $null; WindowId = $null }
        }

        try {
            $text = (& { Save-DevWSWorkspace -SetId "main" } *>&1 | Out-String)

            Assert-Contains $text "State saved for set 'main'." "save still succeeds"
