            $config = Read-DevWSConfigFile -Path $target
            $term = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
            Assert-Equal 0 ([int]$term.activeTab) "stale index never persisted"
            Assert-Equal "C:\p6d-old" ([string]$term.path) "paths preserved"
            Assert-True (Test-Path -LiteralPath $staleSidecar) "the legacy state-root sidecar is left in place and never consumed"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

