            Assert-Equal "C:\p6d-tab1" ([string]$term.tabs[1].path) "explicit tab override untouched"
            Assert-Equal 0 ([int]$term.activeTab) "save-layout never consumes the sidecar"
            Assert-Equal "pwsh" ([string]$term.tabs[0].command) "commands untouched"
            Assert-Equal "-NoLogo" ([string]$term.tabs[0].args[0]) "args untouched"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Write-Host ""
    Start-TestGroup -Name 'startup-retirement' -Title 'Startup-intent retirement (ws save)'

    Test-Case "startup retirement decision matrix is fail-closed" {
        $matchFingerprint = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()

        function New-P6RDecision {
            param(
                [string]$Status = "available",
                [string]$Reason = "ok",
                $StartupState = "startup-child-returned",
                $Fingerprint = $null
            )

            return [pscustomobject]@{ status = $Status; reason = $Reason; startupState = $StartupState; startupSpecSha256 = $Fingerprint }
        }

        $cases = @(
            @{ Name = "returned + match";     D = (New-P6RDecision -Fingerprint $matchFingerprint);                                                       Retire = $true;  Reason = "ok" },
            @{ Name = "active";               D = (New-P6RDecision -StartupState "startup-child-active" -Fingerprint $matchFingerprint);                 Retire = $false; Reason = "state-not-returned" },
            @{ Name = "idle state";           D = (New-P6RDecision -StartupState "idle" -Fingerprint $matchFingerprint);                                 Retire = $false; Reason = "state-not-returned" },
            @{ Name = "missing state";        D = (New-P6RDecision -StartupState $null -Fingerprint $matchFingerprint);                                  Retire = $false; Reason = "state-missing" },
            @{ Name = "wrong-case token";     D = (New-P6RDecision -StartupState "STARTUP-CHILD-RETURNED" -Fingerprint $matchFingerprint);               Retire = $false; Reason = "state-malformed" },
            @{ Name = "mixed-case token";     D = (New-P6RDecision -StartupState "Startup-Child-Returned" -Fingerprint $matchFingerprint);               Retire = $false; Reason = "state-malformed" },
            @{ Name = "missing fingerprint";  D = (New-P6RDecision -Fingerprint $null);                                                                  Retire = $false; Reason = "fingerprint-missing-or-malformed" },
            @{ Name = "empty fingerprint";    D = (New-P6RDecision -Fingerprint "");                                                                     Retire = $false; Reason = "fingerprint-missing-or-malformed" },
            @{ Name = "63 hex";               D = (New-P6RDecision -Fingerprint ($matchFingerprint.Substring(0, 63)));                                   Retire = $false; Reason = "fingerprint-missing-or-malformed" },
            @{ Name = "65 hex";               D = (New-P6RDecision -Fingerprint ($matchFingerprint + "A"));                                              Retire = $false; Reason = "fingerprint-missing-or-malformed" },
            @{ Name = "non-hex";              D = (New-P6RDecision -Fingerprint ("z" * 64));                                                             Retire = $false; Reason = "fingerprint-missing-or-malformed" },
            @{ Name = "valid mismatch";       D = (New-P6RDecision -Fingerprint (Get-DevWSCwdChildSpecFingerprint -Command "other-tool" -Arguments @())); Retire = $false; Reason = "fingerprint-mismatch" },
            @{ Name = "uppercase equivalent"; D = (New-P6RDecision -Fingerprint $matchFingerprint.ToLowerInvariant());                                   Retire = $true;  Reason = "ok" },
            @{ Name = "unavailable decision"; D = (New-P6RDecision -Status "unavailable" -Reason "session-mismatch" -Fingerprint $matchFingerprint);     Retire = $false; Reason = "cwd-unavailable" }
        )

        foreach ($case in $cases) {
            $tab = [pscustomobject]@{ command = "devws-shell"; args = @() }
            $verdict = Get-DevWSTabStartupRetirementDecision -Tab $tab -Decision $case.D
            Assert-Equal $case.Retire ([bool]$verdict.Retire) ("retire verdict: " + $case.Name)
            Assert-Equal $case.Reason ([string]$verdict.Reason) ("reason: " + $case.Name)
        }

        $retireVerdict = Get-DevWSTabStartupRetirementDecision -Tab ([pscustomobject]@{ command = "devws-shell"; args = @() }) -Decision (New-P6RDecision -Fingerprint $matchFingerprint)
        Assert-Equal "devws-shell" ([string]$retireVerdict.Command) "retire verdict carries the configured command"

        $idleVerdict = Get-DevWSTabStartupRetirementDecision -Tab ([pscustomobject]@{ command = $null; args = @() }) -Decision (New-P6RDecision -Fingerprint $matchFingerprint)
        Assert-Equal $false ([bool]$idleVerdict.Retire) "null command never retires even with returned metadata"
        Assert-Equal "configured-idle" ([string]$idleVerdict.Reason) "null command reason"

        $nullDecisionVerdict = Get-DevWSTabStartupRetirementDecision -Tab ([pscustomobject]@{ command = "devws-shell"; args = @() }) -Decision $null
        Assert-Equal $false ([bool]$nullDecisionVerdict.Retire) "null decision preserves"
        Assert-Equal "cwd-unavailable" ([string]$nullDecisionVerdict.Reason) "null decision reason"

        $noTabVerdict = Get-DevWSTabStartupRetirementDecision -Tab $null -Decision (New-P6RDecision -Fingerprint $matchFingerprint)
        Assert-Equal $false ([bool]$noTabVerdict.Retire) "null tab preserves"
        Assert-Equal "no-tab" ([string]$noTabVerdict.Reason) "null tab reason"
    }

    Test-Case "startup retirement fingerprint distinctions and numeric normalization" {
        $fp = @{}
        $fp["empty"]      = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()
        $fp["one-empty"]  = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("")
        $fp["two"]        = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("a", "b")
        $fp["joined"]     = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("a b")
        $fp["switch"]     = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("-w", "5")
        $fp["switchjoin"] = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("-w 5")
        $fp["orderab"]    = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("a", "b")
        $fp["orderba"]    = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("b", "a")
        $fp["unicode"]    = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("héllo", "世界")
        $fp["ascii"]      = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("hello", "world")
        $fp["upper"]      = Get-DevWSCwdChildSpecFingerprint -Command "DevWs-ShElL" -Arguments @()
        $fp["lower"]      = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()
        $fp["numeric"]    = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("1", "2")

        foreach ($pair in @(
            @("empty", "one-empty"), @("two", "joined"), @("switch", "switchjoin"),
            @("orderab", "orderba"), @("unicode", "ascii"), @("upper", "lower"), @("numeric", "joined")
        )) {
            Assert-True ($fp[$pair[0]] -cne $fp[$pair[1]]) ("fingerprint distinct: " + $pair[0] + " vs " + $pair[1])
        }

        # numeric config args normalize through the existing canonical helper
        $numConfig = '[{"command":"devws-shell","args":[1,2]},{"command":"devws-shell","args":["1","2"]}]' | ConvertFrom-Json
        $numFp = Get-DevWSCwdChildSpecFingerprint -Command $numConfig[0].command -Arguments @($numConfig[0].args)
        $strFp = Get-DevWSCwdChildSpecFingerprint -Command $numConfig[1].command -Arguments @($numConfig[1].args)
        Assert-Equal $strFp $numFp "numeric config args normalize to the string representation"

        # current-config correlation: the edited child never retires the old generation
        $decision = [pscustomobject]@{ status = "available"; reason = "ok"; startupState = "startup-child-returned"; startupSpecSha256 = $fp["empty"] }
        $editedArgs = Get-DevWSTabStartupRetirementDecision -Tab ([pscustomobject]@{ command = "devws-shell"; args = @("--new-option") }) -Decision $decision
        Assert-Equal $false ([bool]$editedArgs.Retire) "edited args preserve the current configured command"
        Assert-Equal "fingerprint-mismatch" ([string]$editedArgs.Reason) "edited args mismatch reason"

        $renamed = Get-DevWSTabStartupRetirementDecision -Tab ([pscustomobject]@{ command = "another-tool"; args = @() }) -Decision $decision
        Assert-Equal $false ([bool]$renamed.Retire) "renamed command preserves"
        Assert-Equal "fingerprint-mismatch" ([string]$renamed.Reason) "renamed command mismatch reason"
    }

    Test-Case "startup retirement encoder writes the canonical idle shape" {
        $terminal = [pscustomobject]@{
            id = "slot"; type = "terminal"; enabled = $true; windowId = "DevWS-P6R-slot"; path = "C:\A"; elevated = $true
            tabs = @(
                [pscustomobject]@{ command = "devws-shell"; args = @("--foo"); path = "C:\A\keep" },
                [pscustomobject]@{ command = "other"; args = @() }
            )
            activeTab = 1
            layout = [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4 }
        }

        $siblingBefore = $terminal.tabs[1] | ConvertTo-Json -Depth 10 -Compress

        Invoke-DevWSTabStartupRetirement -Tab $terminal.tabs[0]

        Assert-Equal $null $terminal.tabs[0].command "command becomes null"
        Assert-Equal 0 (@($terminal.tabs[0].args).Count) "args become an empty array"
        Assert-Equal "C:\A\keep" ([string]$terminal.tabs[0].path) "unrelated tab fields preserved"
        Assert-Equal $siblingBefore ($terminal.tabs[1] | ConvertTo-Json -Depth 10 -Compress) "sibling tab untouched"

        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main" -Windows @($terminal)))
        Assert-DevWSConfig -Config $config -Source "startup-retirement encoder"
        "  [ok]   retired config passes full validation"

        Assert-Equal "idle + other" (Get-DevWSTerminalTabSummary -Terminal $terminal) "summary renders the retired tab idle"

        # raw hashtable tab definitions are handled too
        $rawTab = [ordered]@{ command = "devws-shell"; args = @("--x") }
        Invoke-DevWSTabStartupRetirement -Tab $rawTab
        Assert-Equal $null $rawTab["command"] "hashtable command nulled"
        Assert-Equal 0 (@($rawTab["args"]).Count) "hashtable args cleared"
    }

    Test-Case "startup retirement preserves unrelated fields per tab independently" {
        $f = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()

        $terminal = [pscustomobject]@{
            id = "slot"; type = "terminal"; enabled = $true; windowId = "DevWS-P6R-slot"; path = "C:\A"; elevated = $true
            tabs = @(
                [pscustomobject]@{ command = "devws-shell"; args = @() },
                [pscustomobject]@{ command = "devws-shell"; args = @() },
                [pscustomobject]@{ command = "devws-shell"; args = @() },
                [pscustomobject]@{ command = $null; args = @() }
            )
            activeTab = 0
            layout = [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4 }
        }

        $decisions = @(
            [pscustomobject]@{ tabIndex = 0; status = "available"; reason = "ok"; startupState = "startup-child-returned"; startupSpecSha256 = $f },
            [pscustomobject]@{ tabIndex = 1; status = "available"; reason = "ok"; startupState = "startup-child-active"; startupSpecSha256 = $f },
            [pscustomobject]@{ tabIndex = 2; status = "available"; reason = "ok"; startupState = "startup-child-returned"; startupSpecSha256 = (Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @("--other")) },
            [pscustomobject]@{ tabIndex = 3; status = "available"; reason = "ok"; startupState = "idle"; startupSpecSha256 = (Get-DevWSCwdChildSpecFingerprint -Command $null -Arguments @()) }
        )

        foreach ($d in $decisions) {
            $v = Get-DevWSTabStartupRetirementDecision -Tab $terminal.tabs[[int]$d.tabIndex] -Decision $d
            if ([bool]$v.Retire) { Invoke-DevWSTabStartupRetirement -Tab $terminal.tabs[[int]$d.tabIndex] }
        }

        Assert-Equal $null $terminal.tabs[0].command "tab 0 retired"
        Assert-Equal 0 (@($terminal.tabs[0].args).Count) "tab 0 args cleared"
        Assert-Equal "devws-shell" ([string]$terminal.tabs[1].command) "active tab preserved"
        Assert-Equal "devws-shell" ([string]$terminal.tabs[2].command) "mismatch tab preserved"
        Assert-Equal $null $terminal.tabs[3].command "idle tab unchanged"

        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main" -Windows @($terminal)))
        Assert-DevWSConfig -Config $config -Source "startup-retirement independence"
        "  [ok]   mixed result passes full validation"
    }

    Test-Case "startup retirement generation gate blocks rotation and clears metadata" {
        $dir = Join-Path $TestRoot "p6r-gate"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = Join-Path $dir "state"
        New-Item -ItemType Directory -Path $env:DEVWS_STATE_ROOT -Force | Out-Null

        try {
            $fingerprint = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()
            $windowId = "DevWS-P6R-gate"
            $work = Join-Path $dir "work"
            New-Item -ItemType Directory -Path $work -Force | Out-Null

            function New-P6RGateDecision {
                param([string]$SessionId, [string]$StartupState = "startup-child-returned", [string]$Fingerprint = $fingerprint)

                return [pscustomobject]@{
                    terminalId = "slot"; tabIndex = 0
                    status = "available"; reason = "ok"; newCwd = $work
                    sessionId = $SessionId; windowId = $windowId
                    startupState = $StartupState; startupSpecSha256 = $Fingerprint
                }
            }

            $tab = [pscustomobject]@{ command = "devws-shell"; args = @() }

            $ctx1 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId $windowId -TabIndex 0 -StartupSpecSha256 $fingerprint
            $d1 = New-P6RGateDecision -SessionId $ctx1.SessionId
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions @{ slot = @($d1) }
            Assert-Equal "available" ([string]$d1.status) "stable generation passes the gate"
            Assert-Equal $true ([bool](Get-DevWSTabStartupRetirementDecision -Tab $tab -Decision $d1).Retire) "stable generation retires"

            # rotation S1 -> S2 blocks and clears
            $ctx2 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId $windowId -TabIndex 0 -StartupSpecSha256 $fingerprint
            $d2 = New-P6RGateDecision -SessionId $ctx1.SessionId
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions @{ slot = @($d2) }
            Assert-Equal "unavailable" ([string]$d2.status) "rotation downgrades the decision"
            Assert-Equal "session-mismatch" ([string]$d2.reason) "rotation reason"
            Assert-Equal $null $d2.startupState "rotation cleared startupState"
            Assert-Equal $null $d2.startupSpecSha256 "rotation cleared startupSpecSha256"
            Assert-Equal $false ([bool](Get-DevWSTabStartupRetirementDecision -Tab $tab -Decision $d2).Retire) "rotation blocks retirement; the new returned generation never rescues S1"

            # expected record deleted
            Remove-Item -LiteralPath $ctx2.SessionPath -Force
            $d3 = New-P6RGateDecision -SessionId $ctx2.SessionId
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions @{ slot = @($d3) }
            Assert-Equal "expected-missing" ([string]$d3.reason) "deleted expected record downgrades"
            Assert-Equal $false ([bool](Get-DevWSTabStartupRetirementDecision -Tab $tab -Decision $d3).Retire) "deleted expected record blocks retirement"

            # an active decision is never upgraded and the gate leaves it intact
            $ctx3 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId $windowId -TabIndex 0 -StartupSpecSha256 $fingerprint
            $d4 = New-P6RGateDecision -SessionId $ctx3.SessionId -StartupState "startup-child-active"
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions @{ slot = @($d4) }
            Assert-Equal "available" ([string]$d4.status) "active decision passes the gate"
            Assert-Equal "startup-child-active" ([string]$d4.startupState) "gate never rewrites the captured state"
            Assert-Equal $false ([bool](Get-DevWSTabStartupRetirementDecision -Tab $tab -Decision $d4).Retire) "active is never upgraded to retire"

            # publication deletion after captured returned: expected-only gate, no re-read
            $ctx4 = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId $windowId -TabIndex 0 -StartupSpecSha256 $fingerprint
            Write-DevWSCwdPublication -Path (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot" -TabIndex 0) -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = $windowId; sessionId = $ctx4.SessionId
                cwd = $work; startupState = "startup-child-returned"; shellPid = $PID
                shellStartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
                updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })
            $d5 = New-P6RGateDecision -SessionId $ctx4.SessionId
            Remove-Item -LiteralPath (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot" -TabIndex 0) -Force
            Confirm-DevWSTerminalSaveDecisions -SetId "main" -Decisions @{ slot = @($d5) }
            Assert-Equal $true ([bool](Get-DevWSTabStartupRetirementDecision -Tab $tab -Decision $d5).Retire) "publication deletion requires no re-read; the expected-only gate keeps the captured verdict"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "startup retirement metadata is carried only by available decisions" {
        $dir = Join-Path $TestRoot "p6r-metadata"
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_STATE_ROOT = Join-Path $dir "state"
        New-Item -ItemType Directory -Path $env:DEVWS_STATE_ROOT -Force | Out-Null

        try {
            $fingerprint = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()
            $work = Join-Path $dir "work"
            New-Item -ItemType Directory -Path $work -Force | Out-Null
            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            # tracked tab 0: valid pair + returned metadata
            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot" -TabIndex 0) -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-P6R-meta"; sessionId = "M0"; startupSpecSha256 = $fingerprint
            })
            Write-DevWSCwdPublication -Path (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot" -TabIndex 0) -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-P6R-meta"; sessionId = "M0"
                cwd = $work; startupState = "startup-child-returned"; shellPid = $PID; shellStartTimeUtc = $startIso
                updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            # tracked tab 1: valid pair + active metadata
            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId "main" -TerminalId "slot" -TabIndex 1) -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-P6R-meta"; sessionId = "M1"; tabIndex = 1; startupSpecSha256 = $fingerprint
            })
            Write-DevWSCwdPublication -Path (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot" -TabIndex 1) -Record ([ordered]@{
                version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-P6R-meta"; sessionId = "M1"; tabIndex = 1
                cwd = $work; startupState = "startup-child-active"; shellPid = $PID; shellStartTimeUtc = $startIso
                updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            $terminal = [pscustomobject]@{
                id = "slot"; type = "terminal"; enabled = $true; windowId = "DevWS-P6R-meta"; path = "C:\old"; elevated = $true
                tabs = @(
                    [pscustomobject]@{ command = "devws-shell"; args = @() },
                    [pscustomobject]@{ command = "devws-shell"; args = @() },
                    [pscustomobject]@{ command = "devws-shell"; args = @() }
                )
                activeTab = 0
                layout = [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4 }
            }

            $decisions = Get-DevWSTerminalSaveDecisions -SetId "main" -Terminals @($terminal)
            $perTab = @($decisions["slot"])

            Assert-Equal "available" ([string]$perTab[0].status) "tab 0 available"
            Assert-Equal "startup-child-returned" ([string]$perTab[0].startupState) "tab 0 startupState carried"
            Assert-Equal $fingerprint ([string]$perTab[0].startupSpecSha256) "tab 0 fingerprint carried"
            Assert-Equal $true ([bool](Get-DevWSTabStartupRetirementDecision -Tab $terminal.tabs[0] -Decision $perTab[0]).Retire) "tab 0 retires"

            Assert-Equal "available" ([string]$perTab[1].status) "tab 1 available"
            Assert-Equal "startup-child-active" ([string]$perTab[1].startupState) "tab 1 state carried"
            Assert-Equal $false ([bool](Get-DevWSTabStartupRetirementDecision -Tab $terminal.tabs[1] -Decision $perTab[1]).Retire) "tab 1 preserves (active)"

            Assert-Equal "unavailable" ([string]$perTab[2].status) "tab 2 untracked (expected-missing)"
            Assert-Equal $null $perTab[2].startupState "unavailable decision carries no startupState"
            Assert-Equal $null $perTab[2].startupSpecSha256 "unavailable decision carries no fingerprint"
            Assert-Equal $false ([bool](Get-DevWSTabStartupRetirementDecision -Tab $terminal.tabs[2] -Decision $perTab[2]).Retire) "untracked tab preserves command + args"

            # disabled terminals are outside the save scope by construction
            $scopeConfig = ConvertTo-TestConfig -Sets @(
                (New-TestSet -Id "main" -Windows @(
                    ([ordered]@{ id = "live"; type = "terminal"; enabled = $true;  windowId = "DevWS-P6R-live"; path = "C:\A"; elevated = $true; tabs = @([ordered]@{ command = "devws-shell"; args = @() }); activeTab = 0; layout = [ordered]@{ x = 0; y = 0; w = 10; h = 10 } }),
                    ([ordered]@{ id = "off";  type = "terminal"; enabled = $false; windowId = "DevWS-P6R-off";  path = "C:\A"; elevated = $true; tabs = @([ordered]@{ command = "devws-shell"; args = @() }); activeTab = 0; layout = [ordered]@{ x = 0; y = 0; w = 10; h = 10 } })
                ))
            )
            $enabled = @(Get-DevWSEnabledItems -Config $scopeConfig -Set $scopeConfig.sets[0] -Type "terminal")
            Assert-Equal 1 $enabled.Count "disabled terminal excluded from the save scope"
            Assert-Equal "live" ([string]$enabled[0].id) "only the enabled terminal is observed"
        }
        finally {
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "ws save retires startup intent in the same commit" {
        $dir = Join-Path $TestRoot "p6r-save-e2e"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null

        $fpMatch = Get-DevWSCwdChildSpecFingerprint -Command "devws-shell" -Arguments @()

        $slot = [ordered]@{
            id        = "slot"
            type      = "terminal"
            enabled   = $true
            windowId  = "DevWS-P6R-slot"
            path      = "C:\p6r-A"
            elevated  = $true
            tabs      = @(
                [ordered]@{ command = "devws-shell"; args = @() },
                [ordered]@{ command = "devws-shell"; args = @("--new") },
                [ordered]@{ command = $null; args = @() },
                [ordered]@{ command = "devws-shell"; args = @() },
                [ordered]@{ command = "devws-shell"; args = @() }
            )
            activeTab = 0
            layout    = [ordered]@{ x = 1; y = 2; w = 3; h = 4 }
        }

        $target = New-P6DSaveConfig -Name "p6r-save-e2e" -Terminals @($slot)

        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target
        $stateRoot = Join-Path $dir "state"
        $env:DEVWS_STATE_ROOT = $stateRoot
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        $cwds = @{}
        foreach ($key in @("slot#0", "slot#1", "slot#2", "slot#4")) {
            $path = Join-Path $dir ("cwd-" + ($key -replace "#", "-"))
            New-Item -ItemType Directory -Path $path -Force | Out-Null
            $cwds[$key] = $path
        }

        $script:p6rSaveCalls = 0
        $script:p6rNoGeometry = $false
        $script:p6rFailSave = $false
        $p6rOriginalSaveConfig = ${function:Save-DevWSConfig}

        function Save-DevWSConfig {
            param($Config, $Location)
            $script:p6rSaveCalls++
            if ($script:p6rFailSave) { throw "simulated canonical save failure" }
            & $p6rOriginalSaveConfig -Config $Config -Location $Location
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)

            if ($script:p6rNoGeometry) {
                # A completed operation with a protected claim but no geometry.
                return (New-DevWSTestWorkerCaptureResult)
            }

            return (New-DevWSTestWorkerCaptureResult -Lines @("slot|11|12|13|14"))
        }

        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)

            $key = "$TerminalId#$TabIndex"

            if ($key -eq "slot#3") {
                return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null; SessionId = $null; WindowId = $null; StartupState = $null; StartupSpecSha256 = $null }
            }

            $wid = "DevWS-P6R-slot"
            $record = [ordered]@{ version = 1; setId = $SetId; terminalId = $TerminalId; windowId = $wid; sessionId = "R-$key"; startupSpecSha256 = $fpMatch }
            if ($TabIndex -gt 0) { $record["tabIndex"] = $TabIndex }
            Write-DevWSCwdSessionRecord -Path (Get-DevWSCwdSessionPath -SetId $SetId -TerminalId $TerminalId -TabIndex $TabIndex) -Record $record

            $state = "startup-child-returned"
            if ($key -eq "slot#2") { $state = "idle" }
            if ($key -eq "slot#4") { $state = "startup-child-active" }

            return [pscustomobject]@{ Status = "available"; Reason = "ok"; Cwd = $cwds[$key]; SessionId = "R-$key"; WindowId = $wid; StartupState = $state; StartupSpecSha256 = $fpMatch }
        }

        try {
            $text = (& { Save-DevWSWorkspace -SetId "main" } *>&1 | Out-String)

            Assert-Contains $text "State saved for set 'main'." "save succeeds"
            Assert-Contains $text "tab 0 startup retired: devws-shell" "retirement line for tab 0"
            Assert-Equal $false ($text -match "tab [1-4] startup retired") "no retirement line for preserved tabs"
            Assert-Equal 1 $script:p6rSaveCalls "exactly one canonical save"

            $config = Read-DevWSConfigFile -Path $target
            $term = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]

            Assert-Equal $null $term.tabs[0].command "tab 0 command retired"
            Assert-Equal 0 (@($term.tabs[0].args).Count) "tab 0 args cleared"
            Assert-Equal "devws-shell" ([string]$term.tabs[1].command) "tab 1 preserved (fingerprint mismatch)"
            Assert-Equal "--new" ([string]$term.tabs[1].args[0]) "tab 1 args preserved"
            Assert-Equal $null $term.tabs[2].command "tab 2 stays idle"
            Assert-Equal "devws-shell" ([string]$term.tabs[3].command) "tab 3 preserved (untracked)"
            Assert-Equal "devws-shell" ([string]$term.tabs[4].command) "tab 4 preserved (active)"
            Assert-Equal $cwds["slot#0"] ([string]$term.path) "tab 0 cwd still persisted in the same commit"
            Assert-Equal 11 ([int]$term.layout.x) "geometry applied in the same commit"

            # second save: no intent left to retire; stable and silent
            $secondText = (& { Save-DevWSWorkspace -SetId "main" } *>&1 | Out-String)
            Assert-Equal $false ($secondText -match "startup retired") "second save reports no retirement"
            Assert-Equal 2 $script:p6rSaveCalls "second save still uses exactly one canonical save"

            # failed geometry: no retirement commit at all
            $bytesBefore = [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))
            $script:p6rNoGeometry = $true
            $failed = $null
            try { Save-DevWSWorkspace -SetId "main" | Out-Null } catch { $failed = $_.Exception.Message }
            Assert-True (-not [string]::IsNullOrWhiteSpace($failed)) "geometry failure throws"
            Assert-Equal 2 $script:p6rSaveCalls "geometry failure never reaches the canonical save"
            Assert-Equal $bytesBefore ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "geometry failure leaves canonical bytes unchanged"
            $script:p6rNoGeometry = $false

            # canonical save failure: no successful retirement output
            $script:p6rFailSave = $true
            $failureText = ""
            try { $failureText = (& { Save-DevWSWorkspace -SetId "main" } *>&1 | Out-String) } catch { $failureText = "THREW: " + $_.Exception.Message }
            Assert-Contains $failureText "simulated canonical save failure" "failed save surfaces the canonical-save error"
            Assert-Equal $false ($failureText -match "startup retired") "failed save prints no retirement line"
            Assert-Equal $bytesBefore ([Convert]::ToBase64String([System.IO.File]::ReadAllBytes($target))) "failed save leaves canonical bytes unchanged"
            $script:p6rFailSave = $false
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "ws save-layout never retires startup intent" {
        $dir = Join-Path $TestRoot "p6r-save-layout"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null

        $fingerprint = Get-DevWSCwdChildSpecFingerprint -Command "pwsh" -Arguments @("-NoLogo")

        $slot = [ordered]@{
            id        = "slot"
            type      = "terminal"
            enabled   = $true
            windowId  = "DevWS-P6R-layout"
            path      = "C:\p6r-old"
            elevated  = $true
            tabs      = @(
                [ordered]@{ command = "pwsh"; args = @("-NoLogo") },
                [ordered]@{ command = $null; args = @() }
            )
            activeTab = 0
            layout    = [ordered]@{ x = 1; y = 2; w = 3; h = 4 }
        }

        $target = New-P6DSaveConfig -Name "p6r-save-layout" -Terminals @($slot)

        $savedEnv = $env:DEVWS_CONFIG
        $savedState = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $target
        $stateRoot = Join-Path $dir "state"
        $env:DEVWS_STATE_ROOT = $stateRoot
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        # A generation that WOULD retire under `ws save`.
        $ctx = New-DevWSCwdTrackingSession -SetId "main" -TerminalId "slot" -WindowId "DevWS-P6R-layout" -TabIndex 0 -StartupSpecSha256 $fingerprint
        $cwdDir = Join-Path $dir "cwd"
        New-Item -ItemType Directory -Path $cwdDir -Force | Out-Null
        Write-DevWSCwdPublication -Path (Get-DevWSCwdPublicationPath -SetId "main" -TerminalId "slot" -TabIndex 0) -Record ([ordered]@{
            version = 1; setId = "main"; terminalId = "slot"; windowId = "DevWS-P6R-layout"; sessionId = $ctx.SessionId
            cwd = $cwdDir; startupState = "startup-child-returned"; shellPid = $PID
            shellStartTimeUtc = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            updatedAtUtc = (Get-Date).ToUniversalTime().ToString("o")
        })

        $script:p6rLayoutResolverCalls = 0
        function Resolve-DevWSTrackedCwd {
            param([string]$SetId, [string]$TerminalId, [int]$TabIndex = 0)
            $script:p6rLayoutResolverCalls++
            return [pscustomobject]@{ Status = "available"; Reason = "ok"; Cwd = $cwdDir; SessionId = $ctx.SessionId; WindowId = "DevWS-P6R-layout"; StartupState = "startup-child-returned"; StartupSpecSha256 = $fingerprint }
        }

        function Invoke-DevWSWorkerRequest {
            param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
            return (New-DevWSTestWorkerCaptureResult -Lines @("slot|41|42|43|44"))
        }

        try {
            $text = (& { Save-DevWSLayout -SetId "main" } *>&1 | Out-String)

            Assert-Equal 0 $script:p6rLayoutResolverCalls "save-layout never resolves tracked cwd or startup metadata"
            Assert-Equal $false ($text -match "startup retired") "save-layout never prints retirement"

            $config = Read-DevWSConfigFile -Path $target
            $term = @($config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]

            Assert-Equal "pwsh" ([string]$term.tabs[0].command) "startup command untouched by save-layout"
            Assert-Equal "-NoLogo" ([string]$term.tabs[0].args[0]) "startup args untouched by save-layout"
            Assert-Equal 41 ([int]$term.layout.x) "geometry still saved"
            Assert-Equal "C:\p6r-old" ([string]$term.path) "tracked cwd untouched"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Write-Host ""
    Start-TestGroup -Name 'rename-set' -Title 'Workspace set rename (rename-set)'

    Test-Case "pure rename preserves identity and retargets only the set references" {
        $config = ConvertTo-TestConfig -DefaultSet "main" -Bindings @(
            [ordered]@{ hotkey = "alt+shift+y"; setId = "main" },
            [ordered]@{ hotkey = "alt+shift+u"; setId = "secondary" },
            [ordered]@{ hotkey = "alt+shift+i"; setId = "beta" }
        ) -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TerminalDefinition -Id "slot"),
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated")
            )),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TerminalDefinition -Id "studio"),
                (New-TestMatchedAppDefinition -Id "codex" -MatchKind "exe" -MatchValue "codex.exe" -InstanceMode "shared")
            )),
            (New-TestSet -Id "beta" -Windows @((New-TerminalDefinition -Id "scratch")))
        )

        # Identity coverage: a tab path override and a topology profile on the set.
        $secondary = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]
        $secondary.windows[0].tabs[0] | Add-Member -MemberType NoteProperty -Name path -Value "C:\Temp\studio-extra" -Force
        $secondary | Add-Member -MemberType NoteProperty -Name layoutProfiles -Value @(
            [pscustomobject][ordered]@{
                id      = "docked"
                match   = [pscustomobject][ordered]@{ mode = "exact"; monitors = @("edid:11223344@0,0,1920x1080") }
                layouts = [pscustomobject][ordered]@{ studio = [pscustomobject][ordered]@{ x = 10; y = 20; w = 640; h = 480 } }
            }
        ) -Force

        $bindingZero = $config.bindings[0] | ConvertTo-Json -Depth 20 -Compress
        $bindingTwo  = $config.bindings[2] | ConvertTo-Json -Depth 20 -Compress
        $setBefore   = $secondary | ConvertTo-Json -Depth 40 -Compress
        $expectedSet = $setBefore | ConvertFrom-Json
        $expectedSet.id = "development"

        $result = Rename-DevWSSet -Config $config -OldReference "SECONDARY" -NewId "development"

        Assert-Equal $true ([bool]$result.Changed) "rename reports changed"
        Assert-Equal $false ([bool]$result.CaseOnly) "semantic rename is not case-only"
        Assert-Equal $false ([bool]$result.DefaultSetRewritten) "non-default rename leaves defaultSet alone"
        Assert-Equal 1 ([int]$result.BindingsRewritten) "exactly the targeting binding is rewritten"
        Assert-Equal "secondary" ([string]$result.OldId) "canonical old id captured"
        Assert-Equal "development" ([string]$result.NewId) "new id captured"
        Assert-True ([object]::ReferenceEquals($result.Set, $secondary)) "the source set object is preserved (never clone + remove)"

        Assert-Equal "main,development,beta" ((@($config.sets | ForEach-Object { [string]$_.id })) -join ",") "set array position preserved"
        Assert-Equal "main" ([string]$config.defaultSet) "defaultSet untouched"
        Assert-Equal "development" ([string]$config.bindings[1].setId) "targeting binding retargeted"
        Assert-Equal "alt+shift+u" ([string]$config.bindings[1].hotkey) "binding hotkey preserved exactly"
        Assert-Equal $bindingZero ($config.bindings[0] | ConvertTo-Json -Depth 20 -Compress) "unrelated binding unchanged"
        Assert-Equal $bindingTwo ($config.bindings[2] | ConvertTo-Json -Depth 20 -Compress) "second unrelated binding unchanged"

        $renamedSet = @($config.sets | Where-Object { $_.id -eq "development" })[0]
        Assert-Equal ($expectedSet | ConvertTo-Json -Depth 40 -Compress) ($renamedSet | ConvertTo-Json -Depth 40 -Compress) "only the set id changed: items, tabs, args, windowIds, geometry and profiles equal"
        Assert-Equal "DevWS-studio" ([string]$renamedSet.windows[0].windowId) "terminal windowId preserved"
        Assert-Equal "C:\Temp\studio-extra" ([string]$renamedSet.windows[0].tabs[0].path) "tab path override preserved"
        Assert-Equal "shared" ([string]$renamedSet.windows[1].instanceMode) "app instanceMode preserved"
        Assert-Equal "edid:11223344@0,0,1920x1080" ([string]$renamedSet.layoutProfiles[0].match.monitors[0]) "profile matcher preserved"
        Assert-Equal 640 ([int]$renamedSet.layoutProfiles[0].layouts.studio.w) "sparse profile layout preserved"

        Assert-DevWSConfig -Config $config -Source "rename-set test"
        [void](Resolve-DevWSSet -Config $config -Reference "DeVeLoPmEnT")
        $message = Get-ThrownMessage { Resolve-DevWSSet -Config $config -Reference "secondary" }
        Assert-Contains $message "Unknown workspace set 'secondary'" "old id no longer resolves"
    }

    Test-Case "rename retargets defaultSet and stores exact case-only casing" {
        $config = ConvertTo-TestConfig -DefaultSet "main" -Bindings @(
            [ordered]@{ hotkey = "alt+shift+y"; setId = "main" },
            [ordered]@{ hotkey = "alt+shift+u"; setId = "secondary" }
        ) -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
            (New-TestSet -Id "secondary" -Windows @((New-TerminalDefinition -Id "studio")))
        )

        $result = Rename-DevWSSet -Config $config -OldReference "main" -NewId "primary"

        Assert-Equal $true ([bool]$result.DefaultSetRewritten) "default rename rewrites defaultSet"
        Assert-Equal "primary" ([string]$config.defaultSet) "defaultSet carries the exact new id"
        Assert-Equal "primary" ([string](Get-DevWSDefaultSet -Config $config).id) "the renamed set stays the default"
        Assert-Equal "primary,secondary" ((@($config.sets | ForEach-Object { [string]$_.id })) -join ",") "default set keeps its array position"
        Assert-Equal "primary" ([string]$config.bindings[0].setId) "binding to the old default retargeted"
        Assert-Equal "secondary" ([string]$config.bindings[1].setId) "unrelated binding untouched"

        # Case-only rename on a fresh copy (default set included).
        $config2 = ConvertTo-TestConfig -DefaultSet "secondary" -Bindings @(
            [ordered]@{ hotkey = "alt+shift+u"; setId = "secondary" }
        ) -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
            (New-TestSet -Id "secondary" -Windows @((New-TerminalDefinition -Id "studio")))
        )

        $setBefore = (@($config2.sets | Where-Object { $_.id -eq "secondary" })[0] | ConvertTo-Json -Depth 40 -Compress)
        $result2 = Rename-DevWSSet -Config $config2 -OldReference "SECONDARY" -NewId "Secondary"

        Assert-Equal $true ([bool]$result2.Changed) "case-only rename is a real change"
        Assert-Equal $true ([bool]$result2.CaseOnly) "case-only rename detected"
        Assert-Equal $true ([bool]$result2.DefaultSetRewritten) "case-only rename rewrites the default when it targets the set"
        Assert-Equal "Secondary" ([string](@($config2.sets | Where-Object { $_.id -ceq "Secondary" })[0].id)) "exact requested casing stored on the set"
        Assert-Equal "Secondary" ([string]$config2.defaultSet) "defaultSet rewritten to the exact new casing"
        Assert-Equal "Secondary" ([string]$config2.bindings[0].setId) "binding rewritten to the exact new casing"
        Assert-Equal "alt+shift+u" ([string]$config2.bindings[0].hotkey) "binding hotkey unchanged"

        $renamed2   = @($config2.sets | Where-Object { $_.id -ceq "Secondary" })[0]
        $roundtrip  = ($renamed2 | ConvertTo-Json -Depth 40 -Compress | ConvertFrom-Json)
        $roundtrip.id = "secondary"
        Assert-Equal $setBefore ($roundtrip | ConvertTo-Json -Depth 40 -Compress) "case-only rename changes nothing but the stored casing"
        Assert-DevWSConfig -Config $config2 -Source "rename-set case-only test"
    }

    Test-Case "rename refuses before mutation and treats an exact-same name as a no-op" {
        $config = ConvertTo-TestConfig -DefaultSet "main" -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
            (New-TestSet -Id "secondary" -Windows @((New-TerminalDefinition -Id "studio"))),
            (New-TestSet -Id "beta" -Windows @((New-TerminalDefinition -Id "scratch")))
        )
        $snapshot = $config | ConvertTo-Json -Depth 40 -Compress

        $noop = Rename-DevWSSet -Config $config -OldReference "secondary" -NewId "secondary"
        Assert-Equal $false ([bool]$noop.Changed) "exact-same rename is a no-op"
        Assert-Equal 0 ([int]$noop.BindingsRewritten) "no-op rewrites nothing"
        Assert-Equal $snapshot ($config | ConvertTo-Json -Depth 40 -Compress) "no-op leaves the config untouched"

        foreach ($case in @(
            @{ Old = "beta"; New = "Secondary"; Text = "case-insensitive collision" },
            @{ Old = "beta"; New = "MAIN";      Text = "collision with another set" },
            @{ Old = "beta"; New = "";          Text = "empty id" },
            @{ Old = "beta"; New = "bad/id";    Text = "scoped-reference character" },
            @{ Old = "beta"; New = "has space"; Text = "space" },
            @{ Old = "beta"; New = "x`ty";      Text = "tab" },
            @{ Old = "beta"; New = (([char]0x00E9) + "cafe"); Text = "non-ASCII" }
        )) {
            $message = Get-ThrownMessage { Rename-DevWSSet -Config $config -OldReference $case.Old -NewId $case.New }
            Assert-True (-not [string]::IsNullOrWhiteSpace($message)) "refused: $($case.Text)"
            Assert-Equal $snapshot ($config | ConvertTo-Json -Depth 40 -Compress) "no partial mutation after refusal: $($case.Text)"
        }

        $unknown = Get-ThrownMessage { Rename-DevWSSet -Config $config -OldReference "missing" -NewId "x" }
        Assert-Contains $unknown "Unknown workspace set" "unknown source refused before mutation"

        # Zero bindings.
        $noBindings = ConvertTo-TestConfig -DefaultSet "main" -Sets @(
            (New-TestSet -Id "main"),
            (New-TestSet -Id "secondary")
        )
        $result = Rename-DevWSSet -Config $noBindings -OldReference "secondary" -NewId "renamed"
        Assert-Equal $true ([bool]$result.Changed) "zero-binding rename still changes the id"
        Assert-Equal 0 ([int]$result.BindingsRewritten) "zero bindings rewrite nothing"
        Assert-Equal 0 (@($noBindings.bindings).Count) "bindings stay empty"

        # Multiple bindings all targeting the source.
        $multi = ConvertTo-TestConfig -DefaultSet "main" -Bindings @(
            [ordered]@{ hotkey = "alt+shift+y"; setId = "beta" },
            [ordered]@{ hotkey = "alt+shift+u"; setId = "beta" },
            [ordered]@{ hotkey = "alt+shift+i"; setId = "beta" }
        ) -Sets @(
            (New-TestSet -Id "main"),
            (New-TestSet -Id "beta")
        )
        $result = Rename-DevWSSet -Config $multi -OldReference "beta" -NewId "epsilon"
        Assert-Equal 3 ([int]$result.BindingsRewritten) "every targeting binding rewritten"
        Assert-Equal "epsilon,epsilon,epsilon" ((@($multi.bindings | ForEach-Object { [string]$_.setId })) -join ",") "all binding targets retargeted"
        Assert-Equal "alt+shift+y,alt+shift+u,alt+shift+i" ((@($multi.bindings | ForEach-Object { [string]$_.hotkey })) -join ",") "hotkeys unchanged"
    }

    Test-Case "ownership preflight is bounded, fail-closed, and shared-safe" {
        $config = ConvertTo-TestConfig -DefaultSet "main" -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated"),
                (New-TestMatchedAppDefinition -Id "codex" -MatchKind "exe" -MatchValue "codex.exe" -InstanceMode "shared")
            )),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TestMatchedAppDefinition -Id "firefox" -MatchKind "exe" -MatchValue "firefox.exe" -InstanceMode "dedicated")
            )),
            (New-TestSet -Id "sharedonly" -Windows @(
                (New-TestMatchedAppDefinition -Id "codex" -MatchKind "exe" -MatchValue "codex.exe" -InstanceMode "shared")
            ))
        )

        $target     = @($config.sets | Where-Object { $_.id -eq "secondary" })[0]
        $sharedOnly = @($config.sets | Where-Object { $_.id -eq "sharedonly" })[0]

        $identities = @(Get-DevWSRenameSetDedicatedIdentities -Set $target)
        Assert-Equal 1 $identities.Count "only the target set's dedicated apps are probed"
        Assert-Equal "secondary/firefox" ("$($identities[0].SetId)/$($identities[0].ItemId)") "bounded identity is the target set's item"
        Assert-Equal 0 (@(Get-DevWSRenameSetDedicatedIdentities -Set $sharedOnly)).Count "a shared-only set has no ownership identities"

        $state = [pscustomobject]@{ Mode = "owner"; Calls = 0; Descriptors = $null; Throws = $false }
        $reader = {
            param($Hwnd, $BoundDescriptors)
            $state.Calls++
            $state.Descriptors = $BoundDescriptors
            if ($state.Throws) { throw "HWND 4242 carries multiple DevWS ownership properties (DevWS.Owner.v1.secondary/firefox). Refusing to guess an owner." }
            if ($state.Mode -eq "owner" -and $Hwnd -eq 4242) {
                return [pscustomobject]@{ SetId = "secondary"; ItemId = "firefox"; PropertyName = "DevWS.Owner.v1.secondary/firefox"; Hwnd = $Hwnd }
            }
            return $null
        }
        $candidates = @(
            (New-TestWindowCandidate -Hwnd 4242 -ProcessName "firefox" -ProcessPath "C:\PF\firefox.exe" -Title "Mozilla Firefox"),
            (New-TestWindowCandidate -Hwnd 5000 -ProcessName "codex" -ProcessPath "C:\PF\codex.exe" -Title "Codex")
        )

        $blockers = @(Get-DevWSRenameSetOwnershipBlockers -Set $target -Candidates $candidates -OwnershipReader $reader)
        Assert-Equal 1 $blockers.Count "a live exact old-scoped dedicated owner blocks the rename"
        Assert-Equal "secondary/firefox" ([string]$blockers[0].ScopedId) "blocker scoped id"
        Assert-Equal 4242 ([long]$blockers[0].Hwnd) "blocker HWND"
        Assert-Equal "firefox" ([string]$blockers[0].ProcessName) "blocker process"
        Assert-Equal "Mozilla Firefox" ([string]$blockers[0].Title) "blocker title"

        $descriptorNames = @($state.Descriptors | ForEach-Object { [string]$_.PropertyName })
        Assert-Equal 1 $descriptorNames.Count "exactly one bounded descriptor"
        Assert-Equal "DevWS.Owner.v1.secondary/firefox" $descriptorNames[0] "lookups are bounded to the target set's dedicated app"
        Assert-NotContains ($descriptorNames -join ",") "main/firefox" "another set's identical dedicated item can never block"
        Assert-NotContains ($descriptorNames -join ",") "codex" "shared apps never produce ownership descriptors"

        $state.Mode = "none"
        $none = @(Get-DevWSRenameSetOwnershipBlockers -Set $target -Candidates $candidates -OwnershipReader $reader)
        Assert-Equal 0 $none.Count "no live owner allows the rename"

        $state.Calls = 0
        $sharedBlockers = @(Get-DevWSRenameSetOwnershipBlockers -Set $sharedOnly -Candidates $candidates -OwnershipReader $reader)
        Assert-Equal 0 $sharedBlockers.Count "a shared-only set never blocks"
        Assert-Equal 0 $state.Calls "a shared-only set never even reads ownership"

        $state.Throws = $true
        $message = Get-ThrownMessage { Get-DevWSRenameSetOwnershipBlockers -Set $target -Candidates $candidates -OwnershipReader $reader }
        Assert-Contains $message "Cannot rename set 'secondary'" "corruption refuses the rename"
        Assert-Contains $message "failed closed" "corruption is fail-closed"
        $state.Throws = $false

        $message = Format-DevWSSetRenameOwnershipRefusal -SetId "secondary" -Blockers $blockers
        Assert-Contains $message "Cannot rename set 'secondary'" "formatter names the set"
        Assert-Contains $message "dedicated app 'secondary/firefox'" "formatter names the scoped app"
        Assert-Contains $message "HWND 4242" "formatter names the live window"
        Assert-Contains $message "Close that app and retry" "formatter gives the recovery action"
    }

    Test-Case "CLI rename saves once and syncs derived hotkeys only when bindings were retargeted" {
        $dir = Join-Path $TestRoot "rename-cli"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $configPath = Join-Path $dir "workspace.json"
        $config = ConvertTo-TestConfig -DefaultSet "main" -Bindings @(
            [ordered]@{ hotkey = "alt+shift+u"; setId = "secondary" }
        ) -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TerminalDefinition -Id "studio"),
                (New-TestMatchedAppDefinition -Id "appX" -MatchKind "exe" -MatchValue "app-x.exe" -InstanceMode "dedicated")
            ))
        )
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath -Encoding UTF8

        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $configPath
        $script:renameSyncCalls = 0
        $script:renamePreflightCalls = 0
        $script:renameBlock = $false
        $script:renameSyncThrows = $false
        $script:renameFileAtSync = $null

        try {
            function Sync-DevWSBindings {
                param($Config, [string]$InstallRoot, [string]$StateRoot, [string]$StartupPath, [switch]$SkipReload)
                $script:renameSyncCalls++
                if ($script:renameSyncThrows) { throw "simulated hotkey integration failure" }
                $script:renameFileAtSync = [System.IO.File]::ReadAllText($configPath)
                return [pscustomobject]@{ Status = "current"; Path = $null; CorePath = $null; Reloaded = $true }
            }
            function Get-DevWSRenameSetOwnershipBlockers {
                param($Set, $Candidates, $OwnershipReader)
                $script:renamePreflightCalls++
                if (-not $script:renameBlock) { return @() }
                return @([pscustomobject]@{
                    SetId = [string]$Set.id; ItemId = "appX"; ScopedId = "$([string]$Set.id)/appX"
                    Hwnd = 4242; ProcessName = "app-x"; Title = "App X"
                })
            }

            $output = (Invoke-DevWSRenameSet -OldReference "secondary" -NewId "development" 6>&1 | Out-String)
            Assert-Equal 1 $script:renameSyncCalls "one derived sync after a binding-rewriting rename"
            Assert-Equal 1 $script:renamePreflightCalls "semantic rename ran the ownership preflight"
            Assert-Contains $output "Renamed set 'secondary' -> 'development'" "factual rename line"
            Assert-Contains $output "1 launch binding(s) retargeted" "binding retarget reported"
            Assert-Contains $output "reset-terminals development" "cwd boundary explained for a set with terminals"
            Assert-Contains $output "not required" "reset is never implied to be mandatory"

            $atSync = $script:renameFileAtSync | ConvertFrom-Json
            Assert-Equal "development" ([string]$atSync.sets[1].id) "canonical save happened before the derived sync"

            $reloaded = Read-DevWSConfigFile -Path $configPath
            Assert-Equal "development" ([string]$reloaded.sets[1].id) "rename persisted"
            Assert-Equal "development" ([string]$reloaded.bindings[0].setId) "binding retargeted"
            Assert-Equal "alt+shift+u" ([string]$reloaded.bindings[0].hotkey) "hotkey unchanged"

            # Exact-same no-op: no preflight, no sync, no write.
            $before = Get-FileBase64 -Path $configPath
            $noop = (Invoke-DevWSRenameSet -OldReference "development" -NewId "development" 6>&1 | Out-String)
            Assert-Contains $noop "nothing changed" "no-op reported cleanly"
            Assert-Equal 1 $script:renameSyncCalls "no-op performed no sync"
            Assert-Equal 1 $script:renamePreflightCalls "no-op performed no preflight"
            Assert-Equal $before (Get-FileBase64 -Path $configPath) "no-op wrote nothing"

            # Case-only: skips the ownership preflight, still regenerates derived hotkeys.
            Invoke-DevWSRenameSet -OldReference "development" -NewId "Development" | Out-Null
            Assert-Equal 1 $script:renamePreflightCalls "case-only rename skipped the ownership preflight"
            Assert-Equal 2 $script:renameSyncCalls "case-only casing change still regenerates derived hotkeys"
            $reloaded = Read-DevWSConfigFile -Path $configPath
            Assert-Equal "Development" ([string]$reloaded.bindings[0].setId) "case-only binding rewritten to the exact casing"

            # Blocked rename refuses before mutation.
            $script:renameBlock = $true
            $before = Get-FileBase64 -Path $configPath
            $message = Get-ThrownMessage { Invoke-DevWSRenameSet -OldReference "Development" -NewId "final" }
            Assert-Contains $message "Cannot rename set 'Development'" "blocked refusal names the set"
            Assert-Contains $message "still owns live window HWND 4242" "blocked refusal names the live owner"
            Assert-Contains $message "Close that app and retry" "blocked refusal is actionable"
            Assert-Equal $before (Get-FileBase64 -Path $configPath) "blocked rename wrote nothing"
            $script:renameBlock = $false

            # Sync failure keeps canonical save-first semantics.
            $script:renameSyncThrows = $true
            $message = Get-ThrownMessage { Invoke-DevWSRenameSet -OldReference "Development" -NewId "final" }
            Assert-Contains $message "WAS updated" "sync failure states canonical config was updated"
            Assert-Contains $message "ws sync-hotkeys" "sync failure names the recovery command"
            $reloaded = Read-DevWSConfigFile -Path $configPath
            Assert-Equal "final" ([string]$reloaded.sets[1].id) "canonical rename persisted despite the sync failure"
            Assert-Equal "final" ([string]$reloaded.bindings[0].setId) "binding rewrite persisted despite the sync failure"
            $script:renameSyncThrows = $false

            # A rename that rewrites no binding performs no derived sync.
            $dir2 = Join-Path $TestRoot "rename-cli-nobind"
            New-Item -ItemType Directory -Path $dir2 -Force | Out-Null
            $configPath2 = Join-Path $dir2 "workspace.json"
            $config2 = ConvertTo-TestConfig -DefaultSet "main" -Sets @(
                (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
                (New-TestSet -Id "secondary" -Windows @((New-TerminalDefinition -Id "studio")))
            )
            $config2 | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath2 -Encoding UTF8
            $env:DEVWS_CONFIG = $configPath2
            $script:renameSyncCalls = 0
            Invoke-DevWSRenameSet -OldReference "secondary" -NewId "development" | Out-Null
            Assert-Equal 0 $script:renameSyncCalls "a rename without binding rewrites performs no derived sync"
            $env:DEVWS_CONFIG = $configPath

            # Usage errors.
            $usage = Get-ThrownMessage { Invoke-DevWSRenameSet -OldReference "" -NewId "x" }
            Assert-Contains $usage "Usage: ws rename-set <old-set> <new-set>" "missing old id refused"
            $usage = Get-ThrownMessage { Invoke-DevWSRenameSet -OldReference "final" -NewId "" }
            Assert-Contains $usage "Usage: ws rename-set <old-set> <new-set>" "missing new id refused"
        }
        finally {
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }

        # Config-only discipline: exactly one canonical save; no live-window surface.
        $wsSource = Get-SourceOf "src\ws.ps1"
        $start = $wsSource.IndexOf("function Invoke-DevWSRenameSet")
        $end   = $wsSource.IndexOf("# --- CLI tools: set launch bindings", $start)
        Assert-True ($start -ge 0 -and $end -gt $start) "rename adapter region located"
        $region = $wsSource.Substring($start, $end - $start)
        Assert-Equal 1 ([regex]::Matches($region, "Save-DevWSConfig -Config").Count) "exactly one canonical save"
        foreach ($forbidden in @(
            "Invoke-DevWSWorkerRequest", "New-DevWSElevatedBrokerPrepare", "Invoke-DevWSReset",
            "Close-DevWSWindowHwnd", "Focus-DevWSWindowHwnd", "Move-DevWSWindowHwnd",
            "Set-DevWSAppOwnership", "Remove-DevWSAppOwnership", "Invoke-DevWSLaunch"
        )) {
            Assert-NotContains $region $forbidden "rename never touches live windows: $forbidden"
        }
        Assert-Contains $region "Get-DevWSRenameSetOwnershipBlockers" "rename runs the bounded ownership preflight"
        Assert-Contains $region "Invoke-DevWSBindingDerivedSync" "rename reconciles derived hotkeys through the shared path"
    }

    Test-Case "rename leaves cwd tracking scoped to the old set and writes no state" {
        $dir = Join-Path $TestRoot "rename-cwd"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $configPath = Join-Path $dir "workspace.json"
        $config = ConvertTo-TestConfig -DefaultSet "main" -Bindings @(
            [ordered]@{ hotkey = "alt+shift+u"; setId = "secondary" }
        ) -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
            (New-TestSet -Id "secondary" -Windows @((New-TerminalDefinition -Id "studio" -WindowId "DevWS-rename-studio")))
        )
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath -Encoding UTF8

        $stateDir = Join-Path $dir "state"
        New-Item -ItemType Directory -Path $stateDir -Force | Out-Null

        $savedConfig = $env:DEVWS_CONFIG
        $savedState  = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $configPath
        $env:DEVWS_STATE_ROOT = $stateDir

        try {
            function Sync-DevWSBindings {
                param($Config, [string]$InstallRoot, [string]$StateRoot, [string]$StartupPath, [switch]$SkipReload)
                return [pscustomobject]@{ Status = "current"; Path = $null; CorePath = $null; Reloaded = $true }
            }
            function Get-DevWSRenameSetOwnershipBlockers { param($Set, $Candidates, $OwnershipReader) return @() }

            $ctxOld = New-DevWSCwdTrackingSession -SetId "secondary" -TerminalId "studio" -WindowId "DevWS-rename-studio" -TabIndex 0
            $sessionOldPath     = Get-DevWSCwdSessionPath -SetId "secondary" -TerminalId "studio" -TabIndex 0
            $publicationOldPath = Get-DevWSCwdPublicationPath -SetId "secondary" -TerminalId "studio" -TabIndex 0
            New-Item -ItemType Directory -Path (Split-Path -Parent $publicationOldPath) -Force | Out-Null
            $myStart = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")
            [System.IO.File]::WriteAllText($publicationOldPath, (([ordered]@{
                version = 1; setId = "secondary"; terminalId = "studio"; windowId = "DevWS-rename-studio"
                sessionId = $ctxOld.SessionId; shellPid = $PID; shellStartTimeUtc = $myStart; cwd = $TestRoot
            }) | ConvertTo-Json -Compress), [System.Text.UTF8Encoding]::new($false))

            $sessionBefore     = Get-FileBase64 -Path $sessionOldPath
            $publicationBefore = Get-FileBase64 -Path $publicationOldPath

            $resolvedOld = Resolve-DevWSTrackedCwd -SetId "secondary" -TerminalId "studio"
            Assert-Equal "available" ([string]$resolvedOld.Status) "the old-set generation is genuinely valid (control)"
            $resolvedNew = Resolve-DevWSTrackedCwd -SetId "development" -TerminalId "studio"
            Assert-Equal "unavailable" ([string]$resolvedNew.Status) "the semantic new set cannot consume the old generation"
            Assert-Equal "expected-missing" ([string]$resolvedNew.Reason) "refusal reason is the missing new-set expected record"

            # Even a copied pair fails set matching.
            $sessionNewPath     = Get-DevWSCwdSessionPath -SetId "development" -TerminalId "studio" -TabIndex 0
            $publicationNewPath = Get-DevWSCwdPublicationPath -SetId "development" -TerminalId "studio" -TabIndex 0
            New-Item -ItemType Directory -Path (Split-Path -Parent $sessionNewPath) -Force | Out-Null
            New-Item -ItemType Directory -Path (Split-Path -Parent $publicationNewPath) -Force | Out-Null
            Copy-Item -LiteralPath $sessionOldPath -Destination $sessionNewPath -Force
            Copy-Item -LiteralPath $publicationOldPath -Destination $publicationNewPath -Force
            $resolvedCopied = Resolve-DevWSTrackedCwd -SetId "development" -TerminalId "studio"
            Assert-Equal "unavailable" ([string]$resolvedCopied.Status) "a copied-under-the-new-identity pair is refused"
            Assert-Equal "set-mismatch" ([string]$resolvedCopied.Reason) "wrong-identity copies fail set matching"
            Remove-Item -LiteralPath $sessionNewPath -Force
            Remove-Item -LiteralPath $publicationNewPath -Force

            # Run the real CLI adapter: it must not touch any state file.
            Invoke-DevWSRenameSet -OldReference "secondary" -NewId "development"

            $reloaded = Read-DevWSConfigFile -Path $configPath
            Assert-Equal "development" ([string]$reloaded.sets[1].id) "rename persisted"
            Assert-Equal $sessionBefore (Get-FileBase64 -Path $sessionOldPath) "old expected generation bytes untouched"
            Assert-Equal $publicationBefore (Get-FileBase64 -Path $publicationOldPath) "old publication bytes untouched"
            Assert-Equal $false (Test-Path -LiteralPath $sessionNewPath) "rename created no new-set tracking state"
            Assert-Equal $false (Test-Path -LiteralPath (Join-Path $stateDir "runtime-state.json")) "rename wrote no runtime state"

            # Fresh generation under the new identity; old bytes still untouched.
            $ctxNew = New-DevWSCwdTrackingSession -SetId "development" -TerminalId "studio" -WindowId "DevWS-rename-studio" -TabIndex 0
            $sessionNew = Read-DevWSCwdStateFile -Path $sessionNewPath
            Assert-Equal $true ([bool]$sessionNew.Ok) "fresh generation exists after recreation-equivalent setup"
            Assert-Equal "development" ([string]$sessionNew.Record.setId) "fresh generation carries the new set id"
            Assert-Equal $ctxNew.SessionId ([string]$sessionNew.Record.sessionId) "fresh generation uses its own new session id"
            Assert-Equal $sessionBefore (Get-FileBase64 -Path $sessionOldPath) "old expected generation bytes remain untouched"

            # Case-only resolution keeps working (case-insensitive set identity).
            $ctxCase = New-DevWSCwdTrackingSession -SetId "P6R-Case" -TerminalId "studio" -WindowId "DevWS-rename-studio" -TabIndex 0
            $pubCase = Get-DevWSCwdPublicationPath -SetId "P6R-Case" -TerminalId "studio" -TabIndex 0
            New-Item -ItemType Directory -Path (Split-Path -Parent $pubCase) -Force | Out-Null
            [System.IO.File]::WriteAllText($pubCase, (([ordered]@{
                version = 1; setId = "P6R-Case"; terminalId = "studio"; windowId = "DevWS-rename-studio"
                sessionId = $ctxCase.SessionId; shellPid = $PID; shellStartTimeUtc = $myStart; cwd = $TestRoot
            }) | ConvertTo-Json -Compress), [System.Text.UTF8Encoding]::new($false))
            $resolvedCase = Resolve-DevWSTrackedCwd -SetId "p6r-case" -TerminalId "studio"
            Assert-Equal "available" ([string]$resolvedCase.Status) "case-only rename keeps tracking valid"

            # Unavailable decisions preserve the canonical effective paths.
            $terminal = [pscustomobject]@{
                id = "studio"; type = "terminal"; enabled = $true; windowId = "DevWS-rename-studio"
                path = "C:\A"; elevated = $true; activeTab = 1
                tabs = @(
                    [pscustomobject]@{ command = $null; args = @(); path = "C:\A\o0" },
                    [pscustomobject]@{ command = $null; args = @(); path = "C:\A\o1" },
                    [pscustomobject]@{ command = $null; args = @() }
                )
            }
            $decisions = @(
                [pscustomobject]@{ tabIndex = 0; hadOverride = $true; oldEffective = "C:\A\o0"; status = "unavailable"; reason = "expected-missing"; newCwd = $null },
                [pscustomobject]@{ tabIndex = 1; hadOverride = $true; oldEffective = "C:\A\o1"; status = "unavailable"; reason = "expected-missing"; newCwd = $null },
                [pscustomobject]@{ tabIndex = 2; hadOverride = $false; oldEffective = "C:\A"; status = "unavailable"; reason = "expected-missing"; newCwd = $null }
            )
            Invoke-DevWSTerminalSaveState -Terminal $terminal -TabDecisions $decisions
            Assert-Equal "C:\A" ([string]$terminal.path) "unavailable cwd preserves terminal.path"
            Assert-Equal "C:\A\o0" ([string]$terminal.tabs[0].path) "tab 0 override preserved"
            Assert-Equal "C:\A\o1" ([string]$terminal.tabs[1].path) "tab 1 override preserved"
            Assert-Equal $false ($terminal.tabs[2].PSObject.Properties.Name -contains "path") "no redundant tab override materialized"
        }
        finally {
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "preserved windowId recovery makes old runtime cache keys disposable" {
        $presenceConfig = ConvertTo-TestConfig -DefaultSet "development" -Sets @(
            (New-TestSet -Id "development" -Windows @((New-TerminalDefinition -Id "studio" -WindowId "DevWS-rename-studio")))
        )

        $state = New-DevWSRuntimeState
        $state.terminals[(Get-DevWSRuntimeTerminalKey -SetId "secondary" -Id "studio")] = [pscustomobject]@{ windowId = "DevWS-rename-studio"; hwnd = 999 }

        Assert-Equal $null (Get-DevWSRuntimeTerminal -State $state -SetId "development" -Id "studio") "stale old-set key is not consulted for the semantic new id"
        Assert-True ($null -ne (Get-DevWSRuntimeTerminal -State $state -SetId "SECONDARY" -Id "studio")) "old-set lookup stays case-insensitive"

        $reader = { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = @("DevWS-rename-studio"); RawCount = 1 } }
        $processName = { param([long]$Hwnd) return "WindowsTerminal" }

        $snapshot = Get-DevWSTerminalPresenceSnapshot -Config $presenceConfig -SetId "development" -State $state -WtHwnds @(777) -CandidateReader $reader -ProcessNameProvider $processName

        Assert-Equal 1 ([int]$snapshot.Counts.Present) "windowId recovery finds the running terminal under the new set"
        Assert-Equal "snapshot" ([string]$snapshot.Terminals[0].Source) "recovery used the preserved windowId, not the old runtime key"
        Assert-Equal 777 ([long]$snapshot.Terminals[0].Hwnd) "recovery resolves the preserved live window"
        Assert-Equal 0 ([int]$snapshot.Stats.StateHits) "the stale old-set entry was never read"

        $stateDir = Join-Path $TestRoot "rename-runtime"
        New-Item -ItemType Directory -Path $stateDir -Force | Out-Null
        $statePath = Join-Path $stateDir "runtime-state.json"
        Update-DevWSRuntimeTerminal -SetId "development" -Id "studio" -WindowId "DevWS-rename-studio" -Hwnd 777 -Path $statePath
        $reloaded = Read-DevWSRuntimeState -Path $statePath
        Assert-True ($null -ne (Get-DevWSRuntimeTerminal -State $reloaded -SetId "development" -Id "studio")) "normal recovery populates the new key"
        Assert-True ($null -ne (Get-DevWSRuntimeTerminal -State $state -SetId "secondary" -Id "studio")) "old key stays disposable, never migrated or deleted"
        $snapshot2 = Get-DevWSTerminalPresenceSnapshot -Config $presenceConfig -SetId "development" -State $reloaded -WtHwnds @(777) -CandidateReader $reader -ProcessNameProvider $processName
        Assert-Equal "state" ([string]$snapshot2.Terminals[0].Source) "the next plan uses the state-first path with the new key"
    }

    Test-Case "rename-set help metadata and exact CLI grammar" {
        $entry = @(Get-DevWSHelpCommandInfo | Where-Object { $_.Name -eq "rename-set" })
        Assert-Equal 1 $entry.Count "rename-set is in the command catalog"
        Assert-Equal "ws rename-set <old-set> <new-set>" ([string]$entry[0].Usage) "exact usage string"
        Assert-Equal "Workspace sets" ([string]$entry[0].Section) "workspace sets section"
        Assert-True (@($entry[0].Details).Count -ge 3) "rename details are documented"
        Assert-True (@(Get-DevWSHelpTopicByName -Name "sets").Commands -contains "rename-set") "the sets topic lists rename-set"

        $rendered = (Show-DevWSHelpCommand -Command $entry[0] 6>&1 | Out-String)
        Assert-Contains $rendered "ws rename-set <old-set> <new-set>" "ws help rename-set renders"

        $configPath = New-WritableConfigCopy "rename-help"

        $topic = Invoke-WsCli -ConfigPath $configPath -Arguments @("help", "sets")
        Assert-Equal 0 $topic.ExitCode "ws help sets exit"
        Assert-Contains $topic.Output "rename-set" "ws help sets exposes rename-set"

        $all = Invoke-WsCli -ConfigPath $configPath -Arguments @("help", "all")
        Assert-Equal 0 $all.ExitCode "ws help all exit"
        Assert-Contains $all.Output "ws rename-set <old-set> <new-set>" "ws help all exposes rename-set"

        $command = Invoke-WsCli -ConfigPath $configPath -Arguments @("help", "rename-set")
        Assert-Equal 0 $command.ExitCode "ws help rename-set exit"
        Assert-Contains $command.Output "ws rename-set <old-set> <new-set>" "ws help rename-set renders through the CLI"

        $bare = Invoke-WsCli -ConfigPath $configPath -Arguments @()
        Assert-Equal 0 $bare.ExitCode "bare ws exit"
        Assert-NotContains $bare.Output "rename-set" "bare ws stays intentionally unchanged"

        # Exact grammar through the real dispatcher (no config load needed).
        foreach ($badArguments in @(
            @("rename-set"),
            @("rename-set", "main"),
            @("rename-set", "main", "x", "extra")
        )) {
            $result = Invoke-WsCli -ConfigPath $configPath -Arguments $badArguments
            Assert-True ($result.ExitCode -ne 0) ("rejected grammar: " + ($badArguments -join " "))
            Assert-Contains $result.Output "Usage: ws rename-set <old-set> <new-set>" ("usage error: " + ($badArguments -join " "))
        }

        # Full-process semantic + case-only + no-op + collision on a disposable config.
        $dir = Join-Path $TestRoot "rename-cli-full"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $configPath2 = Join-Path $dir "workspace.json"
        $config = ConvertTo-TestConfig -DefaultSet "main" -Sets @(
            (New-TestSet -Id "main" -Windows @((New-TerminalDefinition -Id "slot"))),
            (New-TestSet -Id "secondary" -Windows @(
                (New-TerminalDefinition -Id "studio" -WindowId "DevWS-rename-full"),
                (New-TestMatchedAppDefinition -Id "appX" -MatchKind "exe" -MatchValue "no-such-rename-app.exe" -InstanceMode "dedicated")
            ))
        )
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath2 -Encoding UTF8

        $stateRoot = Join-Path $dir "state"
        New-Item -ItemType Directory -Path $stateRoot -Force | Out-Null

        $semantic = Invoke-WsCli -ConfigPath $configPath2 -StateRoot $stateRoot -Arguments @("rename-set", "SECONDARY", "development")
        Assert-Equal 0 $semantic.ExitCode "full CLI semantic rename exit"
        Assert-Contains $semantic.Output "Renamed set 'secondary' -> 'development'" "full CLI reports the rename"
        Assert-Contains $semantic.Output "reset-terminals development" "full CLI explains the cwd boundary"
        $reloaded = Read-DevWSConfigFile -Path $configPath2
        Assert-Equal "development" ([string]$reloaded.sets[1].id) "full CLI persisted the rename"
        Assert-Equal "DevWS-rename-full" ([string]$reloaded.sets[1].windows[0].windowId) "full CLI preserved the windowId"
        Assert-Equal $false (Test-Path -LiteralPath (Join-Path $stateRoot "runtime-state.json")) "full CLI wrote no runtime state"

        $caseOnly = Invoke-WsCli -ConfigPath $configPath2 -StateRoot $stateRoot -Arguments @("rename-set", "development", "Development")
        Assert-Equal 0 $caseOnly.ExitCode "full CLI case-only rename exit"
        Assert-Contains $caseOnly.Output "(casing only)" "full CLI reports casing-only"
        Assert-NotContains $caseOnly.Output "reset-terminals" "case-only rename shows no stale-cwd note"
        $reloaded = Read-DevWSConfigFile -Path $configPath2
        Assert-Equal "Development" ([string]$reloaded.sets[1].id) "full CLI stored the exact requested casing"

        $before = Get-FileBase64 -Path $configPath2
        $noop = Invoke-WsCli -ConfigPath $configPath2 -StateRoot $stateRoot -Arguments @("rename-set", "Development", "Development")
        Assert-Equal 0 $noop.ExitCode "full CLI no-op exit"
        Assert-Contains $noop.Output "nothing changed" "no-op reported"
        Assert-Equal $before (Get-FileBase64 -Path $configPath2) "no-op wrote no canonical bytes"

        # The exact grammar has no -Force option: the global top-level switch is
        # rejected by the rename-set dispatcher instead of being silently
        # ignored. The rejection precedes any config load, ownership preflight,
        # canonical save or derived hotkey sync.
        Assert-NotContains ([string]$entry[0].Usage) "-Force" "rename-set never advertises -Force"

        $beforeForce = Get-FileBase64 -Path $configPath2
        $forced = Invoke-WsCli -ConfigPath $configPath2 -StateRoot $stateRoot -Arguments @("rename-set", "Development", "forced", "-Force")
        Assert-True ($forced.ExitCode -ne 0) "-Force is rejected with a nonzero exit"
        Assert-Contains $forced.Output "Usage: ws rename-set <old-set> <new-set>" "-Force rejection prints the exact usage"
        Assert-NotContains $forced.Output "Renamed set" "-Force rejection never renames"
        Assert-NotContains $forced.Output "generated hotkeys" "-Force rejection never syncs derived hotkeys"
        Assert-Equal $beforeForce (Get-FileBase64 -Path $configPath2) "-Force rejection wrote no canonical bytes"
        $reloaded = Read-DevWSConfigFile -Path $configPath2
        Assert-Equal "Development" ([string]$reloaded.sets[1].id) "-Force rejection left the set id unchanged"

        # No config is needed: the grammar rejection cannot have reached the
        # ownership preflight, so the preflight is not required to run.
        $missingConfig = Join-Path $dir "missing-workspace.json"
        $forcedNoConfig = Invoke-WsCli -ConfigPath $missingConfig -Arguments @("rename-set", "a", "b", "-Force")
        Assert-True ($forcedNoConfig.ExitCode -ne 0) "-Force rejection needs no config"
        Assert-Contains $forcedNoConfig.Output "Usage: ws rename-set <old-set> <new-set>" "-Force rejection precedes config load / preflight / save / sync"

        $before = Get-FileBase64 -Path $configPath2
        $collision = Invoke-WsCli -ConfigPath $configPath2 -StateRoot $stateRoot -Arguments @("rename-set", "Development", "main")
        Assert-True ($collision.ExitCode -ne 0) "collision refused through the full CLI"
        Assert-Contains $collision.Output "already exists" "collision message"
        Assert-Equal $before (Get-FileBase64 -Path $configPath2) "collision wrote no canonical bytes"
    }

    Write-Host ""
    Start-TestGroup -Name 'stage1-coordinator' -Title 'Stage 1 warm coordinator'

    Test-Case "Stage 1 coordinator protocol validates strictly" {
        $version = Get-DevWSCoordinatorProtocolVersion

        $ok = Test-DevWSCoordinatorRequest -Line ('{"version":' + $version + ',"command":"ping"}')
        Assert-Equal $true $ok.Ok "ping accepted"
        Assert-Equal "ping" $ok.Request.Command "ping command"
        Assert-Equal $null $ok.Request.SetId "ping has no setId"

        $ok = Test-DevWSCoordinatorRequest -Line ('{"version":' + $version + ',"command":"launch","setId":"main"}')
        Assert-Equal $true $ok.Ok "launch accepted"
        Assert-Equal "main" $ok.Request.SetId "setId carried"

        $ok = Test-DevWSCoordinatorRequest -Line ('{"version":' + $version + ',"command":"shutdown"}')
        Assert-Equal $true $ok.Ok "shutdown accepted"

        $ok = Test-DevWSCoordinatorRequest -Line ('{"version":' + $version + ',"command":"status"}')
        Assert-Equal $true $ok.Ok "status accepted"
        Assert-Equal "status" $ok.Request.Command "status command"
        Assert-Equal $null $ok.Request.SetId "status has no setId"

        foreach ($bad in @(
            '',
            'not json',
            '[]',
            '"text"',
            '{"version":2,"command":"ping"}',
            '{"version":1,"command":"invoke"}',
            '{"version":1,"command":"ping","script":"calc"}',
            '{"version":1,"command":"launch","setId":""}',
            '{"version":1,"command":"launch","setId":42}',
            '{"command":"ping"}'
        )) {
            $result = Test-DevWSCoordinatorRequest -Line $bad
            Assert-Equal $false $result.Ok "rejected: $bad"
        }

        $oversized = '{"version":1,"command":"ping","pad":"' + ('x' * 5000) + '"}'
        $result = Test-DevWSCoordinatorRequest -Line $oversized
        Assert-Equal $false $result.Ok "oversized request rejected"
        Assert-Contains $result.Error "protocol limit" "oversize names the limit"

        $coordinator = Get-SourceOf "src\lib\devws-coordinator.ps1"
        Assert-NotContains $coordinator "Invoke-Expression" "no dynamic script execution in the protocol path"
        Assert-Contains $coordinator "DevWS.Coordinator.v1" "pipe name contract present"
    }

    Test-Case "Stage 1 coordinator launch uses canonical default and explicit set semantics" {
        $target = Join-Path $TestRoot "stage1-coordinator-config\workspace.json"
        New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null

        ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @()),
            (New-TestSet -Id "secondary" -Windows @())
        ) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

        $config = Read-DevWSConfigFile -Path $target

        $defaultResult = Invoke-DevWSCoordinatorLaunch -Config $config
        Assert-Equal $true $defaultResult.ok "default launch succeeds"
        Assert-Equal "main" $defaultResult.setId "default launch follows defaultSet"
        Assert-Equal $true $defaultResult.noEnabledItems "empty default set is a friendly no-op"

        $explicitResult = Invoke-DevWSCoordinatorLaunch -Config $config -SetId "secondary"
        Assert-Equal $true $explicitResult.ok "explicit launch succeeds"
        Assert-Equal "secondary" $explicitResult.setId "explicit launch is set-scoped"

        $unknown = Invoke-DevWSCoordinatorLaunch -Config $config -SetId "nope"
        Assert-Equal $false $unknown.ok "unknown set fails structurally"
        Assert-Contains ([string]$unknown.message) "Unknown workspace set" "unknown set names the failure"

        $coordinator = Get-SourceOf "src\lib\devws-coordinator.ps1"
        Assert-Contains $coordinator "Invoke-DevWSLaunchTransaction" "coordinator launch calls the canonical transaction"
        Assert-NotContains $coordinator "Get-DevWSAppWindowProbe" "no duplicated app policy in the coordinator library"

        $hostSource = Get-SourceOf "src\coordinator\coordinator.ps1"
        Assert-NotContains $hostSource "Invoke-DevWSAppLaunchCommand" "no duplicated launch policy in the coordinator host"
        Assert-NotContains $hostSource "Invoke-Expression" "no arbitrary execution in the coordinator host"
    }

    Test-Case "Stage 1 coordinator process is single-instance, strictly validated and restart-aware" {
        $fixture = New-InstallFixture "stage1-coordinator-live"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        New-Item -ItemType Directory -Path (Split-Path -Parent $fixture.Canonical) -Force | Out-Null
        ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @()),
            (New-TestSet -Id "secondary" -Windows @())
        ) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $fixture.Canonical -Encoding UTF8

        $pipe  = "DevWS.Stage1.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $mutex = "Local\DevWS.Stage1.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)

        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $fixture.Canonical

        function Invoke-Stage1Pipe([string]$PipeName, [string]$Json, [switch]$TwoLines) {
            $client = [System.IO.Pipes.NamedPipeClientStream]::new('.', $PipeName, [System.IO.Pipes.PipeDirection]::InOut)
            try {
                $client.Connect(5000)
                $enc = [System.Text.UTF8Encoding]::new($false)
                $writer = [System.IO.StreamWriter]::new($client, $enc, 8192, $true)
                $reader = [System.IO.StreamReader]::new($client, $enc, $false, 8192, $true)
                $writer.WriteLine($Json)
                $writer.Flush()
                $first = $reader.ReadLine()
                $second = $null
                if ($TwoLines) { $second = $reader.ReadLine() }
                return [pscustomobject]@{ First = $first; Second = $second }
            }
            finally {
                $client.Dispose()
            }
        }

        $coordinator = $null
        $second      = $null
        $stale       = $null

        try {
            $coordinator = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', (Join-Path $fixture.Root "app\coordinator.ps1"),
                '-PipeName', $pipe, '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root
            ) -PassThru -WindowStyle Hidden

            $ready = $false
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                try {
                    $probe = Invoke-Stage1Pipe $pipe '{"version":1,"command":"ping"}'
                    if ($probe.First) { $ready = $true; break }
                }
                catch {
                    Start-Sleep -Milliseconds 250
                }
            }

            Assert-Equal $true $ready "live coordinator became ready"
            $ping = $probe.First | ConvertFrom-Json
            Assert-Equal $true ([bool]$ping.ok) "ping ok"
            Assert-Equal $coordinator.Id $ping.pid "ping identifies the coordinator process"

            $second = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', (Join-Path $fixture.Root "app\coordinator.ps1"),
                '-PipeName', ($pipe + ".x"), '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root, '-NoWarmup'
            ) -PassThru -WindowStyle Hidden

            $secondExited = $second.WaitForExit(20000)
            Assert-Equal $true $secondExited "second instance exits cleanly"
            Assert-Equal 0 $second.ExitCode "second instance exit code is 0"

            $malformed = (Invoke-Stage1Pipe $pipe 'not json at all').First | ConvertFrom-Json
            Assert-Equal $false ([bool]$malformed.ok) "malformed request rejected"

            $unsupported = (Invoke-Stage1Pipe $pipe '{"version":1,"command":"invoke"}').First | ConvertFrom-Json
            Assert-Equal $false ([bool]$unsupported.ok) "unsupported command rejected"

            $launch = Invoke-Stage1Pipe $pipe '{"version":1,"command":"launch"}' -TwoLines
            $ack = $launch.First | ConvertFrom-Json
            $done = $launch.Second | ConvertFrom-Json
            Assert-Equal $true ([bool]$ack.ok) "launch acknowledged immediately"
            Assert-Equal "accepted" ([string]$ack.status) "ack status"
            Assert-Equal $true ([bool]$done.ok) "launch completed"
            Assert-Equal "main" ([string]$done.setId) "live launch follows defaultSet"

            $unknown = Invoke-Stage1Pipe $pipe '{"version":1,"command":"launch","setId":"nope"}' -TwoLines
            $unknownSingle = $unknown.First | ConvertFrom-Json
            Assert-Equal $false ([bool]$unknownSingle.ok) "unknown set rejected before acceptance"

            $stop = Stop-DevWSCoordinator -PipeName $pipe -InstallRoot $fixture.Root -ConnectTimeoutMilliseconds 1000 -ResponseTimeoutMilliseconds 3000 -ExitTimeoutMilliseconds 15000
            Assert-Equal "stopped" $stop.State "coordinator shutdown helper reports stopped"
            Assert-Equal $coordinator.Id ([int]$stop.Pid) "shutdown response identifies the coordinator process"
            Assert-Equal $true ($coordinator.WaitForExit(15000)) "shutdown stops the coordinator"
            $coordinator = $null

            $stopAgain = Stop-DevWSCoordinator -PipeName $pipe -InstallRoot $fixture.Root -ConnectTimeoutMilliseconds 300 -ResponseTimeoutMilliseconds 500 -ExitTimeoutMilliseconds 1000
            Assert-Equal "absent" $stopAgain.State "repeated coordinator shutdown is a no-op"

            # Stale-deployed-code detection: a changed managed file makes the
            # running coordinator refuse and exit so fresh code can start.
            $stalePipe = $pipe + ".stale"
            $stale = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', (Join-Path $fixture.Root "app\coordinator.ps1"),
                '-PipeName', $stalePipe, '-MutexName', ($mutex + ".stale"), '-InstallRootOverride', $fixture.Root
            ) -PassThru -WindowStyle Hidden

            $staleReady = $false
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                try {
                    $probe2 = Invoke-Stage1Pipe $stalePipe '{"version":1,"command":"ping"}'
                    if ($probe2.First) { $staleReady = $true; break }
                }
                catch {
                    Start-Sleep -Milliseconds 250
                }
            }

            Assert-Equal $true $staleReady "stale-test coordinator became ready"
            Add-Content -LiteralPath (Join-Path $fixture.Root "app\lib\devws-coordinator.ps1") -Value "`n# stale test touch"

            $staleResponse = (Invoke-Stage1Pipe $stalePipe '{"version":1,"command":"ping"}').First | ConvertFrom-Json
            Assert-Equal $false ([bool]$staleResponse.ok) "changed deployment rejects the command"
            Assert-Equal "restart-required" ([string]$staleResponse.error) "changed deployment asks for a restart"
            Assert-Equal $true ($stale.WaitForExit(15000)) "changed deployment exits for recovery"
            $stale = $null
        }
        finally {
            if ($null -ne $coordinator -and -not $coordinator.HasExited) { Stop-Process -Id $coordinator.Id -Force -ErrorAction SilentlyContinue }
            if ($null -ne $second -and -not $second.HasExited) { Stop-Process -Id $second.Id -Force -ErrorAction SilentlyContinue }
            if ($null -ne $stale -and -not $stale.HasExited) { Stop-Process -Id $stale.Id -Force -ErrorAction SilentlyContinue }

            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "coordinator shutdown falls back only to verified executed-script identity and preserves unrelated PowerShell" {
