    Test-Case "Stage 1 observational status keeps a stale coordinator resident; ping still recovers" {
        # The dedicated status command exists exactly because the launch-path
        # ping makes a stale coordinator exit. status reports staleness and
        # leaves the host running; existing ping semantics are re-proven after.
        $fixture = New-InstallFixture "stage1-coordinator-status"
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        New-Item -ItemType Directory -Path (Split-Path -Parent $fixture.Canonical) -Force | Out-Null
        ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @()),
            (New-TestSet -Id "secondary" -Windows @())
        ) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $fixture.Canonical -Encoding UTF8

        $pipe  = "DevWS.Stage1.Status.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $mutex = "Local\DevWS.Stage1.Status.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)

        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $fixture.Canonical

        . (Join-Path $LibDir "devws-coordinator.ps1")

        $coordinator = $null

        try {
            $coordinator = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', (Join-Path $fixture.Root "app\coordinator.ps1"),
                '-PipeName', $pipe, '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root
            ) -PassThru -WindowStyle Hidden

            $status = $null
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                $status = Get-DevWSCoordinatorStatus -PipeName $pipe -TimeoutMilliseconds 1500

                if ($status.State -eq "ready") { break }
                Start-Sleep -Milliseconds 250
            }

            Assert-Equal "ready" $status.State "fixture coordinator answered status"
            Assert-Equal $true $status.GenerationCurrent "fresh fixture generation current"

            $residentGeneration = [string]$status.Generation

            # Change the fixture install so the deployed generation advances.
            Add-Content -LiteralPath (Join-Path $fixture.Root "app\lib\devws-coordinator.ps1") -Value "`n# stale test touch"

            # 1. observational status: stale, but the host STAYS RESIDENT
            $staleStatus = Get-DevWSCoordinatorStatus -PipeName $pipe -TimeoutMilliseconds 3000
            Assert-Equal "stale" $staleStatus.State "stale status reported"
            Assert-Equal $residentGeneration $staleStatus.Generation "resident generation reported"
            Assert-Equal $false $staleStatus.GenerationCurrent "generation currency false"
            Assert-Equal $false $coordinator.HasExited "stale coordinator stays resident after status"

            # 2. existing ping semantics unchanged: restart-required + exit
            $client = [System.IO.Pipes.NamedPipeClientStream]::new('.', $pipe, [System.IO.Pipes.PipeDirection]::InOut)

            try {
                $client.Connect(3000)
                $enc = [System.Text.UTF8Encoding]::new($false)
                $writer = [System.IO.StreamWriter]::new($client, $enc, 8192, $true)
                $reader = [System.IO.StreamReader]::new($client, $enc, $false, 8192, $true)
                $writer.WriteLine('{"version":1,"command":"ping"}')
                $writer.Flush()
                $response = $reader.ReadLine()
            }
            finally {
                $client.Dispose()
            }

            $ping = $response | ConvertFrom-Json
            Assert-Equal $false ([bool]$ping.ok) "stale ping still refuses"
            Assert-Equal "restart-required" ([string]$ping.error) "stale ping asks for a restart"
            Assert-Equal $true ($coordinator.WaitForExit(15000)) "stale coordinator still exits after ping"
            $coordinator = $null
        }
        finally {
            if ($null -ne $coordinator -and -not $coordinator.HasExited) { Stop-Process -Id $coordinator.Id -Force -ErrorAction SilentlyContinue }
            Remove-Item -LiteralPath $fixture.Root -Recurse -Force -ErrorAction SilentlyContinue
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Stage 1 batch kicks off every missing app before any finalization" {
        $target = New-Pass3ProbeConfig "stage1-batch-kickoff"
        $config = Read-DevWSConfigFile -Path $target
        $set    = @($config.sets | Where-Object { $_.id -eq "apps3" })[0]
        $apps   = @($set.windows | Where-Object { $_.type -eq "app" })

        $events = [System.Collections.Generic.List[string]]::new()
        $script:s1Probes = 0

        try {
            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                $script:s1Probes++
                $events.Add("probe $($script:s1Probes)")
                return @()
            }

            function Invoke-DevWSAppLaunchCommand {
                param($App)
                $events.Add("kick $($App.id)")
            }

            function Resolve-DevWSAppLaunchOutcome {
                param($Probed, $PreLaunchHwnds, $SetId, $ItemId, $Match, $Mode)
                $events.Add("evaluate $ItemId")
                return [pscustomobject]@{ Status = "resolved"; Hwnd = [long]9001; NeedsTagging = $false; Message = $null }
            }

            function Move-DevWSWindowHwnd {
                param([long]$Hwnd, $Layout, [string]$Context)
                $events.Add("move $Context")
            }

            $plan = New-DevWSAppLaunchPlan -Config $config -SetId "apps3" -Apps $apps
            $start = Start-DevWSAppLaunchPlan -Plan $plan
            $complete = Complete-DevWSAppLaunchPlan -Plan $plan -Config $config -Kicks $start.Kicks -PollMilliseconds 10

            $firstEvaluate = [array]::IndexOf($events, "evaluate renderer")

            foreach ($id in @("renderer", "editor42", "browser")) {
                $kickIndex = [array]::IndexOf($events, "kick $id")
                Assert-True ($kickIndex -ge 0) "kick $id present"
                Assert-True ($kickIndex -lt $firstEvaluate) "kick $id precedes the first finalization evaluation"
            }

            Assert-Equal 3 $script:s1Probes "one shared probe per phase tick (A + one refresh + one finalization tick)"
            Assert-Equal 0 @($plan.Failures).Count "prepare reports no failures"
            Assert-Equal 0 @($start.Failures).Count "kickoff reports no failures"
            Assert-Equal 0 @($complete.Failures).Count "finalization reports no failures"
            Assert-Equal 3 @($complete.Finalized).Count "all three apps finalized"
        }
        finally {
            $plan = $null
            $start = $null
            $complete = $null
        }
    }

    Test-Case "Stage 1 batch uses exactly one fresh refresh and one shared probe per tick" {
        $target = New-Pass3ProbeConfig "stage1-batch-refresh"
        $config = Read-DevWSConfigFile -Path $target
        $set    = @($config.sets | Where-Object { $_.id -eq "apps3" })[0]
        $apps   = @($set.windows | Where-Object { $_.type -eq "app" })

        $events = [System.Collections.Generic.List[string]]::new()
        $script:s1Probes = 0

        function Get-DevWSAppWindowProbe {
            param($Config, $Candidates, [switch]$TolerantOwnership)
            $script:s1Probes++
            $events.Add("probe $($script:s1Probes)")
            return @()
        }

        function Invoke-DevWSAppLaunchCommand {
            param($App)
            $events.Add("kick $($App.id)")
        }

        function Resolve-DevWSAppLaunchOutcome {
            param($Probed, $PreLaunchHwnds, $SetId, $ItemId, $Match, $Mode)
            $events.Add("evaluate $ItemId @$($script:s1Probes)")

            if ($script:s1Probes -ge 4) {
                return [pscustomobject]@{ Status = "resolved"; Hwnd = [long]9002; NeedsTagging = $false; Message = $null }
            }

            return [pscustomobject]@{ Status = "pending"; Hwnd = [long]0; NeedsTagging = $false; Message = $null }
        }

        function Move-DevWSWindowHwnd {
            param([long]$Hwnd, $Layout, [string]$Context)
            $events.Add("move $Context")
        }

        $plan = New-DevWSAppLaunchPlan -Config $config -SetId "apps3" -Apps $apps
        $start = Start-DevWSAppLaunchPlan -Plan $plan
        $complete = Complete-DevWSAppLaunchPlan -Plan $plan -Config $config -Kicks $start.Kicks -PollMilliseconds 10

        Assert-Equal 4 $script:s1Probes "initial + exactly one fresh refresh + one shared probe per finalization tick"
        Assert-Equal 6 @($events | Where-Object { $_ -like "evaluate *" }).Count "every launched app evaluated once per tick"
        Assert-True ([array]::IndexOf($events, "probe 2") -lt [array]::IndexOf($events, "kick renderer")) "the single refresh precedes kickoff"
        Assert-Equal 3 @($complete.Finalized).Count "all apps finalized"

        $launchLib = Get-SourceOf "src\lib\devws-launch.ps1"
        Assert-Contains $launchLib "exactly one fresh batch refresh" "single refresh documented in the canonical batch"
    }

    Test-Case "Stage 1 batch keeps one launch failure independent and ordered" {
        $target = New-Pass3ProbeConfig "stage1-batch-failure"
        $config = Read-DevWSConfigFile -Path $target
        $set    = @($config.sets | Where-Object { $_.id -eq "apps3" })[0]
        $apps   = @($set.windows | Where-Object { $_.type -eq "app" })

        $events = [System.Collections.Generic.List[string]]::new()
        $script:s1Probes = 0

        function Get-DevWSAppWindowProbe {
            param($Config, $Candidates, [switch]$TolerantOwnership)
            $script:s1Probes++
            return @()
        }

        function Invoke-DevWSAppLaunchCommand {
            param($App)
            $events.Add("kick $($App.id)")

            if ($App.id -eq "editor42") {
                throw "launch-boom-editor42"
            }
        }

        function Resolve-DevWSAppLaunchOutcome {
            param($Probed, $PreLaunchHwnds, $SetId, $ItemId, $Match, $Mode)

            if ($ItemId -eq "editor42") {
                throw "a failed kickoff must never be evaluated"
            }

            return [pscustomobject]@{ Status = "resolved"; Hwnd = [long]9003; NeedsTagging = $false; Message = $null }
        }

        function Move-DevWSWindowHwnd {
            param([long]$Hwnd, $Layout, [string]$Context)
            $events.Add("move $Context")
        }

        $plan = New-DevWSAppLaunchPlan -Config $config -SetId "apps3" -Apps $apps
        $start = Start-DevWSAppLaunchPlan -Plan $plan
        $complete = Complete-DevWSAppLaunchPlan -Plan $plan -Config $config -Kicks $start.Kicks -PollMilliseconds 10

        Assert-Equal "kick renderer|kick editor42|kick browser" (($events | Where-Object { $_ -like "kick *" }) -join "|") "later independent apps still kick after one launch failure"
        Assert-Equal 1 @($start.Failures).Count "the start phase reports the one launch failure"
        Assert-Contains $start.Failures[0].Message "launch-boom-editor42" "the exact launch failure is reported"
        Assert-Equal 2 @($complete.Finalized).Count "independent apps still finalize"
    }

    Test-Case "Stage 1 batch preserves adoption, ambiguity and owned-mismatch semantics" {
        $target = New-Pass3ProbeConfig "stage1-batch-semantics"
        $config = Read-DevWSConfigFile -Path $target
