                (New-TestProbedWindow -Hwnd 121 -ProcessName "editor42.exe" -ProcessPath "C:\Apps\editor42.exe"),
                (New-TestProbedWindow -Hwnd 122 -ProcessName "editor42.exe" -ProcessPath "C:\Apps\editor42.exe"),
                (New-TestProbedWindow -Hwnd 131 -ProcessName "other.exe" -ProcessPath "C:\Apps\other.exe" -OwnerKey "apps3/browser")
            )
        }

        function Set-DevWSAppOwnership {
            param([long]$Hwnd, [string]$SetId, [string]$ItemId)
