        function Test-DevWSAppOwnership {
            param([long]$Hwnd, [string]$SetId, [string]$ItemId)
            return $true
        }

        function Invoke-DevWSAppLaunchCommand {
            param($App)
            $script:s1Kicks++
        }

        function Move-DevWSWindowHwnd {
            param([long]$Hwnd, $Layout, [string]$Context)
            $events.Add("move $Context")
        }

        $plan = New-DevWSAppLaunchPlan -Config $config -SetId "apps3" -Apps $apps
        $start = Start-DevWSAppLaunchPlan -Plan $plan
        $complete = Complete-DevWSAppLaunchPlan -Plan $plan -Config $config -Kicks $start.Kicks -PollMilliseconds 10

        Assert-Equal 1 $script:s1Probes "no refresh when no app is pending"
        Assert-Equal 1 $script:s1Adopted.Count "the single unowned dedicated candidate was adopted"
        Assert-Equal 111 $script:s1Adopted[0] "adoption targets the exact candidate HWND"
        Assert-Equal "move app 'apps3/renderer'" (($events | Where-Object { $_ -like "move *" }) -join "|") "the adopted window was placed"
        Assert-Equal 0 $script:s1Kicks "nothing was launched"

        Assert-Equal 2 @($plan.Failures).Count "ambiguity and owned-mismatch refuse during prepare without launching"
        Assert-Contains $plan.Failures[0].Message "eligible matching windows" "shared ambiguity refusal reported first (configured order)"
        Assert-Contains $plan.Failures[1].Message "no longer matches" "dedicated owned-mismatch refusal reported second"
