    Write-Host ""
    Start-TestGroup -Name 'stage2-broker' -Title 'Stage 2 elevated broker and terminal plan'

    Test-Case "Stage 2 terminal plan: a validated state hit can never become missing" {
        # The highest-priority regression for the Stage-2C POC incident: a
        # state-validated terminal must survive as present/state in the FINAL
        # plan representation, in any configured order.
        foreach ($statePosition in @(0, 2)) {
            $terminals = @(
                (New-TerminalDefinition -Id "alpha" -WindowId "S2-alpha" -Path $TestRoot),
                (New-TerminalDefinition -Id "beta"  -WindowId "S2-beta"  -Path $TestRoot),
                (New-TerminalDefinition -Id "gamma" -WindowId "S2-gamma" -Path $TestRoot)
            )

            $config = ConvertTo-TestConfig -Windows $terminals
            $state = New-DevWSRuntimeState
            $stateHwnd = [long](710000 + $statePosition)
            Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id ([string]$terminals[$statePosition].id) -WindowId ([string]$terminals[$statePosition].windowId) -Hwnd $stateHwnd

            $plan = Get-DevWSTerminalLaunchPlan `
                -Config $config `
                -SetId "main" `
                -State $state `
                -Terminals $terminals `
                -WtHwnds @($stateHwnd) `
                -CandidateReader { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-alpha", "S2-beta", "S2-gamma")); RawCount = 2 } } `
                -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" } `
                -TrackingContextFactory { param($Terminal) return [pscustomobject]@{ TerminalId = [string]$Terminal.id } } `
                -CreateArgumentsFactory { param($Terminal, $Tracking) return @("new-tab") }

            $hit = @($plan.Terminals | Where-Object { [string]$_.TerminalId -eq [string]$terminals[$statePosition].id })[0]
            Assert-Equal "present" ([string]$hit.State) "state hit stays present (position $statePosition)"
            Assert-Equal "state" ([string]$hit.Source) "state hit keeps its source (position $statePosition)"
            Assert-Equal $stateHwnd ([long]$hit.Hwnd) "state hit keeps its exact HWND (position $statePosition)"
            Assert-Equal 1 ([int]$plan.Counts.Present) "exactly one present terminal"
            Assert-Equal 2 ([int]$plan.Counts.Missing) "unresolved terminals stay missing"
        }
    }

    Test-Case "Stage 2 terminal plan: stale and invalid state falls back safely" {
        $terminals = @(
            (New-TerminalDefinition -Id "dead"   -WindowId "S2-dead"   -Path $TestRoot),
            (New-TerminalDefinition -Id "crossed" -WindowId "S2-cross" -Path $TestRoot),
            (New-TerminalDefinition -Id "wrongtab" -WindowId "S2-wrong" -Path $TestRoot),
            (New-TerminalDefinition -Id "foreign" -WindowId "S2-foreign" -Path $TestRoot)
        )

        $config = ConvertTo-TestConfig -Windows $terminals
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "dead"     -WindowId "S2-dead"    -Hwnd 999999          # not in the WT set
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "crossed"  -WindowId "S2-other"   -Hwnd 720001          # expected id mismatch
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "wrongtab" -WindowId "S2-wrong"   -Hwnd 720002          # tab association missing
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "foreign"  -WindowId "S2-foreign" -Hwnd 720003          # non-WT process

        $reader = {
            param([long]$Hwnd)
            switch ($Hwnd) {
                720001 { return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-other")); RawCount = 2 } }
                720002 { return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("SomethingElse")); RawCount = 2 } }
                720003 { return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-foreign")); RawCount = 2 } }
                default { return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-dead")); RawCount = 2 } }
            }
        }

        $process = { param([long]$Hwnd) if ($Hwnd -eq 720003) { return "notepad" } return "WindowsTerminal" }

        $plan = Get-DevWSTerminalLaunchPlan `
            -Config $config -SetId "main" -State $state -Terminals $terminals `
            -WtHwnds @(720001, 720002, 720003) `
            -CandidateReader $reader -ProcessNameProvider $process `
            -TrackingContextFactory { param($Terminal) return [pscustomobject]@{ TerminalId = [string]$Terminal.id } } `
            -CreateArgumentsFactory { param($Terminal, $Tracking) return @("new-tab") }

        foreach ($terminal in $terminals) {
            $record = @($plan.Terminals | Where-Object { [string]$_.TerminalId -eq [string]$terminal.id })[0]
            Assert-Equal "missing" ([string]$record.State) "invalid state falls back to missing for $($terminal.id)"
        }

        Assert-Equal 4 ([int]$plan.Counts.Missing) "all four terminals are missing"
    }

