                if ($Hwnd -eq 730000) { return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-state")); RawCount = 2 } }
                return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-snap")); RawCount = 2 }
            } `
