    Test-Case "Stage 2 terminal plan: zero-tab reads retry boundedly" {
        $identityLib = Join-Path $LibDir "devws-uia.ps1"

        try {
            $script:s2ZtCalls = 0
            $script:s2ZtGive = 2   # first two reads return empty, third returns tabs

            function Get-DevWSTabElementsFromHwnd {
                param([long]$Hwnd)
                $script:s2ZtCalls++
                if ($script:s2ZtCalls -le $script:s2ZtGive) { return @() }
                return @([pscustomobject]@{ Current = [pscustomobject]@{ Name = "S2-zt" } })
            }

            function Test-DevWSWindowHwnd { param([long]$Hwnd) return $true }

            $read = Read-DevWSTerminalHwndTabs -Hwnd 740000 -EmptyRetryCount 2 -EmptyRetryDelayMilliseconds 1
            Assert-Equal 3 $script:s2ZtCalls "the zero-tab read retried until tabs materialized"
            Assert-Equal 1 ([int]$read.RawCount) "the retried read returns the real count"
            Assert-True ($read.TabNames.Contains("S2-zt")) "the retried read returns the real tab names"

            $script:s2ZtCalls = 0
            $script:s2ZtGive = 99  # never materializes
            $read2 = Read-DevWSTerminalHwndTabs -Hwnd 740010 -EmptyRetryCount 2 -EmptyRetryDelayMilliseconds 1
            Assert-Equal 3 $script:s2ZtCalls "an always-empty read stops after the bounded retries"
            Assert-Equal 0 ([int]$read2.RawCount) "the bounded miss reports zero tabs"
        }
        finally {
            . (Join-Path $LibDir "devws-uia.ps1")
            . (Join-Path $LibDir "devws-window-ops.ps1")
        }
    }

    Test-Case "Stage 2 terminal plan: duplicate windowId refuses and valid state wins" {
        $terminals = @((New-TerminalDefinition -Id "dup" -WindowId "S2-dup" -Path $TestRoot))
        $config = ConvertTo-TestConfig -Windows $terminals

        $shared = { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-dup")); RawCount = 2 } }

        # No state: two distinct HWNDs expose the same windowId -> ambiguous.
        $plan = Get-DevWSTerminalLaunchPlan `
            -Config $config -SetId "main" -State $null -Terminals $terminals `
            -WtHwnds @(750000, 750010) `
            -CandidateReader $shared `
            -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" } `
            -TrackingContextFactory { param($Terminal) return [pscustomobject]@{ TerminalId = [string]$Terminal.id } } `
            -CreateArgumentsFactory { param($Terminal, $Tracking) return @("new-tab") }

        Assert-Equal "ambiguous" ([string]$plan.Terminals[0].State) "duplicate windowId is ambiguous, never missing"
        Assert-Equal 0 ([long]$plan.Terminals[0].Hwnd) "ambiguous records carry no HWND"
        Assert-Contains ([string]$plan.Terminals[0].Diagnostic) "750000" "diagnostic lists the candidate HWNDs"
        Assert-Equal 0 ([int]$plan.Counts.Missing) "an ambiguous terminal is never missing"

        $script:s2Kicks = 0
        $kick = Start-DevWSTerminalLaunchPlan -Plan $plan -ProcessStarter { param($Record) $script:s2Kicks++ }
        Assert-Equal 0 $script:s2Kicks "ambiguous terminals are never launched"
        Assert-Equal 0 @($kick.Kicks).Count "no kick records for an ambiguous plan"
        Assert-Equal 0 @($kick.Failures).Count "ambiguity is not a kick failure"

        # Valid state HWND that is one of the duplicates: state wins.
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "dup" -WindowId "S2-dup" -Hwnd 750010

        $plan2 = Get-DevWSTerminalLaunchPlan `
            -Config $config -SetId "main" -State $state -Terminals $terminals `
            -WtHwnds @(750000, 750010) `
            -CandidateReader $shared `
            -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" } `
            -TrackingContextFactory { param($Terminal) return [pscustomobject]@{ TerminalId = [string]$Terminal.id } } `
            -CreateArgumentsFactory { param($Terminal, $Tracking) return @("new-tab") }

        Assert-Equal "present" ([string]$plan2.Terminals[0].State) "a validated state HWND resolves the duplicate"
        Assert-Equal "state" ([string]$plan2.Terminals[0].Source) "state source wins over ambiguity"
        Assert-Equal 750010 ([long]$plan2.Terminals[0].Hwnd) "the exact validated state HWND is used"
    }

