            -Config $config -SetId "main" -State $null -Terminals $terminals `
            -WtHwnds @(760010) `
            -CandidateReader { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-f1", "S2-f1")); RawCount = 2 } } `
            -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" } `
            -TrackingContextFactory { param($Terminal) return [pscustomobject]@{ TerminalId = [string]$Terminal.id } } `
            -CreateArgumentsFactory { param($Terminal, $Tracking) return @("new-tab") }

        Assert-Equal "present" ([string]$plan2.Terminals[0].State) "duplicate raw tab names still associate by name set"
        Assert-Equal 1 ([int]$plan2.Stats.UiaReads) "one candidate read, no state reads"
    }

    Test-Case "Stage 2 terminal kick: only missing terminals are invoked, back-to-back" {
        $terminals = @(
            (New-TerminalDefinition -Id "k1" -WindowId "S2-k1" -Path $TestRoot),
            (New-TerminalDefinition -Id "k2" -WindowId "S2-k2" -Path $TestRoot),
            (New-TerminalDefinition -Id "k3" -WindowId "S2-k3" -Path $TestRoot)
        )

        $config = ConvertTo-TestConfig -Windows $terminals
        $state = New-DevWSRuntimeState
        Set-DevWSRuntimeTerminal -State $state -SetId "main" -Id "k2" -WindowId "S2-k2" -Hwnd 770010

        $plan = Get-DevWSTerminalLaunchPlan `
            -Config $config -SetId "main" -State $state -Terminals $terminals `
            -WtHwnds @(770010) `
            -CandidateReader { param([long]$Hwnd) return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-k2")); RawCount = 2 } } `
            -ProcessNameProvider { param([long]$Hwnd) return "WindowsTerminal" } `
            -TrackingContextFactory { param($Terminal) return [pscustomobject]@{ TerminalId = [string]$Terminal.id } } `
            -CreateArgumentsFactory { param($Terminal, $Tracking) return @("new-tab", "-w", [string]$Terminal.windowId) }

        $script:s2KickOrder = [System.Collections.Generic.List[string]]::new()
        $script:s2KickArgs  = [System.Collections.Generic.List[object]]::new()

        $kick = Start-DevWSTerminalLaunchPlan -Plan $plan -ProcessStarter {
            param($Record)
            $script:s2KickOrder.Add([string]$Record.TerminalId) | Out-Null
            $script:s2KickArgs.Add(@($Record.CreateArguments)) | Out-Null
        }

        Assert-Equal "k1,k3" ($script:s2KickOrder -join ",") "only the two missing terminals are kicked, in configured order"
        Assert-Equal 2 @($kick.Kicks).Count "two kick records"
        Assert-Equal 0 @($kick.Failures).Count "no kick failures"
        Assert-Equal "new-tab,-w,S2-k1" ($script:s2KickArgs[0] -join ",") "exact argument boundaries are preserved"
        Assert-Equal "new-tab,-w,S2-k3" ($script:s2KickArgs[1] -join ",") "second invocation arguments preserved"
    }

    Test-Case "Stage 2 terminal completion: one snapshot finalizes every ready terminal" {
        $uiaLib = Join-Path $LibDir "devws-uia.ps1"
        $windowLib = Join-Path $LibDir "devws-window-ops.ps1"
        $stateLib = Join-Path $LibDir "devws-state.ps1"
        $identityLib = Join-Path $LibDir "devws-identity.ps1"

        try {
            $script:s2Snapshots = 0

            function Move-DevWSWindowHwnd { param([long]$Hwnd, $Layout, [string]$Context) }
            function Select-DevWSTabByIndexFromHwnd { param([long]$Hwnd, [int]$Index, [string]$Context) return $true }
            function Update-DevWSRuntimeTerminal { param([string]$SetId, [string]$Id, [string]$WindowId, $Hwnd, [string]$Path) }
            function Test-DevWSProcessNameIsWindowsTerminal { param([string]$ProcessName) return $true }
            function Test-DevWSCreatedTabCount { param([int]$ActualCount, [int]$ConfiguredCount) return ($ActualCount -le $ConfiguredCount) }

            $terminals = @(
                (New-TerminalDefinition -Id "c1" -WindowId "S2-c1" -Path $TestRoot),
                (New-TerminalDefinition -Id "c2" -WindowId "S2-c2" -Path $TestRoot),
                (New-TerminalDefinition -Id "c3" -WindowId "S2-c3" -Path $TestRoot)
            )

            $records = @()
            for ($i = 0; $i -lt $terminals.Count; $i++) {
                $records += [pscustomobject]@{
                    Order = $i; Terminal = $terminals[$i]; TerminalId = [string]$terminals[$i].id; SetId = "main"
                    WindowId = [string]$terminals[$i].windowId; ActiveTab = 0; State = "missing"; Source = "fast-missing"
                    Hwnd = 0; TrackingContext = $null; CreateArguments = @("new-tab"); Diagnostic = $null; Error = $null
                }
            }

            $plan = [pscustomobject]@{
                PlanId = "s2c"; SetId = "main"; WtHwnds = @(); WtToken = ""
                Terminals = $records
                Counts = [pscustomobject]@{ Present = 0; Missing = 3; Ambiguous = 0; Failed = 0 }
            }

            $kicks = @()
            for ($i = 0; $i -lt 3; $i++) {
                $kicks += [pscustomobject]@{ Order = $i; TerminalId = [string]$terminals[$i].id; WindowId = [string]$terminals[$i].windowId; CreateArguments = @("new-tab"); StartedAtUtc = [DateTimeOffset]::UtcNow; DeadlineUtc = [DateTimeOffset]::UtcNow.AddSeconds(15) }
            }

            $kickResult = [pscustomobject]@{ Kicks = $kicks; Failures = @() }

            $summary = Complete-DevWSTerminalLaunchPlan `
                -Plan $plan `
                -KickResult $kickResult `
                -PollMilliseconds 1 `
                -SnapshotProvider {
                    $script:s2Snapshots++
                    return @(
                        [pscustomobject]@{ Hwnd = 900000; ProcessName = "WindowsTerminal"; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-c1")); RawCount = 2 },
                        [pscustomobject]@{ Hwnd = 900010; ProcessName = "WindowsTerminal"; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-c2")); RawCount = 2 },
                        [pscustomobject]@{ Hwnd = 900020; ProcessName = "WindowsTerminal"; TabNames = (New-DevWSPresentTabNameSet -Names @("S2-c3")); RawCount = 2 }
                    )
                }

            Assert-Equal 1 $script:s2Snapshots "one batch snapshot resolved all three pending terminals"
            Assert-Equal 3 @($summary.Finalized).Count "all three terminals finalized"
            Assert-Equal 0 @($summary.Failures).Count "no failures"
            Assert-Equal "main/c1,main/c2,main/c3" (@($summary.Finalized) -join ",") "finalization order follows configured order"
        }
        finally {
            . $uiaLib
            . $windowLib
            . $stateLib
            . $identityLib
        }
    }

    Test-Case "Stage 2 terminal completion: failures aggregate in configured order" {
        $uiaLib = Join-Path $LibDir "devws-uia.ps1"
        $windowLib = Join-Path $LibDir "devws-window-ops.ps1"
        $stateLib = Join-Path $LibDir "devws-state.ps1"
        $identityLib = Join-Path $LibDir "devws-identity.ps1"

        try {
            function Move-DevWSWindowHwnd { param([long]$Hwnd, $Layout, [string]$Context) }
            function Select-DevWSTabByIndexFromHwnd { param([long]$Hwnd, [int]$Index, [string]$Context) return $true }
            function Update-DevWSRuntimeTerminal { param([string]$SetId, [string]$Id, [string]$WindowId, $Hwnd, [string]$Path) }
            function Test-DevWSProcessNameIsWindowsTerminal { param([string]$ProcessName) return $true }
            function Test-DevWSCreatedTabCount { param([int]$ActualCount, [int]$ConfiguredCount) return ($ActualCount -le $ConfiguredCount) }

            $terminals = @(
                (New-TerminalDefinition -Id "f1" -WindowId "S2-f1" -Path $TestRoot),
                (New-TerminalDefinition -Id "f2" -WindowId "S2-f2" -Path $TestRoot),
                (New-TerminalDefinition -Id "f3" -WindowId "S2-f3" -Path $TestRoot)
            )

            $records = @(
                [pscustomobject]@{ Order = 0; Terminal = $terminals[0]; TerminalId = "f1"; SetId = "main"; WindowId = "S2-f1"; ActiveTab = 0; State = "failed"; Source = $null; Hwnd = 0; TrackingContext = $null; CreateArguments = $null; Diagnostic = $null; Error = "classification failed" },
                [pscustomobject]@{ Order = 1; Terminal = $terminals[1]; TerminalId = "f2"; SetId = "main"; WindowId = "S2-f2"; ActiveTab = 0; State = "ambiguous"; Source = "snapshot"; Hwnd = 0; TrackingContext = $null; CreateArguments = $null; Diagnostic = "two Windows Terminal windows expose 'S2-f2'"; Error = $null },
                [pscustomobject]@{ Order = 2; Terminal = $terminals[2]; TerminalId = "f3"; SetId = "main"; WindowId = "S2-f3"; ActiveTab = 0; State = "missing"; Source = "fast-missing"; Hwnd = 0; TrackingContext = $null; CreateArguments = @("new-tab"); Diagnostic = $null; Error = $null }
            )

            $plan = [pscustomobject]@{
                PlanId = "s2f"; SetId = "main"; WtHwnds = @(); WtToken = ""
                Terminals = $records
                Counts = [pscustomobject]@{ Present = 0; Missing = 1; Ambiguous = 1; Failed = 1 }
            }

            $kickResult = [pscustomobject]@{
                Kicks = @([pscustomobject]@{ Order = 2; TerminalId = "f3"; WindowId = "S2-f3"; CreateArguments = @("new-tab"); StartedAtUtc = [DateTimeOffset]::UtcNow; DeadlineUtc = [DateTimeOffset]::UtcNow.AddSeconds(-1) })
                Failures = @()
            }

            $summary = Complete-DevWSTerminalLaunchPlan `
                -Plan $plan `
                -KickResult $kickResult `
                -PollMilliseconds 1 `
                -SnapshotProvider { return @() }

            Assert-Equal 0 @($summary.Finalized).Count "nothing finalized"
            Assert-Equal 3 @($summary.Failures).Count "classification and completion failures aggregate"
            Assert-Contains $summary.Failures[0] "Terminal 'f1'" "failed classification first (configured order)"
            Assert-Contains $summary.Failures[0] "classification failed" "classification error text"
            Assert-Contains $summary.Failures[1] "Terminal 'f2'" "ambiguous second"
            Assert-Contains $summary.Failures[1] "S2-f2" "ambiguity diagnostic carried"
            Assert-Contains $summary.Failures[2] "Terminal 'f3'" "completion failure last"
            Assert-Contains $summary.Failures[2] "could not be identified" "identity timeout text"
        }
        finally {
            . $uiaLib
            . $windowLib
            . $stateLib
            . $identityLib
        }
    }

    Test-Case "Stage 2 broker protocol validates strictly and keeps the secure ACL shape" {
        $version = Get-DevWSBrokerProtocolVersion

        foreach ($good in @(
            '{"version":1,"command":"ping"}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main"}',
            '{"version":1,"command":"go-launch","requestId":7,"planId":"abc"}',
            '{"version":1,"command":"abort-launch","requestId":7}',
            '{"version":1,"command":"status"}',
            '{"version":1,"command":"shutdown"}'
        )) {
            $result = Test-DevWSBrokerProtocolRequest -Line $good
            Assert-Equal $true $result.Ok "accepted: $good"
        }

        $statusRequest = Test-DevWSBrokerProtocolRequest -Line '{"version":1,"command":"status"}'
        Assert-Equal "status" $statusRequest.Request.Command "status command"

        foreach ($bad in @(
            '',
            'not json',
            '[]',
            '"text"',
            '{"version":2,"command":"ping"}',
            '{"version":1,"command":"execute"}',
            '{"version":1,"command":"ping","script":"calc"}',
            '{"version":1,"command":"prepare-launch","setId":"main"}',
            '{"version":1,"command":"prepare-launch","requestId":"7","setId":"main"}',
            '{"version":1,"command":"prepare-launch","requestId":0,"setId":"main"}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":""}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":42}',
            '{"version":1,"command":"go-launch","requestId":7}',
            '{"version":1,"command":"go-launch","requestId":7,"planId":42}',
            '{"version":1,"command":"go-launch","requestId":7,"planId":""}',
            '{"version":1,"command":"abort-launch"}',
            '{"version":1,"command":"status","requestId":1}',
            '{"version":1,"command":"status","setId":"main"}',
            '{"version":1,"command":"ping","requestId":1}'
        )) {
            $result = Test-DevWSBrokerProtocolRequest -Line $bad
            Assert-Equal $false $result.Ok "rejected: $bad"
        }

        $oversized = '{"version":1,"command":"ping","pad":"' + ('x' * 5000) + '"}'
        Assert-Equal $false (Test-DevWSBrokerProtocolRequest -Line $oversized).Ok "oversized request rejected"

        $oversizedBound = '{"version":1,"command":"ping","pad":"' + ('x' * ((Get-DevWSBrokerMaxLineLength) + 1)) + '"}'
        $boundResult = Test-DevWSBrokerProtocolRequest -Line $oversizedBound
        Assert-Equal $false $boundResult.Ok "request beyond the placement-era ceiling rejected"
        Assert-Contains $boundResult.Error "protocol limit" "boundary rejection names the limit"

        $sddl = Get-DevWSElevatedBrokerPipeSddl
        $sid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
        Assert-Contains $sddl "D:(A;;GA;;;$sid)" "current user has full access"
        Assert-Contains $sddl "(A;;GA;;;SY)" "SYSTEM has full access"
        Assert-Contains $sddl "S:(ML;;NW;;;ME)" "Medium mandatory label allows the non-elevated coordinator"
        Assert-NotContains $sddl ";;;WD)" "no Everyone grant"
        Assert-NotContains $sddl ";;;AU)" "no Authenticated Users grant"
    }

    Test-Case "Stage 2 broker protocol validates terminal placement records strictly" {
        $valid = '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":true,"x":-7,"y":0,"w":654,"h":1407},{"id":"term2","move":false}]}'
        $parsed = Test-DevWSBrokerProtocolRequest -Line $valid
        Assert-Equal $true $parsed.Ok "valid placement payload accepted"
        Assert-Equal 2 @($parsed.Request.TerminalPlacements).Count "placement records carried"
        Assert-Equal "slot" ([string]@($parsed.Request.TerminalPlacements)[0].id) "first record id"
        Assert-Equal $false ([bool]@($parsed.Request.TerminalPlacements)[1].move) "second record move=false"

        $single = '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":false}]}'
        $parsedSingle = Test-DevWSBrokerProtocolRequest -Line $single
        Assert-Equal $true $parsedSingle.Ok "single-record array accepted"
        Assert-Equal 1 @($parsedSingle.Request.TerminalPlacements).Count "single record preserved as an array"

        foreach ($bad in @(
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":{}}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":"slot"}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[null]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":true}]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":true,"x":0,"y":0,"w":0,"h":100}]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":false,"x":1}]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":"yes"}]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":false},{"id":"SLOT","move":false}]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"bad/id","move":false}]}',
            '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":false,"extra":true}]}',
            '{"version":1,"command":"ping","terminalPlacements":[{"id":"slot","move":false}]}',
            '{"version":1,"command":"status","terminalPlacements":[{"id":"slot","move":false}]}',
            '{"version":1,"command":"go-launch","requestId":7,"planId":"abc","terminalPlacements":[{"id":"slot","move":false}]}',
            '{"version":1,"command":"focus-terminals","requestId":7,"setId":"main","terminalPlacements":[{"id":"slot","move":false}]}'
        )) {
            $rejected = Test-DevWSBrokerProtocolRequest -Line $bad
            Assert-Equal $false $rejected.Ok "placement rejection: $bad"
        }

        # Bounded 64 KiB ceiling: a LIBERAL but finite placement array fits,
        # and one byte beyond the ceiling is refused.
        Assert-Equal 65536 (Get-DevWSBrokerMaxLineLength) "strict 64 KiB request bound"

        $records = [System.Collections.Generic.List[object]]::new()
        $candidate = ""
        $index = 0

        while ($true) {
            $records.Add([ordered]@{ id = ("t" + [string]$index); move = $true; x = -1000; y = -1000; w = 100; h = 100 }) | Out-Null
            $candidate = ([ordered]@{
                version            = 1
                command            = "prepare-launch"
                requestId          = 7
                setId              = "main"
                terminalPlacements = @($records.ToArray())
            } | ConvertTo-Json -Compress -Depth 6)

            if ($candidate.Length -gt ((Get-DevWSBrokerMaxLineLength) - 150)) { break }
            $index++
        }

        Assert-True ($candidate.Length -le (Get-DevWSBrokerMaxLineLength)) "near-boundary placement request fits the ceiling"
        Assert-Equal $true (Test-DevWSBrokerProtocolRequest -Line $candidate).Ok "near-boundary placement request accepted"

        $overBoundary = $candidate + (' ' * ((Get-DevWSBrokerMaxLineLength) + 1 - $candidate.Length))
        $overResult = Test-DevWSBrokerProtocolRequest -Line $overBoundary
        Assert-Equal $false $overResult.Ok "over-boundary placement request rejected"
        Assert-Contains $overResult.Error "protocol limit" "over-boundary rejection names the limit"
    }

    Test-Case "Stage 2 broker host source guards" {
        $hostSource = Get-SourceOf "src\workers\elevated-broker.ps1"
        $protocol  = Get-SourceOf "src\lib\devws-broker-protocol.ps1"

        Assert-Contains $hostSource "WaitForConnection" "idle wait is a blocking pipe accept"
        Assert-Contains $hostSource "Get-DevWSEffectiveRuntimeGeneration" "per-command deployed-code check (normal + privileged generation)"
        Assert-Contains $hostSource "restart-required" "stale code is refused"
        Assert-Contains $hostSource "Get-DevWSTerminalLaunchPlan" "terminal plan comes from the canonical library"
        Assert-Contains $hostSource "Start-DevWSTerminalLaunchPlan" "kickoff comes from the canonical library"
        Assert-Contains $hostSource "Complete-DevWSTerminalLaunchPlan" "completion comes from the canonical library"
        Assert-Contains $hostSource "Test-DevWSTerminalLaunchPlanFresh" "cheap WT-generation recheck before GO"
        Assert-Contains $hostSource 'type      = "go-ack"' "GO-ACK is sent before kickoff"
        Assert-NotContains $hostSource "poct" "the POC-only kick filter is not carried into production"
        Assert-NotContains $hostSource "TcpListener" "no TCP listener"
        Assert-NotContains $hostSource "HttpListener" "no HTTP listener"
        Assert-NotContains $hostSource "Invoke-Expression" "no arbitrary execution"
        Assert-NotContains $hostSource "Start-Job" "no job machinery"
        Assert-NotContains $hostSource "Runspace" "no runspace machinery"
        Assert-NotContains $hostSource "New-DevWSTerminalCreateArguments" "no duplicated creation policy in the host"

        Assert-Contains $protocol "CreateNamedPipeW" "raw secure pipe creation preserved"
        Assert-Contains $protocol "Get-DevWSElevatedBrokerPipeSddl" "explicit SDDL"
        Assert-NotContains $protocol "Invoke-Expression" "no arbitrary execution in the protocol library"
        Assert-NotContains $protocol "Get-DevWSTerminalLaunchPlan" "no terminal policy in the protocol library"

        # GO-ACK precedes kickoff in source order inside the host.
        $ackIndex = $hostSource.IndexOf('type      = "go-ack"')
        $kickIndex = $hostSource.IndexOf("Start-DevWSTerminalLaunchPlan -Plan")
        Assert-True ($ackIndex -ge 0 -and $kickIndex -gt $ackIndex) "GO-ACK is written before terminal side effects"

        Assert-Contains $hostSource '"status"' "observational status command present"
        $statusIndex = $hostSource.IndexOf('$request.Command -eq "status"')
        $staleIndex  = $hostSource.IndexOf('if ($currentGeneration -ne $generation)')
        Assert-True ($statusIndex -ge 0 -and $statusIndex -lt $staleIndex) "status answers before the stale-generation exit"
    }

    # ----- Pass 2B: broker terminal operations (focus / capture) -----

    function New-P2BTerminalSetConfig {
        param([Parameter(Mandatory)][string]$Name)

        $dir = Join-Path $TestRoot $Name
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $target = Join-Path $dir "workspace.json"

        $terminals = @(
            (New-TerminalDefinition -Id "term1" -WindowId "DevWS-P2B-term1" -Path $TestRoot),
            (New-TerminalDefinition -Id "term2" -WindowId "DevWS-P2B-term2" -Path $TestRoot),
            (New-TerminalDefinition -Id "term3" -WindowId "DevWS-P2B-term3" -Path $TestRoot)
        )

        $config = ConvertTo-TestConfig -Sets @((New-TestSet -Id "main" -Windows $terminals))
        $config | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8
        return $target
    }

    Test-Case "Pass 2B: terminal-operation protocol validates strictly and keeps launch validation unchanged" {
        foreach ($command in @("focus-terminals", "capture-terminals")) {
            $parsed = Test-DevWSBrokerProtocolRequest -Line ('{"version":1,"command":"' + $command + '","requestId":21,"setId":"main"}')
            Assert-Equal $true $parsed.Ok "accepted: $command"
            Assert-Equal $command $parsed.Request.Command "$command command"
            Assert-Equal 21 ([long]$parsed.Request.RequestId) "$command requestId"
            Assert-Equal "main" $parsed.Request.SetId "$command setId"
        }

        foreach ($bad in @(
            '{"version":1,"command":"focus-terminals","setId":"main"}',
            '{"version":1,"command":"focus-terminals","requestId":21}',
            '{"version":1,"command":"focus-terminals","requestId":0,"setId":"main"}',
            '{"version":1,"command":"focus-terminals","requestId":21,"setId":""}',
            '{"version":1,"command":"focus-terminals","requestId":21,"setId":"main","planId":"p"}',
            '{"version":1,"command":"capture-terminals","requestId":21,"setId":"main","extra":1}',
            '{"version":1,"command":"capture-terminals","requestId":"21","setId":"main"}'
        )) {
            Assert-Equal $false (Test-DevWSBrokerProtocolRequest -Line $bad).Ok "rejected: $bad"
        }

        Assert-Equal $true (Test-DevWSBrokerProtocolRequest -Line '{"version":1,"command":"prepare-launch","requestId":7,"setId":"main"}').Ok "prepare-launch unchanged"
        Assert-Equal $false (Test-DevWSBrokerProtocolRequest -Line '{"version":1,"command":"prepare-launch","requestId":7}').Ok "prepare-launch still requires setId"
        Assert-Equal $false (Test-DevWSBrokerProtocolRequest -Line '{"version":1,"command":"ping","requestId":1}').Ok "ping still rejects requestId"
    }

    Test-Case "Pass 2B: broker host wires the shared terminal operations" {
