    Test-Case "Pass 2B: shared focus core preserves reverse order, exact HWNDs and activeTab" {
        $target = New-P2BTerminalSetConfig "p2b-focus-core"
        $config = Read-DevWSConfigFile -Path $target
        $terminals = @($config.sets[0].windows)
        $state = New-DevWSRuntimeState

        $script:p2bFocus = [System.Collections.Generic.List[string]]::new()

        function Resolve-DevWSTerminalHwnd {
            param($WindowId, [string]$SetId, $State, [string]$TerminalId)
            $script:p2bFocus.Add("resolve $SetId/$TerminalId")
            return [pscustomobject]@{ Status = "present"; Hwnd = [long](800000 + [int]($TerminalId -replace "term", "")); Source = "state" }
        }
        function Focus-DevWSWindowHwnd { param([long]$Hwnd, [string]$Context) $script:p2bFocus.Add("focus $Hwnd $Context") }
        function Select-DevWSTabByIndexFromHwnd { param([long]$Hwnd, [int]$Index, [string]$Context) $script:p2bFocus.Add("select $Hwnd $Index"); return $true }
