    Test-Case "Pass 2B: focus routing falls back only before acceptance" {
        $target = New-LifecycleConfigCopy "p2b-focus-routing"
        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            $script:p2bOpCalls = 0
            $script:p2bOpResult = $null
            $script:p2bWorkerCalls = [System.Collections.Generic.List[object]]::new()

            function Invoke-DevWSElevatedBrokerTerminalOperation {
                param($Command, [long]$RequestId, [string]$SetId, [string]$PipeName, [int]$ConnectTimeoutMilliseconds = 1500, [int]$AcceptTimeoutMilliseconds = 30000, [int]$FinalTimeoutMilliseconds = 120000)
                $script:p2bOpCalls++
                Assert-Equal "focus-terminals" $Command "focus command routed"
                if ($null -ne $script:p2bOpResult) { return $script:p2bOpResult }
                return [pscustomobject]@{ Status = "NotAccepted"; Ok = $false; Message = ""; Error = "unavailable" }
            }
            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $script:p2bWorkerCalls.Add([pscustomobject]@{ Kind = $Kind; TaskName = $TaskName; SetId = $Payload.setId })
                return [pscustomobject]@{ requestId = "stub"; ok = $true; message = "OK" }
            }
            function Get-DevWSAppWindowProbe { param($Config, $Candidates, [switch]$TolerantOwnership) return @() }
            function Resolve-DevWSAppLifecycleWindow { param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe) return [long]900001 }
            function Move-DevWSWindowHwnd { param([long]$Hwnd, $Layout, [string]$Context) }
            function Focus-DevWSWindowHwnd { param([long]$Hwnd, [string]$Context) }

            Invoke-DevWSFocus -SetId "main"
            Assert-Equal 1 $script:p2bOpCalls "broker attempted first"
            Assert-Equal 1 $script:p2bWorkerCalls.Count "fallback invoked exactly once before acceptance"
            Assert-Equal "focus" $script:p2bWorkerCalls[0].Kind "focus worker kind"
            Assert-Equal "DevWorkspace-ElevatedFocus" $script:p2bWorkerCalls[0].TaskName "focus task name"

            $script:p2bOpCalls = 0
            $script:p2bWorkerCalls.Clear()
            $script:p2bOpResult = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $true; Message = "OK"; Error = "" }
            Invoke-DevWSFocus -SetId "main"
            Assert-Equal 1 $script:p2bOpCalls "broker accepted"
            Assert-Equal 0 $script:p2bWorkerCalls.Count "no fallback after acceptance"

            $script:p2bOpCalls = 0
            $script:p2bWorkerCalls.Clear()
            $script:p2bOpResult = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $false; Message = "focus broke"; Error = "" }
            $message = Get-ThrownMessage { Invoke-DevWSFocus -SetId "main" }
            Assert-Contains $message "Terminal focus failed: focus broke" "broker operation failure surfaced"
            Assert-Equal 0 $script:p2bWorkerCalls.Count "no fallback after accepted failure"

            $script:p2bOpCalls = 0
            $script:p2bWorkerCalls.Clear()
            $script:p2bOpResult = [pscustomobject]@{ Status = "AcceptedButUncertain"; Ok = $false; Message = ""; Error = "lost" }
            $message = Get-ThrownMessage { Invoke-DevWSFocus -SetId "main" }
            Assert-Contains $message "uncertain" "uncertainty reported"
            Assert-Contains $message "No fallback was attempted" "no-fallback boundary explicit"
            Assert-Equal 0 $script:p2bWorkerCalls.Count "no fallback after uncertainty"

            $script:p2bOpCalls = 0
            $script:p2bWorkerCalls.Clear()
            $script:p2bOpResult = $null
            Invoke-DevWSFocus -SetId "empty"
            Assert-Equal 0 $script:p2bOpCalls "empty set never contacts the broker"
            Assert-Equal 0 $script:p2bWorkerCalls.Count "empty set never starts the worker"

            $appsOnly = New-Pass3ProbeConfig "p2b-focus-appsonly"
            $env:DEVWS_CONFIG = $appsOnly
            $script:p2bOpCalls = 0
            $script:p2bWorkerCalls.Clear()
            Invoke-DevWSFocus -SetId "single"
            Assert-Equal 0 $script:p2bOpCalls "apps-only focus never contacts the broker"
            Assert-Equal 0 $script:p2bWorkerCalls.Count "apps-only focus never starts the worker"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Pass 2B: capture routing falls back only before acceptance and never saves on uncertainty" {
        $target = New-LifecycleConfigCopy "p2b-capture-routing"
        $savedEnv = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target

        try {
            $script:p2bCapOpCalls = 0
            $script:p2bCapOpResult = $null
            $script:p2bCapWorkerCalls = 0
            $script:p2bCapSaved = 0
            $script:p2bCaptureLines = @("termalpha|11|22|33|44", "termbeta|55|66|77|88")

            function Invoke-DevWSElevatedBrokerTerminalOperation {
                param($Command, [long]$RequestId, [string]$SetId, [string]$PipeName, [int]$ConnectTimeoutMilliseconds = 1500, [int]$AcceptTimeoutMilliseconds = 30000, [int]$FinalTimeoutMilliseconds = 120000)
                $script:p2bCapOpCalls++
                Assert-Equal "capture-terminals" $Command "capture command routed"
                if ($null -ne $script:p2bCapOpResult) {
                    if ($script:p2bCapOpResult.Status -eq "AcceptedAndCompleted" -and $script:p2bCapOpResult.Ok) {
                        # Phase 2-B: the fake broker fabricates the protected
                        # publication for the exact request id it received.
                        $publication = New-DevWSTestCapturePublication -OperationId ([string]$RequestId) -Lines $script:p2bCaptureLines
                        return [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $true; Message = "OK"; Error = ""; Publication = $publication }
                    }
                    return $script:p2bCapOpResult
                }
                return [pscustomobject]@{ Status = "NotAccepted"; Ok = $false; Message = ""; Error = "unavailable" }
            }
            function Invoke-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $script:p2bCapWorkerCalls++
                Assert-Equal "capture" $Kind "capture worker kind"
                Assert-Equal "DevWorkspace-ElevatedCapture" $TaskName "capture task name"
                return (New-DevWSTestWorkerCaptureResult -Lines $script:p2bCaptureLines)
            }
            function Get-DevWSAppWindowProbe { param($Config, $Candidates, [switch]$TolerantOwnership) return @() }
            function Resolve-DevWSAppLifecycleWindow { param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe) return [long]910001 }
            function Get-DevWSWindowHwndRect { param([long]$Hwnd) return [pscustomobject]@{ x = 1; y = 2; w = 3; h = 4; Valid = $true } }
            function Save-DevWSConfig { param($Config, $Location) $script:p2bCapSaved++ }

            Save-DevWSLayout -SetId "main"
            Assert-Equal 1 $script:p2bCapOpCalls "broker attempted first"
            Assert-Equal 1 $script:p2bCapWorkerCalls "fallback invoked exactly once before acceptance"
            Assert-Equal 1 $script:p2bCapSaved "fallback capture saved once"

            $script:p2bCapOpCalls = 0
            $script:p2bCapWorkerCalls = 0
            $script:p2bCapSaved = 0
            $script:p2bCapOpResult = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $true; Message = "OK"; Error = "" }
            Save-DevWSLayout -SetId "main"
            Assert-Equal 1 $script:p2bCapOpCalls "broker accepted"
            Assert-Equal 0 $script:p2bCapWorkerCalls "no fallback after acceptance"
            Assert-Equal 1 $script:p2bCapSaved "broker capture saved once"

            $script:p2bCapOpCalls = 0
            $script:p2bCapWorkerCalls = 0
            $script:p2bCapSaved = 0
            $script:p2bCapOpResult = [pscustomobject]@{ Status = "AcceptedAndCompleted"; Ok = $false; Message = "capture broke"; Error = "" }
            $message = Get-ThrownMessage { Save-DevWSLayout -SetId "main" }
            Assert-Contains $message "Elevated capture failed: capture broke" "broker capture failure surfaced"
            Assert-Equal 0 $script:p2bCapWorkerCalls "no fallback after accepted failure"
            Assert-Equal 0 $script:p2bCapSaved "no save after accepted failure"

            $script:p2bCapOpCalls = 0
            $script:p2bCapWorkerCalls = 0
            $script:p2bCapSaved = 0
            $script:p2bCapOpResult = [pscustomobject]@{ Status = "AcceptedButUncertain"; Ok = $false; Message = ""; Error = "lost" }
            $message = Get-ThrownMessage { Save-DevWSLayout -SetId "main" }
            Assert-Contains $message "uncertain" "uncertainty reported"
            Assert-Contains $message "No fallback was attempted" "no-fallback boundary explicit"
            Assert-Equal 0 $script:p2bCapWorkerCalls "no fallback after uncertainty"
            Assert-Equal 0 $script:p2bCapSaved "no save after uncertainty"
            Assert-True (-not (Test-Path -LiteralPath (Join-Path (Get-DevWSRuntimeRoot) "capture-elevated.txt"))) "no unprotected capture artifact is ever produced"

            $appsOnly = New-Pass3ProbeConfig "p2b-capture-appsonly"
            $env:DEVWS_CONFIG = $appsOnly
            $script:p2bCapOpCalls = 0
            $script:p2bCapWorkerCalls = 0
            $script:p2bCapSaved = 0
            Save-DevWSLayout -SetId "single"
            Assert-Equal 0 $script:p2bCapOpCalls "apps-only capture never contacts the broker"
            Assert-Equal 0 $script:p2bCapWorkerCalls "apps-only capture never starts the worker"
            Assert-Equal 1 $script:p2bCapSaved "apps-only capture still saves"
        }
        finally {
            if ($null -ne $savedEnv) { $env:DEVWS_CONFIG = $savedEnv } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Pass 2B: broker operation client distinguishes lost FINAL and lost ACCEPTED" {
        . (Join-Path $LibDir "devws-broker-protocol.ps1")

        $serverScript = @(
            'param([string]$PipeName, [string]$ReadyPath, [string]$Mode)',
            '$ErrorActionPreference = ''Stop''',
            '$server = [System.IO.Pipes.NamedPipeServerStream]::new($PipeName, [System.IO.Pipes.PipeDirection]::InOut, 1, [System.IO.Pipes.PipeTransmissionMode]::Byte, [System.IO.Pipes.PipeOptions]::None)',
            'Set-Content -LiteralPath $ReadyPath -Value ''ready'' -NoNewline',
            '$server.WaitForConnection()',
            '$enc = [System.Text.UTF8Encoding]::new($false)',
            '$r = [System.IO.StreamReader]::new($server, $enc, $false, 4096, $true)',
            '$w = [System.IO.StreamWriter]::new($server, $enc, 4096, $true)',
            '$line = $r.ReadLine()',
            'if ($Mode -eq ''no-accepted'') { $r.Dispose(); $w.Dispose(); $server.Dispose(); exit 0 }',
            '$req = $line | ConvertFrom-Json',
            '$w.WriteLine((''{"version":1,"type":"operation-accepted","operation":"'' + [string]$req.command + ''","requestId":'' + [long]$req.requestId + ''}'')); $w.Flush()',
            'if ($Mode -eq ''no-final'') { $r.Dispose(); $w.Dispose(); $server.Dispose(); exit 0 }',
            '$w.WriteLine((''{"version":1,"type":"operation-final","operation":"'' + [string]$req.command + ''","requestId":'' + [long]$req.requestId + '',"ok":true,"message":"OK"}'')); $w.Flush()',
            '$r.Dispose(); $w.Dispose(); $server.Dispose()'
        ) -join "`r`n"

        $serverPath = Join-Path $TestRoot "p2b-scripted-broker.ps1"
        Set-Content -LiteralPath $serverPath -Value $serverScript -NoNewline
        $savedProtocolEnv = $null

        $cases = @(
            @{ Mode = "happy";      Expected = "AcceptedAndCompleted" },
            @{ Mode = "no-final";   Expected = "AcceptedButUncertain" },
            @{ Mode = "no-accepted"; Expected = "NotAccepted" }
        )

        $serverProc = $null

        try {
            foreach ($case in $cases) {
                $pipe = "DevWS.P2B.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)
                $ready = Join-Path $TestRoot ("p2b-ready-" + $case.Mode + ".txt")
                $serverProc = Start-Process -FilePath "pwsh" -ArgumentList @('-NoProfile', '-File', $serverPath, '-PipeName', $pipe, '-ReadyPath', $ready, '-Mode', $case.Mode) -PassThru -WindowStyle Hidden

                $deadline = (Get-Date).AddSeconds(15)
                while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $ready)) { Start-Sleep -Milliseconds 100 }
                Assert-True (Test-Path -LiteralPath $ready) "scripted broker ready ($($case.Mode))"

                $result = Invoke-DevWSElevatedBrokerTerminalOperation -Command "focus-terminals" -RequestId 71 -SetId "main" -PipeName $pipe -ConnectTimeoutMilliseconds 3000 -AcceptTimeoutMilliseconds 5000 -FinalTimeoutMilliseconds 5000
                Assert-Equal $case.Expected $result.Status "client status for $($case.Mode)"
                if ($case.Mode -eq "happy") { Assert-Equal $true $result.Ok "happy path ok" }

                [void]$serverProc.WaitForExit(10000)
                Stop-TestFixtureProcess $serverProc
            }
        }
        finally {
            # Every exit path -- including a failed assertion while the server
            # is still resident -- must stop the exact fixture server and
            # remove the exact fixture files; no other process is ever touched.
            Stop-TestFixtureProcess $serverProc
            Remove-Item -LiteralPath $serverPath -Force -ErrorAction SilentlyContinue
            foreach ($case in $cases) {
                Remove-Item -LiteralPath (Join-Path $TestRoot ("p2b-ready-" + $case.Mode + ".txt")) -Force -ErrorAction SilentlyContinue
            }
        }
    }

    Test-Case "Pass 2B: a busy single-threaded broker still answers the launch availability ping within budget" {
        . (Join-Path $LibDir "devws-broker-protocol.ps1")

        $busyScript = @(
            'param([string]$PipeName, [string]$ReadyPath, [string]$StartedPath)',
            '$ErrorActionPreference = ''Stop''',
            '$server = [System.IO.Pipes.NamedPipeServerStream]::new($PipeName, [System.IO.Pipes.PipeDirection]::InOut, 1, [System.IO.Pipes.PipeTransmissionMode]::Byte, [System.IO.Pipes.PipeOptions]::None)',
            'Set-Content -LiteralPath $ReadyPath -Value ''ready'' -NoNewline',
            '$server.WaitForConnection()',
            '$enc = [System.Text.UTF8Encoding]::new($false)',
            '$r = [System.IO.StreamReader]::new($server, $enc, $false, 4096, $true)',
            '$w = [System.IO.StreamWriter]::new($server, $enc, 4096, $true)',
            '$line = $r.ReadLine()',
            'Set-Content -LiteralPath $StartedPath -Value ''op'' -NoNewline',
            '$req = $line | ConvertFrom-Json',
            'Start-Sleep -Milliseconds 600',
            '$w.WriteLine((''{"version":1,"type":"operation-accepted","operation":"'' + [string]$req.command + ''","requestId":'' + [long]$req.requestId + ''}'')); $w.Flush()',
            'Start-Sleep -Milliseconds 100',
            '$w.WriteLine((''{"version":1,"type":"operation-final","operation":"'' + [string]$req.command + ''","requestId":'' + [long]$req.requestId + '',"ok":true,"message":"OK"}'')); $w.Flush()',
            '$r.Dispose(); $w.Dispose(); $server.Dispose()',
            '$server2 = [System.IO.Pipes.NamedPipeServerStream]::new($PipeName, [System.IO.Pipes.PipeDirection]::InOut, 1, [System.IO.Pipes.PipeTransmissionMode]::Byte, [System.IO.Pipes.PipeOptions]::None)',
            '$server2.WaitForConnection()',
            '$r2 = [System.IO.StreamReader]::new($server2, $enc, $false, 4096, $true)',
            '$w2 = [System.IO.StreamWriter]::new($server2, $enc, 4096, $true)',
            '$null = $r2.ReadLine()',
            '$w2.WriteLine(''{"version":1,"type":"pong"}''); $w2.Flush()',
            '$r2.Dispose(); $w2.Dispose(); $server2.Dispose()'
        ) -join "`r`n"

        $runnerScript = @(
            'param([string]$PipeName, [string]$OutPath, [string]$LibDir)',
            '$ErrorActionPreference = ''Stop''',
            '. (Join-Path $LibDir ''devws-broker-protocol.ps1'')',
            '$result = Invoke-DevWSElevatedBrokerTerminalOperation -Command ''focus-terminals'' -RequestId 77 -SetId ''main'' -PipeName $PipeName -ConnectTimeoutMilliseconds 5000 -AcceptTimeoutMilliseconds 10000 -FinalTimeoutMilliseconds 10000',
            '$result | ConvertTo-Json | Set-Content -LiteralPath $OutPath -Encoding UTF8'
        ) -join "`r`n"

        $busyPath = Join-Path $TestRoot "p2b-busy-broker.ps1"
        $runnerPath = Join-Path $TestRoot "p2b-busy-runner.ps1"
        Set-Content -LiteralPath $busyPath -Value $busyScript -NoNewline
        Set-Content -LiteralPath $runnerPath -Value $runnerScript -NoNewline

        $pipe = "DevWS.P2B.Busy." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $ready = Join-Path $TestRoot "p2b-busy-ready.txt"
        $started = Join-Path $TestRoot "p2b-busy-started.txt"
        $runnerOut = Join-Path $TestRoot "p2b-busy-result.json"

        $serverProc = $null
        $runnerProc = $null

        try {
            $serverProc = Start-Process -FilePath "pwsh" -ArgumentList @('-NoProfile', '-File', $busyPath, '-PipeName', $pipe, '-ReadyPath', $ready, '-StartedPath', $started) -PassThru -WindowStyle Hidden

            $deadline = (Get-Date).AddSeconds(15)
            while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $ready)) { Start-Sleep -Milliseconds 100 }
            Assert-True (Test-Path -LiteralPath $ready) "busy broker ready"

            $runnerProc = Start-Process -FilePath "pwsh" -ArgumentList @('-NoProfile', '-File', $runnerPath, '-PipeName', $pipe, '-OutPath', $runnerOut, '-LibDir', $LibDir) -PassThru -WindowStyle Hidden

            $deadline = (Get-Date).AddSeconds(15)
            while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $started)) { Start-Sleep -Milliseconds 50 }
            Assert-True (Test-Path -LiteralPath $started) "operation connection established before the ping"

            $watch = [System.Diagnostics.Stopwatch]::StartNew()
            $available = Test-DevWSElevatedBrokerAvailable -PipeName $pipe -TimeoutMilliseconds 1500
            $watch.Stop()

            Assert-Equal $true $available "availability ping succeeds after the bounded busy window"
            Assert-True ($watch.Elapsed.TotalMilliseconds -lt 2000) "ping stays inside the busy-visibility budget (measured $([Math]::Round($watch.Elapsed.TotalMilliseconds,0)) ms)"

            [void]$runnerProc.WaitForExit(15000)
            Assert-True (Test-Path -LiteralPath $runnerOut) "operation runner produced a result"
            $runnerResult = Get-Content -LiteralPath $runnerOut -Raw | ConvertFrom-Json
            Assert-Equal "AcceptedAndCompleted" $runnerResult.Status "operation completed while the ping waited"
            Assert-Equal $true $runnerResult.Ok "operation ok"

            [void]$serverProc.WaitForExit(15000)
        }
        finally {
            # Every exit path -- including a failed assertion mid-operation --
            # must stop the exact busy server and operation runner processes
            # and remove the exact fixture files; no other process is touched.
            Stop-TestFixtureProcess $runnerProc
            Stop-TestFixtureProcess $serverProc
            Remove-Item -LiteralPath $busyPath -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $runnerPath -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $ready -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $started -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $runnerOut -Force -ErrorAction SilentlyContinue
        }
    }

    Test-Case "Pass 2B: an absent broker fails fast before the scheduled fallback" {
        . (Join-Path $LibDir "devws-broker-protocol.ps1")

        # The real helper's best-effort restart kickoff must never be exercised
        # inside the test suite: replace it with a no-op recorder.
        $script:p2bRestartKicks = 0
        function Request-DevWSElevatedBrokerRestartBestEffort { param() $script:p2bRestartKicks++ }

        $pipe = "DevWS.P2B.Absent." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $watch = [System.Diagnostics.Stopwatch]::StartNew()
        $result = Invoke-DevWSElevatedBrokerTerminalOperation -Command "focus-terminals" -RequestId 81 -SetId "main" -PipeName $pipe -ConnectTimeoutMilliseconds 5000 -AcceptTimeoutMilliseconds 5000 -FinalTimeoutMilliseconds 5000
        $watch.Stop()

        Assert-Equal "NotAccepted" $result.Status "absent broker is a pre-acceptance failure"
        Assert-True ($watch.Elapsed.TotalMilliseconds -lt 1000) "absent broker fails fast without waiting for the connect timeout (measured $([Math]::Round($watch.Elapsed.TotalMilliseconds,0)) ms)"
        Assert-Equal 1 $script:p2bRestartKicks "best-effort recovery kicked exactly once for future calls"
    }

    Test-Case "Pass 2B: thin focus and capture workers keep their request/result contracts" {
        $fixture = New-WorkerProbeFixture "p2b-worker-parity" -WithBinding

        $focus = Invoke-FreshWorkerRun `
            -WorkerPath (Join-Path $RepoRoot "src\workers\elevated-focus.ps1") `
            -ConfigPath $fixture.ConfigPath `
            -StateRoot $fixture.StateRoot `
