        Assert-Equal "returned" $focus.Outcome "focus worker returned"
        Assert-Equal $true ([bool]$focus.Result.ok) "focus worker result ok"
        Assert-Equal "OK" ([string]$focus.Result.message) "focus worker success message"

        $captureRequestId = [guid]::NewGuid().ToString()

        $capture = Invoke-FreshWorkerRun `
            -WorkerPath (Join-Path $RepoRoot "src\workers\elevated-capture.ps1") `
