            -StateRoot $fixture.StateRoot `
            -Kind "capture" `
            -RequestId $captureRequestId `
            -Payload @{ setId = "main" }

        Assert-Equal "returned" $capture.Outcome "capture worker returned"
        Assert-Equal $true ([bool]$capture.Result.ok) "capture worker result ok"
        Assert-Equal "OK" ([string]$capture.Result.message) "capture worker success message"

        # Phase 2-B: the geometry is now a protected publication; the worker
        # reports the publication identity through the result data and nothing
        # is written under the user state root.
        $capturePublication = [string]$capture.Result.data.publication
        Assert-True (-not [string]::IsNullOrWhiteSpace($capturePublication)) "capture worker reports the publication identity"

        $publicationRead = Read-DevWSProtectedCapturePublication -OperationId $captureRequestId -ExpectedPublication $capturePublication
        Assert-Equal 0 @($publicationRead.Geometry.Keys).Count "empty set captured as empty geometry"
        Assert-True (-not (Test-Path -LiteralPath (Join-Path $fixture.StateRoot "capture-elevated.txt"))) "no unprotected geometry file is written"
    }

    Test-Case "Pass 2B: broker terminal operations run through the real disposable broker" {
        $fixture = New-InstallFixture "p2b-broker-live-ops"
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $configPath = Join-Path $fixture.Root "broker-config.json"
        ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @()),
            (New-TestSet -Id "secondary" -Windows @())
        ) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath -Encoding UTF8

        $opsState = Join-Path $fixture.Root "ops-state"
        New-Item -ItemType Directory -Path $opsState -Force | Out-Null

        $pipe  = "DevWS.P2B.Broker." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $mutex = "Local\DevWS.P2B.Broker." + [guid]::NewGuid().ToString("N").Substring(0, 8)

        $savedConfig = $env:DEVWS_CONFIG
        $savedState  = $env:DEVWS_STATE_ROOT
        $env:DEVWS_CONFIG = $configPath
        $env:DEVWS_STATE_ROOT = $opsState

        $broker = $null

        try {
            . (Join-Path $LibDir "devws-broker-protocol.ps1")

            $broker = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', ('"' + (Join-Path $fixture.Privileged "workers\elevated-broker.ps1") + '"'),
                '-PipeName', $pipe, '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root
            ) -PassThru -WindowStyle Hidden

            $ready = $false
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                if (Test-DevWSElevatedBrokerAvailable -PipeName $pipe -TimeoutMilliseconds 1000) { $ready = $true; break }
                Start-Sleep -Milliseconds 250
            }

            Assert-Equal $true $ready "live broker became ready"

            $wtBefore = @(Get-DevWSTerminalTopLevelHwnds).Count

            $focus = Invoke-DevWSElevatedBrokerTerminalOperation -Command "focus-terminals" -RequestId 31 -SetId "main" -PipeName $pipe -ConnectTimeoutMilliseconds 5000 -AcceptTimeoutMilliseconds 15000 -FinalTimeoutMilliseconds 15000
            Assert-Equal "AcceptedAndCompleted" $focus.Status "focus accepted and completed"
            Assert-Equal $true $focus.Ok "focus ok"
            Assert-Equal "OK" $focus.Message "focus message"

            # Phase 2-B: an INSTALLED-layout broker capture writes to the REAL
            # protected root by design (production authority). The suite must
            # never touch it, so live capture coverage runs through a
            # repository-layout disposable broker at the end of this test.
            Assert-True (-not (Test-Path -LiteralPath (Join-Path $opsState "capture-elevated.txt"))) "installed broker operations write no unprotected capture file"

            $reject = Invoke-DevWSElevatedBrokerTerminalOperation -Command "focus-terminals" -RequestId 33 -SetId "nope" -PipeName $pipe -ConnectTimeoutMilliseconds 5000 -AcceptTimeoutMilliseconds 15000 -FinalTimeoutMilliseconds 15000
            Assert-Equal "NotAccepted" $reject.Status "unknown set rejected before acceptance"
            Assert-Contains $reject.Error "Unknown workspace set" "actionable rejection"

            $wtAfter = @(Get-DevWSTerminalTopLevelHwnds).Count
            Assert-Equal $wtBefore $wtAfter "terminal operations created no windows"

            Add-Content -LiteralPath (Join-Path $fixture.Root "app\lib\devws-broker-protocol.ps1") -Value "`n# stale test touch"
            $stale = Invoke-DevWSElevatedBrokerTerminalOperation -Command "focus-terminals" -RequestId 34 -SetId "main" -PipeName $pipe -ConnectTimeoutMilliseconds 5000 -AcceptTimeoutMilliseconds 15000 -FinalTimeoutMilliseconds 15000
            Assert-Equal "NotAccepted" $stale.Status "stale deployment refuses before acceptance"
            Assert-Contains $stale.Error "restart-required" "restart-required surfaced"
            Assert-Equal $true ($broker.WaitForExit(15000)) "stale broker exits for recovery"
            $broker = $null

            # Phase 2-B live capture through a REAL repository-layout broker:
            # the protected publication lands in the repository-only fixture
            # seam and the Medium-side reader consumes its own publication.
            $repoPipe  = "DevWS.P2B.RepoBroker." + [guid]::NewGuid().ToString("N").Substring(0, 8)
            $repoMutex = "Local\DevWS.P2B.RepoBroker." + [guid]::NewGuid().ToString("N").Substring(0, 8)

            $repoBroker = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', ('"' + (Join-Path $RepoRoot "src\workers\elevated-broker.ps1") + '"'),
                '-PipeName', $repoPipe, '-MutexName', $repoMutex
            ) -PassThru -WindowStyle Hidden

            $repoReady = $false
            $repoDeadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $repoDeadline) {
                if (Test-DevWSElevatedBrokerAvailable -PipeName $repoPipe -TimeoutMilliseconds 1000) { $repoReady = $true; break }
                Start-Sleep -Milliseconds 250
            }

            Assert-Equal $true $repoReady "repository broker became ready"

            $repoCaptureRequestId = [long](1789900000000000000 + (Get-Random -Maximum 1000000))
            $repoCapture = Invoke-DevWSElevatedBrokerTerminalOperation -Command "capture-terminals" -RequestId $repoCaptureRequestId -SetId "main" -PipeName $repoPipe -ConnectTimeoutMilliseconds 5000 -AcceptTimeoutMilliseconds 15000 -FinalTimeoutMilliseconds 15000
            Assert-Equal "AcceptedAndCompleted" $repoCapture.Status "repository broker capture accepted and completed"
            Assert-Equal $true $repoCapture.Ok "repository broker capture ok"
            Assert-True (-not [string]::IsNullOrWhiteSpace([string]$repoCapture.Publication)) "repository broker FINAL carries the publication identity"

            $repoPublication = Read-DevWSProtectedCapturePublication -OperationId ([string]$repoCaptureRequestId) -ExpectedPublication ([string]$repoCapture.Publication)
            Assert-Equal 0 @($repoPublication.Geometry.Keys).Count "repository broker captured the empty set as empty geometry"
            Assert-True (-not (Test-Path -LiteralPath (Join-Path $opsState "capture-elevated.txt"))) "no unprotected capture file is produced"
            Assert-True (-not (Test-Path -LiteralPath (Join-Path $opsState "capture-elevated.snapshots.json"))) "no unprotected sidecar is produced"
        }
        finally {
            if ($null -ne $broker -and -not $broker.HasExited) { Stop-Process -Id $broker.Id -Force -ErrorAction SilentlyContinue }
            if ($null -ne $repoBroker -and -not $repoBroker.HasExited) { Stop-Process -Id $repoBroker.Id -Force -ErrorAction SilentlyContinue }
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            if ($null -ne $savedState) { $env:DEVWS_STATE_ROOT = $savedState } else { Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue }
        }
    }
    Test-Case "Stage 2 broker live: prepare/abort/expiry/mismatch/restart with zero side effects" {
        # The suite installs default process-local broker fakes for hermeticity
        # (see the isolation block after the production dot-sources near the
        # top of this file). This integration test deliberately restores the
        # REAL broker client implementation for its unique, disposable broker
        # instance (unique fixture root, pipe and mutex, served by a fixture
        # broker process). Dynamic scoping drops the restored functions when
        # this test body ends, so the suite-wide defaults remain in force for
        # every other test.
        . (Join-Path $LibDir "devws-broker-protocol.ps1")

        $fixture = New-InstallFixture "stage2-broker-live"
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $configPath = Join-Path $fixture.Root "broker-config.json"
        ConvertTo-TestConfig -Sets @((New-TestSet -Id "main" -Windows @()), (New-TestSet -Id "secondary" -Windows @())) |
            ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath -Encoding UTF8

        $pipe  = "DevWS.Stage2.Broker.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $mutex = "Local\DevWS.Stage2.Broker.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)

        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $configPath

        $broker = $null
        $first  = $null
        $second = $null

        try {
            $broker = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', ('"' + (Join-Path $fixture.Privileged "workers\elevated-broker.ps1") + '"'),
                '-PipeName', $pipe, '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root
            ) -PassThru -WindowStyle Hidden

            $ready = $false
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                if (Test-DevWSElevatedBrokerAvailable -PipeName $pipe -TimeoutMilliseconds 1000) { $ready = $true; break }
                Start-Sleep -Milliseconds 250
            }

            Assert-Equal $true $ready "live broker became ready"

            # prepare -> READY with an empty plan (no terminals, no side effects)
            $connection = New-DevWSElevatedBrokerPrepare -RequestId 11 -SetId "main" -PipeName $pipe -TimeoutMilliseconds 8000
            $readyLine = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            Assert-Equal "ready" ([string]$readyLine.type) "prepare answers READY"
            Assert-Equal 0 @($readyLine.plan.terminals).Count "empty plan has no terminals"
            Assert-Equal "main" ([string]$readyLine.plan.setId) "plan carries the requested set"

            # go on the empty plan: GO-ACK then FINAL with nothing kicked
            $ack = Send-DevWSElevatedBrokerGo -Connection $connection -RequestId 11 -PlanId ([string]$readyLine.planId)
            Assert-Equal "go-ack" ([string]$ack.type) "GO-ACK returned"
            $final = Read-DevWSElevatedBrokerFinal -Connection $connection -TimeoutMilliseconds 20000
            Assert-Equal "final" ([string]$final.type) "FINAL returned"
            Assert-Equal 0 @($final.kicked).Count "nothing kicked for an empty plan"
            Assert-Equal 0 @($final.summary.finalized).Count "nothing finalized"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            # invalid set -> prepare-failed, no side effects
            $connection = New-DevWSElevatedBrokerPrepare -RequestId 12 -SetId "nope" -PipeName $pipe -TimeoutMilliseconds 8000
            $failed = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            Assert-Equal "prepare-failed" ([string]$failed.type) "unknown set fails the prepare"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            # abort discards the plan
            $connection = New-DevWSElevatedBrokerPrepare -RequestId 13 -SetId "main" -PipeName $pipe -TimeoutMilliseconds 8000
            $null = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            $aborted = Send-DevWSElevatedBrokerAbort -Connection $connection -RequestId 13
            Assert-Equal "aborted" ([string]$aborted.type) "abort acknowledged"
            $goAfterAbort = Send-DevWSElevatedBrokerGo -Connection $connection -RequestId 13 -PlanId "anything"
            Assert-Equal "replan-required" ([string]$goAfterAbort.type) "aborted plan cannot go"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            # plan-id mismatch
            $connection = New-DevWSElevatedBrokerPrepare -RequestId 14 -SetId "main" -PipeName $pipe -TimeoutMilliseconds 8000
            $null = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            $mismatch = Send-DevWSElevatedBrokerGo -Connection $connection -RequestId 14 -PlanId "wrong-plan"
            Assert-Equal "replan-required" ([string]$mismatch.type) "plan-id mismatch refuses"
            Assert-Equal "plan-mismatch" ([string]$mismatch.reason) "mismatch reason reported"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            # expiry
            $connection = New-DevWSElevatedBrokerPrepare -RequestId 15 -SetId "main" -PipeName $pipe -TimeoutMilliseconds 8000
            $expiryReady = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            Start-Sleep -Milliseconds 2600
            $expired = Send-DevWSElevatedBrokerGo -Connection $connection -RequestId 15 -PlanId ([string]$expiryReady.planId)
            Assert-Equal "replan-required" ([string]$expired.type) "expired plan refuses"
            Assert-Equal "expired" ([string]$expired.reason) "expiry reason reported"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            # Pass 5D placement transport against the real broker: a record
            # for a terminal outside the canonical membership fails the
            # prepare (membership mismatch, never a guess), while an empty
            # placement array over the empty terminal set is accepted and
            # produces the same empty plan. No side effects; abort discards.
            $connection = New-DevWSElevatedBrokerPrepare `
                -RequestId 16 `
                -SetId "main" `
                -PipeName $pipe `
                -TimeoutMilliseconds 8000 `
                -TerminalPlacements @([pscustomobject]@{ id = "ghost"; move = $true; x = 0; y = 0; w = 100; h = 100 })
            $placementFailed = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            Assert-Equal "prepare-failed" ([string]$placementFailed.type) "unknown placement id fails the prepare"
            Assert-Contains ([string]$placementFailed.error) "No configured terminal with id 'ghost'" "membership mismatch names the id"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            $connection = New-DevWSElevatedBrokerPrepare -RequestId 17 -SetId "main" -PipeName $pipe -TimeoutMilliseconds 8000 -TerminalPlacements @()
            $emptyPlacementReady = Wait-DevWSElevatedBrokerPrepare -Connection $connection -TimeoutMilliseconds 20000
            Assert-Equal "ready" ([string]$emptyPlacementReady.type) "empty placement array over an empty set is accepted"
            Assert-Equal 0 @($emptyPlacementReady.plan.terminals).Count "placement-based plan still empty"
            $emptyPlacementAborted = Send-DevWSElevatedBrokerAbort -Connection $connection -RequestId 17
            Assert-Equal "aborted" ([string]$emptyPlacementAborted.type) "placement plan aborted without side effects"
            Close-DevWSElevatedBrokerConnection -Connection $connection

            # stale deployed code -> restart-required and clean exit
            Add-Content -LiteralPath (Join-Path $fixture.Root "app\lib\devws-broker-protocol.ps1") -Value "`n# stale test touch"
            $stale = Test-DevWSElevatedBrokerAvailable -PipeName $pipe -TimeoutMilliseconds 2000
            Assert-Equal $false $stale "stale-code broker refuses the ping"
            Assert-Equal $true ($broker.WaitForExit(15000)) "stale-code broker exits for recovery"
            $broker = $null

            # second instance exits cleanly while a broker owns the mutex
            #
            # Ownership barrier: the first broker is proven to own the fixture
            # singleton before the second is started. Its pipe name appears only
            # after WaitOne(0) already succeeded (the host creates the pipe
            # strictly after mutex acquisition), so bounded pipe presence is
            # the happens-before edge. A protocol ping cannot be used here:
            # this fixture's deployed code is intentionally stale, so a ping
            # would be answered with restart-required and the owner under test
            # would exit instead of being validated.
            $firstPipe = $pipe + ".x"
            $first = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', ('"' + (Join-Path $fixture.Privileged "workers\elevated-broker.ps1") + '"'),
                '-PipeName', $firstPipe, '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root, '-NoWarmup'
            ) -PassThru -WindowStyle Hidden

            $firstOwnsSingleton = $false
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                if (Test-DevWSElevatedBrokerPipeExists -PipeName $firstPipe -ConfirmMilliseconds 250) { $firstOwnsSingleton = $true; break }
                if ($first.HasExited) { break }
            }

            Assert-Equal $true $firstOwnsSingleton "first broker instance acquired the singleton before the second starts"

            $second = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', ('"' + (Join-Path $fixture.Privileged "workers\elevated-broker.ps1") + '"'),
                '-PipeName', ($pipe + ".y"), '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root, '-NoWarmup'
            ) -PassThru -WindowStyle Hidden

            Assert-Equal $true ($second.WaitForExit(20000)) "second broker instance exits cleanly"
            Assert-Equal 0 $second.ExitCode "second broker instance exit code is 0"
            Assert-Equal $false $first.HasExited "first broker instance still owns the singleton"
        }
        finally {
            # Exact-identity cleanup on every exit path: the rejected second
            # instance (if it ever started), the singleton owner, and the
            # original fixture broker; then the exact fixture root.
            Stop-TestFixtureProcess $second
            Stop-TestFixtureProcess $first
            Stop-TestFixtureProcess $broker
            Remove-Item -LiteralPath $fixture.Root -Recurse -Force -ErrorAction SilentlyContinue
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Stage 2 observational status keeps a stale broker resident; ping still recovers" {
        # The dedicated status command exists exactly because a launch-path ping
        # makes a stale broker exit. status reports staleness and leaves the
        # host running; the existing ping semantics are re-proven afterwards.
        . (Join-Path $LibDir "devws-broker-protocol.ps1")

        $fixture = New-InstallFixture "stage2-broker-status"
        $null = Initialize-TestPrivilegedFixture -Fixture $fixture
        $null = Install-DevWSApplicationFiles -RepoRoot $RepoRoot -InstallRoot $fixture.Root
        $null = Install-DevWSNativeRuntime -RepoRoot $RepoRoot -InstallRoot $fixture.Root

        $configPath = Join-Path $fixture.Root "broker-config.json"
        ConvertTo-TestConfig -Sets @((New-TestSet -Id "main" -Windows @()), (New-TestSet -Id "secondary" -Windows @())) |
            ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $configPath -Encoding UTF8

        $pipe  = "DevWS.Stage2.Status.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)
        $mutex = "Local\DevWS.Stage2.Status.Test." + [guid]::NewGuid().ToString("N").Substring(0, 8)

        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $configPath

        $broker = $null

        try {
            $broker = Start-Process -FilePath "pwsh" -ArgumentList @(
                '-NoProfile', '-File', ('"' + (Join-Path $fixture.Privileged "workers\elevated-broker.ps1") + '"'),
                '-PipeName', $pipe, '-MutexName', $mutex, '-InstallRootOverride', $fixture.Root
            ) -PassThru -WindowStyle Hidden

            $ready = $false
            $deadline = (Get-Date).AddSeconds(45)

            while ((Get-Date) -lt $deadline) {
                if (Test-DevWSElevatedBrokerAvailable -PipeName $pipe -TimeoutMilliseconds 1000) { $ready = $true; break }
                Start-Sleep -Milliseconds 250
            }

            Assert-Equal $true $ready "fixture broker became ready"
            $residentGeneration = [string](Get-DevWSEffectiveRuntimeGeneration -InstallRoot $fixture.Root -PrivilegedRoot $fixture.Privileged)

            # Change the fixture install so the deployed generation advances.
            Add-Content -LiteralPath (Join-Path $fixture.Root "app\lib\devws-broker-protocol.ps1") -Value "`n# stale test touch"
            $currentGeneration = [string](Get-DevWSEffectiveRuntimeGeneration -InstallRoot $fixture.Root -PrivilegedRoot $fixture.Privileged)
            Assert-True ($currentGeneration -ne $residentGeneration) "fixture generation advanced"

            # 1. observational status: stale, but the host STAYS RESIDENT
            $status = Get-DevWSElevatedBrokerStatus -PipeName $pipe -TimeoutMilliseconds 3000
            Assert-Equal "stale" $status.State "stale status reported"
            Assert-Equal $residentGeneration $status.Generation "resident generation reported"
            Assert-Equal $currentGeneration $status.CurrentGeneration "current generation reported"
            Assert-Equal $false $status.GenerationCurrent "generation currency false"
            Assert-Equal $false $broker.HasExited "stale broker stays resident after status"

            # 2. existing ping semantics unchanged: restart-required + exit
            $available = Test-DevWSElevatedBrokerAvailable -PipeName $pipe -TimeoutMilliseconds 3000
            Assert-Equal $false $available "stale ping still refuses"
            Assert-Equal $true ($broker.WaitForExit(15000)) "stale broker still exits after ping"
            $broker = $null
        }
        finally {
            if ($null -ne $broker -and -not $broker.HasExited) { Stop-Process -Id $broker.Id -Force -ErrorAction SilentlyContinue }
            Remove-Item -LiteralPath $fixture.Root -Recurse -Force -ErrorAction SilentlyContinue
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "Stage 2 app prepare launches nothing; kick launches missing back-to-back; age refresh runs once" {
        $target = New-Pass3ProbeConfig "stage2-app-split"
        $config = Read-DevWSConfigFile -Path $target
        $set    = @($config.sets | Where-Object { $_.id -eq "apps3" })[0]
        $apps   = @($set.windows | Where-Object { $_.type -eq "app" })

        $script:s2AppProbes = 0
        $script:s2AppKicks = 0
        $script:s2AppEvents = [System.Collections.Generic.List[string]]::new()

        try {
            function Get-DevWSAppWindowProbe {
                param($Config, $Candidates, [switch]$TolerantOwnership)
                $script:s2AppProbes++
                return @()
            }

            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                return [long]0
            }

            function Invoke-DevWSAppLaunchCommand {
                param($App)
                $script:s2AppKicks++
                $script:s2AppEvents.Add("kick $($App.id)") | Out-Null
            }

            function Move-DevWSWindowHwnd {
                param([long]$Hwnd, $Layout, [string]$Context)
                $script:s2AppEvents.Add("move $Context") | Out-Null
            }

            $plan = New-DevWSAppLaunchPlan -Config $config -SetId "apps3" -Apps $apps

            Assert-Equal 0 $script:s2AppKicks "app prepare launches nothing"
            Assert-Equal 3 @($plan.Missing).Count "all three apps are missing"
            Assert-Equal 2 $script:s2AppProbes "Phase A plus exactly one fresh refresh"
            Assert-Equal 0 @($plan.Failures).Count "no classification failures"

            $start = Start-DevWSAppLaunchPlan -Plan $plan
            Assert-Equal 3 $script:s2AppKicks "app kick launches every missing app"
            Assert-Equal 3 @($start.Kicks).Count "three kick records"
            Assert-Equal "kick renderer,kick editor42,kick browser" ($script:s2AppEvents -join ",") "kick order follows configured order"

            $beforeRefresh = $script:s2AppProbes
            $refreshed = Update-DevWSAppLaunchPlan -Plan $plan -Config $config -SetId "apps3"
            Assert-Equal ($beforeRefresh + 1) $script:s2AppProbes "age refresh runs exactly one fresh probe"

            $beforeSecond = $script:s2AppProbes
            $refreshed2 = Update-DevWSAppLaunchPlan -Plan $refreshed -Config $config -SetId "apps3"
            Assert-Equal ($beforeSecond + 1) $script:s2AppProbes "each explicit refresh is a single probe (no repeated loops)"

            # A refresh that resolves an app moves it to Present instead of Missing.
            $script:s2AppProbeMode = "resolved"
            function Resolve-DevWSAppLifecycleWindow {
                param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe)
                if ($script:s2AppProbeMode -eq "resolved" -and $App.id -eq "renderer") { return [long]777 }
                return [long]0
            }

            $refreshed3 = Update-DevWSAppLaunchPlan -Plan $plan -Config $config -SetId "apps3"
            Assert-Equal 1 @($refreshed3.Present).Count "an app that appeared during the refresh moves to Present"
            Assert-Equal 2 @($refreshed3.Missing).Count "the remaining apps stay missing"
        }
        finally {
            . (Join-Path $LibDir "devws-app-window.ps1")
            . (Join-Path $LibDir "devws-app.ps1")
            . (Join-Path $LibDir "devws-window-ops.ps1")
        }
    }

    Test-Case "Stage 2 post-GO-ACK broker loss never falls back to the Helper" {
        $target = Join-Path $TestRoot "stage2-goack-loss\workspace.json"
        New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
        ConvertTo-TestConfig -Sets @(
            (New-TestSet -Id "main" -Windows @(
                (New-TerminalDefinition -Id "slot" -WindowId "S2-goack-slot" -Path $TestRoot)
            ))
        ) | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $target -Encoding UTF8

        $savedConfig = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $target
        $message = $null
        $script:s2HelperCalls = 0

        try {
            function Invoke-DevWSWithLifecycleLock {
                param([Parameter(Mandatory)][scriptblock]$ScriptBlock, [int]$TimeoutSeconds = 300, [string]$MutexName = "test")
                return (& $ScriptBlock)
            }

            function Test-DevWSElevatedBrokerAvailable {
                param([string]$PipeName, [int]$TimeoutMilliseconds = 1500)
                return $true
            }

            function New-DevWSElevatedBrokerPrepare {
                param([long]$RequestId, [string]$SetId, [AllowNull()][object[]]$TerminalPlacements = $null, [string]$PipeName, [int]$TimeoutMilliseconds = 3000)
                return [pscustomobject]@{ Reader = $null; Writer = $null; Client = $null }
            }

            function Wait-DevWSElevatedBrokerPrepare {
                param($Connection, [int]$TimeoutMilliseconds = 30000)
                return [pscustomobject]@{ type = "ready"; planId = "plan-1"; plan = [pscustomobject]@{ counts = [pscustomobject]@{ present = 0; missing = 1; ambiguous = 0; failed = 0 } } }
            }

            function Send-DevWSElevatedBrokerGo {
                param($Connection, [long]$RequestId, [string]$PlanId, [int]$TimeoutMilliseconds = 10000)
                return [pscustomobject]@{ type = "go-ack"; recheckMs = 1; ackAt = 0 }
            }

            function Read-DevWSElevatedBrokerFinal {
                param($Connection, [int]$TimeoutMilliseconds = 120000)
                return $null
            }

            function Close-DevWSElevatedBrokerConnection { param($Connection) }

            function Start-DevWSWorkerRequest {
                param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60)
                $script:s2HelperCalls++
                throw "the Helper must never run after GO-ACK"
            }

            try { $null = Invoke-DevWSLaunch -SetId "main" } catch { $message = $_.Exception.Message }

            Assert-Equal 0 $script:s2HelperCalls "the Helper is never invoked after GO-ACK"
            Assert-Contains ([string]$message) "uncertain" "the failure reports an uncertain broker completion"
            Assert-Contains ([string]$message) "No fallback was attempted" "the uncertainty boundary is explicit"
        }
        finally {
            if ($null -ne $savedConfig) { $env:DEVWS_CONFIG = $savedConfig } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
            . (Join-Path $LibDir "devws-launch.ps1")
            . (Join-Path $LibDir "devws-broker-protocol.ps1")
            . (Join-Path $LibDir "devws-worker-protocol.ps1")
        }
    }

