            Error             = $null
        }
    }

    function New-StatusSyntheticModel {
        param($Terminals, $Apps, $Broker, $Coordinator, [bool]$IsDefault = $true)

        $summary = [ordered]@{ Present = 0; Missing = 0; Ambiguous = 0; Mismatch = 0; Unowned = 0; Disabled = 0; Error = 0 }

        foreach ($row in @($Terminals) + @($Apps)) {
            $key = [string]$row.State
            if ($summary.Contains($key)) { $summary[$key]++ }
        }

        return [pscustomobject]@{
            SetId               = "main"
            IsDefault           = $IsDefault
            InstalledGeneration = "FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF"
            Terminals           = @($Terminals)
            Apps                = @($Apps)
            Broker              = $Broker
            Coordinator         = $Coordinator
            Summary             = [pscustomobject]$summary
        }
    }

    function Assert-StatusClassifierParity {
        param(
            [string]$Name,
            $StateEntries,
            $Terminals,
            [long[]]$WtHwnds,
            $Readers,
            $Procs,
            $Expected
        )

        $config = [pscustomobject]@{
            defaultSet = 'main'
            sets       = @([pscustomobject]@{ id = 'main'; windows = @() })
        }

        $state = New-DevWSRuntimeState

        foreach ($entry in @($StateEntries)) {
            $state.terminals[$entry.Key] = [pscustomobject]@{ windowId = [string]$entry.WindowId; hwnd = [long]$entry.Hwnd }
        }

        $readerMap = $Readers
        $procMap   = $Procs

        $readerProvider = { param([long]$Hwnd) return $readerMap[[int]$Hwnd] }
        $procProvider   = { param([long]$Hwnd) return $procMap[[int]$Hwnd] }

        $snapshot = Get-DevWSTerminalPresenceSnapshot -Config $config -SetId 'main' -State $state -Terminals $Terminals -WtHwnds $WtHwnds -CandidateReader $readerProvider -ProcessNameProvider $procProvider

        $planner = Get-DevWSTerminalLaunchPlan -Config $config -SetId 'main' -State $state -Terminals $Terminals -WtHwnds $WtHwnds -CandidateReader $readerProvider -ProcessNameProvider $procProvider -TrackingContextFactory { param($t) $null } -CreateArgumentsFactory { param($t, $k) @() }

        for ($i = 0; $i -lt @($Terminals).Count; $i++) {
            $s = $snapshot.Terminals[$i]
            $p = $planner.Terminals[$i]
            $e = $Expected[$i]

            Assert-Equal $e.State $s.State "$Name[$i] classifier state"
            Assert-Equal $e.Source $s.Source "$Name[$i] classifier source"
            Assert-Equal ([long]$e.Hwnd) ([long]$s.Hwnd) "$Name[$i] classifier hwnd"

            Assert-Equal $s.State $p.State "$Name[$i] planner parity state"
            Assert-Equal $s.Source $p.Source "$Name[$i] planner parity source"
            Assert-Equal ([long]$s.Hwnd) ([long]$p.Hwnd) "$Name[$i] planner parity hwnd"
        }

        Assert-Equal $snapshot.Stats.StateHits $planner.Stats.StateHits "$Name stats parity (stateHits)"
        Assert-Equal $snapshot.Stats.SnapshotHits $planner.Stats.SnapshotHits "$Name stats parity (snapshotHits)"
        Assert-Equal $snapshot.Stats.FastMissing $planner.Stats.FastMissing "$Name stats parity (fastMissing)"
        Assert-Equal $snapshot.Stats.UiaReads $planner.Stats.UiaReads "$Name stats parity (uiaReads)"
    }

