            $script:statusProbeCalls = 0

            function Get-DevWSTerminalTopLevelHwnds { $script:statusWtCalls++; return [long[]]@() }
            function Resolve-DevWSTrackedCwd { param([string]$SetId, [string]$TerminalId, [string]$SessionPath, [string]$PublicationPath) $script:statusCwdCalls++; return [pscustomobject]@{ Status = "unavailable"; Reason = "expected-missing"; Cwd = $null } }
            function Get-DevWSAppWindowCandidates { param([switch]$IncludeInvisible) $script:statusCandidateCalls++; return @() }
            function Get-DevWSAppWindowProbe { param($Config, [object[]]$Candidates, [switch]$TolerantOwnership) $script:statusProbeCalls++; return @() }

            $model = Get-DevWSStatusModel -Config $config

            $rows = @{}
            foreach ($row in @($model.Terminals) + @($model.Apps)) { $rows[[string]$row.ItemId] = $row }

            Assert-Equal "disabled" $rows["t-off"].State "disabled terminal state"
            Assert-Equal "disabled" $rows["a-off"].State "disabled app state"
            Assert-Equal "missing" $rows["t-on"].State "enabled terminal still classified"
            Assert-Equal "missing" $rows["a-on"].State "enabled app still classified"
            Assert-Equal "t-off,t-on" (@($model.Terminals | ForEach-Object { $_.ItemId }) -join ",") "configured order preserved"
            Assert-Equal 1 $script:statusWtCalls "one shared WT enumeration for the enabled terminal"
            Assert-Equal 1 $script:statusCwdCalls "cwd resolved only for the enabled terminal"
            Assert-Equal 1 $script:statusCandidateCalls "one shared candidate enumeration for enabled apps"
            Assert-Equal 1 $script:statusProbeCalls "one shared probe for enabled apps"
            Assert-Equal 2 $model.Summary.Disabled "disabled summary count"
        }
        finally {
            $env:DEVWS_STATE_ROOT = $savedRoot
        }
    }

    Test-Case "terminal presence snapshot matches the launch planner across the fixture matrix" {
        Assert-StatusClassifierParity -Name "state-hit" `
