            -Terminals @((New-StatusTerminalDefinition -Id "t1" -WindowId "W1")) `
            -WtHwnds @(1001) `
            -Readers @{ 1001 = (New-StatusRead $true @("W1", "x")) } `
            -Procs @{ 1001 = "WindowsTerminal" } `
