        Assert-StatusClassifierParity -Name "state-stale-discovery" `
            -StateEntries @([pscustomobject]@{ Key = "main/t1"; WindowId = "W1"; Hwnd = 1001 }) `
            -Terminals @((New-StatusTerminalDefinition -Id "t1" -WindowId "W1")) `
            -WtHwnds @(1001, 2002) `
            -Readers @{ 1001 = (New-StatusRead $true @("W9")); 2002 = (New-StatusRead $true @("W1")) } `
            -Procs @{ 1001 = "WindowsTerminal"; 2002 = "WindowsTerminal" } `
