            -Procs @{ 4004 = "WindowsTerminal"; 4005 = "WindowsTerminal" } `
            -Expected @([pscustomobject]@{ State = "ambiguous"; Source = "snapshot"; Hwnd = 0 })

        Assert-StatusClassifierParity -Name "candidate-read-failure" `
            -StateEntries @() `
            -Terminals @((New-StatusTerminalDefinition -Id "t1" -WindowId "W3")) `
            -WtHwnds @(6006) `
            -Readers @{ 6006 = (New-StatusRead $false @()) } `
            -Procs @{ 6006 = "WindowsTerminal" } `
            -Expected @([pscustomobject]@{ State = "missing"; Source = "snapshot"; Hwnd = 0 })

        Assert-StatusClassifierParity -Name "foreign-process-same-tab-name" `
            -StateEntries @() `
            -Terminals @((New-StatusTerminalDefinition -Id "t1" -WindowId "W4")) `
            -WtHwnds @(7007) `
            -Readers @{ 7007 = (New-StatusRead $true @("W4")) } `
            -Procs @{ 7007 = "evil" } `
            -Expected @([pscustomobject]@{ State = "missing"; Source = "snapshot"; Hwnd = 0 })

        Assert-StatusClassifierParity -Name "state-from-another-set-never-validates" `
