    Test-Case "status model maps terminal classification, sources and diagnostics" {
        $configPath = New-StatusConfigPath -Name "terminal-map" -Terminals @(
            (New-StatusTerminalDefinition -Id "t1" -WindowId "W1"),
            (New-StatusTerminalDefinition -Id "t2" -WindowId "W2"),
            (New-StatusTerminalDefinition -Id "t3" -WindowId "W3"),
            (New-StatusTerminalDefinition -Id "t4" -WindowId "W4")
        )
        $config = Read-DevWSConfigFile -Path $configPath

        $savedRoot = $env:DEVWS_STATE_ROOT
        $stateRoot = New-StatusStateRoot "terminal-map"
        $env:DEVWS_STATE_ROOT = $stateRoot

        try {
            @{ version = 2; terminals = [ordered]@{ "main/t1" = [ordered]@{ windowId = "W1"; hwnd = 1001 } } } |
                ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $stateRoot "runtime-state.json") -Encoding UTF8

            function Get-DevWSTerminalTopLevelHwnds { return [long[]]@(1001, 2002, 4004, 4005) }

            function Read-DevWSTerminalHwndTabs {
                param([long]$Hwnd, [int]$EmptyRetryCount = 2, [int]$EmptyRetryDelayMilliseconds = 250)

                $map = @{
                    1001 = @("W1", "x")
                    2002 = @("W2")
                    4004 = @("W4")
                    4005 = @("W4")
                }

                $names = @($map[[int]$Hwnd])
                return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names $names); RawCount = $names.Count }
            }

            function Get-DevWSWindowHwndProcessName { param([long]$Hwnd) return "WindowsTerminal" }

            function Resolve-DevWSTrackedCwd {
                param([string]$SetId, [string]$TerminalId, [string]$SessionPath, [string]$PublicationPath)
                return [pscustomobject]@{ Status = "unavailable"; Reason = "publication-missing"; Cwd = $null }
            }

            $model = Get-DevWSStatusModel -Config $config

            $rows = @{}
            foreach ($row in $model.Terminals) { $rows[[string]$row.ItemId] = $row }

            Assert-Equal "present" $rows["t1"].State "cached state hit revalidates"
            Assert-Equal "state" $rows["t1"].Source "state source"
            Assert-Equal 1001 $rows["t1"].Hwnd "exact cached hwnd"
            Assert-Equal "present" $rows["t2"].State "stale state falls back to discovery"
            Assert-Equal "snapshot" $rows["t2"].Source "snapshot source"
            Assert-Equal 2002 $rows["t2"].Hwnd "discovered hwnd"
            Assert-Equal "missing" $rows["t3"].State "missing terminal"
            Assert-Equal "snapshot" $rows["t3"].Source "missing from snapshot"
            Assert-Equal "ambiguous" $rows["t4"].State "duplicate windowId is ambiguous"
            Assert-Contains $rows["t4"].Diagnostic "refusing to choose" "ambiguity diagnostic"
            Assert-True (([string]$rows["t4"].Diagnostic).Contains("4004") -and ([string]$rows["t4"].Diagnostic).Contains("4005")) "ambiguity names both hwnds"
            Assert-Equal 2 $model.Summary.Present "summary present"
            Assert-Equal 1 $model.Summary.Missing "summary missing"
            Assert-Equal 1 $model.Summary.Ambiguous "summary ambiguous"
        }
        finally {
            $env:DEVWS_STATE_ROOT = $savedRoot
        }
    }

    Test-Case "cwd observation is independent and read-only" {
        $configPath = New-StatusConfigPath -Name "cwd-obs" -Terminals @(
            (New-StatusTerminalDefinition -Id "t1" -WindowId "W1"),
            (New-StatusTerminalDefinition -Id "t2" -WindowId "W2"),
            (New-StatusTerminalDefinition -Id "t3" -WindowId "W3")
        )
        $config = Read-DevWSConfigFile -Path $configPath

        $savedRoot = $env:DEVWS_STATE_ROOT
        $stateRoot = New-StatusStateRoot "cwd-obs"
        $env:DEVWS_STATE_ROOT = $stateRoot

        try {
            $cwdDir = Join-Path $TestRoot "status-cwd-dir"
            New-Item -ItemType Directory -Path $cwdDir -Force | Out-Null
            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            foreach ($fixture in @(
                @{ Id = "t1"; WindowId = "W1"; SessionId = "S1"; Pub = $true;  Pid = $PID;   Cwd = $cwdDir }
                @{ Id = "t2"; WindowId = "W2"; SessionId = "S2"; Pub = $false; Pid = $null;  Cwd = $null }
                @{ Id = "t3"; WindowId = "W3"; SessionId = "S3"; Pub = $true;  Pid = 999999; Cwd = $cwdDir }
            )) {
                $sessionPath = Join-Path $stateRoot "cwd-sessions\main\$($fixture.Id).json"
                New-Item -ItemType Directory -Path (Split-Path -Parent $sessionPath) -Force | Out-Null
                @{ version = 1; setId = "main"; terminalId = $fixture.Id; windowId = $fixture.WindowId; sessionId = $fixture.SessionId } |
                    ConvertTo-Json -Compress | Set-Content -LiteralPath $sessionPath -Encoding UTF8

                if ($fixture.Pub) {
                    $pubPath = Join-Path $stateRoot "cwd\main\$($fixture.Id).json"
                    New-Item -ItemType Directory -Path (Split-Path -Parent $pubPath) -Force | Out-Null
                    @{ version = 1; setId = "main"; terminalId = $fixture.Id; windowId = $fixture.WindowId; sessionId = $fixture.SessionId; shellPid = $fixture.Pid; shellStartTimeUtc = $startIso; cwd = $fixture.Cwd; updatedAtUtc = $startIso } |
                        ConvertTo-Json -Compress | Set-Content -LiteralPath $pubPath -Encoding UTF8
                }
            }

            function Get-DevWSTerminalTopLevelHwnds { return [long[]]@() }

            $model = Get-DevWSStatusModel -Config $config

            $rows = @{}
            foreach ($row in $model.Terminals) { $rows[[string]$row.ItemId] = $row }

            Assert-Equal "available" $rows["t1"].CwdStatus "available cwd"
            Assert-Equal $cwdDir $rows["t1"].Cwd "cwd path"
            Assert-Equal "unavailable" $rows["t2"].CwdStatus "publication missing"
            Assert-Equal "publication-missing" $rows["t2"].CwdReason "publication-missing reason"
            Assert-Equal "unavailable" $rows["t3"].CwdStatus "shell dead"
            Assert-Equal "shell-dead" $rows["t3"].CwdReason "shell-dead reason"
            Assert-Equal "missing,missing,missing" (@($model.Terminals | ForEach-Object { $_.State }) -join ",") "cwd never changes terminal presence"
        }
        finally {
            $env:DEVWS_STATE_ROOT = $savedRoot
        }
    }

