                @{ Name = "one unowned candidate";   Probe = @((New-StatusProbedRow 23 "ded")); Expected = "unowned"; Hwnd = 0 }
                @{ Name = "two unowned candidates";  Probe = @((New-StatusProbedRow 24 "ded"), (New-StatusProbedRow 25 "ded")); Expected = "ambiguous"; Hwnd = 0 }
                @{ Name = "two exact owners";        Probe = @((New-StatusProbedRow 26 "ded" -OwnerKey "main/d1"), (New-StatusProbedRow 27 "ded" -OwnerKey "main/d1")); Expected = "ambiguous"; Hwnd = 0 }
                @{ Name = "owned by another app";    Probe = @((New-StatusProbedRow 28 "ded" -OwnerKey "main/other")); Expected = "missing"; Hwnd = 0 }
