    Test-Case "status host results flow into the model and render ready, stale and unavailable explicitly" {
        $genA = "AAAAAAAA000000000000000000000000000000000000000000000000000000AA"
        $genB = "BBBBBBBB000000000000000000000000000000000000000000000000000000BB"

        # rendering: both ready on one shared current generation
        $model = New-StatusSyntheticModel -Terminals @() -Apps @() `
            -Broker (New-StatusHostInfo -State "ready" -HostPid 123 -Generation $genA -GenerationCurrent $true) `
            -Coordinator (New-StatusHostInfo -State "ready" -HostPid 456 -Generation $genA -GenerationCurrent $true)

        $text = (@(Get-DevWSStatusLines -Model $model) -join "`n")
        Assert-Contains $text "broker ready pid 123" "broker ready rendered"
        Assert-Contains $text "coordinator ready pid 456" "coordinator ready rendered"
        Assert-Contains $text "gen AAAAAAAA current" "single shared current-generation token"

        # rendering: stale broker with an explicit resident -> current arrow
        $model = New-StatusSyntheticModel -Terminals @() -Apps @() `
            -Broker (New-StatusHostInfo -State "stale" -HostPid 123 -Generation $genA -CurrentGeneration $genB -GenerationCurrent $false) `
            -Coordinator (New-StatusHostInfo -State "unavailable")

        $text = (@(Get-DevWSStatusLines -Model $model) -join "`n")
        Assert-Contains $text "broker stale pid 123 gen AAAAAAAA -> BBBBBBBB" "stale arrow rendered"
        Assert-Contains $text "coordinator unavailable" "unavailable rendered"

        # model: host state passthrough (ready)
        $configPath = New-StatusConfigPath -Name "hosts" -Terminals @()
        $config = Read-DevWSConfigFile -Path $configPath

        function Get-DevWSElevatedBrokerStatus { param([string]$PipeName, [int]$TimeoutMilliseconds = 1500) return [pscustomobject]@{ State = "ready"; Pid = 1234; Generation = "AAAAAAAAAAAAAAAA"; CurrentGeneration = "AAAAAAAAAAAAAAAA"; GenerationCurrent = $true; Error = $null } }
        function Get-DevWSCoordinatorStatus { param([string]$PipeName, [int]$TimeoutMilliseconds = 1500) return [pscustomobject]@{ State = "stale"; Pid = 99; Generation = "AAAAAAAAAAAAAAAA"; CurrentGeneration = "BBBBBBBBBBBBBBBB"; GenerationCurrent = $false; UptimeSeconds = 5.0; Error = "restart-required" } }

        $live = Get-DevWSStatusModel -Config $config
        Assert-Equal "ready" $live.Broker.State "broker state passthrough"
        Assert-Equal 1234 $live.Broker.Pid "broker pid passthrough"
        Assert-Equal "stale" $live.Coordinator.State "coordinator state passthrough"
        Assert-Equal $false $live.Coordinator.GenerationCurrent "coordinator currency passthrough"
        Assert-Equal 0 $live.Summary.Present "hosts never enter the item summary"
    }

