            (New-StatusTerminalRow -Id "studio" -State "missing" -Path "C:\DevWS-Fixture\workspaces\studio"),
            (New-StatusTerminalRow -Id "notes" -State "disabled" -Path "C:\Status\notes"),
            (New-StatusTerminalRow -Id "scratch" -State "present" -Hwnd 0x1F0C22 -CwdStatus "unavailable" -CwdReason "shell-dead"),
            (New-StatusTerminalRow -Id "dup" -State "ambiguous" -Diagnostic "windowId 'W' is exposed by 2 Windows Terminal windows (HWNDs 1, 2); refusing to choose.")
        ) -Apps @(
            (New-StatusAppRow -Id "firefox" -State "present" -Hwnd 0x2B0B56),
            (New-StatusAppRow -Id "candidate" -State "unowned" -Candidates @(0x30)),
            (New-StatusAppRow -Id "codex" -State "mismatch" -Hwnd 0x3F1A90),
            (New-StatusAppRow -Id "multi" -State "ambiguous" -Candidates @(0x41, 0x42)),
            (New-StatusAppRow -Id "corrupt" -State "error" -Reason "ownership-corrupt"),
            (New-StatusAppRow -Id "off" -State "disabled" -Mode "shared")
        ) -Broker (New-StatusHostInfo -State "ready" -HostPid 123 -Generation $gen -GenerationCurrent $true) `
          -Coordinator (New-StatusHostInfo -State "ready" -HostPid 456 -Generation $gen -GenerationCurrent $true)

        $lines = @(Get-DevWSStatusLines -Model $model)
        $text = $lines -join "`n"

        Assert-Contains $text "WORKSPACE: main (default)" "header with default marker"
        Assert-Contains $text "terminal  slot" "terminal type label"
        Assert-Contains $text "app       firefox" "app type label"
        Assert-Contains $text "cwd C:\DevWS-Fixture\workspaces\slot" "present terminal shows live cwd"
        Assert-Contains $text "path C:\DevWS-Fixture\workspaces\studio" "missing terminal shows configured path"
        Assert-Contains $text "cwd unavailable (shell-dead)" "present terminal cwd reason"
        Assert-Contains $text "refusing to choose" "ambiguity diagnostic shown"
        Assert-Contains $text "unowned candidate 0x30" "unowned wording"
        Assert-Contains $text "owned hwnd 0x3F1A90 no longer matches" "mismatch wording"
        Assert-Contains $text "2 candidates (0x41, 0x42)" "ambiguous app wording"
        Assert-Contains $text "ownership-corrupt" "error reason"
        Assert-Contains $text "3 present " "summary present count"
        Assert-Contains $text "1 missing " "summary missing count"
        Assert-Contains $text "2 ambiguous " "summary ambiguous count"
        Assert-Contains $text "1 mismatch " "summary mismatch count"
        Assert-Contains $text "1 unowned " "summary unowned count"
        Assert-Contains $text "2 disabled " "summary disabled count"
        Assert-Contains $text "1 error" "summary error count"

        # configured order is preserved across terminals and apps
        Assert-True ($text.IndexOf("slot") -lt $text.IndexOf("studio")) "order: slot before studio"
        Assert-True ($text.IndexOf("studio") -lt $text.IndexOf("notes")) "order: studio before notes"
        Assert-True ($text.IndexOf("dup") -lt $text.IndexOf("firefox")) "order: terminals before apps"
        Assert-True ($text.IndexOf("firefox") -lt $text.IndexOf("candidate")) "order: apps in configured order"

        # a missing terminal never shows a stale cwd
        $studioLine = @($lines | Where-Object { $_ -match "studio" })[0]
        Assert-NotContains $studioLine "cwd" "missing terminal omits stale cwd"
    }

    Test-Case "status never mutates config, runtime state, cwd session or publication bytes" {
        $configPath = New-StatusConfigPath -Name "byte-identity" -Terminals @(
            (New-StatusTerminalDefinition -Id "t1" -WindowId "W1"),
            (New-StatusTerminalDefinition -Id "t2" -WindowId "W2")
        )
        $config = Read-DevWSConfigFile -Path $configPath

        $savedRoot = $env:DEVWS_STATE_ROOT
        $stateRoot = New-StatusStateRoot "byte-identity"
        $env:DEVWS_STATE_ROOT = $stateRoot

        try {
            $cwdDir = Join-Path $TestRoot "status-byte-cwd"
            New-Item -ItemType Directory -Path $cwdDir -Force | Out-Null
            $startIso = (Get-Process -Id $PID).StartTime.ToUniversalTime().ToString("o")

            @{ version = 2; terminals = [ordered]@{ "main/t1" = [ordered]@{ windowId = "W1"; hwnd = 1001 } } } |
                ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $stateRoot "runtime-state.json") -Encoding UTF8

            $sessionPath = Join-Path $stateRoot "cwd-sessions\main\t1.json"
            New-Item -ItemType Directory -Path (Split-Path -Parent $sessionPath) -Force | Out-Null
            @{ version = 1; setId = "main"; terminalId = "t1"; windowId = "W1"; sessionId = "S1" } |
                ConvertTo-Json -Compress | Set-Content -LiteralPath $sessionPath -Encoding UTF8

            $pubPath = Join-Path $stateRoot "cwd\main\t1.json"
            New-Item -ItemType Directory -Path (Split-Path -Parent $pubPath) -Force | Out-Null
            @{ version = 1; setId = "main"; terminalId = "t1"; windowId = "W1"; sessionId = "S1"; shellPid = $PID; shellStartTimeUtc = $startIso; cwd = $cwdDir; updatedAtUtc = $startIso } |
                ConvertTo-Json -Compress | Set-Content -LiteralPath $pubPath -Encoding UTF8

            function Get-DevWSTerminalTopLevelHwnds { return [long[]]@(1001) }
            function Read-DevWSTerminalHwndTabs {
                param([long]$Hwnd, [int]$EmptyRetryCount = 2, [int]$EmptyRetryDelayMilliseconds = 250)
                return [pscustomobject]@{ Ok = $true; TabNames = (New-DevWSPresentTabNameSet -Names @("W1")); RawCount = 1 }
            }
            function Get-DevWSWindowHwndProcessName { param([long]$Hwnd) return "WindowsTerminal" }

            $before = [ordered]@{
                Config       = Get-FileBase64 -Path $configPath
                State        = Get-FileBase64 -Path (Join-Path $stateRoot "runtime-state.json")
                Session      = Get-FileBase64 -Path $sessionPath
                Publication  = Get-FileBase64 -Path $pubPath
            }

            $model = Get-DevWSStatusModel -Config $config

            # the run must actually have used the fixtures
            $t1 = @($model.Terminals | Where-Object { $_.ItemId -eq "t1" })[0]
            Assert-Equal "present" $t1.State "fixture terminal classified"
            Assert-Equal "available" $t1.CwdStatus "fixture cwd resolved"

            Assert-Equal $before.Config (Get-FileBase64 -Path $configPath) "config bytes unchanged"
            Assert-Equal $before.State (Get-FileBase64 -Path (Join-Path $stateRoot "runtime-state.json")) "runtime state bytes unchanged"
            Assert-Equal $before.Session (Get-FileBase64 -Path $sessionPath) "cwd session bytes unchanged"
            Assert-Equal $before.Publication (Get-FileBase64 -Path $pubPath) "cwd publication bytes unchanged"
        }
        finally {
            $env:DEVWS_STATE_ROOT = $savedRoot
        }
    }

    Test-Case "status exits non-zero only when a status cannot be produced" {
