    Write-Host ""
    Start-TestGroup -Name 'monitors' -Title 'Read-only monitor diagnostics'

    function New-MonitorTestGdiRow {
        param(
            [Parameter(Mandatory)][string]$GdiDeviceName,
            [bool]$Primary = $false,
            [int]$X = 0,
            [int]$Y = 0,
            [int]$W = 1920,
            [int]$H = 1080,
            $WorkX,
            $WorkY,
            $WorkW,
            $WorkH,
            [bool]$DpiOk = $true,
            [uint32]$DpiEffectiveX = 96
        )

        $workXValue = $X
        $workYValue = $Y
        $workWValue = $W
        $workHValue = $H

        if ($null -ne $WorkX) { $workXValue = [int]$WorkX }
        if ($null -ne $WorkY) { $workYValue = [int]$WorkY }
        if ($null -ne $WorkW) { $workWValue = [int]$WorkW }
        if ($null -ne $WorkH) { $workHValue = [int]$WorkH }

        return [pscustomobject]@{
            HMonitor      = 0
            GdiDeviceName = $GdiDeviceName
            Primary       = $Primary
            MonitorLeft   = $X
            MonitorTop    = $Y
            MonitorRight  = $X + $W
            MonitorBottom = $Y + $H
            WorkLeft      = $workXValue
            WorkTop       = $workYValue
            WorkRight     = $workXValue + $workWValue
            WorkBottom    = $workYValue + $workHValue
            DpiOk         = $DpiOk
            DpiEffectiveX = $DpiEffectiveX
            DpiEffectiveY = $DpiEffectiveX
        }
    }

    function New-MonitorTestPathRow {
        param(
            [Parameter(Mandatory)][string]$GdiDeviceName,
            [string]$DevicePath = '\\?\DISPLAY#ACME001#5&1a2b3c4d&0&UID1100#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}',
            [string]$FriendlyName = '',
            [uint32]$OutputTechnology = 10,
            [uint32]$ConnectorInstance = 0,
            [int]$SourceX = 0,
            [int]$SourceY = 0,
            [int]$SourceW = 1920,
            [int]$SourceH = 1080
        )

        return [pscustomobject]@{
            GdiDeviceName       = $GdiDeviceName
            SourceAdapterLuid   = '00000000:00010000'
            SourceId            = 0
            TargetAdapterLuid   = '00000000:00010000'
            TargetId            = 1
            OutputTechnology    = $OutputTechnology
            TargetAvailable     = $true
            FriendlyName        = $FriendlyName
            MonitorDevicePath   = $DevicePath
            EdidManufactureId   = 0
            EdidProductCodeId   = 0
            ConnectorInstance   = $ConnectorInstance
            SourceModePositionX = $SourceX
            SourceModePositionY = $SourceY
            SourceModeWidth     = $SourceW
            SourceModeHeight    = $SourceH
            TargetActiveWidth   = $SourceW
            TargetActiveHeight  = $SourceH
        }
    }

    function New-MonitorTestEdid {
        param(
            [string]$Manufacturer = 'MSI',
            [string]$Product = '4CD2',
            [uint32]$SerialNumber = 0,
            [string]$SerialString = '',
            [string]$MonitorName = ''
        )

        return [pscustomobject]@{
            Manufacturer = $Manufacturer
            Product      = $Product
            SerialNumber = $SerialNumber
            SerialString = $SerialString
            MonitorName  = $MonitorName
            RawLength    = 128
        }
    }

    function New-MonitorTestEdidBytes {
        param(
            [string]$Manufacturer = 'MSI',
            [string]$Product = '4CD2',
            [uint32]$SerialNumber = 0,
            $SerialString,
            $MonitorName
        )

        $bytes = New-Object byte[] 128
        $bytes[0] = 0

        for ($index = 1; $index -le 6; $index++) { $bytes[$index] = 0xFF }

        $bytes[7] = 0

        $letter1 = [int][char]$Manufacturer[0] - 64
        $letter2 = [int][char]$Manufacturer[1] - 64
        $letter3 = [int][char]$Manufacturer[2] - 64
        $bits = ($letter1 -shl 10) -bor ($letter2 -shl 5) -bor $letter3
        $bytes[8] = [byte](($bits -shr 8) -band 0xFF)
        $bytes[9] = [byte]($bits -band 0xFF)

        $productValue = [Convert]::ToInt32($Product, 16)
        $bytes[10] = [byte]($productValue -band 0xFF)
        $bytes[11] = [byte](($productValue -shr 8) -band 0xFF)

        $bytes[12] = [byte]($SerialNumber -band 0xFF)
        $bytes[13] = [byte](($SerialNumber -shr 8) -band 0xFF)
        $bytes[14] = [byte](($SerialNumber -shr 16) -band 0xFF)
        $bytes[15] = [byte](($SerialNumber -shr 24) -band 0xFF)

        $offset = 54

        foreach ($pair in @(@(0xFF, $SerialString), @(0xFC, $MonitorName))) {
            if ($null -eq $pair[1]) { $offset += 18; continue }

            $bytes[$offset] = 0
            $bytes[$offset + 1] = 0
            $bytes[$offset + 2] = 0
            $bytes[$offset + 3] = [byte]$pair[0]
            $bytes[$offset + 4] = 0

            $text = [string]$pair[1]

            for ($index = 0; $index -lt $text.Length -and $index -lt 13; $index++) {
                $bytes[$offset + 5 + $index] = [byte][char]$text[$index]
            }

            if ($text.Length -lt 13) { $bytes[$offset + 5 + $text.Length] = 10 }

            $offset += 18
        }

        return $bytes
    }

    function New-MonitorTestFixtureModel {
        param([switch]$Reversed)

        $gdiMag    = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -Primary $true -X 0 -Y 0 -W 2560 -H 1440
        $gdiLaptop = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY1' -X 2560 -Y 355 -W 1920 -H 1080
        $pathMag   = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY4' -FriendlyName 'ACME 27Q X10' -OutputTechnology 10 -SourceW 2560 -SourceH 1440
        $pathLap   = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY1' -DevicePath '\\?\DISPLAY#ACME002#4&5e6f7a8b&0&UID2200#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}' -OutputTechnology ([uint32]2147483648) -SourceX 2560 -SourceY 355

        if ($Reversed) {
            return ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiLaptop, $gdiMag) -PathRows @($pathLap, $pathMag) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        }

        return ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag, $gdiLaptop) -PathRows @($pathMag, $pathLap) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
    }

    Test-Case "monitor identity chain uses meaningful EDID serials and falls back exactly" {
        $instance = 'ACME001/5&1A2B3C4D&0&UID1100'

        $stringSerial = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -SerialString 'CN-123456' -SerialNumber 0x1A2B3C4D) -DevicePathInstance $instance
        Assert-Equal 'edid:MSI-4CD2-CN-123456' $stringSerial.Token "string serial wins over numeric"
        Assert-Equal 'edid' $stringSerial.Source "string serial identity source"

        $numericSerial = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -SerialNumber 0x1A2B3C4D) -DevicePathInstance $instance
        Assert-Equal 'edid:MSI-4CD2-0x1A2B3C4D' $numericSerial.Token "numeric serial renders as invariant hex"
        Assert-Equal 'edid' $numericSerial.Source "numeric serial identity source"

        $zeroNumeric = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -SerialNumber 0) -DevicePathInstance $instance
        Assert-Equal "path:$instance" $zeroNumeric.Token "numeric zero is not an identity"

        $placeholder = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -SerialNumber 0x01010101) -DevicePathInstance $instance
        Assert-Equal "path:$instance" $placeholder.Token "0x01010101 is not an identity"

        $blankString = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -SerialString '   ') -DevicePathInstance $instance
        Assert-Equal "path:$instance" $blankString.Token "blank serial string is not an identity"

        $zeroString = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -SerialString '000000' -SerialNumber 0x01010101) -DevicePathInstance $instance
        Assert-Equal "path:$instance" $zeroString.Token "all-zero serial string is not an identity"

        $noEdid = Get-DevWSMonitorIdentityToken -Edid $null -DevicePathInstance $instance
        Assert-Equal "path:$instance" $noEdid.Token "device-path fallback without EDID"
        Assert-Equal 'path' $noEdid.Source "device-path identity source"

        $serialWithoutFacts = Get-DevWSMonitorIdentityToken -Edid (New-MonitorTestEdid -Manufacturer '' -Product '' -SerialString 'SN9') -DevicePathInstance $instance
        Assert-Equal "path:$instance" $serialWithoutFacts.Token "unbuildable edid token falls back to the device path"

        $unavailable = Get-DevWSMonitorIdentityToken -Edid $null -DevicePathInstance $null
        Assert-Equal $null $unavailable.Token "no identity facts at all"
        Assert-Equal 'unavailable' $unavailable.Source "unavailable identity source"
    }

    Test-Case "monitor device paths normalize strictly and never use ordinals" {
        $standard = ConvertFrom-DevWSMonitorDevicePath -DevicePath '\\?\DISPLAY#ACME001#5&1a2b3c4d&0&UID1100#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'
        Assert-Equal 'ACME001' $standard.HardwareId "hardware id extracted"
        Assert-Equal 'ACME001/5&1A2B3C4D&0&UID1100' $standard.Instance "instance normalized and upper-cased"

        $lower = ConvertFrom-DevWSMonitorDevicePath -DevicePath '\\?\display#acme001#5&1a2b3c4d&0&uid1100#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'
        Assert-Equal $standard.Instance $lower.Instance "casing is normalized consistently"

        $withoutGuid = ConvertFrom-DevWSMonitorDevicePath -DevicePath '\\?\DISPLAY#ACME002#4&5e6f7a8b&0&UID2200'
        Assert-Equal 'ACME002/4&5E6F7A8B&0&UID2200' $withoutGuid.Instance "interface GUID is optional and ignored"

        foreach ($malformed in @(
            '',
            'nonsense',
            '\\.\DISPLAY1',
            '\\?\DISPLAY#ABC',
            '\\?\DISPLAY##x#{}',
            '\\?\DISPLAY#ABC#',
            'DISPLAY#ABC#DEF',
            '\\?\DISPLAY#AB C#DEF'
        )) {
            $parsed = ConvertFrom-DevWSMonitorDevicePath -DevicePath $malformed
            Assert-Equal $null $parsed "malformed path refused: '$malformed'"
        }
    }

    Test-Case "EDID parsing extracts identity fields and rejects malformed data" {
        $bytes = New-MonitorTestEdidBytes -Manufacturer 'MSI' -Product '4CD2' -SerialNumber 0x11223344 -SerialString 'SN00001' -MonitorName 'TEST PANEL'
        $edid = ConvertFrom-DevWSMonitorEdidBytes -Bytes $bytes

        Assert-Equal 'MSI' $edid.Manufacturer "EDID manufacturer"
        Assert-Equal '4CD2' $edid.Product "EDID product code"
        Assert-Equal ([uint32]0x11223344) $edid.SerialNumber "EDID numeric serial"
        Assert-Equal 'SN00001' $edid.SerialString "EDID serial-string descriptor"
        Assert-Equal 'TEST PANEL' $edid.MonitorName "EDID monitor-name descriptor"
        Assert-Equal 128 $edid.RawLength "EDID raw length"

        $emptyDescriptors = ConvertFrom-DevWSMonitorEdidBytes -Bytes (New-MonitorTestEdidBytes)
        Assert-Equal '' $emptyDescriptors.SerialString "no serial descriptor"
        Assert-Equal '' $emptyDescriptors.MonitorName "no name descriptor"

        Assert-Equal $null (ConvertFrom-DevWSMonitorEdidBytes -Bytes (New-Object byte[] 64)) "short EDID refused"

        $badHeader = New-MonitorTestEdidBytes
        $badHeader[0] = 1
        Assert-Equal $null (ConvertFrom-DevWSMonitorEdidBytes -Bytes $badHeader) "bad EDID header refused"

        Assert-Equal $null (ConvertFrom-DevWSMonitorEdidBytes -Bytes $null) "missing EDID refused"
    }

    Test-Case "topology model correlates GDI and QDC rows deterministically" {
        $gdiMag  = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -Primary $true -X 0 -Y 0 -W 2560 -H 1440
        $gdiLap  = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY1' -X 2560 -Y 355 -W 1920 -H 1080
        $pathMag = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY4' -FriendlyName 'ACME 27Q X10'
        $pathLap = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY1' -DevicePath '\\?\DISPLAY#ACME002#4&5e6f7a8b&0&UID2200#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}' -OutputTechnology ([uint32]2147483648)

        $model = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag, $gdiLap) -PathRows @($pathLap, $pathMag) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal $true $model.Available "model available"
        Assert-Equal 2 @($model.Monitors).Count "both monitors represented"
        Assert-Equal '\\.\DISPLAY4' $model.Monitors[0].GdiDeviceName "GDI order preserved"
        Assert-Equal 'ACME 27Q X10' $model.Monitors[0].FriendlyName "QDC facts attach by device name, not array order"
        Assert-Equal 'path:ACME001/5&1A2B3C4D&0&UID1100' $model.Monitors[0].IdentityToken "first monitor identity"
        Assert-Equal 'path:ACME002/4&5E6F7A8B&0&UID2200' $model.Monitors[1].IdentityToken "second monitor identity"
        Assert-Equal $true $model.IdentityComplete "identity complete"
        Assert-Equal $true $model.CorrelationComplete "correlation complete"
        Assert-Equal 1 $model.Attempts "attempts passthrough"

        # A GDI monitor without QDC facts is retained with identity unavailable.
        $lonelyModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag) -PathRows @() -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal 1 @($lonelyModel.Monitors).Count "unmatched GDI monitor retained"
        Assert-Equal $null $lonelyModel.Monitors[0].IdentityToken "unmatched monitor has no identity"
        Assert-Equal 'unavailable' $lonelyModel.Monitors[0].IdentitySource "unmatched monitor identity source"
        Assert-Equal $false $lonelyModel.IdentityComplete "identity incomplete without facts"
        Assert-Equal $false $lonelyModel.CorrelationComplete "correlation incomplete without facts"
        Assert-Equal $null $lonelyModel.Signature "no signature without identity"

        # An extra active path without GDI geometry blocks the signature too.
        $extraModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag) -PathRows @($pathMag, $pathLap) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal $true $extraModel.IdentityComplete "represented monitor identity complete"
        Assert-Equal $false $extraModel.CorrelationComplete "extra path breaks correlation"
        Assert-Equal 1 $extraModel.UncorrelatedPathCount "uncorrelated path counted"
        Assert-Equal $null $extraModel.Signature "no signature from a partial topology"

        # Duplicate GDI device-name anomalies are correlation failures.
        $duplicateModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag, $gdiMag) -PathRows @($pathMag) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal $false $duplicateModel.CorrelationComplete "duplicate device name breaks correlation"
        Assert-Equal $null $duplicateModel.Signature "duplicate device name blocks the signature"

        # Internal panel: internal technology and empty friendly name.
        Assert-Equal $true $model.Monitors[1].IsInternal "internal output technology flagged"
        Assert-Equal '' $model.Monitors[1].FriendlyName "internal friendly name stays empty"

        $failedModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @() -PathRows @() -Attempts 3 -ErrorCode 87 -EdidByInstance @{}
        Assert-Equal $false $failedModel.Available "incoherent acquisition unavailable"
        Assert-Equal 87 $failedModel.ErrorCode "error code carried"
        Assert-Equal $null $failedModel.Signature "no signature on acquisition failure"
        Assert-Contains $failedModel.Error "87" "acquisition error names the win32 error"
        Assert-Contains $failedModel.Error "coherent" "acquisition error is explicit"
    }

    Test-Case "topology signature and fingerprint are order-independent and exact" {
        $normal    = New-MonitorTestFixtureModel
        $reversed  = New-MonitorTestFixtureModel -Reversed

        $expectedSignature = 'path:ACME001/5&1A2B3C4D&0&UID1100@0,0,2560x1440;path:ACME002/4&5E6F7A8B&0&UID2200@2560,355,1920x1080'
        $expectedFingerprint = 'D494EB2198C174BAAED24A7F03AE892FCC3180D8039AF22D5C96BFB0D7B1D28A'

        Assert-Equal $expectedSignature $normal.Signature "canonical signature"
        Assert-Equal $expectedFingerprint $normal.Fingerprint "fingerprint is the stable SHA-256 of the canonical signature"
        Assert-Equal $normal.Signature $reversed.Signature "signature ignores enumeration order"
        Assert-Equal $normal.Fingerprint $reversed.Fingerprint "fingerprint ignores enumeration order"

        # Work-area changes never affect the signature.
        $gdiMag  = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -Primary $true -X 0 -Y 0 -W 2560 -H 1440 -WorkW 2560 -WorkH 1392
        $gdiLap  = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY1' -X 2560 -Y 355 -W 1920 -H 1080 -WorkW 1920 -WorkH 1032
        $pathMag = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY4' -FriendlyName 'ACME 27Q X10'
        $pathLap = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY1' -DevicePath '\\?\DISPLAY#ACME002#4&5e6f7a8b&0&UID2200#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'

        $taskbarModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag, $gdiLap) -PathRows @($pathMag, $pathLap) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal $normal.Signature $taskbarModel.Signature "work-area changes keep the signature"
        Assert-Equal $normal.Fingerprint $taskbarModel.Fingerprint "work-area changes keep the fingerprint"

        # A primary-role flip alone (same identities and rects) keeps the signature.
        $flipMag = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -Primary $false -X 0 -Y 0 -W 2560 -H 1440
        $flipLap = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY1' -Primary $true -X 2560 -Y 355 -W 1920 -H 1080
        $flipModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($flipMag, $flipLap) -PathRows @($pathMag, $pathLap) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal $normal.Signature $flipModel.Signature "primary bit alone keeps the signature"

        # Geometry changes must change the signature.
        $resizedMag = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -Primary $true -X 0 -Y 0 -W 1920 -H 1080
        $resizedModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($resizedMag, $gdiLap) -PathRows @($pathMag, $pathLap) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-True ($resizedModel.Signature -ne $normal.Signature) "resolution change alters the signature"

        $movedLap = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY1' -X 2560 -Y 0 -W 1920 -H 1080
        $movedModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag, $movedLap) -PathRows @($pathMag, $pathLap) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-True ($movedModel.Signature -ne $normal.Signature) "position change alters the signature"

        # An extra active monitor changes the signature.
        $gdiThird  = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY7' -X 4480 -Y 0 -W 1280 -H 720
        $pathThird = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY7' -DevicePath '\\?\DISPLAY#ABC1234#9&55555&1&UID999999#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'
        $thirdModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdiMag, $gdiLap, $gdiThird) -PathRows @($pathMag, $pathLap, $pathThird) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal 3 @($thirdModel.Monitors).Count "third monitor represented"
        Assert-True ($thirdModel.Signature -ne $normal.Signature) "extra monitor alters the signature"

        # Negative origins render exactly.
        $negativeMag = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -Primary $true -X -1920 -Y 0 -W 1920 -H 1080
        $negativeModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($negativeMag) -PathRows @($pathMag) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal 'path:ACME001/5&1A2B3C4D&0&UID1100@-1920,0,1920x1080' $negativeModel.Signature "negative-origin signature"

        # Duplicate identities at different rectangles are legal multiset members.
        $gdi8 = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY8' -Primary $true -X 0 -Y 0 -W 1000 -H 1000
        $gdi9 = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY9' -X 1000 -Y 0 -W 1000 -H 1000
        $path8 = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY8' -DevicePath '\\?\DISPLAY#DUP0001#1&1&0&UID1#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'
        $path9 = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY9' -DevicePath '\\?\DISPLAY#DUP0001#1&1&0&UID1#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'
        $duplicateModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdi8, $gdi9) -PathRows @($path8, $path9) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal 'path:DUP0001/1&1&0&UID1@0,0,1000x1000;path:DUP0001/1&1&0&UID1@1000,0,1000x1000' $duplicateModel.Signature "duplicate identities at different rects stay representable"
        Assert-Equal $false $duplicateModel.IdentityAmbiguous "different rectangles are not ambiguous"

        $gdi9Same = New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY9' -X 0 -Y 0 -W 1000 -H 1000
        $sameRectPath = New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY9' -DevicePath '\\?\DISPLAY#DUP0001#1&1&0&UID1#{e6f07b5f-ee97-4a90-b076-33f57bf4eaa7}'
        $ambiguousModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @($gdi8, $gdi9Same) -PathRows @($path8, $sameRectPath) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        Assert-Equal $true $ambiguousModel.IdentityAmbiguous "identical identity at identical rectangle is flagged"
    }

    Test-Case "monitor reachability matches the locked rule including threshold edges" {
        $monitor = @(New-DevWSMonitorRect -X 0 -Y 0 -W 1000 -H 1000)

        $full = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 0 -Y 0 -W 500 -H 500) -MonitorRects $monitor
        Assert-Equal $true $full.Reachable "fully visible rect is reachable"
        Assert-Equal ([long]250000) $full.VisibleArea "fully visible area"

        $overhang = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X -7 -Y 0 -W 500 -H 500) -MonitorRects $monitor
        Assert-Equal $true $overhang.Reachable "slight negative border overlap stays reachable"

        $spanMonitors = @(
            (New-DevWSMonitorRect -X 0 -Y 0 -W 1000 -H 1000)
            (New-DevWSMonitorRect -X 1000 -Y 0 -W 1000 -H 1000)
        )
        $span = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 950 -Y 0 -W 100 -H 500) -MonitorRects $spanMonitors
        Assert-Equal $true $span.Reachable "rect spanning two monitors is reachable"
        Assert-Equal 100 $span.VisibleWidth "span visible width"

        $sliver = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 940 -Y 100 -W 400 -H 300) -MonitorRects $monitor
        Assert-Equal $false $sliver.Reachable "60 px sliver is unreachable"

        $corner = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 980 -Y 980 -W 400 -H 300) -MonitorRects $monitor
        Assert-Equal $false $corner.Reachable "20 px corner is unreachable"

        $offscreen = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 2000 -Y 0 -W 400 -H 300) -MonitorRects $monitor
        Assert-Equal $false $offscreen.Reachable "fully off-screen is unreachable"
        Assert-Equal ([long]0) $offscreen.VisibleArea "fully off-screen has no visible area"

        $strip = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 100 -Y 960 -W 800 -H 300) -MonitorRects $monitor
        Assert-Equal $true $strip.Reachable "800x40 visible strip is reachable"
        Assert-Equal 40 $strip.VisibleHeight "strip visible height"

        $ratioExact = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 950 -Y 950 -W 100 -H 100) -MonitorRects $monitor
        Assert-Equal $true $ratioExact.Reachable "exactly 25 percent visible is reachable"
        Assert-Equal ([long]2500) $ratioExact.VisibleArea "exactly 25 percent visible area"

        $ratioUnder = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 951 -Y 951 -W 100 -H 100) -MonitorRects $monitor
        Assert-Equal $false $ratioUnder.Reachable "just under 25 percent is unreachable"

        $dimensions = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 900 -Y 960 -W 300 -H 200) -MonitorRects $monitor
        Assert-Equal $true $dimensions.Reachable "100x40 visible passes the dimension branch"
        Assert-Equal ([long]4000) $dimensions.VisibleArea "dimension branch visible area"

        $width99 = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 901 -Y 960 -W 300 -H 200) -MonitorRects $monitor
        Assert-Equal $false $width99.Reachable "99 px visible width fails the dimension branch"

        $height39 = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 900 -Y 961 -W 300 -H 200) -MonitorRects $monitor
        Assert-Equal $false $height39.Reachable "39 px visible height fails the dimension branch"

        $negativeMonitor = @(New-DevWSMonitorRect -X -1920 -Y 0 -W 1920 -H 1080)
        $negativeReach = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X -1800 -Y 100 -W 800 -H 600) -MonitorRects $negativeMonitor
        Assert-Equal $true $negativeReach.Reachable "negative-origin monitor reachability"
        $negativeMissing = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X -4000 -Y 100 -W 800 -H 600) -MonitorRects $negativeMonitor
        Assert-Equal $false $negativeMissing.Reachable "rect on a vanished negative-origin monitor is unreachable"

        # Overlapping monitor rectangles are never double-counted.
        $overlapping = @(
            (New-DevWSMonitorRect -X 0 -Y 0 -W 1000 -H 1000)
            (New-DevWSMonitorRect -X 500 -Y 0 -W 1000 -H 1000)
        )
        $overlap = Test-DevWSRectReachable -Rect (New-DevWSMonitorRect -X 0 -Y 0 -W 1000 -H 1000) -MonitorRects $overlapping
        Assert-Equal ([long]1000000) $overlap.VisibleArea "overlapping monitors are unioned, not double-counted"
        Assert-Equal $true $overlap.Reachable "overlap union reachable"
    }

    Test-Case "monitor formatter renders deterministic read-only diagnostics" {
        $model = New-MonitorTestFixtureModel
        $lines = @(Get-DevWSMonitorLines -Topology $model)
        $text  = $lines -join "`n"

        Assert-Contains $text "* ACME 27Q X10" "primary marker and friendly name"
        Assert-Contains $text "id      path:ACME001/5&1A2B3C4D&0&UID1100" "full identity token rendered"
        Assert-Contains $text "rect    x=0 y=0 w=2560 h=1440" "primary rect rendered"
        Assert-Contains $text "work    x=0 y=0 w=2560 h=1440" "work rect rendered"
        Assert-Contains $text "scale   100% (96 dpi)" "scale rendered"
        Assert-Contains $text "output  DisplayPortExternal" "external output technology rendered"
        Assert-Contains $text "Internal display" "internal friendly fallback"
        Assert-Contains $text "rect    x=2560 y=355 w=1920 h=1080" "second rect rendered"
        Assert-Contains $text "output  Internal" "internal output technology rendered"
        Assert-Contains $text "TOPOLOGY" "topology section"
        Assert-Contains $text "fingerprint  D494EB2198C1" "short fingerprint rendered"
        Assert-Contains $text "identity     complete" "identity complete wording"
        Assert-Contains $text "monitors     2" "monitor count"
        Assert-NotContains $text ([string][char]27) "no ANSI escapes are required"

        $gdiOnly = ConvertTo-DevWSMonitorTopologyModel -GdiRows @((New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4')) -PathRows @() -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        $incompleteText = (@(Get-DevWSMonitorLines -Topology $gdiOnly)) -join "`n"
        Assert-Contains $incompleteText "identity     incomplete" "incomplete identity wording"
        Assert-Contains $incompleteText "fingerprint  unavailable (identity incomplete)" "incomplete fingerprints are explicit"
        Assert-Contains $incompleteText "(identity unavailable)" "missing token rendered explicitly"

        $unavailable = ConvertTo-DevWSMonitorTopologyModel -GdiRows @() -PathRows @() -Attempts 3 -ErrorCode 87 -EdidByInstance @{}
        $unavailableText = (@(Get-DevWSMonitorLines -Topology $unavailable)) -join "`n"
        Assert-Contains $unavailableText "unavailable: " "acquisition failure rendered"
        Assert-Contains $unavailableText "QueryDisplayConfig" "acquisition failure names the API"

        $negativeModel = ConvertTo-DevWSMonitorTopologyModel -GdiRows @((New-MonitorTestGdiRow -GdiDeviceName '\\.\DISPLAY4' -X -1920 -Y -100 -W 1920 -H 1080)) -PathRows @(
            (New-MonitorTestPathRow -GdiDeviceName '\\.\DISPLAY4')
        ) -Attempts 1 -ErrorCode 0 -EdidByInstance @{}
        $negativeText = (@(Get-DevWSMonitorLines -Topology $negativeModel)) -join "`n"
        Assert-Contains $negativeText "rect    x=-1920 y=-100 w=1920 h=1080" "negative coordinates render"

        $deltaText = (@(Get-DevWSMonitorLines -Topology (New-MonitorTestFixtureModel -Reversed))) -join "`n"
        Assert-Contains $deltaText "Internal display" "reversed model renders the same fallback label"
    }

    Test-Case "ws monitors is config-free and strictly observational" {
        $brokenDir = Join-Path $TestRoot "monitor-configs"
        New-Item -ItemType Directory -Path $brokenDir -Force | Out-Null
        $brokenPath = Join-Path $brokenDir "broken.json"
        Set-Content -LiteralPath $brokenPath -Value "{ not json" -NoNewline

        $malformed = Invoke-WsCli -ConfigPath $brokenPath -Arguments @("monitors")
        Assert-Equal 0 $malformed.ExitCode "malformed config never blocks ws monitors"
        Assert-Contains $malformed.Output "MONITORS" "monitors output present"
        Assert-Contains $malformed.Output "TOPOLOGY" "topology output present"
        Assert-NotContains $malformed.Output "ws: " "no config error surfaced"

        $missing = Invoke-WsCli -ConfigPath (Join-Path $TestRoot "does-not-exist\workspace.json") -Arguments @("monitors")
        Assert-Equal 0 $missing.ExitCode "missing config never blocks ws monitors"
        Assert-Contains $missing.Output "MONITORS" "monitors output present without a config"

        $extra = Invoke-WsCli -ConfigPath $brokenPath -Arguments @("monitors", "extra")
        Assert-Equal 1 $extra.ExitCode "extra arguments are rejected"
        Assert-Contains $extra.Output "Usage: ws monitors" "usage error surfaced"
    }

    Test-Case "monitor diagnostics never mutate config, state, windows or hosts" {
        # In-body function DECLARATIONS create process-local shadows that are
        # torn down with the test body. (Set-Item function: on an existing
        # name replaces the script-scope original in place and would poison
        # every later group in the full suite.)
        function Get-DevWSContext { throw "monitor diagnostics must never call a side-effecting function." }
        function Save-DevWSConfig { throw "monitor diagnostics must never call a side-effecting function." }
        function Save-DevWSRuntimeState { throw "monitor diagnostics must never call a side-effecting function." }
        function Update-DevWSRuntimeTerminal { throw "monitor diagnostics must never call a side-effecting function." }
        function Move-DevWSWindowHwnd { throw "monitor diagnostics must never call a side-effecting function." }
        function Focus-DevWSWindowHwnd { throw "monitor diagnostics must never call a side-effecting function." }
        function Close-DevWSWindowHwnd { throw "monitor diagnostics must never call a side-effecting function." }
        function Set-DevWSAppOwnership { throw "monitor diagnostics must never call a side-effecting function." }
        function Set-DevWSProbedWindowOwnership { throw "monitor diagnostics must never call a side-effecting function." }
        function Request-DevWSElevatedBrokerRecovery { throw "monitor diagnostics must never call a side-effecting function." }
        function Start-DevWSWorkerRequest { throw "monitor diagnostics must never call a side-effecting function." }
        function Invoke-DevWSWorkerRequest { throw "monitor diagnostics must never call a side-effecting function." }

        $topology = Get-DevWSMonitorTopology
        Assert-True ($null -ne $topology) "topology produced under throwing side-effect fakes"

        $lines = @(Get-DevWSMonitorLines -Topology $topology)
        Assert-True ($lines.Count -gt 0) "monitor lines rendered under throwing side-effect fakes"
    }

    Test-Case "monitor native source is read-only and bounded" {
        $native = Get-SourceOf "src\native\devws-monitor.cs"

        Assert-Contains $native "DevWSMonitorNative" "monitor native type"
        Assert-Contains $native "MaxSnapshotAttempts" "bounded attempt constant"
        Assert-Contains $native "attempt <= MaxSnapshotAttempts" "bounded retry loop"
        Assert-Contains $native "ErrorInsufficientBuffer = 122" "documented retry error code"
        Assert-Contains $native "GetDisplayConfigBufferSizes" "buffer size query"
        Assert-Contains $native "QueryDisplayConfig" "topology query"
        Assert-Contains $native "DisplayConfigGetDeviceInfo" "device-info query"

        foreach ($forbidden in @("SetDisplayConfig", "ChangeDisplaySettings", "SetWindowPos", "MoveWindow", "SetForegroundWindow")) {
            Assert-NotContains $native $forbidden "no display/window mutation API: $forbidden"
        }

        $monitorLib = Get-SourceOf "src\lib\devws-monitor.ps1"
        Assert-NotContains $monitorLib "Add-Type" "monitor library never compiles"
        Assert-NotContains $monitorLib "Save-DevWSConfig" "monitor library never saves canonical config"
        Assert-NotContains $monitorLib "Move-DevWSWindowHwnd" "monitor library never moves windows"

        $requiredTypes = @(Get-DevWSNativeRequiredTypeNames)
