        Assert-True ($requiredTypes -contains "DevWSMonitorGdiRow") "GDI row type is required by the native runtime"
        Assert-True ($requiredTypes -contains "DevWSMonitorPathSnapshot") "path snapshot type is required by the native runtime"

        $sourceNames = @(Get-DevWSNativeSourcePaths -RepoRoot $RepoRoot | ForEach-Object { Split-Path -Leaf $_ })
        Assert-True ($sourceNames -contains "devws-monitor.cs") "installer compiles devws-monitor.cs"

        $typeMap = Get-DevWSNativeSourceTypeMap
        Assert-True ($typeMap.Contains("devws-monitor.cs")) "native source/type map carries devws-monitor.cs"
    }

