    Write-Host ""
    Start-TestGroup -Name 'layout-profiles' -Title 'Topology layout profiles (Pass 5C)'

    function New-LayoutProfileTestRect {
        param([int]$X, [int]$Y, [int]$W, [int]$H)
        return [pscustomobject]@{ x = $X; y = $Y; w = $W; h = $H }
    }

    function New-LayoutProfileTestTerminal {
        param([string]$Id, [bool]$Enabled = $true, [int]$X = 1)

        return [pscustomobject][ordered]@{
            id        = $Id
            type      = "terminal"
            enabled   = $Enabled
            windowId  = "DevWS-LP-$Id"
            path      = 'C:\x'
            elevated  = $true
            tabs      = @([pscustomobject][ordered]@{ command = $null; args = @() })
            activeTab = 0
            layout    = (New-LayoutProfileTestRect -X $X -Y 2 -W 3 -H 4)
        }
    }

    function New-LayoutProfileTestApp {
        param([string]$Id, [bool]$Enabled = $true)

        return [pscustomobject][ordered]@{
            id           = $Id
            type         = "app"
            enabled      = $Enabled
            match        = [pscustomobject][ordered]@{ kind = "exe"; value = "$Id.exe" }
            launch       = [pscustomobject][ordered]@{ kind = "exe"; value = "C:\$Id.exe"; args = @() }
            instanceMode = "dedicated"
            layout       = (New-LayoutProfileTestRect -X 1 -Y 2 -W 3 -H 4)
        }
    }

    function New-LayoutProfileTestSet {
        param([object[]]$Profiles = @(), [object[]]$Windows = @())

        $set = [pscustomobject][ordered]@{ id = "main" }

        if (@($Profiles).Count -gt 0) {
            $set | Add-Member -MemberType NoteProperty -Name "layoutProfiles" -Value @($Profiles)
        }

        $set | Add-Member -MemberType NoteProperty -Name "windows" -Value @($Windows)
        return $set
    }

    function New-LayoutProfileTestConfig {
        param($Set)

        return [pscustomobject][ordered]@{
            version    = 3
            defaultSet = "main"
            bindings   = @()
            sets       = @($Set)
        }
    }

    function New-LayoutProfileTestTopology {
        param(
            [string]$Signature,
            [bool]$IdentityComplete = $true,
            [bool]$CorrelationComplete = $true,
            [bool]$Ambiguous = $false,
            [bool]$Available = $true
        )

        $monitors = @()
        $fingerprint = $null

        if (-not [string]::IsNullOrWhiteSpace($Signature)) {
            foreach ($token in @($Signature -split ';')) {
                $parsed = ConvertFrom-DevWSLayoutMonitorToken -Token $token

                if ($null -ne $parsed) {
                    $monitors += [pscustomobject]@{
                        MonitorRect   = New-LayoutProfileTestRect -X $parsed.X -Y $parsed.Y -W $parsed.W -H $parsed.H
                        IdentityToken = $parsed.Identity
                    }
                }
            }
        }

        if ($Available -and -not [string]::IsNullOrWhiteSpace($Signature)) {
            $sha = [System.Security.Cryptography.SHA256]::Create()

            try { $fingerprint = ([System.BitConverter]::ToString($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($Signature)))).Replace('-', '') }
            finally { $sha.Dispose() }
        }

        return [pscustomobject]@{
            Available           = $Available
            Signature           = $Signature
            Fingerprint         = $fingerprint
            IdentityComplete    = $IdentityComplete
            CorrelationComplete = $CorrelationComplete
            IdentityAmbiguous   = $Ambiguous
            Monitors            = @($monitors)
        }
    }

    function Write-LayoutProfileFixtureConfig {
        param(
            [Parameter(Mandatory)][string]$Name,
            [switch]$WithProfiles,
            [switch]$WithDisabledItem
        )

        $dir = Join-Path $TestRoot ("layout-profile-configs\" + $Name)
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $path = Join-Path $dir "workspace.json"

        $profilesJson = '[]'
        $profilesLine = ""

        if ($WithProfiles) {
            $profilesJson = '[ { "id": "docked", "match": { "mode": "exact", "monitors": [ "path:AAA/1@0,0,1000x1000", "path:BBB/2@1000,0,1000x1000" ] }, "layouts": { "slot": { "x": 100, "y": 0, "w": 50, "h": 60 } } }, { "id": "laptop", "match": { "mode": "exact", "monitors": [ "path:AAA/1@0,0,1000x1000" ] }, "layouts": {} } ]'
            $profilesLine = '"layoutProfiles": ' + $profilesJson + ','
        }

        $disabledJson = ''
        $disabledComma = ''

        if ($WithDisabledItem) {
            $disabledComma = ','
            $disabledJson = '{ "id": "ghost", "type": "terminal", "enabled": false, "windowId": "DevWS-LP-ghost", "path": "C:\\x", "elevated": true, "tabs": [ { "command": null, "args": [] } ], "activeTab": 0, "layout": { "x": 9, "y": 9, "w": 9, "h": 9 } }'
        }

        $json = @"
{
  "version": 3,
  "defaultSet": "main",
  "bindings": [],
  "sets": [
    {
      "id": "main",
      $profilesLine
      "windows": [
        { "id": "slot",  "type": "terminal", "enabled": true, "windowId": "DevWS-LP-slot",  "path": "C:\\x", "elevated": true, "tabs": [ { "command": null, "args": [] } ], "activeTab": 0, "layout": { "x": 1, "y": 2, "w": 3, "h": 4 } },
        { "id": "term2", "type": "terminal", "enabled": true, "windowId": "DevWS-LP-term2", "path": "C:\\x", "elevated": true, "tabs": [ { "command": null, "args": [] } ], "activeTab": 0, "layout": { "x": 5, "y": 6, "w": 7, "h": 8 } }$disabledComma
        $disabledJson
      ]
    }
  ]
}
"@

        Set-Content -LiteralPath $path -Value $json -Encoding UTF8
        return $path
    }

    function New-LayoutProfileFakeCapture {
        param($Context, [string]$SetId, [object[]]$CaptureFiles = @())

        $target = Resolve-DevWSLifecycleTarget -Config $Context.Config -SetId $SetId
        $terminals = @($target.Set.windows | Where-Object { $_.type -eq 'terminal' -and $_.enabled })
        $apps = @($target.Set.windows | Where-Object { $_.type -eq 'app' -and $_.enabled })

        $terminalGeometry = @{}

        foreach ($terminal in $terminals) {
            switch ([string]$terminal.id) {
                'slot'  { $terminalGeometry[$terminal.id] = New-LayoutProfileTestRect -X 11 -Y 12 -W 13 -H 14 }
                'term2' { $terminalGeometry[$terminal.id] = New-LayoutProfileTestRect -X 21 -Y 22 -W 23 -H 24 }
                default { $terminalGeometry[$terminal.id] = New-LayoutProfileTestRect -X 31 -Y 32 -W 33 -H 34 }
            }
        }

        return [pscustomobject]@{
            Context          = $Context
            Target           = $target
            Terminals        = $terminals
            Apps             = $apps
            AppGeometry      = @{}
            TerminalGeometry = $terminalGeometry
            CaptureFiles     = @($CaptureFiles)
        }
    }

    function Invoke-LayoutProfileFixture {
        # Runs a body against a disposable config via DEVWS_CONFIG with the
        # environment restored afterwards.
        param(
            [Parameter(Mandatory)][string]$ConfigPath,
            [Parameter(Mandatory)][scriptblock]$Body
        )

        $saved = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $ConfigPath

        try {
            & $Body
        }
        finally {
            if ($null -ne $saved) { $env:DEVWS_CONFIG = $saved } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "layout profile schema accepts valid shapes" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        # Absent property.
        Assert-DevWSConfig -Config (New-LayoutProfileTestConfig -Set (New-LayoutProfileTestSet -Windows @((New-LayoutProfileTestTerminal -Id "t1")))) -Source "schema-absent"

        # Explicitly empty array.
        $emptySet = New-LayoutProfileTestSet -Windows @((New-LayoutProfileTestTerminal -Id "t1"))
        $emptySet | Add-Member -MemberType NoteProperty -Name "layoutProfiles" -Value @()
        Assert-DevWSConfig -Config (New-LayoutProfileTestConfig -Set $emptySet) -Source "schema-empty"

        # One profile, sparse empty layouts.
        $single = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        Assert-DevWSConfig -Config (New-LayoutProfileTestConfig -Set (New-LayoutProfileTestSet -Profiles @($single) -Windows @((New-LayoutProfileTestTerminal -Id "t1")))) -Source "schema-single"

        # Multiple profiles + sparse override with case-insensitive item key.
        $single.layouts = (ConvertTo-DevWSLayoutMapObject -Entries @([pscustomobject]@{ Key = "T1"; Value = (New-LayoutProfileTestRect -X 0 -Y 1 -W 2 -H 3) }))
        $laptop = New-DevWSLayoutProfile -Id "laptop" -MonitorTokens @('path:AAA/1@0,0,1000x1000')
        Assert-DevWSConfig -Config (New-LayoutProfileTestConfig -Set (New-LayoutProfileTestSet -Profiles @($single, $laptop) -Windows @((New-LayoutProfileTestTerminal -Id "t1")))) -Source "schema-multi"

        # Round-trip through a real file: JSON array shape survives (single
        # profile stays an array) and logical content is unchanged.
        $dir = Join-Path $TestRoot "layout-profile-roundtrip"
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $path = Join-Path $dir "workspace.json"
        $config = New-LayoutProfileTestConfig -Set (New-LayoutProfileTestSet -Profiles @($single) -Windows @((New-LayoutProfileTestTerminal -Id "t1")))
        Save-DevWSConfig -Config $config -Location (New-DevWSWritableConfigLocation -Path $path)

        $reloaded = Get-DevWSConfig -Location (New-DevWSWritableConfigLocation -Path $path)
        Assert-Equal 1 @($reloaded.sets[0].layoutProfiles).Count "single profile stays an array after round-trip"
        Assert-Equal ([string]$sigDocked).Split(';').Length (@($reloaded.sets[0].layoutProfiles[0].match.monitors)).Count "matcher tokens survive round-trip"
        Assert-Equal 0 $reloaded.sets[0].layoutProfiles[0].layouts.t1.x "sparse rect survives round-trip"
        Assert-Equal ($config | ConvertTo-Json -Depth 20 -Compress) ($reloaded | ConvertTo-Json -Depth 20 -Compress) "config round-trips logically unchanged"
    }

    Test-Case "layout profile schema rejects every invalid shape" {
        $validWindows = @((New-LayoutProfileTestTerminal -Id "t1"))
        $validProfile = { New-DevWSLayoutProfile -Id "docked" -MonitorTokens @('path:AAA/1@0,0,1000x1000') }

        $cases = @(
            @{ Name = "not-array";       Build = { $set = New-LayoutProfileTestSet -Windows $validWindows; $set | Add-Member -NotePropertyName "layoutProfiles" -NotePropertyValue ([pscustomobject]@{ id = "x" }); $set }; Needle = "must be an array" },
            @{ Name = "null profile";    Build = { New-LayoutProfileTestSet -Profiles @($null) -Windows $validWindows }; Needle = "must be a JSON object" },
            @{ Name = "missing id";      Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "missing a non-empty string 'id'" },
            @{ Name = "bad id";          Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a/b"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "unsupported characters" },
            @{ Name = "reserved id";     Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "FALLBACK"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "reserved" },
            @{ Name = "duplicate id";    Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{} }, [pscustomobject]@{ id = "A"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:B/2@5,0,1x1') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "duplicate profile id" },
            @{ Name = "missing match";   Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "'match' must be an object" },
            @{ Name = "bad mode";        Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "subset"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "match.mode must be 'exact'" },
            @{ Name = "missing monitors"; Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact" }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "match.monitors must be an array" },
            @{ Name = "empty monitors";  Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @() }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "at least one" },
            @{ Name = "malformed token"; Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @("garbage") }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "malformed" },
            @{ Name = "ordinal token";   Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('\\.\DISPLAY1@0,0,100x50') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "malformed" },
            @{ Name = "zero width";      Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,0x50') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "malformed" },
            @{ Name = "duplicate token"; Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,100x50', 'path:A/1@0,0,100x50') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "duplicates an earlier monitor token" },
            @{ Name = "duplicate matcher"; Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,100x50') }; layouts = [pscustomobject]@{} }, [pscustomobject]@{ id = "b"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,100x50') }; layouts = [pscustomobject]@{} }) -Windows $validWindows }; Needle = "duplicates the monitor matcher" },
            @{ Name = "layouts missing"; Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') } }) -Windows $validWindows }; Needle = "'layouts' must be an object" },
            @{ Name = "orphan key";      Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{ ghost = [pscustomobject]@{ x = 0; y = 0; w = 1; h = 1 } } }) -Windows $validWindows }; Needle = "does not exist in this set" },
            @{ Name = "zero rect width"; Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{ t1 = [pscustomobject]@{ x = 0; y = 0; w = 0; h = 1 } } }) -Windows $validWindows }; Needle = "greater than 0" },
            @{ Name = "typo field";      Build = { New-LayoutProfileTestSet -Profiles @([pscustomobject]@{ id = "a"; match = [pscustomobject]@{ mode = "exact"; monitors = @('path:A/1@0,0,1x1') }; layouts = [pscustomobject]@{}; extra = $true }) -Windows $validWindows }; Needle = "unexpected property" }
        )

        foreach ($case in $cases) {
            $set = & $case.Build
            $thrown = $null

            try { Assert-DevWSConfig -Config (New-LayoutProfileTestConfig -Set $set) -Source "schema-invalid" }
            catch { $thrown = $_.Exception.Message }

            Assert-True ($null -ne $thrown) "invalid case rejected: $($case.Name)"
            Assert-Contains ([string]$thrown) $case.Needle "invalid case names the problem: $($case.Name)"
        }
    }

    Test-Case "layout matcher tokens use one canonical parser" {
        $parsed = ConvertFrom-DevWSLayoutMonitorToken -Token 'path:AB@CD/1@-5,7,100x50'
        Assert-Equal 'path:AB@CD/1' $parsed.Identity "identity keeps interior punctuation (last @ wins)"
        Assert-Equal -5 $parsed.X "signed x"
        Assert-Equal 7 $parsed.Y "signed y"

        $parsed = ConvertFrom-DevWSLayoutMonitorToken -Token 'edid:MSI-4CD2-SN1@0,0,2560x1440'
        Assert-Equal 'edid:MSI-4CD2-SN1' $parsed.Identity "edid identity"

        foreach ($bad in @('', 'path:A/1', 'path:A/1@0,0,1', 'PATH:A/1@0,0,1x1', '\\.\DISPLAY1@0,0,1x1', 'edid:@0,0,1x1', 'path:A/1@0,0,0x1', 'path:A/1@0,0,1x0')) {
            Assert-Equal $null (ConvertFrom-DevWSLayoutMonitorToken -Token $bad) "malformed token refused: '$bad'"
        }

        Assert-Equal 'path:B/2@5,0,100x50;path:C/3@0,0,100x50' (Get-DevWSLayoutMatcherSignature -Tokens @('path:C/3@0,0,100x50', 'path:B/2@5,0,100x50')) "signature is ordinal sorted and ';' joined"

        $topology = New-LayoutProfileTestTopology -Signature 'path:B/2@5,0,100x50;path:C/3@0,0,100x50'
        Assert-Equal 'path:B/2@5,0,100x50' (@(Get-DevWSLayoutTopologyTokens -Topology $topology)[0]) "topology tokens come from the canonical signature"
    }

    Test-Case "pure profile selection follows the locked semantics" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'
        $sigLaptop = 'path:AAA/1@0,0,1000x1000'

        $noProfiles = Resolve-DevWSLayoutProfile -Set (New-LayoutProfileTestSet -Windows @()) -Topology $null
        Assert-Equal "fallback" $noProfiles.Status "no profiles -> fallback"
        Assert-Equal "no-profiles" $noProfiles.Reason "no profiles reason"

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @()

        $matched = Resolve-DevWSLayoutProfile -Set $set -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        Assert-Equal "matched" $matched.Status "exact match"
        Assert-Equal "docked" $matched.ProfileId "matched profile id"

        $miss = Resolve-DevWSLayoutProfile -Set $set -Topology (New-LayoutProfileTestTopology -Signature $sigLaptop)
        Assert-Equal "no-match" $miss.Reason "no match reason"

        $unavailable = Resolve-DevWSLayoutProfile -Set $set -Topology $null
        Assert-Equal "topology-unavailable" $unavailable.Reason "unavailable reason"

        foreach ($fixture in @(
            @{ Topology = (New-LayoutProfileTestTopology -Signature $sigDocked -IdentityComplete $false); Reason = "topology-incomplete" },
            @{ Topology = (New-LayoutProfileTestTopology -Signature $sigDocked -CorrelationComplete $false); Reason = "topology-incomplete" },
            @{ Topology = (New-LayoutProfileTestTopology -Signature $sigDocked -Ambiguous $true); Reason = "topology-ambiguous" }
        )) {
            Assert-Equal $fixture.Reason (Resolve-DevWSLayoutProfile -Set $set -Topology $fixture.Topology).Reason "unsafe topology reason: $($fixture.Reason)"
        }

        # Reordered config tokens still match; work-area/primary-only changes
        # keep the same signature and therefore match.
        $reversed = New-DevWSLayoutProfile -Id "rev" -MonitorTokens @(@($sigDocked -split ';')[1], @($sigDocked -split ';')[0])
        Assert-Equal "matched" (Resolve-DevWSLayoutProfile -Set (New-LayoutProfileTestSet -Profiles @($reversed) -Windows @()) -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)).Status "token order canonicalized"

        # Defensive duplicate runtime matchers: never first-wins.
        $dupeA = New-DevWSLayoutProfile -Id "a" -MonitorTokens @($sigDocked -split ';')
        $dupeB = New-DevWSLayoutProfile -Id "b" -MonitorTokens @($sigDocked -split ';')
        $ambiguous = Resolve-DevWSLayoutProfile -Set (New-LayoutProfileTestSet -Profiles @($dupeA, $dupeB) -Windows @()) -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        Assert-Equal "ambiguous" $ambiguous.Status "duplicate matchers -> ambiguous state"
        Assert-Equal "ambiguous-matchers" $ambiguous.Reason "ambiguous reason"
    }

    Test-Case "topology eligibility and stability gates are exact" {
        $sig = 'path:AAA/1@0,0,1000x1000'

        Assert-True (Test-DevWSLayoutTopologyMatchable -Topology (New-LayoutProfileTestTopology -Signature $sig)).Eligible "complete topology is eligible"
        Assert-Equal "topology-unavailable" (Test-DevWSLayoutTopologyMatchable -Topology $null).Reason "null topology unavailable"
        Assert-Equal "topology-unavailable" (Test-DevWSLayoutTopologyMatchable -Topology (New-LayoutProfileTestTopology -Signature $sig -Available $false)).Reason "unavailable flag"
        Assert-Equal "topology-incomplete" (Test-DevWSLayoutTopologyMatchable -Topology (New-LayoutProfileTestTopology -Signature "")).Reason "empty signature is incomplete"
        Assert-Equal "topology-ambiguous" (Test-DevWSLayoutTopologyMatchable -Topology (New-LayoutProfileTestTopology -Signature $sig -Ambiguous $true)).Reason "ambiguous flag"

        $stable = Test-DevWSLayoutTopologyStable -First (New-LayoutProfileTestTopology -Signature $sig) -Second (New-LayoutProfileTestTopology -Signature $sig)
        Assert-Equal $true $stable.Stable "identical snapshots stable"

        $changed = Test-DevWSLayoutTopologyStable -First (New-LayoutProfileTestTopology -Signature $sig) -Second (New-LayoutProfileTestTopology -Signature 'path:CCC/3@0,0,100x100')
        Assert-Equal "topology-signature-changed" $changed.Reason "signature change unstable"

        $unsafe = Test-DevWSLayoutTopologyStable -First (New-LayoutProfileTestTopology -Signature $sig) -Second (New-LayoutProfileTestTopology -Signature $sig -IdentityComplete $false)
        Assert-Equal "topology-not-matchable" $unsafe.Reason "unsafe second snapshot unstable"
    }

    Test-Case "effective layout resolution is sparse-safe and non-mutating" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "alpha" -Rect (New-LayoutProfileTestRect -X 10 -Y 10 -W 500 -H 500)

        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @(
            (New-LayoutProfileTestTerminal -Id "alpha" -X 1),
            (New-LayoutProfileTestTerminal -Id "beta" -X 2)
        )

        $topology = New-LayoutProfileTestTopology -Signature $sigDocked
        $before = $set | ConvertTo-Json -Depth 20 -Compress
        $model = Get-DevWSEffectiveLayout -SetId "main" -Set $set -Topology $topology
        $after = $set | ConvertTo-Json -Depth 20 -Compress

        Assert-Equal $before $after "resolution never mutates config objects"
        Assert-Equal "matched" $model.Status "matched model"

        $alpha = @($model.Items | Where-Object { $_.ItemId -eq "alpha" })[0]
        $beta  = @($model.Items | Where-Object { $_.ItemId -eq "beta" })[0]

        Assert-Equal "profile" $alpha.Source "override item uses the profile"
        Assert-Equal 10 $alpha.Rect.x "override rect"
        Assert-Equal "fallback" $beta.Source "sparse item falls back"
        Assert-Equal 2 $beta.Rect.x "fallback rect"
        Assert-True ($null -ne $alpha.Reachable) "reachability computed with monitor geometry"

        $noTopology = Get-DevWSEffectiveLayout -SetId "main" -Set $set -Topology $null
        Assert-True ($null -eq @($noTopology.Items | Where-Object { $_.ItemId -eq "beta" })[0].Reachable) "reachability unavailable without topology"
    }

    Test-Case "write scope routing refuses unsafe implicit writes" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'
        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @()

        $legacy = Resolve-DevWSLayoutWriteScope -Set (New-LayoutProfileTestSet -Windows @()) -Topology $null
        Assert-Equal $true $legacy.Ok "profile-free implicit write needs no topology"
        Assert-Equal "fallback" $legacy.Source "profile-free scope is fallback"

        $matched = Resolve-DevWSLayoutWriteScope -Set $set -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        Assert-Equal "profile" $matched.Source "matched scope is the profile"

        $miss = Resolve-DevWSLayoutWriteScope -Set $set -Topology (New-LayoutProfileTestTopology -Signature 'path:AAA/1@0,0,1000x1000')
        Assert-Equal "fallback" $miss.Source "no-match scope is fallback"

        foreach ($unsafe in @(
            $null,
            (New-LayoutProfileTestTopology -Signature $sigDocked -IdentityComplete $false),
            (New-LayoutProfileTestTopology -Signature $sigDocked -CorrelationComplete $false),
            (New-LayoutProfileTestTopology -Signature $sigDocked -Ambiguous $true)
        )) {
            $scope = Resolve-DevWSLayoutWriteScope -Set $set -Topology $unsafe
            Assert-Equal $false $scope.Ok "unsafe topology refuses implicit write"
            Assert-Contains ([string]$scope.Refusal) "Nothing was changed" "refusal is explicit"
        }
    }

    Test-Case "profile save target resolution enforces create and update safety" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'
        $sigOther  = 'path:CCC/3@0,0,100x100'
        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @()

        $update = Resolve-DevWSLayoutProfileSaveTarget -Set $set -ProfileId "docked" -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        Assert-True ($update.Ok -and -not $update.Create -and $update.Profile.id -eq "docked") "existing matching profile updates"

        $wrong = Resolve-DevWSLayoutProfileSaveTarget -Set $set -ProfileId "docked" -Topology (New-LayoutProfileTestTopology -Signature $sigOther)
        Assert-True (-not $wrong.Ok) "wrong matcher refused"
        Assert-Contains ([string]$wrong.Refusal) "ws layout-profile match" "re-key hint"

        $occupied = Resolve-DevWSLayoutProfileSaveTarget -Set $set -ProfileId "newone" -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        Assert-True (-not $occupied.Ok) "creation refused when another profile owns the matcher"
        Assert-Contains ([string]$occupied.Refusal) "already matched by profile 'docked'" "occupied-matcher message"

        $create = Resolve-DevWSLayoutProfileSaveTarget -Set $set -ProfileId "newone" -Topology (New-LayoutProfileTestTopology -Signature $sigOther)
        Assert-True ($create.Ok -and $create.Create -and $null -eq $create.Profile) "creation allowed for a fresh topology"

        Assert-True (-not (Resolve-DevWSLayoutProfileSaveTarget -Set $set -ProfileId "fallback" -Topology (New-LayoutProfileTestTopology -Signature $sigOther)).Ok) "reserved id refused"
        Assert-True (-not (Resolve-DevWSLayoutProfileSaveTarget -Set $set -ProfileId "newone" -Topology $null).Ok) "explicit profile save requires topology"
    }

    Test-Case "profile map helpers preserve casing, order, and depth" {
        $profile = New-DevWSLayoutProfile -Id "m" -MonitorTokens @('path:AAA/1@0,0,1000x1000')
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "alpha" -Rect (New-LayoutProfileTestRect -X 1 -Y 1 -W 1 -H 1)
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "beta" -Rect (New-LayoutProfileTestRect -X 2 -Y 2 -W 2 -H 2)

        $entry = Get-DevWSLayoutProfileEntry -Profile $profile -ItemId "ALPHA"
        Assert-Equal 1 $entry.x "case-insensitive lookup"

        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "alpha" -Rect (New-LayoutProfileTestRect -X 9 -Y 9 -W 9 -H 9)
        $keys = @($profile.layouts.PSObject.Properties.Name)
        Assert-Equal 2 $keys.Count "replace does not add a duplicate"
        Assert-True ($keys[0] -ceq "alpha") "replace preserves position"
        Assert-Equal 9 $profile.layouts.alpha.x "replace updates the rect"

        Rename-DevWSLayoutProfileEntry -Profile $profile -OldId "ALPHA" -NewId "ALPHA2"
        $keys = @($profile.layouts.PSObject.Properties.Name)
        Assert-True ($keys[0] -ceq "ALPHA2") "re-key updates casing in place"
        Assert-Equal 9 $profile.layouts.ALPHA2.x "re-key preserves the rect"

        Remove-DevWSLayoutProfileEntry -Profile $profile -ItemId "alpha2"
        $keys = @($profile.layouts.PSObject.Properties.Name)
        Assert-Equal 1 $keys.Count "removal keeps other entries"
        Assert-True ($keys[0] -ceq "beta") "removal keeps order"

        $mapCopy = Copy-DevWSLayoutProfileMap -Profile $profile
        $mapCopy.beta.x = 42
        Assert-Equal 2 $profile.layouts.beta.x "map copy is deep"

        $profilesCopy = Copy-DevWSLayoutProfiles -Profiles @($profile)
        $profilesCopy[0].layouts.beta.x = 77
        Assert-Equal 2 $profile.layouts.beta.x "profile-array copy is deep"
        Assert-Equal "m" $profilesCopy[0].id "profile id copied"
    }

    Test-Case "profile CRUD manages the optional property" {
        $set = New-LayoutProfileTestSet -Windows @()

        $first = New-DevWSLayoutProfile -Id "one" -MonitorTokens @('path:AAA/1@0,0,1000x1000')
        Add-DevWSLayoutProfile -Set $set -Profile $first
        Assert-True (Test-DevWSSetHasLayoutProfiles -Set $set) "first profile creates the property"
        Assert-Equal 1 @(Get-DevWSLayoutProfiles -Set $set).Count "one profile stored"

        $second = New-DevWSLayoutProfile -Id "two" -MonitorTokens @('path:BBB/2@0,0,100x100')
        Add-DevWSLayoutProfile -Set $set -Profile $second
        Assert-Equal 2 @(Get-DevWSLayoutProfiles -Set $set).Count "second profile appended"

        Set-DevWSLayoutProfileMatcher -Profile $second -MonitorTokens @('path:CCC/3@0,0,1x1', 'path:DDD/4@1,0,1x1')
        Assert-Equal 'path:CCC/3@0,0,1x1;path:DDD/4@1,0,1x1' ($second.match.monitors -join ';') "matcher re-keyed and sorted"

        Remove-DevWSLayoutProfile -Set $set -ProfileId "ONE"
        Assert-Equal 1 @(Get-DevWSLayoutProfiles -Set $set).Count "case-insensitive removal"

        Remove-DevWSLayoutProfile -Set $set -ProfileId "two"
        Assert-True (-not (Test-DevWSProperty -Object $set -Name "layoutProfiles")) "final removal drops the property"

        # Empty-array property: adding reuses it without duplicates.
        $empty = New-LayoutProfileTestSet -Windows @()
        $empty | Add-Member -MemberType NoteProperty -Name "layoutProfiles" -Value @()
        Add-DevWSLayoutProfile -Set $empty -Profile (New-DevWSLayoutProfile -Id "x" -MonitorTokens @('path:AAA/1@0,0,1x1'))
        Assert-Equal 1 @(Get-DevWSLayoutProfiles -Set $empty).Count "empty array reused"
    }

    Test-Case "profile reference resolver is scoped and strict" {
        $config = [pscustomobject]@{
            version    = 3
            defaultSet = "main"
            bindings   = @()
            sets       = @(
                [pscustomobject]@{ id = "main"; windows = @() },
                [pscustomobject]@{ id = "secondary"; windows = @() }
            )
        }

        $unscoped = Resolve-DevWSLayoutProfileReference -Config $config -Reference "docked"
        Assert-Equal "main" $unscoped.SetId "unscoped targets defaultSet"
        Assert-Equal "docked" $unscoped.ProfileId "unscoped profile id"
        Assert-Equal $false $unscoped.Scoped "unscoped flag"

        $scoped = Resolve-DevWSLayoutProfileReference -Config $config -Reference "secondary/laptop"
        Assert-Equal "secondary" $scoped.SetId "scoped set"
        Assert-Equal "laptop" $scoped.ProfileId "scoped profile"
        Assert-Equal $true $scoped.Scoped "scoped flag"

        foreach ($bad in @("", "/x", "set/", "a/b/c", "main/fallback", "main/bad id", "nope/docked")) {
            $thrown = $false
            try { $null = Resolve-DevWSLayoutProfileReference -Config $config -Reference $bad } catch { $thrown = $true }
            Assert-True $thrown "reference '$bad' rejected"
        }
    }

