    Test-Case "cross-set clones copy by matcher equivalence only" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'
        $sigLaptop = 'path:AAA/1@0,0,1000x1000'

        $sourceProfile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        Set-DevWSLayoutProfileRect -Profile $sourceProfile -ItemId "term" -Rect (New-LayoutProfileTestRect -X 4 -Y 4 -W 4 -H 4)
        $sourceSet = New-LayoutProfileTestSet -Profiles @($sourceProfile) -Windows @((New-LayoutProfileTestTerminal -Id "term"))

        # Target: same name but different matcher, and equivalent matcher
        # under a different name.
        $byNameWrong = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigLaptop -split ';')
        $byMatcherRight = New-DevWSLayoutProfile -Id "other-name" -MonitorTokens @($sigDocked -split ';')
        $targetSet = New-LayoutProfileTestSet -Profiles @($byNameWrong, $byMatcherRight) -Windows @()
        $config = [pscustomobject]@{
            version    = 3
            defaultSet = "main"
            bindings   = @()
            sets       = @($sourceSet, $targetSet)
        }
        $targetSet.id = "secondary"

        $clone = Clone-DevWSTerminal -Config $config -SourceId "term" -NewId "term-clone" -Set $targetSet -SourceSet $sourceSet

        Assert-Equal $null (Get-DevWSLayoutProfileEntry -Profile $byNameWrong -ItemId "term-clone") "same name with a different matcher is NOT copied"
        Assert-Equal 4 (Get-DevWSLayoutProfileEntry -Profile $byMatcherRight -ItemId "term-clone").x "equivalent matcher copies geometry"

        # No equivalent target matcher: target profiles stay sparse and no
        # profile is created.
        $thirdSet = New-LayoutProfileTestSet -Profiles @($byNameWrong) -Windows @()
        $thirdSet.id = "third"
        $config.sets = @($sourceSet, $targetSet, $thirdSet)
        $null = Clone-DevWSTerminal -Config $config -SourceId "term" -NewId "term-clone-2" -Set $thirdSet -SourceSet $sourceSet
        Assert-Equal $null (Get-DevWSLayoutProfileEntry -Profile $byNameWrong -ItemId "term-clone-2") "no equivalent matcher leaves target sparse"
        Assert-Equal 1 @(Get-DevWSLayoutProfiles -Set $thirdSet).Count "no target profile is created"
    }

