    Test-Case "ws save composes geometry and cwd with one commit" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        $configPath = Write-LayoutProfileFixtureConfig -Name "save-workspace" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            $state = @{ Saves = 0; Config = $null; Order = [System.Collections.Generic.List[string]]::new() }

            function Get-DevWSLiveLayoutCapture { param([string]$SetId, $Context) $state.Order.Add("capture") | Out-Null; if ($null -eq $Context) { $Context = Get-DevWSContext }; New-LayoutProfileFakeCapture -Context $Context -SetId $SetId }
            function Get-DevWSTerminalSaveDecisions {
                param([string]$SetId, [object[]]$Terminals = @())
                $state.Order.Add("cwd-decisions") | Out-Null
                $decisions = [ordered]@{}

                foreach ($terminal in $Terminals) {
                    $perTab = [System.Collections.Generic.List[object]]::new()
                    $tabCount = @($terminal.tabs).Count

                    for ($tabIndex = 0; $tabIndex -lt $tabCount; $tabIndex++) {
                        if ([string]$terminal.id -eq "slot" -and $tabIndex -eq 0) {
                            $perTab.Add([pscustomobject]@{ terminalId = $terminal.id; tabIndex = $tabIndex; hadOverride = $false; oldExplicitPath = $null; oldEffective = "C:\x"; status = "available"; reason = "ok"; newCwd = "C:\new"; sessionId = "S1"; windowId = "W1" }) | Out-Null
                        }
                        else {
                            $perTab.Add([pscustomobject]@{ terminalId = $terminal.id; tabIndex = $tabIndex; hadOverride = $false; oldExplicitPath = $null; oldEffective = "C:\x"; status = "unavailable"; reason = "expected-missing"; newCwd = $null; sessionId = $null; windowId = $null }) | Out-Null
                        }
                    }

                    $decisions[$terminal.id] = $perTab.ToArray()
                }

                return $decisions
            }
            function Confirm-DevWSTerminalSaveDecisions { param([string]$SetId, $Decisions) $state.Order.Add("cwd-gate") | Out-Null }
            function Get-DevWSMonitorTopology { $state.Order.Add("topology") | Out-Null; New-LayoutProfileTestTopology -Signature $sigDocked }
            function Save-DevWSConfig { param($Config, $Location) $state.Order.Add("save") | Out-Null; $state.Saves++; $state.Config = $Config }

            Save-DevWSWorkspace -SetId "main" | Out-Null

            Assert-Equal 1 $state.Saves "exactly one canonical save"
            Assert-Equal "topology,capture,cwd-decisions,topology,cwd-gate,save" ($state.Order -join ",") "gate order: topology(A) -> capture -> cwd decisions -> topology(B) -> cwd gate -> save"

            $profile = @($state.Config.sets[0].layoutProfiles | Where-Object { $_.id -eq "docked" })[0]
            Assert-Equal 11 $profile.layouts.slot.x "geometry routed to the matched profile"

            $slot  = @($state.Config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
            $term2 = @($state.Config.sets[0].windows | Where-Object { $_.id -eq "term2" })[0]
            Assert-Equal "C:\new" $slot.path "cwd applied globally to terminal.path"
            Assert-Equal "C:\x" $term2.path "unavailable cwd keeps the existing path"
        }
    }

