                    $tabCount = @($terminal.tabs).Count

                    for ($tabIndex = 0; $tabIndex -lt $tabCount; $tabIndex++) {
                        $perTab.Add([pscustomobject]@{ terminalId = $terminal.id; tabIndex = $tabIndex; hadOverride = $false; oldExplicitPath = $null; oldEffective = "C:\x"; status = "available"; reason = "ok"; newCwd = "C:\new"; sessionId = "S1"; windowId = "W1" }) | Out-Null
                    }

                    $decisions[$terminal.id] = $perTab.ToArray()
                }

                return $decisions
            }
            function Confirm-DevWSTerminalSaveDecisions {
                param([string]$SetId, $Decisions)
                # Simulate a reset advancing the generation between resolution
                # and commit: the gate downgrades every decision.
                foreach ($key in @($Decisions.Keys)) {
                    foreach ($decision in @($Decisions[$key])) {
                        $decision.status = "unavailable"
                        $decision.reason = "session-mismatch"
                        $decision.newCwd = $null
                    }
                }
            }
            function Get-DevWSMonitorTopology { New-LayoutProfileTestTopology -Signature $sigDocked }
            function Save-DevWSConfig { param($Config, $Location) $state.Saves++; $state.Config = $Config }

            Save-DevWSWorkspace -SetId "main" | Out-Null

            Assert-Equal 1 $state.Saves "geometry still saves once"
            $slot = @($state.Config.sets[0].windows | Where-Object { $_.id -eq "slot" })[0]
            Assert-Equal "C:\x" $slot.path "stale cwd never persisted"
            Assert-Equal 11 (@($state.Config.sets[0].layoutProfiles | Where-Object { $_.id -eq "docked" })[0]).layouts.slot.x "geometry still routed"
        }
    }

