    Test-Case "set-geometry implicit routing follows the current topology" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        # Matched topology: implicit edits go to the profile.
        $configPath = Write-LayoutProfileFixtureConfig -Name "set-geometry-matched" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { New-LayoutProfileTestTopology -Signature $sigDocked }
            Invoke-DevWSSetGeometry -Reference "term2" -Arguments @("--x", "70", "--y", "0", "--width", "10", "--height", "10") | Out-Null

            $config = Get-DevWSConfig -Location (Resolve-DevWSConfigLocation -StartPath (Get-Location).Path)
            Assert-Equal 70 (@($config.sets[0].layoutProfiles | Where-Object { $_.id -eq "docked" })[0]).layouts.term2.x "implicit matched write edits the profile"
            Assert-Equal 5 $config.sets[0].windows[1].layout.x "fallback untouched"
        }

        # No match: implicit edits go to the fallback.
        $configPath = Write-LayoutProfileFixtureConfig -Name "set-geometry-nomatch" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { New-LayoutProfileTestTopology -Signature 'path:ZZZ/9@0,0,1x1' }
            Invoke-DevWSSetGeometry -Reference "term2" -Arguments @("--x", "80", "--y", "0", "--width", "10", "--height", "10") | Out-Null

            $config = Get-DevWSConfig -Location (Resolve-DevWSConfigLocation -StartPath (Get-Location).Path)
            Assert-Equal 80 $config.sets[0].windows[1].layout.x "implicit no-match write edits the fallback"
            Assert-True ($null -eq (Get-DevWSLayoutProfileEntry -Profile (@($config.sets[0].layoutProfiles | Where-Object { $_.id -eq "docked" })[0]) -ItemId "term2")) "profile untouched on no-match"
        }

        # Unsafe topology: implicit write refused.
        $configPath = Write-LayoutProfileFixtureConfig -Name "set-geometry-unsafe" -WithProfiles
        $before = Get-FileBase64 -Path $configPath
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { $null }
            $thrown = $false
            try { Invoke-DevWSSetGeometry -Reference "slot" -Arguments @("--x", "1", "--y", "0", "--width", "1", "--height", "1") | Out-Null } catch { $thrown = $true }
            Assert-True $thrown "implicit unsafe write refused"
        }
        Assert-Equal $before (Get-FileBase64 -Path $configPath) "refused implicit write leaves canonical bytes unchanged"

        # Profile-free set: legacy behavior with no topology dependency.
        $configPath = Write-LayoutProfileFixtureConfig -Name "set-geometry-legacy"
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { throw "profile-free implicit writes must not sample topology" }
            Invoke-DevWSSetGeometry -Reference "slot" -Arguments @("--x", "90", "--y", "0", "--width", "10", "--height", "10") | Out-Null
            $config = Get-DevWSConfig -Location (Resolve-DevWSConfigLocation -StartPath (Get-Location).Path)
            Assert-Equal 90 $config.sets[0].windows[0].layout.x "legacy fallback write"
        }
    }

    Test-Case "layout-profile list model and renderer are coherent" {
