    Test-Case "show-layout formatter renders effective policy as lifecycle truth" {
        $sigDocked = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sigDocked -split ';')
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "alpha" -Rect (New-LayoutProfileTestRect -X 10 -Y 10 -W 500 -H 500)

        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @(
            (New-LayoutProfileTestTerminal -Id "alpha" -X 1),
            (New-LayoutProfileTestTerminal -Id "beta" -X 2)
        )

        $model = Get-DevWSEffectiveLayout -SetId "main" -Set $set -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        $text = (@(Get-DevWSEffectiveLayoutLines -Model $model)) -join "`n"

        Assert-Contains $text "profile 'docked'" "selected profile rendered"
        Assert-Contains $text "topology" "topology line"
        Assert-Contains $text "profiles    docked" "profile ids summary"
        Assert-Contains $text "[fallback]" "sparse per-item fallback marker"
        Assert-Contains $text "apply exactly this effective layout" "lifecycle truth note"

        # Unreachable rectangles are marked when reachability is false.
        $farProfile = New-DevWSLayoutProfile -Id "far" -MonitorTokens @($sigDocked -split ';')
        Set-DevWSLayoutProfileRect -Profile $farProfile -ItemId "alpha" -Rect (New-LayoutProfileTestRect -X 5000 -Y 5000 -W 100 -H 100)
        $farSet = New-LayoutProfileTestSet -Profiles @($farProfile) -Windows @((New-LayoutProfileTestTerminal -Id "alpha"))
        $farModel = Get-DevWSEffectiveLayout -SetId "main" -Set $farSet -Topology (New-LayoutProfileTestTopology -Signature $sigDocked)
        $farText = (@(Get-DevWSEffectiveLayoutLines -Model $farModel)) -join "`n"
        Assert-Contains $farText "[unreachable]" "unreachable marker"

        # Incomplete topology shows the fallback preview wording.
        $incompleteModel = Get-DevWSEffectiveLayout -SetId "main" -Set $set -Topology (New-LayoutProfileTestTopology -Signature $sigDocked -IdentityComplete $false)
        $incompleteText = (@(Get-DevWSEffectiveLayoutLines -Model $incompleteModel)) -join "`n"
        Assert-Contains $incompleteText "not fully identified" "incomplete topology wording"

        # Profile-free: no-profiles reason.
        $legacyModel = Get-DevWSEffectiveLayout -SetId "main" -Set (New-LayoutProfileTestSet -Windows @((New-LayoutProfileTestTerminal -Id "alpha"))) -Topology $null
        $legacyText = (@(Get-DevWSEffectiveLayoutLines -Model $legacyModel)) -join "`n"
        Assert-Contains $legacyText "no profiles configured" "no-profiles wording"
        Assert-NotContains $legacyText ([string][char]27) "no ANSI required"
    }

    Test-Case "layout-profile commands mutate through a disposable config" {
        $sigFixture = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        # match: re-key success, layout preservation, one canonical save.
        $configPath = Write-LayoutProfileFixtureConfig -Name "commands-match" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { New-LayoutProfileTestTopology -Signature $sigFixture }

            Invoke-DevWSLayoutProfileCommand -Subcommand "match" -Arguments @("docked") | Out-Null

            $config = Get-DevWSConfig -Location (Resolve-DevWSConfigLocation -StartPath (Get-Location).Path)
            $profile = @($config.sets[0].layoutProfiles | Where-Object { $_.id -eq "docked" })[0]
            Assert-Equal $sigFixture ($profile.match.monitors -join ';') "matcher re-keyed to the fixture topology"
            Assert-Equal 100 $profile.layouts.slot.x "layouts preserved by re-key"
        }

        # match: duplicate conflict refused.
        $configPath = Write-LayoutProfileFixtureConfig -Name "commands-match-conflict" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { New-LayoutProfileTestTopology -Signature 'path:AAA/1@0,0,1000x1000' }

            $thrown = $null
            try { Invoke-DevWSLayoutProfileCommand -Subcommand "match" -Arguments @("docked") | Out-Null } catch { $thrown = $_.Exception.Message }
            Assert-Contains ([string]$thrown) "already matched by profile 'laptop'" "duplicate matcher conflict refused"
        }

        # match: unavailable topology refused.
        $configPath = Write-LayoutProfileFixtureConfig -Name "commands-match-unavailable" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { $null }

            $thrown = $null
            try { Invoke-DevWSLayoutProfileCommand -Subcommand "match" -Arguments @("docked") | Out-Null } catch { $thrown = $_.Exception.Message }
            Assert-Contains ([string]$thrown) "not safely matchable" "unavailable topology refused"
        }

        # remove: confirmation cancel leaves config unchanged.
        $configPath = Write-LayoutProfileFixtureConfig -Name "commands-remove-cancel" -WithProfiles
        $before = Get-FileBase64 -Path $configPath
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Read-Host { param($Prompt) return "n" }
            Invoke-DevWSLayoutProfileCommand -Subcommand "remove" -Arguments @("docked") | Out-Null
        }
        Assert-Equal $before (Get-FileBase64 -Path $configPath) "cancelled removal leaves bytes unchanged"

        # remove: -Force removes one profile; final removal drops the property.
        $configPath = Write-LayoutProfileFixtureConfig -Name "commands-remove-force" -WithProfiles
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            Invoke-DevWSLayoutProfileCommand -Subcommand "remove" -Arguments @("docked") -SkipConfirmation | Out-Null

            $config = Get-DevWSConfig -Location (Resolve-DevWSConfigLocation -StartPath (Get-Location).Path)
            Assert-Equal 1 @($config.sets[0].layoutProfiles).Count "one profile removed"
            Assert-Equal "laptop" (@($config.sets[0].layoutProfiles)[0]).id "other profile remains"

            Invoke-DevWSLayoutProfileCommand -Subcommand "remove" -Arguments @("laptop") -SkipConfirmation | Out-Null

            $config = Get-DevWSConfig -Location (Resolve-DevWSConfigLocation -StartPath (Get-Location).Path)
            Assert-True (-not (Test-DevWSProperty -Object $config.sets[0] -Name "layoutProfiles")) "final removal drops the property"
            Assert-Equal 1 $config.sets[0].windows[0].layout.x "fallback layout untouched by removal"
        }

        # list: read-only, renders without throwing.
        $configPath = Write-LayoutProfileFixtureConfig -Name "commands-list" -WithProfiles
        $before = Get-FileBase64 -Path $configPath
        Invoke-LayoutProfileFixture -ConfigPath $configPath -Body {
            function Get-DevWSMonitorTopology { New-LayoutProfileTestTopology -Signature $sigFixture }
            $output = (& { Invoke-DevWSLayoutProfileCommand -Subcommand "list" -Arguments @() } 6>&1 | Out-String)
            Assert-Contains $output "LAYOUT PROFILES: main" "list renders the heading"
        }
        Assert-Equal $before (Get-FileBase64 -Path $configPath) "list never writes"
    }

