    Test-Case "help surface documents the profile policy and lifecycle usage" {
        $commands = @(Get-DevWSHelpCommandInfo)
        Assert-Equal 41 $commands.Count "command catalog grows to 41"
        Assert-Equal 5 @(Get-DevWSHelpTopicInfo).Count "topic count stays five"

        $entry = @($commands | Where-Object { $_.Name -eq "layout-profile" })[0]
        Assert-Equal "ws layout-profile <list|remove|match> ..." $entry.Usage "layout-profile usage"
        Assert-Equal "Layout" $entry.Section "layout-profile is a layout command"

        $layoutTopic = @(Get-DevWSHelpTopicInfo | Where-Object { $_.Name -eq "layout" })[0]
        Assert-True (@($layoutTopic.Commands) -contains "layout-profile") "layout topic lists layout-profile"

        $saveLayout = @($commands | Where-Object { $_.Name -eq "save-layout" })[0]
        Assert-Contains ([string]($saveLayout.Details -join " ")) "--profile" "save-layout help documents --profile"

        $save = @($commands | Where-Object { $_.Name -eq "save" })[0]
        Assert-Contains ([string]($save.Details -join " ")) "global" "save help documents global cwd"

        $setGeometry = @($commands | Where-Object { $_.Name -eq "set-geometry" })[0]
        Assert-Contains ([string]$setGeometry.Usage) "--layout" "set-geometry usage documents --layout"

        $showLayout = @($commands | Where-Object { $_.Name -eq "show-layout" })[0]
        Assert-Contains ([string]($showLayout.Details -join " ")) "apply exactly these effective rectangles" "show-layout help states lifecycle usage"

        $resetLayout = @($commands | Where-Object { $_.Name -eq "reset-layout" })[0]
        Assert-Contains ([string]($resetLayout.Details -join " ")) "never created, modified or deleted" "reset-layout help states profile preservation"

        $target = New-WritableConfigCopy "layout-profile-help"

        $help = Invoke-WsCli -ConfigPath $target -Arguments @("help", "layout-profile")
        Assert-Equal 0 $help.ExitCode "help layout-profile exit"
        Assert-Contains $help.Output "ws layout-profile list" "help lists subcommands"
        Assert-Contains $help.Output "applied automatically by 'ws launch'" "help states lifecycle usage"

        $all = Invoke-WsCli -ConfigPath $target -Arguments @("help", "all")
        Assert-Contains $all.Output "ws layout-profile" "help all advertises layout-profile"
    }

    Write-Host ""
    Start-TestGroup -Name 'lifecycle-layouts' -Title 'Lifecycle profile placement (Pass 5D)'

    $script:lcTopologyCalls = 0

    function Write-LifecycleLayoutFixtureConfig {
        # Disposable one-set config for lifecycle placement tests: a terminal
        # 'slot' (fallback layout optionally far off-screen), an optional
        # 'firefox' app, an optional second terminal and an optional disabled
        # ghost; -OverrideEntries adds exact matched-profile rectangles.
        param(
            [Parameter(Mandatory)][string]$Name,
            [object[]]$OverrideEntries = @(),
            [switch]$WithProfiles,
            [switch]$FarSlotFallback,
            [switch]$NoApp,
            [switch]$SecondTerminal,
            [switch]$DisabledGhost,
            [switch]$DisabledSlot
        )

        $dir = Join-Path $TestRoot ("lifecycle-layout-configs\" + $Name)
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        $path = Join-Path $dir "workspace.json"

        $slotLayout = if ($FarSlotFallback) { [ordered]@{ x = 9000; y = 9000; w = 100; h = 100 } } else { [ordered]@{ x = 1; y = 2; w = 300; h = 200 } }
        $windows = [System.Collections.Generic.List[object]]::new()

        $windows.Add([ordered]@{
            id        = "slot"
            type      = "terminal"
            enabled   = (-not $DisabledSlot)
            windowId  = "DevWS-LC-slot"
            path      = $TestRoot
            elevated  = $true
            tabs      = @([ordered]@{ command = $null; args = @() })
            activeTab = 0
            layout    = $slotLayout
        }) | Out-Null

        if ($SecondTerminal) {
            $windows.Add([ordered]@{
                id        = "term2"
                type      = "terminal"
                enabled   = $true
                windowId  = "DevWS-LC-term2"
                path      = $TestRoot
                elevated  = $true
                tabs      = @([ordered]@{ command = $null; args = @() })
                activeTab = 0
                layout    = [ordered]@{ x = 5; y = 6; w = 300; h = 200 }
            }) | Out-Null
        }

        if (-not $NoApp) {
            $windows.Add([ordered]@{
                id           = "firefox"
                type         = "app"
                enabled      = $true
                match        = [ordered]@{ kind = "exe"; value = "firefox.exe" }
                launch       = [ordered]@{ kind = "exe"; value = 'C:\fake\firefox.exe'; args = @() }
                instanceMode = "shared"
                layout       = [ordered]@{ x = 10; y = 20; w = 500; h = 400 }
            }) | Out-Null
        }

        if ($DisabledGhost) {
            $windows.Add([ordered]@{
                id        = "ghost"
                type      = "terminal"
                enabled   = $false
                windowId  = "DevWS-LC-ghost"
                path      = $TestRoot
                elevated  = $true
                tabs      = @([ordered]@{ command = $null; args = @() })
                activeTab = 0
                layout    = [ordered]@{ x = 9000; y = 9000; w = 100; h = 100 }
            }) | Out-Null
        }

        $set = [ordered]@{ id = "main" }

        if ($WithProfiles) {
            $layouts = [ordered]@{}
            foreach ($entry in @($OverrideEntries)) {
                $layouts[[string]$entry.Id] = $entry.Rect
            }

            $set["layoutProfiles"] = @([ordered]@{
                id      = "docked"
                match   = [ordered]@{ mode = "exact"; monitors = @("path:AAA/1@0,0,1000x1000") }
                layouts = $layouts
            })
        }

        $set["windows"] = @($windows.ToArray())
        $config = [ordered]@{ version = 3; defaultSet = "main"; bindings = @(); sets = @($set) }
        Set-Content -LiteralPath $path -Value ($config | ConvertTo-Json -Depth 20) -Encoding UTF8
        return $path
    }

    function Invoke-LifecycleLayoutFixture {
        param(
            [Parameter(Mandatory)][string]$ConfigPath,
            [Parameter(Mandatory)][scriptblock]$Body
        )

        $saved = $env:DEVWS_CONFIG
        $env:DEVWS_CONFIG = $ConfigPath

        try {
            & $Body
        }
        finally {
            if ($null -ne $saved) { $env:DEVWS_CONFIG = $saved } else { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue }
        }
    }

    Test-Case "profile-free lifecycle plan never samples topology and keeps fallback geometry" {
        $set = New-LayoutProfileTestSet -Windows @(
            (New-LayoutProfileTestTerminal -Id "slot"),
            (New-LayoutProfileTestApp -Id "firefox")
        )

        $script:lcTopologyCalls = 0
        $provider = { $script:lcTopologyCalls++; throw "profile-free lifecycle must never sample topology" }

        $plan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -TopologyProvider $provider

        Assert-Equal 0 $script:lcTopologyCalls "topology provider never invoked"
        Assert-Equal $false ([bool]$plan.ProfileAware) "profile-free plan not profile-aware"
        Assert-Equal "fallback" ([string]$plan.Source) "source is fallback"
        Assert-Equal "no-profiles" ([string]$plan.Reason) "reason is no-profiles"
        Assert-Equal 2 @($plan.Items).Count "both target items placed"
        Assert-Equal 0 @($plan.Warnings).Count "no warnings"

        foreach ($item in @($plan.Items)) {
            Assert-Equal $true ([bool]$item.ApplyGeometry) "$($item.ItemId) keeps movement enabled"
            Assert-Equal "fallback" ([string]$item.Source) "$($item.ItemId) fallback source"
            Assert-Equal $null $item.Reachable "$($item.ItemId) has no reachability gate"
        }

        # A disabled-only set has no targets and still performs no monitor read.
        $script:lcTopologyCalls = 0
        $null = New-DevWSLifecycleLayoutPlan -SetId "main" -Set (New-LayoutProfileTestSet -Windows @((New-LayoutProfileTestTerminal -Id "only" -Enabled $false))) -TopologyProvider $provider
        Assert-Equal 0 $script:lcTopologyCalls "disabled-only set performs no monitor read"

        # The launch wrapper returns null for a no-op launch (no placement
        # policy, no topology cost).
        $fixturePath = Write-LifecycleLayoutFixtureConfig -Name "plan-noop" -DisabledSlot -NoApp
        Invoke-LifecycleLayoutFixture -ConfigPath $fixturePath -Body {
            function Get-DevWSMonitorTopology { throw "no-op launch must not sample topology" }
            $plan = New-DevWSLaunchLayoutPlan -Config (Read-DevWSConfigFile -Path $env:DEVWS_CONFIG) -SetId "main"
            Assert-Equal $null $plan "no enabled items -> no plan"
        }
    }

    Test-Case "profile-aware plan samples topology once and resolves matched and no-match placement" {
        $sig = 'path:AAA/1@0,0,1000x1000;path:BBB/2@1000,0,1000x1000'

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sig -split ';')
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "slot" -Rect (New-LayoutProfileTestRect -X 100 -Y 0 -W 600 -H 800)

        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @(
            (New-LayoutProfileTestTerminal -Id "slot"),
            (New-LayoutProfileTestApp -Id "firefox")
        )

        $script:lcTopologyCalls = 0
        $plan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -TopologyProvider { $script:lcTopologyCalls++; New-LayoutProfileTestTopology -Signature $sig }

        Assert-Equal 1 $script:lcTopologyCalls "exactly one topology snapshot"
        Assert-Equal "profile" ([string]$plan.Source) "matched source"
        Assert-Equal "docked" ([string]$plan.ProfileId) "matched profile id"
        Assert-Equal "matched" ([string]$plan.Reason) "matched reason"
        Assert-Equal $sig ([string]$plan.TopologySignature) "signature frozen"
        Assert-True (-not [string]::IsNullOrWhiteSpace([string]$plan.TopologyFingerprint)) "fingerprint frozen"
        Assert-Equal "slot,firefox" ((@($plan.Items) | ForEach-Object { $_.ItemId }) -join ",") "configured order preserved"

        $slot = @($plan.Items | Where-Object { $_.ItemId -eq "slot" })[0]
        $firefox = @($plan.Items | Where-Object { $_.ItemId -eq "firefox" })[0]

        Assert-Equal "profile" ([string]$slot.Source) "slot profile override"
        Assert-Equal 100 ([int]$slot.Layout.x) "slot exact profile rect"
        Assert-Equal $true ([bool]$slot.ApplyGeometry) "reachable profile override moves"
        Assert-Equal "fallback" ([string]$firefox.Source) "sparse firefox falls back"
        Assert-Equal 1 ([int]$firefox.Layout.x) "firefox fallback rect"
        Assert-Equal $true ([bool]$firefox.ApplyGeometry) "reachable fallback still moves"

        # No profile matches: every item falls back; this is NOT a failure.
        $script:lcTopologyCalls = 0
        $missPlan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -TopologyProvider { $script:lcTopologyCalls++; New-LayoutProfileTestTopology -Signature 'path:ZZZ/9@0,0,1000x1000' }

        Assert-Equal 1 $script:lcTopologyCalls "no-match still samples exactly once"
        Assert-Equal "fallback" ([string]$missPlan.Source) "no-match source"
        Assert-Equal "no-match" ([string]$missPlan.Reason) "no-match reason"
        Assert-Equal 0 @($missPlan.Items | Where-Object { -not [bool]$_.ApplyGeometry }).Count "reachable fallbacks all move"
    }

    Test-Case "profile-aware plan refuses unsafe topologies before any placement" {
        $sig = 'path:AAA/1@0,0,1000x1000'

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sig -split ';')
        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @((New-LayoutProfileTestTerminal -Id "slot"))

        foreach ($fixture in @(
            @{ Topology = $null; Needle = "unavailable" },
            @{ Topology = (New-LayoutProfileTestTopology -Signature $sig -IdentityComplete $false); Needle = "not safely matchable" },
            @{ Topology = (New-LayoutProfileTestTopology -Signature $sig -CorrelationComplete $false); Needle = "not safely matchable" },
            @{ Topology = (New-LayoutProfileTestTopology -Signature $sig -Ambiguous $true); Needle = "ambiguous monitor identities" }
        )) {
            $script:lcTopologyCalls = 0
            $topologyValue = $fixture.Topology
            $message = $null

            try { $null = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -TopologyProvider { $script:lcTopologyCalls++; $topologyValue } }
            catch { $message = $_.Exception.Message }

            Assert-True ($null -ne $message) "unsafe topology refused: $($fixture.Needle)"
            Assert-Contains ([string]$message) $fixture.Needle "refusal names the problem: $($fixture.Needle)"
            Assert-Contains ([string]$message) "refused before any side effect" "refusal states the boundary"
            Assert-Equal 1 $script:lcTopologyCalls "unsafe topology sampled once"
        }

        # Duplicate matchers are a static config error, refused defensively.
        $dupeA = New-DevWSLayoutProfile -Id "a" -MonitorTokens @($sig -split ';')
        $dupeB = New-DevWSLayoutProfile -Id "b" -MonitorTokens @($sig -split ';')
        $dupeSet = New-LayoutProfileTestSet -Profiles @($dupeA, $dupeB) -Windows @((New-LayoutProfileTestTerminal -Id "slot"))

        $message = $null
        try { $null = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $dupeSet -TopologyProvider { New-LayoutProfileTestTopology -Signature $sig } }
        catch { $message = $_.Exception.Message }

        Assert-Contains ([string]$message) "two or more layout profiles" "duplicate matchers refused"
    }

    Test-Case "unreachable profile override is fatal and target-scoped" {
        $sig = 'path:AAA/1@0,0,1000x1000'

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sig -split ';')
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "slot" -Rect (New-LayoutProfileTestRect -X 9000 -Y 9000 -W 100 -H 100)

        $slot = New-LayoutProfileTestTerminal -Id "slot"
        $ghost = New-LayoutProfileTestTerminal -Id "ghost" -Enabled $false
        $browser = New-LayoutProfileTestApp -Id "browser"
        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @($slot, $ghost, $browser)

        $message = $null
        try { $null = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -TopologyProvider { New-LayoutProfileTestTopology -Signature $sig } }
        catch { $message = $_.Exception.Message }

        Assert-Contains ([string]$message) "Set 'main'" "set named"
        Assert-Contains ([string]$message) "'slot'" "item named"
        Assert-Contains ([string]$message) "'docked'" "profile named"
        Assert-Contains ([string]$message) "x=9000 y=9000 w=100 h=100" "rectangle named"
        Assert-Contains ([string]$message) "not reachable" "reachability issue named"
        Assert-Contains ([string]$message) "refused before any side effect" "fatal boundary stated"

        # The remediation names REAL commands: set-geometry takes --layout and
        # all four geometry switches (never the invalid inline `--profile`),
        # and both references are concrete scoped references.
        Assert-Contains ([string]$message) "--layout docked" "remediation uses the valid --layout selector"
        Assert-NotContains ([string]$message) "set-geometry --profile" "no invalid set-geometry --profile remediation"
        Assert-Contains ([string]$message) "ws set-geometry main/slot" "remediation carries the concrete scoped item reference"
        Assert-Contains ([string]$message) "ws layout-profile match main/docked" "re-key remediation carries the concrete scoped profile reference"

        # An unreachable override on an item OUTSIDE the operation never blocks.
        $targetedPlan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -Items @($browser) -TopologyProvider { New-LayoutProfileTestTopology -Signature $sig }
        Assert-Equal 1 @($targetedPlan.Items).Count "only the requested target is placed"
        Assert-Equal "browser" ([string]@($targetedPlan.Items)[0].ItemId) "requested target placed"

        # A targeted DISABLED item is included (single-reset semantics).
        $disabledPlan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -Items @($ghost) -TopologyProvider { New-LayoutProfileTestTopology -Signature $sig }
        $ghostItem = @($disabledPlan.Items)[0]
        Assert-Equal "ghost" ([string]$ghostItem.ItemId) "disabled target included"
        Assert-Equal $true ([bool]$ghostItem.ApplyGeometry) "disabled target still uses its reachable fallback"
    }

    Test-Case "unreachable fallback geometry skips movement with deterministic warnings" {
        $sig = 'path:AAA/1@0,0,1000x1000'

        $profile = New-DevWSLayoutProfile -Id "docked" -MonitorTokens @($sig -split ';')
        Set-DevWSLayoutProfileRect -Profile $profile -ItemId "firefox" -Rect (New-LayoutProfileTestRect -X 10 -Y 20 -W 500 -H 400)

        $farTerm = New-LayoutProfileTestTerminal -Id "slot" -X 9000
        $set = New-LayoutProfileTestSet -Profiles @($profile) -Windows @($farTerm, (New-LayoutProfileTestApp -Id "firefox"))

        $plan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set -TopologyProvider { New-LayoutProfileTestTopology -Signature $sig }

        $slot = @($plan.Items | Where-Object { $_.ItemId -eq "slot" })[0]
        $firefox = @($plan.Items | Where-Object { $_.ItemId -eq "firefox" })[0]

        Assert-Equal $false ([bool]$slot.ApplyGeometry) "unreachable fallback skips movement"
        Assert-Equal $false ([bool]$slot.Reachable) "slot marked unreachable"
        Assert-Equal $true ([bool]$firefox.ApplyGeometry) "profile override still moves"
        Assert-Equal 1 @($plan.Warnings).Count "exactly one warning"
        Assert-Equal "main/slot: fallback layout is not reachable on the current monitor topology; the item will be handled normally but its window position will not be changed." ([string]$plan.Warnings[0]) "deterministic warning text"

        # No-match fallback is subject to the same skip policy.
        $noMatchSet = New-LayoutProfileTestSet -Profiles @($profile) -Windows @((New-LayoutProfileTestTerminal -Id "slot" -X 9000))
        $noMatchPlan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $noMatchSet -TopologyProvider { New-LayoutProfileTestTopology -Signature 'path:ZZZ/9@0,0,1000x1000' }
        $noMatchItem = @($noMatchPlan.Items)[0]

        Assert-Equal $false ([bool]$noMatchItem.ApplyGeometry) "no-match fallback skip"
        Assert-Equal "fallback" ([string]$noMatchItem.Source) "no-match item source"
        Assert-Equal 1 @($noMatchPlan.Warnings).Count "no-match warning once"

        # Warnings follow configured order, never hashtable order.
        $orderedSet = New-LayoutProfileTestSet -Profiles @($profile) -Windows @(
            (New-LayoutProfileTestTerminal -Id "zfar" -X 9000),
            (New-LayoutProfileTestTerminal -Id "afar" -X 9001)
        )
        $orderedPlan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $orderedSet -TopologyProvider { New-LayoutProfileTestTopology -Signature $sig }

        Assert-Equal 2 @($orderedPlan.Warnings).Count "two skip warnings"
        Assert-Contains ([string]@($orderedPlan.Warnings)[0]) "zfar" "configured order first"
        Assert-Contains ([string]@($orderedPlan.Warnings)[1]) "afar" "configured order second"
    }

    Test-Case "precomputed lifecycle plan validation guards transaction misuse" {
        $set = New-LayoutProfileTestSet -Windows @(
            (New-LayoutProfileTestTerminal -Id "slot"),
            (New-LayoutProfileTestApp -Id "firefox")
        )
        $items = @($set.windows | Where-Object { $_.enabled })
        $plan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set

        Assert-DevWSLifecycleLayoutPlan -Plan $plan -SetId "main" -Items $items

        $slotItem = @($plan.Items | Where-Object { $_.ItemId -eq "slot" })[0]
        $firefoxItem = @($plan.Items | Where-Object { $_.ItemId -eq "firefox" })[0]

        $cases = @(
            @{ Plan = [pscustomobject]@{ SetId = "secondary"; Items = @() }; Needle = "belongs to set" },
            @{ Plan = [pscustomobject]@{ SetId = "main"; Items = @($slotItem, $slotItem) }; Needle = "duplicate item" },
            @{ Plan = [pscustomobject]@{ SetId = "main"; Items = @($slotItem) }; Needle = "missing a placement record for target 'firefox'" },
            @{ Plan = [pscustomobject]@{ SetId = "main"; Items = @($slotItem, $firefoxItem, [pscustomobject]@{ ItemId = "ghost"; Type = "terminal"; ApplyGeometry = $true; Layout = $slotItem.Layout }) }; Needle = "not a target of this operation" },
            @{ Plan = [pscustomobject]@{ SetId = "main"; Items = @([pscustomobject]@{ ItemId = "slot"; Type = "terminal"; ApplyGeometry = $true; Layout = $null }) }; Needle = "invalid rectangle" }
        )

        foreach ($case in $cases) {
            $message = $null
            try { Assert-DevWSLifecycleLayoutPlan -Plan $case.Plan -SetId "main" -Items $items } catch { $message = $_.Exception.Message }
            Assert-Contains ([string]$message) $case.Needle "misuse rejected: $($case.Needle)"
        }

        # move=false records need no rectangle.
        $skipOnly = [pscustomobject]@{ SetId = "main"; Items = @(
            [pscustomobject]@{ ItemId = "slot"; Type = "terminal"; ApplyGeometry = $false; Layout = $null },
            [pscustomobject]@{ ItemId = "firefox"; Type = "app"; ApplyGeometry = $false; Layout = $null }
        ) }
        Assert-DevWSLifecycleLayoutPlan -Plan $skipOnly -SetId "main" -Items $items
    }

    Test-Case "terminal placement records transport final geometry only" {
        $set = New-LayoutProfileTestSet -Windows @(
            (New-LayoutProfileTestTerminal -Id "slot"),
            (New-LayoutProfileTestApp -Id "firefox"),
            (New-LayoutProfileTestTerminal -Id "term2")
        )
        $plan = New-DevWSLifecycleLayoutPlan -SetId "main" -Set $set
        $records = @(Get-DevWSLifecycleTerminalPlacementRecords -Plan $plan)

        Assert-Equal 2 @($records).Count "apps are not transported"
        Assert-Equal "slot,term2" ((@($records) | ForEach-Object { $_.id }) -join ",") "configured terminal order"
        Assert-Equal $true ([bool]$records[0].move) "move decision present"
        Assert-Equal 1 ([int]$records[0].x) "exact geometry transported"
        Assert-Equal 3 ([int]$records[0].w) "width transported"
        Assert-True (-not (Test-DevWSProperty -Object $records[0] -Name "profileId")) "no profile authority transported"
        Assert-True (-not (Test-DevWSProperty -Object $records[0] -Name "fingerprint")) "no topology authority transported"

        $skipPlan = [pscustomobject]@{ SetId = "main"; Items = @(
            [pscustomobject]@{ ItemId = "slot"; Type = "terminal"; ApplyGeometry = $false; Layout = (New-LayoutProfileTestRect -X 9000 -Y 9000 -W 100 -H 100) }
        ) }
        $skipRecord = @(Get-DevWSLifecycleTerminalPlacementRecords -Plan $skipPlan)[0]

        Assert-Equal $false ([bool]$skipRecord.move) "skip record"
        Assert-True (-not (Test-DevWSProperty -Object $skipRecord -Name "x")) "geometry omitted when move is false"
    }

    Test-Case "delegated app plan applies frozen placements (present, missing, move=false)" {
        $app = New-LayoutProfileTestApp -Id "firefox"
        $profileRect = New-LayoutProfileTestRect -X 100 -Y 200 -W 300 -H 400
        $fallbackRect = $app.layout

        $moves = [System.Collections.Generic.List[object]]::new()

        function Move-DevWSWindowHwnd { param([long]$Hwnd, $Layout, [string]$Context) $moves.Add([pscustomobject]@{ Hwnd = [long]$Hwnd; Layout = $Layout; Context = $Context }) | Out-Null }

        # Present app with a frozen placement.
        $plan = [pscustomobject]@{
            SetId = "main"; Apps = @($app)
            Present = @([pscustomobject]@{ Ref = "main/firefox"; App = $app; Hwnd = [long]111 })
            Missing = @(); ProbeHwnds = @(); Failures = @(); SharedProbes = 1
            Placements = @{ "firefox" = [pscustomobject]@{ ApplyGeometry = $true; Layout = $profileRect } }
            ReadyAtUtc = [DateTimeOffset]::UtcNow
        }

        $result = Start-DevWSAppLaunchPlan -Plan $plan
        Assert-Equal 1 @($result.Moved).Count "present app processed"
        Assert-Equal 1 $moves.Count "present app moved"
        Assert-Equal 100 ([int]$moves[0].Layout.x) "profile rect delivered to Move"
        Assert-True ([int]$moves[0].Layout.x -ne [int]$fallbackRect.x) "fallback rect never used for movement"

        # Present app with move=false: handled, never moved, not a failure.
        $skipPlan = [pscustomobject]@{
            SetId = "main"; Apps = @($app)
            Present = @([pscustomobject]@{ Ref = "main/firefox"; App = $app; Hwnd = [long]222 })
            Missing = @(); ProbeHwnds = @(); Failures = @(); SharedProbes = 1
            Placements = @{ "firefox" = [pscustomobject]@{ ApplyGeometry = $false; Layout = $profileRect } }
            ReadyAtUtc = [DateTimeOffset]::UtcNow
        }

        $moves.Clear()
        $skipResult = Start-DevWSAppLaunchPlan -Plan $skipPlan
        Assert-Equal 0 $moves.Count "move=false never moves the present app"
        Assert-Equal 0 @($skipResult.Moved).Count "skip is not a move"
        Assert-Equal 1 @($skipResult.Skipped).Count "skip recorded"
        Assert-Equal 0 @($skipResult.Failures).Count "skip is not a failure"

        # Missing app: launched, resolved, finalized with the SAME frozen rect.
        function Invoke-DevWSAppLaunchCommand { param($App) }
        function Get-DevWSAppWindowProbe { param($Config, $Candidates, [switch]$TolerantOwnership) return @() }
        function Complete-DevWSAppLaunchAttempt { param($SetId, $App, $Probed, $PreLaunchHwnds, $Deadline, [int]$LaunchTimeoutSeconds) return [pscustomobject]@{ Status = "resolved"; Hwnd = [long]333 } }

        $missingPlan = [pscustomobject]@{
            SetId = "main"; Apps = @($app)
            Present = @(); Missing = @($app); ProbeHwnds = @([long]1); Failures = @(); SharedProbes = 1
            Placements = @{ "firefox" = [pscustomobject]@{ ApplyGeometry = $true; Layout = $profileRect } }
            ReadyAtUtc = [DateTimeOffset]::UtcNow
        }

        $moves.Clear()
        $start = Start-DevWSAppLaunchPlan -Plan $missingPlan
        Assert-Equal 1 @($start.Kicks).Count "missing app kicked"
        $complete = Complete-DevWSAppLaunchPlan -Plan $missingPlan -Config ([pscustomobject]@{}) -Kicks $start.Kicks -PollMilliseconds 1
        Assert-Equal 1 @($complete.Finalized).Count "missing app finalized"
        Assert-Equal 1 $moves.Count "missing app moved after resolution"
        Assert-Equal 100 ([int]$moves[0].Layout.x) "exact frozen rect applied after resolution"
        Assert-Equal ([long]333) ([long]$moves[0].Hwnd) "resolved hwnd moved"

        # Missing app with move=false: launched/resolved/finalized, no move.
        $skipMissingPlan = [pscustomobject]@{
            SetId = "main"; Apps = @($app)
            Present = @(); Missing = @($app); ProbeHwnds = @([long]1); Failures = @(); SharedProbes = 1
            Placements = @{ "firefox" = [pscustomobject]@{ ApplyGeometry = $false; Layout = $profileRect } }
            ReadyAtUtc = [DateTimeOffset]::UtcNow
        }

        $moves.Clear()
        $start2 = Start-DevWSAppLaunchPlan -Plan $skipMissingPlan
        $complete2 = Complete-DevWSAppLaunchPlan -Plan $skipMissingPlan -Config ([pscustomobject]@{}) -Kicks $start2.Kicks -PollMilliseconds 1
        Assert-Equal 0 $moves.Count "no move after resolution when skipped"
        Assert-Equal 1 @($complete2.Finalized).Count "skipped missing app stays finalized"

        # Plan refresh preserves the placement map by reference.
        $placementMap = @{ "firefox" = [pscustomobject]@{ ApplyGeometry = $true; Layout = $profileRect } }
        $refreshPlan = [pscustomobject]@{
            SetId = "main"; Apps = @($app)
            Present = @(); Missing = @($app); ProbeHwnds = @(); Failures = @(); SharedProbes = 1
            Placements = $placementMap
            ReadyAtUtc = [DateTimeOffset]::UtcNow
        }

        function Resolve-DevWSAppLifecycleWindow { param($Config, [string]$SetId, $App, [string]$Operation, $InitialProbe) return [long]0 }

        $refreshed = Update-DevWSAppLaunchPlan -Plan $refreshPlan -Config ([pscustomobject]@{}) -SetId "main"
        Assert-True ([object]::ReferenceEquals($refreshPlan.Placements, $refreshed.Placements)) "refresh preserves the placement map"

        # Direct legacy callers without a placement map keep App.layout.
        $legacyPlan = [pscustomobject]@{
            SetId = "main"; Apps = @($app)
            Present = @([pscustomobject]@{ Ref = "main/firefox"; App = $app; Hwnd = [long]444 })
            Missing = @(); ProbeHwnds = @(); Failures = @(); SharedProbes = 1
            ReadyAtUtc = [DateTimeOffset]::UtcNow
        }

        $moves.Clear()
        $null = Start-DevWSAppLaunchPlan -Plan $legacyPlan
        Assert-Equal 1 $moves.Count "legacy caller still moves"
        Assert-Equal ([int]$fallbackRect.x) ([int]$moves[0].Layout.x) "legacy caller uses App.layout"
    }

    Test-Case "terminal plan records and completion consume frozen placements" {
        $terminal = New-LayoutProfileTestTerminal -Id "slot"
        $profileRect = New-LayoutProfileTestRect -X 100 -Y 0 -W 600 -H 800

        # Missing terminal with an explicit move placement.
        $placementMap = [System.Collections.Hashtable]::new([System.StringComparer]::OrdinalIgnoreCase)
        $placementMap["slot"] = [pscustomobject]@{ ApplyGeometry = $true; Layout = $profileRect }

        $config = New-LayoutProfileTestConfig -Set (New-LayoutProfileTestSet -Windows @($terminal))
        $plan = Get-DevWSTerminalLaunchPlan `
            -Config $config `
            -SetId "main" `
            -Terminals @($terminal) `
            -WtHwnds @() `
            -Placements $placementMap `
            -TrackingContextFactory { param($t) [pscustomobject]@{ Marker = "ctx" } } `
            -CreateArgumentsFactory { param($t, $c) [string[]]@("fake-arg") }

        $record = @($plan.Terminals)[0]
        Assert-Equal "missing" ([string]$record.State) "fixture terminal is missing"
        Assert-Equal $true ([bool]$record.ApplyGeometry) "explicit move decision"
        Assert-Equal 100 ([int]$record.Layout.x) "frozen rect carried on the record"
        Assert-Equal "fake-arg" ([string](@($record.CreateArguments)[0])) "creation args unchanged"
        Assert-Equal "ctx" ([string]$record.TrackingContexts.Marker) "tracking context unchanged"

        # Present terminal with an explicit placement: move + activeTab.
        $moves = [System.Collections.Generic.List[object]]::new()
        $selects = [System.Collections.Generic.List[object]]::new()

        function Move-DevWSWindowHwnd { param([long]$Hwnd, $Layout, [string]$Context) $moves.Add([pscustomobject]@{ Hwnd = [long]$Hwnd; Layout = $Layout }) | Out-Null }
        function Select-DevWSTabByIndexFromHwnd { param([long]$Hwnd, [int]$Index, [string]$Context) $selects.Add([pscustomobject]@{ Hwnd = [long]$Hwnd; Index = $Index }) | Out-Null; return $true }
        function Update-DevWSRuntimeTerminal { param([string]$SetId, [string]$Id, [string]$WindowId, [long]$Hwnd) }

        $presentRecord = New-DevWSTerminalPlanRecord -Order 0 -Terminal $terminal -SetId "main" -State "present" -Source "snapshot" -Hwnd ([long]555) -ApplyGeometry $true -Layout $profileRect
        $presentPlan = [pscustomobject]@{ PlanId = "p"; SetId = "main"; WtHwnds = @(); WtToken = ""; Terminals = @($presentRecord) }

        $complete = Complete-DevWSTerminalLaunchPlan -Plan $presentPlan -PollMilliseconds 1
        Assert-Equal 1 @($complete.Finalized).Count "present terminal finalized"
        Assert-Equal 1 $moves.Count "present terminal moved"
        Assert-Equal 100 ([int]$moves[0].Layout.x) "present move uses the frozen record layout"
        Assert-Equal 1 $selects.Count "activeTab still selected"

        # Present terminal with move=false: activeTab maintained, no move.
        $skipRecord = New-DevWSTerminalPlanRecord -Order 0 -Terminal $terminal -SetId "main" -State "present" -Source "snapshot" -Hwnd ([long]556) -ApplyGeometry $false -Layout $profileRect
        $skipPlan = [pscustomobject]@{ PlanId = "p2"; SetId = "main"; WtHwnds = @(); WtToken = ""; Terminals = @($skipRecord) }

        $moves.Clear()
        $selects.Clear()
        $skipComplete = Complete-DevWSTerminalLaunchPlan -Plan $skipPlan -PollMilliseconds 1
        Assert-Equal 0 $moves.Count "move=false present terminal not moved"
        Assert-Equal 1 $selects.Count "activeTab maintenance continues without movement"
        Assert-Equal 1 @($skipComplete.Finalized).Count "skip is not a failure"

        # Kicked terminal: identified, then moved (or skipped) with the frozen decision.
        function Get-DevWSTerminalWindowSnapshot {
            return @([pscustomobject]@{
                Hwnd        = [long]777
                ProcessName = "WindowsTerminal"
                TabNames    = (New-DevWSPresentTabNameSet -Names @("DevWS-LP-slot"))
                RawCount    = 1
            })
        }

        $kick = [pscustomobject]@{ Kicks = @([pscustomobject]@{ Order = 0; TerminalId = "slot"; WindowId = "DevWS-LP-slot"; CreateArguments = @("x"); StartedAtUtc = [DateTimeOffset]::UtcNow; DeadlineUtc = [DateTimeOffset]::UtcNow.AddSeconds(30) }); Failures = @() }

        $kickedRecord = New-DevWSTerminalPlanRecord -Order 0 -Terminal $terminal -SetId "main" -State "missing" -Source "fast-missing" -TrackingContexts ([pscustomobject]@{ Marker = "ctx" }) -CreateArguments ([string[]]@("x")) -ApplyGeometry $true -Layout $profileRect
        $kickedPlan = [pscustomobject]@{ PlanId = "p3"; SetId = "main"; WtHwnds = @(); WtToken = ""; Terminals = @($kickedRecord) }

        $moves.Clear()
        $kickedComplete = Complete-DevWSTerminalLaunchPlan -Plan $kickedPlan -KickResult $kick -PollMilliseconds 1
        Assert-Equal 1 @($kickedComplete.Finalized).Count "kicked terminal finalized"
        Assert-Equal 1 $moves.Count "kicked terminal moved after identification"
        Assert-Equal 100 ([int]$moves[0].Layout.x) "kicked move uses the frozen record layout"

        $skipKickedRecord = New-DevWSTerminalPlanRecord -Order 0 -Terminal $terminal -SetId "main" -State "missing" -Source "fast-missing" -TrackingContexts ([pscustomobject]@{ Marker = "ctx" }) -CreateArguments ([string[]]@("x")) -ApplyGeometry $false -Layout $profileRect
        $skipKickedPlan = [pscustomobject]@{ PlanId = "p4"; SetId = "main"; WtHwnds = @(); WtToken = ""; Terminals = @($skipKickedRecord) }

        $moves.Clear()
        $skipKickedComplete = Complete-DevWSTerminalLaunchPlan -Plan $skipKickedPlan -KickResult $kick -PollMilliseconds 1
        Assert-Equal 0 $moves.Count "move=false kicked terminal never moved"
        Assert-Equal 1 @($skipKickedComplete.Finalized).Count "skipped kicked terminal stays finalized"

        # Direct legacy callers without an explicit placement keep Terminal.layout.
        $legacyRecord = New-DevWSTerminalPlanRecord -Order 0 -Terminal $terminal -SetId "main" -State "present" -Source "snapshot" -Hwnd ([long]558)
        Assert-Equal $true ([bool]$legacyRecord.ApplyGeometry) "legacy default move=true"
        Assert-Equal ([int]$terminal.layout.x) ([int]$legacyRecord.Layout.x) "legacy default uses Terminal.layout"
    }

    Test-Case "launch transaction transmits frozen placements and replan reuses them" {
        $configPath = Write-LifecycleLayoutFixtureConfig -Name "tx-broker" -NoApp
        $prepares = [System.Collections.Generic.List[object]]::new()

        Invoke-LifecycleLayoutFixture -ConfigPath $configPath -Body {
            function Invoke-DevWSWithLifecycleLock { param([Parameter(Mandatory)][scriptblock]$ScriptBlock, [int]$TimeoutSeconds = 300, [string]$MutexName = "test") return (& $ScriptBlock) }
            function Test-DevWSElevatedBrokerAvailable { param([string]$PipeName, [int]$TimeoutMilliseconds = 1500) return $true }
            function Request-DevWSElevatedBrokerRecovery { param([int]$TimeoutSeconds = 20, [int]$PingTimeoutMilliseconds = 1500) return $true }
            function New-DevWSElevatedBrokerPrepare {
                param([long]$RequestId, [string]$SetId, [AllowNull()][object[]]$TerminalPlacements = $null, [string]$PipeName, [int]$TimeoutMilliseconds = 3000)
                $prepares.Add([pscustomobject]@{ RequestId = $RequestId; SetId = $SetId; Placements = @($TerminalPlacements) })
                return [pscustomobject]@{ Marker = ("conn-" + [string]$prepares.Count) }
            }
            function Wait-DevWSElevatedBrokerPrepare { param($Connection, [int]$TimeoutMilliseconds = 30000) return [pscustomobject]@{ type = "ready"; planId = "plan-1"; elapsedMs = 5; plan = [pscustomobject]@{ counts = [pscustomobject]@{ present = 0; missing = 1; ambiguous = 0; failed = 0 } } } }
            function Send-DevWSElevatedBrokerGo {
                param($Connection, [long]$RequestId, [string]$PlanId, [int]$TimeoutMilliseconds = 10000)
                $script:lcGoCount++
                if ($script:lcGoCount -eq 1) { return [pscustomobject]@{ type = "replan-required"; reason = "wt-generation-changed" } }
                return [pscustomobject]@{ type = "go-ack"; recheckMs = 1; ackAt = 1 }
            }
            function Read-DevWSElevatedBrokerFinal { param($Connection, [int]$TimeoutMilliseconds = 120000) return [pscustomobject]@{ type = "final"; planId = "plan-1"; kicked = @(); summary = [pscustomobject]@{ finalized = @(); failures = @() } } }
            function Close-DevWSElevatedBrokerConnection { param($Connection) }
            function Start-DevWSWorkerRequest { param([string]$Kind, [string]$TaskName, $Payload, [int]$TimeoutSeconds = 60) throw "the Helper must not run after GO-ACK" }

            $script:lcGoCount = 0
            $null = Invoke-DevWSLaunchTransaction -Config (Read-DevWSConfigFile -Path $env:DEVWS_CONFIG) -SetId "main"

            Assert-Equal 2 $prepares.Count "one bounded re-prepare"
            Assert-Equal 2 $script:lcGoCount "two GO attempts (replan then ACK)"

            $first = @($prepares[0].Placements)
            $second = @($prepares[1].Placements)

            Assert-Equal 1 @($first).Count "one placement record per enabled terminal"
            Assert-Equal "slot" ([string]$first[0].id) "record id"
            Assert-Equal $true ([bool]$first[0].move) "record move"
            Assert-Equal 1 ([int]$first[0].x) "record exact fallback geometry"
            Assert-Equal 300 ([int]$first[0].w) "record exact fallback width"
            Assert-Equal ($first | ConvertTo-Json -Compress -Depth 6) ($second | ConvertTo-Json -Compress -Depth 6) "replan reuses identical frozen placements"
        }
    }

