        New-Item -ItemType Directory -Path $probeDir -Force | Out-Null

        $scriptPath = Join-Path $probeDir "p2e-noop.ahk"
        $noopBody = @'
#Requires AutoHotkey v2.0
ExitApp 0
'@
        Set-Content -LiteralPath $scriptPath -Value $noopBody -Encoding utf8

        $probePath = Join-Path $probeDir "p2e-startfail-probe.ps1"
        $probeSource = @'
param([string]$RepoRoot, [string]$ScriptPath)
. (Join-Path $RepoRoot "src\lib\devws-native.ps1")
. (Join-Path $RepoRoot "src\lib\devws-paths.ps1")
. (Join-Path $RepoRoot "src\lib\devws-ahk.ps1")

function Get-DevWSAutoHotkeyPath { return (Join-Path $PSScriptRoot "missing\definitely-not-autohotkey.exe") }

$threw = $false
$count = -1

try {
    $emitted = @(Invoke-DevWSAhk -Script $ScriptPath)
    $count = @($emitted).Count
}
catch {
    $threw = $true
}

"threw=$threw"
"emitted=$count"
'@
        Set-Content -LiteralPath $probePath -Value $probeSource -NoNewline

        $output = & pwsh -NoLogo -NoProfile -File $probePath -RepoRoot $RepoRoot -ScriptPath $scriptPath 2>&1 | Out-String
