    function New-P2EHealthStubContext {
        param(
            [Parameter(Mandatory)][string]$Name,
            [Parameter(Mandatory)][string]$ChildBody
        )

        $root = Join-Path $TestRoot "p2e-health-$Name"
        $appDir = Join-Path $root "app"
        $stateDir = Join-Path $root "state"
        New-Item -ItemType Directory -Path $appDir, $stateDir -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $appDir "ws.ps1") -Value $ChildBody -NoNewline

        $configPath = Join-Path $root "workspace.json"
        Set-Content -LiteralPath $configPath -Value '{"version":3,"defaultSet":"main","bindings":[],"sets":[{"id":"main","windows":[]}]}' -Encoding utf8

        return [pscustomobject]@{
            InstallRoot   = $root
            StateRoot     = $stateDir
            CanonicalPath = $configPath
        }
    }

    function Invoke-P2EHealthRun {
        param(
            [Parameter(Mandatory)]$Context,
            [Parameter(Mandatory)][string]$TempDir,
            [int]$ListTimeoutSeconds = 20
        )

        $savedTmp = $env:TMP
        $savedTemp = $env:TEMP
        $savedConfig = $env:DEVWS_CONFIG

        try {
            $env:TMP = $TempDir
            $env:TEMP = $TempDir
            $env:DEVWS_CONFIG = (Join-Path (Split-Path -Parent $Context.CanonicalPath) "sentinel-config.json")

            $summary = Invoke-DevWSHealthCheck -Context $Context -ListTimeoutSeconds $ListTimeoutSeconds

            $byId = @{}
            foreach ($entry in @($summary.Results)) { $byId[$entry.Id] = $entry }

            return [pscustomobject]@{
                Summary     = $summary
                ById        = $byId
                ConfigAfter = $env:DEVWS_CONFIG
            }
        }
        finally {
            if ($null -eq $savedTmp) { Remove-Item Env:\TMP -ErrorAction SilentlyContinue } else { $env:TMP = $savedTmp }
            if ($null -eq $savedTemp) { Remove-Item Env:\TEMP -ErrorAction SilentlyContinue } else { $env:TEMP = $savedTemp }
            if ($null -eq $savedConfig) { Remove-Item Env:\DEVWS_CONFIG -ErrorAction SilentlyContinue } else { $env:DEVWS_CONFIG = $savedConfig }
        }
    }

    Test-Case "health ws-list check uses no temporary files and keeps its contract" {
        $tempDir = Join-Path $TestRoot "p2e-health-temp"
        New-Item -ItemType Directory -Path $tempDir -Force | Out-Null

        $floodBody = @'
$chunk = "H" * 1024
for ($i = 0; $i -lt 300; $i++) { [Console]::Out.Write($chunk) }
for ($i = 0; $i -lt 300; $i++) { [Console]::Error.Write($chunk) }
exit 0
'@
        $context = New-P2EHealthStubContext -Name "flood" -ChildBody $floodBody
        $run = Invoke-P2EHealthRun -Context $context -TempDir $tempDir

        Assert-Equal 25 @($run.Summary.Results).Count "health check count is unchanged"
        Assert-Equal $true $run.ById["ws-list"].Ok "a flooding ws list still passes"
        Assert-Equal (Join-Path (Split-Path -Parent $context.CanonicalPath) "sentinel-config.json") $run.ConfigAfter "DEVWS_CONFIG is restored"
        Assert-Equal 0 @(Get-ChildItem -LiteralPath $tempDir -Recurse -File -ErrorAction SilentlyContinue).Count "no temporary files are created by the health check"
        Assert-Equal 0 @(Get-ChildItem -LiteralPath $tempDir -Filter 'devws-health-*' -Recurse -File -ErrorAction SilentlyContinue).Count "no health redirect files exist"

        $exitContext = New-P2EHealthStubContext -Name "exit3" -ChildBody "exit 3"
        $exitRun = Invoke-P2EHealthRun -Context $exitContext -TempDir $tempDir
        Assert-Equal $false $exitRun.ById["ws-list"].Ok "a nonzero ws list fails the check"
        Assert-Equal 0 @(Get-ChildItem -LiteralPath $tempDir -Recurse -File -ErrorAction SilentlyContinue).Count "nonzero exit leaves no temporary files"

        $sleepContext = New-P2EHealthStubContext -Name "timeout" -ChildBody "Start-Sleep -Seconds 300"
        $timeoutRun = Invoke-P2EHealthRun -Context $sleepContext -TempDir $tempDir -ListTimeoutSeconds 2
        Assert-Equal $false $timeoutRun.ById["ws-list"].Ok "a hung ws list fails the check"
        $leftoverGone = Wait-TestFixtureProcessesGone -Select {
            Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $null -ne $_.CommandLine -and $_.CommandLine -like ("*" + $sleepContext.InstallRoot + "*") }
        }
        Assert-Equal $true $leftoverGone.Gone "the timed-out child is terminated"
        Assert-Equal 0 @(Get-ChildItem -LiteralPath $tempDir -Recurse -File -ErrorAction SilentlyContinue).Count "timeout leaves no temporary files"
    }

    Test-Case "health child-exit classification uses child timing, not stream-drain grace" {
        $pwshExe = (Get-Process -Id $PID).Path
        $fixtureDir = Join-Path $TestRoot "p2e-health-exit-class"
        New-Item -ItemType Directory -Path $fixtureDir -Force | Out-Null
        $tempDir = [System.IO.Path]::GetTempPath()
        $beforeTemp = @(Get-ChildItem -LiteralPath $tempDir -Filter 'devws-*' -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
        $marker = "P2E-EXITCLASS-$([guid]::NewGuid().ToString('N').Substring(0, 8))"

        function Start-P2ERedirectedChild {
            param([string]$Script)
            $encoded = [Convert]::ToBase64String([System.Text.Encoding]::Unicode.GetBytes($Script))
            $psi = [System.Diagnostics.ProcessStartInfo]::new()
            $psi.FileName = $pwshExe
            $psi.Arguments = "-NoLogo -NoProfile -EncodedCommand $encoded"
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            return [System.Diagnostics.Process]::Start($psi)
        }

        try {
            # 1. Comfortable timely exit.
            $fast = Start-P2ERedirectedChild 'exit 0'
            $fastSw = [System.Diagnostics.Stopwatch]::StartNew()
            $fastOk = Read-DevWSHealthChildStreamsToExit -Process $fast -TimeoutMilliseconds 10000
            $fastSw.Stop()
            Assert-Equal $true $fastOk "a comfortably timely exit is a completed wait"
            Assert-Equal 0 $fast.ExitCode "the timely exit code is preserved"
            $fast.Dispose()

            # 2. Nonzero exit before the deadline is still a completed wait;
            #    the exit code decides check success, not this helper.
            $nonzero = Start-P2ERedirectedChild 'exit 3'
            $nonzeroOk = Read-DevWSHealthChildStreamsToExit -Process $nonzero -TimeoutMilliseconds 10000
            Assert-Equal $true $nonzeroOk "a nonzero timely exit is a completed wait"
            Assert-Equal 3 $nonzero.ExitCode "the nonzero exit code is preserved"
            $nonzero.Dispose()

            # 3. A child that exits only AFTER the deadline is a timeout.
            $late = Start-P2ERedirectedChild 'Start-Sleep -Seconds 3'
            $lateSw = [System.Diagnostics.Stopwatch]::StartNew()
            $lateOk = Read-DevWSHealthChildStreamsToExit -Process $late -TimeoutMilliseconds 400
            $lateSw.Stop()
            Assert-Equal $false $lateOk "an exit after the deadline is a timeout"
            Assert-True ($lateSw.Elapsed.TotalMilliseconds -lt 2500) "the timeout decision is bounded"
            if (-not $late.HasExited) { $late.Kill() }
            [void]$late.WaitForExit(5000)
            $late.Dispose()

            # 4. A genuine hang requiring termination is a timeout.
            $hang = Start-P2ERedirectedChild 'Start-Sleep -Seconds 60'
            $hangOk = Read-DevWSHealthChildStreamsToExit -Process $hang -TimeoutMilliseconds 400
            Assert-Equal $false $hangOk "a genuine hang is a timeout"
            $hang.Kill()
            [void]$hang.WaitForExit(5000)
            Assert-True $hang.HasExited "the timed-out child is terminated"
            $hang.Dispose()

            # 5. Simultaneous stdout/stderr flooding cannot deadlock.
            $floodScript = @'
$chunk = 'F' * 1024
for ($i = 0; $i -lt 300; $i++) { [Console]::Out.Write($chunk) }
for ($i = 0; $i -lt 300; $i++) { [Console]::Error.Write($chunk) }
exit 0
'@
            $flood = Start-P2ERedirectedChild $floodScript
            $floodOk = Read-DevWSHealthChildStreamsToExit -Process $flood -TimeoutMilliseconds 15000
            Assert-Equal $true $floodOk "a flooding child that exits is a completed wait"
            Assert-Equal 0 $flood.ExitCode "the flooding child exit code is preserved"
            $flood.Dispose()

            # 6. The decisive near-deadline case: the child has ALREADY exited
            #    (before the call, therefore before the deadline) while a
            #    descendant retains the inherited stdout/stderr writers. The
            #    finite drain grace must complete the wait as SUCCESS even
            #    though the grace extends past the deadline, and must never
            #    wait for the descendant itself.
            $holdCmd = Join-Path $fixtureDir 'hold-writer.cmd'
            @(
                '@echo off',
                "start `"`" `"$pwshExe`" -NoProfile -Command `"Start-Sleep -Seconds 60 # $marker`"",
                'exit /b 0'
            ) | Set-Content -LiteralPath $holdCmd -Encoding ASCII

            $hold = Start-P2ERedirectedChild ("& '" + $holdCmd + "'")
            Assert-True ($hold.WaitForExit(8000)) "the immediate child exits promptly"
            $holdExit = $hold.ExitCode

            $holdSw = [System.Diagnostics.Stopwatch]::StartNew()
            $holdOk = Read-DevWSHealthChildStreamsToExit -Process $hold -TimeoutMilliseconds 300
            $holdSw.Stop()

            $holders = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $null -ne $_.CommandLine -and $_.CommandLine -like "*$marker*" })
            Assert-Equal $true $holdOk "a timely exit with a descendant holding the writers is a completed wait"
            Assert-Equal 0 $holdExit "the immediate child exit code is preserved"
            Assert-True ($holdSw.Elapsed.TotalMilliseconds -ge 250) "the finite drain grace was applied"
            Assert-True ($holdSw.Elapsed.TotalMilliseconds -lt 3000) "the drain grace stayed finite"
            Assert-True ($holders.Count -ge 1) "the descendant held the writers through the wait and was not waited for"
            $hold.Dispose()
        }
        finally {
            $holders = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $null -ne $_.CommandLine -and $_.CommandLine -like "*$marker*" })
            foreach ($holder in $holders) { Stop-Process -Id $holder.ProcessId -Force -ErrorAction SilentlyContinue }

            # A fixed sleep followed by one snapshot is the same observation
            # race: wait for the actual absence condition instead.
            $gone = Wait-TestFixtureProcessesGone -Select {
                Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $null -ne $_.CommandLine -and $_.CommandLine -like "*$marker*" }
            }

            Assert-Equal $true $gone.Gone ("the inherited-writer fixture descendant was cleaned up (remaining: " + (@($gone.Remaining | ForEach-Object { $_.ProcessId }) -join ',') + ")")
        }

        # 7. Zero temporary files and zero residual fixture processes.
        $afterTemp = @(Get-ChildItem -LiteralPath $tempDir -Filter 'devws-*' -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
        Assert-Equal @($beforeTemp).Count @($afterTemp).Count "the classification fixtures create no temporary files"
        $residualGone = Wait-TestFixtureProcessesGone -Select {
            Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $null -ne $_.CommandLine -and $_.CommandLine -like "*$fixtureDir*" }
        }
        Assert-Equal $true $residualGone.Gone "no residual fixture processes remain"
    }

    Test-Case "installed bootstrap produces no filesystem diagnostics" {
        $fixture = New-InstallFixture "p2e-bootstrap-installed"
        $helpersDir = Join-Path $fixture.Privileged "helpers"
        $leafDir = Join-Path $fixture.Privileged "lib"
        New-Item -ItemType Directory -Path $helpersDir, $leafDir -Force | Out-Null

        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\helpers\cwd-shell-bootstrap.ps1") -Destination (Join-Path $helpersDir "cwd-shell-bootstrap.ps1") -Force
        Copy-Item -LiteralPath (Join-Path $RepoRoot "src\lib\devws-cwd-paths.ps1") -Destination (Join-Path $leafDir "devws-cwd-paths.ps1") -Force

        $work = Join-Path $fixture.Root "work"
        $state = Join-Path $fixture.Root "state"
        New-Item -ItemType Directory -Path $work, $state -Force | Out-Null

        $publicationPath = Join-Path $state "cwd\main\slot.json"
        $before = @(Get-ChildItem -LiteralPath $fixture.Root -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })

        $process = Start-Process `
            -FilePath (Get-Process -Id $PID).Path `
            -ArgumentList @(
                '-NoLogo', '-NoProfile', '-NoExit',
                '-File', ('"' + (Join-Path $helpersDir "cwd-shell-bootstrap.ps1") + '"'),
                '-SetId', 'main',
                '-TerminalId', 'slot',
                '-WindowId', 'DevWS-slot',
                '-SessionId', 'p2e-bootstrap-installed-1',
                '-PublicationPath', ('"' + $publicationPath + '"'),
                '-ChildSpecBase64', 'not-base64'
            ) `
            -WorkingDirectory $work `
            -PassThru `
            -WindowStyle Hidden

        try {
            Start-Sleep -Seconds 3
            Assert-True (-not $process.HasExited) "installed diagnostics never break the shell"

            $after = @(Get-ChildItem -LiteralPath $fixture.Root -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
            Assert-Equal @($before).Count @($after).Count "installed bootstrap creates no filesystem output"
            Assert-True (-not (Test-Path -LiteralPath $publicationPath)) "the blocked installed publication writes nothing"
        }
        finally {
            if (-not $process.HasExited) { Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue }
        }
    }

