        Assert-Contains $locale 'PackageName: DevWS' "manifest package name"
        Assert-Contains $locale 'Publisher: ekinokss' "manifest locale publisher"
        Assert-Contains $locale 'License: MIT' "manifest license"
        Assert-Contains $locale 'PrivacyUrl: https://github.com/ekinokss/DevWS/blob/main/PRIVACY.md' "manifest privacy link"

        $readme = Get-SourceOf "packaging\winget\README.md"
        Assert-Contains $readme 'microsoft/winget-pkgs' "README documents the submission target"
        Assert-Contains $readme 'Current disposition: blocked' "README records that submission is blocked"
        Assert-Contains $readme 'Do not submit this template for the v0.2.0 release' "README blocks the v0.2.0 submission"
        Assert-Contains $readme 'No WinGet catalog package' "README states that no catalog package exists"
        Assert-Contains $readme 'RequireSameElevatedSid' "README documents DevWS caller-SID enforcement"
        Assert-Contains $readme 'different administrator account' "README documents cross-account elevation rejection"
    }

    Test-Case "trusted PowerShell and protected staging policy are explicit" {
        $resolver = Get-SourceOf "packaging\bootstrapper\PowerShellResolver.cs"
        Assert-Contains $resolver 'Microsoft.PowerShell_8wekyb3d8bbwe' "the official MSIX family is fixed"
        Assert-Contains $resolver 'GetPackagesByPackageFamily' "MSIX discovery uses package APIs"
        Assert-Contains $resolver 'GetPackagePathByFullName' "MSIX discovery uses the registered package path"
        Assert-Contains $resolver 'PowerShell", "7", "pwsh.exe' "the machine-wide candidate is exact"
        Assert-Contains $resolver 'WindowsApps' "the MSIX root is the protected WindowsApps root"
        Assert-Contains $resolver 'FileMajorPart >= 7' "PowerShell major version is checked"
        Assert-Contains $resolver 'ProductMajorPart >= 7' "PowerShell product version is checked"
        Assert-NotContains $resolver 'Environment.GetEnvironmentVariable("PATH")' "PowerShell is never resolved through PATH"
        Assert-NotContains $resolver 'where.exe' "PowerShell is never resolved through where.exe"

        $security = Get-SourceOf "packaging\bootstrapper\PackageSecurity.cs"
        Assert-Contains $security 'PropagationFlags.InheritOnly' "inherit-only ACEs are excluded from current-object authority"
        Assert-Contains $security 'TrustedInstaller' "the protected OS TrustedInstaller principal is trusted"
        Assert-NotContains $security 'includeInheritedRules' "inherited ACEs are evaluated effectively, not skipped"
        Assert-NotContains (Get-SourceOf "packaging\bootstrapper\InstalledSetup.cs") 'includeInheritedRules' "the parent validation has no inherited-rule escape hatch"

        $staging = Get-SourceOf "packaging\bootstrapper\ProtectedStaging.cs"
        Assert-Contains $staging 'SpecialFolder.CommonApplicationData' "staging uses the OS ProgramData root"
        Assert-Contains $staging 'setup-staging' "staging uses the dedicated setup area"
        Assert-Contains $staging 'CreateDirectoryW' "staging directories are created with security attributes"
        Assert-Contains $staging 'SetAccessRuleProtection' "staging DACLs are protected"
        Assert-Contains $staging 'ReparsePoint' "staging refuses reparse points"
        Assert-NotContains $staging 'GetTempPath' "staging never uses a user temp root"
        Assert-NotContains $staging 'LocalApplicationData' "staging never uses LOCALAPPDATA"

        $payload = Get-SourceOf "packaging\bootstrapper\PayloadArchive.cs"
        Assert-Contains $payload 'GetFullPath' "archive destinations are normalized"
        Assert-Contains $payload 'duplicate normalized targets' "duplicate archive targets are refused"
        Assert-Contains $payload 'ReparsePoint' "archive reparse entries are refused"
        Assert-Contains $payload 'escapes the staging root' "archive traversal is refused"

        $workflow = Get-SourceOf ".github\workflows\bootstrapper-ci.yml"
        Assert-Contains $workflow 'workflow_dispatch:' "bootstrapper validation is manually dispatched"
        Assert-Contains $workflow 'contents: read' "the workflow is read-only"
        Assert-Contains $workflow 'actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1' "checkout is SHA-pinned"
        Assert-Contains $workflow 'actions/setup-dotnet@26b0ec14cb23fa6904739307f278c14f94c95bf1' "setup-dotnet is SHA-pinned"
        Assert-Contains $workflow 'packaging/test-bootstrapper.ps1' "the workflow runs fixture acceptance"
        Assert-NotContains $workflow 'secrets.' "the workflow uses no repository secret"
        Assert-NotContains $workflow 'self-hosted' "the workflow stays hosted"
    }

    Write-Host ""
    Start-TestGroup -Name 'test-harness' -Title 'Test harness'

    Test-Case "suite broker isolation is installed and never connects to the production broker pipe" {
        Assert-Equal $true $script:DevWSTestBrokerIsolationInstalled "default broker isolation marker is installed"

        # The default availability probe is process-local and returns false
        # without opening any pipe; the connect canary counts (and refuses) any
        # real transport attempt for the whole suite run.
        Assert-Equal $false (Test-DevWSElevatedBrokerAvailable) "default broker availability returns false without a connection"
        Assert-Equal 0 $script:DevWSTestBrokerConnectAttempts "the suite never invoked the broker connect canary"
    }

    Test-Case "test group catalog is complete, ordered, and fully registered" {
        Assert-Equal 64 $script:TestGroupCatalog.Count "catalog covers every section group including the harness"
        Assert-Equal 64 $script:TestGroupsStarted.Count "every catalog group was started exactly once"
        Assert-Equal (($script:TestGroupCatalog.Keys) -join ",") ($script:TestGroupsStarted -join ",") "group execution order matches the catalog"
    }

    Test-Case "harness classifies pass, runtime skip, and failure as mutually exclusive outcomes" {
        # A body that completes normally is a pass.
        $passed = Invoke-TestCaseBody -Body { $null = 1 }
        Assert-Equal "passed" $passed.Outcome "a completing body is a pass"
        Assert-True ($null -eq $passed.Reason) "a pass carries no reason"

        # A body that signals an unmet runtime precondition is a SKIP, not a pass.
        $skipped = Invoke-TestCaseBody -Body { Skip-Test "fixture precondition absent" }
        Assert-Equal "runtime-skipped" $skipped.Outcome "Skip-Test produces a runtime skip"
        Assert-Equal "fixture precondition absent" $skipped.Reason "the skip reason is preserved"
        Assert-True ($skipped.Outcome -ne "passed") "a runtime skip is never classified as a pass"

        # Any other error is a failure, never a skip.
        $failed = Invoke-TestCaseBody -Body { throw "genuine defect" }
        Assert-Equal "failed" $failed.Outcome "an unexpected error is a failure"
        Assert-Equal "genuine defect" $failed.Reason "the failure reason is preserved"
        Assert-True ($failed.Outcome -ne "runtime-skipped") "a failure is never classified as a skip"

        # A skip raised from nested helper code still classifies as a skip.
        $nested = Invoke-TestCaseBody -Body { & { Skip-Test "nested precondition absent" } }
        Assert-Equal "runtime-skipped" $nested.Outcome "a nested skip still classifies as a skip"

        $outcomes = @($passed.Outcome, $skipped.Outcome, $failed.Outcome)
        Assert-Equal 3 @($outcomes | Sort-Object -Unique).Count "the executed outcomes are pairwise distinct"
    }

    Test-Case "harness counts discovered, selected, skipped, failed and filter-excluded cases separately" {
        $before = [pscustomobject]@{
            Discovered = $script:TestsDiscovered
            Selected   = $script:TestsSelected
            Passed     = $script:TestsPassed
            Failed     = $script:TestsFailed
            Skipped    = $script:TestsRuntimeSkipped
            Filtered   = $script:TestsFilterExcluded
        }

        $savedFilter = $script:TestGroupFilter
        try {
            # Drive Test-Case through the real filter path with a hostile filter.
            $script:TestGroupFilter = @('a-group-that-does-not-contain-the-harness')
            Test-Case "harness self-check (filter-excluded)" { throw "this body must never execute" } 6> $null

            Assert-Equal ($before.Discovered + 1) $script:TestsDiscovered     "a reached case is discovered"
            Assert-Equal ($before.Filtered + 1)   $script:TestsFilterExcluded "an unselected case increments only the filter-excluded counter"
            Assert-Equal $before.Selected $script:TestsSelected        "a filter-excluded case is not selected"
            Assert-Equal $before.Passed   $script:TestsPassed          "a filter-excluded case is not a pass"
            Assert-Equal $before.Failed   $script:TestsFailed          "a filter-excluded case is not a failure"
            Assert-Equal $before.Skipped  $script:TestsRuntimeSkipped  "a filter-excluded case is not a runtime skip"

            # Drive a real runtime skip through Test-Case.
            $script:TestGroupFilter = @()
            Test-Case "harness self-check (runtime-skipped)" { Skip-Test "self-check precondition absent" } 6> $null

            Assert-Equal ($before.Discovered + 2) $script:TestsDiscovered     "both self-checks were discovered"
            Assert-Equal ($before.Selected + 1)   $script:TestsSelected       "a runtime-skipped case is selected"
            Assert-Equal ($before.Skipped + 1)    $script:TestsRuntimeSkipped "a runtime skip increments only the runtime-skip counter"
            Assert-Equal $before.Passed $script:TestsPassed   "a runtime skip is not a pass"
            Assert-Equal $before.Failed $script:TestsFailed   "a runtime skip is not a failure"
        }
        finally {
            $script:TestGroupFilter = $savedFilter
            # The self-check cases must not pollute the suite totals.
            $script:TestsDiscovered     = $before.Discovered
            $script:TestsSelected       = $before.Selected
            $script:TestsPassed         = $before.Passed
            $script:TestsFailed         = $before.Failed
            $script:TestsRuntimeSkipped = $before.Skipped
            $script:TestsFilterExcluded = $before.Filtered
        }
    }

    Test-Case "the test workspace fixture is never mutated by the suite" {
        Assert-True ($null -ne $script:WorkspaceFixtureSha256) "the fixture digest was captured at startup"

        $actual = (Get-FileHash -LiteralPath $WorkspaceFixturePath -Algorithm SHA256).Hash
        Assert-Equal $script:WorkspaceFixtureSha256 $actual `
            "the neutral test corpus must never be written in place; copy it first"
    }

    Test-Case "every window-station skip site leaves no fixture window behind" {
        # A runtime skip must never strand a disposable fixture window. Every
        # window-station skip site must therefore either be guarded by a
        # "no window was created" test, or destroy the window(s) it created
        # before leaving. This is a source contract: it is deterministic and
        # cannot flake on a machine that lacks a usable window station.
        $sourceLines = [IO.File]::ReadAllLines((Join-Path $RepoRoot "tests\run-tests.ps1"))
        $sites = @()

        for ($i = 0; $i -lt $sourceLines.Count; $i++) {
            if ($sourceLines[$i] -notmatch '^\s*Skip-Test\s+"no disposable test window could be created') { continue }

            $context = ($sourceLines[[Math]::Max(0, $i - 8)..$i] -join [Environment]::NewLine)

            $sites += [pscustomobject]@{
                Line    = $i + 1
                Guarded = ($context -match '\[IntPtr\]::Zero')
                Cleaned = ($context -match '::Destroy\(')
            }
        }

        Assert-True ($sites.Count -ge 9) "every window-station skip site was found (found $($sites.Count))"

        foreach ($site in $sites) {
            Assert-True ($site.Guarded -or $site.Cleaned) `
                "window-station skip at line $($site.Line) must be guarded by an IntPtr::Zero test or destroy its fixture window(s) first"
        }
    }

    Test-Case "harness outcome counters partition every reached case exactly once" {
        # This case is itself in flight: Test-Case has already counted it as
        # discovered and selected, but its own outcome is recorded only after
        # this body returns, so the completed-outcome partition is checked
        # against selected - 1.
        $completedSelected = $script:TestsSelected - 1

        Assert-Equal $completedSelected ($script:TestsPassed + $script:TestsFailed + $script:TestsRuntimeSkipped) `
            "partition: completed selected = passed + failed + runtime-skipped"

        # Derived, not a literal: two Test-Case lines in this file are the
        # harness self-check invocations above, which are conditional calls
        # rather than declared cases.
        $declaredCases = @([IO.File]::ReadAllLines((Join-Path $RepoRoot "tests\run-tests.ps1")) |
            Where-Object { $_ -match '^\s*Test-Case\s' }).Count - 2

        Assert-Equal $declaredCases $script:TestsDiscovered "every declared case is discovered exactly once"

        Assert-Equal $script:TestsDiscovered ($script:TestsSelected + $script:TestsFilterExcluded) `
            "partition: discovered = selected + filter-excluded"

        if ($script:TestGroupFilter.Count -eq 0) {
            Assert-Equal 0 $script:TestsFilterExcluded "an unfiltered run excludes nothing"
        }
    }
}
finally {
    Remove-Item Env:\DEVWS_STATE_ROOT -ErrorAction SilentlyContinue
    Remove-Item Env:\DEVWS_PROTECTED_STATE_ROOT -ErrorAction SilentlyContinue
    if (-not [string]::IsNullOrWhiteSpace($script:P2CCwdFixtureRoot)) {
        Remove-Item -LiteralPath $script:P2CCwdFixtureRoot -Recurse -Force -ErrorAction SilentlyContinue
    }

    if (Test-Path -LiteralPath $TestRoot) {
        Remove-Item -LiteralPath $TestRoot -Recurse -Force -ErrorAction SilentlyContinue
    }
}

Write-Host ""

if ($script:TestGroupFilter.Count -gt 0) {
    Write-Host ("Selected groups: " + ($script:TestGroupFilter -join ", ")) -ForegroundColor Cyan
}

# Case accounting is reported UNCONDITIONALLY, for filtered and unfiltered runs
# alike, with terminology that cannot imply a skipped body completed its
# assertions:
#
#   discovered       every Test-Case reached
#   selected         discovered and not excluded by -Group (bodies entered)
#   passed           selected; assertions ran and all held
#   failed           selected; an assertion or the body raised
#   runtime-skipped  selected; the body left early WITHOUT completing its
#                    assertions (a precondition was unmet)
#   filter-excluded  not selected; the body was never entered
#
# Partition equations (both are enforced below and are a harness defect if
# violated):
#   discovered = selected + filter-excluded
#   selected   = passed + failed + runtime-skipped
Write-Host "Case accounting:" -ForegroundColor Cyan
Write-Host ("  discovered       : {0}" -f $script:TestsDiscovered) -ForegroundColor Cyan
Write-Host ("  selected         : {0}" -f $script:TestsSelected) -ForegroundColor Cyan
Write-Host ("  passed           : {0}" -f $script:TestsPassed) -ForegroundColor Cyan
Write-Host ("  failed           : {0}" -f $script:TestsFailed) -ForegroundColor Cyan
Write-Host ("  runtime-skipped  : {0}   (selected; did NOT complete their assertions)" -f $script:TestsRuntimeSkipped) -ForegroundColor Cyan
Write-Host ("  filter-excluded  : {0}   (not selected; bodies never entered)" -f $script:TestsFilterExcluded) -ForegroundColor Cyan

if ($script:TestsSelected -eq 0) {
    Write-Host "No cases were selected." -ForegroundColor Red
    exit 1
}

# Structural guarantees. A violation is a harness defect and must never exit 0.
$partitionErrors = @()
if ($script:TestsDiscovered -ne ($script:TestsSelected + $script:TestsFilterExcluded)) {
    $partitionErrors += ("discovered={0} but selected+filter-excluded={1}" -f `
        $script:TestsDiscovered, ($script:TestsSelected + $script:TestsFilterExcluded))
}
if ($script:TestsSelected -ne ($script:TestsPassed + $script:TestsFailed + $script:TestsRuntimeSkipped)) {
    $partitionErrors += ("selected={0} but passed+failed+runtime-skipped={1}" -f `
        $script:TestsSelected, ($script:TestsPassed + $script:TestsFailed + $script:TestsRuntimeSkipped))
}
if ($partitionErrors.Count -gt 0) {
    Write-Host ("Harness partition violated: " + ($partitionErrors -join "; ") + ".") -ForegroundColor Red
    exit 1
}

$coverageFailure = ($RequireFullCoverage -and $script:TestsRuntimeSkipped -gt 0)

if ($script:TestsFailed -eq 0 -and -not $coverageFailure) {
    if ($script:TestsRuntimeSkipped -gt 0) {
        Write-Host ("{0} selected case(s) passed. {1} selected case(s) were skipped at runtime and did NOT complete their assertions, so coverage is NOT complete." -f $script:TestsPassed, $script:TestsRuntimeSkipped) -ForegroundColor Yellow
    }
    else {
        Write-Host ("All {0} selected cases passed." -f $script:TestsPassed) -ForegroundColor Green
    }

    exit 0
}

if ($script:TestsFailed -gt 0) {
    Write-Host ("{0} of {1} selected case(s) failed." -f $script:TestsFailed, $script:TestsSelected) -ForegroundColor Red
}

if ($coverageFailure) {
    Write-Host ("-RequireFullCoverage: {0} selected case(s) were runtime-skipped, so this run is not a full-coverage pass." -f $script:TestsRuntimeSkipped) -ForegroundColor Red
}

exit 1








